\caption{A visual representation of Full CP methodology \citep[Figure 1]{cp-ip}. The Conformal Prediction Region is obtained as in \eqref{eq_imp5}.}\label{fig1}
\end{figure*}


\noindent \citet[Section 5]{cp-ip} point out how Full CP can be written as a correspondence

\begin{equation}\label{conf-pred-correspond-def}
\kappa: [0,1] \times Y^n \times \mathscr{F} \rightrightarrows Y, \quad (\alpha,y^n,\psi) \mapsto \kappa(\alpha,y^n,\psi),
\end{equation}

where 
\begin{align}\label{funct-coll}
    \mathscr{F}\coloneqq \{\psi: Y^n \times Y \rightarrow \mathbb{R} \text{, } \psi \text{ is invariant to permutations in its first argument}\},
\end{align}
and the image of $\kappa$ is defined as 
%follows. Pick any $\alpha \in [0,1]$ and call $y^n=(y_1,\ldots,y_n)$ an element of $Y^n$. Let $y^{n+1}\coloneqq (y^n,y_{n+1}) \in Y^{n+1}$ and define, for all $i\in\{1,\ldots,n\}$, 
%$$y^{n+1}_{-i} \coloneqq (y_1, \dots, y_{i-1}, y_{i+1}, \dots, y_{n+1}) \in Y^n.$$
%$y^{n+1}_{-i}\coloneqq y^{n+1} \setminus \{y_i\}$. 
%Then,
\begin{align}\label{kappa-definition}
    \kappa(\alpha,y^n,\psi) \coloneqq \Bigg\{y_{n+1}\in Y : \underbrace{\frac{1}{n+1}\sum_{i=1}^{n+1} \mathbbm{1}\left[\psi \left(y^{n+1}_{-i},y_i \right)  \geq \psi \left(y^{n+1}_{-(n+1)},y_{n+1} \right)\right]}_{\eqqcolon \pi(y_{n+1},y^n)} > \alpha\Bigg\}.
\end{align}
It is easy to see, then, that  $\kappa(\alpha,y^n,\psi) \equiv \mathscr{R}_\alpha^\psi(y^n)$.







Full Conformal Prediction (FCP) is not the only way of carrying out conformal prediction. There exists another type called Inductive (or Split) Conformal Prediction (ICP). It assumes exchangeability and it is used to build the same region $\mathscr{R}_\alpha^\psi(y^n)$ in \eqref{eq_imp5} having the same guarantee \eqref{eq_imp6}, while being computationally less expensive than FCP. 
%. Because the main focus of this paper are CPRs and their guarantee, we avoid analyzing ICP in detail. 
Since ICP produces the same region as FCP, which is what we need in light of the goal of our paper, we do not present ICP in detail. We refer the interested reader to \citep{papadopoulos2008inductive,angelopoulos2024theoreticalfoundationsconformalprediction}.



