\section{Conformal Prediction as an Upper Hemicontinuous Morphism}\label{main}



%The following is introduced in \citet[Definition 17.2]{aliprantis}.

This section introduces category \textbf{UHCont}, and shows that, under minimal assumptions, the Conformal Prediction correspondence $\kappa$ is a morphism of \textbf{UHCont}, embedded in a commuting diagram. The following is inspired by \citet[Example 1.1.14]{perrone2024starting}.


\begin{definition}[Structure \textbf{UHCont}]\label{structure-uhcont}
Define a structure $\mathbf{UHCont}$ as follows,
\begin{itemize}
  \item \textbf{Objects:} Topological spaces $(X, \tau_X)$.
  \item \textbf{Morphisms:} Upper hemicontinuous correspondences $\Phi : X \rightrightarrows Y$ (see Definition \ref{uhc-definition} in Appendix \ref{funct-anal}).
%  \item \textbf{Composition:} Given $\Phi : X \rightrightarrows Y$ and $\Psi : Y \rightrightarrows Z$, define the composition $\Psi \circ \Phi : X \rightrightarrows Z$ by:
%  \[
%  (\Psi \circ \Phi)(x) \coloneqq \bigcup_{y \in \Phi(x)} \Psi(y).
%  \]
%  \item \textbf{Identities:} For each object $X$, define $\mathrm{id}_X : X \rightrightarrows X$ by $\mathrm{id}_X(x) \coloneqq \{x\}$.
\end{itemize}
\end{definition}



\begin{theorem}[\textbf{UHCont} is a Category]\label{cat-uhc}
The structure $\mathbf{UHCont}$ defines a category.
\end{theorem}

\begin{proof}
We verify the axioms of a category.

\textbf{(1) Identity morphisms.} For each object $X$, define $\mathrm{id}_X(x) \coloneqq \{x\}$. Let $V \subseteq X$ be open and suppose $x_0 \in X$ satisfies $\mathrm{id}_X(x_0) = \{x_0\} \subseteq V$. Then, since $x_0 \in V$ and $V$ is open, there exists an open neighborhood $U = V$ of $x_0$ such that for all $x \in U$, $\mathrm{id}_X(x) = \{x\} \subseteq V$. Hence, $\mathrm{id}_X$ is upper hemicontinuous.

\textbf{(2) Associativity of composition.} Let $\Phi : X \rightrightarrows Y$, $\Psi : Y \rightrightarrows Z$, and $\Theta : Z \rightrightarrows W$. Then for all $x \in X$,
\[
((\Theta \circ \Psi) \circ \Phi)(x)
= \bigcup_{y \in \Phi(x)} \bigcup_{z \in \Psi(y)} \Theta(z)
= \bigcup_{z \in (\Psi \circ \Phi)(x)} \Theta(z)
= (\Theta \circ (\Psi \circ \Phi))(x)
\]
by the associativity of union. Thus, composition is associative.

\textbf{(3) Closure under composition.} Let $\Phi : X \rightrightarrows Y$ and $\Psi : Y \rightrightarrows Z$ be upper hemicontinuous correspondences. By \citet[Theorem 17.23]{aliprantis}, the composition $\Psi \circ \Phi$ defined by
\[
(\Psi \circ \Phi)(x) \coloneqq \bigcup_{y \in \Phi(x)} \Psi(y)
\]
is also upper hemicontinuous. Thus, the composition of morphisms is again a morphism.

\textbf{(4) Identity laws.} For any morphism $\Phi : X \rightrightarrows Y$ and any $x\in X$, 
\[
(\Phi \circ \mathrm{id}_X)(x) = \bigcup_{z \in \mathrm{id}_X(x)} \Phi(z) = \Phi(x), \quad
(1_Y \circ \Phi)(x) = \bigcup_{y \in \Phi(x)} \{y\} = \Phi(x).
\]
Hence, $\mathrm{id}_X$ acts as a left and right identity.

Therefore, $\mathbf{UHCont}$ satisfies the axioms of a category.
\end{proof}




We now show that, under minimal assumptions, the (Full) Conformal Prediction correspondence $\kappa$ in  \eqref{conf-pred-correspond-def} is a morphism of $\mathbf{UHCont}$, and that it is part of a commutative diagram involving the IHDR and the credal set correspondences. 
%in \eqref{ihdr-corresp} and \eqref{cred-corresp}, respectively. 
Fix any $n \in \mathbb{N}$, and consider the following conditions,

\newcommand{\kappaCorr}{\kappa}
\newcommand{\SigY}{\Sigma_Y}
\newcommand{\piVal}{\pi}
\newcommand{\credset}{\mathcal M}

\begin{enumerate}[label=(\roman*)]
  \item\label{H1}
    $\Y$ is compact Hausdorff and $\SigY=\mathcal{B}(Y)$ is its Borel $\sigma$-field.
  \item\label{H2}
    Each $\psi\in\F$ is jointly continuous on $\Y^{n}\times\Y$; We can then write $\F \subset C(Y^n \times Y)$, the space of jointly continuous real-valued functions on $Y^n \times Y$. $\F$ is endowed with the uniform ($\sup$-norm) topology.
  \item\label{H3}
    \emph{No-tie parameter:}
    The credibility level $\alpha$ satisfies
    $\alpha\notin S_{n+1}\coloneqq \{0, \frac{1}{n+1}, \frac{2}{n+1}, \ldots, \frac{n}{n+1}, 1\}$.
  % \item\label{H4}
  %   For all $A\in\SigY$, the map
  %   $(y^{n},\psi)\mapsto
  %        \overline\Pi_{(y^{n},\psi)}(A)=\sup_{y\in A}\piVal(y,y^{n},\psi)$
  %   is \emph{upper semicontinuous}.
  \item\label{H5}
    $\Prob$ is endowed with the weak$^\star$ topology,
    %(\emph{Banach-Alaoglu}: $\Prob$ is compact),
    and $\mathscr C\subset 2^{\Prob}$ is endowed with the Vietoris topology (see Definition \ref{vietoris} in Appendix \ref{funct-anal}).
\end{enumerate}

%--------------------------------------------------------------------
The following is a famous classical result in set-valued functional analysis \citep[Theorem 17.11]{aliprantis}.

\begin{lemma}[Closed Graph Theorem]
\label{lem:CG}
A correspondence with compact Hausdorﬀ
range space has closed graph if and only if it is upper hemicontinuous and closed-valued.
\end{lemma}

Another important lemma that sets the table for our main result is the following.

\begin{lemma}[Upper Semicontinuity of the Upper Envelope $\overline{\Pi}$]\label{lem-H4}
    If \ref{H1} and \ref{H2} hold, then the map $(y^{n},\psi)\mapsto \overline\Pi_{(y^{n},\psi)}(A)=\sup_{y\in A}\piVal(y,y^{n},\psi)$
     is {upper semicontinuous}, for all closed sets $A\in\Sigma_Y$.
\end{lemma}


\begin{proof}
First, we show that, if a generic set $K$ is compact and a generic map \(f:K\to\mathbb R\) is upper semicontinuous (u.s.c.), then \(f\) attains its maximum on \(K\). Choose \(x_m\) with \(f(x_m)\ge\sup_K f-\tfrac1m\).
A compactness subsequence \(x_{m_k}\to x_\star\in K\) exists.
Upper semicontinuity gives
\(
f(x_\star)\ge\limsup f(x_{m_k})=\sup_K f.
\)

Now, we introduce auxiliary maps, and show their continuity.
For \(i\in\{1,\dots ,n+1\}\), put
\[
g_i(y_{n+1},y^{n},\psi)
   \coloneqq\psi\bigl(y^{n+1}_{-i},y_i\bigr)-\psi\bigl(y^{n},y_{n+1}\bigr).
\]
Because (a) the evaluation \(\psi\mapsto\psi(y^n,y)\) is continuous in the sup-norm, and (b) coordinate deletion \(y^{n+1}\mapsto(y^{n+1}_{-i},y_i)\) is continuous, each \(g_i\) is continuous on \(Y^{n+1}\times \F\).

Let us now show the upper semicontinuity of \(\pi_\psi\).
Fix \((y^{n+1},\psi)\).
The set \(\{g_i\ge0\}\) is closed;
For \(k=0,\dots ,n+1\) define
\[
R_k\coloneqq\Bigl\{(y^{n+1},\psi)\,:\,
          \pi_\psi(y_{n+1},y^{n})\ge\tfrac{k}{n+1}\Bigr\}.
\]
At least \(k\) of the inequalities
\(g_i\ge0\) must hold, so
\(R_k=\bigcup_{\lvert I\rvert=k}
      \bigcap_{i\in I}\{g_i\ge0\}\),
a finite union of finite intersections of closed sets;
Hence \(R_k\) is closed and \(\pi_\psi\) is u.s.c.




We are now ready to prove the main statement. Fix any closed set $A\in\Sigma_Y$. By \ref{H1}, it is also compact. 
Let \(\bigl(y^{n}_m,\psi_m\bigr)_{m\ge1}\)
converge to \((y^{n},\psi)\) and set
\(
L\coloneqq\limsup_{m\to\infty}\overline\Pi_{(y^{n}_m,\psi_m)}(A)
\).\footnote{If $Y$ is not first countable, we can switch from a sequence to a net argument.}
We must show \(L\le \overline\Pi_{(y^{n},\psi)}(A)\).


\emph{Step 1 (Discretization).}
Because \(\pi_\psi\) takes values in the finite set
\(\{0,\tfrac1{n+1},\dots ,1\}\),
there is an integer \(k\in\{0,\dots ,n+1\}\)
and a subsequence (still indexed by \(m\)) with
\(\overline\Pi_{(y^{n}_m,\psi_m)}(A)=k/(n+1)\), for all \(m\).


\emph{Step 2 (Select Maximizers).}
By the attained maximum result that we presented earlier, pick
\(y_{n+1}^{(m)}\in A\) such that
\(\pi_{\psi_m}\bigl(y_{n+1}^{(m)},y^{n}_m\bigr)=k/(n+1)\).
Compactness of \(A\) yields a further subsequence and a limit
\(y_{n+1}\in A\) with \(y_{n+1}^{(m)}\to y_{n+1}\).


\emph{Step 3 (Pass to the Limit).}
For every \(i\), the continuity of \(g_i\) gives
\(
g_i\bigl(y_{n+1}^{(m)},y^{n}_m,\psi_m\bigr)
\to g_i\bigl(y_{n+1},y^{n},\psi\bigr).
\)
Since at least \(k\) of the \(g_i\)’s are non-negative for each \(m\),
suppose, for contradiction, that {\em strictly fewer} than \(k\)
are non-negative at the limit.
Then there exists \(\delta>0\) such that,
for all sufficiently large \(m\),
fewer than \(k\) indices satisfy
\(g_i\bigl(y_{n+1}^{(m)},y^{n}_m,\psi_m\bigr)\ge-\delta\),
contradicting the fact that {\em every} \(m\) has
\(k\) indices with the same expression \(\ge0\).
Hence at least \(k\) of the limiting \(g_i\)’s are \(\ge0\), and
\[
\pi_\psi(y_{n+1},y^{n})\;\ge\;\frac{k}{n+1}.
\]


\emph{Step 4 (Take the Supremum).}
Because \(y_{n+1}\in A\),
\[
\overline\Pi_{(y^{n},\psi)}(A)
      \;\ge\;\pi_\psi(y_{n+1},y^{n})
      \;\ge\;\frac{k}{n+1}
      \;=\;L.
\]
Thus \(\limsup_{m\to\infty}\overline\Pi_{(y^{n}_m,\psi_m)}(A)\le \overline\Pi_{(y^{n},\psi)}(A)\),
establishing upper semicontinuity.
\end{proof}

