\begin{theorem}[The Conformal Prediction Diagram Commutes, $\mathbf{UHCont}$]\label{conf-pred-diagr}
   Assume that \ref{H1}-\ref{H5} hold, and that the conformal transducer $\pi$ is {\em consonant}. Consider the restrictions $\kappa_\alpha$ and $\IHDR_\alpha$ to any $\alpha \in [0,1]$ that satisfies \ref{H3}. Then, $\IHDR_\alpha \circ \CRED = \kappa_\alpha$. That is, the {\em Full CP Diagram}
$$
   \begin{tikzcd}
    Y^n \times \mathscr{F} \ar{r}{\CRED} \ar{dr}[swap]{\kappa_\alpha} & \mathscr{C} \ar{d}{\IHDR_\alpha} \\
    & \Sigma_Y
   \end{tikzcd}
  $$
  commutes in $\mathbf{UHCont}$.
\end{theorem}

In the Full CP Diagram that factorizes $\kappa_\alpha=\IHDR_\alpha \circ \CRED$ inside $\mathbf{UHCont}$, for all $\alpha$ satisfying \ref{H3}, we indicated $\Ccal$ as the image set of $\CRED$, and $\Sigma_Y$ as the image set of $\kappa_\alpha$ and $\IHDR_\alpha$. This is an immediate consequence of writing our three correspondences in their functional form $\kappa_\alpha^\text{funct}: Y^n \times \F \to \Sigma_Y$, $\IHDR_\alpha^\text{funct}: \mathscr{C} \to \Sigma_Y$, and $\CRED^\text{funct}: Y^n \times \F \to \Ccal$, where the latter holds under consonance. Notice also that $\Sigma_Y=\mathcal{B}(Y)$ by \ref{H1}.



%to make it clear that our morphisms are indeed correspondences, and what their range spaces are.


\begin{proof}[Proof of Theorem \ref{conf-pred-diagr}]
    Fix any $n\in\mathbb{N}$. We first show that $\kappaCorr$, $\CRED$, and $\IHDR$ have a closed graph. 

\textbf{(i) $\kappaCorr$.}
By \ref{H2} and its definition, the conformal transducer
$\piVal(\cdot,y^{n},\psi):\Y\to[0,1]$
is upper semicontinuous.
Because $\alpha$ avoids the grid $S_{n+1}$, let
\begin{align}\label{beta-def}
  \beta(\alpha) \equiv \beta\;\coloneqq\;\min\Bigl\{\tfrac{k}{n+1} \in S_{n+1}: \tfrac{k}{n+1}>\alpha\Bigr\},
  \quad\text{so } 0<\alpha<\beta\le1.
\end{align}
Then,
% \[
%   \kappaCorr(\alpha,y^{n},\psi)
%   \;=\;\piVal^{-1}\!\bigl([\beta,1]\bigr),
% \]
% the preimage of a closed set under a continuous map;
% Hence each value is closed.
define
\[
  G\;\coloneqq\;\bigl\{(\alpha,y^{n},\psi,y):
      \piVal(y,y^{n},\psi)\ge\beta\bigr\}
  \subset [0,1]\times\Y^{n}\times\F\times\Y.
\]
This is a super-level set of \(\pi(\cdot,y^{n},\psi)\), and since $\pi$ is upper semicontinuous, $G$ is closed. In turn, $\operatorname{Gr}(\kappaCorr)=G$ is closed.

\textbf{(ii) $\CRED$.}
For every closed $A\in\SigY$, set
\[
  G_{A}
  \coloneqq\Bigl\{(y^{n},\psi,P):
      P(A)\le\overline\Pi_{(y^{n},\psi)}(A)\Bigr\}.
\]
Weak$^\star$-continuity of $P\mapsto P(A)$
and upper semicontinuity of the right‐hand side (see Lemma \ref{lem-H4})
make $G_{A}$ closed.
Because $\operatorname{Gr}(\CRED)=\bigcap_{A\in\SigY}G_{A}$,
the graph is closed.

\textbf{(iii) $\IHDR$.} For each $A\in\SigY$ define
$f_{A}(\alpha,\credset)\coloneqq\underline P_{\!\credset}(A)-(1-\alpha)$.
Weak$^\star$ continuity of $P\mapsto P(A)$ and compactness of $\credset$
imply that $\credset\mapsto\underline P_{\!\credset}(A)$
is upper semicontinuous in the Vietoris topology \ref{H5},
while $\alpha\mapsto1-\alpha$ is continuous.
Hence the set
\[
  H_{A}\coloneqq\bigl\{(\alpha,\credset):f_{A}(\alpha,\credset)\ge0\bigr\}
\]
is closed; Moreover $(\alpha,\credset)\mapsto H_{A}(\alpha,\credset)$
is closed‐valued by \ref{H1}.
In turn,
$\operatorname{Gr}(\IHDR)=
      \bigl\{(\alpha,\credset,y):y\in\Y\setminus
            \bigcap_{A}H_{A}(\alpha,\credset)\bigr\}^{c}
      =\bigcap_{A}(H_{A}\times\Y)$
is closed.




Notice also that $Y$ is compact Hausdorff by \ref{H1}, and that $\Delta_Y$ is compact by \ref{H5} and Banach-Alaoglu, and Hausdorff because it is a subset of a dual Banach space equipped with its weak$^\star$ topology. 

It follows that $\kappaCorr$, $\CRED$, and $\IHDR$ are upper hemicontinuous by Lemma \ref{lem:CG}. In turn, they are morphisms of $\mathbf{UHCont}$. Fix now some $\alpha \in [0,1]\setminus S_{n+1}$. The restrictions $\kappaCorr_\alpha$ and $\IHDR_\alpha$ remain upper hemicontinuous. Notice also that $t(\CRED)=s(\IHDR_\alpha)=\mathscr{C}$; That is, the target space of $\CRED$ and the source space of $\IHDR_\alpha$ coincide, and are equal to the space of credal sets $\mathscr{C}$. This is clear by looking at the functional forms $\CRED^\text{funct}$ and $\IHDR^\text{funct}_\alpha$ of $\CRED$ and $\IHDR_\alpha$, respectively.

    $Y$ is a topological space from \ref{H1}; $[0,1] \times \Ccal$ is a topological space in the product topology by \ref{H5}; $Y^n \times \F$ is a topological space in the product topology by \ref{H2}; $[0,1] \times Y^n \times \mathscr{F}$ is a topological space in the product topology by \ref{H1} and \ref{H2}. Hence, these spaces are all objects of $\mathbf{UHCont}$.

    The fact that the Full Conformal Prediction Diagram commutes in $\mathbf{UHCont}$, then, is an immediate consequence of \citet[Proposition 5]{cp-ip}. It states that, for all $\alpha \in [0,1]$, $y^n \in Y^n$, and $\psi \in \mathscr{F}$, the Conformal Prediction Region $\kappa_\alpha(y^n,\psi)$ corresponds to the $\alpha$-level IHDR of the credal set $\CRED(y^n,\psi)$.
\end{proof}

