\section{Conformal Prediction as a Weakly measurable Morphism}\label{main2}
%The following is introduced in \citet[Definition 18.1]{aliprantis}.

This section introduces category $\mathbf{WMeas}_{\text{uc}}$, and shows that, under minimal assumptions, the (Full) Conformal Prediction correspondence $\kappa$ is a morphism of $\mathbf{WMeas}_{\text{uc}}$ as well, embedded in a commuting diagram. The following too is inspired by \citet[Example 1.1.14]{perrone2024starting}.


\begin{definition}[Structure $\mathbf{WMeas}_{\text{uc}}$]
\label{meas-corr-def}
Define a structure $\mathbf{WMeas}_{\text{uc}}$ as follows,
\begin{itemize}
  \item \textbf{Objects:} Measurable Polish spaces $(X,\Sigma_X)$, with $\Sigma_X=\mathcal{B}(X)$, the Borel $\sigma$-algebra.
  \item \textbf{Morphisms:} Weakly measurable (see Definition \ref{w-mble-definition} in Appendix \ref{funct-anal}), uniformly compact-valued (see Definition \ref{unif-cpct-val-definition} in Appendix \ref{funct-anal}) 
        correspondences $\Phi: X\rightrightarrows Y$.
  % \item \textbf{Composition:} $(\Psi\circ\Phi)(x)=\bigcup_{y\in\Phi(x)}\Psi(y)$.
  % \item \textbf{Identities:} $\operatorname{id}_X(x)=\{x\}$.
\end{itemize}
\end{definition}

\begin{theorem}[$\mathbf{WMeas}_{\text{uc}}$ is a category]
\label{meas-corr-cat}
The structure $\mathbf{WMeas}_{\text{uc}}$ defines a category.
\end{theorem}

\begin{proof}
We verify the four axioms.

\textbf{(1) and (4) Identity morphisms and Identity laws.}
For any object $X$, $\operatorname{id}_X(x)=\{x\}$ is non-empty compact.
Put $K_{\operatorname{id}_X}=X$ (compact because $X$ is Polish and we may take
the closed unit ball in its metric); The uniformly compact-valued condition holds.
For every open $O\subseteq X$ we have
$\operatorname{id}_X^{-1}(O)=O\in\Sigma_X$, so $\operatorname{id}_X$
is a morphism.  The usual set-theoretic equalities
$\Phi\circ\operatorname{id}_X=\Phi$ and
$\operatorname{id}_Y\circ\Phi=\Phi$ prove the identity laws.

\textbf{(2) Associativity.}
For morphisms
$\Phi\colon X\rightrightarrows Y$,
$\Psi\colon Y\rightrightarrows Z$ and
$\Theta\colon Z\rightrightarrows W$,
the associativity of union gives
$\bigl((\Theta\!\circ\!\Psi)\circ\Phi\bigr)(x)
      =(\Theta\!\circ\!(\Psi\!\circ\!\Phi))(x)$,
for every $x\in X$.

\textbf{(3) Closure under composition.}
Let $\Phi\colon X\rightrightarrows Y$ and
$\Psi\colon Y\rightrightarrows Z$ be morphisms.
Write $K_\Phi\subseteq Y$ and $K_\Psi\subseteq Z$ for the uniform compact bounds, see Definition \ref{def:ucv}.(ii).

\emph{Compactness of fibers.}
For each $x\in X$,
\[
  (\Psi\circ\Phi)(x)
     =\bigcup_{y\in\Phi(x)}\Psi(y)
     \subseteq \bigcup_{y\in\Phi(x)} K_\Psi
     \subseteq K_\Psi .
\]
Since $K_\Psi$ is compact and the union is taken inside it,
$(\Psi\circ\Phi)(x)$ is a closed subset of a compact
space, hence compact.  Thus compactness holds with the \emph{same}
compact bound $K_\Psi$, so the uniformly compact-valued condition also holds.

\emph{Weak measurability.}
Fix an open $O\subseteq Z$ and define
$H\coloneqq\Psi\circ\Phi$.
Because $\Phi$ has non-empty closed values, the
Kuratowski-Ryll-Nardzewski theorem \citep[Theorem 18.13]{aliprantis} yields Borel selectors
$(f_n)_{n\in\mathbb N}\subseteq\mathcal{B}(X,Y)$ with
$f_n(x)\in\Phi(x)$ and $\overline{\{f_n(x):n\in\mathbb N\}}=\Phi(x)$.
Then
\[
  H(x)\cap O\neq\emptyset
  \iff \exists n\in \mathbb{N} : \Psi(f_n(x))\cap O\neq\emptyset,
\]
so
\[
  H^{-1}(O)=\bigcup_{n\in\mathbb N}f_n^{-1}\!\bigl(\Psi^{-1}(O)\bigr).
\]
Each $f_n$ is Borel and $\Psi$ is weakly measurable, whence
$\Psi^{-1}(O)\in\Sigma_Y$ and
$f_n^{-1}\!\bigl(\Psi^{-1}(O)\bigr)\in\Sigma_X$.
A countable union of Borel sets is Borel, so $H^{-1}(O)\in\Sigma_X$.
Therefore $H$ is weakly measurable, completing closure.

Therefore, $\mathbf{WMeas}_{\text{uc}}$ satisfies the axioms of a category.
\end{proof}

Similarly to what we did in Section \ref{main}, we now ask ourselves what are the minimal conditions that make correspondences $\kappa$, $\CRED$, and $\IHDR$ uniformly compact-valued and weakly measurable. As we shall see in Theorem \ref{conf-pred-diagr2}, they are the same as in Section \ref{main}, with \ref{H1} and \ref{H2} slightly strengthened to

\begin{enumerate}[label=(\roman*')]
  \item\label{H1-prime}
    $\Y$ is compact metric and $\SigY$ is its Borel $\sigma$-field.
\item\label{H2-prime}
    Each $\psi\in\F$ is jointly continuous on $\Y^{n}\times\Y$;
    $\F$ is Polish in the uniform ($\sup$-norm) topology.
\end{enumerate}

In Remark \ref{rk:minimality2}, we show that \ref{H1-prime} is needed to make $\IHDR$ weakly measurable, and \ref{H2-prime} to make $Y^n \times \F$ Polish. We are now ready for the main result of this section.


\begin{theorem}[The Conformal Prediction Diagram Commutes, $\mathbf{WMeas}_{\text{uc}}$]\label{conf-pred-diagr2}
   Assume that \ref{H1-prime}, \ref{H2-prime}, \ref{H3}, \ref{H5} hold, and that the conformal transducer $\pi$ is {\em consonant}. Consider the restrictions $\kappa_\alpha$ and $\IHDR_\alpha$ to any $\alpha \in [0,1]$ that satisfies \ref{H3}. Then, $\IHDR_\alpha \circ \CRED = \kappa_\alpha$. That is, the {\em Full CP Diagram}
$$
   \begin{tikzcd}
    Y^n \times \mathscr{F} \ar{r}{\CRED} \ar{dr}[swap]{\kappa_\alpha} & \mathscr{C} \ar{d}{\IHDR_\alpha} \\
    & \Sigma_Y
   \end{tikzcd}
  $$
  commutes in $\mathbf{WMeas}_{\text{uc}}$.
\end{theorem}

Notice that, in the Full CP Diagram, $\Sigma_Y=\mathcal{B}(Y)$ by Definition \ref{meas-corr-def}.

\begin{proof}[Proof of Theorem \ref{conf-pred-diagr2}]
Fix any $n\in \mathbb{N}$. We first show that $\kappaCorr$, $\CRED$, and $\IHDR$ are uniformly compact-valued and weakly measurable.

\textbf{Uniformly compact-valued.}
All three images lie inside the fixed compact spaces
\(Y\) (by \ref{H1-prime}) or \(\Delta_Y\) (by \ref{H5}); We are now left to show that they themselves are compact-valued. 

Notice that, under consonance, for all $y^n \in Y^n$ and all $\psi\in\F$, $\CRED(y^n,\psi)$ is a credal set, so a closed subset of the compact space \(\Delta_Y\), and so compact in turn. 

Also, for all $\alpha \in [0,1]\setminus S_{n+1}$ and all credal sets $\mathcal{M}$, $\IHDR(\alpha,\mathcal{M})$ is an intersection of closed sets,
%(from the weak inequality $\underline{P}_\mathcal{M}(A) \geq 1-\alpha$), 
and so closed itself. In turn, it is a closed subset of the compact space $Y$, so it is itself compact. 

An argument similar to point \textbf{(i)} in the Proof of Theorem \ref{conf-pred-diagr} shows that, for all $y^n \in Y^n$, all $\psi\in\F$, and all $\alpha \in [0,1]\setminus S_{n+1}$, the set $\kappa(\alpha,y^n,\psi)=\{y : \pi(y,y^n,\psi) >\alpha\} = \{y : \pi(y,y^n,\psi) \geq \beta\}$ is closed, where $\beta\equiv \beta(\alpha)$ was defined in \eqref{beta-def}. Indeed, it is a super-level set of \(\pi(\cdot,y^{n},\psi)\), and the latter is upper semicontinuous. This is because $\{y: \psi (y^{n+1}_{-i},y_i )  \geq \psi (y^{n+1}_{-(n+1)},y_{n+1})\}$ is a closed set, so $\mathbbm{1}[\{y: \psi (y^{n+1}_{-i},y_i )  \geq \psi (y^{n+1}_{-(n+1)},y_{n+1})\}]$ is upper semicontinuous, and the latter is preserved by finite averages.
%(by the upper semicontinuity of $\pi(\cdot,y^n,\psi)$, a result of $\psi$ being jointly continuous \ref{H2}). 
Thus, $\kappa(\alpha,y^n,\psi)$ is a closed subset of the compact space $Y$, so it is itself compact.

\textbf{Weak measurability of \(\kappa\).} Let $\Lambda \coloneqq [0,1]\setminus S_{n+1}$. For every non-empty open set \(G\subseteq Y\), put
\[
  f_G(\alpha,y^{n},\psi)
  \;\coloneqq\;\sup_{y\in G}\pi(y,y^{n},\psi),
  \quad
  (\alpha,y^{n},\psi)\in\Lambda\times Y^{n}\times\F.
\]
Since \(\pi(\cdot,y^{n},\psi)\) is upper semicontinuous
and \(G\) is open in the compact space \(Y\),
\(f_G\) is itself {upper semicontinuous} and therefore Borel.

Because \(\pi\) only takes values in \(S_{n+1}\),
\[
  \kappa(\alpha,y^{n},\psi)\cap G\neq\emptyset
  \quad\Longleftrightarrow\quad
  f_G(\alpha,y^{n},\psi)\;\ge\;\beta(\alpha).
\]
The map \(\beta:\Lambda\to S_{n+1}\) is piecewise
{constant} (hence Borel). Set
\[
  \Theta_G
  \coloneqq\bigl\{(\alpha,y^{n},\psi)\in
           \Lambda\times Y^{n}\times\F:
           f_G(\alpha,y^{n},\psi)\ge\beta(\alpha)\bigr\}.
\]
Because \(f_G\) is Borel and \(\beta\) is Borel,
\(\Theta_G\) is a Borel subset of the product space.
Therefore
\[
  \bigl\{(\alpha,y^{n},\psi):
         \kappa(\alpha,y^{n},\psi)\cap G\neq\emptyset\bigr\}
  \;=\;\Theta_G\in\mathcal B\bigl(\Lambda\times Y^{n}\times\F\bigr).
\]

In turn, for every open \(G\subseteq Y\), the selector set
\(\{\kappa(\cdot)\cap G\neq\emptyset\}\) is measurable,
hence the correspondence
\[
  \kappa:\;\Lambda\times Y^{n}\times\F\rightrightarrows Y
\]
is {weakly measurable} \citep[Definition 18.1]{aliprantis}.



\textbf{Weak measurability of \(\CRED\).} 
Let \(G\subseteq\Delta_Y\) be open.
Because \(\Delta_Y\) is metric and \(\CRED\) has compact values,
\(\CRED(y^n,\psi)\cap G\neq\emptyset\)
if and only if there exists \(P\in G\) satisfying all the  constraints
\(P(A_j)\le\overline{\Pi}_{(y^n,\psi)}(A_j)\), where the $A_j$'s are the closed sets in $\Sigma_Y$.
For each integer \(m\), let
\(G_m=\{P\in G : d(P,G^{c})\ge 1/m\}\);
\(\{G_m\}\) is a countable basis for \(G\).
Hence
\[
  \bigl\{(y^{n},\psi):\CRED(y^{n},\psi)\cap G\neq\emptyset\bigr\}
  \;=\;
  \bigcup_{m=1}^{\infty}
  \bigcup_{P\in\mathscr D_m}
  \bigl\{(y^{n},\psi):
         P(A_j)\le\overline{\Pi}_{(y^{n},\psi)}(A_j),\;
         \forall j\bigr\},
\]
where \(\mathscr D_m\) is a \emph{countable} dense subset of \(G_m\)
(using separability of \(\Delta_Y\)).
Each inner set is Borel by Lemma \ref{lem-H4};
Countable unions preserve measurability,
so the whole pre-image is in
\(\mathcal{B}\bigl(Y^{n}\!\times\!\F\bigr)\).

\textbf{Weak measurability of \(\IHDR\).}  
For open \(G\subseteq Y\), let
\(\mathscr B=\{B_k\}_{k\in\mathbb N}\)
be a countable closed basis of \(Y\).
Define
\(
  \phi_k(\alpha,\credset)=1-\alpha-\underline P_{\!\credset}(B_k).
\)
Each \(\phi_k\) is u.s.c.\ (by \ref{H5}, since $\Ccal$ is endowed with the Vietoris topology and $\mathcal{M}$ is weak$^\star$-compact),
hence Borel on \([0,1]\times\mathscr C\).
Because
\(\IHDR(\alpha,\credset)\cap G\neq\emptyset
      \iff \exists k: B_k\subseteq G,\;\phi_k(\alpha,\credset)\le0,
\)
the desired pre-image is a \emph{countable union} of
Borel sets, hence Borel.

We have now showed that $\kappaCorr$, $\CRED$, and $\IHDR$ are uniformly compact-valued and weakly measurable, and thus morphisms of $\mathbf{WMeas}_{\text{uc}}$. Fix now any $\alpha \in [0,1]\setminus S_{n+1}$. It is easy to see that the restrictions $\kappa_\alpha$ and $\IHDR_\alpha$ remain uniformly compact-valued and weakly measurable. In addition, as in the Proof of Theorem \ref{conf-pred-diagr}, we have that $t(\CRED)=s(\IHDR_\alpha)=\Ccal$.


Now, recall that the product of two Polish spaces is Polish. Since $Y$ is compact metric by \ref{H1-prime}, it is also measurable Polish; $[0,1] \times \Ccal$ is measurable Polish in the product topology by \ref{H5}; $Y^n \times \F$ is measurable Polish in the product topology by \ref{H1-prime} and \ref{H2-prime}; $[0,1] \times Y^n \times \mathscr{F}$ is measurable Polish in the product topology by \ref{H1-prime} and \ref{H2-prime}. Hence, these spaces are all objects of $\mathbf{WMeas}_{\text{uc}}$.

The fact that the Full Conformal Prediction Diagram commutes in $\mathbf{WMeas}_{\text{uc}}$, then, is an immediate consequence of \citet[Proposition 5]{cp-ip}. 
