A simple example of a function $\psi \in \mathscr{F}$ that satisfies the assumptions in Theorem \ref{conf-pred-wmble}, and that is also of use in Machine Learning, is, for $\zeta,\xi>0$, $\psi_{\zeta,\xi}:(\mathbb{R}^d)^n \times \mathbb{R}^d \rightarrow \mathbb{R}$, $(y^n,y_{n+1}) \mapsto \psi_{\zeta,\xi}(y^n,y_{n+1}) \coloneqq \frac{1}{\xi^2} \|y_{n+1} - \frac{1}{n}\sum_{i=1}^n y_i\|^2 + \zeta \|y_{n+1}\|^2$. This is reminiscent of the regularized one-step loss, but also of the online anomaly (novelty) score, and of energy-based modeling (by putting energy function $E(y)=\psi_{\zeta,\xi}(y^n,y)$).




\begin{proof}[Proof of Theorem \ref{conf-pred-wmble}]

Fix $x=(\alpha,y^{n},\psi)\in X_+$ and set
\[
   M\coloneqq\max_{1\le i\le n}\psi\bigl(y^{n+1}_{-i},y_i\bigr).
\]
For any $y\in\kappa(x)$ the index $i=n+1$ inside $p$ satisfies the
inequality automatically, but achieving
$p(y,y^{n},\psi)\ge\alpha>\tfrac1{n+1}$ forces at least one of the other
$n$ indicators to equal~$1$, whence
$\psi(y^{n},y)\le M$.  Thus
\[
    \kappa(x)\subset
    K_{\psi,y^{n}}(M)\;\coloneqq\;\{y:\psi(y^{n},y)\le M\}.
\]
By \textnormal{(IC)} the set $K_{\psi,y^{n}}(M)$ is compact, and $\kappa(x)$
is closed (by the proof of Theorem \ref{conf-pred-uhc}), so $\kappa(x)$ is compact.

If $\alpha\le\frac1{n+1}$ the last index ensures
$p(y,y^{n},\psi)\ge\alpha$ for \emph{all} $y\in Y$,
so $\kappa(x)=Y$; compactness then fails whenever $Y$ is non-compact.

\emph{Step 1.} Under (B), $X_+$ is a is a Borel (indeed analytic) sub-space of the Polish space $X=[0,1]\times Y^{n}\times\mathscr{F}$; Hence it is a standard Borel space, which suffices for what follows.
%$G_\delta$ subset of
%$X=[0,1]\times Y^{n}\times\mathscr{F}$,
%hence itself a Polish space (Souslin theorem).

\noindent\emph{Step 2.}  
As we have seen before, each value of $\kappa$ on $X_+$ is compact.
The proof of Theorem \ref{conf-pred-uhc} gives a closed graph.

\noindent\emph{Step 3.}  
Choose and fix a countable dense set $D=\{d_1,d_2,\dots\}\subset Y$. For each $m\in\mathbb N$ define
\[
   A_m\;\coloneqq\;\{x\in X_{+}:d_m\in\kappa(x)\}.
\]
Because $\operatorname{Gr}\kappa$ is closed, we have
\(
   A_m = \bigl\{x:(x,d_m)\in\operatorname{Gr}\kappa\bigr\},
\)
hence $A_m$ is closed (and therefore Borel) in $X_{+}$. Set
\[
   m_1(x)\;\coloneqq\;\min\{m\ge1:x\in A_m\},\qquad
   s_1(x)\;\coloneqq\;d_{\,m_1(x)}.
\]
The pre-image $\{x:m_1(x)=m\}=A_m\setminus\bigcup_{\ell<m}A_\ell$ is
Borel, so $m_1$ and $s_1$ are Borel.

Given Borel selectors $s_1,\dots,s_k$ with corresponding indices
$m_1<\dots<m_k$, define
\[
   m_{k+1}(x)
   \coloneqq\min\bigl\{m>m_k(x):x\in A_m\bigr\},
   \qquad
   s_{k+1}(x)\coloneqq d_{\,m_{k+1}(x)}.
\]

If the set in braces is empty (which can happen only when
$\kappa(x)$ is finite) put $m_{k+1}(x)\coloneqq m_k(x)$, so
$s_{k+1}(x)=s_k(x)$.  
The map $m_{k+1}$ is Borel for the same reason as $m_1$, hence
$s_{k+1}$ is Borel.  
Proceeding recursively we obtain a sequence
\begin{equation}\label{eq:selectors}
      s_1,s_2,s_3,\dots:X_{+}\;\rightarrow\;Y
      \quad\text{with}\quad
      s_k(x)\in\kappa(x)\ \ \forall(x,k).
\end{equation}

Fix $x\in X_{+}$ and $y\in\kappa(x)$.  
Choose $d_m\in D\cap\kappa(x)$ with $d_m$ arbitrarily close to $y$
(using density of $D$ and closedness of $\kappa(x)$,
where $d$ is any complete metric compatible with the topology of $Y$).
By construction of the indices,
$m=m_j(x)$ for some $j$, so $s_j(x)=d_m$.  
Hence for every $\varepsilon>0$ there exists $j$ with
$d(s_j(x),y)<\varepsilon$, giving
\begin{equation}\label{eq:dense}
   \kappa(x)
   \;=\;
   \overline{\{s_1(x),s_2(x),\dots\}},
   \qquad\forall x\in X_{+}.
\end{equation}

For an open set $U\subset Y$,
\[
   \kappa^{-1}(U)
   =\{x:\kappa(x)\cap U\neq\emptyset\}
   \overset{\eqref{eq:dense}}{=}
   \{x:\exists k,\ s_k(x)\in U\}
   =\bigcup_{k=1}^{\infty}s_k^{-1}(U).
\]
Each $s_k$ is Borel by \eqref{eq:selectors}, so
$s_k^{-1}(U)$ is Borel; the countable union is Borel.
Thus $\kappa^{-1}(U)\in\mathcal B(X_{+})$ for every open $U$,
i.e. $\kappa$ is weakly (Borel) measurable on $X_{+}$.
\end{proof}


