For $P\in\Delta_\Theta^{\mathrm{dens}}$ having density $p$, and data $y^{n}\in Y^{n}$, set
\[
  p_P\left(y_{n+1}\mid y^{n}\right)
     \coloneqq
     \frac{N_P(y_{n+1},y^{n})}{D_P(y^{n})},
\]
where $N_P(y_{n+1},y^{n})\coloneqq\int_\Theta k_{n+1}(\theta,(y^n,y_{n+1}))
p(\theta)\lambda_\Theta(\text{d}\theta)$. 
%It is easy to see, then, that $p_P\left(y_{n+1}\mid y^{n}\right)$ is the classical posterior predictive distribution \citep{hoff}. 
By \ref{H10}, it is well-defined. 


Because $y\mapsto p_P(y\mid y^{n})$ is continuous (we prove this in Lemma \ref{bayes-cont}) and
$Y^{n+1}$ is compact by \ref{H1}, the natural codomain for such a map is the Banach space $C(Y^n \times Y)$ with norm $\|f\|_\infty\coloneqq\sup_{(y^n,y)\in Y^n \times Y}|f(y^n,y)|$. Define
\[
  \mathsf{BCP}:\;
  Y^{n}\times\Delta_\Theta^{\mathrm{dens}}
  \rightarrow
  Y^{n}\times C(Y^n \times Y),
\quad
  \mathsf{BCP}\bigl(y^{n},P\bigr)
     \coloneqq\bigl(y^{n},\psi_{(y^{n},P)}\bigr),
\]
where
\[
  \psi_{(y^{n},P)}(y_{n+1})
      \coloneqq-\,p_P(y_{n+1}\mid y^{n});
\]
We call it $\mathsf{BCP}$ because it is evocative of an acronym for Bayesian Conformal Prediction \citep{fong-bayes}. Next, we have an important lemma.


\begin{lemma}\label{bayes-cont}
Under \ref{H6}-\ref{H10}, the following hold for every fixed $n\in \mathbb N$,

\begin{itemize}
    \item For every $P\in\Delta_\Theta^{\mathrm{dens}}$, the
        predictive map
        \(
            (y_{n+1},y^{n})\mapsto p_P(y_{n+1}\mid y^{n})
        \)
        is jointly continuous on $Y^n \times Y = Y^{n+1}$;
    \item The map $\mathsf{BCP}$ is continuous when $C(Y^n \times Y) \equiv C(Y^{n+1})$ is equipped with the sup-norm.
\end{itemize}
\end{lemma}

\begin{proof}
Throughout, let $P\in\Delta_\Theta^{\mathrm{dens}}$ be fixed and write
$\text{d}P/\text{d}\lambda_\Theta=p$.

\textbf{Step 1. Continuity of the numerator $N_P$.}
Define
\[
  g(\theta,y_{n+1},y^{n})
    \coloneqq k_{n+1}(\theta,(y^n,y_{n+1}))p(\theta);
\]
We have $\lvert g\rvert\le p(\theta)M(\theta)$ by \ref{H8}.
Assumption \ref{H7} gives continuity of
$(y_{n+1},y^{n})\mapsto g(\theta,y_{n+1},y^{n})$ for
$\lambda_\Theta$-almost all $\theta$.
The envelope $p M^{n+1}\in L^{1}(\lambda_\Theta)$ by \ref{H9}; Hence, 
dominated convergence yields continuity of
$(y_{n+1},y^{n})\mapsto N_P(y_{n+1},y^{n})$.

\textbf{Step 2. Continuity and positivity of the denominator $D_P$.}
The integrand in
\(
  D_P(y^{n})
\)
is $g$, but ``stopped'' at observation $n$, so the same argument as Step 1 shows that 
\(y^{n}\mapsto D_P(y^{n})\) is continuous.  Positivity follows from \ref{H10}.

\textbf{Step 3. Joint (and uniform) continuity of the predictive.}
Because $Y^{n+1}$ is compact by \ref{H1} and $D_P$ never vanishes,
\[
  p_P(y_{n+1}\mid y^{n})
      =\frac{N_P(y_{n+1},y^{n})}{D_P(y^{n})}
\]
is continuous in $(y_{n+1},y^{n})$ and, by compactness, uniformly
continuous.  This proves joint continuity of the map \(
            (y_{n+1},y^{n})\mapsto p_P(y_{n+1}\mid y^{n})
        \).

\textbf{Step 4. Continuity in the prior.}
Let $P_m\to P$ in $L^{1}(\lambda_\Theta)$, with densities
$p_m\coloneqq \text{d}P_m/\text{d}\lambda_\Theta$.
From \ref{H8}-\ref{H9}
\[
  \bigl\|N_{P_m}-N_{P}\bigr\|_\infty
     \le\int_\Theta \lvert p_m-p\rvert\,M\,\text{d}\lambda_\Theta
     \xrightarrow[m\to\infty]{}0,
\]
and similarly
\(
    \|D_{P_m}-D_P\|_\infty\to0.
\)
Since $D_P$ is bounded below (by Step 2) and $D_{P_m}$ converges uniformly,
\[
 \|p_{P_m}(\cdot\mid y^{n})-p_P(\cdot\mid y^{n})\|_\infty
     \xrightarrow[m\to\infty]{}0
     \quad\text{uniformly in }y^{n}.
\]

\textbf{Step 5. Continuity of \(\mathsf{BCP}\).}
Fix a point
\(
  (y^{n},P)
\)
in the domain.  If
\(
  y^{n}_m\to y^{n}\text{ and }P_m\to P
\)
(as in Step 4), then
\[
  \|\psi_{(y^{n}_m,P_m)}-\psi_{(y^{n},P)}\|_\infty
    \le
    \|p_{P_m}(\cdot\mid y^{n}_m)-p_{P_m}(\cdot\mid y^{n})\|_\infty
      +\|p_{P_m}(\cdot\mid y^{n})-p_P(\cdot\mid y^{n})\|_\infty .
\]
The first term vanishes by uniform continuity from Step 3, the second by Step 4. Hence,
\(\|\psi_{(y^{n}_m,P_m)}-\psi_{(y^{n},P)}\|_\infty\to0\),
and the first component $y^{n}_m\to y^{n}$ by assumption. Therefore, \(\mathsf{BCP}\) is continuous.
\end{proof}

Conditions \ref{H6}-\ref{H10} are indispensable for Lemma \ref{bayes-cont} to hold. This is examined in the following remark.

\begin{remark}[Minimality of \ref{H6}-\ref{H10}]
The five conditions \ref{H6}-\ref{H10} are truly minimal for Lemma \ref{bayes-cont} to hold.
% not only sufficient for the continuity of
% \[
%   F:(y^n,\Pi)\;\longmapsto\;(y^n,\,-\,p_\Pi(\cdot\mid y^n))
%   \;\in\;Y^n\times C(Y^{n+1}),
% \]
% but also \emph{necessary}.  
If any single hypothesis is dropped, one can construct a Bayesian model for which \(\mathsf{BCP}\) fails to be continuous (or even well-defined). To see this, consider the following.

\begin{itemize}
  \item {\bf Drop \ref{H6} (Measurability of \(k\)).}  Without measurability in \(\theta\), the integrals defining \(N_P\) and \(D_P\) need not exist as Lebesgue integrals.
  \item {\bf Drop \ref{H7} (\(y\)-continuity a.e.).}  If \(k_n(\theta,\cdot)\) has a jump in \(y\), then \(D_P\)---and hence \(p_P\)---can jump as a function of \(y\), breaking continuity.
  \item {\bf Drop  \ref{H8} (Integrable envelope).} In the absence of any \(M\in L^1(\lambda_\Theta)\) with \(k_{n+1}(\theta,(y^n,y_{n+1}))\le M(\theta)\), the dominated convergence fails, and we can have \(P_m\to P\) for which \(N_{P_m}\not\!\to N_P\).
  \item {\bf Drop \ref{H9} (Prior integrability).}  If \(\int_\Theta M(\theta)P(\text{d}\theta)=\infty\) for some \(P\), then \(N_P\) or \(D_P\) may diverge or lose continuity.
  \item {\bf Drop \ref{H10} (Positive marginal likelihood).}  If \(D_P(y^n)=0\) for some \(y^n\), the posterior density \(p_P\) is undefined there, so \(\mathsf{BCP}\) cannot be continuous.
\end{itemize}

In practice, conditions \ref{H6}-\ref{H10} are almost \emph{built-in} to any reasonable Bayesian model. Let us briefly expand on this. First, notice that almost every statistical model (Gaussian, exponential
    family, mixture, etc.) has a likelihood density continuous and 
    measurable in $y$, so that \ref{H6} is met.

Condition \ref{H7} guarantees that, as we vary our
    data $y^n$, the integrand in $N_P$ and $D_P$ moves continuously, so
    dominated convergence applies.  In practice, standard density kernels
    (Normal, Laplace, Student-$t$, etc.) are smooth in $y$.

  The uniform‐in‐$y$ bound of \ref{H8} is the key to swapping limits and integrals.
    If $Y$ is compact (as it is in our setting, by \ref{H1}) and $k_n(\theta,\cdot)$ is continuous, we can often take
    $M(\theta)=\sup_{y\in Y}k_n(\theta,y)$, which is finite and
    $L^1$-integrable under mild assumptions on $k_n$.

 Since $N_P$ involves $k_{n+1}$, the moment condition in \ref{H9} 
    ensures finiteness and continuity of the predictive density.  Common priors
    (Gaussian, Gamma, Beta, compact support) have finite moments of all
    orders, so \ref{H9} is automatic.

  Condition \ref{H10} prevents division by zero in the posterior
    \( p_P(y_{n+1}\mid y^n)=N_P/D_P\).  In well‐posed
    Bayesian models, the prior’s support overlaps every parameter value
    that could generate the observed data, so $D_P$ never vanishes.

It is safe to say, then, that hypotheses \ref{H6}-\ref{H10} are the \emph{minimal technical
machinery} needed to ensure the posterior predictive is well‐defined and
varies continuously in both the data $y^n$ and the prior $P$.  In
practical modeling, they hold almost automatically.
\end{remark}

Before the main result of this section, we need to introduce a further condition on the posterior predictive Cumulative Density Function (CDF).

\begin{enumerate}[label=(\roman*),start=10]
  \item\label{H11} {\em Well-behaved CDF.} 
    For each fixed $(y^n,P) \in Y^n \times \Delta_\Theta^\text{dens}$, the CDF
    \[
      F(c;\,y^n,P)
      \coloneqq\int_{\{\,p_P(\cdot\mid y^n)\le c\}}
             p_P(y\mid y^n)\text{d}y
    \]
    is continuous and strictly increasing in a neighborhood of  
    its $(1-\alpha)$-quantile
    \[
      c(\alpha,y^n,P)
      = \inf\{\,c: F(c;y^n,P)\ge1-\alpha\}.
    \]
\end{enumerate}


Call then $\mathsf{QUANT}: [0,1] \times Y^n \times \Delta_\Theta^\text{dens} \rightrightarrows Y$ the set-valued map that extracts the $\alpha$-level set of the posterior predictive distribution. That is,

$$(\alpha,y^n,P) \mapsto \mathsf{QUANT}(\alpha,y^n,P)
    \coloneqq H\bigl(c(\alpha,y^n,P),\,y^n,P\bigr),$$
where 
$$H:\R\times Y^n\times\Delta_\Theta^{\mathrm{dens}}
    \;\rightrightarrows\;Y,
  \qquad
  H\bigl(c,y^n,P\bigr)
    \coloneqq \{\,y\in Y: p_P(y\mid y^n)\ge c\}.$$


%Highest Density Region of the posterior predictive distribution associated with prior $P\in\Delta_\Theta^\text{dens}$ and likelihood encoded in the kernel $k$ \citep{hyndman}. That is, we simply replace $\inf_{P\in\mathcal{M}}P(A)$ in \eqref{ihdr-corresp} with $P_\text{pred}(A)$, where $P_\text{pred}$ is a probability measure in $\Delta_Y^\text{dens}$ whose density with respect to a $\sigma$-finite Borel measure $\lambda_Y$ on $(Y,\Sigma_Y)$ is $\text{d}P_\text{pred}/\text{d}\lambda_Y=p_P$.

\begin{lemma}\label{uhc-quant}
    Under assumptions \ref{H1}-\ref{H11}, the correspondence $\mathsf{QUANT}$ is upper hemicontinuous.
\end{lemma}

\begin{proof}
    First, we show that under \ref{H1}-\ref{H11}, the correspondence $H$ is upper hemicontinuous. Fix $(c_0,y^n_0,P_0)$ and let $V\supset H(c_0,y^n_0,P_0)$ be open in $Y$.
Since $p_P(y\mid y^n)$ is jointly continuous and $Y$ is compact,
\(
  H(c_0,y^n_0,P_0)
  =\{y: p_{P_0}(y\mid y^n_0)\ge c_0\}
\)
is closed and contained in $V$.  Thus there is $\varepsilon>0$ such that
\[
  \bigl\{y: p_{P_0}(y\mid y^n_0)\ge c_0 - \varepsilon\bigr\}
  \;\subset\;V.
\]
By joint continuity of $(c,y^n,P,y)\mapsto p_P(y\mid y^n)$, there is a
neighborhood $U$ of $(c_0,y^n_0,P_0)$ in
$\R\times Y^n\times\Delta_\Theta^{\mathrm{dens}}$ such that for all
\((c,y^n,P)\in U\) and all $y\in Y$,
\[
  p_P(y\mid y^n)\;\ge\;c
  \quad\Longrightarrow\quad
  p_{P_0}(y\mid y^n_0)\;\ge\;c_0 - \varepsilon.
\]
Hence for every $(c,y^n,P)\in U$,
\[
  H(c,y^n,P)
  =\{y:p_P(y\mid y^n)\ge c\}
  \;\subset\;
  \{y:p_{P_0}(y\mid y^n_0)\ge c_0-\varepsilon\}
  \;\subset\;V,
\]
proving upper hemicontinuity.  
%Closed‐valuedness is immediate from continuity of the level sets.

Now, we show that under \ref{H1}-\ref{H11}, function $c$ is continuous. By \ref{H11}, for each fixed $(y^n,P)$ the function
$c\mapsto F(c;y^n,P)$ is continuous and strictly increasing near the target
quantile.  Standard results on the continuity of inverse functions then
imply that 
\[
  (\alpha,y^n,P)\;\longmapsto\;c(\alpha,y^n,P)
\]
is continuous at every point, since it solves
$F\bigl(c(\alpha,y^n,P);y^n,P\bigr)=1-\alpha$ uniquely in $c$, and both the
left side and the right side vary continuously in
\((\alpha,y^n,P)\).

Finally, we put everything together to show the upper hemicontinuity of $\mathsf{QUANT}$. View $\mathsf{QUANT}$ as the composition
\[
  (\alpha,y^n,P)
  \;\xmapsto{\;c\;}\;
  \bigl(c(\alpha,y^n,P),\,y^n,P\bigr)
  \;\xmapsto{\;H\;}\;
  H\bigl(c(\alpha,y^n,P),\,y^n,P\bigr).
\]
As we showed before, $H$ is upper hemicontinuous in its three arguments, and
$c(\alpha,y^n,P)$ is continuous, hence he
singleton-valued correspondence associated with $c$ (that we still denote by $c$ for ease 
of notation) is upper hemicontinuous. The composition of two upper hemicontinuous correspondences is again upper
hemicontinuous \citep[Theorem 17.23]{aliprantis}.  Therefore, $\mathsf{QUANT}$ is upper hemicontinuous.
\end{proof}

Let us add a brief discussion on condition \ref{H11}.

\begin{remark}[On the Well-Behavior of the Predictive CDF]
In many continuous Bayesian models,
    \(p_P(y\mid y^n)\) is a continuous, strictly positive function on
    compact \(Y\) (for us, this holds by \ref{H1}).  As \(c\) varies, the level‐sets 
    \(\{y:p_P(y\mid y^n)\le c\}\) move continuously, so \(F(c)\) has no jumps. Since \(p_P\) has no plateaus of positive volume, for any
    \(c<c^\prime\), the set \(\{c<p_P(y \mid y^n)\le c^\prime\}\) has strictly positive mass,
    forcing \(F(c^\prime)-F(c)>0\). Hence, \(F(c)\) is both continuous and strictly increasing at the
    target quantile.


The condition may fail in two cases, rather negligible in practice. If \(p_P(y\mid y^n)\equiv c\) on a subset of \(Y\) of positive measure,
    then \(F(c)\) is constant across that plateau, violating strict increase. Also, if the predictive has atoms (point‐mass components), \(F(c)\) jumps at
    those mass points and fails to be continuous.
\end{remark}




Lemmas \ref{bayes-cont} and \ref{uhc-quant} are crucial in light of the following, which is the main result of this section.

\begin{theorem}[Unifying Bayes, Conformal, and Imprecise Prediction in $\mathbf{UHCont}$]\label{unifying-thm}
   Assume that \ref{H1}-\ref{H11} hold. Consider the restrictions $\kappa_\alpha$, $\IHDR_\alpha$, and $\mathsf{QUANT}_\alpha$ to any $\alpha \in [0,1]$ that satisfies \ref{H3}. Then, the following diagram
$$
   \begin{tikzcd}[row sep=3em, column sep=3.5em]
    Y^{n}\times\mathscr{F} 
        \ar[r, "\CRED"] 
        \ar[dr, swap, "\kappa_{\alpha}"] 
    & \mathscr{C} 
        \ar[d, "\IHDR_{\alpha}"] 
\\
    Y^n \times \Delta^\text{dens}_\Theta  
        \ar[u, "\mathsf{BCP}"]              %  A → Y^n × F  (choose any label, here ϕ)
        \ar[r, swap, "\mathsf{QUANT}_\alpha"]           %  A → Σ_Y      (choose any label, here ψ)
    & \Sigma_{Y}
\end{tikzcd}
  $$
  commutes in $\mathbf{UHCont}$, that is, $\mathsf{QUANT}_\alpha=\kappa_\alpha\circ\mathsf{BCP}=\IHDR_\alpha\circ\CRED\circ\mathsf{BCP}$.
\end{theorem}


\begin{proof}
    First, notice that we do not require consonance directly because it is immediately satisfied as a result of \ref{H1} and \(
            (y_{n+1},y^{n})\mapsto p_P(y_{n+1}\mid y^{n})
        \)
        being jointly continuous on $Y^n \times Y = Y^{n+1}$.

    Notice also that, by \ref{H1} and $\Delta^\text{dens}_\Theta$ being endowed the $L^1(\lambda_\Theta)$ topology, $Y^n \times \Delta^\text{dens}_\Theta$ is a topological space in the product topology, hence a well-defined object of $\mathbf{UHCont}$. 



    In addition, by Lemma \ref{bayes-cont}, function $\mathsf{BCP}$ is continuous. The latter implies that the singleton-valued correspondence associated with $\mathsf{BCP}$ (that we still denote by $\mathsf{BCP}$ for ease of notation) is upper hemicontinuous. Moreover, by Lemma \ref{uhc-quant}, correspondence $\mathsf{QUANT}$ (and also, trivially, its restriction $\mathsf{QUANT}_\alpha$ to some $\alpha$ satisfying \ref{H3}) is upper hemicontinuous as well. In turn, they are well-defined morphisms of $\mathbf{UHCont}$.

    Furthermore, we have that $t(\mathsf{BCP})=s(\kappa_\alpha)=s(\CRED)=Y^n \times \F$. That is, the target space of $\mathsf{BCP}$ coincides with the source spaces of both $\kappa_\alpha$ and $\CRED$. This is a consequence of 
    \begin{itemize}
        \item \citet{fong-bayes}, who show that the negative posterior predictive density is a valid non-conformity score (i.e. it is an element of $\F$ in \eqref{funct-coll});
        \item Lemma \ref{bayes-cont}, which shows that map
        \(
            (y_{n+1},y^{n})\mapsto p_P(y_{n+1}\mid y^{n})
        \)
        is jointly continuous on $Y^n \times Y = Y^{n+1}$ (and so also $\psi_{(y^n,P)}(y^{n+1})$ is continuous, since we simply multiply $p_P(y_{n+1}\mid y^{n})$ by $-1$). This shows that $\psi_{(y^n,P)}(y^{n+1}) \equiv \psi_{P}(y^n,y^{n+1})$ satisfies \ref{H2}.
    \end{itemize}

    Now, given our choice of non-conformity score, the Conformal Prediction Region, that is, the image $\kappa_\alpha(y^n,\psi_{(y^n,P)})$ of the Conformal correspondence $\kappa_\alpha$, coincides with the $\alpha$-level
set $\mathsf{QUANT}_\alpha(y^n,P)$ of the posterior predictive distribution, for all $\alpha$ that satisfies \ref{H3}. To see this, notice that, by definition, a candidate $y\in Y$ lies in $\mathscr{R}^{\psi_{(y^n,P)}}_\alpha(y^n) \equiv \kappa_\alpha(y^n,\psi_{(y^n,P)})$ if and only if
\[
  |\{\,i: \psi_{(y^n,P)}(y_i) \ge \psi_{(y^n,P)}(y_{n+1})\} | = |\{\,i: p_P(y_i \mid y^n) \le p_P(y_{n+1} \mid y^n)\} | >\;k \coloneqq \lceil (n+1)\alpha\rceil.
\]
But among the $n$ scores $\psi_{(y^n,P)}(y_1),\ldots,\psi_{(y^n,P)}(y_n)$, the event
$|\{i: \psi_{(y^n,P)}(y_i) \ge s\}|>k$ holds precisely when $s\le \psi_{(y^n,P)}(y_{(k)})$, where $\{\psi_{(y^n,P)}(y_{(1)}),\ldots,\psi_{(y^n,P)}(y_{(n)})\}$ are the ordered values of $\{\psi_{(y^n,P)}(y_1),\ldots,\psi_{(y^n,P)}(y_n)\}$. Therefore,
\[
  y\in \kappa_\alpha(y^n,\psi_{(y^n,P)})
  \quad\iff\quad
  \psi_{(y^n,P)}(y_{n+1})\;\le\;\psi_{(y^n,P)}(y_{(k)}).
\]
Set $c(\alpha,y^n,P)=\psi_{(y^n,P)}(y_{(k)})$.  Then,
\[
  \kappa_\alpha(y^n,\psi_{(y^n,P)})
    = \{\,y_{n+1} \in Y: \psi_{(y^n,P)}(y_{n+1})\le c(\alpha,y^n,P)\},
\]
that is, $\kappa_\alpha(y^n,\psi_{(y^n,P)})$ is exactly the level set of the posterior predictive
density at level $c(\alpha,y^n,P)$.

By \citet[Proposition 5]{cp-ip}, we also know that $\kappa_\alpha(y^n,\psi_{(y^n,P)})=\IHDR_\alpha(\mathcal{M}(\overline{\Pi}))$, for all $\alpha$ that satisfies \ref{H3}. The remaining arrows follow directly from Theorem \ref{conf-pred-diagr}.
\end{proof}

Theorem \ref{unifying-thm} is the central payoff of our categorical treatment, and therefore the greatest joy (so far!) of looking at Conformal Prediction from a categorical angle. It confirms the intuition put forth in \citet{martin2022valid} and \citet[Section 5.2]{cp-ip}, that CP is a bridge between the Bayesian, frequentist, and imprecise approaches to predictive statistical reasoning. In the category \textbf{UHCont}, the model-based Bayesian and imprecise methods, and the model-free conformal construction, yield the same $\alpha$-level prediction region,
%Within category \textbf{UHCont}, extracting the $\alpha$-level prediction region from the available data via model-based Bayesian or imprecise approaches, or a model-free conformal path, gives us the same result, 
thus showing a very profound connections between these three only apparently far apart prediction mechanisms.
%strands of predictive reasoning.
%Theorem \ref{unifying-thm} is the central payoff of our categorical treatment, and therefore the greatest joy (so far!) of looking at Conformal Prediction from a categorical angle. In the category \textbf{UHCont}, the model-based Bayesian and imprecise approaches, and the model-free conformal construction yield canonically isomorphic $\alpha$-level prediction regions, thereby formalizing the bridge among these three strands of predictive inference.

Notice also that Theorem \ref{unifying-thm} allows us to tie CP to the concept of e-posterior  \citep{grunwald2023posterior}, thus further testifying the central role of CP in modern Machine Learning.

To see this, denote by $\Delta_Y^\text{dens}$ the space of finitely additive probability measures on $Y$ that admit a density with respect to a $\sigma$-finite dominating (atomless) measure $\lambda_Y$. Since we observe the realizations $y^n=(y_1,\ldots,y_n)$ of the first $n$ terms $\mathcal{Y}_1,\ldots,\mathcal{Y}_n$ of an exchangeable process (as pointed out in Section \ref{full-cp}), the likelihood density $p(y^n \mid \theta) \equiv \ell(y^n \mid \theta)$ can be written as \citep{definetti1,definetti2}
$$\ell(y^n \mid \theta) = \int \left[ \prod_{i=1}^n h(y_i \mid \varsigma) \right] G_\theta(\text{d}\varsigma),$$
where $h(\cdot \mid \varsigma)$ is the density of an element $L_\varsigma \in \Delta_Y^\text{dens}$ (given a latent parameter $\varsigma$), and $G_\theta$ is a mixing distribution indexed by the parameter $\theta \in \Theta$. 

Consider then a credal prior set $\mathcal{P}_\text{prior}$, that is, a nonempty convex and weak$^\star$-closed (and hence also closed in the $L^1(\lambda_\Theta)$ topology) subset of $\Delta_\Theta^\text{dens}$. Let $\overline{P}$ be its upper probability, and $\overline{p}\coloneqq \sup_{P \in \mathcal{P}_\text{prior}} \frac{\text{d}P}{\text{d}\lambda_\Theta}$ be the upper prior density; The lower prior density $\underline{p}$ is defined similarly, with $\sup$ replaced by $\inf$.

\begin{proposition}[The Upper Posterior is an e-Posterior]\label{post-e-prop}
    Suppose that $\overline{P}$ is $2$-alternating, that is, $\overline{P}(A_1 \cup A_2) + \overline{P}(A_1\cap A_2) \leq \overline{P}(A_1) + \overline{P}(A_2)$, for all $A_1,A_2\in\Sigma_\Theta$, and that $\sup_{y^n \in Y^n} \ell(y^n \mid \theta)<\infty$, for all $\theta \in \Theta$. Then, the upper posterior density
    \begin{align}\label{upper-post}
        \overline{p}(\theta \mid y^n)=\frac{\ell(y^n \mid \theta)\overline{p}(\theta)}{\underline{\ell}(y^n)},
    \end{align}
where $\underline{\ell}(y^n) \coloneqq \int_\Theta \ell(y^n \mid \theta)\underline{p}(\theta) \lambda_\Theta(\mathrm{d}\theta)$, is an e-posterior \citep{grunwald2023posterior}. 
%if and only if $\int_{Y^n} \underline{\ell}(y^n) \lambda_Y^{\otimes n}(\text{d}y)\leq \overline{p}(\theta)$, where $\lambda_Y^{\otimes n}$ is the $n$-fold product of $\lambda_Y$.
\end{proposition}

\begin{proof}
    First, notice that the upper posterior density in \eqref{upper-post} is well defined if $\overline{P}$ is $2$-alternating and $\sup_{y^n \in Y^n} \ell(y^n \mid \theta)<\infty$, for all $\theta \in \Theta$, by \citet{wasserman,novel_bayes}. 

    Then, recall that an e-posterior is a function $p^\text{e}(\theta \mid y^n)=1/Z_\theta(y^n)$, where $Z_\theta(y^n)$ is an e-variable, that is, a statistic for which $\mathbb{E}_{Y^n \sim L_\theta}[Z_\theta(Y^n)] \leq 1$. Call $\lambda_Y^{\otimes n}$ the $n$-fold product of $\lambda_Y$; We have
    \begin{align*}
   \mathbb{E}_{Y^n \sim L_\theta}\left[ \frac{1}{\overline{p}(\theta \mid Y^n)} \right] &= \mathbb{E}_{Y^n \sim L_\theta}\left[ \frac{\underline{\ell}(Y^n)}{\ell(Y^n \mid \theta)\overline{p}(\theta)} \right] \\
   &= \int_{Y^n} \frac{\underline{\ell}(y^n)}{\ell(y^n \mid \theta)\overline{p}(\theta)} \ell(y^n \mid \theta) \lambda_Y^{\otimes n}(\text{d}y^n)\\
   &=\frac{1}{\overline{p}(\theta)} \int_{Y^n} \underline{\ell}(y^n) \lambda_Y^{\otimes n}(\text{d}y^n)\\
   &\leq 1 \iff \int_{Y^n} \underline{\ell}(y^n) \lambda_Y^{\otimes n}(\text{d}y^n) \leq  \overline{p}(\theta), \quad \forall \theta \in \Theta.
\end{align*} 
Now, notice that
\begin{align*}
    \int_{Y^n} \underline{\ell}(y^n) \lambda_Y^{\otimes n}(\text{d}y^n) &= \int_{Y^n} \int_\Theta \ell(y^n \mid \theta)\underline{p}(\theta) \lambda_\Theta(\mathrm{d}\theta) \lambda_Y^{\otimes n}(\text{d}y^n)\\
    &=\int_\Theta \underline{p}(\theta) \int_{Y^n} \ell(y^n \mid \theta) \lambda_Y^{\otimes n}(\text{d}y^n) \lambda_\Theta(\mathrm{d}\theta) \\
    &=\int_\Theta \underline{p}(\theta) \lambda_\Theta(\mathrm{d}\theta),
\end{align*}
where the last-but-one equality comes from Fubini-Tonelli, and the last one comes from $\ell(y^n \mid \theta)$ being a proper density. Hence, the upper posterior density $\overline{p}(\theta \mid y^n)$ is an e-posterior if and only if
$$\int_\Theta \underline{p}(\theta) \lambda_\Theta(\mathrm{d}\theta) \leq \overline{p}(\theta), \quad \forall \theta \in \Theta.$$
But this corresponds to the coherence condition in \citet[Section 2.5]{walley1991statistical}, which is always met when $\mathcal{P}_\text{prior} \neq \emptyset$. The proof is then concluded.
\end{proof}

A consequence of Proposition \ref{post-e-prop} is that, if 
\begin{align}\label{eq-cond-e-cp}
    \overline{\Pi}(A) \equiv \overline{\Pi}_{(y^n,\psi)}(A)=\int_A \underbrace{\int_\Theta \ell(y_{n+1} \mid \theta) \overline{p}(\theta \mid y^n) \lambda_\Theta(\text{d}\theta)}_{\eqqcolon \overline{p}(y_{n+1} \mid y^n)}\lambda_Y(\text{d}y), \quad \forall A\in \Sigma_Y,
\end{align}
then the $\alpha$-level Imprecise Highest Density Region $\IHDR_\alpha(\mathcal{M}(\overline{\Pi}))$ in Theorem \ref{unifying-thm} is a prediction region that is associated with an e-posterior. The equality in \eqref{eq-cond-e-cp} only holds if the upper posterior predictive density $\overline{p}(y_{n+1} \mid y^n)$ collapses to a point mass.

\begin{proposition}[Coincidence of Upper Probabilities implies Degeneracy]\label{prop-degen}
If \eqref{eq-cond-e-cp} holds, then then there exist elements $y^\ast\in Y$ and $\theta^\ast\in \Theta$ such that
\[
  \overline{p}(y_{n+1} \mid y^n)=\delta_{y^\ast}(y)\quad(\lambda_Y\text{-a.s.}),
  \qquad
  \overline p\!\left(\theta\mid y^{n}\right)=\delta_{\theta^\ast}(\theta),
  \qquad
  \ell\!\left(y\mid\theta^\ast\right)=\delta_{y^\ast}(y).
\]
\end{proposition}

\begin{proof}
Let $\overline{\Pi}_{\mathrm B}(A)\coloneqq \int_A \overline{p}(y_{n+1} \mid y^n) \lambda_Y(\text{d}y)$, for all $A\in\Sigma_Y$.

\textbf{Step 1. Maxitivity versus additivity.}
For disjoint measurable sets $A,B\in \Sigma_Y$,
\[
  \overline{\Pi} (A\cup B)
  =\max\{\overline{\Pi} (A),\overline{\Pi} (B)\},
  \qquad
  \overline{\Pi}_{\mathrm B}(A\cup B)
  =\overline{\Pi}_{\mathrm B}(A)+\overline{\Pi}_{\mathrm B}(B),
\]
because $\overline{\Pi} $ is \emph{maxitive} while
$\overline{\Pi}_{\mathrm B}$ is \emph{additive}.
Equality \eqref{eq-cond-e-cp} therefore forces
\begin{align}\label{force}
     \max\{\overline{\Pi}_{\mathrm B}(A),\overline{\Pi}_{\mathrm B}(B)\}
  \;=\;
  \overline{\Pi}_{\mathrm B}(A)+\overline{\Pi}_{\mathrm B}(B).
\end{align}


\textbf{Step 2.  A $0$-$1$ law for $\overline{\Pi}_{\mathrm B}$.}
If $0<\overline{\Pi}_{\mathrm B}(A)<1$ and
$0<\overline{\Pi}_{\mathrm B}(B)<1$ with $A\cap B=\emptyset$,
then \eqref{force} is impossible because
$\max\{x,y\}<x+y$ for $x,y\in(0,1)$.  
Hence for \emph{every} measurable $A$, it must be that
\begin{align}\label{force2}
    \overline{\Pi}_{\mathrm B}(A)\in\{0,1\}.
\end{align}

\textbf{Step 3.  Concentration on a single point.}
Define the set
$S=\{y\in Y:\overline{p}(y_{n+1} \mid y^n)>0\}$.  
If $\lambda_Y(S)=0$ then $\overline{\Pi}_{\mathrm B}\equiv0$, contradicting
$\overline{\Pi}_{\mathrm B}(Y)=1$.
Thus $\lambda_Y(S)>0$ and \eqref{force2} with $A=S$ gives
$\overline{\Pi}_{\mathrm B}(S)=1$.  
Now take \emph{any} two disjoint measurable subsets
$A,B\subseteq S$ with positive $\lambda_Y$-measure.
By \eqref{force2} at most one of them can have $\overline{\Pi}_{\mathrm B}=1$,
so we must have $\overline{\Pi}_{\mathrm B}(A)=\overline{\Pi}_{\mathrm B}(B)=0$.
This is possible only if \emph{every} measurable subset of $S$
with positive $\lambda_Y$-measure has $\overline{\Pi}_{\mathrm B}(\cdot)=1$, which forces
$S$ to be a $\lambda_Y$-null neighborhood of a \emph{single point} $y^\ast$
(up to $\lambda_Y$-null sets).  Hence
$\overline{\Pi}_{\mathrm B}$ (and therefore $\overline{p}(y_{n+1} \mid y^n)$) is the point mass
$\delta_{y^\ast}$, proving the first claim.

\textbf{Step 4.  Collapse of the posterior and the likelihood.}
Because
\[
  \overline{p}(y_{n+1} \mid y^n)
  =\int_{\Theta}\ell(y\mid\theta)\,
         \overline p(\theta\mid y^{n})\,
         \lambda_\Theta(\mathrm d\theta)
  =\delta_{y^\ast}(y)\quad(\lambda_Y\text{-a.s.}),
\]
the mixture representation can hold only if
$\overline p(\theta\mid y^{n})=\delta_{\theta^\ast}(\theta)$
and $\ell(y\mid\theta^\ast)=\delta_{y^\ast}(y)$.
\end{proof}


Although Proposition \ref{prop-degen} shows that the equality in \eqref{eq-cond-e-cp} holds only under very restrictive conditions, it nevertheless hints at the possibility of an arrow in the diagram of Theorem \ref{unifying-thm} connecting $Y^n \times \Delta_\Theta^\text{dens}$ and $\mathscr{C}$ via an e-posterior-based method.\footnote{To be precise, for such an arrow to be a morphism of $\mathbf{UHCont}$, we need to substitute $Y^n \times \Delta_\Theta^\text{dens}$ with $Y^n \times \mathscr{C}_\Theta^\text{dens}$, where $\mathscr{C}_\Theta^\text{dens}$ denotes the set of convex and weak$^\star$-closed subsets of $\Delta_\Theta^\text{dens}$. In that case, $\mathsf{BCP}$ and $\mathsf{QUANT}_\alpha$ both take as input the pair $(y^n,\{P\})$, where $\{P\} \subset \mathcal{P}_\text{prior}$.} A deeper study of the broader interest of the e-posterior approach to Conformal Prediction within a category theory framework 
%proposed in this paper 
is left for future research.





\section{Conformal Prediction Regions as Images of the Imprecise Highest Density Region Functor}\label{impr-prob-sec}

In this section, we see how the correspondence $\IHDR_\alpha$ can be seen as a functor between two well-known categories. As a consequence, the Conformal Prediction Region can be seen as a functor image.





\newcommand{\M}{\mathcal{M}}
\newcommand{\Mone}{\mathcal{M}_{1}}
\newcommand{\Mtwo}{\mathcal{M}_{2}}
\newcommand{\Mthr}{\mathcal{M}_{3}}
\newcommand{\B}[1]{B_{#1}^{\alpha}}
\renewcommand{\IHDR}{\mathsf{IHDR}_{\alpha}}
\newcommand{\prob}{\Delta_Y}



\begin{theorem}[Functoriality of the $\,\alpha$-IHDR]\label{thm:IHDRfunctor}
	Let $(\Y,\SigY)$ be a measurable space, and let $\prob$ be the set of all
	finitely additive probability measures on $\SigY$ endowed with the weak$^{*}$ topology.
	Let
	\[
	\Ccal \;\coloneqq\;\bigl\{\,
	    \M\subseteq\prob : \M \text{ is convex and weak$^{*}$-closed}
	  \bigr\},
	\]
	and regard both $\Ccal$ and $\SigY$ as (pre-)categories whose only
	morphisms are inclusions ``$\subseteq$''.  
	Fix $\alpha\in[0,1]$.  For $\M\in\Ccal$, define
	\[
	   \B{\M}
	   \;\coloneqq\;
	   \bigcap\Bigl\{
	       A\in\SigY :
	       \underline{P}_\mathcal{M}(A)\,\ge 1-\alpha
	   \Bigr\}.
	\]
	Set
	\[
	    \IHDR:\Ccal\rightarrow\SigY,
	    \quad
	    \M\mapsto\B{\M},
	    \qquad
	    \IHDR(\Mone\hookrightarrow\Mtwo)\coloneqq\B{\Mone}\hookrightarrow\B{\Mtwo}.
	\]
	Then, $\IHDR$ is a covariant functor.
\end{theorem}

\begin{proof}
	\textbf{(i) Objects.}
	Every $A$ in the defining intersection for $\B{\M}$ is measurable; Arbitrary
	intersections of sets in $\SigY$ remain in $\SigY$, hence
	$\B{\M}\in\SigY$.  Thus $\IHDR$ maps objects of~$\Ccal$ to objects of~$\SigY$.


	\textbf{(ii) Morphisms (monotonicity).}
	Suppose $\Mone\subseteq\Mtwo$.  
	Let $y\in\B{\Mone}$.  If $y\notin\B{\Mtwo}$, then by definition of
	$\B{\Mtwo}$, there exists $A\in\SigY$ such that
	\[
	  \underline{P}_{\mathcal{M}_2}(A)\;\ge 1-\alpha, 
	  \qquad y\notin A.
	\]
	Because $\Mone\subseteq\Mtwo$, the same inequality holds with $\Mtwo$
	replaced by~$\Mone$, so $A$ belongs to the family of sets whose intersection
	defines $\B{\Mone}$.  Consequently $y\in A$, contradicting $y\notin A$.
	Therefore $y\in\B{\Mtwo}$, and
	\(
	      \B{\Mone}\subseteq\B{\Mtwo}.
	\)
	Hence $\IHDR$ maps the arrow $\Mone\hookrightarrow\Mtwo$ to the arrow
	$\B{\Mone}\hookrightarrow\B{\Mtwo}$.


	\textbf{(iii) Identities.}
	For each $\M\in\Ccal$, the identity morphism is $\M\hookrightarrow\M$.
	Since inclusion is reflexive, $\B{\M}\hookrightarrow\B{\M}$ is the identity
	in $\SigY$, so $\IHDR(\mathrm{id}_{\M})=\mathrm{id}_{\B{\M}}$.


	\textbf{(iv) Composition.}
	Given $\Mone\subseteq\Mtwo\subseteq\Mthr$, the composite morphism in $\Ccal$
	is $\Mone\hookrightarrow\Mthr$.  By monotonicity,
	\(
	   \B{\Mone}\subseteq\B{\Mtwo}\subseteq\B{\Mthr},
	\)
	so
    \begin{align*}
        \IHDR(\Mone\hookrightarrow\Mthr)
	        =\B{\Mone}\hookrightarrow\B{\Mthr}
	        &=(\B{\Mtwo}\hookrightarrow\B{\Mthr})
	              \circ(\B{\Mone}\hookrightarrow\B{\Mtwo})\\
	        &=\IHDR(\Mtwo\hookrightarrow\Mthr)
	              \circ\IHDR(\Mone\hookrightarrow\Mtwo).
    \end{align*}


Since $\IHDR$ respects objects, morphisms, identities and
	composition, it is a covariant functor.
\end{proof}















