\begin{theorem}[Vietoris Monad on \(\mathbf{UHCont}^{\mathrm{cH}}_\text{c}\)]\label{vietoris-monad}
There exists a monad \((T, \eta_X, \nu_X)\) on the category \(\mathbf{UHCont}^{\mathrm{cH}}_\text{c}\), where
\begin{itemize}
  \item \(T(X) \coloneqq \mathcal{K}(X)\), the space of compact subsets of $X$, endowed with the Vietoris topology;
  \item For a morphism \(\Phi: X \rightrightarrows Y\), define \(T(\Phi): \mathcal{K}(X) \rightrightarrows \mathcal{K}(Y)\) by
  \[
  T(\Phi)(K)\;\coloneqq\;
   \bigl\{\,L\in\mathcal K(Y)\;:\;
           L\subset\Phi[K]\bigr\},
   \quad
   \Phi[K]\coloneqq\bigcup_{x\in K}\Phi(x);
  \]
  \item The unit \(\eta_X: X \rightarrow \mathcal{K}(X)\) is given by \(\eta_X(x) = \{x\}\);
  \item The multiplication \(\nu_X: \mathcal{K}(\mathcal{K}(X)) \rightarrow \mathcal{K}(X)\) is defined by
  \[
  \nu_X(\mathcal{A}) \coloneqq \bigcup_{A \in \mathcal{A}} A,
  \]
  where $\mathcal{K}(\mathcal{K}(X))$ is the hyperspace of nonempty, compact collections of compact subsets of $X$.
\end{itemize}
\end{theorem}

\begin{proof}
We verify the monad axioms.

\textbf{(1) Well-definedness.}
\begin{itemize}
  \item \(T(X)\) is a compact Hausdorff space (classical result).
  \item We now verify that \(T(\Phi)\) is a morphism in \(\mathbf{UHCont}^{\mathrm{cH}}_\text{c}\). By Lemma \ref{lem:CG}, \(\Phi\) has a closed graph; It also has compact values. It follows from standard results on the Vietoris topology \citep{michael1951} that
\begin{itemize}
  \item The map \(K \mapsto T(\Phi)(K)\) is upper hemicontinuous;
  \item The values \(T(\Phi)(K)\) are nonempty, compact subsets of \(\mathcal{K}(Y)\), hence compact in the Vietoris topology.
 % \item The graph of \(T(\Phi)\) is closed.
\end{itemize}
Thus, \(T(\Phi)\) is again a compact-valued, upper hemicontinuous correspondence. Finally, for morphisms $\Phi:X\!\rightrightarrows\!Y$ and
$\Psi:Y\!\rightrightarrows\!Z$ we can see that
\[
L\subset(\Psi\circ\Phi)[K]
\iff
\exists M\subset\Phi[K]\;\bigl(L\subset\Psi[M]\bigr),
\]
hence $T(\Psi\circ\Phi)=T(\Psi)\circ T(\Phi)$; Thus $T$ is indeed a functor.
% If \(\Phi: X \rightrightarrows Y\) is a continuous correspondence, then \(T(\Phi)\) is upper hemicontinuous with closed graph \citep[Theorem 17.11]{aliprantis}. The image sets are nonempty compact subsets, because \(\Phi(x)\) is compact and nonempty.
\end{itemize}

\textbf{(2) Naturality of \(\eta_X\).}  
For each \(x \in X\), \(\eta_X(x) = \{x\}\) is a continuous map (singletons are closed in compact Hausdorff spaces and form a continuous embedding into \(\mathcal{K}(X)\)), and hence upper hemicontinuous and compact-valued.
%clearly a compact singleton. The map \(x \mapsto \{x\}\) is continuous from \(X\) into \(\mathcal{K}(X)\) under the Vietoris topology.

\textbf{(3) Naturality of \(\nu_X\).}  
Given \(\mathcal{A} \in \mathcal{K}(\mathcal{K}(X))\), \(\nu_X(\mathcal{A}) = \bigcup \mathcal{A}\) is continuous in the Vietoris topology,\footnote{For basic opens $\langle U_1,\dots,U_m\rangle\subset\mathcal{K}(X)$ we have
\(
  \nu_X^{-1}\!\langle U_1,\dots,U_m\rangle
  =\bigl\langle\,
       \langle U_1\rangle,\dots,\langle U_m\rangle,\,
       \langle U_1\cup\cdots\cup U_m\rangle
    \bigr\rangle,
\)
which is open in $\mathcal{K}(\mathcal{K}(X))$, see Definition \ref{vietoris}.} and hence upper hemicontinuous and compact-valued.

%is compact in \(X\) since it is a finite union of compact subsets. The union map is continuous in the Vietoris topology by classical results on hyperspace topologies.

%This map is continuous in the Vietoris topology and hence upper hemicontinuous and closed-valued.




\textbf{(4) Monad laws.}
\begin{itemize}
  \item Left unit: \(\nu_X \circ T(\eta_X)(K) = \bigcup_{x \in K} \eta_X(x) = \bigcup_{x \in K} \{x\} = K\).
  \item Right unit: \(\nu_X \circ \eta_{T(X)}(K) = \nu_X(\{K\}) = K\).
  \item Associativity: \(\nu_X \circ T(\nu_X) = \nu_X \circ \nu_{T(X)}\) holds due to the associativity of set union.
\end{itemize}
Therefore, \((T, \eta_X, \nu_X)\) is a monad on \(\mathbf{UHCont}^{\mathrm{cH}}_\text{c}\).
\end{proof}


