\begin{definition}[Structure $\mathbf{WMeas}_\text{uc}^\text{c}$]\label{struct-4}
Define a structure $\mathbf{WMeas}_\text{uc}^\text{c}$ as follows,
\begin{itemize}
    \item \textbf{Objects:} {\em Compact} Polish spaces $X$ equipped with their Borel $\sigma$-algebra $\mathcal{B}(X)$.
    \item \textbf{Morphisms:} Uniformly compact-valued, weakly measurable correspondences $\Phi: X \rightrightarrows Y$.
\end{itemize}
\end{definition}

It is immediate to see that structure $\mathbf{WMeas}_\text{uc}^\text{c}$ is a subcategory of $\mathbf{WMeas}_\text{uc}$, as its objects need to be compact as well. We now show that it admits a monad.

Let $X$ be an object of $\mathbf{WMeas}_\text{uc}^\text{c}$. Define an endofunctor $\mathcal{K} \colon \mathbf{WMeas}_\text{uc}^\text{c}\to\mathbf{WMeas}_\text{uc}^\text{c}$, a unit transformation 
\(\eta_X\equiv \eta : \mathrm{Id}_{\mathbf{WMeas}_\text{uc}^\text{c}} \!\Rightarrow\! \mathcal{K}
\)
and a multiplication
\(
\nu_X \equiv \nu : \mathcal{K}\!\circ\! \mathcal{K} \Rightarrow \mathcal{K}
\)
by
\[
\begin{aligned}
\mathcal{K}(X)            &\coloneqq  \bigl\{ C\subseteq X : C\neq\emptyset,\; C\text{ compact} \bigr\},\\
\mathcal{K}(\Phi)(C)      &\coloneqq  \bigl\{\,\overline{\Phi[C]}\bigr\}, \quad C\in \mathcal{K}(X),\\
\eta_X(x)                 &\coloneqq  \bigl\{\,\{x\}\bigr\}, \quad x\in X,\\
\nu_X(\mathcal C)         &\coloneqq  \bigl\{\bigcup_{C\in\mathcal C} C\bigr\}, \quad \mathcal C\in \mathcal{K}\!\bigl(\mathcal{K}(X)\bigr).
\end{aligned}
\]

\begin{theorem}[Vietoris monad on $\mathbf{WMeas}_{\mathrm{uc}}^{\mathrm{c}}$]
\label{thm:vietoris-monad}
The triple $(\mathcal{K},\eta,\nu)$ satisfies the monad axioms inside $\mathbf{WMeas}_\text{uc}^\text{c}$.
Moreover, $\mathcal{K}(X)\not\cong X$ for any $X$ other than a singleton, so the monad is non-trivial.
\end{theorem}

\begin{proof}
\textbf{1. $\mathcal{K}$ is an endofunctor.}
\begin{enumerate}
  \item \emph{(Objects).} For any compact Polish space $X$, $\mathcal{K}(X)$ endowed with the Vietoris 
  %(Hausdorff) 
  topology is again compact Polish; Its Borel $\sigma$-algebra makes $\mathcal{K}(X)$ an object of the category $\mathbf{WMeas}_\text{uc}^\text{c}$.

  \item \emph{(Morphisms).}  
        Given $\Phi:X\rightrightarrows Y$ in~$\mathbf{WMeas}_\text{uc}^\text{c}$, each fiber of $\mathcal{K}(\Phi)$ is a singleton $\{ \overline{\Phi[C]} \}$, hence compact; The common compact bound is $K_\Phi$, the one already bounding~$\Phi$.  
        Weak measurability follows because inverse images of Vietoris subbasic open sets can be expressed via the measurable “hit’’ and “miss’’ sets of~$\Phi$ (studied below).  
        Functoriality is immediate,
        \[
        \mathcal{K}(\operatorname{id}_X)=\operatorname{id}_{\mathcal{K}(X)}, 
        \qquad
        \mathcal{K}(\Psi\circ\Phi)=\mathcal{K}(\Psi)\circ \mathcal{K}(\Phi),
        \]
        since closures commute with unions in compact spaces.
\end{enumerate}

\textbf{2. The unit $\eta$.}
For every $X$, $\eta_X$ has compact fibres $\{x\}$, is uniformly bounded by $\mathcal{K}(X)$, and is weakly measurable because
\(
\eta_X^{u}(\langle U\rangle) \coloneqq \{x \in X : \eta_X(x) \cap \langle U\rangle \neq \emptyset\} =U\in\mathcal B(X)
\)
for each open $U\subseteq X$.  
Naturality of~$\eta$ is trivial:
\(
\mathcal{K}(\Phi)\circ\eta_X=\eta_Y\circ\Phi
\)
for every $\Phi:X\rightrightarrows Y$.

\textbf{3. The multiplication $\nu$.}
For $\mathcal C\in \mathcal{K}\bigl(\mathcal{K}(X)\bigr)$, the union $\bigcup_{C\in\mathcal C}C$ is compact (union of a compact family of compact subsets in a compact space).  
Thus $\nu_X(\mathcal C)\in \mathcal{K}(X)$, giving well-defined singleton fibres.  
Uniform boundedness is by $\mathcal{K}(X)$ itself.  
Weak measurability is checked on subbasic Vietoris open sets:

\begin{itemize}
   \item \emph{Hit part:}  
         $\nu_X^{-1}\!\langle U\rangle
         =\bigl\{\mathcal C : \exists C\in\mathcal C,\;C\cap U\neq\emptyset\bigr\},
         $
         which is open in the Vietoris topology of $\mathcal{K}(\mathcal{K}(X))$.
   \item \emph{Miss part:}  
         $\nu_X^{-1}\langle U_1,\dots,U_m \rangle
         =\bigl\{\mathcal C : \textstyle\bigcup_{C\in\mathcal C} C \subseteq U_1\cup\dots\cup U_m,\;C\cap U_i\neq\emptyset \text{ } forall i\bigr\},
         $
         again Vietoris-open.
\end{itemize}

Naturality of~$\nu$ follows from
\(
\nu_Y \circ \mathcal{K}(\mathcal{K}(\Phi)) 
       = \mathcal{K}(\Phi) \circ \nu_X
\),
since direct images commute with unions and closure.

\textbf{4. Monad laws.}
For every $X$ the diagrams
\[
\mathcal{K}^3(X)\;\xrightarrow{\mathcal{K}\nu_X}\;\mathcal{K}^2(X)\;\xrightarrow{\nu_X}\;\mathcal{K}(X)
\quad=\quad
\mathcal{K}^3(X)\;\xrightarrow{\nu_{\mathcal{K}(X)}}\;\mathcal{K}^2(X)\;\xrightarrow{\nu_X}\;\mathcal{K}(X)
\]
and
\begin{align*}
    \mathcal{K}(X)\;\xrightarrow{\mathcal{K}\eta_X}\;\mathcal{K}^2(X)\;\xrightarrow{\nu_X}\;\mathcal{K}(X)
\quad&=\quad
\mathcal{K}(X)\;\xrightarrow{\mathrm{id}}\;\mathcal{K}(X)\\
&=\quad
\mathcal{K}(X)\;\xrightarrow{\eta_{\mathcal{K}(X)}}\;\mathcal{K}^2(X)\;\xrightarrow{\nu_X}\;\mathcal{K}(X)
\end{align*}
commute because unions of singletons reproduce the original compact set, and unions are associative.

\textbf{5. Non-triviality.}
If $X$ has at least two points, then $\mathcal{K}(X)$ is strictly larger than~$X$ under any continuous, measure-compatible identification; Hence $(\mathcal{K},\eta,\nu)$ is not isomorphic to the identity monad.
\end{proof}



















