    T(\Phi)(F) \coloneqq \{ \overline{\Phi(F)} \}, \quad \text{where } \Phi(F) \coloneqq \bigcup_{x \in F} \Phi(x);
    \]
    \item The unit $\eta_X: X \rightarrow \mathtt{F}(X)$, $x \mapsto \{x\}$;
    \item The multiplication $\nu_X: \mathtt{F}(\mathtt{F}(X)) \rightarrow \mathtt{F}(X)$, $\nu_X(\mathfrak{F}) \coloneqq \overline{\bigcup_{F \in \mathfrak{F}} F}$.\footnote{Here we denote by $\mathtt{F}(\mathtt{F}(X))$ the space of nonempty closed subsets of nonempty closed subsets of $X$.}
\end{itemize}
\end{theorem}

\begin{proof}

\textbf{(1) Measurability of $\eta_X$ and $\nu_X$.}
\begin{itemize}
    \item $\eta_X$ is measurable. The map $x \mapsto \{x\}$ is measurable because $\{ F : F \cap U \neq \emptyset \}$ is open in the Effros structure.
    \item $\nu_X$ is measurable. Since both union and closure are Borel measurable operations on $\mathtt{F}(X)$, the composition $\nu_X(\mathfrak{F}) = \overline{ \bigcup \mathfrak{F} }$ is measurable.
\end{itemize}

\textbf{(2) Monad laws.}
\begin{itemize}
    \item {Left unit:} For $F \in \mathtt{F}(X)$,
    \[
    \nu_X(T(\eta_X)(F)) = \nu_X(\{ \{x\} : x \in F \}) = \overline{\bigcup_{x \in F} \{x\}} = \overline{F} = F.
    \]
    \item {Right unit:} For $F \in \mathtt{F}(X)$,
    \[
    \nu_X(\eta_{\mathtt{F}(X)}(F)) = \nu_X(\{F\}) = \overline{F} = F.
    \]
    \item {Associativity:} For $\mathfrak{G} \in \mathtt{F}(\mathtt{F}(\mathtt{F}(X)))$, we have\footnote{Here we denote by $\mathtt{F}(\mathtt{F}(\mathtt{F}(X)))$ the space of nonempty closed subsets of nonempty closed subsets of nonempty closed subsets of $X$.}
    \[
    \nu_X(T(\nu_X)(\mathfrak{G})) = \overline{ \bigcup_{ \mathfrak{F} \in \mathfrak{G} } \nu_X(\mathfrak{F}) }
    = \overline{ \bigcup_{\mathfrak{F} \in \mathfrak{G}} \bigcup_{F \in \mathfrak{F}} F }
    = \overline{ \bigcup_{F \in \bigcup \mathfrak{G}} F }
    = \nu_X( \nu_{\mathtt{F}(X)}(\mathfrak{G}) ).
    \]
\end{itemize}

Thus, $(T, \eta_X, \nu_X)$ satisfies the monad axioms and defines a monad on the category.
\end{proof}
\fi 







The monad that we found on the category $\mathbf{WMeas}_\text{uc}^\text{c}$ is again the classic Vietoris monad, adapted to the category of compact Polish spaces (with their Borel $\sigma$-algebra), with uniformly compact-valued, weakly measurable correspondences. It is immediate to see that Theorem \ref{conf-pred-diagr2} still holds for $\mathbf{WMeas}_\text{uc}^\text{c}$, since we simply require the extra assumption that the objects are {\em compact} measurable Polish spaces.





