\section{Category $\mathbf{LHCont}$}\label{lhc-appendix}


The structure $\mathbf{LHCont}$ defined analogously to $\mathbf{UHCont}$, with upper hemicontinuous correspondences substituted by lower hemicontinuous correspondences, is a category as well.



\begin{proposition}[Structure $\mathbf{LHCont}$ is a Category]\label{def:LHCont}
The structure $\mathbf{LHCont}$ whose components are
\begin{enumerate}
  \item \textbf{Objects:} Topological spaces $(X,\tau_X)$,
  \item \textbf{Morphisms:} Lower hemicontinuous correspondences (lhc)
        $\Phi:X\rightrightarrows Y$,
\end{enumerate}
defines a category.
\end{proposition}


\begin{proof}
We verify the category axioms.

\noindent\textbf{(1) Identity morphisms.} For every space $X$, define
\[
  \operatorname{id}_X:X\rightrightarrows X,\qquad
  \operatorname{id}_X(x)=\{x\}.
\]
Given an open $V\subseteq X$,
\(
  \{x: \operatorname{id}_X(x)\cap V\neq\emptyset\}=V,
\)
which is open; Hence $\operatorname{id}_X$ is lower hemicontinuous.

\textbf{(2) Associativity and identity laws.}\;
For correspondences,  
\[
  \Theta\circ(\Psi\circ\Phi)=
  (\Theta\circ\Psi)\circ\Phi
\]
because both sides equal
\(
  x\mapsto\bigcup_{y\in\Phi(x)}\bigcup_{z\in\Psi(y)}\Theta(z).
\)
Unit laws follow from
\(
  \Phi\circ\operatorname{id}_X=\Phi=\operatorname{id}_Y\circ\Phi,
\)
since inserting singletons leaves the unions unchanged.

\textbf{(3) Closure under composition} Let $\Phi:X\rightrightarrows Y$ and $\Psi:Y\rightrightarrows Z$ be lhc correspondences.
Their usual set-valued composition is
\[
  (\Psi\circ\Phi)(x)\;\coloneqq\;\bigcup_{y\in\Phi(x)}\Psi(y)\subseteq Z.
\]
Fix an open set $V\subseteq Z$ and a point $x_0\in X$ with
$(\Psi\circ\Phi)(x_0)\cap V\neq\emptyset$.  
Choose $y_0\in\Phi(x_0)$ such that $\Psi(y_0)\cap V\neq\emptyset$.

Because $\Psi$ is lhc, there exists an open neighborhood $W\subseteq Y$ of $y_0$
satisfying
\begin{equation}\label{interm-1-ni}
    \forall\,y\in W,\quad \Psi(y)\cap V\neq\emptyset.
\end{equation}

Since $\Phi(x_0)\cap W\neq\emptyset$ and $\Phi$ is lhc,
there is an open neighborhood $U\subseteq X$ of $x_0$ with
\begin{equation*}
    \forall\,x\in U,\quad \Phi(x)\cap W\neq\emptyset.
\end{equation*}

For any $x\in U$, pick $y\in\Phi(x)\cap W$.  
By \eqref{interm-1-ni} we have $\Psi(y)\cap V\neq\emptyset$, so
$(\Psi\circ\Phi)(x)\cap V\neq\emptyset$.
Thus
\(
  \{x: (\Psi\circ\Phi)(x)\cap V\neq\emptyset\}
\)
contains $U$ and is open; hence $\Psi\circ\Phi$ is lhc.





Hence objects, morphisms, identities and composition satisfy
all category axioms; $\mathbf{LHCont}$ is thus a category.
\end{proof}



The previous results inspire the study of the commutative Conformal prediction diagram. 


Let $n\in\mathbb{N}$ be fixed, and consider the following conditions.



\begin{itemize}
  \item \textbf{(Y-cmp).} $\Y$ is a \emph{compact Hausdorff} topological space.  Denote by $\mathcal{B}(\Y)$ its Borel $\sigma$--algebra.
  \item \textbf{(\ensuremath{\mu}\textbf{-full}).} $\mu$ is a \emph{finite}, \emph{full\,--support} Borel measure on $\Y$ (i.e.~$\mu(U)>0$ for every non-empty open $U\subset \Y$).
  \item \textbf{(\ensuremath{\psi}\textbf{-cts}).} $\F$ is a family of \emph{jointly continuous} functions $\psi: \Y^{n}\times \Y\to\mathbb{R}$, endowed with the \emph{compact-open} topology.
\end{itemize}

%Notice that \textbf{(Y-cmp)} and \textbf{(\ensuremath{\psi}\textbf{-cts})} are the same conditions that we require in Theorem \ref{conf-pred-uhc}. 
Define
\[
  G(\alpha,y^{n},\psi,y)\;\coloneqq\;\frac{1}{n+1}\sum_{i=1}^{n+1}
      \mathbbm{1}\bigl[\psi(y^{n+1}_{-i},y_{i})\ge \psi(y^{n+1}_{-(n+1)},y)\bigr],
\]
so the Full CP correspondence $\kappa$ is such that
\[
  \kappacorr(\alpha,y^{n},\psi)\coloneqq\bigl\{y\in\Y: G(\alpha,y^{n},\psi,y)>\alpha\bigr\}.
\]

Now, recall that $\Prob$ is the space of \emph{finitely additive} probability measures on $(\Y,\mathcal B(\Y))$, equipped with the weak$^\star$ topology. Call $\Prob^\text{dens}$ the subset of $\Prob$ whose elements have a \emph{continuous} density $f_{P}$ with respect to $\mu$,
$P(B)=\int_{B}f_{P}\,d\mu$ for all Borel $B$ \citep{bell1988separation}.


Define the credal set correspondence
\[
  \CRED(\alpha,y^{n},\psi)\coloneqq\left\lbrace{P\in\Prob^\text{dens} : P(A)\le \sup_{y\in A}G(\alpha,y^{n},\psi,y),\;\forall A\in\mathcal{B}(\Y)}\right\rbrace.
\]

It is easy to see that $\CRED(\alpha,y^{n},\psi)$ is a credal set (i.e. a convex and weak$^\star$ closed subset of $\Prob^\text{dens}$, which we assume nonempty) whose upper envelope is given by the possibility function $\overline{\Pi}(A)= \sup_{y\in A}G(\alpha,y^{n},\psi,y)$, for all $A\in\mathcal{B}(Y)$.

Let $\Ccal$ be the collection of weak$^\star$ closed, convex subsets $\mathcal M\subset\Prob^\text{dens}$, and equip it with the \emph{sup-norm Hausdorff metric}
        \[
          d_{H}(\mathcal M_{1},\mathcal M_{2})
          \coloneqq\max\Bigl\{\sup_{P\in\mathcal M_{1}}\inf_{Q\in\mathcal M_{2}}\|f_{P}-f_{Q}\|_{\infty},
                        \sup_{Q\in\mathcal M_{2}}\inf_{P\in\mathcal M_{1}}\|f_{P}-f_{Q}\|_{\infty}\Bigr\}.
        \]

For $\mathcal{M}\in\Ccal$ write $g_{\mathcal M}(y)\coloneqq\inf_{P\in\mathcal M}f_{P}(y)$ and define
\[
  k_{\mathcal M}\;\coloneqq\;\sup\Bigl\{t\ge 0 : \mu\bigl(\{y\in \Y : g_{\mathcal M}(y)\ge t\}\bigr)\ge 1-\alpha\Bigr\}.
\]

We now use the technology introduced above to redefine the IHDR correspondence as
\[
  \IHDR(\mathcal M) \equiv \IHDR(\alpha,\mathcal M)\coloneqq\bigl\{y\in\Y : g_{\mathcal M}(y)\ge k_{\mathcal M}\bigr\}.
\]

Let $S_{n+1}\coloneqq\{0,\tfrac{1}{n+1},\dots,\tfrac{n}{n+1}\}$.  We call the following the {\bf (Gap)} condition.
\begin{enumerate}
  \item \emph{either}\, $\alpha\notin S_{n+1}$,
  \item \emph{or}
        for every $(\alpha,y^{n},\psi)$ and $y\in\kappacorr(\alpha,y^{n},\psi)$ there exists $\varepsilon>0$ such that
        $G(\alpha,y^{n},\psi,y)\ge \alpha+\varepsilon$. 
        %(and analogously for $\CRED$ and $\IHDR$).
\end{enumerate}

We then have the following two auxiliary lemmas.

\begin{lemma}[Upper semicontinuity of $G$]\label{lem:u.s.c.}
The map $(\alpha,y^{n},\psi,y)\mapsto G(\alpha,y^{n},\psi,y)$ is upper semicontinuous on the product space $[0,1]\times\Y^{n}\times\F\times\Y$.
\end{lemma}

\begin{proof}
Fix $(\bar\alpha,\bar y^{n},\bar\psi,\bar y)$.  Continuity of $\bar\psi$ implies each indicator $\mathbbm{1}[\bar\psi(\cdot)\ge \bar\psi(\cdot)]$ is upper semicontinuous; A finite sum preserves that property, so $G$ is u.s.c. in $(y^{n},\psi, y)$. The extra $\alpha$ coordinate is irrelevant.
\end{proof}

\begin{lemma}[Lower semicontinuity of the infimum density]\label{lem:lsc-gM}
For every $\mathcal M\in\Ccal$, the function $g_{\mathcal M}:\Y\to\mathbb R$ is lower semicontinuous.  Moreover, $(\alpha,\mathcal M)\mapsto k_{\mathcal M}$ is continuous on $[0,1]\times\Ccal$.
\end{lemma}

Finally, the sufficient conditions for all three correspondences to be lhc.


\begin{proof}
Lower semicontinuity of $g_{\mathcal M}$ follows because it is the infimum of a family of continuous functions.  For the continuity of $k_{\mathcal M}$, take $(\alpha_{n},\mathcal M_{n})\to(\bar\alpha,\bar{\mathcal M})$.  By dominated convergence (densities are bounded and $\mu$ finite) and the continuity of $g_{\mathcal M}$ in $\mathcal M$ under $d_{H}$, the integrals that define $k_{\mathcal M_{n}}$ converge to the integral that defines $k_{\bar{\mathcal M}}$.
\end{proof}


\begin{proposition}[Lower Hemicontinuity of $\kappa$, $\CRED$, and $\IHDR$]\label{prop:LHC}
Under \textbf{(Y-cmp)}, \textbf{(\ensuremath{\mu}-full)}, \textbf{(\ensuremath{\psi}-cts)} and the \textbf{(Gap)} condition, the correspondences
\[
  \kappacorr:[0,1]\times\Y^{n}\times\F\rightrightarrows \Y,\quad
  \CRED:[0,1]\times\Y^{n}\times\F\rightrightarrows \Prob^\text{dens},\quad
  \IHDR:[0,1] \times \Ccal\rightrightarrows \Y
\]
are \emph{lower hemicontinuous} at every point of their respective domains.
\end{proposition}

\begin{proof}

{\em Proof of lower hemicontinuity of $\kappacorr$.} Take $(\bar\alpha,\bar y^{n},\bar\psi)\in[0,1]\times\Y^{n}\times\F$ and $\bar y\in\kappacorr(\bar\alpha,\bar y^{n},\bar\psi)$.  By (Gap) there exists $\varepsilon>0$ with $G(\bar\alpha,\bar y^{n},\bar\psi,\bar y)\ge \bar\alpha+\varepsilon$.  By Lemma~\ref{lem:u.s.c.} there is a product neighborhood $U$ of $(\bar\alpha,\bar y^{n},\bar\psi,\bar y)$ on which $G\ge \bar\alpha+\varepsilon/2$.  Projecting $U$ onto the first three coordinates gives a neighborhood $V$ of $(\bar\alpha,\bar y^{n},\bar\psi)$ such that $\kappacorr(x)\cap W\ne\emptyset$ for every $x\in V$, where $W$ is the $\Y$-component of $U$.  This is precisely the definition of lower hemicontinuity.


{\em Proof of lower hemicontinuity of $\CRED$.}
Fix $(\bar\alpha,\bar y^{n},\bar\psi)$ and $\breve{P}\in\CRED(\bar\alpha,\bar y^{n},\bar\psi)$.  The weak$^\star$ topology on $\Prob^\text{dens} \subset \Prob$ is first countable (by Alaoglu and metrizability of the dual ball of $C(\Y)$).  Let $\{O_{k}\}$ be a neighborhood basis of $\breve{P}$.  For each $k$ choose finitely many Borel sets $A_{1}^{k},\dots,A_{m_{k}}^{k}$ and $\delta_{k}>0$ so small that if
\[
  \sup_{1\le j\le m_{k}}\bigl|Q(A_{j}^{k})-\breve{P}(A_{j}^{k})\bigr|<\delta_{k}
\]
then $Q\in O_{k}$.  For every $j$ use (Gap) as in the previous proof to find a neighborhood $V_{k,j}$ of $(\bar\alpha,\bar y^{n},\bar\psi)$ on which $\sup_{y\in A_{j}^{k}}G>\breve{P}(A_{j}^{k})+\delta_{k}$.  Intersecting these $V_{k,j}$ in $j$ and $k$ yields a neighborhood $V$ with the property that $\CRED(x)\cap O_{k}\ne\emptyset$ for all $x\in V$ and all $k$.  Again this is the definition of lower hemicontinuity.


{\em Proof of lower hemicontinuity of $\IHDR$.}
Let $(\bar\alpha,\bar{\mathcal M})$ be given and pick $\bar y\in\IHDR(\bar\alpha,\bar{\mathcal M})$.  By Lemma~\ref{lem:lsc-gM} there is $\varepsilon>0$ such that
\[
  g_{\bar{\mathcal M}}(\bar y)\ge k_{\bar{\mathcal M}}+\varepsilon,
\]
with $k_{\bar{\mathcal M}}$ continuous in $(\alpha,\mathcal M)$.  Choose a neighborhood $W$ of $\bar y$ on which $g_{\bar{\mathcal M}}\ge k_{\bar{\mathcal M}}+\tfrac{\varepsilon}{2}$.  Continuity of $(\alpha,\mathcal M)\mapsto k_{\mathcal M}$ and of $(\mathcal M,y)\mapsto g_{\mathcal M}(y)$ now gives a neighborhood $V$ of $(\bar\alpha,\bar{\mathcal M})$ such that for every $(\alpha,\mathcal M)\in V$ we still have $g_{\mathcal M}(y)\ge k_{\mathcal M}$ for some $y\in W$.  Hence $\IHDR(\alpha,\mathcal M)\cap W\neq\emptyset$ for all $(\alpha,\mathcal M)\in V$, which confirms lower hemicontinuity.
\end{proof}


Since the Hausdorff metric $d_H$ that we chose makes $\mathscr{C}$ a topological space (with respect to the topology metric), it is easy to conclude that $\kappa$, $\CRED$, and $\IHDR$ are all morphisms of $\textbf{LHCont}$ under the conditions in Proposition \ref{prop:LHC}. Then, we are ready to introduce the Full CP diagram, and show that it commutes.



\begin{theorem}
    Fix any $\alpha\in [0,1]$, and suppose the conditions in Proposition \ref{prop:LHC} hold. Consider the restrictions $\kappa_\alpha$, $\CRED_\alpha$, and $\IHDR$. Then, $\IHDR \circ \CRED_\alpha = \kappa_\alpha$. That is, the following {\em Full CP diagram} commutes
$$
   \begin{tikzcd}
    Y^n \times \mathscr{F} \ar{r}{\CRED_\alpha} \ar{dr}[swap]{\kappa_\alpha} & \Prob^\text{dens} \ar{d}{\IHDR} \\
    & Y
   \end{tikzcd}
  $$
\end{theorem}

\begin{proof}
    By \citet[Proposition 5]{cp-ip}, we know that, for all $\alpha \in [0,1]$, $y^n \in Y^n$, and $\psi \in \mathscr{F}$, the Conformal Prediction Region $\kappa_\alpha(y^n,\psi)$ corresponds to the $\alpha$-level IHDR of the credal set $\{P : P(A) \leq \overline{\Pi}(A) \text{, } \forall A \in \mathcal{B}(Y)\}$ associated with the possibility function $\overline{\Pi}$. The claim, then, follows from the definitions of the correspondences, and our assumptions that ensure us that our correspondences are morphisms of $\textbf{LHCont}$.
\end{proof}


\fi 





