	\keywords{  scalar curvature; rigidity theorems; Gagliardo-Nirenberg inequalities,  	unweighted Yamabe-type constants}

	\thanks{Liang Cheng's  Research partially supported by
		Natural Science Foundation of China 12171180
	}

