	\email{chengliang@ccnu.edu.cn }





	\begin{abstract}
		In this paper, we study the rigidity properties concerning the Gagliardo-Nirenberg constants and the unweighted Yamabe-type constants. We show that when $\alpha$ lies in a specific range around $1$, if an open subset $V \subset M$ satisfies $\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0$ and the Gagliardo-Nirenberg constants $\mathbb{G}_{\alpha}^{\pm}(V,g)$ are not less than those of the Euclidean space, then $V$ must be flat. Here, $\lambda_1(\operatorname{Rc})$ denotes the first eigenvalue of the Ricci tensor. Moreover, when $\alpha$ lies in a more restrictive range around $1$, if we replace the condition $\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0$ with the weaker condition for the scalar curvature $\int_{V} \operatorname{Sc} \, d\mu \geq 0$  and also assume that the Gagliardo-Nirenberg constants $\mathbb{G}_{\alpha}^{\pm}(V,g)$ are not less than those of the Euclidean space, we can still conclude that $V$ must be flat.
		We also show that when $\alpha$ is close to $1$, if an open subset $V \subset M$ satisfies the condition that its unweighted Yamabe-type constants $\mathbb{Y}_{\alpha}^{\pm}(V,g)$ are not less than those of the Euclidean space, then $V$ must be flat.	
	\end{abstract}
	\maketitle	

	\section{Introduction}

	It has been established that if a complete noncompact Riemannian manifold $M$ has nonnegative Ricci curvature and the optimal constants of several Sobolev-type inequalities are not less than those of Euclidean space, then $M$ must be flat. These Sobolev-type inequalities include the Sobolev inequality \cite{LSobolev}, the log-Sobolev inequality \cite{BCL, Ni2, Ni3, BKT}, the Gagliardo-Nirenberg inequality \cite{X2005, BKT}, the Caffarelli-Kohn-Nirenberg inequality \cite{DX, K2}, etc.
	The following natural problems arise:
	\begin{enumerate}
		\item Do these rigidity results hold locally? That is, if the optimal constants match the Euclidean ones in some open subset $V \subset M$, does this imply flatness for $V$?

		\item Can the nonnegative Ricci curvature condition in the aforementioned rigidity results be weakened to nonnegative scalar curvature (or something weaker)?
	\end{enumerate}

	The rigidity properties of Riemannian manifolds with lower scalar curvature bounds are an important subject of intensive study. 
	As highlighted by M. Gromov in the following problems: \textit{ Find verifiable criteria for extremality and rigidity, decide which manifolds admit extremal/rigid metrics and describe particular extremal/rigid manifolds; see Problem C in \cite{Gdozen}.}
	\textit{	What are the further examples of extremal/rigid with positive scalar curvature; see P27 in \cite{Gromovlecture}.} 	For a comprehensive overview of the rigidity results concerning scalar curvature, we refer to the survey \cite{Brendle} and the lectures \cite{Gromovlecture}, along with additional references therein.	


	This paper first investigates the aforementioned problems concerning Gagliardo-Nirenberg constants. To present our results, we begin by recalling the definition of \emph{Gagliardo-Nirenberg constants}.

	\begin{defn}
		Let $(M^n,g)$ be an $n$-dimensional Riemannian manifold, and $V \subset M^n$. Denote $\|u\|_{L^p(V)} := \left(\int_V |u|^p \, \mathrm{d}\mu_g\right)^{\frac{1}{p}}$, where $\mathrm{d}\mu_g$ is the volume form of $V$ induced by $g$. The Gagliardo-Nirenberg constants of $V$ with respect to $g$ are defined as:
		$$
		\mathbb{G}_{\alpha}^-(V,g) := \inf_{u \in W_0^{1,2}(V)} \frac{\|\nabla u\|^2_{L^2(V)} \|u\|_{L^{2\alpha}(V)}^{\frac{2(1-\gamma)}{\gamma}}}{\|u\|_{L^{\alpha+1}(V)}^{\frac{2}{\gamma}}}, \quad \text{for } 0 < \alpha < 1,
		$$
		and
		$$
		\mathbb{G}_{\alpha}^+(V,g) := \inf_{u \in W_0^{1,2}(V)} \frac{\|\nabla u\|^2_{L^2(V)} \|u\|_{L^{\alpha+1}(V)}^{\frac{2(1-\theta)}{\theta}}}{\|u\|_{L^{2\alpha}(V)}^{\frac{2}{\theta}}}, \quad \text{for } 1 < \alpha \leq \frac{n}{n-2},
		$$
		where  
		\begin{equation}
			\gamma:=\frac{2^*(1-\alpha)}{\left(2^*-2\alpha \right)(\alpha +1)}, \text{i.e. $\gamma$ is determined by }\frac{1}{\alpha+1} = \frac{\gamma}{2^*} + \frac{1-\gamma}{2\alpha},
		\end{equation}
		here $2^* := \frac{2n}{n-2}$, and 
		\begin{equation}\label{def:theta}
			\theta:=\frac{2^*(\alpha-1)}{2\alpha \left(2^*-\alpha -1\right)}, \text{i.e. $\theta$ is determined by  }	\frac{1}{2\alpha} = \frac{\theta}{2^*} + \frac{1-\theta}{\alpha+1}.
		\end{equation}
	\end{defn}
	\begin{rem}
		When $V=\mathbb{R}^n$ is $n$-dimensional Euclidean space, Del Pino and Dolbeault \cite{DD} proved 
		\begin{equation}\label{def_optimal_const}
			\begin{aligned}
				\mathbb{G}_{\alpha}^-(\mathbb{R}^n,g_{\mathbb{R}^n})&=\mathcal{N}_{\alpha, n}:=\left(\frac{1-\alpha}{2}\right)^\gamma \frac{\left(\frac{2}{n}\right)^{\frac{\gamma}{2}+\frac{\gamma}{n}}\left(\frac{1+\alpha}{1-\alpha}+\frac{n}{2}\right)^{\frac{\gamma}{2}-\frac{1}{\alpha+1}}\left(\frac{1+\alpha}{1-\alpha}\right)^{\frac{1}{\alpha+1}}}{\left(\omega_n \mathrm{~B}\left(\frac{1+\alpha}{1-\alpha}, \frac{n}{2}\right)\right)^{\frac{\gamma}{n}}},\\
				\mathbb{G}_{\alpha}^+(\mathbb{R}^n,g_{\mathbb{R}^n})&=\mathcal{G}_{\alpha, n}:=\left(\frac{\alpha-1}{2}\right)^\theta \frac{\left(\frac{2}{n}\right)^{\frac{\theta}{2}+\frac{\theta}{n}}\left(\frac{\alpha+1}{\alpha-1}-\frac{n}{2}\right)^{\frac{1}{2\alpha }}\left(\frac{\alpha+1}{\alpha-1}\right)^{\frac{\theta}{2}-\frac{1}{2\alpha }}}{\left(\omega_n \mathrm{~B}\left(\frac{\alpha+1}{\alpha-1}-\frac{n}{2}, \frac{n}{2}\right)\right)^{\frac{\theta}{n}}},
			\end{aligned}
		\end{equation}
		where $\mathrm{B}(\cdot, \cdot)$ is the Euler beta-function.
		Moreover, 
		$\mathbb{G}_{\alpha}^-(\mathbb{R}^n,g_{\mathbb{R}^n})$ and  $\mathbb{G}_{\alpha}^+(\mathbb{R}^n,g_{\mathbb{R}^n})$ both can be achieved by the family of functions 
		$$
		h_{\alpha}^\lambda(x)=\left(\lambda+(\alpha-1)\|x\|^{2}\right)_{+}^{\frac{1}{1-\alpha}}, \quad x \in \mathbb{R}^n,
		$$
		where  $r_{+}=\max \{0, r\}$ for $r \in \mathbb{R}$. 
	\end{rem}
	\begin{rem}
		The borderline case $\alpha=\frac{n}{n-2}$ (thus $\theta=1$) of $\mathbb{G}_{\alpha}^+(V,g)$ reduces to the optimal constant of the Sobolev inequality of $V$. Furthermore,   whenever $\alpha \rightarrow 1$, both $\mathbb{G}_{\alpha}^+(V,g)$ and $\mathbb{G}_{\alpha}^-(V,g)$ degenerate to the optimal constant of  logarithmic Sobolev inequality of $V$: $ \inf\limits_{\substack{u \in W_0^{1,2}(V),\int_{V} u^2 d\mu = 1}}\frac{\frac{n}{2} \log\left(\frac{2}{n\pi e} \int_{V}|\nabla u|^2\,d\mu_g\right)}{\int_{V} u^2 \log u^2\,d\mu_g}$.  When $\alpha \rightarrow 0$,
		$\mathbb{G}_{\alpha}^-(V,g)$ reduces to the optimal constant of the Faber-Krahn type inequality of $V$: 
		$
		\inf\limits_{\substack{u \in W_0^{1,2}(V)}} \frac{\|\nabla u\|_{L^2(V)}|\operatorname{supp}(u)|^{\frac{1}{2}}}{\|u\|_{L^1}}.
		$
	\end{rem}

	The Gagliardo-Nirenberg constants are related to
	the  weighted
	Yamabe constants considered by
	Jeffrey S. Case \cite{Jcase}\cite{Jcase2}, which constitute a one-parameter family and interpolate between the
	Yamabe constant and Perelman’s $\nu$-entropy when the parameter $m$ is zero and inﬁnity,
	respectively. 
	Let $(M^n, g, e^{-\phi} \text{dvol}, m)$ be the  quadruples consisting of an $n$-dimensional Riemannian manifold $(M^n, g)$, a weighted volume measure $e^{-\phi} \text{dvol}$, and a dimensional parameter $m \in [0, \infty]$, where the fundamental geometric quantity is the weighted scalar curvature $R_\phi^m = \operatorname{Sc}(g) + 2\Delta \phi - \frac{m+1}{m} |\nabla \phi|^2$. The weighted Yamabe constants, which serve as curved analogues for the Gagliardo-Nirenberg constants, are defined as the infimum of the quotient
	\begin{equation}\label{case_def}
		\mathcal{Q}(w) = \frac{\left(\int_M |\nabla w|^2 + \frac{m+n-2}{4(m+n-1)} R_\phi^m w^2\right) \left(\int_M |w|^{\frac{2(m+n-1)}{m+n-2}} e^{\phi/m}\right)^{\frac{2m}{n}}}{\left(\int_M |w|^{\frac{2(m+n)}{m+n-2}}\right)^{\frac{2m+n-2}{n}}},
	\end{equation}
	where all integrals are computed with respect to $e^{-\phi}\text{dvol}$.
	The weighted Yamabe quotient is conformally invariant in the sense that if
	$
	\left(M^n, \hat{g}, e^{-\hat{\phi}} \operatorname{dvol}_{\hat{g}}, m\right) = \left(M^n, e^{\frac{2 \sigma}{m+n-2}} g, e^{\frac{(m+n) \sigma}{m+n-2}} e^{-\phi} \operatorname{dvol}_g, m\right),
	$
	then $\hat{Q}(w)=Q(we^{\frac{\sigma}{2}})$.




	For the second purpose of this paper, we study the rigidity properties associated with the unweighted case (i.e., $\phi \equiv \mathrm{constant}$ in \eqref{case_def}) for weighted Yamabe constants. Specifically, we use the
	following definitions:


	\begin{defn}
		Let $(M^n,g)$ be an $n$-dimensional manifold  and $V\subset M^n$. 	Denote $\|u\|_{L^p(V)} := \left(\int_V |u|^p \, \mathrm{d}\mu_g\right)^{\frac{1}{p}}$, where $\mathrm{d}\mu_g$ is the volume form of $V$ induced by $g$. 
		The unweighted Yamabe-type constants of $V$ with respect to metric $g$ are defined as	
		$$
		\mathbb{Y}_{\alpha}^-(V,g):=\inf_{u \in  W_0^{1,2}(V)}\frac{\left(\|\nabla u\|_{L^2(V)}^2+\frac{1}{2(1+\alpha)}  \int_V \operatorname{Sc}\cdot u^2d\mu_g	\right)\cdot \|u\|_{L^{2\alpha}(V)}^{\frac{2(1-\gamma)}{\gamma}}}{\|u\|_{L^{\alpha+1}(V)}^{\frac{2}{\gamma}}  } \text{ for $0<\alpha<1$,}
		$$		
		and
		$$
		\mathbb{Y}_{\alpha}^+(V,g):=\inf_{u \in  W_0^{1,2}(V)}\frac{\left(\|\nabla u\|_{L^2(V)}^2+\frac{1}{2(1+\alpha)}  \int_V \operatorname{Sc}\cdot u^2d\mu_g	\right)\cdot \|u\|_{L^{\alpha+1}(V)}^{\frac{2(1-\theta)}{\theta}}}{\|u\|^{\frac{2}{\theta}}_{L^{2\alpha}(V)}  } \text{ for  $1<\alpha\le \frac{n}{n-2}$,}
		$$
		where $\operatorname{Sc}$ denotes the scalar curvature with respect to $g$.
	\end{defn}

	\begin{rem}
		Take $\alpha=\frac{m+n}{m+n-2}$ and when $\phi\equiv constant$, the quantity $\mathbb{Y}_{\alpha}^+(V,g)$ coincides with the infimum of the quotient in \eqref{case_def}.    
		%$\mathbb{Y}_{\alpha}^-(V,g)$ is defined in a similar way.
	\end{rem}	

	\begin{rem} 
		The borderline case $\alpha=\frac{n}{n-2}$ (thus $\theta=1$ ) of $\mathbb{Y}_{\alpha}^+(V,g)$ reduces to the Yamabe constant of $V$.
		%$\mathbb{Y}_{\alpha}^-(V,g)$ is defined in a similar way.
	\end{rem}


	\textbf{	We now present the main results of this paper.  }
	Our first main theorem establishes local rigidity results with respect to the Gagliardo-Nirenberg constant.
	We establish that when $\alpha$ lies in a specific range around $1$ (which will be explicitly specified in the following theorem), if an open subset $V \subset M$ satisfies $\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0$ and the Gagliardo-Nirenberg constants $\mathbb{G}_{\alpha}^{\pm}(V,g)$ are not less than those of the Euclidean space, then $V$ must be flat.  Moreover, when $\alpha$ lies in a more restrictive range around $1$ (which will be explicitly specified in the following theorem), if we replace the condition $\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0$ with the weaker condition for scalar curvature $\int_{V} \operatorname{Sc} \, d\mu \geq 0$, we can still conclude that $V$ must be flat.

	\begin{thm}\label{const_rigidity}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$, and let $V$ be an open bounded subset of $M^n$.	

		\noindent\textbf{(a) For the case $0<\alpha<1$:}
		\begin{enumerate}
			\item For $0<\alpha<1$, if 
			\begin{equation}\label{const_comparison_iso_2_6}
				\mathbb{G}_{\alpha}^-(V,g) \geq \mathbb{G}_{\alpha}^-(\mathbb{R}^n,g_{\mathbb{R}^n}),
			\end{equation}
			then the scalar curvature satisfies 
			$$\text{$\operatorname{Sc}(x) \leq 0$ for all $x \in V$.}$$

			\item  For $0<\alpha<1$,  
			if both \eqref{const_comparison_iso_2_6} and
			\begin{equation}\label{thm_Rc_point_compare_6}
				\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0 
			\end{equation}
			hold, \textbf{then} $V$ must be flat. Here, $\lambda_1(\operatorname{Rc})$ denotes the first eigenvalue of the Ricci tensor.

			\item Under the more restrictive range:
			\begin{equation}\label{6_i_3}
				\begin{cases}
					0<\alpha<1, & \text{if } n=3, \\
					\frac{2 n^2+n-25-\sqrt{28 n^2-16 n-287}}{2 n^2+3 n-38}<\alpha<1, & \text{if } n\geq 4,
				\end{cases}
			\end{equation}
			if both \eqref{const_comparison_iso_2_6} and 
			\begin{equation}\label{thm_R_point_compare_6}
				\int_{V} \operatorname{Sc} \, d\mu \geq 0 
			\end{equation}
			hold, \textbf{then} $V$ must be flat.
		\end{enumerate} 

		\noindent\textbf{(b) For the case $1<\alpha\le \frac{n}{n-2}$:}
		\begin{enumerate}
			\item For $\alpha$ in the range:
			\begin{equation}\label{6_i_2}
				\begin{cases}
					1< \alpha<\frac{n+4}{n}, & \text{if } n\leq 4, \\
					1<\alpha\leq \frac{n}{n-2}, & \text{if } n\geq 5,
				\end{cases}
			\end{equation}
			if 
			\begin{equation}\label{eq:comparison_iso_2_6}
				\mathbb{G}_{\alpha}^+(V, g) \geq \mathbb{G}_{\alpha}^+(\mathbb{R}^n, g_{\mathbb{R}^n}),
			\end{equation}
			then the scalar curvature satisfies 
			$$\text{$\operatorname{Sc}(x) \leq 0$ for all $x \in V$.}$$

			\item Under the more restrictive range:
			\begin{equation}\label{6_i_4666}
				\begin{cases}
					1<\alpha<\frac{n+6}{n+2}, & \text{if } n\leq 6, \\
					1<\alpha\le\frac{n}{n-2}, & \text{if } n\geq7,
				\end{cases}
			\end{equation}
			if both \eqref{eq:comparison_iso_2_6} and
			\begin{equation}\label{thm_Rc_point_compare_666}
				\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0 
			\end{equation}
			hold, \textbf{then} $V$ must be flat.

			\item Under the more restrictive range:
			\begin{equation}\label{6_i_4}
				\begin{cases}
					1<\alpha<\frac{n+6}{n+2}, & \text{if } n\leq 6, \\
					1<\alpha<\frac{2 n^2+n-25+\sqrt{28 n^2-16 n-287}}{2 n^2+3 n-38}, & \text{if } n\geq7,
				\end{cases}
			\end{equation}
			if both \eqref{eq:comparison_iso_2_6} and 
			\begin{equation}\label{Sc_int_nonnegative}
				\int_{V} \operatorname{Sc} \, d\mu \geq 0
			\end{equation}
			hold, \textbf{then} $V$ must be flat.
		\end{enumerate}
	\end{thm}

	For the second main theorem of this paper, we show that when $\alpha$ is sufficiently close to $1$, if an open subset $V \subset M$ has unweighted Yamabe-type constants no less than $\mathbb{G}_{\alpha}^{\pm}(\mathbb{R}^n,g_{\mathbb{R}^n})$, then $V$ must be flat.


	\begin{thm}\label{Yamabe_rigidity}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$, and let $V$ be an open bounded subset of $M^n$. 	
		Suppose that there exist constants $\kappa^{\pm}$, depending only on $n$, such that
		when $0<|\alpha-1|<\kappa^{\pm}$, the following holds:
		\begin{equation}\label{Yamabe_comparison_iso_2_6}
			\mathbb{Y}_{\alpha}^{\pm}(V,g)\ge \mathbb{G}_{\alpha}^{\pm}(\mathbb{R}^n,g_{\mathbb{R}^n}),
		\end{equation}
		Then $V$ must be flat.
	\end{thm}
	\begin{rem}
		The exact values of $\kappa^{\pm}$ are related to the solutions to the seventh degree polynomial equations (see Remark~\ref{exact_number_equation}).
	\end{rem}


	It remains unclear for us whether the ranges of $\alpha$ in Theorem~\ref{const_rigidity} (specified in \eqref{6_i_3}, \eqref{6_i_2}, \eqref{6_i_4666} and \eqref{6_i_4}) and the range \eqref{Yamabe_comparison_iso_2_6} in Theorem \ref{Yamabe_rigidity} are sharp for these results. However, the following example demonstrates that
	\begin{itemize}
		\item The conclusion of \textbf{(b)}(3) in Theorem \ref{const_rigidity} fails for the borderline case $\alpha=\frac{n}{n-2}$ , where $\mathbb{G}_{\alpha}^+(V,g)$ reduces to the Sobolev constant;
		\item The conclusion of Theorem~\ref{Yamabe_rigidity} also fails for the borderline case $\alpha=\frac{n}{n-2}$, where $\mathbb{Y}_{\alpha}^+(V,g)$ reduces to the Yamabe constant.
	\end{itemize}
	Here, we remark that, for comparison, the rigidity in \textbf{(b)}(2) in Theorem \ref{const_rigidity} holds for the borderline case $\alpha=\frac{n}{n-2}$ when $n \ge 7$. 
	This shows that when $n \ge 7$, the range of $\alpha$ for which we can guarantee that \eqref{eq:comparison_iso_2_6} and \eqref{Sc_int_nonnegative} imply the flatness of $V$ is strictly smaller than the range of $\alpha$ for which we can guarantee that \eqref{eq:comparison_iso_2_6} and \eqref{thm_Rc_point_compare_666} imply  the flatness of $V$.


	\begin{exam}[Schwarzschild metric]
		Note that the scalar curvature and Yamabe quotient of $g=u^{\frac{4}{n-2}} g_0$ on $M$ are related to the scalar curvature of $g_0$ by
		\begin{equation}\label{conformal_change_R}
			\operatorname{Sc}(g)= u^{-\frac{n+2}{n-2}} \left(\operatorname{Sc}\left(g_0\right) u-c(n)\Delta_{g_0} u\right),
		\end{equation}
		where $c(n)=\frac{4(n-1)}{n-2}$, and
		\begin{equation}\label{conformal_of_Q}
			Q_{g}(\phi)=Q_{g_0}(\phi u) \text{ for any smooth function } \phi,
		\end{equation}
		where the Yamabe quotient defined as 
		$$ Q_{g}(\phi):=\frac{\int_M \left( c(n) |\nabla_g \phi|^2+\operatorname{Sc}(g)\cdot \phi^2\right)d\mu_g}{\left(\int_M \phi^{\frac{2n}{n-2}}d\mu_g\right)^{\frac{n-2}{n}}} $$
		\text{ (cf. \cite{STbook})}.
		For a manifold $x\in\mathbb{R}^n\setminus\{0\}$ with $n \geq 3$, let $g_0:=\delta_{ij}$, $u(x):=1+ \frac{m}{2\left|x\right|^{n-2}}$, and $g=u^{\frac{4}{n-2}} g_0$, where $m$ is a positive real number. The hypersurface defined by $|x|=\frac{m}{2}$ is a totally geodesic submanifold, called the horizon. Reflecting the region $|x|>\frac{m}{2}$ across this horizon yields a complete smooth Riemannian manifold $N$, which is diffeomorphic to $S^{n-1} \times(0,1)$. Moreover, by \eqref{conformal_change_R} and $\Delta_{g_0}\frac{1}{\left| x\right|^{n-2}}=0$, we have $\operatorname{Sc}(g)\equiv 0$. 
		By \eqref{conformal_of_Q}, we have 
		$$
		\frac{\int_N |\nabla_g \phi|^2d\mu_g}{\left(\int_N \phi^{\frac{2n}{n-2}}d\mu_g\right)^{\frac{n-2}{n}}}=\frac{\int_N |\nabla_{g_0} (\phi u)|^2d\mu_{g_0}}{\left(\int_N (\phi u)^{\frac{2n}{n-2}}d\mu_{g_0}\right)^{\frac{n-2}{n}}} \text{ for any smooth function } \phi.
		$$
		This implies that the optimal constant of the Sobolev inequality for $(N,g)$ coincides with the Euclidean best constant. However, although $\operatorname{Sc}(g)\equiv 0$, the manifold $(N,g)$ is not Ricci flat. Note that $\mathbb{Y}_{\alpha}^+(N,g)$ reduces to $\mathbb{G}_{\alpha}^+(N,g)$ when $\operatorname{Sc}(g)\equiv 0$. So, this example also shows that the conclusion of Theorem~\ref{Yamabe_rigidity} fails when $\alpha=\frac{n}{n-2}$.
	\end{exam}




	We outline the strategy of our proofs. We employ the power series expansion method to prove our main results.
	In the previous work \cite{Cheng}, the author discovered that both logarithmic Sobolev functional $\mathcal{L}(V,g,u,t)$ and Perelman's $\mathcal{W}$-functional $\mathcal{W}(V,g,u,t)$ (see \eqref{Perel_W} and \eqref{log_func} for the definitions) admit the power series expansion:
	\begin{equation}\label{expansion_nu_opt}
		\mathcal{W}(V,g,u,t)=
		-\frac{1}{6}|\operatorname{Rm}|^2(p)t^2+o(t^2),
	\end{equation}		
	and
	\begin{equation}\label{expansion_n_opt}
		\mathcal{L}(V,g,u,t)=
		-\operatorname{Sc}(p)t-\left(\Delta \operatorname{Sc}(p)+\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+o(t^2),
	\end{equation}   
	when $u$ is chosen as $ u = (4\pi t)^{-\frac{n}{4}}e^{-\frac{d(p,x)^2}{8t}}\eta$, which is modified from the function $ (4\pi t)^{-\frac{n}{4}}e^{-\frac{d(p,x)^2}{8t}}$ which achieve the optimal constant in the logarithmic Sobolev inequality on Euclidean space. Here, $\eta$ satisfies $ \int_V (4\pi t)^{-\frac{n}{2}}e^{-\frac{d(p,x)^2}{4t}}\eta^2 d\mu = 1$ and
	\begin{enumerate}
		\item $p \in \operatorname{supp}(\eta) \subset\subset V$,
		\item $\eta^2$ admits the local expansion 
		$$
		\eta(x,t)^2 = \sum_{k=0}^2 \phi_k(x)t^k + o(t^2) \quad \text{around } (p,0),
		$$
		with the following regularity conditions at $p$:
		\begin{itemize}
			\item Both fourth derivatives of $\phi_0$ and second derivatives of $\phi_1$ exist at $p$,
			\item $\phi_2$ is continuous at $p$,
		\end{itemize}

		\item $\phi_0$ admits the local expansion
		$$
		\phi_0(x) = 1 + \frac{1}{3}\operatorname{Rc}(p)_{ij}x^ix^j + o(d^2) \quad \text{around } p,
		$$
		where $\{x^i\}$ denotes the normal coordinates on $T_pM$.
	\end{enumerate}
	Using the expansions  \eqref{expansion_nu_opt} and \eqref{expansion_n_opt}, 
	the author \cite{Cheng} proved that  if an open subset $V \subset M$ satisfies $\mathop{\int}_{V} \operatorname{Sc} \, d\mu \geq 0$ and  the optimal constant of  log-Sobolev inequality (the limit case $\alpha \to 1$ of the Gagliardo-Nirenberg constants) 
	is not less than that of the Euclidean space, then $V$ must be flat.

	Motivated by this work, in order to prove \textbf{(a)}(3) and \textbf{(b)}(3) of Theorem \ref{const_rigidity} and Theorem \ref{Yamabe_rigidity}, we find that  when $\alpha$ lies in a specific range around $1$ (which will be explicitly specified in  Theorem \ref{expansion_L_a} and Lemma \ref{expansion_W_a}), the power series expansions of 
	$\mathcal{L}^{\pm}_{\alpha}$-functionals $\mathcal{L}^{\pm}_{\alpha}(V,g, u, \tau)$ and $\mathcal{W}^{\pm}_{\alpha}$-functionals $\mathcal{W}^{\pm}_{\alpha}(V,g, u, \tau)$ (see Definitions \ref{Def_sec2}) - which generalize the logarithmic Sobolev and Perelman's $\mathcal{W}$-functionals - also admit remarkable power series expansions  (see Theorem \ref{expansion_L_a} and Lemma \ref{expansion_W_a}) when
	$u$ is chosen as 
	\begin{itemize}
		\item $u = C_1t^{-\frac{n}{2(\alpha+1)}}\left(1+ \frac{(\alpha-1)d(p,x)^2}{8t}\right)_+^{\frac{1}{1-\alpha}}\xi_-$ for $\mathcal{L}^{-}_{\alpha}$-functionals and $\mathcal{W}^{-}_{\alpha}$-functionals (with $\int_V u^{\alpha+1} d\mu_g = 1$), and
		$u = C_2t^{-\frac{n}{4\alpha}}\left(1+ \frac{(\alpha-1)d(p,x)^2}{8t}\right)_+^{\frac{1}{1-\alpha}}\xi_+$ for $\mathcal{L}^{+}_{\alpha}$-functionals and $\mathcal{W}^{+}_{\alpha}$-functionals (with $\int_V u^{2\alpha} d\mu_g = 1$),
	\end{itemize}
	where $\xi_{\pm}$ satisfies:
	\begin{enumerate}
		\item  [(a)] $p \in \operatorname{supp}(\xi_{\pm}) \subset\subset V$,
		\item [(b)] $\xi_{\pm}^2$ admits the local expansion 
		$$
		\xi_{\pm}(x,t)^2 = \sum_{k=0}^2 \phi_k(x)t^k + o(t^2) \quad \text{around } (p,0),
		$$
		with the following regularity conditions at $p$:
		\begin{itemize}
			\item Both fourth derivatives of $\phi_0$ and second derivatives of $\phi_1$ exist at $p$
			\item $\phi_2$ is continuous at $p$
		\end{itemize}

		\item[(c)]  $\phi_0$ admits the local expansion
		$$
		\phi_0(x) = 1 + \frac{2}{3\left((n+6)\alpha^2 - (2n+6)\alpha + n+4\right)}\operatorname{Rc}(p)_{ij}x^ix^j + o(d^2) \quad \text{around } p,
		$$
		where $\{x^i\}$ denotes the normal coordinates on $T_pM$.
	\end{enumerate}
	We denote by $\mathscr{B}_p(V)$ the set of all such functions:
	\begin{equation}\label{B_def}
		\mathscr{B}_p(V) = \biggl\{\eta \biggm| 
		\begin{aligned}
			& \eta \text{ satisfies conditions (a), (b), and (c)}
		\end{aligned}
		\biggr\}.
	\end{equation}
	Here, $u$ is modified from the functions 
	$ C(t)\left(1+ \frac{(\alpha-1)d(p,x)^2}{8t}\right)_+^{\frac{1}{1-\alpha}} $ and $ C(t)\left(1+ \frac{(\alpha-1)d(p,x)^2}{8t}\right)_+^{\frac{1}{1-\alpha}} $
	which achieve the Gagliardo-Nirenberg constants in Euclidean space. We emphasize that the expansions under the choice  
	$ u = C(t)\left(1+ \frac{(\alpha-1)d(p,x)^2}{8t}\right)_+^{\frac{1}{1-\alpha}} $ 
	cannot be used to prove \textbf{(a)}(3) and \textbf{(b)}(3) of Theorem \ref{const_rigidity} and Theorem \ref{Yamabe_rigidity} (see the case \( a = 0 \) in Theorem~\ref{expansion_L_a}) .  





	Finally, we can also use the expansion formulas obtained in this paper to prove the following rigidity theorem concerning the scalar curvature and isoperimetric inequality  proved in \cite{Cheng} (see Theorem 1.1 and Remark 1.2 in \cite{Cheng}):
	\begin{thm}\cite{Cheng}\label{rigidity_iso_profile}
		Let $(M^n,g)$ be an $n$-dimensional Riemannian manifold, and let $V$ be a bounded open subset with $\overline{V}\subset M$.
		Suppose that  the following two conditions hold: 

		\noindent (a) The scalar curvature of $V$ satisfies
		\begin{equation}\label{scalar_curvature_lowerbound}
			\fint_{V} \operatorname{Sc} \, d\mu :=\frac{\int_{V} \operatorname{Sc} \, d\mu}{\mathrm{Vol}(V)} \ge n(n-1)K,
		\end{equation}	
		\noindent (b)  There exists $\beta_0 > 0$ such that the isoperimetric profile of $V$ satisfies
		\begin{equation}\label{comparison_iso}
			\operatorname{I}(V, \beta) \coloneqq \inf_{\substack{\Omega \subset V \\ \mathrm{Vol}(\Omega) = \beta}} \mathrm{Area}(\partial \Omega) \geq \operatorname{I}(M^n_K, \beta) \quad \text{for all } \beta < \beta_0,
		\end{equation}
		where  $M^n_K$ is the  space form of constant sectional curvature $K$.\\
		Then the sectional curvature of $V$ satisfies 
		$$\operatorname{Sec}(x)=K  \text{ for all } x\in V.$$ 
	\end{thm}


	The present paper is organized as follows. In Section 2, we introduce the definitions of $\mathcal{L}^{\pm}_{\alpha}$-functionals and $\mathcal{W}^{\pm}_{\alpha}$-functionals. Then we investigate the relationship between $\mathbb{G}_{\alpha}^{\pm}(V,g)$ (resp. $\mathbb{Y}_{\alpha}^{\pm}(V,g)$) and $\mathbb{L}^{\pm}_{\alpha}(V,g, \tau)$ (resp. $\mathcal{\mu}^{\pm}_{\alpha}(V,g,\tau)$). In Section 3, we present preliminary calculations for the power series expansion formulas of $\mathcal{L}^{\pm}_{\alpha}$-functionals and $\mathcal{W}^{\pm}_{\alpha}$-functionals. In Section 4, we derive the power series expansion formulas for the $\mathcal{L}^{\pm}_{\alpha}$-functionals, and subsequently provide the proof of Theorem~\ref{const_rigidity}. In Section 5,
	we derive the power series expansion formulas for the $\mathcal{W}^{\pm}_{\alpha}$-functionals when choosing $\xi_{\pm}\in \mathscr{B}_p(V)$, and subsequently provide the proof of Theorem~\ref{Yamabe_rigidity}.
	In Section 6, we give the proof of Theorem \ref{rigidity_iso_profile} by using the expansion formulas of $\mathcal{L}^{\pm}_{\alpha}$-functionals.

	\section{Definitions of $\mathcal{L}^{\pm}_{\alpha}$-functionals and $\mathcal{W}^{\pm}_{\alpha}$-functionals }

	For the proofs of Theorem \ref{const_rigidity} and Theorem \ref{Yamabe_rigidity}, it is convenient to use the power series expansion formulas of the $\tau$-dependent $\mathcal{L}^{\pm}_{\alpha}$-functionals and the $\mathcal{W}^{\pm}_{\alpha}$-functionals. The $\mathcal{W}^{+}_{\alpha}$- functional was introduced by Jeffrey S. Case as a generalization of Perelman's $\mathcal{W}$-functional (cf. Definition 3.8 in \cite{Jcase}), and $\mathcal{W}^{-}_{\alpha}$-functionals and $\mathcal{L}^{\pm}_{\alpha}$-functionals can be defined in a similar way.
	\begin{defn}\label{Def_sec2}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$ and $V$ be an open bounded subset of $M^n$. $\mathcal{N}_{\alpha, n}$ and $\mathcal{G}_{\alpha, n}$ are the constants defined in \eqref{def_optimal_const}. Let $\mathfrak{m}$ be any fixed positive constant.
		\\
		\noindent (i) For $0<\alpha<1$, denote
		$$
		\Gamma_{\alpha}:=\frac{n}{2}\cdot\frac{1-\alpha}{1+\alpha}, \quad \text{and} \quad \Sigma^-_{\alpha}:= \left(\frac{\Gamma_{\alpha}}{\Gamma_{\alpha}+1}\right)^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}} \mathcal{N}_{\alpha,n}^{\frac{2}{\gamma}\cdot\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}.
		$$
		The\textbf{ $\mathcal{L}^-_{\alpha}$- functional} is defined by
		$$
		\begin{aligned}
			\mathcal{L}^-_{\alpha}(V,g, u, \tau) = \tau^{\Gamma_{\alpha}+1} \int_V \left|\nabla u\right|^2 d\mu + \mathfrak{m}\left( \tau^{-\Gamma_{\alpha}}\int_V u^{2\alpha}d\mu - \int_V u^{\alpha+1}d\mu\right) + \mathfrak{m}\left(1-\frac{2\Gamma_{\alpha}+1}{\Gamma_{\alpha}}\mathfrak{m}^{-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}\right),
		\end{aligned}
		$$
		and the \textbf{$\mathcal{W}^-_{\alpha}$-functional}  is defined by
		$$
		\begin{aligned}
			\mathcal{W}^-_{\alpha}(V,g, u, \tau) = \mathcal{L}^-_{\alpha}(V,g, u, \tau) + \frac{1}{2(1+\alpha)}\tau^{\Gamma_{\alpha}+1} \int_V \operatorname{Sc} \cdot u^2 d\mu.
		\end{aligned}
		$$


		\noindent (ii) For $1<\alpha\le \frac{n}{n-2}$, denote
		$$
		\Theta_{\alpha}:=\frac{n}{4}\frac{\alpha-1}{\alpha}, \quad \text{and} \quad \Sigma^+_{\alpha}:= \left(\frac{\Theta_{\alpha}}{1-2\Theta_{\alpha}}\right)^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}} \mathcal{G}_{\alpha,n}^{\frac{2}{\theta}\cdot\frac{\Theta_{\alpha}}{(1-\Theta_{\alpha})}}.
		$$
		The \textbf{$\mathcal{L}^+_{\alpha}$- functional}  is defined by
		$$
		\begin{aligned}
			\mathcal{L}^+_{\alpha}(V,g, u, \tau) = \tau^{1-2\Theta_{\alpha}} \int_V \left|\nabla u\right|^2 d\mu  + \mathfrak{m}\left( \tau^{-\Theta_{\alpha}}\int_V u^{\alpha+1} d\mu - \int_V u^{2\alpha} d\mu \right) + \mathfrak{m}\left(1-\frac{1-\Theta_{\alpha}}{\Theta_{\alpha}}\mathfrak{m}^{-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}\right),
		\end{aligned}
		$$
		and
		the \textbf{$\mathcal{W}^+_{\alpha}$- functional}  is defined by
		$$
		\begin{aligned}
			\mathcal{W}^+_{\alpha}(V,g, u, \tau) = \mathcal{L}^+_{\alpha}(V,g, u, \tau) + \frac{1}{2(1+\alpha)}\tau^{1-2\Theta_{\alpha}} \int_V \operatorname{Sc} \cdot u^2 d\mu.
		\end{aligned}
		$$

		\noindent   (iii)
		The \textbf{$\mathbb{L}^{\pm}_{\alpha}$-constant} of $V$ is defined by
		$$
		\mathbb{L}^-_{\alpha}(V,g, \tau):= \inf_{\substack{u \in W_0^{1,2}(V),\int_{V} u^{\alpha+1} d\mu = 1}} \mathcal{L}^-_{\alpha}(V,g, u, \tau), \quad \mathbb{L}^{+}_{\alpha}(V,g, \tau):= \inf_{\substack{u \in W_0^{1,2}(V),\int_{V} u^{2\alpha} d\mu = 1}} \mathcal{L}^{+}_{\alpha}(V,g, u, \tau),
		$$
		and the \textbf{$\mathbb{\mu}^{\pm}_{\alpha}$-constant} of $V$ is defined by
		$$
		\mathbb{\mu}^-_{\alpha}(V,g, \tau):= \inf_{\substack{u \in W_0^{1,2}(V),\int_{V} u^{\alpha+1} d\mu = 1}} \mathcal{W}^-_{\alpha}(V,g, u, \tau),\quad	\mathbb{\mu}^{+}_{\alpha}(V,g, \tau):= \inf_{\substack{u \in W_0^{1,2}(V),\int_{V} u^{2\alpha} d\mu = 1}} \mathcal{W}^{+}_{\alpha}(V,g, u, \tau).
		$$
	\end{defn}


	\begin{rem}
		Note that $\mathcal{W}^{\pm}_{\alpha}(V,g, u, \tau)$ are the generalization of Perelman's $\mathcal{W}$-functional. Indeed,
		when $\alpha\to 1$ and let $\mathfrak{m}:=\mathfrak{m}(\alpha)$ satisfying $\frac{|\alpha-1|}{2}\mathfrak{m}(\alpha)\to 1$, $\mathcal{W}^{\pm}_{\alpha}(V,g, u, \tau)$
		tends to the Perelman's $\mathcal{W}$-functional
		\begin{equation}\label{Perel_W}
			\mathcal{W}(V,g, u, \tau)=\tau \int_V\left( \left|\nabla u\right|^2+\frac{1}{4}\operatorname{Sc}\cdot u^2 \right)d\mu-\int_V u^2\log u^2d\mu-\frac{n}{2}\log \tau-n,
		\end{equation}
		and
		$\mathcal{L}^{\pm}_{\alpha}(V,g, u, \tau)$
		tends to following  functional which related to log-Sobolev inequality:
		\begin{equation}\label{log_func}	
			\mathcal{L}(V,g, u, \tau)=\tau \int_V \left|\nabla u\right|^2 d\mu-\int_V u^2\log u^2-\frac{n}{2}\log \tau-n,
		\end{equation}
	\end{rem}

	The following theorem reveals the relationship between $\mathbb{G}_{\alpha}^{\pm}(V,g)$ (resp.\ $\mathbb{Y}_{\alpha}^{\pm}(V,g)$) and $\mathbb{L}^{\pm}_{\alpha}(V,g, \tau)$ (resp.\ $\mathcal{\mu}^{\pm}_{\alpha}(V,g,\tau)$).

	\begin{thm}\label{connection}
		$\mathbb{G}_{\alpha}^{\pm}(V,g)\ge \mathbb{G}_{\alpha}^{\pm}(\mathbb{R}^n,g_{\mathbb{R}^n})$	if and only	if $\mathbb{L}^{\pm}_{\alpha}(V,g, \tau)\ge 0$ for any $\tau>0$. Moreover,	$\mathbb{Y}_{\alpha}^{\pm}(V,g)\ge \mathbb{G}_{\alpha}^{\pm}(\mathbb{R}^n,g_{\mathbb{R}^n})$	if and only	if $\mathcal{\mu}^{\pm}_{\alpha}(V,g,\tau)\ge 0$ for any $\tau>0$.
	\end{thm}
	\begin{proof}
		Theorem \ref{connection} follows from the 
		straightforward calculus exercise: if $A, B \geq 0$, then
		$$
		\inf _{x>0}\left\{A \tau^{p}+\mathfrak{m} B \tau^{-q}\right\}=\frac{\mathfrak{m}(p+q)}{p}\left(\frac{p }{\mathfrak{m} q}A B^{\frac{p}{q}}\right)^{\frac{q}{p+q}}
		$$
		for all $\tau>0$, with equality if and only if
		\begin{equation}\label{tau_connection}
			\tau=\left(\frac{\mathfrak{m} q}{p}\cdot\frac{ B}{ A}\right)^{\frac{1}{p+q}}.
		\end{equation}


	\end{proof}




	\section{Preliminaries for the calculation of Power series expansion formulas }	

	In this section, we present preliminary calculations for the power series expansion formulas of $\mathcal{L}^{\pm}_{\alpha}$-functionals and $\mathcal{W}^{\pm}_{\alpha}$-functionals.

	Here and below, we will use the following notation:
	for $p>0$
	\begin{equation}\label{def_mathcsr_B}
		\mathscr{B}(p,q):= 	\begin{cases}
			\mathrm{B}(p,q)  & \text{if } q>0,\\
			\mathrm{B}(p,-q-p+1) & \text{if } q<0 	 \text{ and } -p-q+1>0,	
		\end{cases}
	\end{equation}	
	where $\mathrm{B}(\cdot, \cdot)$ is the Euler beta-function.


	We will use the following identities in our calculations:
	When
	\begin{equation*}
		\begin{cases}
			q_1>-n, q_2>-1, & \text{if }	\alpha<1, \\
			q_1>-n, -q_2-\frac{n+q_1}{2}>0,	 & \text{if } \alpha>1,
		\end{cases}
	\end{equation*}
	we have 
	\begin{equation}\label{3.1_e0}
		\begin{aligned}
			& \int_{\mathbb{R}^n} |y|^{q_1}\left(1+\frac{(\alpha-1)|y|^2}{8}\right)_+^{q_2} dy^n \\ 
			&= \omega_{n-1}\int_0^{\infty} r^{n-1+q_1}\left(1+\frac{(\alpha-1)r^2}{8}\right)_+^{q_2} dr\\
			&\xlongequal{s=\frac{|\alpha-1|r^2}{8}}
			\begin{cases}
				\frac{\omega_{n-1}}{2} \left(\frac{1-\alpha}{8}\right)^{-\frac{n+q_1}{2}}\int_0^{1} s^{\frac{n+q_1}{2}-1}\left(1-s\right)_+^{q_2} ds, & \text{if } \alpha<1, q_1>-n, q_2>-1,\\
				\frac{\omega_{n-1}}{2} \left(\frac{\alpha-1}{8}\right)^{-\frac{n+q_1}{2}}\int_0^{\infty} s^{\frac{n+q_1}{2}-1}\left(1+s\right)^{q_2} ds, & \text{if } \alpha>1, q_1>-n, -q_2-\frac{n+q_1}{2}>0 , 			
			\end{cases}
			\\
			&= \frac{\omega_{n-1}}{2} \left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+q_1}{2}} \mathscr{B}\left(\frac{n+q_1}{2},q_2+1\right),
		\end{aligned}
	\end{equation}
	where we have used
	\begin{equation}\label{beta_func_def}
		\text{ $\int_0^{1} s^{p-1}\left(1-s\right)^{q-1} ds=\mathrm{B}(p, q)$  and $\int_0^{\infty} s^{p-1}\left(1+s\right)^{-(p+q)} ds=\mathrm{B}(p, q)$ for $p>0$ and $q>0$.} 
	\end{equation}


	When
	\begin{equation*}
		\begin{cases}
			q_1>-n-2, q_2>-1, & \text{if }	\alpha<1, \\
			q_1>-n-2, -q_2-\frac{n+q_1+2}{2}>0,	 & \text{if } \alpha>1,
		\end{cases}
	\end{equation*}
	we have for any symmetric matrix $A_{ij}$:
	\begin{equation}\label{3.1_e11}
		\begin{aligned}
			&	\ \ \ \  \int_{\mathbb{R}^n} |y|^{q_1}\left(1+\frac{(\alpha-1)|y|^2}{8}\right)_+^{q_2}   A_{i j} y^i y^j dy^n \\ 
			&=  \int_0^{\infty} r^{n+1+q_1}\left(1+\frac{(\alpha-1)r^2}{8}\right)_+^{q_2} dr\int_{s^{n-1}(1)} A_{i j}  z^i z^j dz^{n-1} \\
			&\xlongequal{s=\frac{|\alpha-1|r^2}{8}}
			\begin{cases}
				\frac{\omega_{n-1}}{2n} \left(\frac{1-\alpha}{8}\right)^{-\frac{n+q_1+2}{2}}\operatorname{tr}(A)\int_0^{1} s^{\frac{n+q_1+2}{2}-1}\left(1-s\right)_+^{q_2} ds, & \text{if } \alpha<1, q_1>-n-1, q_2>-1,\\
				\frac{\omega_{n-1}}{2n} \left(\frac{\alpha-1}{8}\right)^{-\frac{n+q_1+2}{2}}\operatorname{tr}(A)\int_0^{\infty} s^{\frac{n+q_1+2}{2}-1}\left(1+s\right)^{q_2} ds, & \text{if } \alpha>1, q_1>-n-1, -q_2-\frac{n+q_1+2}{2}>0,  		
			\end{cases}
			\\
			&= 		\frac{\omega_{n-1}}{2n} \left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+q_1+2}{2}} \mathscr{B}(\frac{n+q_1+2}{2},q_2+1) \operatorname{tr}(A),
		\end{aligned}
	\end{equation}
	where we have used \eqref{beta_func_def} and
	$$
	\int_{s^{n-1}(1)}A_{i j}  z^i z^j =\sum_{i=1} A_{i i} \int_{s^{n-1}(1)}  (z^i)^2dz^{n-1}=\frac{\int_{s^{n-1}(1)}  \sum\limits^n_{i=1}(z^i)^2dz^{n-1}}{n}\operatorname{tr}(A)=\frac{\omega_{n-1}}{n} \operatorname{tr}(A).
	$$
	Moreover,
	when
	\begin{equation*}
		\begin{cases}
			q_1>-n-4, q_2>-1, & \text{if }	\alpha<1, \\
			q_1>-n-4, -q_2-\frac{n+q_1+4}{2}>0,	 & \text{if } \alpha>1,
		\end{cases}
	\end{equation*} 
	we have for any four tensor $\lambda_{ijkl}$:	
	\begin{equation}\label{3.1_e21}
		\begin{aligned}
			&	\ \ \ \  \int_{\mathbb{R}^n} |y|^{q_1}\left(1+\frac{(\alpha-1)|y|^2}{8}\right)_+^{q_2}   \lambda_{i j k l} y^i y^j y^k y^l dy^n \\ 
			&=  \int_0^{\infty} r^{n+3+q_1}\left(1+\frac{(\alpha-1)r^2}{8}\right)_+^{q_2} dr\int_{s^{n-1}(1)}  \lambda_{i j k} z^i z^j z^{k } z^ldz^{n-1} \\
			&\xlongequal{s=\frac{|\alpha-1|r^2}{8}}
			\begin{cases}
				\frac{\omega_{n-1}}{2n(n+2)} \left(\frac{1-\alpha}{8}\right)^{-\frac{n+q_1+4}{2}}\operatorname{E}(\lambda)\int_0^{1} s^{\frac{n+q_1+4}{2}-1}\left(1-s\right)_+^{q_2} ds, & \text{if } \alpha<1,   q_1>-(n+4),  q_2>-1,\\
				\frac{\omega_{n-1}}{2n(n+2)} \left(\frac{\alpha-1}{8}\right)^{-\frac{n+q_1+4}{2}}\operatorname{E}(\lambda)\int_0^{\infty} s^{\frac{n+q_1+4}{2}-1}\left(1+s\right)^{q_2} ds, & \text{if } \alpha>1, q_1>-(n+4),  -q_2-\frac{n+q_1+4}{2}>0,
			\end{cases}
			\\
			&= 		\frac{\omega_{n-1}}{2n(n+2)} \left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+q_1+4}{2}}\mathscr{B}(\frac{n+q_1+4}{2},q_2+1)\operatorname{E}(\lambda),
		\end{aligned}
	\end{equation}
	where 
	\begin{equation}\label{def_of_E}
		\operatorname{E}(\lambda):= \sum\limits_{i j=1}^n\left(\lambda_{i i j j}+\lambda_{i j i j}+\lambda_{i j j i}\right),
	\end{equation}
	we have used \eqref{beta_func_def} and
	$$
	\begin{aligned}
		&\ \ \ \int_{S^{n-1}(1)} \lambda_{i j k l}  z^i z^j z^k z^l dz^{n-1}\\
		& =\frac{\omega_{n-1}}{n(n+2)}\left\{3 \sum_{i=1}^n \lambda_{i i i i}+\sum_{i \neq j}\left(\lambda_{i i j j}+\lambda_{i j i j}+\lambda_{i j j i}\right)\right\}\\
		& =\frac{\omega_{n-1}}{n(n+2)} \operatorname{E}(\lambda) ,
	\end{aligned}
	$$
	since 
	$\int_{S^{n-1}(1)} z_i^4 dz^{n-1}=3 \int_{S^{n-1}(1)} z_i^2 z_j^2 dz^{n-1}=\frac{3 \pi^{n / 2}}{(n+2)\Gamma(\frac{n}{2} +1)}$ for $i\ne j$ (c.f. (A.4) and (A.5) in \cite{G} )  and 
	each the integral of which $a_i$ appears for odd times is zero because the integral over one hemisphere cancels the integral over the other.







	Next, we derive the following lemma, which is required for calculating each term in the power series expansions of the $\mathcal{L}^{\pm}_{\alpha}$-functionals and $\mathcal{W}^{\pm}_{\alpha}$-functionals.

	\begin{lem}\label{key_lemma}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$ and $p\in V\subset\mathring{M^n}$, where $V$ is a neighborhood of $p$. 
		Denote the function $\operatorname{H}:\mathbb{R}_+\to \mathbb{R}_+$:
		$$\operatorname{H}(r)=\left(1+ \frac{(\alpha-1)r^2}{8}\right)_+^{\frac{1}{1-\alpha}}.$$  
		Take the function $\xi(x,t)$ on $M$, which has the following expansion around $p$:
		\begin{equation}\label{expansion_of_xi}
			\begin{aligned}
				&\xi^2(x,t)=\sum_{k=0}^2 \phi_k(x)t^k + o(t^2),\\
				&\phi_0(x)=1+\textbf{a}_{ij}x^ix^j+e_{ijk}x^ix^jx^k+b_{ijkl}x^ix^jx^kx^l+o(|x|^4),\\
				&\phi_1(x) =\beta_1+q_ix^i+d_{ij}x^ix^j+o(|x|^2),\\
				&\phi_2(x)=\beta_2+o(1),
			\end{aligned}
		\end{equation}
		where $\{x^k\}^n_{k=1}$ is the normal coordinates of $T_pM$.

		\noindent(i)
		When  either $0<\alpha<1$, or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-1>0$), we have
		\begin{equation}\label{expansion_D1st}
			t^{-\frac{n}{2}}  \int_V 
			\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)^m d\mu=D_0(m)+D_1(m)t+o(t),
		\end{equation}
		Moreover, when either $0<\alpha<1$, or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-2>0$),  we have
		\begin{equation}\label{expansion_D2rd}
			t^{-\frac{n}{2}}  \int_V 
			\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)^m d\mu=D_0(m)+D_1(m)t+D_2(m)t^2+o(t^2),
		\end{equation}
		where
		$$
		D_0(m)=\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{m}{1-\alpha}+1),
		$$
		$$
		\frac{D_1(m)}{D_0(m)}=\frac{m}{2}\beta_1+\frac{m}{2n}\left(\frac{|\alpha-1|}{8}\right)^{-1}\frac{\mathscr{B}(\frac{n}{2}+1,\frac{m}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{m}{1-\alpha}+1)}\operatorname{tr}(\textbf{a})-\frac{1}{6n}
		\left(\frac{|\alpha-1|}{8}\right)^{-1}\frac{\mathscr{B}(\frac{n}{2}+1,\frac{m}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{m}{1-\alpha}+1)}\operatorname{Sc}(p),
		$$
		$$
		\begin{aligned}
			\frac{D_2(m)}{D_0(m)}&=\frac{1}{n(n+2)}	\left(\frac{|\alpha-1|}{8}\right)^{-2}\frac{\mathscr{B}(\frac{n}{2}+2,\frac{m}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{m}{1-\alpha}+1)}\left[\frac{m}{2}\operatorname{E}(b)+\frac{m(m-2)}{8}\operatorname{E}(\textbf{a} \otimes \textbf{a})+\operatorname{E}(v)-\frac{m}{12}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\right]\\
			&+\frac{1}{n}	\left(\frac{|\alpha-1|}{8}\right)^{-1}\frac{\mathscr{B}(\frac{n}{2}+1,\frac{m}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{m}{1-\alpha}+1)}\left[\frac{m}{2}\operatorname{tr}(d)+\frac{m(m-2)}{4}\beta_1 \operatorname{tr}(\textbf{a})-\frac{m}{12}\beta_1 \operatorname{Sc}(p)\right]\\
			&+\left(\frac{m}{2}\beta_2+\frac{m(m-2)}{8}\beta_1^2\right),
		\end{aligned}
		$$
		where $\mathscr{B}(p,q)$ is defined in \eqref{def_mathcsr_B}, $\operatorname{E}$ is defined in \eqref{def_of_E} and  $v$ is the tensor defined as
		\begin{equation}\label{def_v}
			v_{ijkl}=\frac{1}{24}\left(-\frac{3}{5} \nabla_k \nabla_l R_{ij}-\frac{2}{15}\sum\limits_{s, t=1}^n R_{isjt}R_{kslt}+\frac{1}{3} R_{ij} R_{k l}\right)(p). 
		\end{equation}

		\noindent(ii)  When  either $0<\alpha<1$, or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$), we have
		\begin{equation}\label{expansion_A1st}
			t^{1-\frac{n}{2}}  \int_V \left|\nabla
			\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)\right|^2 d\mu  =A_0+A_1t+o(t)	,
		\end{equation}
		Moreover,  when  either $0<\alpha<1$, or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$), we have
		\begin{equation}\label{expansion_A2rd}
			t^{1-\frac{n}{2}}  \int_V \left|\nabla
			\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)\right|^2 d\mu  =A_0+A_1t+A_2t^2+o(t^2)	,
		\end{equation}
		where
		$$
		A_0=\frac{\omega_{n-1}}{32}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+2}{2}}\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1),
		$$
		$$
		\frac{A_1}{A_0}=\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{tr}(\textbf{a})-\frac{1}{6}\operatorname{Sc}(p)\right)-\frac{8}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(\textbf{a})+\beta_1, 
		$$
		$$
		\begin{aligned}
			\frac{A_2}{A_0}&=\frac{1}{n(n+2)}	\left(\frac{|\alpha-1|}{8}\right)^{-2}\frac{\mathscr{B}(\frac{n}{2}+3,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{E}(b)+\operatorname{E}(v)-\frac{1}{6}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\right)\\
			&+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{tr}(d)-\frac{1}{6}\beta_1\operatorname{Sc}(p)\right)+\beta_2+\frac{16}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(\textbf{a}^2)\\
			&	\quad -\frac{8}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(d)+
			\frac{1}{n(n+2)}	\left(\frac{|\alpha-1|}{8}\right)^{-1}\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(-16\operatorname{E}(b)+\frac{4}{3}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\right), 
		\end{aligned}
		$$

		\noindent(iii) When either $0<\alpha<1$, or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-1>0$), we have
		\begin{equation}
			\begin{aligned}
				\begin{aligned}
					&t^{1-\frac{n}{2}}  \int_V \operatorname{Sc}(x)\cdot  \left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)^2  d\mu  \\ =&\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)\times\\
					&\Big\{\operatorname{Sc}(p)t+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2+o(t^2)\Big\}	,
				\end{aligned}
			\end{aligned}
		\end{equation}
	\end{lem}
	\begin{proof} \textbf{(i)} 
		Let $\Sigma_p\subset T_pM$ be the segment domain of $p$, and let $\operatorname{det}\left(g_{k \ell}(x)\right) := 0$ and $\xi^2(x,t):= 0$ outside $\Sigma_p$.
		Recall that in the normal coordinates $\{x^k\}^n_{k=1}$ of $T_pM$,  $\operatorname{det}\left(g_{k \ell}(x)\right) $ has the following  power series expansion near $p$ (see Lemma 3.4 in p. 210 of \cite{STbook})
		\begin{equation}\label{expansion_detg}
			\begin{aligned}
				\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} &  =1-\frac{1}{6} R_{ij}(p) x^i x^j-\frac{1}{12} \nabla_k R_{ij}(p) x^i x^j x^k +v_{ijkl} x^i x^j x^k x^l  +O\left(|x|^5\right),
			\end{aligned}
		\end{equation}	
		where $v$ is the tensor defined in \eqref{def_v}. 
		By \eqref{expansion_of_xi} and \eqref{expansion_detg}, we have 
		\begin{equation}\label{key_lemma_term1}
			\begin{aligned}
				&\ \ \ \ \xi^m(x,t)\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				=&\left\{1+\frac{m}{2}\left(\textbf{a}_{ij}x^ix^j+\beta_1t\right)+\frac{m}{2}\left(e_{ijk}x^ix^jx^k+q_i x^it\right)+\frac{m}{2}\left(b_{ijkl}x^ix^jx^kx^l+d_{ij} x^ix^jt+\beta_2 t^{2}\right)\right.\\
				&\left.+\frac{m(m-2)}{8}\left(\beta_1^2t^2+2\beta_1 \textbf{a}_{ij}x^ix^jt+\textbf{a}_{ij}\textbf{a}_{kl}x^ix^jx^kx^l\right)+o(|x|^2)t+o(|x|^4)+o(1)t^2\right\}\times\\
				&\left\{1-\frac{1}{6} R_{ij}(p) x^i x^j-\frac{1}{12} \nabla_k R_{ij}(p) x^i x^j x^k +v_{ijkl} x^i x^j x^k x^l +o(|x|^4) \right\}\\
				&=Q_{m,1}+Q_{m,2}+P,
			\end{aligned}
		\end{equation}	
		where
		\begin{align}
			Q_{m,1}:=&1+\left(\frac{m}{2}\textbf{a}_{ij}-\frac{1}{6} R_{ij}(p) \right)x^i x^j+\frac{m}{2}\beta_1t,\label{def_Q_1}\\
			Q_{m,2}:=&  \left\{\frac{m}{2}\left(e_{ijk}x^ix^jx^k+q_i x^it\right)-\frac{1}{12} \nabla_k R_{ij}(p) x^i x^j x^k\right\}\nonumber\\
			& +\left\{\left(\frac{m}{2}b_{ijkl}+\frac{m(m-2)}{8}\textbf{a}_{ij}\textbf{a}_{kl}+v_{ijkl}-\frac{m}{12}\textbf{a}_{ij} R_{kl}(p)\right)x^ix^jx^kx^l\right.\nonumber\\
			&\left.\ \ \ \ +\left(\frac{m}{2}d_{ij}+\frac{m(m-2)}{4}\beta_1 \textbf{a}_{ij}-\frac{m}{12}\beta_1R_{ij}(p)\right) x^ix^jt +\left(\frac{m}{2}\beta_2+\frac{m(m-2)}{8}\beta_1^2\right) t^2 \right\} ,\label{def_Q_2}\\
			P  :=& o(|x|^2)t+o(|x|^4)+o(1)t^2.\nonumber
		\end{align}



		Denote $$W:= \Sigma_p \cap exp^{-1}_p \left(V\cap \operatorname{supp}\{\xi\}\right),$$ we have
		\begin{equation}\label{term1}
			\begin{aligned}
				&\quad   t^{-\frac{n}{2}}  \int_V 
				\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)^m d\mu\\
				&= t^{-\frac{n}{2}}  \int_{W} 
				\operatorname{H}^m(\frac{|x|}{\sqrt{t}}) \xi^m(x,t)\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}dx^n\\
				&= t^{-\frac{n}{2}}  \int_{W} 
				\operatorname{H}^m(\frac{|x|}{\sqrt{t}}) \left(Q_{m,1}+Q_{m,2}+P\right)dx^n.
			\end{aligned}
		\end{equation}

		\textbf{Next, we calculate each term of \eqref{term1} separately.}

		When $0 < \alpha < 1$, and noting that $\operatorname{H}\left(\frac{d(p,x)}{\sqrt{t}}\right) = 0$ if $d(p,x)^2 \geq \frac{8}{1-\alpha}t$, we have for sufficiently small $t$ and any smooth function $f$ on $M$:
		\begin{equation}\label{alphal1}
			\int_{W} \operatorname{H}^m\left(\frac{|x|}{\sqrt{t}}\right) f dx^n = \int_{T_pM} \operatorname{H}^m\left(\frac{|x|}{\sqrt{t}}\right) f dx^n.
		\end{equation}



		When $1 < \alpha \leq \frac{n}{n-2}$, taking some ball $B(o,r_0) \subset W$, since
		\begin{equation}\label{estimate_Q}
			\begin{aligned}
				&\quad t^{-\frac{n}{2}}\int_{T_pM \setminus W} \operatorname{H}^m\left(\frac{|x|}{\sqrt{t}}\right) |x|^k \, dx^n \\
				&\le t^{-\frac{n}{2}}\int_{T_pM \setminus B(o,r_0)} \operatorname{H}^m\left(\frac{|x|}{\sqrt{t}}\right) |x|^k \, dx^n \\
				&\leq \left(\frac{\alpha-1}{8}\right)^{\frac{m}{1-\alpha}} t^{\frac{m}{\alpha-1} - \frac{n}{2}} \int_{T_pM \setminus B(o,r_0)} |x|^{\frac{2m}{1-\alpha} + k} \, dx^n \\
				&= \left(\frac{\alpha-1}{8}\right)^{\frac{m}{1-\alpha}} \omega_{n-1} t^{\frac{m}{\alpha-1} - \frac{n}{2}} \int^{\infty}_{r_0} r^{\frac{2m}{1-\alpha} + n + k - 1} \, dr \\
				&= o(t^{\frac{k}{2}}) \quad \text{if } \frac{m}{\alpha-1} - \frac{n}{2} - \frac{k}{2} > 0,
			\end{aligned}
		\end{equation}
		we have
		\begin{equation}\label{estimate_Q_1}
			\begin{aligned}
				&\quad \left| t^{-\frac{n}{2}} \int_{T_pM \setminus W} \operatorname{H}^m\left(\frac{|x|}{\sqrt{t}}\right) Q_{m,1} \, dx^n \right| \\
				&\leq l_1 \left| t^{-\frac{n}{2}} \int_{T_pM \setminus B(o,r_0)} \left(1 + \frac{(\alpha-1)|x|^2}{8t}\right)^{\frac{m}{1-\alpha}} |x|^2 \, dx^n \right| \\
				&= o(t) \quad \text{ if } \frac{m}{\alpha-1} - \frac{n}{2} - 1 > 0,
			\end{aligned}
		\end{equation}
		and		
		\begin{equation}\label{estimate_Q_2}
			\begin{aligned}
				&\quad \left| t^{-\frac{n}{2}}\int_{T_pM\backslash W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})  \left(Q_{m,1}+Q_{m,2}\right) dx^n\right|\\
				&\le l_2\left| t^{-\frac{n}{2}}\int_{T_pM\backslash B(o,r_0)} \left(1+ \frac{(\alpha-1)|x|^2}{8t}\right)^{\frac{m}{1-\alpha}}|x|^4 dx^n\right|\\
				&= o(t^2) \quad \text{ if }\frac{m}{\alpha-1}-\frac{n}{2}-2>0,
			\end{aligned}
		\end{equation}
		where  we have used
		\begin{equation}\label{estimate_forQ}
			Q_{m,1}(x,t)\leq l_1|x|^2 \text{ and } Q_{m,1}(x,t)+Q_{m,2}(x,t)\le l_2|x|^4 \text{ for } x\in  T_pM\backslash B(o,r_0), 0<t\le 1,
		\end{equation}
		where $l_1$ and $l_2$ is a constant depending on $r_0$, $\alpha$, $n$, $m$,  $|\nabla^k\operatorname{\operatorname{Rm}}|(p)$ for $k=0,1,2$, and the expansion coefficients of $\xi^2$ in \eqref{expansion_of_xi}.

		By (\ref{3.1_e0}) and (\ref{3.1_e11}) with $q_1=0$ and $q_2=\frac{m}{1-\alpha}$, \eqref{def_Q_1}, \eqref{alphal1} and \eqref{estimate_Q_1}, we get
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-1>0$):
		\begin{equation}\label{D1st_1}
			\begin{aligned}
				&\quad   t^{-\frac{n}{2}}\int_{ W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})Q_{m,1} dx^n\\
				&= t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\operatorname{H}^m(\frac{|x|}{\sqrt{t}})Q_{m,1} dx^n\\
				&\xlongequal{y=\frac{x}{\sqrt{t}}}\int_{ T_pM}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}} Q_{m,1}(t^{\frac{1}{2}}y,t)dy^n+o(t)\\
				&=D_0(m)\left(1+\frac{D_1(m)}{D_0(m)}t\right)+o(t).
			\end{aligned}
		\end{equation}


		Moreover, by  (\ref{3.1_e0}), \eqref{3.1_e11} and (\ref{3.1_e21}) with $q_1=0$ and $q_2=\frac{m}{1-\alpha}$, \eqref{def_Q_2}, \eqref{alphal1}  and \eqref{estimate_Q_2}, we get
		for  either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-2>0$):
		\begin{equation}\label{D2rd_1}
			\begin{aligned}
				&\quad   t^{-\frac{n}{2}}\int_{ W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})\left(Q_{m,1}+Q_{m,2}\right) dx^n\\
				&= t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\operatorname{H}^m(\frac{|x|}{\sqrt{t}})\left(Q_{m,1}+Q_{m,2}\right) dx^n\\
				&\xlongequal{y=\frac{x}{\sqrt{t}}}\int_{ T_pM}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}} \left(Q_{m,1}(t^{\frac{1}{2}}y,t)+Q_{m,2}(t^{\frac{1}{2}}y,t)\right)dy^n+o(t^2)\\
				&=D_0(m)\left(1+\frac{D_1(m)}{D_0(m)}t+\frac{D_2(m)}{D_0(m)}t^2\right)+o(t^2)
			\end{aligned}
		\end{equation}
		where we have used that $\int_{ T_pM} \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{1}{1-\alpha}} \left\{\frac{m}{2}\left(e_{ijk}y^iy^jy^k+q_i y^i\right)-\frac{1}{12} \nabla_k R_{ij}(p) y^i y^j y^k\right\}t^{\frac{3}{2}}dy^n=0$ since
		the integral over one hemisphere cancels the integral over the other. 

		For any function $F(x)=o(|x|^k)$ and $F(x)$  bounded on $W$,
		we have
		\begin{equation}\label{reason}
			\begin{aligned}
				&\quad   \left|t^{-\frac{n}{2}}\int_{ W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})F(x)dx^n \right|\\
				&\xlongequal{y=\frac{x}{\sqrt{t}}} \left|\int_{ t^{-\frac{1}{2}}W}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}} o(t^{\frac{k}{2}}|y|^k)dy^n\right|\\
				&\le  t^{\frac{k}{2}}\int_{ T_pM}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}}  \frac{o(t^{\frac{k}{2}}|y|^k)}{t^{\frac{k}{2}}|y|^k}|y|^k dy^n\\
				&=o(t^{\frac{k}{2}}) \text{ if either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-\frac{k}{2}>0)$},
			\end{aligned}
		\end{equation}
		where we have used $\int_{ T_pM}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}} |y|^k dy^n<\infty$  if either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-\frac{k}{2}>0$), so $\int_{ T_pM}  \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{m}{1-\alpha}}  \frac{o(t^{\frac{k}{2}}|y|^k)}{t^{\frac{k}{2}}|y|^k}|y|^k dy^n\to 0$ by Lebesgue dominated theorem.
		Since $\left(Q_{m,2}+P\right)=o(|x|^2)+O(|x|)t+o(t)$, we have 
		\begin{equation}\label{D1st_2}
			\begin{aligned}
				\left|t^{-\frac{n}{2}}\int_{ W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})\left(Q_{m,2}+P\right)dx^n \right|=o(t)
				\text{ for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-1>0$)},
			\end{aligned}
		\end{equation}
		and   since $	P = o(|x|^2)t+o(|x|^4)+o(1)t^2$, we have
		\begin{equation}\label{D2rd_2}
			\begin{aligned}
				\left|t^{-\frac{n}{2}}\int_{ W} \operatorname{H}^m(\frac{|x|}{\sqrt{t}})Pdx^n \right|=o(t^2)  \text{ for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{m}{\alpha-1}-\frac{n}{2}-2>0$)}.
			\end{aligned}
		\end{equation}


		\textbf{Then \eqref{expansion_D1st} follows from \eqref{D1st_1} and \eqref{D1st_2}, and
			\eqref{expansion_D2rd} follows from \eqref{D2rd_1} and \eqref{D2rd_2}.}



		\textbf{(ii)} We calculate 
		\begin{equation}\label{term2}
			\begin{aligned}
				&\quad  t^{1-\frac{n}{2}}  \int_V \left|\nabla
				\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)\right|^2 d\mu  	\\
				&=t^{1-\frac{n}{2}}  \int_W\left| \left\{ - \frac{|x|\nabla |x|}{4t\left(1+ \frac{(\alpha-1)|x|^2}{8t}\right)_+} \xi+\nabla\xi\right\}\left(1+ \frac{(\alpha-1)|x|^2}{8t}\right)_+^{\frac{1}{1-\alpha}} \right|^2\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n\\
				&=  t^{-\frac{n}{2}}  \int_W\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\xi^2 \operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n+t^{1-\frac{n}{2}}  \int_W\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)|\nabla \xi|^2\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n \\
				&\quad -\frac{1}{8}t^{-\frac{n}{2}}  \int_W\operatorname{H}^{1+\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\langle \nabla|x|^2,  \nabla\xi^2 \rangle\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n.	
			\end{aligned}
		\end{equation}
		\textbf{Next, we calculate each term of \eqref{term2} separately.}

		\textbf{First, we calculate the first term in \eqref{term2}.}
		Applying \eqref{key_lemma_term1} with $m=2$,(\ref{3.1_e0}) and (\ref{3.1_e11}) with $q_1=2$, $q_2=\frac{2\alpha}{1-\alpha}$,   
		we get for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$):
		\begin{equation}\label{expansion_A1st_i}
			\begin{aligned}
				&t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\xi^2(x,t)\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}dx^n\\
				=&t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)Q_{2,1}dx^n+t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\left(Q_{2,2}+P\right)dx^n\\
				\xlongequal{y=\frac{x}{\sqrt{t}}}&
				\int_{T_pM} \frac{|y|^2}{16}\left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{2\alpha}{1-\alpha}} \xi^2(t^{\frac{1}{2}}y,t)	Q_{2,1}(t^{\frac{1}{2}}y,t)dy^n \\
				=& A_0\left\{1+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{tr}(\textbf{a})-\frac{1}{6}\operatorname{Sc}(p)\right)t+\beta_1 t\right\}+o(t),
			\end{aligned}
		\end{equation}
		where we have used  
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{-\frac{n}{2}}\int_{T_pM\backslash W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right) Q_{2,1} dx^n\right|= o(t),\\
				&\left|t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\left(Q_{2,2}+P\right) dx^n\right|=o(t)
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_forQ} with $m=2$, 
		\eqref{estimate_Q}   with $k=4$  and  \eqref{reason}  with $k=4$. 

		Moreover, applying (\ref{3.1_e0}), (\ref{3.1_e11})  and (\ref{3.1_e21}) with $q_1=2$, $q_2=\frac{2\alpha}{1-\alpha}$,  \eqref{key_lemma_term1} with $m=2$, 
		we get for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}\label{expansion_A2rd_i}
			\begin{aligned}
				&t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\xi^2(x,t)\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}dx^n\\
				=&t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)\left(Q_{2,1}+Q_{2,2}\right)dx^n+t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)Pdx^n\\
				\xlongequal{y=\frac{x}{\sqrt{t}}}&
				\int_{T_pM} \frac{|y|^2}{16}\left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{2\alpha}{1-\alpha}} \xi^2(t^{\frac{1}{2}}y,t)	\left(Q_{2,1}+Q_{2,2}\right)(t^{\frac{1}{2}}y,t)dy^n +o(t^2)\\
				=& A_0\left\{1+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{tr}(\textbf{a})-\frac{1}{6}\operatorname{Sc}(p)\right)t+\beta_1 t\right.\\
				&	+
				\frac{1}{n(n+2)}	\left(\frac{|\alpha-1|}{8}\right)^{-2}\frac{\mathscr{B}(\frac{n}{2}+3,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{E}(b)+\operatorname{E}(v)-\frac{1}{6}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\right)t^2\\
				&\left.+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(\operatorname{tr}(d)-\frac{1}{6}\beta_1\operatorname{Sc}(p)\right)t^2+\beta_2t^2\right\}+o(t^2),
			\end{aligned}
		\end{equation}
		where we have used 
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{-\frac{n}{2}}\int_{T_pM\backslash W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right) \left(Q_{2,1}+Q_{2,2}\right) dx^n\right|= o(t^2),\\
				&\left|t^{-\frac{n}{2}}\int_{ W}\frac{|x|^2}{16t}\operatorname{H}^{2\alpha}\left(\frac{|x|}{\sqrt{t}}\right)P dx^n\right|=o(t^2),
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_forQ} with $m=2$, 
		\eqref{estimate_Q}   with $k=6$  and  \eqref{reason}  with $k=6$.

		\textbf{Second, we calculate the second term in \eqref{term2}.}
		We calculate that
		\begin{equation}\label{second_term_nabla}
			\begin{aligned}
				&\quad |\nabla \xi|^2\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}= \frac{|\nabla \xi^2|^2}{4\xi^2}\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&=\frac{|\nabla \phi_0|^2+tO(d)+O(t^2)}{4\xi^2}\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&=\frac{\sum\limits_{k=1}| \frac{\partial}{\partial x^k} (\textbf{a}_{ij}x^ix^j)|^2+o(d^2)+tO(d)+O(t^2)}{4\xi^2}\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&=\sum_{i=1} \textbf{a}_{ij}\textbf{a}_{ik}x^jx^k+o(d^2)+tO(d)+O(t^2).
			\end{aligned}
		\end{equation}
		Hence, we can write $|\nabla \xi|^2\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}=o(|x|^s)+O(t)$ on $W$ for all $0<s\le 1$. By \eqref{reason}, we have
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2}{\alpha-1}-\frac{n}{2}=\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$): take $s$ small enough such that $\frac{2}{\alpha-1}-\frac{n+s}{2}>0$ if $\alpha>1$ and  $0<s\le 1$ if $0<\alpha<1$ ,
		\begin{equation}\label{expansion_A1st_ii}
			\begin{aligned}
				&t^{1-\frac{n}{2}}\int_V\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)|\nabla \xi|^2d\mu\\
				=&t^{1-\frac{n}{2}}\int_{W}\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)\left(o(|x|^s)+O(t)\right)dx^n\\
				\xlongequal{y=\frac{x}{\sqrt{t}}}& t\int_{W}\left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{2}{1-\alpha}}\left(\frac{o(t^{\frac{s}{2}}|y|^s)}{t^{\frac{s}{2}}|y|^s}t^{\frac{s}{2}}|y|^s+O(t)\right)dy^n\\
				=& o(t).
			\end{aligned}
		\end{equation}
		Moreover, applying \eqref{second_term_nabla}, (\ref{3.1_e11}) with $q_1=0$ and $q_2=\frac{2}{1-\alpha}$, we get for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2}{\alpha-1}-\frac{n}{2}-1=\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}\label{expansion_A2rd_ii}
			\begin{aligned}
				&t^{1-\frac{n}{2}}\int_V\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)|\nabla \xi|^2d\mu\\
				=&t^{1-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)\left(\sum_{i=1} \textbf{a}_{ij}\textbf{a}_{ik}x^jx^k\right)dx^n\\
				&+t^{1-\frac{n}{2}}\int_{T_pM}\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)\left(o(|x|^2)+tO(|x|)+O(t^2)\right)dx^n\\
				\xlongequal{y=\frac{x}{\sqrt{t}}}& t\int \left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{2}{1-\alpha}}\left(\sum_{i=1} \textbf{a}_{ij}\textbf{a}_{ik}y^jy^kt\right)dy^n+o(t^2) \\
				=& A_0\cdot\frac{16}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(\textbf{a}^2)t^2+o(t^2),
			\end{aligned}
		\end{equation}
		where we have used 
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2}{\alpha-1}-\frac{n}{2}-1>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{1-\frac{n}{2}}\int_{T_pM\backslash W}\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)\left(\sum_{i=1} \textbf{a}_{ij}\textbf{a}_{ik}x^jx^k\right) dx^n\right|= o(t^2),\\
				&\left|t^{1-\frac{n}{2}}\int_{ W}\operatorname{H}^{2}\left(\frac{|x|}{\sqrt{t}}\right)\left(o(|x|^2)+tO(|x|)+O(t^2)\right) dx^n\right|=o(t^2),
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_Q} with $k=2$ and $m=2$, \eqref{reason}.  

		\textbf{Third, we calculate the third term in \eqref{term2}.}
		We calculate that 
		\begin{equation*}
			\begin{aligned}
				&\quad\left(\nabla d^2 \cdot \nabla \xi^2\right)\operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&	= g^{rs} \frac{\partial d^2}{\partial x_r} \frac{\partial \xi^2}{\partial x_s} \operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&	= \left(\delta_{rs}+\frac{1}{3}R_{rijs}(p)x^ix^j+O(d^3)\right) \frac{\partial d^2}{\partial x_r} \frac{\partial \xi^2}{\partial x_s} \operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2}\\
				&= 4\textbf{a}_{ij}x^ix^j+T+P,
			\end{aligned}
		\end{equation*}
		where
		$$
		\begin{aligned}
			T := \left(6e_{ijk}x^ix^jx^k+2q_ix^it\right)+\left(4d_{ij}x^ix^j t+8b_{ijkl}x^ix^jx^kx^l-\frac{2}{3}\textbf{a}_{ij}R_{kl}(p)x^ix^jx^kx^l+\frac{4}{3}\sum_r R_{ijkr}(p)\textbf{a}_{rl}x^ix^jx^kx^l\right) ,
		\end{aligned}
		$$
		$$
		\begin{aligned}
			P  := o(|x|^2)t+o(|x|^4)+o(1)t^2.
		\end{aligned}
		$$
		Applying (\ref{3.1_e0})-(\ref{3.1_e21}) with $q_1=0$, $q_2=\frac{1+\alpha}{1-\alpha}=\frac{2\alpha}{1-\alpha}+1$,
		we get for
		either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$):
		\begin{equation}\label{expansion_A1st_iii}
			\begin{aligned}
				&\quad -t^{-\frac{n}{2}}\int_W\frac{1}{8}\operatorname{H}^{1+\alpha} \langle \nabla|x|^2,  \nabla\xi^2 \rangle \operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n \\
				&= -t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\frac{1}{8}\operatorname{H}^{1+\alpha} 4\textbf{a}_{ij}x^ix^jdx^n-t^{-\frac{n}{2}}\int_{W}\frac{1}{8}\operatorname{H}^{1+\alpha} \left(T+P\right)dx^n \\
				&\xlongequal{y=\frac{x}{\sqrt{t}}} -\int \frac{1}{8}\left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{1+\alpha}{1-\alpha}}  4\textbf{a}_{ij}y^iy^jtdy^n +o(t)\\
				&= -A_0\cdot\frac{8}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(\textbf{a})t+o(t),
			\end{aligned}
		\end{equation}
		where we have used
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-2>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{-\frac{n}{2}}\int_{T_pM\backslash W}\frac{1}{8}\operatorname{H}^{1+\alpha} 4\textbf{a}_{ij}x^ix^jdx^n\right|= o(t),\\
				&\left|t^{-\frac{n}{2}}\int_{ W}\frac{1}{8}\operatorname{H}^{1+\alpha} \left(T+P\right) dx^n\right|=o(t),
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_Q} with $k=2$ and $m=1+\alpha$,
		\eqref{reason}.

		Moreover, applying (\ref{3.1_e0}), (\ref{3.1_e11}) and (\ref{3.1_e21}) with $q_1=0$, $q_2=\frac{1+\alpha}{1-\alpha}=\frac{2\alpha}{1-\alpha}+1$,
		we get for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}\label{expansion_A2rd_iii}
			\begin{aligned}
				&\quad -t^{-\frac{n}{2}}\int_W\frac{1}{8}\operatorname{H}^{1+\alpha} \langle \nabla|x|^2,  \nabla\xi^2 \rangle \operatorname{det}\left(g_{k \ell}(x)\right)^\frac{1}{2} dx^n \\
				&= -t^{-\frac{n}{2}}\left(\int_{T_pM}-\int_{T_pM\backslash W}\right)\frac{1}{8}\operatorname{H}^{1+\alpha} \left( 4\textbf{a}_{ij}x^ix^j+T\right) dx^n-t^{-\frac{n}{2}}\int_{W}\frac{1}{8}\operatorname{H}^{1+\alpha} Pdx^n\\
				&\xlongequal{y=\frac{x}{\sqrt{t}}} -\int \frac{1}{8}\left(1+ \frac{(\alpha-1)|y|^2}{8}\right)_+^{\frac{1+\alpha}{1-\alpha}}  \left( 4\textbf{a}_{ij}y^iy^jt+T(t^{\frac{1}{2}}y,t)\right)dy^n +o(t^2)\\
				&= A_0\left\{-\frac{8}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(\textbf{a})t-\frac{8}{n}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\operatorname{tr}(d)t^2\right.\\
				&	\left.\quad +
				\frac{1}{n(n+2)}	\left(\frac{|\alpha-1|}{8}\right)^{-1}\frac{\mathscr{B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+2)}{\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}\left(-16\operatorname{E}(b)+\frac{4}{3}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\right)t^2\right\}+o(t^2),
			\end{aligned}
		\end{equation}
		where we have used 
		$$
		E(\sum_rR_{ijkr}(p)\textbf{a}_{rl})=\sum\limits_{i, j}\sum_r\left(R_{iijr}(p)\textbf{a}_{rj}+R_{ijir}(p)\textbf{a}_{rj}+R_{ijjr}(p)\textbf{a}_{ri}\right)=0.
		$$
		and
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and  $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{-\frac{n}{2}}\int_{T_pM\backslash W}\frac{1}{8}\operatorname{H}^{1+\alpha} \left(4\textbf{a}_{ij} +T\right)dx^n\right|= o(t^2),\\
				&\left|t^{-\frac{n}{2}}\int_{ W}\frac{1}{8}\operatorname{H}^{1+\alpha} P dx^n\right|=o(t^2).
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_Q} with $k=4$ and $m=1+\alpha$, \eqref{reason}.


		\textbf{Then \eqref{expansion_A1st} follows from \eqref{expansion_A1st_i}, \eqref{expansion_A1st_ii} and \eqref{expansion_A1st_iii}. Then \eqref{expansion_A2rd} follows from \eqref{expansion_A2rd_i}, \eqref{expansion_A2rd_ii} and \eqref{expansion_A2rd_iii}.}

		(iii)
		Also notice that when $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$), we have
		\begin{equation}\label{term7}
			\begin{aligned}
				&\quad 	 
				t^{1-\frac{n}{2}}  \int_V \operatorname{Sc}(x)\cdot  \left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi(x,t)\right)^2  d\mu 
				\\
				&= 	t^{1-\frac{n}{2}} \int_{W} \left(\operatorname{Sc}(p)+\nabla_i\operatorname{Sc}(p)x^i+\frac{1}{2}\nabla_i\nabla_j \operatorname{Sc}(p) x^i x^j+o(|x|^2)\right)\\
				&\times
				\left(1+\textbf{a}_{ij}x^ix^j+o(|x|^2)+\beta_1 t+o(t)\right)\times (1-\frac{1}{6} R_{ij}(p) x^i x^j+o(|x|^2))\operatorname{H}^2(\frac{|x|}{\sqrt{t}})dx^n	\\
				&= 	t^{1-\frac{n}{2}} \left(\int_{T_pM}- \int_{T_pM\backslash W}\right)\left(\operatorname{Sc}(p)+\frac{1}{2}\nabla_i\nabla_j \operatorname{Sc}(p) x^i x^j+\operatorname{Sc}(p)\textbf{a}_{ij} x^i x^j-\frac{1}{6}\operatorname{Sc}(p) R_{ij}(p)x^i x^j+\beta_1 \operatorname{Sc}(p) t\right)\operatorname{H}^2(\frac{|x|}{\sqrt{t}})dx^n\\
				&\quad+t^{1-\frac{n}{2}} \int_{W} \left(o(|x|^2)+o(t)\right)\operatorname{H}^2(\frac{|x|}{\sqrt{t}})dx^n\\
				&\xlongequal{y=\frac{x}{\sqrt{t}}} 	t\int_{T_pM} \left(\operatorname{Sc}(p)+\frac{1}{2}\nabla_i\nabla_j \operatorname{Sc}(p) y^i y^j t+\operatorname{Sc}(p)\textbf{a}_{ij} y^i y^j t-\frac{1}{6}\operatorname{Sc}(p) R_{ij}(p)y^i y^jt+\beta_1 \operatorname{Sc}(p) t\right)\operatorname{H}^2(|y|)dy^n\\
				& \quad+o(t^2)+t \int_{W} \left(o(t|y|^2)+o(t)\right)\operatorname{H}^2(|y|)dy^n\\
				&=\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)\times\\
				&\Big\{\operatorname{Sc}(p)t+\frac{1}{n}\left(\frac{|\alpha-1|}{8}\right)^{-1}	\frac{\mathscr{B}(\frac{n}{2}+1,\frac{2}{1-\alpha}+1)}{\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2\Big\}+o(t^2),
			\end{aligned}
		\end{equation}
		where we have used 
		for either $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and  $\frac{2\alpha}{\alpha-1}-\frac{n}{2}-3>0$):
		\begin{equation}
			\begin{aligned}
				&\left| t^{1-\frac{n}{2}}\int_{T_pM\backslash W}\left(\operatorname{Sc}(p)+\frac{1}{2}\nabla_i\nabla_j \operatorname{Sc}(p) x^i x^j+\operatorname{Sc}(p)\textbf{a}_{ij} x^i x^j-\frac{1}{6}\operatorname{Sc}(p) R_{ij}(p)x^i x^j+\beta_1 \operatorname{Sc}(p) t\right)\operatorname{H}^2(\frac{|x|}{\sqrt{t}})\right|= o(t^2),\\
				&\left|t^{1-\frac{n}{2}} \int_{W} \left(o(|x|^2)+o(t)\right)\operatorname{H}^2(\frac{|x|}{\sqrt{t}})dx^n\right|=o(t^2),
			\end{aligned}
		\end{equation}
		by applying \eqref{estimate_Q} with $k=2$ and $m=2$, \eqref{reason}. 
	\end{proof}

	\section{ Power series expansion formulas of $\mathcal{L}^{\pm}_{\alpha}$-functionals and Proof of Theorem \ref{const_rigidity}}



	In this section, we derive the power series expansion formulas for the $\mathcal{L}^{\pm}_{\alpha}$-functionals, and subsequently provide the proof of Theorem~\ref{const_rigidity}.


	\begin{thm}\label{expansion_L_a}
		Let $(M^n,g)$ be an $n$-dimensional Riemannian manifold and $p\in V\subset \mathring{M^n}$, where $V$ is a neighborhood of $p$.


		\noindent (i)	 Denote
		\begin{equation}\label{def_u-}
			v_-(x,t):=(4\pi t )^{-\frac{n}{2(\alpha+1)}}\operatorname{H}(\frac{|x|}{\sqrt{t}}) \text{ and }  u_-:=\frac{v_-}{(\int_{T_pM}v_-^{\alpha+1}dx^n)^{\frac{1}{\alpha+1}}}=\frac{ t ^{-\frac{n}{2(\alpha+1)}}\operatorname{H}(\frac{|x|}{\sqrt{t}})}{D_0(\alpha+1)^{\frac{1}{\alpha+1}}}
		\end{equation}
		and $$\tau_-(t)^{1+2\Gamma_{\alpha}}:=\frac{\mathfrak{m}\Gamma_{\alpha}}{1+\Gamma_{\alpha}}\left(\frac{A_0}{D_0(\alpha+1)^{\frac{2}{\alpha+1}}}\right)^{-1}\frac{D_0(2\alpha)}{D_0(\alpha+1)^{\frac{2\alpha}{\alpha+1}}}t^{1+2\Gamma_{\alpha}}\footnote{ See \eqref{tau_connection} for the reason behind our choice of $\tau_{\pm}(t)$\label{llama3.2tau}}.$$ 
		Choose the function $\xi_-(x,t)$ has the expansion  \eqref{expansion_of_xi} such that  $\int_V (u_-\xi_-)^{\alpha+1}d\mu \equiv 1.$ 	

		When $0<\alpha<1$, we have 
		\begin{equation}\label{expansion_-}
			\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left(\zeta_1 \operatorname{Sc}(p)t-32\zeta_2\Delta \operatorname{Sc}(p)t^2+32\zeta_2\operatorname{\uppercase\expandafter{\romannumeral2}} t^2+\operatorname{\uppercase\expandafter{\romannumeral3}}^-t^2+o(t^2)\right),
		\end{equation}
		where
		\begin{equation}\label{see_why}
			\begin{aligned}
				&\operatorname{\uppercase\expandafter{\romannumeral2}} :=\chi\left|\textbf{a}-\frac{2(\alpha+1) \operatorname{Rc}(p)}{3\chi}\right|^2+\frac{4((n+5) \alpha-n-3)(\alpha-1) }{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p),
			\end{aligned}		
		\end{equation}
		\begin{equation}
			\zeta_1:=\frac{8}{n\left(n(\alpha-1)-4\right)},		\zeta_2:=\frac{\zeta_1}{8\left(n(\alpha-1)+2\alpha-6\right)},		\chi:=(n+6) \alpha^2-2(n+3)\alpha+ n+4.
		\end{equation}
		and
		$\operatorname{\uppercase\expandafter{\romannumeral3}}^-$ is a constant satisfying
		$
		\operatorname{\uppercase\expandafter{\romannumeral3}}^-=0 \text{ if } \operatorname{Sc}(p)=0 \text{ and } \operatorname{tr}(\textbf{a})=0$ \footnote{ For the proof of Theorem \ref{const_rigidity}, the exact value of $\operatorname{\uppercase\expandafter{\romannumeral3}}^{\pm}$ are not required. However, these precise values  become essential for Theorem \ref{Yamabe_rigidity}. We will compute
			the exact value of $\operatorname{\uppercase\expandafter{\romannumeral3}}^{\pm}$ in Lemma \ref{expansion_W_a}.\label{llama3.2}}. Here, $\textbf{a}$ is the tensor which defined in the expansion  \eqref{expansion_of_xi}.


		\noindent (ii)	 Denote 
		\begin{equation}\label{def_u+}
			v_+(x,t):=(4\pi t )^{-\frac{n}{4\alpha}}\operatorname{H}(\frac{|x|}{\sqrt{t}}) \text{ and } u_+:=\frac{v_+}{(\int_{T_pM}v_+^{2\alpha}dx^n)^{\frac{1}{2\alpha}}}=\frac{t ^{-\frac{n}{4\alpha}}\operatorname{H}(\frac{|x|}{\sqrt{t}})}{D_0(2\alpha)^{\frac{1}{2\alpha}}}, 
		\end{equation}
		and 
		$$\tau_+(t)^{1-\Theta_{\alpha}}:=\frac{\mathfrak{m}\Theta_{\alpha}}{1-2\Theta_{\alpha}}\left(\frac{A_0}{D_0(2\alpha)^{\frac{1}{\alpha}}}\right)^{-1}\frac{D_0(\alpha+1)}{ D_0(2\alpha)^{\frac{\alpha+1}{2\alpha}}}t^{1-\Theta_{\alpha}}
		\textsuperscript{\ref{llama3.2tau}}.$$
		Choose $\xi_+$  has the expansion  such that  
		$\int_V (u_+\xi_+)^{2\alpha}d\mu \equiv 1.$ \\
		When $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+4}{n}$,
		we have 
		\begin{equation}\label{expansion_+_1}
			\mathcal{L}^+_{\alpha}(V,g, u_+(x,t)\xi_+(x,t),\tau_+(t))=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}   \left(\zeta_1 \operatorname{Sc}(p)t+o(t)\right)
		\end{equation}
		Moreover, when $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$,
		we have 
		\begin{equation}\label{expansion_+_2}
			\mathcal{L}^+_{\alpha}(V,g, u_+(x,t)\xi_+(x,t),\tau_+(t))=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}   \left(\zeta_1 \operatorname{Sc}(p)t-32\zeta_2\Delta \operatorname{Sc}(p)t^2+32\zeta_2\operatorname{\uppercase\expandafter{\romannumeral2}} t^2+\operatorname{\uppercase\expandafter{\romannumeral3}}^+t^2+o(t^2)\right),
		\end{equation}
		and
		$\operatorname{\uppercase\expandafter{\romannumeral3}}^+$ is a constant satisfying
		$
		\operatorname{\uppercase\expandafter{\romannumeral3}}^+=0 \text{ if } \operatorname{Sc}(p)=0 \text{ and } \operatorname{tr}(\textbf{a})=0\textsuperscript{\ref{llama3.2}}.
		$


	\end{thm}
	\begin{proof} \textbf{(i)}
		By Lemma \ref{key_lemma},  we get for
		$0<\alpha<1$: 
		\begin{equation}\label{expan_c_i1}
			\begin{aligned}
				&\quad\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))\\
				&=\left(\frac{\mathfrak{m}\Gamma_{\alpha}}{1+\Gamma_{\alpha}}\left(\frac{A_0}{D_0(\alpha+1)^{\frac{2}{\alpha+1}}}\right)^{-1}\frac{D_0(2\alpha)}{D_0(\alpha+1)^{\frac{2\alpha}{\alpha+1}}}\right)^{\frac{1+\Gamma_{\alpha}}{1+2\Gamma_{\alpha}}}	D_0(\alpha+1)^{-\frac{2}{\alpha+1}} A_0 \left(A_0^{-1} t^{1-\frac{n}{2}}  \int_V \left|\nabla
				\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi_-(x,t)\right)\right|^2 d\mu \right)
				\\
				&\quad +\mathfrak{m}\left(\frac{\mathfrak{m}\Gamma_{\alpha}}{1+\Gamma_{\alpha}}\left(\frac{A_0}{D_0(\alpha+1)^{\frac{2}{\alpha+1}}}\right)^{-1}\frac{D_0(2\alpha)}{D_0(\alpha+1)^{\frac{2\alpha}{\alpha+1}}}\right)^{-\frac{\Gamma_{\alpha}}{1+2\Gamma_{\alpha}}}	D_0(\alpha+1)^{-\frac{2\alpha}{\alpha+1}} D_0(2\alpha)\left(D_0(2\alpha)^{-1}t^{-\frac{n}{2}}  \int_V 
				\left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi_-(x,t)\right)^{2\alpha}\right)\\
				&\quad -\frac{2\Gamma_{\alpha}+1}{\Gamma_{\alpha}}\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}+o(t^2)\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}\left(1+\frac{A_1}{A_0}t+\frac{A_2}{A_0}t^2+o(t^2)\right)
				+\frac{\Gamma_{\alpha}+1}{\Gamma_{\alpha}}m^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}\left(1+\frac{D_1(2\alpha)}{D_0(2\alpha)}t+\frac{D_2(2\alpha)}{D_0(2\alpha)}t^2+o(t^2)\right) \\
				&\quad -\frac{2\Gamma_{\alpha}+1}{\Gamma_{\alpha}}\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}+o(t^2)\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}\left\{\left(\frac{A_1}{A_0}+\frac{\Gamma_{\alpha}+1}{\Gamma_{\alpha}}\frac{D_1(2\alpha)}{D_0(2\alpha)}\right)t+\left(\frac{A_2}{A_0}+\frac{\Gamma_{\alpha}+1}{\Gamma_{\alpha}}\frac{D_2(2\alpha)}{D_0(2\alpha)}\right)t^2+o(t^2)\right\}\\		&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left\{\left(\frac{A_1}{A_0}+\frac{(1-\gamma)}{\gamma\alpha}\frac{D_1(2\alpha)}{D_0(2\alpha)}-\frac{2}{\gamma(\alpha+1)}\frac{D_1(\alpha+1)}{D_0(\alpha+1)}\right)t\right.\\
				&\left.\quad\quad+\left(\frac{A_2}{A_0}+\frac{(1-\gamma)}{\gamma\alpha}\frac{D_2(2\alpha)}{D_0(2\alpha)}-\frac{2}{\gamma(\alpha+1)}\frac{D_2(\alpha+1)}{D_0(\alpha+1)}\right)t^2+o(t^2)\right\},
			\end{aligned}		
		\end{equation}
		where we have used  
		$$
		\mathcal{N}_{\alpha,n} = \frac{A_0^{\frac{\gamma}{2}}D_0(2\alpha)^{\frac{1-\gamma}{2\alpha}}}{D_0(\alpha+1)^{\frac{1}{\alpha+1}}}, \quad 
		\Sigma^-_{\alpha} = \left(\frac{\Gamma_{\alpha}}{\Gamma_{\alpha}+1}\right)^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}} \mathcal{N}_{\alpha,n}^{\frac{2}{\gamma}\cdot\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}, \quad
		\frac{\Gamma_{\alpha}+1}{\Gamma_{\alpha}} = \frac{1-\gamma}{\gamma \alpha},
		$$
		and by 
		$
		\int_V (u_- \xi_-)^{\alpha+1} d\mu \equiv 1
		$
		and Lemma \ref{key_lemma}, 
		\begin{equation}\label{normal_1}
			\frac{D_1(\alpha+1)}{D_0(\alpha+1)} = 0 \quad \text{and} \quad \frac{D_2(\alpha+1)}{D_0(\alpha+1)} = 0.
		\end{equation}

		Observing from Lemma \ref{key_lemma},
		for $0<\alpha<1$, we can write that
		\begin{equation}\label{keylemma:1st}
			\begin{aligned}
				\frac{A_1}{A_0}+\frac{1-\gamma}{\gamma\alpha}\frac{D_1(2\alpha)}{D_0(2\alpha)}-\frac{2}{\gamma(\alpha+1)}\frac{D_1(\alpha+1)}{D_0(\alpha+1)}:=c_1^{-}\operatorname{Sc}(p)+l_1^{-}\beta_1+l_2^{-}\operatorname{tr}(\textbf{a})
			\end{aligned}		
		\end{equation}
		and
		\begin{equation}\label{ot2_term}
			\begin{aligned}
				&\frac{A_2}{A_0}+\frac{1-\gamma}{\gamma\alpha}\frac{D_2(2\alpha)}{D_0(2\alpha)}-\frac{2}{\gamma(\alpha+1)}\frac{D_2(\alpha+1)}{D_0(\alpha+1)}\\
				:=& c_2^{-}\operatorname{tr}(\textbf{a}^2)+c_3^{-}\operatorname{E}(v)+c_4^{-}\operatorname{E}(\textbf{a} \otimes \textbf{a})+c_5^{-}\operatorname{E}(\textbf{a} \otimes \operatorname{Rc})\\
				&+c_6^{-}\beta_1\operatorname{tr}(\textbf{a})+c_7^{-}\beta_1^2+c_8^{-}\beta_1 \operatorname{Sc}(p)+k_1^{-}\beta_2+k_2^{-}\operatorname{E}(b)+k_3^{-}\operatorname{tr}(d)
			\end{aligned}		
		\end{equation}
		Here, the constants  $c_i^{-}$, $l_i^{-}$ and $k_i^{-}$, depend only on $n$ and $\alpha$. 




		\textbf{We next calculate $c_1^{-}$, $c_2^{-}$, $c_3^{-}$, $c_4^{-}$ and $c_5^{-}$ term by term using the Lemma \ref{key_lemma}.}


		Using Lemma \ref{key_lemma} and \eqref{keylemma:1st}, we get
		\begin{equation}\label{c_1_-}
			\begin{aligned}
				c_1^-=& \frac{1}{6n}\left(\frac{|\alpha-1|}{8}\right)^{-1}\left\{-	\frac{\mathrm{~B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}-\frac{1-\gamma}{\gamma\alpha}\frac{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+1)}+\frac{2}{\gamma(\alpha+1)}\frac{\mathrm{~B}(\frac{n}{2}+1,\frac{1+\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2},\frac{1+\alpha}{1-\alpha}+1)}\right\}\\
				=&\frac{1}{6n}\left(\frac{1-\alpha}{8}\right)^{-1}\left(-\frac{\frac{n}{2}+1}{\frac{2\alpha}{1-\alpha}+\frac{n}{2}+2}-\frac{1-\gamma}{\gamma\alpha}\frac{\frac{n}{2}}{\frac{2\alpha}{1-\alpha}+\frac{n}{2}+1}+\frac{2}{\gamma(\alpha+1)}\frac{\frac{n}{2}}{\frac{1+\alpha}{1-\alpha}+\frac{n}{2}+1}\right)\\
				=&\zeta_1,
			\end{aligned}   
		\end{equation}
		where we have used 
		\begin{equation}\label{thm:beta_ii_1}
			\frac{\mathrm{~B}(p+1,q)}{\mathrm{~B}(p,q)}=\frac{p}{p+q} \text{ when $p>0$ and $q>0$.}
		\end{equation}
		The final simplification step is computed using the mathematical software Maple.

		Using Lemma \ref{key_lemma} and \eqref{ot2_term}, we get
		\begin{equation}\label{c_2_-}
			\begin{aligned}
				c_2^-=&\frac{16}{n}	\frac{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+3)}{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}=128(\alpha+1)\zeta_2,\\
				c_3^-=& \frac{1}{n(n+2)}\left(\frac{|\alpha-1|}{8}\right)^{-2}\left\{
				\frac{\mathrm{~B}(\frac{n}{2}+3,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2}+1,\frac{\alpha\gamma}{1-\alpha}+1)}
				+\frac{1-\gamma}{2\alpha}\frac{\mathrm{~B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+1)}\right.\\
				&\left.-\frac{2}{\gamma(1+\alpha)}\frac{\mathrm{~B}(\frac{n}{2}+2,\frac{1+\alpha}{1-\alpha}
					+1)}{\mathrm{~B}(\frac{n}{2},\frac{1+\alpha}{1-\alpha}
					+1)}  \right\}\\
				=&640\zeta_2,\\
