	Next, we prove Theorem~\ref{const_rigidity}. In fact, we establish a more general result (Theorem~\ref{mu_rigidity}), from which Theorem~\ref{const_rigidity} follows directly.


	\begin{thm}\label{mu_rigidity}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$, and let $V$ be an open bounded subset of $M^n$. 

		\noindent\textbf{(a) For the case $0<\alpha<1$:}
		\begin{enumerate}
			\item When $0<\alpha<1$,
			if there exists $\tau_0>0$ such that for all $\tau\le\tau_0$
			\begin{equation}\label{thm_comparison_iso_2_66}
				\mathbb{L}^-_{\alpha}(V,g, \tau)\ge -o(\tau),
			\end{equation}
			\textbf{then} the scalar curvature of $V$ satisfies
			$$
			\operatorname{Sc}(x)\le 0 \quad \text{for all } x \in V.
			$$	

			\item When $0<\alpha<1$,
			if there exists $\tau_0>0$ such that for all $\tau\le\tau_0$
			\begin{equation}\label{thm_comparison_iso_2_6}
				\mathbb{L}^-_{\alpha}(V,g, \tau)\ge -o(\tau^2),
			\end{equation}
			and if additionally
			\begin{equation}\label{thm_Rc_point_compare_68888}
				\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0, 
			\end{equation}
			\textbf{then} $V$ must be flat. Here, $\lambda_1(\operatorname{Rc})$ denotes the first eigenvalue of the Ricci tensor.

			\item When $\alpha$ satisfies the more restrictive range \eqref{6_i_3}, 
			if both \eqref{thm_comparison_iso_2_6}
			and
			\begin{equation}\label{thm_R_point_compare_6}
				\int_{V} \operatorname{Sc} \, d\mu \geq 0
			\end{equation}
			hold, \textbf{then} $V$ must be flat.
		\end{enumerate} 

		\noindent\textbf{(b) For the case $1<\alpha\le \frac{n}{n-2}$:}
		\begin{enumerate}
			\item When $\alpha$ satisfies the range \eqref{6_i_2},        
			if there exists  $\tau_0>0$ such that for all $\tau\le\tau_0$
			\begin{equation}\label{comparison_iso_2_66}
				\mathbb{L}^+_{\alpha}(V,g, \tau)\ge -o(\tau),
			\end{equation}
			\textbf{then} the scalar curvature satisfies 
			$$\text{$\operatorname{Sc}(x) \leq 0$ for all $x \in V$.}$$

			\item When $\alpha$ satisfies the more restrictive range \eqref{6_i_4666},
			if there exists $\tau_0>0$ such that for all $\tau\le\tau_0$
			\begin{equation}\label{comparison_iso_2_6}
				\mathbb{L}^+_{\alpha}(V,g, \tau)\ge -o(\tau^2),
			\end{equation}
			and if additionally
			\begin{equation}\label{thm_Rc_point_compare_6888866}
				\int_{V} \lambda_1(\operatorname{Rc}) \, d\mu \geq 0, 
			\end{equation}
			\textbf{then} $V$ must be flat. 


			\item When $\alpha$ satisfies the more restrictive range \eqref{6_i_4},if both \eqref{comparison_iso_2_6} and
			\begin{equation}\label{integral_nonnegative}
				\int_{V} \operatorname{Sc} \, d\mu \geq 0
			\end{equation}
			hold, \textbf{then} $V$ must be flat.
		\end{enumerate}
	\end{thm}

	\begin{proof}
		\textbf{(a)}\textbf{ First, we prove \textbf{(a)}(1).}
		For any $p\in V$,  we obtain from \eqref{expansion_-} and \eqref{thm_comparison_iso_2_66} that for $t$ small enough:
		\begin{equation}\label{lemma32:111}
			\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left(\zeta_1 \operatorname{Sc}(p)t+o(t)\right)\ge -o(t),
		\end{equation}
		where $u_-(x,t)$ and $\xi_-(x,t)$ are these used in Theorem \ref{expansion_L_a}.
		Since $\zeta_1 < 0$ when $0 < \alpha < 1$, by comparing the $O(t)$ term in \eqref{lemma32:111} we have
		\begin{equation}\label{lemma4.1_i}
			\text{$\operatorname{Sc}(x) \leq 0$ for all $x \in V$,}
		\end{equation}
		since $p$ is arbitrarily chosen. \textbf{This proves \textbf{(a)}(1)}. \textbf{	This proves \textbf{(a)}(2)}.

		\textbf{ Second, we prove \textbf{(a)}(2).}   By \eqref{lemma4.1_i}, we know that $
		\text{$\lambda_1(\operatorname{Rc})(x) \leq 0$ for all $x \in V$.}$ This together with \eqref{thm_Rc_point_compare_6888866} imply $\lambda_1(\operatorname{Rc})(x) \equiv 0$ on $V$, so $\operatorname{Rc} \equiv 0$ on $V$ by \eqref{lemma4.1_i}. Now  we take
		$
		\textbf{a}=0 
		$
		in \eqref{expansion_-}. Then we obtain from \eqref{expansion_-} and \eqref{thm_comparison_iso_2_6} that for $t$ small enough:
		\begin{equation}\label{6666666666666666666666}
			\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left(-\frac{32\zeta_2}{6}|\operatorname{Rm}|^2(p) t^2+o(t^2)\right)\ge -o(t^2),
		\end{equation}
		where we have used, by \eqref{III_-} and $\textbf{a}=0$, 
		\begin{equation}\label{lemma32:55}
			\mathrm{III}^-=C_1'(\alpha,n)\operatorname{Sc}^2(p)=0.
		\end{equation}
		Since $\zeta_2>0$, we conclude that $\operatorname{Rm}\equiv 0$ on $V$ by \eqref{6666666666666666666666} since $p$ is arbitrarily chosen.

		\textbf{ Third, we prove \textbf{(a)}(3).}
		\eqref{thm_R_point_compare_6}  together with \eqref{lemma4.1_i} imply $\operatorname{Sc}\equiv 0$ on $V$. Now we take $\xi_-(x,t)\in \mathscr{B}_p(V)$, that is, we take
		\begin{equation}\label{choosing_a}
			\textbf{a}=\frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p) 
		\end{equation}
		in \eqref{expansion_-}.
		Then we obtain from \eqref{expansion_-} and \eqref{thm_comparison_iso_2_6} that  for $t$ small enough:
		\begin{equation}\label{lemma32:1}
			\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left(\mathrm{II} t^2+o(t^2)\right)\ge -o(t^2),
		\end{equation}
		with 
		\begin{equation}\label{lemma32:5}
			\begin{aligned}
				&\mathrm{II} =32\zeta_2\left\{ \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right\},
			\end{aligned}
		\end{equation}
		where we have used, by \eqref{III_-} and \eqref{choosing_a}, 
		\begin{equation}\label{lemma32:55}
			\mathrm{III}^-=C_1''(\alpha,n)\operatorname{Sc}^2(p)=0.
		\end{equation}

		From the curvature decomposition, we get
		\begin{equation*}
			\operatorname{Rm}=W+\frac{1}{n-2} \left(\operatorname{Rc}-\frac{\operatorname{Sc}}{n}\right)\odot g+\frac{\operatorname{Sc}}{2n(n-1)} g\odot g,
		\end{equation*}
		and so
		\begin{equation}\label{orthogonal_decomposition}
			\begin{aligned}
				|\operatorname{Rm}|^2 &=\left|\operatorname { W }\right|^2+\left|\frac{1}{n-2} \stackrel{\circ}{\operatorname{Rc} } \odot g\right|^2+\left|\frac{\operatorname{Sc}}{2 n(n-1)} g \odot g\right|^2\\
				&= |W|^2+\frac{4}{n-2}|\operatorname{Rc}|^2-\frac{2}{(n-1)(n-2)} \operatorname{Sc}^2.
			\end{aligned}
		\end{equation}
		Since $\operatorname{Sc}(p)=0$, we obtain
		$$
		|\operatorname{Rm}|^2(p)\ge \frac{4}{n-2}|\operatorname{Rc}|^2(p).
		$$
		Consequently,
		\begin{equation*}
			\begin{aligned}
				&\mathrm{II} \le 32\zeta_2\left\{ \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}-\frac{4}{6(n-2)}\right\}|\operatorname{Rc}|^2(p).
			\end{aligned}
		\end{equation*}
		Combining this with  \eqref{lemma32:1}, and also note that $\zeta_2>0$ when $0<\alpha<1$ and $\operatorname{Sc}(p)=0$, we obtain
		$$
		\left(\frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}-\frac{4}{6(n-2)}\right)|\operatorname{Rc}|^2(p)\ge 0.
		$$
		This implies $|\operatorname{Rc}|(p) = 0$ if
		\begin{equation}\label{lemma32:2}
			\frac{4((n+5)\alpha - n - 3)(\alpha - 1)}{9\chi} - \frac{4}{6(n - 2)} < 0,
		\end{equation}
		and in this case, we  see from \eqref{lemma32:1} and \eqref{lemma32:5} that $|\operatorname{Rm}|(p) = 0$.

		Since $\chi>0$, \eqref{lemma32:2} is equivalent to
		\begin{equation}\label{lemma32:3}
			\left(2 n^2+3 n-38\right) \alpha^2+\left(-4 n^2-2 n+50\right) \alpha+2 n^2-n-24<0.
		\end{equation}
		Inequality \eqref{lemma32:3} always holds for $n=3$. For $n\ge 4$, \eqref{lemma32:3} is equivalent to
		$$
		\alpha\in A:=	\left(\frac{2 n^2+n-25-\sqrt{28 n^2-16 n-287}}{2 n^2+3 n-38},\frac{2 n^2+n-25+\sqrt{28 n^2-16 n-287}}{2 n^2+3 n-38}\right).
		$$

		Also note that  $0<\alpha<1$.  We conclude that 
		when $\alpha$ satisfies 
		the range \eqref{6_i_3} (i.e. $\alpha\in (0,1)\cap A $), the conditions \eqref{thm_comparison_iso_2_6} and \eqref{thm_R_point_compare_6} imply that $V$ must be flat.
		\textbf{	This proves \textbf{(a)}(3).}

		\textbf{(b)} \textbf{ First, we prove \textbf{(b)}(1).}
		For any $p\in V$, 
		when $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+4}{n}$,
		it follows from \eqref{expansion_+_1} and \eqref{comparison_iso_2_66} that
		\begin{equation}\label{lemma32:111222}
			\mathcal{L}^+_{\alpha}(V,g, u_+(x,t)\xi_+(x,t),\tau_+(t))=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}   \left(\zeta_1 \operatorname{Sc}(p)t+o(t)\right)\ge -o(t),
		\end{equation}
		where $u_+(x,t)$ and $\xi_+(x,t)$ are these used in Theorem \ref{expansion_L_a}.  
		Since $\zeta_1 < 0$ when $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+4}{n}$, by comparing the $O(t)$ term in \eqref{lemma32:111222} 	\begin{equation}\label{lemma4.1_ii}
			\text{$\operatorname{Sc}(x) \leq 0$ for all $x \in V$,}
		\end{equation}
		since $p$ is arbitrarily chosen.  Notice that the inequalities
		$
		1<\alpha\le \frac{n}{n-2} \quad \text{and} \quad 1<\alpha<\frac{n+4}{n}
		$
		are equivalent to say $\alpha$ belonging to the range range \eqref{6_i_2}.
		\textbf{	This proves \textbf{(b)}(1)}.

		\textbf{ Second, the proof of \textbf{(b)}(2) is similar to  \textbf{(a)}(2).}	 Notice that the inequalities
		$
		1<\alpha\le \frac{n}{n-2} \quad \text{and} \quad \alpha<\frac{n+6}{n+2}
		$
		are equivalent to say $\alpha$ belonging to the range range \eqref{6_i_4666}, which guarantees expansion \eqref{expansion_+_2}.

		\textbf{ Third, we prove \textbf{(b)}(3).}	
		\eqref{integral_nonnegative}  together with \eqref{lemma4.1_ii} imply $\operatorname{Sc}\equiv 0$ on $V$.
		Now we take $\xi_+(x,t)\in \mathscr{B}_p(V)$, that is, we take
		\begin{equation}\label{choosing_aa}
			\textbf{a}=\frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p)  
		\end{equation}
		in \eqref{expansion_+_2}.
		Then we obtain from \eqref{expansion_+_2} and \eqref{comparison_iso_2_6} that when $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$,
		\begin{equation}
			\mathcal{L}^+_{\alpha}(V,g, u_+(x,t)\xi_+(x,t),\tau_+(t))=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}  \left(\mathrm{II} t^2+o(t^2)\right)\ge -o(t^2),
		\end{equation}
		with $\zeta_2>0$ and
		\begin{equation}
			\begin{aligned}
				&\mathrm{II} =32\zeta_2\left\{ \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right\},
			\end{aligned}
		\end{equation}
		where we have used, by \eqref{III_+} and \eqref{choosing_aa}, 
		\begin{equation}
			\mathrm{III}^+=C_2'(\alpha,n)\operatorname{Sc}^2(p)=0.
		\end{equation}

		When $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$, following similar arguments as in part (a) (2), 
		we can conclude that if \eqref{lemma32:3} holds, $|\operatorname{Rm}|(p)=0$. Note that
		the range \eqref{6_i_4} is equivalent to $\alpha$ satisfying \eqref{lemma32:3}, $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$. \textbf{This proves \textbf{(b)}(3).}

	\end{proof}

	Now we give the proof of Theorem \ref{const_rigidity}.
	\begin{proof}[Proof of Theorem \ref{const_rigidity}:]
		Theorem  \ref{const_rigidity} follows directly from Theorem \ref{mu_rigidity} and Theorem \ref{connection}.
