	\section{ Power series expansion formulas of $\mathcal{W}^{\pm}_{\alpha}$-functionals and Proof of Theorem \ref{Yamabe_rigidity}}



	In this section, we derive the power series expansion formulas for the $\mathcal{W}^{\pm}_{\alpha}$-functionals and subsequently provide the proof of Theorem~\ref{Yamabe_rigidity}.
	\begin{lem}\label{expansion_W_a}
		We use the same notation as in Theorem \ref{expansion_L_a},
		and we choose $\xi_{\pm} \in \mathscr{B}_p(V)$, i.e. we take
		$
		\textbf{a}=\frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p)
		$
		in \eqref{expansion_of_xi}. \\
		\noindent (i)	 
		For $0<\alpha<1$, we have 
		\begin{equation}\label{expansion_W-}
			\begin{aligned}
				&\quad\mathcal{W}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left\{32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+j^-(\alpha,n)\operatorname{Sc}^2(p)t^2+o(t^2)\right\},
			\end{aligned}
		\end{equation}
		where $j^-(\alpha,n)$ is a constant depending on $\alpha$ and $n$ that satisfies
		$$j^-(\alpha,n)\to 0 \text{ as } \alpha\to 1.$$



		\noindent (ii)	
		For $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$,
		we have 
		\begin{equation}\label{expansionW_+_2}
			\begin{aligned}
				&\quad\mathcal{W}^+_{\alpha}(V,g, u_+(x,t)\xi_+(x,t),\tau_+(t))\\
				&=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha} \left\{32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+j^+(\alpha,n)\operatorname{Sc}^2(p)t^2+o(t^2)\right\},
			\end{aligned}
		\end{equation}
		where $j^+(\alpha,n)$ is a constant depending on $\alpha$ and $n$ that satisfies
		$$j^+(\alpha,n)\to 0 \text{ as } \alpha\to 1.$$

	\end{lem}

	\begin{proof}
		(i)   By Lemma \ref{key_lemma} (iii), we get for $0<\alpha<1$:
		\begin{equation}\label{sc_expansion_-}
			\begin{aligned}
				&\quad 	 
				\frac{1}{2(1+\alpha)}\tau^{\Gamma_{\alpha}+1} \int_V \operatorname{Sc}(x) \cdot \left( u_-(x,t)\xi_-(x,t)\right)^2 d\mu
				\\
				&=\frac{1}{2(1+\alpha)}\left(\frac{\mathfrak{m}\Gamma_{\alpha}}{1+\Gamma_{\alpha}}\left(\frac{A_0}{D_0(\alpha+1)^{\frac{2}{\alpha+1}}}\right)^{-1}\frac{D_0(2\alpha)}{D_0(\alpha+1)^{\frac{2\alpha}{\alpha+1}}}\right)^{\frac{1+\Gamma_{\alpha}}{1+2\Gamma_{\alpha}}}	D_0(\alpha+1)^{-\frac{2}{\alpha+1}} A_0\left(A_0^{-1} t^{1-\frac{n}{2}}   \int_V \operatorname{Sc}(x)\cdot  \left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi_-(x,t)\right)^2 d\mu \right)\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}{2(1+\alpha)A_0}\times\\
				&\Big\{\operatorname{Sc}(p)t-\frac{8}{n(\alpha-1)+2\alpha-6}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2+o(t^2)\Big\}\\
				&=-\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \zeta_1\Big\{\operatorname{Sc}(p)t-\frac{8}{n(\alpha-1)+2\alpha-6}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2+o(t^2)\Big\}\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \Big\{-\zeta_1\operatorname{Sc}(p)t+32\zeta_2\Delta \operatorname{Sc}(p)t^2+\left(-\frac{32\zeta_2}{3}\operatorname{Sc}^2(p)+64\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)-\zeta_1\beta_1  \operatorname{Sc}(p)\right)t^2+o(t^2)\Big\},
			\end{aligned}
		\end{equation}
		where we have used $\left(\frac{\Gamma_{\alpha}}{1+\Gamma_{\alpha}}\left(\frac{A_0}{D_0(\alpha+1)^{\frac{2}{\alpha+1}}}\right)^{-1}\frac{D_0(2\alpha)}{D_0(\alpha+1)^{\frac{2\alpha}{\alpha+1}}}\right)^{\frac{1+\Gamma_{\alpha}}{1+2\Gamma_{\alpha}}}	D_0(\alpha+1)^{-\frac{2}{\alpha+1}} A_0=\Sigma^-_{\alpha} $ and, by \eqref{thm:beta_eq_1},
		$$
		\frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}{2(1+\alpha)A_0}=\frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathrm{B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+3)}{2(1+\alpha)\frac{\omega_{n-1}}{32}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+2}{2}}\mathrm{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}=-\zeta_1.
		$$

		Since 
		\begin{equation}\label{choose_a}
			\textbf{a}=\frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p),
		\end{equation}
		we have that, by \eqref{expansion_-},
		\begin{equation}
			\begin{aligned}
				&\quad\mathcal{W}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))\\
				&=\mathcal{L}^-_{\alpha}(V,g, u_-(x,t)\xi_-(x,t),\tau_-(t))+\frac{1}{2(1+\alpha)}\tau^{\Gamma_{\alpha}+1} \int_V \operatorname{Sc}(x) \cdot \left( u_-(x,t)\xi_-(x,t)\right)^2 d\mu\\
				&=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha} \left\{32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+\operatorname{\uppercase\expandafter{\romannumeral3}}^- t^2\right.\\
				&\left.\quad+\left(-\frac{32\zeta_2}{3}\operatorname{Sc}^2(p)+64\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)-\zeta_1\beta_1  \operatorname{Sc}(p)\right)t^2+o(t^2)\right\}.
			\end{aligned}
		\end{equation}
		Here, by \eqref{III_-}, we have
		\begin{equation}
			\begin{aligned}
				\operatorname{\uppercase\expandafter{\romannumeral3}}^-=&\frac{c_3^-}{72}\operatorname{Sc}^2(p)+c_4^-(\operatorname{tr}(\textbf{a}))^2 +c_5^-\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)+c_6^-\beta_1\operatorname{tr}(\textbf{a})+c_7^-\beta_1^2+c_8^-\beta_1 \operatorname{Sc}(p).
			\end{aligned}
		\end{equation}

		\textbf{We need to calculate $c_6^{-}$, $c_7^{-}$, $c_8^{-}$ in \eqref{III_-}.}
		By Lemma \ref{key_lemma}, \eqref{ot2_term}, \eqref{thm:beta_ii_1} and \eqref{thm:beta_eq_1}, we have
		$$
		\begin{aligned}
			c_6^-=& \frac{1}{n}	\left(\frac{|\alpha-1|}{8}\right)^{-1}\left(\frac{1-\gamma}{\gamma\alpha}\frac{2\alpha(\alpha-2)}{4}\frac{\mathrm{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+1)}-\frac{2}{\gamma(1+\alpha)}\frac{(\alpha+1)(\alpha-1)}{4}\frac{\mathrm{B}(\frac{n}{2}+1,\frac{1+\alpha}{1-\alpha}+1)}{\mathrm{B}(\frac{n}{2},\frac{1+\alpha}{1-\alpha}+1)}\right)\\
			=&\frac{-4(\alpha-1)^2 n-8 \alpha^2+24 \alpha}{n(n(\alpha-1)-4)}=\frac{-(\alpha-1)^2 n-2 \alpha^2+6 \alpha}{2}\zeta_1,\\
			c_7^-=& \left(\frac{1-\gamma}{\gamma\alpha}\frac{2\alpha(2\alpha-2)}{8}-\frac{2}{\gamma(1+\alpha)}\frac{(\alpha+1)(\alpha-1)}{8}\right)\\
			=&\frac{(n-2) \alpha^2-2( n+1) \alpha+n}{4 n},
		\end{aligned}
		$$
		and
		$$
		\begin{aligned}
			c_8^-=& \frac{1}{6n}\left(\frac{|\alpha-1|}{8}\right)^{-1}\left\{-	\frac{\mathrm{~B}(\frac{n}{2}+2,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}-\frac{1-\gamma}{\gamma}\frac{\mathrm{~B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+1)}+\frac{1}{\gamma}   \frac{\mathrm{~B}(\frac{n}{2}+1,\frac{1+\alpha}{1-\alpha}+1)}{\mathrm{~B}(\frac{n}{2},\frac{1+\alpha}{1-\alpha}+1)}\right\}\\
			=&\frac{1}{6n}\left(\frac{|\alpha-1|}{8}\right)^{-1}\left(-\frac{\frac{n}{2}+1}{\frac{2\alpha}{1-\alpha}+\frac{n}{2}+2}-\frac{1-\gamma}{\gamma}\frac{\frac{n}{2}}{\frac{2\alpha}{1-\alpha}+\frac{n}{2}+1}+\frac{2}{\gamma}\frac{\frac{n}{2}}{\frac{1+\alpha}{1-\alpha}+\frac{n}{2}+1}\right)\\
			=&\frac{\alpha+1}{3}\zeta_1.
		\end{aligned}
		$$	
		The final simplification steps are computed using the mathematical software Maple.

		Hence,
		\begin{equation}
			\begin{aligned}
				&\operatorname{\uppercase\expandafter{\romannumeral3}}^--\frac{32\zeta_2}{3}\operatorname{Sc}^2(p)+64\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)-\zeta_1\beta_1  \operatorname{Sc}(p)\\
				=&	-\frac{16}{9}\zeta_2\operatorname{Sc}^2(p)+\left(96\alpha^2-160\alpha+16n(\alpha-1)^2\right)\zeta_2(\operatorname{tr}(\textbf{a}))^2 +64\left(1-\frac{(\alpha+1)}{3 }\right)\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\\
				&+\frac{-(\alpha-1)^2 n-2 \alpha^2+6 \alpha}{2}\zeta_1\beta_1\operatorname{tr}(\textbf{a})+\frac{(n-2) \alpha^2-2( n+1) \alpha+n}{4 n}\beta_1^2+\frac{\alpha-2}{3}\zeta_1\beta_1 \operatorname{Sc}(p).
			\end{aligned}
		\end{equation}
		Since $\int_V (u_-\xi_-)^{\alpha+1}d\mu \equiv 1$, $\operatorname{tr}(\textbf{a})$, $\beta_1$ and $\operatorname{Sc}(p)$ should satisfy \eqref{normal_1_condition}.
		This together with \eqref{choose_a} implies that
		$$
		\begin{aligned}
			\beta_1=-\frac{8 \left((n+4) \alpha^2-2(n+5) \alpha+n+2\right)}{3 (\alpha+1)((n-2) \alpha-n-2)\chi} \operatorname{Sc}(p).
		\end{aligned}
		$$
		When $\alpha\to 1$, we have
		$\zeta_1\to -\frac{2}{n}$, $\zeta_2\to \frac{1}{16n}$, $\beta_1\to -\frac{1}{3}\operatorname{Sc}(p)$,  $\chi\to 4$ and $\textbf{a} \to \frac{1}{3}\operatorname{Rc}(p)$. It follows that  
		$$
		\operatorname{\uppercase\expandafter{\romannumeral3}}^--\frac{32\zeta_2}{3}\operatorname{Sc}^2(p)+64\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)-\zeta_1\beta_1  \operatorname{Sc}(p)=j^-(\alpha,n)\operatorname{Sc}^2(p).
		$$
		with
		$$j^-(\alpha,n)\to 0.$$

		(ii) Similar to \eqref{sc_expansion_-}, by Lemma \ref{key_lemma} (iii), we have for $1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$:
		\begin{equation}\label{sc_expansion_+}
			\begin{aligned}
				&\quad 	 
				\frac{1}{2(1+\alpha)}\tau^{1-2\Theta_{\alpha}} \int_V \operatorname{Sc}(x) \cdot \left( u_+(x,t)\xi_+(x,t)\right)^2 d\mu
				\\
				&=\frac{1}{2(1+\alpha)}\left(\frac{\mathfrak{m}\Theta_{\alpha}}{1-2\Theta_{\alpha}}\left(\frac{A_0}{D_0(2\alpha)^{\frac{1}{\alpha}}}\right)^{-1}\frac{D_0(\alpha+1)}{ D_0(2\alpha)^{\frac{\alpha+1}{2\alpha}}}\right)^{\frac{1-2\Theta_{\alpha}}{1-\Theta_{\alpha}}}	D_0(2\alpha)^{-\frac{1}{\alpha}}A_0 \left(A_0^{-1} t^{1-\frac{n}{2}}   \int_V \operatorname{Sc}(x)\cdot  \left( \operatorname{H}(\frac{d(p,x)}{\sqrt{t}})\xi_+(x,t)\right)^2 d\mu \right)\\
				&=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha} \frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}{2(1+\alpha)A_0}\times\\
				&\Big\{\operatorname{Sc}(p)t-\frac{8}{n(\alpha-1)+2\alpha-6}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2+o(t^2)\Big\}\\
				&=-\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}\zeta_1\Big\{\operatorname{Sc}(p)t-\frac{8}{n(\alpha-1)+2\alpha-6}\left(\frac{1}{2}\Delta \operatorname{Sc}(p)-\frac{1}{6}\operatorname{Sc}^2(p)+\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)\right)t^2+\beta_1 \operatorname{Sc}(p)t^2+o(t^2)\Big\}\\
				&=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha} \Big\{-\zeta_1\operatorname{Sc}(p)t+32\zeta_2\Delta \operatorname{Sc}(p)t^2+\left(-\frac{32\zeta_2}{3}\operatorname{Sc}^2(p)+64\zeta_2\operatorname{tr}(\textbf{a})\operatorname{Sc}(p)-\zeta_1\beta_1  \operatorname{Sc}(p)\right)t^2+o(t^2)\Big\},
			\end{aligned}
		\end{equation}
		where we have used $\left(\frac{\Theta_{\alpha}}{1-2\Theta_{\alpha}}\left(\frac{A_0}{D_0(2\alpha)^{\frac{1}{\alpha}}}\right)^{-1}\frac{D_0(\alpha+1)}{ D_0(2\alpha)^{\frac{\alpha+1}{2\alpha}}}\right)^{\frac{1-2\Theta_{\alpha}}{1-\Theta_{\alpha}}}	D_0(2\alpha)^{-\frac{1}{\alpha}}A_0= \Sigma^+_{\alpha}$.
		Similar to \eqref{c_2_+}, based on \eqref{thm:beta_ii_1} and \eqref{thm:beta_ii_2}, we still have for $1<\alpha\le \frac{n}{n-2}$:
		$$
		\frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2}{1-\alpha}+1)}{2(1+\alpha)A_0}=\frac{\frac{\omega_{n-1}}{2}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n}{2}}\mathscr{B}(\frac{n}{2},\frac{2\alpha}{1-\alpha}+3)}{2(1+\alpha)\frac{\omega_{n-1}}{32}\left(\frac{|\alpha-1|}{8}\right)^{-\frac{n+2}{2}}\mathscr{B}(\frac{n}{2}+1,\frac{2\alpha}{1-\alpha}+1)}=-\zeta_1.
		$$
		Similarly, we can show that $c_i^{+}(\alpha,n) = c_i^{-}(\alpha,n)$ for $i=6,7,8$ (ignoring the domain of variable $\alpha$) based on \eqref{thm:beta_ii_1},  \eqref{thm:beta_ii_2}, \eqref{thm:beta_ii_1} and \eqref{thm:beta_ii_2}. 

		Since $\int_V (u_+\xi_+)^{\alpha+1}d\mu \equiv 1$, $\operatorname{tr}(\textbf{a})$, $\beta_1$ and $\operatorname{Sc}(p)$ should satisfy \eqref{normal_2_condition}.
		This together with \eqref{choose_a} implies that
		$$
		\begin{aligned}
			\beta_1=-\frac{4 \left((n+4) \alpha^2-2(n+5) \alpha+n+2\right)}{3 \alpha((n-2) \alpha-n-2)\chi} \operatorname{Sc}(p).
		\end{aligned}
		$$
		We still have $\beta_1\to -\frac{1}{3}\operatorname{Sc}(p)$ as $\alpha\to 1$. Hence, we can conclude that Lemma \ref{expansion_W_a} (ii) holds as Lemma \ref{expansion_W_a} (i).
	\end{proof}	

	Next, we prove Theorem~\ref{Yamabe_rigidity}. In fact, we establish a more general result (Theorem~\ref{mu_constant_rigidity}), from which Theorem~\ref{Yamabe_rigidity} follows directly.

	\begin{thm}\label{mu_constant_rigidity}
		Let $(M^n,g)$ be a Riemannian manifold of dimension $n\geq 3$, and let $V$ be an open bounded subset of $M^n$.    
		Suppose that there exist constants $\kappa^{\pm}$, depending only on $n$, such that for $0<|\alpha-1|<\kappa^{\pm}$, the following holds: 
		there exists $\tau_0$ such that $\tau\leq \tau_0$ satisfies
		\begin{equation}\label{mu_constant_comparison_iso_2_6}
			\mu^{\pm}_{\alpha}(V,g, \tau) \geq -o(\tau^2).
		\end{equation}
		Then $V$ must be flat.
	\end{thm}
	\begin{proof}
		For any $p \in V$, we choose $\xi_{\pm} \in \mathscr{B}_p(V)$(i.e. we take
		$
		\textbf{a} = \frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p)
		$
		)
		such that $\int_V (u_-\xi_-)^{\alpha+1} d\mu \equiv 1$ if $0 < \alpha < 1$,
		and $\int_V (u_+\xi_+)^{2\alpha} d\mu \equiv 1$ if $1 < \alpha \leq \frac{n}{n-2}$.

		By Lemma \ref{expansion_W-}, we have for $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$ and $\alpha<\frac{n+6}{n+2}$):
		\begin{equation*}
			\begin{aligned}
				&\quad\mathcal{W}^{\pm}_{\alpha}(V,g, u_{\pm}(x,t)\xi_{\pm}(x,t),\tau_{\pm}(t))\\
				&=\operatorname{M}^{\pm}_{\alpha} \left\{32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+j^{\pm}(\alpha,n)\operatorname{Sc}^2(p)t^2+o(t^2)\right\},
			\end{aligned}
		\end{equation*}
		with
		$$j^{\pm}(\alpha,n)\to 0 \text{ as } \alpha\to 1.$$
		Here, $\operatorname{M}^{-}_{\alpha}=\mathfrak{m}^{1-\frac{\Gamma_{\alpha}}{2\Gamma_{\alpha}+1}}\Sigma^-_{\alpha}$ and  $\operatorname{M}^{+}_{\alpha}=\mathfrak{m}^{1-\frac{\Theta_{\alpha}}{1-\Theta_{\alpha}}}\Sigma^+_{\alpha}$.

		By the curvature decomposition \eqref{orthogonal_decomposition}, we have
		\begin{equation}\label{thm5.2_i}
			|\operatorname{Rm}|^2(p) \ge \frac{4}{n-2}|\operatorname{Rc}|^2(p) - \frac{2}{(n-1)(n-2)} \operatorname{Sc}^2(p).
		\end{equation}

		When $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$  and $\alpha<\frac{n+6}{n+2}$), and if $\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) \le 0$,
		by Lemma \ref{expansion_W_a} and \eqref{mu_constant_comparison_iso_2_6},
		we get for $t$ small enough:
		\begin{align}
			& -o(t^2)\le \mathcal{W}^{\pm}_{\alpha}(V,g, u_{\pm}(x,t)\xi_{\pm}(x,t),\tau_{\pm}(t)) \nonumber \\
			=& \operatorname{M}^{\pm}_{\alpha} \left\{32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right)t^2+j^{\pm}(\alpha,n)\operatorname{Sc}^2(p)t^2+o(t^2)\right\} \label{goback2} \\
			\le & \operatorname{M}^{\pm}_{\alpha} \left\{ 32\zeta_2\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) |\operatorname{Rc}|^2(p) \right.\nonumber \\
			& \quad \left.+ \left(\frac{32\zeta_2}{3(n-1)(n-2)} + j^{\pm}(\alpha,n)\right) \operatorname{Sc}^2(p)\right\}t^2 +o(t^2)\label{goback} \\
			\le & 32\zeta_2 \operatorname{M}^{\pm}_{\alpha} \left\{\frac{1}{n}\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) \right. \nonumber \\
			& \quad \left. + \left(\frac{1}{3(n-1)(n-2)} + \frac{j^{\pm}(\alpha,n)}{32\zeta_2}\right)\right\} \operatorname{Sc}^2(p)t^2+o(t^2), \label{goback3}
		\end{align}
		with $\zeta_2>0$, where we have used \eqref{thm5.2_i} and $|\operatorname{Rc}|^2(p)\ge \frac{1}{n}\operatorname{Sc}^2(p)$.
		Hence, when 
		\begin{equation}\label{co_1}
			\text{ $0<\alpha<1$ or ($1<\alpha\le \frac{n}{n-2}$  and $\alpha<\frac{n+6}{n+2}$)},
		\end{equation}
		and
		\begin{equation}\label{co_2}
			\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) \le 0,
		\end{equation}
		and
		\begin{equation}\label{co_3}
			\operatorname{F}(\alpha,n):=\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) + n\left(\frac{1}{3(n-1)(n-2)} + \frac{j^{\pm}(\alpha,n)}{32\zeta_2}\right) < 0,
		\end{equation}
		we conclude from \eqref{goback3} that $\operatorname{Sc}(p) = 0$. 
		Consequently, $\operatorname{Rc}(p) = 0$ by \eqref{goback}, and $\operatorname{Rm}(p) = 0$ by \eqref{goback2}.  Since $j^{\pm}(\alpha,n)\to 0$  and $\chi\to 4$ as $\alpha \to 1$,  there exist $\kappa^{\pm}$ such that when $0<|\alpha-1|<\kappa^{\pm}$, there hold \eqref{co_1}, \eqref{co_2} and \eqref{co_3}.
	\end{proof}

	\begin{rem}\label{exact_number_equation}
		From the proof of Theorem~\ref{mu_constant_rigidity}, we observe that $\kappa^{\pm}$ depends on the intersections of the ranges given in \eqref{co_1}, \eqref{co_2}, and \eqref{co_3}. 
		Through direct calculation using Maple, we find that $\operatorname{F}(\alpha,n)=0$ is a complicated seventh-degree polynomial equation.
	\end{rem}


	Now we give the proof of Theorem \ref{Yamabe_rigidity}.
	\begin{proof}[Proof of Theorem \ref{Yamabe_rigidity}:]
		Theorem  \ref{Yamabe_rigidity} follows directly from Theorem \ref{mu_constant_rigidity} and Theorem \ref{connection}.
	\end{proof}










	\section{the proof of Theorem \ref{rigidity_iso_profile}}

	Before presenting the proof of Theorem \ref{mu_rigidity}, we need the following lemma.
	\begin{lem}\label{section}
		Let $(M^n,g)$ be an $n$-dimensional manifold and $p\in \mathring{M^n}$. 	Let $u_{\pm}$ be the functions defined in \eqref{def_u-} and \eqref{def_u+}.

		\noindent\textbf{(a) For the case $0<\alpha<1$:}
		\begin{enumerate}
			\item 
			When 
			\begin{equation}\label{6_i_1}
				0<\alpha<1,
			\end{equation}
			if there exist a neighborhood $V_p$ of $p$,  $\xi_-(x,t)\in \mathcal{B}_p(V_p)$ and $\bar{\xi}_-(x,t)\in \mathcal{B}_{p_K}(M^n_K)$ for some point $p_K\in M^n_K$ satisfying
			\begin{equation}\label{comparison_l1}
				\mathcal{L}^-_{\alpha}(V_p,g,u_-\xi_-,t )\ge  \mathcal{L}^-_{\alpha}(M^n_K,g_K, \bar{u}_-\bar{\xi}_-,t)-o(t),
			\end{equation}
			for all $0<t<\tau_0$ and some $\tau_0>0$,
			then the scalar curvature at $p$ satisfies
			$$
			\operatorname{Sc}(p)\le n(n-1)K.
			$$	
			Here, $ M^n_K$ 
			is the space form with constant sectional curvature $K$.
			\item   When $\alpha$ satisfies the more restrictive range \eqref{6_i_3},
			if we assume  that 
			\begin{equation}\label{comparison_ll}
				\mathcal{L}^-_{\alpha}(V_p,g,u_-\xi_-,t )\ge  \mathcal{L}^-_{\alpha}(M^n_K,g_K, \bar{u}_-\bar{\xi}_-,t)-o(t^2),
			\end{equation}
			for all $0<t<\tau_0$ and some $\tau_0>0$,
			and if additionally
			\begin{equation}\label{R_point_compare_6}
				\operatorname{Sc}(p)    \ge n(n-1)K, \quad	\Delta \operatorname{Sc}(p) \ge 0, 
			\end{equation}
			then the sectional curvature at $p$ satisfies
			$$\operatorname{Sec}(p)=K.$$
		\end{enumerate}


		\noindent\textbf{(b) For the case $1<\alpha\le \frac{n}{n-2}$:}
		\begin{enumerate}
			\item 	
			When $\alpha$ satisfies the range \eqref{6_i_2},  
			if there exist a neighborhood $V_p$ of $p$,  $\xi_+(x,t)\in \mathcal{B}_p^(V_p)$ and $\bar{\xi}_+(x,t)\in \mathcal{B}_{p_K}(M^n_K)$ for some point $p_K\in M^n_K$ satisfying
			\begin{equation}\label{comparison_21}
				\mathcal{L}^+_{\alpha}(V_p,g,u_+\xi_+,t )\ge  \mathcal{L}^+_{\alpha}(M^n_K,g_K, \bar{u}_+\bar{\xi}_+,t)-o(t),
			\end{equation}
			for all $0<t<\tau_0$ and some $\tau_0>0$,
			then the scalar curvature at $p$ satisfies
			$$
			\operatorname{Sc}(p)\le n(n-1)K.
			$$	
			Here, $ M^n_K$ 
			is the space form with constant sectional curvature $K$.
			\item  When $\alpha$ satisfies the more restrictive range \eqref{6_i_4},
			if we assume  that \begin{equation}\label{comparison_2}
				\mathcal{L}^+_{\alpha}(V_p,g,u_+\xi_+,t )\ge  \mathcal{L}^+_{\alpha}(M^n_K,g_K, \bar{u}_+\bar{\xi}_+,t)-o(t^2),
			\end{equation}
			for all $0<t<\tau_0$ and some $\tau_0>0$, and if addtionally
			\begin{equation}\label{R_point_compare_66}
				\operatorname{Sc}(p)    \ge  n(n-1)K, \quad	\Delta \operatorname{Sc}(p) \ge 0, 
			\end{equation}
			then the sectional curvature at $p$ satisfies
			$$\operatorname{Sec}(p)= n(n-1)K.$$
		\end{enumerate}
	\end{lem}



	\begin{proof} 
		\textbf{  First, we prove (a)(1) and (b)(1).}
		By (\ref{expansion_-}) \eqref{expansion_+_1} and  (\ref{comparison_l1}) \eqref{comparison_21}, when $\alpha$ satisfies \eqref{6_i_1} or \eqref{6_i_2}, we conclude that 
		\begin{equation}\label{q_1} 
			\begin{aligned}
				\zeta_1 \operatorname{Sc}(p)t 
				\ge \zeta_1 \operatorname{Sc}_K(p)t-o(t)
			\end{aligned}
		\end{equation}
		for all $t\le \tau_0$, 
		where $\operatorname{Sc}_K$ denotes the scalar curvature of the $n$-dimensional space form of constant sectional curvature $K$. Since $\zeta_1<0$ when $\alpha$ satisfies \eqref{6_i_1} or \eqref{6_i_2}, we have $\operatorname{Sc}(p)\le \operatorname{Sc}_K(p_K)=n(n-1)K$.

		\textbf{ Second, we prove (a)(2) and (b)(2).}
		By (\ref{expansion_-}) \eqref{expansion_+_2} and  (\ref{comparison_ll}) \eqref{comparison_2}, when $\alpha$ satisfies \eqref{6_i_3} or \eqref{6_i_4}, we conclude that 
		\begin{equation}\label{q_2}
			\begin{aligned}
				&\zeta_1 \operatorname{Sc}(p)t- 32\zeta_2\Delta \operatorname{Sc}(p)t^2+32\zeta_2\left\{ \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\right\} t^2+C_1'\operatorname{Sc}^2(p) \\
				\ge& \zeta_1 \operatorname{Sc}_K(p)t+32\zeta_2\left\{ \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc_K}|^2(p)-\frac{1}{6}|\operatorname{Rm}_K|^2(p)\right\} t^2+C_1'\operatorname{Sc}_K^2(p)-o(t^2)
			\end{aligned}
		\end{equation}
		where  $\operatorname{Rc_K}$ and $\operatorname{Rm}_K$ denote the Ricci curvature and curvature tensor of the $n$-dimensional space form of constant sectional curvature $K$. 

		If we have $\operatorname{Sc}(p)\ge n(n-1)K$, then $\operatorname{Sc}(p)=n(n-1)K$. Since $\Delta\operatorname{Sc}(p)\ge 0$ and $\zeta_2>0$, 
		we conclude from (\ref{q_2}) that 
		\begin{equation}\label{6_ii_1}
			\begin{aligned}
				&\frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}|\operatorname{Rm}|^2(p)\\
				\ge& \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc_K}|^2(p)-\frac{1}{6}|\operatorname{Rm}_K|^2(p). 
			\end{aligned}
		\end{equation}

		From the curvature orthogonal decomposition \eqref{orthogonal_decomposition}, 
		we have
		\begin{equation*}
			\begin{aligned}
				&\frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc}|^2(p)-\frac{1}{6}\left(\frac{4}{n-2}|\operatorname{Rc}|^2(p)-\frac{2}{(n-1)(n-2)} \operatorname{Sc}^2(p)\right)\\
				\ge& \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi}|\operatorname{Rc_K}|^2(p)-\frac{1}{6}\left(\frac{4}{n-2}|\operatorname{Rc_K}|^2(p)-\frac{2}{(n-1)(n-2)} \operatorname{Sc_K}^2(p)\right)
			\end{aligned}
		\end{equation*}
		If\begin{equation}
			\left( \frac{4((n+5) \alpha-n-3)(\alpha-1)}{9\chi} - \frac{2}{3(n-2)}\right) <0 ,
		\end{equation}
		we conclude that
		$$
		|\operatorname{Rc}|^2(p)\le |\operatorname{Rc}_K|^2(p)=\frac{1}{n}\operatorname{Sc_K}^2(p)=\frac{1}{n}\operatorname{Sc}^2(p),
		$$
		and hence
		$$
		|\operatorname{Rc}|^2(p)=|\operatorname{Rc}_K|^2(p)=\frac{1}{n}\operatorname{Sc}^2(p).
		$$
		and by \eqref{6_ii_1}
		\begin{equation}\label{rm_iii}		|\operatorname{Rm}|^2(p)\le|\operatorname{Rm}_K|^2(p)=2n(n-1)K^2.
		\end{equation}
		Again curvature orthogonal decomposition \eqref{orthogonal_decomposition}, 
		we have
		\begin{equation}\label{q_3}
			|\mathrm{\operatorname{Rm}}|^2(p)\ge \left|\frac{\operatorname{Sc}}{2 n(n-1)} g \odot g\right|^2(p)=2n(n-1)K^2
		\end{equation}
		with equality if and only if $g$ has the constant sectional curvature. Then we get $\operatorname{Sec}(p)=K$ by \eqref{rm_iii} and \eqref{q_3}.	



	\end{proof}


	Now we give the proof of Theorem \ref{rigidity_iso_profile}.

	\begin{proof}[Proof of Theorem \ref{rigidity_iso_profile}]
		For any $p\in V$,
		we take 
		$\eta\in \mathscr{B}_p(V)$, $u=u_-\eta$ when $0<\alpha<1$ or $u=u_+\eta$ when $1<\alpha\le \frac{n}{n-2}$, where $u_{\pm}$ are the functions defined in \eqref{def_u-} and \eqref{def_u+}.
		Next, we apply the spherical symmetrization (Schwarz symmetrization) method.

		We can choose $r_0$ to be small enough so that $\operatorname{supp}\{\eta\}\subset B(p,r_0)\subset\subset V$ and therefore there exists $B^K(p_K,r_t)\subset M^n_K$ such that
		$
		\operatorname{Vol}_{g}(\{x \in M^n\mid u(x,t) >0\})=\operatorname{Vol}\left(B^K(p_K,r_t)\right)\le \beta_0.
		$
		Let
		$
		\bar{u}(\cdot,t)
		$
		be a non-negative rotational symmetric function such that
		\begin{equation}\label{vol_equa}
			\operatorname{Vol}\left(\left\{y \in  M^n_K\mid \bar{u}(y,t) \geq s\right\}\right)= \operatorname{Vol}\left(\{x \in V\mid u(x,t) \geq s\}\right)
		\end{equation}
		for all $s>0$ and $\bar{u}(y,t)=0$ when $\bar{d}(p_K,y)\geq r_t$. It is clear that  $\bar{u}(r,t) :=\bar{u}(y,t)$ is non-increasing in $r=\bar{d}(p_K,y)$ for any $t>0$. We define
		$
		\mathcal{M}_s :=\{x \in V\mid u(x,t) \geq s\}, \mathcal{M}_s^{\prime} :=\left\{y \in  M^n_K\mid \bar{u}(y,t) \geq s\right\}
		$
		and $\Gamma_s := \partial \mathcal{M}_s$, $\Gamma_s^{\prime} :=\partial \mathcal{M}_s^{\prime}$. By the co-area formula and (\ref{vol_equa}), we have
		\begin{equation}\label{level_set_equa}
			\int_{\Gamma_s} \frac{1}{|\nabla u(\cdot,t)|} d \sigma=\int_{\Gamma_s^{\prime}} \frac{1}{|\bar{\nabla} \bar{u}(\cdot,t)|} d \sigma_K,
		\end{equation}
		\begin{equation}\label{1.1_1}
			\int_{V} u(\cdot,t)^q d\mu=	\int_{M^n_K} \bar{u}(\cdot,t)^q d\mu_K,
		\end{equation}
		for any $q>0$.    

		Since $\mathcal{M}_s^{\prime}$ is a round ball in space form and by (\ref{comparison_iso}), we have
		\begin{equation}\label{key}
			\begin{aligned}
				\operatorname{Area}\left(\Gamma_s^{\prime}\right)  =\operatorname{I}(M^n_K,\operatorname{Vol}\left(\mathcal{M}_s^{\prime}\right)) \le \operatorname{I}(V,\operatorname{Vol}\left(\mathcal{M}_s\right)) \leq \operatorname{Area}\left(\Gamma_s\right).
			\end{aligned}
		\end{equation}
		and hence
		\begin{equation*}
			\begin{aligned}
				& \int_{\Gamma_s^{\prime}}|\bar{\nabla} \bar{u}(\cdot,t)| d \sigma_K \cdot \int_{\Gamma_s^{\prime}} \frac{1}{|\bar{\nabla} \bar{u}(\cdot,t)|} d \sigma_K \\
				=& \left(\text { Area }\left(\Gamma_s^{\prime}\right)\right)^2\leq\left(\text { Area }_{\tilde{g}}\left(\Gamma_s\right)\right)^2 \\
				\leq&  \int_{\Gamma_s}|\nabla u(\cdot,t)| d \sigma\cdot \int_{\Gamma_s} \frac{1}{|\nabla u(\cdot,t)|} d \sigma,
			\end{aligned}
		\end{equation*}
		where we used the H\"{o}lder inequality to obtain the last inequality. By this and (\ref{level_set_equa}), we have
		\begin{equation}\label{1.1_3}
			\int_{M^n_K}|\bar{\nabla} \bar{u}(\cdot,t)|^2  d \mu_K
			\leq \int_{V}|\nabla u(\cdot,t)|^2 d \mu.
		\end{equation}
		It follows that (\ref{1.1_1}) and (\ref{1.1_3}),
		we have
		\begin{equation}\label{1.1_8}
			\mathcal{L}^{\pm}_{\alpha}(V,g, u,t )\ge  \mathcal{L}^{\pm}_{\alpha}(M^n_K,g_K, \bar{u},t).
		\end{equation}

		Now we let $\alpha$  satisfy \eqref{6_i_3} or \eqref{6_i_4}.
		For the case $K= 0$, we have $\mathcal{L}^{\pm}_{\alpha}(V,g, u,t )\ge 0$ by Theorem \ref{connection} and the Gagliardo-Nirenberg
		inequality in Euclidean space. In this case, Theorem \ref{rigidity_iso_profile} follows from Theorem  \ref{mu_rigidity}. 

		Next, we consider the case $K\ne 0$.
		Taking $s=\bar{u}(r,t)$ in (\ref{level_set_equa}),  $\bar{u}$ is the solution to
		\begin{equation}\label{key_7}
			\int_{\Gamma_r} \frac{1}{|\nabla u(\cdot,t)|} d \sigma= \frac{\operatorname{Area_K}(\partial B^K(p_K,r))}{|\frac{d}{dr} \bar{u}(r,t)|},
		\end{equation}
		with  $\Gamma_r=\{x\in M \mid u(x,t)=\bar{u}(r,t) \}$. 
		Now we rescale the metrics as $\tilde{g}=t^{-1}g$ and  $\tilde{g}_K=t^{-1}g_K$. 
		Then (\ref{key_7})  becomes
		\begin{equation}\label{key_6}
			\int_{\tilde{\Gamma_r}} \frac{1}{|\tilde{\nabla}\tilde{u}(x,t)|} d \sigma_{\tilde{g}}= \frac{\operatorname{Area_{tK}}(\partial B^{tK}(p_K,r))}{|\frac{d}{dr} \tilde{u}_K(r,t)|},
		\end{equation}
		where $\tilde{u}(x,t)=t^{\frac{n}{2(\alpha+1)}}D_0(\alpha+1)^{-\frac{1}{\alpha+1}}u(\sqrt{t}x,t)$ and $\tilde{u}_K(r,t)=t^{\frac{n}{4\alpha}}D_0(2\alpha)^{-\frac{1}{2\alpha}}\bar{u}_K(\sqrt{t}r,t)$ if $0<\alpha<1$,  $\tilde{u}(x,t)=t^{\frac{n}{4\alpha}}u(\sqrt{t}x,t)$ and $\tilde{u}_K(r,t)=t^{\frac{n}{4\alpha}}\bar{u}_K(\sqrt{t}r,t)$ if $\alpha>1$, $\tilde{\Gamma_r}=\{x\in M \mid \tilde{u}(x,t)=\tilde{u}_K(r,t)\}$. Moreover, we can write $\tilde{u}(x,t)= \operatorname{H}(x)\tilde{\eta}(x,t)$ and $\tilde{\eta}^2$ can be written as $\tilde{\eta}^2=1+\frac{2(\alpha+1)}{3\chi} \operatorname{Rc}(p)_{ij}t\tilde{y^i}\tilde{y^j}
		+e_{ijk}t^{\frac{3}{2}}\tilde{y^i}\tilde{y^j}\tilde{y^k}+b_{ijkl}t^2\tilde{y^i}\tilde{y^j}\tilde{y^k}\tilde{y^l}+o(t^2d_{\tilde{g}}^4)+\beta_1 t+q_it^{\frac{3}{2}}\tilde{y^i}+d_{ij}t^2\tilde{y^i}\tilde{y^j}+o(td_{\tilde{g}}^2)t+\beta_2 t^2+o(t^2)
		$, here  $\{\tilde{x}^k\}^n_{k=1}$ be the normal geodesic coordinates centered at $p$ on $T_pM$ with respect to metric $\tilde{g}$.  Taking $t\to 0$ in (\ref{key_6}), we can get
		$\tilde{u}(r,0)=\operatorname{H}(r)$.
		It is straightforward from (\ref{key_6}) and the differentiability of $\tilde{\Gamma_r}$ and $\tilde{\eta}^2$ that $ \bar{u}(r,t)=u_{\pm}(r)\bar{\eta}(r,t)$ with rotational symmetric function $\bar{\eta}(x,t)$ can be written as $\bar{\eta}(x,t)^2=\sum\limits_{k=0}^2\bar{\phi}_k(x)t^k+o(t^2)$ around $(p_K,0)$ with $\bar{\phi}_2$ being continuous at $p_K$, both 4th derivatives of $\bar{\phi}_0$, and 2nd derivatives of $\bar{\phi}_1$ exist at $p_K$. 


		Letting  $t\to 0$ in (\ref{1.1_1}), we get $\bar{\eta}^2(p_K,0)=1$. Also note that $\bar{u}(r,t) $ is non-increasing in $r$ for any $t>0$. Then $\bar{u}(y,t)$ achieves its maximum at $p_K$ for any $t$ and therefore $\bar{\nabla}\bar{u}(p_K,t)=0$.
		By (\ref{expansion_-}), (\ref{expansion_+_2}) and comparing the $O(t)$ terms of (\ref{1.1_8}), we get $\operatorname{Sc}(x)\le n(n-1)K$ for all $x\in V$ since $p$ is arbitrarily chosen. We get $\operatorname{Sc}(x)\equiv n(n-1)K$ on $V$ by \eqref{scalar_curvature_lowerbound}. Therefore,   $\Delta\operatorname{Sc}\equiv 0$
		on $V$.
		By the $O(t)$ terms of (\ref{1.1_1}) and (\ref{expansion_D1st}), we have
		$\frac{D_1(q)}{D_0(q)}=\frac{\bar{D}_1(q)}{\bar{D}_0(q)}$ for any $q>\max\{2\alpha,\alpha+1\}$. Hence, we can get $\frac{\partial}{\partial t}\bar{\eta}^2(p_K,0)=\frac{\partial}{\partial t}\eta^2(p,0)=\beta_1$ and $\operatorname{tr}(\bar{\nabla}\bar{\nabla} \bar{\eta}^2)(p_K,0)=\operatorname{tr}(\nabla\nabla \eta^2)(p,0)=\frac{4(\alpha+1)}{3\chi}\operatorname{Sc}(p)=\frac{4(\alpha+1)}{3\chi}n(n-1)K$.  Hence, $\bar{\nabla}\bar{\nabla} \bar{\eta}^2(p_K,0)=\frac{4(\alpha+1)}{3\chi}(n-1)K\delta_{ij}$ since $\bar{\eta}$ is rotational symmetric. Then we get $\bar{u}\in \mathscr{B}_p(M^n_K)$.
		So, Theorem \ref{rigidity_iso_profile}  follows from Lemma \ref{section}.

	\end{proof}




