\title{\vspace{0mm}Convergent Methods for Koopman Operators\\on Reproducing Kernel Hilbert Spaces}
\author{Nicolas Boull\'e\thanks{Department of Mathematics, Imperial College London, London, SW7 2AZ UK (n.boulle@imperial.ac.uk).}\and Matthew Colbrook\thanks{DAMTP, University of Cambridge, Cambridge, CB3 0WA UK (m.colbrook@damtp.cam.ac.uk, gjc51@cam.ac.uk).}\and Gustav Conradie\footnotemark[2]}
