    \centering
    \includegraphics[height=0.35\textwidth]{sea_level_evals_angle.pdf}\hspace{1cm}
    \includegraphics[height=0.35\textwidth]{sea_level_pspec.pdf}
    \caption{Northern Hemisphere sea surface height. Left: The eigenvalues outputted by kEDMD using a Mat{\'e}rn kernel are plotted based on their argument and (the log of) their modulus. The color coding shows the size of their residuals, as computed by SpecRKHS-Eig (\cref{evalverif_alg}). The dotted black lines correspond to the lines $\mathrm{arg}(\lambda)=\pi k/6$ for $k=-5,\dots,5$, and the $5$ dominant eigenvalues which we use for predictions are larger. Right: The plot shows pseudospectral contours for the same system using the same kernel, as computed by SpecRKHS-PseudoPF (\cref{pspecadjoint_alg}). The white dotted line shows the circle $\{z\in\mathbb{C}:|z|=1\}$.}
    \label{fig:sealevelevals}
\end{figure}

\begin{figure}[th!]
    \centering
    \includegraphics[height=0.2\textwidth]{sea_levels_evals_mode_2.png}\vspace{0.5cm}
    \includegraphics[height=0.2\textwidth]{sea_levels_evals_mode_4.png}
