        \begin{tcolorbox}[colback=gray!5!white,colframe=gray!75!black,title=Prompt: CoT-based Prompting]
        \textbf{Objective:} Analyze a product review to determine if the product is recommended.  

        \textbf{Step-by-Step Reasoning:}
        \begin{enumerate}
            \item \textbf{Step 1:} Identify the main sentiment of the reviewer (positive or negative).  
            \item \textbf{Step 2:} List the main reasons supporting the sentiment.  
            \item \textbf{Step 3:} Check if the reasons are mostly related to product quality, service, or pricing.  
            \item \textbf{Step 4:} Determine if the reviewer explicitly recommends or discourages the product.  
            \item \textbf{Step 5:} Conclude if the product is generally recommended based on sentiment and reasons.  
        \end{enumerate}

        \textbf{Expected Output:}  
        The output should be formatted as follows:  

        \texttt{
        \textbf{Step 1:} [Main sentiment identified] \\
        \textbf{Step 2:} [List of reasons] \\
        \textbf{Step 3:} [Category of reasons: Quality/Service/Pricing] \\
        \textbf{Step 4:} [Recommendation status: Yes/No] \\
        \textbf{Step 5:} [Final conclusion: Recommended/Not Recommended]
        }
        \end{tcolorbox}
    \end{minipage}
