\left( \mathcal{\hat{B}}_{L}\left( l\right) \right) $. Thus, $\bar{\sigma}%
\left( \mathcal{E}_{L\rightarrow \bar{L}}^{-}\left( \mathcal{\hat{B}}%
_{L}\left( l\right) \right) \right) =\sigma \left( \mathcal{\hat{B}}%
_{L}\left( l\right) \right) $ implies 
\begin{equation*}
\bar{\sigma}\left( \mathcal{E}_{L\rightarrow \bar{L}}^{+}\left( \mathcal{%
\hat{B}}_{L}\left( l\right) \right) \right) =\sigma \left( \mathcal{\hat{B}}%
_{L}\left( l\right) \right) .
\end{equation*}%
It follows that $\sigma \left( \mathcal{E}_{\bar{L}\rightarrow L}^{-}\left( 
\mathcal{E}_{L\rightarrow \bar{L}}^{-}\left( \mathcal{\hat{B}}_{L}\left(
l\right) \right) \right) \right) =\bar{\sigma}\left( \mathcal{E}%
_{L\rightarrow \bar{L}}^{-}\left( \mathcal{\hat{B}}_{L}\left( l\right)
\right) \right) $ implies 
\begin{equation*}
\sigma \left( \mathcal{E}_{\bar{L}\rightarrow L}^{+}\left( \mathcal{E}%
_{L\rightarrow \bar{L}}^{+}\left( \mathcal{\hat{B}}_{L}\left( l\right)
\right) \right) \right) =\bar{\sigma}\left( \mathcal{E}_{L\rightarrow \bar{L}%
}^{+}\left( \mathcal{\hat{B}}_{L}\left( l\right) \right) \right)
\end{equation*}%
and we obtain:%
\begin{equation*}
\sigma \left( \mathcal{E}_{\bar{L}\rightarrow L}^{+}\left( \mathcal{E}%
_{L\rightarrow \bar{L}}^{+}\left( \mathcal{\hat{B}}_{L}\left( l\right)
\right) \right) \right) =\bar{\sigma}\left( \mathcal{E}_{L\rightarrow \bar{L}%
}^{+}\left( \mathcal{\hat{B}}_{L}\left( l\right) \right) \right) =\sigma
\left( \mathcal{\hat{B}}_{L}\left( l\right) \right) \text{,}
\end{equation*}%
or%
\begin{equation*}
\mathcal{T}_{\bar{L}\rightarrow L}^{+}\left( \mathcal{T}_{L\rightarrow \bar{L%
}}^{+}\left( l\right) \right) =l
\end{equation*}

It follows that $L^{dp}\subseteq L^{p}$ and $\bar{L}^{dp}\subseteq \bar{L}%
^{p}$.

Finally, note that by the definition of $\sigma $ and $\bar{\sigma}$, $%
\sigma \left( \varnothing \right) =\bar{\sigma}\left( \varnothing \right)
=\varnothing $, and thus $\varnothing \in \mathcal{B}^{dp}$. It follows that 
$f\in L^{dp}\not=\varnothing $ and $\bar{f}\in \bar{L}^{dp}\not=\varnothing $%
.

\underline{\textbf{Proof of Lemma \ref{lemma-consistency-translation}}}:

We first show that the outer translation operator satisfies outer
consistency of translation. Consider $l\in L$ and $\bar{l}\in \bar{L}$ with
corresponding events in the joint state space $\sigma \left( b_{l}\right) $
and $\bar{\sigma}\left( b_{\bar{l}}\right) $. By the characterization of the
outer translation in (\ref{outer-translation}), and using (\ref{outer-event}%
) 
\begin{equation*}
\mathcal{T}_{\bar{L}\rightarrow L}^{+}\left( \bar{l}\right) =\vee _{\left \{
w^{\prime }\in W\mid \sigma \left( w^{\prime }\right) \cap \bar{\sigma}%
\left( b_{\bar{l}}\right) \not=\varnothing \right \} }l_{w^{\prime }}
\end{equation*}%
Thus, if $l\wedge \mathcal{T}_{\bar{L}\rightarrow L}^{+}\left( \bar{l}%
\right) \not=f$, there is a $w\in W$ and $\bar{w}\in \bar{W}$ such that $%
\sigma \left( w\right) \subseteq \sigma \left( b_{l}\right) $, $\bar{\sigma}%
\left( \bar{w}\right) \subseteq \bar{\sigma}\left( b_{\bar{l}}\right) $ and $%
