\not=\varnothing $. This in turn implies that 
\begin{equation*}
\bar{f}\not=\bar{l}_{\bar{w}}\Rightarrow _{\bar{L}}\bar{l}\wedge \left( \vee
_{\left \{ \bar{w}^{\prime }\in \bar{W}\mid \bar{\sigma}\left( \bar{w}%
^{\prime }\right) \cap \sigma \left( b_{l}\right) \not=\varnothing \right \}
}\bar{l}_{\bar{w}^{\prime }}\right) =\bar{l}\wedge \mathcal{T}_{L\rightarrow 
\bar{L}}^{+}\left( l\right)
