\bar{\sigma}\left( b_{\bar{l}}\right) \not \subseteq \left \{ \bar{w}%
^{\prime }\in \bar{W}\mid \bar{\sigma}\left( \bar{w}^{\prime }\right) \cap
\sigma \left( b_{l}\right) =\varnothing \text{, }\bar{\sigma}\left( \bar{w}%
^{\prime }\right) \subseteq A\right \}
