\section{Notation and Standing Assumptions}\label{app:notation}

We recap all symbols that enter the proofs and explicitly list the technical
conditions under which the main results hold.

\subsection*{A.1  Symbols}

\begin{tabular}{@{}ll@{}}\toprule
Symbol & Description \\ \midrule
$\mathcal{S}$                & compact support of the stationary density $p_{\mathrm{s}}$ \\
$\{\psi_{j}\}_{j\ge1}$       & $L^{2}(p_{\mathrm{s}})$–orthonormal dictionary          \\
$J$                          & number of basis functions retained                     \\
$\Psi_{J}(x)$                & $(\psi_{1}(x),\dots,\psi_{J}(x))^{\mathsf{T}}$          \\
$G_{M},A_{M}$                & weighted EDMD matrices, Eq.~\eqref{eq:GA_mats}          \\
$G_{\ast},A_{\ast}$          & population analogues of $G_{M},A_{M}$                  \\
$\varphi_{i},\lambda_{i}$    & true Koopman eigenfunctions and eigenvalues            \\
$\xi_{i},\mu_{i}$            & projections $\Pi_{J}\varphi_{i}$ and $e^{\lambda_{i}\Delta t}$\\
$\widehat\xi_{i},\widehat\mu_{i}$ & empirical eigenpairs of $A_{M}G_{M}^{\dagger}$   \\
$c_{i}(t)$                   & modal coefficient in expansion~\eqref{eq:q_expansion}  \\
$\widehat{c}_{i}(t)$         & estimated modal coefficient                            \\ \bottomrule
\end{tabular}

\subsection*{A.2  Assumptions}
\begin{enumerate}[label=\textbf{(A\arabic*)},leftmargin=20pt,itemsep=4pt]
\item\label{assump:KDE1}  \textbf{Density smoothness}
$p_s \in C^2(S)$ and $\sup_{x\in S}\|\nabla^2 p_s(x)\| \le C_p$.
\item\label{assump:KDE2}  \textbf{Kernel properties}
$K$ is bounded, symmetric, of order 2, $\int K = 1$, 
                 and Lipschitz with constant $L_K$.
\end{enumerate}
\begin{enumerate}[label=\textbf{(B\arabic*)},leftmargin=20pt,itemsep=4pt]
\item\label{B:ergodic} \textbf{Ergodic diffusion}  
      The SDE~\eqref{eq:sde} is ergodic with unique stationary density
      $p_{\mathrm{s}}$; its trajectory is exponentially $\beta$--mixing:
      $\beta(\tau)\le C_{0}e^{-\kappa\tau}$.

\item\label{B:dictionary} \textbf{Dictionary completeness}  
      There exist constants $C_{\varphi},q>0$ such that for each leading mode
      $\varphi_{i}$ ($i=1,\dots,r$),
      $\|(\mathrm{Id}-\Pi_{J})\varphi_{i}\|_{L^{2}(p_{\mathrm{s}})}
          \le C_{\varphi}J^{-q}$.

\item\label{B:bounded} \textbf{Moment bound}  
      $\sup_{x\in\mathcal{S}}\|\Psi_{J}(x)\|^{4}\le C_{\Psi}$ for all $J$.

\item\label{B:gram} \textbf{Population non--degeneracy}  
      The Gram matrix
      $G_{\ast}=\mathbb{E}_{p_{\mathrm{s}}}[\Psi_{J}(X)\Psi_{J}(X)^{\top}]$
      is positive definite with $\lambda_{\min}(G_{\ast})\ge\lambda_{0}>0$.

\item\label{B:gap} \textbf{Spectral gap}  
      $\min_{1\le i\le r}(\lambda_{i-1}-\lambda_{i})\ge\gamma>0$ with
      $\lambda_{0}=0$.

\item\textbf{Dictionary smoothness} 
Each basis function $\psi_j$ is $L_{\Psi}$–Lipschitz on $S$:
\[
  |\psi_j(x)-\psi_j(y)| \le L_{\Psi}\,\|x-y\|, 
  \qquad \forall x,y\in S,\; j=1,\dots,J.
\]
\label{assump:dict-lip}
\end{enumerate}
Conditions~\ref{B:ergodic}--\ref{B:bounded} guarantee concentration of
empirical moments; \ref{B:gram} ensures invertibility of $G_{M}$ for large
$M$; \ref{B:gap} stabilizes eigenvectors under perturbations.


