\section{Auxiliary Lemmas}\label{app:lemmas}

\begin{lemma}[Concentration of Gram and Cross Matrices]\label{lem:GA_conc}
Under \textbf{\ref{B:ergodic}--\ref{B:bounded}}, such that for every $t>0$
\[
  \Pr\!\{\|G_M-G_\ast\|_2\ge t\}\;\le\;
      J\exp\!\bigl(-cMt^2\bigr),\qquad
  \Pr\!\{\|A_M-A_\ast\|_2\ge t\}\;\le\;
      J\exp\!\bigl(-cMt^2\bigr).
\]
Consequently\[
  \mathbb{E}\|G_{M}-G_{\ast}\|_{2}=O(M^{-1/2}),\qquad
  \mathbb{E}\|A_{M}-A_{\ast}\|_{2}=O(M^{-1/2}).
\]
\end{lemma}

\begin{proof}

Applying the matrix Bernstein inequality for geometrically $\beta$–mixing random matrices in \citep{BannaMerlevedeYoussef2016} to the centered summands $Y_k:=w_k\Psi_J(z_k)\Psi_J(z_k)^\top-G_\ast$ whose bounded spectrum and variance are guaranteed by Assumptions~\ref{B:ergodic}--\ref{B:bounded} yields the tail bound $\|G_M-G_\ast\|_2,\|A_M-A_\ast\|_2=O_{\mathbb{P}}(M^{-1/2})$, proving the lemma. 


\end{proof}

\begin{lemma}[Operator Perturbation]\label{lem:op_perturb}
Let $\mathcal{K}^{\Pi}_{\ast}=A_{\ast}G_{\ast}^{-1}$ and
$\widehat{\mathcal{K}}_{M}=A_{M}G_{M}^{\dagger}$.
Under Assumptions \textbf{\ref{B:ergodic}--\ref{B:gram}},
\[
  \|\widehat{\mathcal{K}}_{M}-\mathcal{K}^{\Pi}_{\ast}\|_{2}
  = O_{\mathbb{P}}(M^{-1/2}).
\]
\end{lemma}

\begin{proof}
Write $\widehat{\mathcal{K}}_{M}-\mathcal{K}^{\Pi}_{\ast}
 =(A_{M}-A_{\ast})G_{M}^{\dagger}
  +A_{\ast}(G_{M}^{\dagger}-G_{\ast}^{-1})$.
Lemma~\ref{lem:GA_conc} bounds the first term.
For the second,
$G_{M}^{\dagger}-G_{\ast}^{-1}=G_{\ast}^{-1}(G_{\ast}-G_{M})G_{M}^{\dagger}$
and use $\|G_{M}^{\dagger}\|_{2}\le2/\lambda_{0}$ for large $M$.
\end{proof}
\begin{lemma}\label{lem:phi-lip}
Under Assumption~\ref{assump:dict-lip}, each coordinate of $\Phi(x)=\Xi^\top\Psi(x)$ is Lipschitz on the support of $p_{\mathrm{s}}$.
\end{lemma}

\begin{lemma}[Uniform KDE error]\label{lem:kde}
Let $\hat p_s$ denote the kernel density estimator with bandwidth
$h_M=M^{-\beta}$, where $\beta\in(0,1/2)$.  Under
Assumptions~\ref{assump:KDE1}--\ref{assump:KDE2} we have
\[
  \|\hat p_s-p_s\|_\infty \;=\;
  O_P\!\bigl(M^{-\beta}\bigr)
  \;+\;
  O_P\!\bigl(M^{-(1-\beta)/2}\bigr).
\]
Choosing any $\beta\in(\tfrac13,\tfrac12)$ makes
$\|\hat p_s-p_s\|_\infty=o_P(M^{-1/2})$.
\end{lemma}





