\section{Spectral Convergence Theorem}\label{app:spectral_proof}

\begin{theorem}[Spectral Convergence of EDMD]\label{thm:spec_conv_app}
Suppose \textbf{\ref{B:ergodic}--\ref{B:gap}} and
$J\ll M^{1/2}$.  Then
\[
  \max_{1\le i\le r}
   \Bigl(|\widehat\mu_{i}-\mu_{i}|
