\section{Forecast Error in $W_{2}$}\label{app:w2_proof}

% ---------- Revised Proof of Theorem 4 (Prediction Risk) ----------
\begin{theorem}[Finite–h prediction error in $W_2$]\label{thm:W2-risk}
Let assumptions \ref{B:ergodic}--\ref{assump:dict-lip} and the additional conditions
\ref{as:C1}--\ref{as:C3} below hold:
%
\begin{enumerate}[label=\textbf{(C\arabic*)}]
  \item\label{as:C1}  All densities lie on a common compact set
        $S\subset\mathbb{R}^{d}$ with diameter $D$ and volume $\operatorname{vol}(S)$.
  \item\label{as:C3}   For $j>r$ the Koopman
        eigenvalues satisfy $\Re\,\lambda_j\le -\eta<0$.
\end{enumerate}
%
Without loss of generality we assume the functions
        $\{\psi_j\}_{j=1}^{J}$ are orthonormal in $L^2(p_s)$. Fix a finite forecast horizon $h>0$ and assume the sample size $M\to\infty$
while the retained rank $r$ stays fixed.  Then
\begin{equation}\label{eq:W2-bound}
  \mathbb{E}\,
  W_2^2\!\bigl(p_{T+h},\hat p_{T+h}\bigr)
  = \mathcal{O}\!\bigl(M^{-1/2}\bigr)
    + \mathcal{O}\!\bigl(e^{-\,\eta h}\bigr),
\end{equation}
where the hidden constants depend only on $D$, $\operatorname{vol}(S)$,
the dictionary Lipschitz and $L^\infty$ bounds, and the spectrum of $K_\ast$.
\end{theorem}

\begin{proof}
Let the true density and its DPDD forecast be
\[
  p_{T+h}(x)=\sum_{j\ge1}c_j(h)\psi_j(x),\qquad
  \hat p_{T+h}(x)=\sum_{j=1}^{r}\hat c_j(h)\psi_j(x).
\]
Introduce the decomposition
\[
  \Delta(x)\;=\;\hat p_{T+h}(x)-p_{T+h}(x)
      \;=\;\underbrace{\sum_{j=1}^{r}\!\bigl[\hat c_j(h)-c_j(h)\bigr]\psi_j(x)}_{\Delta_{\mathrm{est}}}
        +\underbrace{\sum_{j>r}c_j(h)\psi_j(x)}_{\Delta_{\mathrm{tail}}},
\]
and write $\delta c_j(h)=\hat c_j(h)-c_j(h)$.

\paragraph{Step 1 (coefficient error).}
By the Spectral Convergence Theorem~\ref{thm:spec_conv_app} together with the diagonal action of $e^{h\Lambda}$,
\[
  \mathbb{E}\,\|\delta c(h)\|_2^{2}=\mathcal{O}\!\bigl(M^{-1}\bigr).
\]

\paragraph{Step 2 (tail truncation).}
Using assumption~\ref{as:C3},
\begin{equation}\label{eq:tail-L2}
  \|\Delta_{\mathrm{tail}}\|_2^{2}
  =\sum_{j>r}c_j^2(0)\,e^{2\Re\lambda_j h}
  \le e^{-\,2\eta h}\sum_{j>r}c_j^2(0)
  =\mathcal{O}\!\bigl(e^{-\,2\eta h}\bigr).
\end{equation}

\paragraph{Step 3 ($L^2$ control).}
Since we have assumed the dictionary functions to be orthonormal,
\[
  \|\Delta\|_2^{2}
    =\|\Delta_{\mathrm{est}}\|_2^{2}+\|\Delta_{\mathrm{tail}}\|_2^{2}
    =\|\delta c(h)\|_2^{2}+\|\Delta_{\mathrm{tail}}\|_2^{2}.
\]
Taking expectations and using Step 1 and~\eqref{eq:tail-L2},
\[
  \mathbb{E}\,\|\Delta\|_2^{2}
    =\mathcal{O}\!\bigl(M^{-1}\bigr)
     +\mathcal{O}\!\bigl(e^{-\,2\eta h}\bigr).
\]

\paragraph{Step 4 ($L^1$ conversion).}
By Hölder on the compact set $S$ (diameter $D$, volume $V$),
\[
  \mathbb{E}\,\|\Delta\|_1
  \;\le\;\sqrt{V}\,
        \bigl[\mathbb{E}\,\|\Delta\|_2^{2}\bigr]^{1/2}
  =\mathcal{O}\!\bigl(M^{-1/2}\bigr)
   +\mathcal{O}\!\bigl(e^{-\,\eta h}\bigr).
\]

\paragraph{Step 5 ($W_2$ bound).}
For measures supported on a set of diameter $D$, according to Theorem 6.15 in \citep{villani2009optimal} we have
\[
  W_2^{2}(\mu,\nu)
    \;\le\;D\,W_1(\mu,\nu)
    \;\le\;\frac{D^{2}}{2}\,\mathrm{TV}(\mu,\nu)
    \;=\;\frac{D^{2}}{2}\,\|p_\mu-p_\nu\|_1,
\]


Applying this with $\mu=p_{T+h}$, $\nu=\hat p_{T+h}$ and using Step 4 yields
\[
  \mathbb{E}\,
  W_2^{2}\bigl(p_{T+h},\hat p_{T+h}\bigr)
    \;\le\;\frac{D^{2}}{2}\,
           \mathbb{E}\,\|\Delta\|_1
    =\mathcal{O}\!\bigl(M^{-1/2}\bigr)
     +\mathcal{O}\!\bigl(e^{-\,\eta h}\bigr),
\]
which is exactly our theorem.
\end{proof}
% ---------- End proof ----------




