    \underline{\widehat{\omega}}^\dag_n &: = e^{N-3} \underline{\tau}^\dag + \iota_{\underline{z}}\omega^\dag+ \iota_{\xi{}}\underline{c}_n^{\dag}-\iota_{\underline{z}}{c}_{n}^{\dag}{\xi^{n}}\\
    \underline{v}^\dag &:=\epsilon_n e^{N-4} [\underline{\mu}^\dag, e],
\end{align*}
and rewrite $\underline{\omega}_n^\dag$ as
\begin{align}\label{e:split_omegan_dag}
    \underline{\omega}^{\dag}_n& = \underline{\whom}^\dag_n + \underline{v}^\dag.
\end{align}



}



{
