        && \underline{\txi{}}^\dag &= \underline{\xi}^{\dag} + \underline{c}_n^\dag (\nu+v) + d_{\omega}\epsilon_n (Z_a \underline{\mu}^\dag)^{(a)} + \nu [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}] \\
        && \underline{\txi{}}_n^{\dag} &= \underline{\xi}^{\dag}_n + X^{(a)}\underline{c}_{an}^\dag \mu^\dag + d(e^{N-4}\epsilon \underline{\tau}^\dag \mu^\dag) + \iota_z \underline{c}_n^\dag (\nu+v) + \iota_z(\nu+v) [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]\\
