    The first and last terms are respectively \reft{e:omega_s}{psiS10} and \reft{e:psi-omegaH}{psiHc3} $+$ \reft{e:psi-omegaH}{psiHx3}, while the second is compensated by \reft{e:psi-omegaH}{psiHe6}, \reft{e:psi-omegaH}{psiHen2}, \reft{e:psi-omegaH}{psiHon3}, \reft{e:psi-omegaH}{psiHc5} and \reft{e:psi-omegaH}{psiHxn5}:
    \begin{align*}
    \delta (\iota_{\underline{z}}v) \delta \omega^\dag - \delta ( \iota_z v \xi^{n}) \delta \underline{c}_n^\dag + \delta \xi^{n} \delta (\iota_z v \underline{c}_{n}^\dag)= \delta (\iota_{\underline{z}}v) \delta(Z)
    \end{align*}
    and 
    \begin{align*}
        \delta e \delta \left(\iota_{\underline{z}}(v_a Z)^{(a)}\right) + \delta \underline{e}_n \delta \left((v_a Z)^{(a)}\right)= \iota_{\delta \underline{z}} \delta ( vZ)
    \end{align*}
\item Consider \reft{e:psi-omegaH}{psiHe2}:
\begin{align*}
      \frac{1}{N-3} &\delta e \delta  \left(  e^{N-4}d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) +  e^{N-4}\sigma \underline{\mu}^\dag\right) =\delta e^{N-3} \delta \left(  d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) +  \sigma \underline{\mu}^\dag\right)\\
     &=   \delta e^{N-3}  [\delta {\whom} , \epsilon_n \underline{\mu}^\dag] + d_{\whom} (\delta e^{N-3})  \epsilon_n \delta \underline{\mu^\dag} + \delta (e^{N-3} \sigma) \delta\underline{\mu}^\dag\\
     &\overset{\eqref{e:PCconstraints2}}{=}\delta {\widehat{\omega}} \delta \left(\epsilon_n[e^{N-3}, \underline{\mu}^\dag]\right)+\epsilon_n  \delta \underline{\mu}^\dag [\delta {\widehat{\omega}} ,  e^{N-3}]+ d_{\widehat{\omega}} \delta e^{N-3}  \epsilon_n \delta \underline{\mu}^\dag\\
     &\phantom{=}+ \delta \left({\epsilon}_n  d_{\whom} e^{(N-3)} - {\epsilon}_n e^{(N-4)} \tau^\dag d \xi^{n} + {X}^{[a]}Z_a\right) \delta\underline{\mu}^\dag\\
     &= \delta {\widehat{\omega}} \delta v^\dag+ \delta \left( - {\epsilon}_n e^{(N-4)} \tau^\dag d \xi^{n} + X^{[a]}Z_a\right) \delta\underline{\mu}^\dag.
\end{align*}
The first term is \reft{e:omega_s}{psiS9}. We consider the last terms in the following points.
\item We consider $\delta \left(X^{[a]}Z_a\right) \delta\underline{\mu}^\dag  $ together with \reft{e:psi-omegaH}{psiHon4}, \reft{e:psi-omegaH}{psiHc6}, \reft{e:psi-omegaH}{psiHxn2}:
\begin{align*}
    \delta  X^{[a]} \delta \left(Z_a \underline{\mu}^\dag \right) =   X^{[b]} (\delta e_b)^{[a]}\delta \left(Z_a \underline{\mu}^\dag \right) +  (\delta X)^{[a]} \delta \left(Z_a \underline{\mu}^\dag \right).
\end{align*}
The first term is  \reft{e:psi-omegaH}{psiHe5}, while, recalling that 
\begin{align*}
    \delta X = [\delta (c+ \iota_{\xi}v), \epsilon_n]+ [\iota_{\xi} \delta \whom, \epsilon_n] + \iota_{\delta \xi{}}d_{\whom}(\epsilon_n)-[\delta \omega_n, \epsilon_n]\xi^{n}+d_{\omega_n} \epsilon_n\delta \xi^{n}
\end{align*}
the second is given by \reft{e:psi-omegaH}{psiHc7}, \reft{e:psi-omegaH}{psiHo3}, \reft{e:psi-omegaH}{psiHx4}, \reft{e:psi-omegaH}{psiHon5}, \reft{e:psi-omegaH}{psiHc9} and \reft{e:psi-omegaH}{psiHxn7}.
\item Lastly we consider $\delta \left( - {\epsilon}_n e^{(N-4)} \tau^\dag d \xi^{n}\right)\delta\underline{\mu}^\dag$ together with \reft{e:psi-omegaH}{psiHxn3} and \reft{e:psi-omegaH}{psiHe8}:
\begin{align*}
   \delta &\left( - {\epsilon}_n e^{(N-4)} \tau^\dag d \xi^{n}\right)\delta\underline{\mu}^\dag+ \delta \xi^n \delta (d(e^{N-4}\epsilon \underline{\tau}^\dag \mu^\dag))+ \theta_N(5) \delta e \delta \left(e^{N-5}\epsilon_n \mu^\dag d\xi^n \underline{\tau}^\dag\right) \\
   &= \delta \tau^\dag \delta \left({\epsilon}_n e^{(N-4)}d \xi^{n}\underline{\mu}^\dag\right)= \delta \tau^\dag \delta \left( e^{(N-3)}\nu\right)\\
   & = \delta \left(\tau^\dag e^{(N-3)} \right) \delta \nu + \frac{1}{N-3}\delta e \delta\left(e^{N-4} \nu \tau^\dag\right).
\end{align*}
 The last term is \reft{e:psi-omegaH}{psiHe3}, while for the first we proceed exactly as in \ref{i:etau} and get \reft{e:psi-omegaH}{psiHo2}, \reft{e:psi-omegaH}{psiHc2}, \reft{e:psi-omegaH}{psiHx2}, \reft{e:psi-omegaH}{psiHe7}, \reft{e:psi-omegaH}{psiHen3}, \reft{e:psi-omegaH}{psiHon2}, \reft{e:psi-omegaH}{psiHc4} and \reft{e:psi-omegaH}{psiHxn4}.
\end{enumerate}


\subsection{Actions}

We use the same strategy for the action. We rewrite $S_s$ as the sum of $S_r$ and an additional part:
\setcounter{terms}{0} 
\begin{align}\label{e:standard_action_split3}
    S_{s}(\Sigma \times I) &= S_{r}(\Sigma \times I) 
    + \int_{\Sigma \times I} \unl{\frac{1}{(N-3)!}e^{N-3} \underline{e}_n d_{\whom} v}{term1}
    +\unl{ \frac{1}{2(n-3)!}e^{N-3} \underline{e}_n[v,v]}{term2} \\
    \nonumber&\phantom{= + \int}
    +\unl{ \frac{1}{(N-2)!} e^{N-2}  d_{\underline{\omega_n}}v}{term3}-\unl{  \iota_{\xi} d_{\whom} v \underline{\whom}_n^\dag}{term4}
    +\unl{ \frac{1}{2}\iota_{\xi}[v,v])\underline{\whom_n^\dag}}{term5}
    -\unl{ [v,c] \underline{\whom}_n^\dag}{term6}
    +\unl{ X(\underline{v^\dag}) }{term7}\\
    \nonumber&\phantom{= + \int}
    -\unl{ \iota_{\xi}  d_{\underline{\omega_n}}v\omega^{\dag}}{term8}
    +\unl{ [\iota_{\xi}v, e] \underline{e}_n^{\dag}}{term9}+\unl{ [\iota_{\xi}v, \underline{e}_n]e^\dag}{term10}-\unl{  \frac{1}{2}\iota_{\xi}\iota_{\xi}d_{\whom} v \underline{c}_n^\dag}{term11}+\unl{ \frac{1}{4}\iota_{\xi}\iota_{\xi}[v,v]\underline{c}_n^\dag}{term12}\\
    \nonumber&\phantom{= + \int}-\unl{d_{\omega_n}v \xi^n \underline{\whom}_n^\dag}{term13}-\unl{\iota_{\xi}d_{\omega_n}v\xi^n\underline{c}_n^\dag}{term14}
\end{align}
where \reft{e:standard_action_split3}{term7} reads
\begin{align*}
    X(\underline{v^\dag}) = \left( \unl{\iota_{\xi} F_{\whom} }{term15}+ \unl{\iota_{\xi} d_{\whom} v }{term16}+ \unl{[\iota_{\xi}v,v]}{term17}+ \unl{d_{\whom} \omega_n \xi^n}{term18} + \unl{\partial_n \whom \xi^n }{term19}+ \unl{d_{\omega_n}v \xi^n }{term20} - \unl{d_{\whom } c }{term21}- \unl{[v,c] }{term22}\right)\underline{v^\dag}
\end{align*}

Before computing the pullback of the action $S_H$ note the following:
\begin{align*}
\psi^*\left(\iota_{\txi{}}F_{\whom} + F_{\tom_n}\txi{n} + d_{\whom}\tc\right) &= \iota_{\xi}F_{\whom} + F_{\omega_n}\xi^n + d_{\whom}c + L_{\xi}^{\omega} \nu + \iota_z (\nu+v) d\xi^n\\
&\phantom{=}+ X^{(a)}\mu_a^\dag d\xi^n  + d_{\omega_n}\nu \xi^n + [\nu,c]\\
\psi^*\left(\iota_{\txi{}}\underline{F_{\tom_n}} +\underline{d_{\tom_n}}\tc \right) &= \iota_{\xi}\underline{F_{\omega_n}} +\underline{d_{\omega_n}}c + \iota_{\underline{\partial_n} \xi} \nu + \underline{d_{\omega_n}}\iota_\xi v + \underline{d_{\omega_n}}\left(X^{(a)}\mu_a^\dag \xi^n\right)\\
&\phantom{=} + \underline{d_{\omega_n}}\left(\iota_{\underline{z}} \nu + \iota_{\underline{z}} v \right) + [X^{(a)}\underline{\mu}_a^\dag,c] + \iota_{\xi}d_{\whom} \left(\iota_{\underline{z}} \nu + \iota_{\underline{z}} v \right)\\
&\phantom{=} + \iota_{\xi}d_{\whom} \left(X^{(a)}\underline{\mu}_a^\dag\right)+ [\iota_{\underline{z}} \nu + \iota_{\underline{z}} v,c]\\
\psi^*\left(\frac{1}{2}\iota_{\txi{}}\iota_{\txi{}}F_{\whom} + \iota_{\txi{}}F_{\tom_n}\txi{n} + \frac{1}{2}[\tc,\tc]\right) &= \frac{1}{2}\iota_{\xi} \iota_{\xi}F_{\whom} +  \iota_{\xi}F_{\omega_n}\xi^n + \frac{1}{2}[c,c]+ \frac{1}{2}\iota_{\xi} \iota_{\xi}d_{\whom} \nu \\
&\phantom{=}+ \iota_{\xi}d_{\whom} \left(\iota_z v+ \iota_z \nu\right)\xi^n + \iota_{\xi}d_{\whom} \left(X^{(a)}\mu_a^\dag\right)\xi^n + \iota_\xi d_{\omega_n}\nu \xi^n\\
&\phantom{=} + [X^{(a)}\mu_a^\dag,c] +[\iota_\xi (\nu+v),c]+ [\iota_z (\nu+v)\xi^n,c]
\end{align*}

We divide the computation in several parts. Let us start from the classical action:
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_cl}
\psi^* &\left(\frac{1}{(N-2)!}\te^{N-2} F_{\tom_n}+ \frac{1}{(N-3)!} \te^{N-3} \underline{\te}_n F_{\widetilde{\whom}}\right) = \frac{1}{(N-2)!} e^{N-2} F_{\omega_n}+ \frac{1}{(N-3)!} e^{N-3} \underline{e}_n F_{\whom} \\ \nonumber
    & + 
    \frac{1}{(N-2)!}e^{N-2}\left( \unl{ d_{\whom} \left(X^{(a)}\underline{\mu}_a^\dag\right)}{psiSHcl1}
    +  \unl{ d_{\whom} \left(\iota_{\underline{z}}(\nu+v)\right)}{psiSHcl2}
    +\unl{ \underline{d_{\omega_n}} \nu}{psiSHcl3}
    +  \unl{ [\nu, X^{(a)}\underline{\mu}_a^\dag]}{psiSHcl4}+  \unl{[\nu,\iota_{\underline{z}}(\nu+v)]}{psiSHcl5}\right)\\ \nonumber
    &
    + \frac{1}{(N-3)!} \unl{e^{N-3} \underline{e}_n d_{\whom} \nu}{psiSHcl6}
    + \frac{1}{2(N-3)!} \unl{e^{N-3} \underline{e}_n [\nu, \nu]}{psiSHcl7}
\end{align}
We then consider the terms with antifields $\whom_n^\dag$ and $\omega^\dag$
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_o}
    \psi^*&\left((\iota_{\txi{}}F_{\whom} + F_{\tom_n}\txi{n} + d_{\whom}\tc)\widetilde{\whom}_n^\dag\right) = \left(\iota_{\xi}F_{\whom} + F_{\omega_n}\xi^n + d_{\whom}c \right) \whom_n^\dag \\ \nonumber
    &+ \left(\unl{L_{\xi}^{\omega} \nu }{psiSHon1}
    + \unl{\iota_z (\nu+v) d\xi^n }{psiSHon2}
    + \unl{X^{(a)}\mu_a^\dag d\xi^n }{psiSHon3}
    + \unl{d_{\omega_n}\nu \xi^n }{psiSHon4} 
    + \unl{[\nu,c] }{psiSHon5}
    + \unl{[\nu,\iota_{\xi}v] }{psiSHon14}
    + \unl{d_{\whom} \iota_{\xi}v}{psiSHon15}\right) \underline{\whom}_n^\dag\\ \nonumber
    & + \left(\unl{\iota_{\xi}F_{\whom}}{psiSHon6} 
    + \unl{F_{\omega_n}\xi^n }{psiSHon7}
    + \unl{d_{\whom}c }{psiSHon8} 
    + \unl{ L_{\xi}^{\omega} \nu }{psiSHon9}
    + \unl{\iota_z (\nu+v) d\xi^n }{psiSHon10}
    + \unl{X^{(a)}\mu_a^\dag d\xi^n  }{psiSHon11}\right) [\epsilon_n, \iota_{\xi}(Z_a \underline{\mu}^\dag)^{(a)}]\\ \nonumber
    & + \left(
     \unl{d_{\omega_n}\nu \xi^n  }{psiSHon12}
    + \unl{[\nu,c]}{psiSHon13}
    + \unl{[\nu,\iota_{\xi}v]}{psiSHon16}
    + \unl{d_{\whom} \iota_{\xi}v}{psiSHon17}
    \right)[\epsilon_n, \iota_{\xi}(Z_a \underline{\mu}^\dag)^{(a)}]\\\nonumber
    \psi^*&\left((\iota_{\txi{}}\underline{F_{\tom_n}} +\underline{d_{\tom_n}}\tc )\tom^\dag\right) = \left(\iota_{\xi}\underline{F_{\omega_n}} +\underline{d_{\omega_n}}c \right)\omega^\dag 
    +\left( \unl{\iota_{\underline{\partial_n} \xi} \nu}{psiSHo1} 
    + \unl{\underline{d_{\omega_n}}\iota_\xi v}{psiSHo2} \right)\omega^\dag\\ \nonumber
    &+ \left( \unl{\underline{d_{\omega_n}}\left(X^{(a)}\mu_a^\dag \xi^n\right)}{psiSHo3}
    + \unl{ \underline{d_{\omega_n}}\left(\iota_{\underline{z}} \nu \xi^n+ \iota_{\underline{z}} v \xi^n\right)}{psiSHo4}
    + \unl{[X^{(a)}\underline{\mu}_a^\dag,c + \iota_{\xi}v]}{psiSHo5} \right)\omega^\dag \\ \nonumber
    & + \left(
    \unl{\iota_{\xi}d_{\whom} \left(\iota_{\underline{z}} \nu + \iota_{\underline{z}} v \right)}{psiSHo6}
    +\unl{\iota_{\xi}d_{\whom} \left(X^{(a)}\underline{\mu}_a^\dag\right)}{psiSHo7}
    + \unl{[\iota_{\underline{z}} \nu + \iota_{\underline{z}} v,c + \iota_{\xi}v]}{psiSHo8}
    \right)\omega^\dag\\ \nonumber
    & + \left(
    \unl{\iota_{\xi}\underline{F_{\omega_n}}}{psiSHo10} +\unl{\underline{d_{\omega_n}}c }{psiSHo11}
    +\unl{\iota_{\underline{\partial_n} \xi} \nu}{psiSHo12} 
    + \unl{\underline{d_{\omega_n}}\iota_\xi v}{psiSHo13}
    + \unl{\underline{d_{\omega_n}}\left(X^{(a)}\mu_a^\dag \xi^n\right)}{psiSHo14}
    \right) [\epsilon_n, (Z_a \mu^\dag)^{(a)}\xi^n] \\ \nonumber
    &+ \left( 
    \unl{ \underline{d_{\omega_n}}\left(\iota_{\underline{z}} \nu \xi^n+ \iota_{\underline{z}} v \xi^n\right)}{psiSHo15}
    + \unl{[X^{(a)}\underline{\mu}_a^\dag,c + \iota_{\xi}v]}{psiSHo16} 
    + \unl{\iota_{\xi}d_{\whom} \left(\iota_{\underline{z}} \nu + \iota_{\underline{z}} v \right)}{psiSHo17}
    \right) [\epsilon_n, (Z_a \mu^\dag)^{(a)}\xi^n]  \\ \nonumber
    & + \left(
    \unl{\iota_{\xi}d_{\whom} \left(X^{(a)}\underline{\mu}_a^\dag\right)}{psiSHo18}
    + \unl{[\iota_{\underline{z}} \nu + \iota_{\underline{z}} v,c + \iota_{\xi}v]}{psiSHo19}
    \right) [\epsilon_n, (Z_a \mu^\dag)^{(a)}\xi^n] 
\end{align}
We now consider the terms with antifields $e_n^\dag$ and $e^\dag$:
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_e}
    \psi^*&\left(\left(L_{\txi{}}^{\widetilde{\whom} } \te  + d_{\tom_n} \te \txi{n}  + \te_n d \txi{n} - [\tc,\te] \right)\underline{\te}_n^{\dag}\right) = \left(L_{\xi{}}^{\omega }e  + d_{\omega_n} e \xi^n  + e_n d \xi^n - [c,e] \right)\underline{e}_n^{\dag}\\ \nonumber
    &+ \unl{[\iota_{\xi}v,e]\underline{e}_n^{\dag}}{psiSHe21} + \frac{1}{N-3} e^{N-4} L_{\xi{}}^{\omega }e \left(  \unl{d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) + \sigma \underline{\mu}^\dag}{psiSHe1}
    + \unl{\underline{\tau}^\dag (\nu+v)}{psiSHe2}\right)\\ \nonumber
    &+L_{\xi{}}^{\omega }e \left(\unl{X^{(a)}(Z_b \underline{\mu}^\dag)_a^{(b)}}{psiSHe3} 
    + \unl{\iota_{\underline{z}}((\nu_a+v_a) Z)^{(a)}}{psiSHe4}
    + \unl{\frac{\theta_N(5) e^{N-5}}{N-4}\epsilon_n \mu^\dag d\xi^n \underline{\tau}^\dag}{psiSHe5}\right)
    \\ \nonumber
    & + \frac{1}{N-3} e^{N-4} d_{\omega_n} e \xi^n \left(  \unl{d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) + \sigma \underline{\mu}^\dag}{psiSHe6}
    + \unl{\underline{\tau}^\dag (\nu+v)}{psiSHe7}\right)\\ \nonumber
    &+d_{\omega_n} e \xi^n \left(\unl{X^{(a)}(Z_b \underline{\mu}^\dag)_a^{(b)}}{psiSHe8} 
    + \unl{\iota_{\underline{z}}((\nu_a+v_a) Z)^{(a)}}{psiSHe9}
    + \unl{\frac{\theta_N(5) e^{N-5}}{N-4}\epsilon_n \mu^\dag d\xi^n \underline{\tau}^\dag}{psiSHe10}\right)
    \\ \nonumber
    & + \frac{1}{N-3} e^{N-4} e_n d \xi^n \left(  \unl{d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) + \sigma \underline{\mu}^\dag}{psiSHe11}
    + \unl{\underline{\tau}^\dag (\nu+v)}{psiSHe12}\right)\\ \nonumber
    &+e_n d \xi^n \left(\unl{X^{(a)}(Z_b \underline{\mu}^\dag)_a^{(b)}}{psiSHe13} 
    + \unl{\iota_{\underline{z}}((\nu_a+v_a) Z)^{(a)}}{psiSHe14}
    + \unl{\frac{\theta_N(5) e^{N-5}}{N-4}\epsilon_n \mu^\dag d\xi^n \underline{\tau}^\dag}{psiSHe15}\right)
    \\ \nonumber
    & + \frac{1}{N-3} e^{N-4} [c + \iota_{\xi} v,e] \left(  \unl{d_{\widehat{\omega}} (\epsilon_n \underline{\mu}^\dag) + \sigma \underline{\mu}^\dag}{psiSHe16}
    + \unl{\underline{\tau}^\dag (\nu+v)}{psiSHe17}\right)\\ \nonumber
    &+[c + \iota_{\xi} v,e] \left(\unl{X^{(a)}(Z_b \underline{\mu}^\dag)_a^{(b)}}{psiSHe18} 
    + \unl{\iota_{\underline{z}}((\nu_a+v_a) Z)^{(a)}}{psiSHe19}
    + \unl{\frac{\theta_N(5) e^{N-5}}{N-4}\epsilon_n \mu^\dag d\xi^n \underline{\tau}^\dag}{psiSHe20}\right)\\ \nonumber
    \psi^*&\left(\left(L_{\txi{}}^{\widetilde{\whom} } \underline{\te}_n  + \underline{d_{\tom_n}} (\te_n \txi{n})  + \iota_{\underline{\partial_n}\txi{}}\te - [\tc,\te_n] \right)\te^{\dag}\right) = \left(\iota_{\xi{}}d_{\omega}\underline{e}_n  + \iota_{\underline{\partial}_n \xi{}}e  - \underline{d_{\omega_n}}(e_n \xi^n) - [c,\underline{e}_n] \right)e^\dag \\ \nonumber
    &+ \unl{[\iota_{\xi}v,\underline{e}_n]e^{\dag}}{psiSHen5}+\left(\unl{\iota_{\xi{}}d_{\omega}\underline{e}_n }{psiSHen1} + \unl{\iota_{\underline{\partial}_n \xi{}}e }{psiSHen2} - \unl{\underline{d_{\omega_n}}(e_n \xi^n)}{psiSHen3} - \unl{[c+\iota_\xi v,\underline{e}_n]}{psiSHen4} \right)((\nu_a + v_a) Z)^{(a)}
\end{align}

Next we consider the terms with $c_n^\dag$
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_c}
    \psi^*&\left(\left(\frac{1}{2}\iota_{\txi{}}\iota_{\txi{}}F_{\whom} + \iota_{\txi{}}F_{\tom_n}\txi{n} + \frac{1}{2}[\tc,\tc]\right) \underline{\tc}_n^\dag\right) = \left(\frac{1}{2}\iota_{\xi} \iota_{\xi}F_{\whom} +  \iota_{\xi}F_{\omega_n}\xi^n + \frac{1}{2}[c,c]\right) \underline{c}_n^\dag \\ \nonumber
    &+\left( \frac{1}{2}\unl{\iota_{\xi} \iota_{\xi}d_{\whom} \nu }{psiSHc1}
    + \unl{\iota_{\xi}d_{\whom} \left(\iota_z v+ \iota_z \nu\right)\xi^n }{psiSHc2}
    + \unl{\iota_{\xi}d_{\whom} \left(X^{(a)}\mu_a^\dag\right)\xi^n }{psiSHc3}
    + \unl{\iota_\xi d_{\omega_n}\nu \xi^n }{psiSHc4}\right)\underline{c}_n^\dag \\ \nonumber
    &+ \left(\unl{[X^{(a)}\mu_a^\dag\xi^n,c]}{psiSHc5}
    +\unl{[\iota_\xi (\nu+v),c]}{psiSHc6}
    + \unl{[\iota_z (\nu+v)\xi^n,c]}{psiSHc7}\right)\underline{c}_n^\dag \\ \nonumber
     &+ \left(\unl{\frac{1}{4}\iota_{\xi}\iota_{\xi}[v,v]}{psiSHc18}+\unl{\frac{1}{2}\iota_{\xi}\iota_{\xi}[\nu,v]}{psiSHc19}+\unl{[\iota_{z}(\nu+v)\xi^n,\iota_{\xi}v]}{psiSHc20}+\unl{[X^{(a)}\mu_a^\dag \xi^n,\iota_{\xi}v]}{psiSHc21}\right)\underline{c}_n^\dag \\ \nonumber
    &+\left(\frac{1}{2}\unl{\iota_{\xi} \iota_{\xi}F_{\whom} }{psiSHc8}
    +\unl{  \iota_{\xi}F_{\omega_n}\xi^n }{psiSHc9}
    + \unl{ \frac{1}{2}[c,c]}{psiSHc10}\right) [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}] \\ \nonumber
    &+\left( \frac{1}{2}\unl{\iota_{\xi} \iota_{\xi}d_{\whom} \nu }{psiSHc11}
    + \unl{\iota_{\xi}d_{\whom} \left(\iota_z v+ \iota_z \nu\right)\xi^n }{psiSHc12}
    + \unl{\iota_{\xi}d_{\whom} \left(X^{(a)}\mu_a^\dag\right)\xi^n }{psiSHc13}
    + \unl{\iota_\xi d_{\omega_n}\nu \xi^n }{psiSHc14}\right)[\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}] \\ \nonumber
    &+ \left(\unl{[X^{(a)}\mu_a^\dag\xi^n,c]}{psiSHc15}
    +\unl{[\iota_\xi (\nu+v),c]}{psiSHc16}+ \unl{[\iota_z (\nu+v)\xi^n,c]}{psiSHc17}\right)[\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]\\ \nonumber
    &+ \left(\unl{\frac{1}{4}\iota_{\xi}\iota_{\xi}[v,v]}{psiSHc22}+\unl{\frac{1}{2}\iota_{\xi}\iota_{\xi}[\nu,v]}{psiSHc23}+\unl{[\iota_{z}(\nu+v)\xi^n,\iota_{\xi}v]}{psiSHc24}+\unl{[X^{(a)}\mu_a^\dag \xi^n,\iota_{\xi}v]}{psiSHc25}\right)[\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}] 
\end{align}
We now consider the terms with $\xi_n^\dag$ and $\xi^\dag$:
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_x}
    \psi^*&\left(\iota_{\txi{}}d\txi{n}\underline{\txi{\dag}}_n + \txi{n}\partial_n \txi{n}\underline{\txi{\dag}}_n\right)= \iota_{\xi}d\xi^n \underline{\xi}_n^\dag + \xi^n\partial_n \xi^n \underline{\xi}_n^\dag\\ \nonumber
    &+ \iota_{\xi}d\xi^n \left( \unl{X^{(a)}\underline{c}_{an}^\dag \mu^\dag }{psiSHxn1}
    + \unl{ d(e^{N-4}\epsilon \underline{\tau}^\dag \mu^\dag) }{psiSHxn2}
    + \unl{ \iota_z \underline{c}_n^\dag (\nu+v) }{psiSHxn3}
    + \unl{ \iota_z(\nu+v) [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn4}\right)\\ \nonumber
    &+ \iota_{\xi}d\xi^n \left( \unl{ d_{\omega_n}\epsilon_n (Z_a \underline{\mu}^\dag)^{(a)}}{psiSHxn5}
    + \unl{ X^{(b)}\mu_{b}^\dag [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn6}\right)\\ \nonumber
    &+ \xi^n\partial_n \xi^n \left( \unl{X^{(a)}\underline{c}_{an}^\dag \mu^\dag }{psiSHxn7}
    + \unl{ d(e^{N-4}\epsilon \underline{\tau}^\dag \mu^\dag) }{psiSHxn8}
    + \unl{ \iota_z \underline{c}_n^\dag (\nu+v) }{psiSHxn9}
    + \unl{ \iota_z(\nu+v) [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn10}\right)\\ \nonumber
    &+ \xi^n\partial_n \xi^n \left( \unl{ d_{\omega_n}\epsilon_n (Z_a \underline{\mu}^\dag)^{(a)}}{psiSHxn11}
    + \unl{ X^{(b)}\mu_{b}^\dag [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn12}\right)
    \\ \nonumber
    \psi^*&\left(\txi{n}\iota_{\partial_n\txi{}}\underline{\txi{\dag}} + \frac{1}{2}\iota_{[\txi{},\txi{}]}\underline{\txi{\dag}}\right) = \xi^{n}\iota_{\partial_n\xi}\underline{\xi}^{\dag} + \frac{1}{2}\iota_{[\xi,\xi]}\underline{\xi}^{\dag}\\ \nonumber
    & + \xi^{n}\iota_{\partial_n\xi}\left(\unl{\underline{c}_n^\dag (\nu+v) }{psiSHxn13}
    + \unl{ d_{\omega}\epsilon_n (Z_a \underline{\mu}^\dag)^{(a)} }{psiSHxn14}
    + \unl{\nu [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn15}\right)
    \\ \nonumber
    & + \frac{1}{2}\iota_{[\xi,\xi]}\left(\unl{\underline{c}_n^\dag (\nu+v) }{psiSHxn16}
    + \unl{ d_{\omega}\epsilon_n (Z_a \underline{\mu}^\dag)^{(a)} }{psiSHxn17}
    + \unl{\nu [\epsilon_n, (Z_a \underline{\mu}^\dag)^{(a)}]}{psiSHxn18}\right)
\end{align}
Lastly we consider all the remaining terms:
\setcounter{terms}{0} 
\begin{align}\label{e:psiSH_v}
        \psi^*&\left(\frac{1}{2(N-3)!}\te^{N-3}\underline{\te}_n [\tv,\tv]+\left( L_{\txi{}}^{\widetilde{\whom}} \tv + [\tc,\tv] + \txi{n} d_{\tom_n} v  + d\txi{n} \iota_z \tv \right)\underline{\tv}^\dag\right)\\ \nonumber
        &= \unl{\frac{1}{2(N-3)!}e^{N-3}\underline{e}_n[v,v]}{psiSHv11}\left( \unl{L_{\xi}^{\omega} v }{psiSHv1}
        + \unl{[c,v] }{psiSHv2}
        + \unl{\xi^{n} d_{\omega_n} v  }{psiSHv3}
        + \unl{d\xi^n \iota_z v }{psiSHv4}
        + \unl{[\iota_{\xi}v,v] }{psiSHv9}\right)\underline{v}^\dag
    \end{align}
The terms that are not underlined correspond to the ones in $S_r$. Everything else should be found in \eqref{e:standard_action_split3} or vanish.

\begin{enumerate}[label=\Alph*]
    \item The following terms simplify:
