\begin{algorithm}[th!]
	\caption{Proposed $\mathcal{H}^2$ construction algorithm for a matrix $K$ based on sketching (permutation matrices are not shown)}
	\label{alg:H2-sketch}
	\raggedright
	\textbf{Input:} Sample block size $d$, a hierarchical partitioning of the blocks of the matrix of $L$ levels, a relative compression tolerance $\epsilon$, a black-box function $Y=K_{blk}(\Omega)$ that can compute $Y=K\Omega$ with a random matrix $\Omega\in \mathbb{R}^{N\times d}$ in $O(Nd)$ time, and a function to evaluate any subblock $K_{s,t}$. \\
	\textbf{Output:} Skeletonization indices $\tilde{I}_\tau$ for each node $\tau$. $\mathcal{H}^2$ matrix $K_\mathcal{H}$ with, for each node $\tau$, $U_\tau$, $D_{\tau,b}$ ($b\in\mathcal{N}_\tau$), $B_{\tau,b}$ ($b\in\mathcal{F}_\tau$) at the leaf level, and $E_{\tau_1}$,$E_{\tau_2}$, $B_{\tau,b}$ ($b\in\mathcal{F}_\tau$) at higher levels.
