		\EndFor	  	
		\textcolor{gray}{		      \While {$\exists$ $\tau$ non-converged (via QR of $Y_\tau^{\mathrm{loc}}$)} \label{line:convergence_leaf}  
			\State \hspace{-0.35cm}$\bar{Y}=K_{blk}(\bar{\Omega})$ with a random $\bar{\Omega} \in \mathbb{R}^{N\times d}$\hspace{-0.1cm}\Comment{\textcolor{teal}{batchedRand}}\label{line:rand_bar_leaf} 
			\State \hspace{-0.35cm}$Y_\tau^{\mathrm{loc}}, \Omega_\tau^l, \forall \tau$ at $l$ = updateSamples($\bar{Y}, \bar{\Omega}, l$)\label{line:sampleupdate_leaf}
			\EndWhile   }		    

		\For{node $\tau$ at level $l$} 
		\State $Y_\tau^\mathrm{loc}=U_\tau Y_\tau^{\mathrm{loc}}(J_\tau,:)$ \label{line:ID_leaf} \Comment{ID with $\epsilon_l$. \textcolor{teal}{batchedID}}
		\State $Y^{l+1}_\tau=Y_\tau^{\mathrm{loc}}(J_\tau,:)$\label{line:update_Y_leaf}\Comment{\textcolor{teal}{batchedShrink}}
		\State $\Omega^{l+1}_\tau=U_\tau^T{\Omega}^l_\tau$\label{line:update_Omega_leaf}\Comment{\textcolor{teal}{batchedGemm}}
		\State $\tilde{I}_\tau={I}_\tau(J_\tau)$ \label{line:skeleton_leaf}\Comment{Pick the $J_{\tau}$ indices from ${I}_{\tau}$}      
		\EndFor	  		
		\Else  \Comment{Inner node}
