\end{equation}
intersecting the exceptional divisors $\mathcal{F}_1$, $\mathcal{F}_9$ and $\mathcal{F}_{10}$, or going through the points with coordinates  
\begin{equation}
    (u_0,v_0) =(0,0)\,, \qquad (U_0,V_0) =(0,0)\,, \qquad (U_8,V_8) =(0,0)
\end{equation}
in~\eqref{eq:syst_92_cascades}. Imposing these constraints we fix the value of some of the coefficient functions $b_{ij}(x)$ in~\eqref{eq:z_5_conic_92} 
\begin{equation}
    b_{20} = 0 \,, \qquad b_{02} = 0 \,, \qquad b_{01} = 0\,. 
\end{equation}
At this stage the relations expressing the coordinates $(z_5,y_5)$ in terms of $(z_{92},y_{92})$ are
\begin{equation}
    y_5 = a_{10}\, z_{92}+a_{00} \,, \qquad z_5 = b_{11}\,z_{92}\,y_{92} + b_{10}\,z_{92}+b_{00}\,. 
\end{equation}
Lastly, requiring that the variables satisfy the original systems respectively, we find the change of coordinates~\eqref{eq:change_5_92}. In particular, we find the following constraints on the remaining coefficient functions $b_{ij}(x)$:
\begin{equation}
\begin{split} 
    &b_{00}=a_{00}'\,, \qquad b_{00}'=6\,a_{00}^2+x\,, \qquad b_{10}=a_{10}'\,, \qquad b_{11}=a_{10}\,, \qquad a_{10}=6\,a_{10}^2 \,, \qquad \\[1ex]
    &b_{11}\,q+b_{10}'=a_{00}\,a_{10}\,.
\end{split} 
\end{equation}
Solving these constraints we fix all the remaining coefficient functions, i.e. 
\begin{equation}
   a_{00}=q(x)\,, \qquad a_{10}=b_{11}=\frac{1}{6}\,, \qquad b_{10}=0\,, \qquad b_{00} = q'(x)  
\end{equation}
and inserting them in the general expressions~\eqref{eq:syst_92_intermediate} and~\eqref{eq:z_5_conic_92} we find the change of variables~\eqref{eq:change_5_92}. 

\subsection{System IX.B(5)}
The system IX.B(5) is given by\footnote{Note the typo in \cite{Guillot} in the second equation, see equation (12) in \cite{Bureau table} instead. } 
\begin{equation}
\begin{cases} \label{eq:syst_95}
y' = -\,y^2 + z + 3\,q(x), \\[1ex]
z' = 4\,yz -  9\,q'(x),
\end{cases} \qquad (q''(x) - 6\,q^2(x))'' = 0\,.
\end{equation}
We assume that  function $q(x)$ in the coefficient satisfies the first Painlev\'e equation~\eqref{eq:P1}.  The system is non-Hamiltonian with respect to the standard symplectic 2-form. However, it is worth noticing that changing the coefficients of~$y^2$ to $2y^2$ in the first equation in~\eqref{eq:syst_92}, the resulting system is Hamiltonian with genus 1 Hamiltonian
\vspace*{-3ex}
\begin{equation}
H_{\text{95m}}(z,y)=9 q'\,y+3 q\, z+2\, z y^2+\frac{z^2}{2}\hspace{10ex} \includegraphics[width=.17\textwidth,valign=c]{diagrams/newton_polygons/system_95.pdf}   
\end{equation}
where the labelling 95m stays for the modified version of the system IX.B(5). 



