\begin{theorem}
Let $(y_{95}\,,z_{95})$ satisfy the system IX.B(5) in~\eqref{eq:syst_95} and $(y_{92}\,,z_{92})$ satisfy the system IX.B(2) in~\eqref{eq:syst_92} with the same $q(x)$ satisfying the first Painlev\'e equation~\eqref{eq:P1}. Then the systems are related by the birational transformation of variables
\begin{equation}\label{eq:coord_95_92}
y_{95}=-\frac{y_{92}}{2},\qquad z_{95}=-\frac{z_{92}}{2}+\frac{3 y_{92}^2}{4}-9q
\end{equation} 
and
\begin{equation}\label{eq:coord_92_95}
y_{92}=-2y_{95},\qquad z_{92}=-2(z_{95}-3y_{95}^2+9q).
\end{equation} 
\end{theorem}
%system 92 is in the orbit of iterated regularisation of system 95,  needs also scaling
\begin{proof}
We prove  the theorem with both the geometric approach and the iterative polynomial regularisation. Comparing~\eqref{eq:syst_92_diag} and~\eqref{eq:syst_95_diag} we establish the correspondence between the two classes of divisors, namely $(\mathcal{K},\mathcal{F}_i)$ and $(\mathcal{I},\mathcal{L}_i)$. We obtain the following equivalences
\begin{equation*}
    \begin{array}{l l}
        \mathcal{F}_1 = \mathcal{I} - \mathcal{L}_2 - \mathcal{L}_3  &   \mathcal{L}_1 = \mathcal{K} - \mathcal{F}_2 - \mathcal{F}_3  \\
        \mathcal{F}_2 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_3 &    \mathcal{L}_2 = \mathcal{K} - \mathcal{F}_1 - \mathcal{F}_3\\
        \mathcal{F}_3 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_2 &  \mathcal{L}_3 = \mathcal{K} - \mathcal{F}_1 - \mathcal{F}_2\\
        \mathcal{F}_4 = \mathcal{L}_6 &  \mathcal{L}_4 = \mathcal{F}_9\\
        \mathcal{F}_5 = \mathcal{L}_7 & \mathcal{L}_5 = \mathcal{F}_{10}\\
        \mathcal{F}_6 = \mathcal{L}_8 & \mathcal{L}_6 = \mathcal{F}_4  \\
        \mathcal{F}_7 = \mathcal{L}_9 & \mathcal{L}_7 = \mathcal{F}_5 \\
        \mathcal{F}_8 = \mathcal{L}_{10} & \mathcal{L}_8 =\mathcal{F}_6 \\
        \mathcal{F}_9 = \mathcal{L}_4 & \mathcal{L}_9 = \mathcal{F}_7\\
        \mathcal{F}_{10} = \mathcal{L}_5 & \mathcal{L}_{10} = \mathcal{F}_8\\
        \mathcal{K} = 2\,\mathcal{I} - \mathcal{L}_1 - \mathcal{L}_2 - \mathcal{L}_3 \hspace{10ex} & \mathcal{I} = 2\,\mathcal{K} - \mathcal{F}_1 - \mathcal{F}_2 - \mathcal{F}_3
    \end{array}
\end{equation*}
In order to find the changes of variables we consider the expressions for the axes $(z_{92}\,,y_{92})$, i.e.\ 
\begin{equation}\label{eq:change_92_95}
    \begin{split}
        y_{92}&\colon \{z_{92}=0\}  \qquad \mathcal{K} - \mathcal{F}_1  = \mathcal{I} - \mathcal{L}_1\\ 
        z_{92}&\colon \{y_{92}=0\}  \qquad \mathcal{K} - \mathcal{F}_9 - \mathcal{F}_{10}   = 2\,\mathcal{I} - \mathcal{L}_1- \mathcal{L}_2- \mathcal{L}_3- \mathcal{L}_4- \mathcal{L}_5\\ 
    \end{split}
\end{equation}
and those for the axes $(z_{95}\,,y_{95})$
\begin{equation}\label{eq:change_95_92}
    \begin{split}
        y_{95}&\colon \{z_{95}=0\}  \qquad  \mathcal{I} - \mathcal{L}_1 = \mathcal{K} - \mathcal{F}_1 \\ 
        z_{95}&\colon \{y_{95}=0\}  \qquad \mathcal{I} - \mathcal{L}_6 - \mathcal{L}_7   = 2\,\mathcal{K} - \mathcal{F}_1- \mathcal{F}_2- \mathcal{F}_3- \mathcal{F}_4- \mathcal{F}_5.\\ 
    \end{split}
\end{equation}
We start by considering the relations in~\eqref{eq:change_92_95}. The expression for $y_{92}$ is given in terms of a linear function in $(z_{95},y_{95})$ intersecting the exceptional line $\mathcal{L}_1$ or, in other words, going through the point with coordinates $(u_0,v_0)=(0,0)$ in~\eqref{eq:syst_95_cascades}. This allows us to write the following 
\begin{equation}\label{eq:line_y92}
    y_{92}\colon  a_{10}\,y_{95} + a_{01}\,z_{95} + a_{00}=0\,.
\end{equation}
By inverting the changes of coordinates in~\eqref{eq:CP2}, the relation~\eqref{eq:line_y92} can be rewritten in the chart~$(u_0,v_0)$ as 
\begin{equation}
    a_{10}\,v_0 + a_{01} + a_{00}\,u_0 = 0\,, 
\end{equation}
and imposing that the point $(u_0,v_0)=(0,0)$ is part of the line, we find the condition $a_{01}=0$. For the expression for the axis $z_{92}$ the procedure is similar, but involves more steps since the expression in~\eqref{eq:change_92_95} is a conic 
\begin{equation}\label{eq:line_z92}
    z_{92}\colon b_{20}\,(y_{95})^2+b_{11}\,y_{95}\,z_{95} + b_{02}\,(z_{95})^2 + b_{10}\,y_{95} + b_{01}\,z_{95} + b_{00}=0 
\end{equation}
and to fix the parameters of the conic $b_{ij}(x)$ we impose that the conic intersects the lines $\mathcal{L}_1$, $\mathcal{L}_2$, $\mathcal{L}_3$, $\mathcal{L}_4$ and $\mathcal{L}_5$, or in other words it goes through the points with coordinates identified by the charts~$(u_0,v_0)$, $\dots$, $(u_4,v_4)$ in~\eqref{eq:syst_95_cascades}. We start by rewriting~\eqref{eq:line_z92} in terms of the chart $(u_0,v_0)$ by inverting the relations in~\eqref{eq:CP2}, i.e.
\begin{equation}
    b_{20}\,(v_0)^2+b_{11}\,v_0 + b_{02} + b_{10}\,u_0\,v_0 + b_{01}\,u_0 + b_{00}\,(u_0)^2=0 \,,
\end{equation}
and imposing the passage through the point $(u_0,v_0)=(0,0)$ we fix the parameter $b_{02}=0$. We now consider the same expression in the chart $(U_1,V_1)$, i.e. 
\begin{equation}
    b_{20}\,V_1+b_{11} + b_{10}\,U_1\,V_1 + b_{01}\,U_1 + b_{00}\,(U_1)^2\,V_1=0 \,,
\end{equation}
from which we find $b_{11}=0$ imposing the passage through the point $(U_1,V_1)=(0,0)$. Considering the same for the remaining intersecting points we fix the coefficient functions
\begin{equation}
    b_{20} = -3\,b_{01}\,, \qquad b_{10} = 0 \,, \qquad b_{00} = 9q(x)\,b_{01}\,.
\end{equation}
Therefore, we can rewrite the expressions~\eqref{eq:line_y92} and~\eqref{eq:line_z92} as 
\begin{equation}
    \begin{split}
    y_{92} = a_{10}\,y_{95}+a_{00} , \qquad 
    z_{92} = b_{01}(z_{95} - 3\,y_{95}^2+9q(x)).
    \end{split} 
\end{equation}
Finally, the last coefficients are fixed by requiring that the coordinates $(y_{92},z_{92})$ satisfy the system~\eqref{eq:syst_92}, and we obtain the final expressions~\eqref{eq:coord_95_92}. 

By inverting the form of~\eqref{eq:coord_95_92} we find~\eqref{eq:coord_92_95}, that is also verified starting from~\eqref{eq:change_95_92} and proceeding analogously to what we shown above, i.e.\ looking for the constraints to obtain the set of coefficient functions for a linear and a conic expression to describe the axes $y_{95}$ and $z_{95}$ respectively.  

We give a second proof of the theorem via the iterative polynomial regularisation. We consider the system in $(z_{95},y_{95})$ and proceed with the blow-up transformations until it is regularised. In the regularisation process we stress that we make use of the intermediate change of variables $(u_i,v_i)\mapsto (\tilde{u}_i,1/\tilde{v}_i)$ in correspondence with the first non-zero point of indeterminacy. We are interested in one of the two regularised system in the final charts. In coordinates $(u,v)$ this takes the form
\begin{equation}\label{eq:syst_95_reg_1}
   \begin{cases} 
   u'=-2+6 q u^2 -u^3 v,\\[1ex]
   v'=-6 q- u v+u^2 v^2\,. 
   \end{cases}
\end{equation}
The regularising transformation for this cascade is obtained by tracking back all the coordinate transformations to get the regularised system. Hence, we can reconstruct the expression of the coordinate functions $(z_{95},y_{95})$ in terms of the variables of the final chart $(u,v)$, as 
\begin{equation}
   z_{95}=\frac{3+u^2(uv-9q)}{u^2}\,, \qquad  y_{95}=\frac{1}{u}\,. 
\end{equation}
We now consider the system~\eqref{eq:syst_95_reg_1} in the variables $(u,v)$ and iterate the regularisation process. We choose a compactification for $(u,v) \in \mathbb{C}^2$ and identify the points of indeterminacy. Just after one blow-up we obtain the regular polynomial system in the new set of coordinates $(w(x),t(x))$ 
\begin{equation}\label{eq:syst_95_reg_2}
   \begin{cases} 
   w'=2\,w^2+t-6q,\\[1ex] 
   t'=-2\,wt,
   \end{cases}
\end{equation}
with $(u,v)\mapsto (1/w,\,wt)$. We observe that the system~\eqref{eq:syst_95_reg_2} is similar to the system IX.B(2) in~\eqref{eq:syst_92}, and they coincide once we consider the rescaling of the variables
\begin{equation}
    w=-\frac{y_{92}}{2},\qquad t=-\frac{z_{92}}{2}\,.
\end{equation}
Taking the composition of all the transformation of variables and their rescaling, we obtain the statement of the theorem. 
\end{proof} 






A direct consequence of the previous Theorem is the following

\begin{corollary}
Combining the transformations relating the system V and the system IX.B(2) in~\eqref{eq:change_5_92} with the transformations~\eqref{eq:change_95_92} relating the system IX.B(2) and IX.B(5), we have 
\begin{equation}\label{eq:syst_95_5}
    y_{95}=-\frac{z_5-q'}{2(y_5-q)},\qquad z_{95}=-9 q-3(y_5-q)+\frac{3(z_5-q')^2}{4(y_5-q)^2}
\end{equation}
and 
\begin{equation}\label{eq:syst_5_95}
    y_5=-2q+y_{95}^2-\frac{z_{95}}{3},\qquad z_5=6 q\, y_{95}-2y_{95}^3+\frac{2}{3}\,y_{95}\,z_{95}+q'.
\end{equation}
\end{corollary}
The expressions in~\eqref{eq:syst_95_5} and~\eqref{eq:syst_5_95} can be obtained from the geometric approach as well, from the comparison between~\eqref{eq:syst_5_diagram} and~\eqref{eq:syst_92_diag}. This allows us to find the correspondence of the components:  % %The correspondence between the elements $(\mathcal{H},\mathcal{E}_i)$ in system V in~\eqref{eq:syst_5_diagram} and $(\mathcal{I},\mathcal{L}_i)$ in system IX.B(5) in~\eqref{eq:syst_92_diag} is the following 
\begin{equation*}
    \begin{array}{l l}
        \mathcal{E}_1 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_5  &   \mathcal{L}_1 = 2\,\mathcal{H} - \mathcal{E}_1 - \mathcal{E}_2 - \mathcal{E}_3 - \mathcal{E}_4  -\mathcal{E}_{10}   \\
        \mathcal{E}_2 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_4 &    \mathcal{L}_2 = \mathcal{H} - \mathcal{E}_4  -\mathcal{E}_{10} \\
        \mathcal{E}_3 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_3 &  \mathcal{L}_3 = \mathcal{H} - \mathcal{E}_3  -\mathcal{E}_{10}  \\
        \mathcal{E}_4 = \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_2 &  \mathcal{L}_4 = \mathcal{H} - \mathcal{E}_2  -\mathcal{E}_{10}\\
        \mathcal{E}_5 = \mathcal{L}_6 & \mathcal{L}_5 = \mathcal{H} - \mathcal{E}_1  -\mathcal{E}_{10}\\
        \mathcal{E}_6 = \mathcal{L}_7 & \mathcal{L}_6 = \mathcal{E}_5  \\
        \mathcal{E}_7 = \mathcal{L}_8 & \mathcal{L}_7 = \mathcal{E}_6 \\
        \mathcal{E}_8 = \mathcal{L}_{9} & \mathcal{L}_8 =\mathcal{E}_7 \\
        \mathcal{E}_9 = \mathcal{L}_{10} & \mathcal{L}_9 = \mathcal{E}_8\\
        \mathcal{E}_{10} = 2\,\mathcal{I} - \mathcal{L}_1 - \mathcal{L}_2 - \mathcal{L}_3 -2\,\mathcal{L}_5 & \mathcal{L}_{10} = \mathcal{E}_9\\
        \mathcal{H} = 3\,\mathcal{I} - 2\,\mathcal{L}_1 - \mathcal{L}_2 - \mathcal{L}_3 - \mathcal{L}_4 - \mathcal{L}_5 \hspace{10ex} & \mathcal{I} = 3\,\mathcal{H} - \mathcal{E}_1 - \mathcal{E}_2 - \mathcal{E}_3 - \mathcal{E}_4 - 2\, \mathcal{E}_{10}
    \end{array}
\end{equation*}
Analogously to the way we proceeded above, we consider the axes for the coordinates $(z_5,y_5)$ in terms of the coordinates $(z_{95},y_{95})$, i.e.
\vspace*{-1ex}
\begin{equation}
    \begin{split}
        y_5 &\colon \{z_5=0\} \qquad \mathcal{H}-\mathcal{E}_1 = 2\, \mathcal{I} - \mathcal{L}_1 - \mathcal{L}_2 - \mathcal{L}_3 - \mathcal{L}_4 \\[1ex]
        z_5 &\colon \{y_5=0\} \qquad \mathcal{H} = 3\,\mathcal{I} - 2\,\mathcal{L}_1 - \mathcal{L}_2 - \mathcal{L}_3 - \mathcal{L}_4 - \mathcal{L}_5.
    \end{split}
\end{equation}
The first expression gives us a conic for $y_5$ as a function of $(z_{95},y_{95})$, whereas the second expression describes a cubic for $z_5$ in the variables $(z_{95},y_{95})$. The generic conic and cubic curves are 
\begin{align}
\label{eq:y5_in_95}
    y_5 &\colon~~ b_{20}\,(z_{95})^2+b_{11}\,z_{95}\,y_{95} + b_{02}\,(y_{95})^2 + b_{10}\,z_{95} + b_{01}\,y_{95} + b_{00}=0\,,  \\[1ex]
    \label{eq:z5_in_95}
   \begin{split}  z_5 &\colon~~ c_{30}\,(z_{95})^3+c_{21}\,z_{95}^2\,y_{95} +c_{12}\,z_{95}\,y_{95}^2 + c_{03}\,(y_{95})^3  \\ 
   & ~~~~ + c_{20}\,(z_{95})^2+c_{11}\,z_{95}\,y_{95} + c_{02}\,(y_{95})^2 + c_{10}\,z_{95} + c_{01}\,y_{95} + c_{00}=0 \,. 
   \end{split}
\end{align}
The conic~\eqref{eq:y5_in_95} goes through the points $(u_0,v_0)=(0,0)$, $\dots$, $(u_3,v_3)=(0,0)$ in~\eqref{eq:syst_95_cascades}, fixing the coefficients 
\begin{equation}
    b_{20}=0\,, \qquad b_{11}=0\,, \qquad b_{10}=-\frac{b_{02}}{3}\,, \qquad b_{01}=0\,. 
\end{equation}
The cubic~\eqref{eq:z5_in_95} goes through the points $(u_0,v_0)=(0,0)$, $(U_1,V_1)=(0,0)$, $(\tilde{u}_2,\tilde{v}_2)=(0,3)$, $(u_3,v_3)=(0,0)$ and $(u_4,v_4)=(0,-9\,q(x))$ in~\eqref{eq:syst_95_cascades}, producing the constraints on the coefficients
\begin{equation}
    c_{30}=0\,, \quad c_{21}=0\,, \quad c_{20}=-\frac{c_{12}}{3}\,, \quad c_{11}=-\frac{c_{03}}{3}\,, \quad c_{10}=-\frac{c_{02}}{3}+ 27\,c_{12}\,q(x).
\end{equation}
The change of variables for $y_5$ and $z_5$ is then 
\begin{equation}\label{eq:intermediate_change_5_95}
\begin{split} 
    y_5&=b_{02} \left( y_{95}^2 -\frac{z_{95}}{3} \right) +b_{00} \,, \\[1ex] 
    z_5 &= c_{00}+c_{01} y_{95}+c_{02} \left( y_{95}^2-\frac{ z_{95}}{3}\right)+c_{03} \left( y_{95}^3-\frac{y_{95} z_{95}}{3} \right)+c_{12} \left(y_{95}^2 z_{95}-\frac{z_{95}^2}{3}  +27 q z_{95}\right). 
    \end{split} 
\end{equation}
Lastly, the remaining coefficient functions are completely determined by requiring that the transformed variables still satisfy the system V. In particular, equating the coefficient functions of terms of the same order in $(z_{95},y_{95})$, we obtain the following constraints
\begin{equation}
\begin{split} 
    c_{00}&= b_{00}'+ 3\,b_{02}\,q'\,,\quad c_{01}=6 q\,,\quad c_{02}= b_{02}' \,, \quad c_{03}=-2\,b_{02}\,,\quad c_{12}=0\,, \\[1ex]
    b_{00}&= -2q\,, \qquad b_{02}=1 \,, 
\end{split} 
\end{equation}
which included in the expression~\eqref{eq:intermediate_change_5_95} yield the transformation~\eqref{eq:syst_5_95}, with the function $q(x)$ always satisfying $\text{P}_{\text{I}}$. 







\subsection{System XIV} 
The system XIV is given by 
\begin{equation}\label{eq:syst_14}
\begin{array}{c c}
\begin{cases} 
y' = y(2z - y) + 3\,p(x)\,y + r(x), \\[1ex]
z' = z(y - z) - 2\,p(x)\,z,
\end{cases}  & \qquad \begin{aligned}
     q(x) &= \frac{1}{12}(p'(x) + p^2(x) - r(x)), \\[1ex]
      r'(x) &= p(x)\,r(x),\quad   (q''(x) - 6\,q^2(x))'' = 0\,. 
\end{aligned}
\end{array}
\end{equation} 
We assume that the function $q(x)$, which is hidden  in the regularisation conditions, satisfies $\text{P}_{\text{I}}$ in~\eqref{eq:P1}, and we stress the fact that this system is non-Hamiltonian. 

To regularise the system XIV, we find three cascades of blow-ups from $\mathbb{P}^2$, emerging from the origins of the charts $(u_0,v_0)$ and $(U_0,V_0)$ and from the additional point of indeterminacy visible in both charts, with coordinates $(u_0,v_0)=(0,3/2)$ and $(U_0,V_0)=(2/3,0)$ respectively:
