        \mathcal{E}_{11} = \mathcal{J} - \mathcal{G}_1 - \mathcal{G}_2 \hspace{10ex} & \mathcal{G}_{11} = \mathcal{E}_{9}\\
        \mathcal{H} = 3\,\mathcal{J} - 2\,\mathcal{G}_1 - \mathcal{G}_2 - \mathcal{G}_3 - \mathcal{G}_4 - \mathcal{G}_5 \hspace{10ex} & \mathcal{J} = 3\,\mathcal{H} - \mathcal{E}_1 - \mathcal{E}_2 - \mathcal{E}_3 - 2\, \mathcal{E}_{10} - \mathcal{E}_{11} .
