        z_5 &\colon \{y_5=0\} \qquad \mathcal{H} = 3\,\mathcal{J} - 2\,\mathcal{G}_1 - \mathcal{G}_2 - \mathcal{G}_3 - \mathcal{G}_4 - \mathcal{G}_5
