\begin{equation}
    b_{20}=0\,, \quad b_{02}=0\,, \quad b_{10}=0\,, \quad b_{01}=0\,, 
\end{equation}
for the conic representing $y_5$ in the first expression of~\eqref{eq:y5z5_syst14}, and 
\begin{equation}
    c_{30}=0\,, \quad c_{03}=0\,, \quad c_{20}=0\,, \quad c_{02}=0\,, \quad c_{10}=r\,c_{21}\,, 
\end{equation}
for the cubic representing $z_5$ in the second expression of~\eqref{eq:y5z5_syst14}. 
The change of variables from the coordinates $(z_5,y_5)$ to $(z_{14},y_{14})$ is then given by the relations
\begin{equation}
\begin{split} 
    y_5 &= b_{11}\, z_{14}\,y_{14}+b_{00}\,,  \\[1ex]
    z_5 &= c_{00}+c_{01}\, y_{14}+c_{11}\, y_{14} z_{14}+c_{12}\, y_{14}^2 z_{14}+c_{21} (r z_{14}+ y_{14} z_{14}^2)\,. 
    \end{split}
\end{equation}
By requiring that the systems V and XIV are satisfied, we set the remaining coefficients. In particular, we have 
\begin{equation}
    \begin{split}
        c_{00}&= b_{00}'\,, \quad c_{01}=0\,, \quad c_{11}=b_{11}\,p+b_{11}'\,, \quad c_{12}=0\,, \quad c_{21}=b_{11}   \\[1ex]
        b_{00}&=\frac{1}{12}(p'+p^2+r) \,, \quad b_{11}=\frac{1}{6}\,, 
