			\node (b0) at (a0) {$(u_0,v_0)=(0\,, 0)$};
			\node (b1) at (a1) {$(U_1,V_1)=(0\,, 0)$};
			\node (b2) at (a2) {$(\tilde{u}_2,\tilde{v}_2)=(0\,, 2)$};
