        \node (b2) at (a2) {$(u_3,v_3)=(0\,,-(f(x)+2\,p'(x)+2\,p^2(x)))$};
        \node (b3) at (a3) {$\hspace*{-20ex}(u_{4},v_{4})=(0\,,f'(x)+4\,p(x)p'(x)+2\,p''(x))$};
