    \caption{PAs measured using a mock model of slow precession. The parameters of the models are as follows: $\delta=10, \Psi_0=10, \alpha=4, \phi_0=200$ and $\zeta=90$ where all the angles are in degrees. \emph{Top} shows PA versus Spin phase for different Spin cycles using different colors. The three vertical dotted lines mark the Spin phases chosen to show PA versus Spin cycle in the \emph{bottom} panel. See Sect.~\ref{ssec:slowp}.}
    \label{fig:simslowp}
\end{figure}

