  \centering
  \includegraphics[width=0.7\textwidth]{Fig1ab.png}
  \caption{(Top) General view of the cylindrical plasma waveguide. Metal coating, transversely inhomogeneous plasma and drive bunch are shown schematically. The on-axis drive bunch moves along the waveguide axis, (bottom) The waveguide plasma density versus the radial coordinate is shown schematically.}\label{Fig:01}
\end{figure}
\section{Analytical studies}
To determine the wakefield excited in the waveguide by a drive bunch of arbitrary charge and current distribution, this the bunch may be conceived as a set of infinitely thin and short rings, and as a preliminary, we shall determine the wakefield of such an infinitely short and thin charged ring. The charge and current densities of the ring particle of radius $r_0$ and charge $q_0$, which moves at a constant velocity v along the waveguide axis ($z$ axis) without  transverse displacement, may be written as
\begin{equation}\label{eq:01}
\begin{split}
\rho(r,z,t) = \frac{q_0}{2\pi r_0v}\delta(r-r_0)\delta(t-t_0-z/v),\,j_z = v\rho,
\end{split}
\end{equation}
where $t_0$  is the time taken by the particle to pass across the coordinate $z=0$, and $\delta(x)$ is the Dirac delta function. By virtue of the fact that the problem is homogeneous in both the time and the direction parallel to the drive bunch velocity, it appears convenient to represent all the quantities as the Fourier double integral over the frequency $\omega$, and over the longitudinal component of the wavenumber $k_z$, parallel to the bunch vector velocity. Then we have
\begin{equation}\label{eq:02}
\begin{split}
\begin{Bmatrix}\mathbf{E}(r,z,t)\\\mathbf{D}(r,z,t)\\\mathbf{H}(r,z,t)\\\end{Bmatrix}&= \int\limits_{ - \infty }^{ + \infty }dk_z\int\limits_{ - \infty }^{ + \infty } {d\omega \begin{Bmatrix}\mathbf{E}_\omega (r,k_z,\omega )\\\varepsilon(\omega)\mathbf{E}_\omega (r,k_z,\omega )\\\mathbf{H}_\omega (r,k_z,\omega )\\\end{Bmatrix} }{e^{ ik_{z}z - i\omega t}}{\text{,}}\\
\begin{Bmatrix}\rho(r,z,t)\\j_z(r,z,t)\\\end{Bmatrix}&= \int\limits_{ - \infty }^{ + \infty }dk_z\int\limits_{ - \infty }^{ + \infty } {d\omega \begin{Bmatrix}\rho_\omega (r,k_z,\omega )\\j_{z\omega} (r,k_z,\omega )\\\end{Bmatrix} }{e^{ik_{z}z - i\omega t}}{\text{.}}
\end{split}
\end{equation}
The dielectric permittivity $\varepsilon(\omega)$ in each of the plasma homogeneity regions $i=(1)-(3)$ is determined by the corresponding plasma density $n_{p(i})$
\begin{equation}\label{eq:03}
\varepsilon(\omega) = \varepsilon_{p(i)}(\omega) =  1 - \omega _{p(i)}^2/{\omega ^2}, \quad \omega^2_{p(i)}=4\pi e^2n_{p(i)}/m_e
\end{equation}
where $e$ and $m_e$ denotes the electron charge and mass, respectively, the ion contribution to the dielectric permittivity will be neglected. From using Maxwell’s equations for the wakefield Fourier-components we obtain the wave equation for the axial component of the electric field $E_{z\omega}$ in the $i$-th region of the piecewise homogeneous plasma
\begin{equation}\label{eq:04}
\begin{split}
\frac{1}{r}\frac{\partial }{{\partial r}}\left( {r\frac{{\partial E_{z\omega} }}{{\partial r}}} \right) + k^2_{\perp p(i)}E_{z\omega} = \frac{iq_0\delta (r-r_0)\delta (k_z - \omega /v)}{\pi r_0v\varepsilon_{p(i)}}\left( k_ze^{ik_zvt_0} - \frac{\varepsilon_{p(i)}\omega v}{c^2}e^{i\omega t_0} \right),
\end{split}
\end{equation}
where the transverse component of the wave vector $k^2_{\perp p(i)}$ is equal to $k^2_{\perp p(i)}=\varepsilon_{p(i)}\omega^2/c^2-k_{z}^2$. The Fourier components of the radial electric field $E_{r\omega}$ and the azimuthal magnetic field $H_{\varphi \omega}$ are expressed in terms of  $E_{z\omega}$
\begin{equation}\label{eq:05}
\begin{split}
H_{\varphi \omega} = \frac{\omega \varepsilon (\omega)}{ck_z}E_{r\omega},\,\,E_{r\omega} = \frac{ik_z}{\varepsilon (\omega)\omega^2/c^2 - k_z^2}\frac{\partial E_{z\omega}}{\partial r}.
\end{split}
\end{equation}
To determine the excited wakefield, by convention the waveguide is divided into four regions: (I)--$(0 \leq r \leq r_0)$, (II)--$(r_0 < r \leq a)$, (III)--$(a < r \leq b)$ and (IV)--$(b < r \leq R)$. The solutions to Eq.~(\ref{eq:04}) for each of the mentioned regions can be written as:
\begin{equation}\label{eq:06}
\begin{split}
&E_{z\omega}^{(I)} = A_{1}\frac{J_0(k_{\perp p(1)}r)}{J_0(k_{\perp p(1)}r_0)},\\
&E_{z\omega}^{(II)} = A_{1}\frac{F_0(k_{\perp p(1)}r,k_{\perp p(1)}a)}{F_0(k_{\perp p(1)}r_0,k_{\perp p(1)}a)} + A_{2}\frac{F_0(k_{\perp p(1)}r,k_{\perp p(1)}r_0)}{F_0(k_{\perp p(1)}a,k_{\perp p(1)}r_0)},\\
&E_{z\omega}^{(III)} = A_{2}\frac{F_0(k_{\perp p(2)}r,k_{\perp p(2)}b)}{F_0(k_{\perp p(2)}a,k_{\perp p(2)}b)} + A_{3}\frac{F_0(k_{\perp p(2)}r,k_{\perp p(2)}a)}{F_0(k_{\perp p(2)}b,k_{\perp p(2)}a)},\\
&E_{z\omega}^{(IV)} = A_{3}\frac{F_0(k_{\perp p(3)}r,k_{\perp p(3)}R)}{F_0(k_{\perp p(3)}b,k_{\perp p(3)}R)},
\end{split}
\end{equation}
where ${F_0}(x,y) = J_0(x)Y_0(y) - Y_0(x)J_0(y)$, $J_0$ and $Y_0$ are, the zeroth-order Bessel and Weber cylinder functions. With this form of writing the solutions to Eq.~(\ref{eq:04}), the axial component of the electric field $E_{z\omega}$ is continuous at the boundaries of plasma regions, while on the metal coating surface ($r=R$) vanishes. The constants $A_{1}$, $A_{2}$ and $A_{3}$ should be determined through the use of the remaining boundary conditions: the axial component of the magnetic field is continuous at the plasma region boundaries ($r=a,b$), while at the beam surface ($r=r_0$) this component experiences a current density-defined jump
\begin{equation}\label{eq:07}
\left( \frac{dE^{(II)}_{z\omega}}{dr} \right)_{r=r_0} - \left( \frac{dE^{(I)}_{z\omega}}{dr} \right)_{r=r_0} = \frac{iq_0\delta (k_z - \omega /v)}{\pi r_0v\varepsilon_{p(1)}}\left( k_ze^{ik_zvt_0} - \frac{\varepsilon_{p(1)}\omega v}{c^2}e^{i\omega t_0} \right).
\end{equation}
Substituting the first two expressions from system~(\ref{eq:06}) into Eq.~(\ref{eq:07}), and performing integration over the longitudinal component of the wavenumber $k_z$, we obtain the expressions for $E_{z\omega}$ in all four regions of the waveguide
\begin{equation}\label{eq:08}
\begin{split}
E^{(I)}_{z\omega} = -\frac{iq_0}{\pi a\omega}\frac{J_0(\varkappa_{p(1)}r)J_0(\varkappa_{p(1)}r_0)}{J^2_0(\varkappa_{p(1)}a)}\frac{D_{2}(\omega ,\omega/v)}{D(\omega ,\omega/v)}e^{i\omega t_0 + i\omega/vz} +\\
\frac{iq_0\varkappa^2_{p(1)}}{2\omega \varepsilon_{p(1)}}\frac{J_0(\varkappa_{p(1)}r)F_0(\varkappa_{p(1)}r_0,\varkappa_{p(1)}a)}{J_0(\varkappa_{p(1)}a)}e^{i\omega t_0 + i\omega/vz},
\end{split}
\end{equation}
\begin{equation}\label{eq:09}
\begin{split}
E^{(II)}_{z\omega} = -\frac{iq_0}{\pi a\omega}\frac{J_0(\varkappa_{p(1)}r)J_0(\varkappa_{p(1)}r_0)}{J^2_0(\varkappa_{p(1)}a)}\frac{D_{2}(\omega ,\omega/v)}{D(\omega ,\omega/v)}e^{i\omega t_0 + i\omega/vz} +\\
\frac{iq_0\varkappa^2_{p(1)}}{2\omega \varepsilon_{p(1)}}\frac{J_0(\varkappa_{p(1)}r_0)F_0(\varkappa_{p(1)}r,\varkappa_{p(1)}a)}{J_0(\varkappa_{p(1)}a)}e^{i\omega t_0 + i\omega/vz},
\end{split}
\end{equation}
\begin{equation}\label{eq:10}
\begin{split}
E^{(III)}_{z\omega} = -\frac{iq_0}{\pi a\omega D(\omega ,\omega/v)}\frac{J_0(\varkappa_{p(1)}r_0)}{J_0(\varkappa_{p(1)}a)}\left( \frac{F_0(\varkappa_{p(2)}r,\varkappa_{p(2)}b)}{F_0(\varkappa_{p(2)}a,\varkappa_{p(2)}b)}D_2(\omega ,\omega/v) + \right. \\ \left.\frac{F_0(\varkappa_{p(2)}r,\varkappa_{p(2)}a)}{F_0(\varkappa_{p(2)}b,\varkappa_{p(2)}a)}\frac{F_1(\varkappa_{p(2)}b,\varkappa_{p(2)}b)}{\varkappa_{p(2)}F_0(\varkappa_{p(2)}a,\varkappa_{p(2)}b)} \right)e^{i\omega t_0 + i\omega/vz},
\end{split}
\end{equation}
\begin{equation}\label{eq:11}
\begin{split}
E^{(IV)}_{z\omega} = -\frac{iq_0}{\pi \varkappa_{p(2)}a\omega D(\omega ,\omega/v)}\frac{J_0(\varkappa_{p(1)}r_0)}{J_0(\varkappa_{p(1)}a)}\frac{F_1(\varkappa_{p(2)}b,\varkappa_{p(2)}b)}{F_0(\varkappa_{p(2)}a,\varkappa_{p(2)}b)}\times\\
\frac{F_0(\varkappa_{p(3)}r,\varkappa_{p(3)}R)}{F_0(\varkappa_{p(3)}b,\varkappa_{p(3)}R)}e^{i\omega t_0 + i\omega/vz},
\end{split}
\end{equation}
where $\varkappa_{p(1)} = k_{\perp p(1)}(k_z=\omega/v)$,\,$\varkappa_{p(2)} = k_{\perp {p(2)}}(k_z=\omega/v)$,\,$\varkappa_{p(3)} = k_{\perp p(3)}(k_z=\omega/v)$, $F_1(x,y) = -J_1(x)Y_0(y)+Y_1(x)J_0(y)$, $J_1$ and $Y_1$ are the Bessel and Weber cylindrical first-order functions. In Eqs.~(\ref{eq:08})--(\ref{eq:11}) the expression for $D(\omega ,k_z)$ is defined as
\begin{equation}\label{eq:12}
\begin{split}
D(\omega ,k_z) &= D_1(\omega ,k_z)D_2(\omega ,k_z) + D_3(\omega ,k_z),\\
D_1(\omega ,k_z) &= \frac{\varepsilon_{p(1)}}{k_{\perp p(1)}}\frac{J_1(k_{\perp p(1)}a)}{J_0(k_{\perp p(1)}a)} + \frac{\varepsilon_{p(2)}}{k_{\perp p(2)}}\frac{F_1(k_{\perp p(2)}a,k_{\perp p(2)}b)}{F_0(k_{\perp p(2)}a,k_{\perp p(2)}b)},\\
D_2(\omega ,k_z) &= \frac{\varepsilon_{p(3)}}{k_{\perp p(3)}}\frac{F_1(k_{\perp p(3)}b,k_{\perp p(3)}R)}{F_0(k_{\perp p(3)}b,k_{\perp p(3)}R)} - \frac{\varepsilon_{p(2)}}{k_{\perp p(2)}}\frac{F_1(k_{\perp p(2)}b,k_{\perp p(2)}a)}{F_0(k_{\perp p(2)}b,k_{\perp p(2)}a)},\\
D_3(\omega ,k_z) &= \frac{\varepsilon_{p(2)}^2}{k_{\perp p(2)}^2}\frac{F_1(k_{\perp p(2)}a,k_{\perp p(2)}a)F_1(k_{\perp p(2)}b,k_{\perp p(2)}b)}{F_0(k_{\perp p(2)}b,k_{\perp p(2)}a)F_0(k_{\perp p(2)}a,k_{\perp p(2)}b)}.
\end{split}
\end{equation}
Having made the Fourier inverse frequency $\omega$ transform from expressions Eqs.~(\ref{eq:08})--(\ref{eq:11}) we obtain the equations for the longitudinal component of the electric field. The integration over frequency reduces to the summation over the residues in the poles of the integrands, which are defined by the zeros of the functions $\varepsilon_{p(1)}(\omega)$ and $D(\omega ,\omega/v)$. The equation  $\varepsilon_{p(1)}(\omega)=0$ determines the frequency of the plasma (Langmuir) wave $\omega_{p(1)}$ in the region $r\leq a$, and the corresponding poles are found only in the expressions for the Fourier components of the electric field in this region. The equation $D(\omega ,\omega/v)=0$ defines the waveguide eigenfrequencies $\omega_s$, being resonant with the drive bunch (Cherenkov resonance), and the corresponding poles are present in the expressions for the Fourier components of both the electric and magnetic fields throughout the waveguide regions. Finally, the longitudinal electric field, excited by the ring charged particle, has the form:
\begin{equation}\label{eq:13}
\begin{split}
E^{(I)}_z(r,z,t,r_0,t_0) = 2q_0k^2_{p(1)}\frac{I_0(k_{p(1)}r)}{I_0(k_{p(1)}a)}\Delta_{0}(k_{p(1)}r_0,k_{p(1)}a)\times\\
\cos\omega_{p(1)}(t-t_0-z/v)\theta(t-t_0-z/v) - \sum_{s}^{}\frac{4q_0}{a\omega_s}\frac{J_0(\varkappa_{p(1)s}r)J_0(\varkappa_{p(1)s}r_0)}{J^2_0(\varkappa_{p(1)s}a)}\frac{D_{2s}}{D'({\omega_s})}\times\\
\cos\omega_s(t-t_0-z/v)\theta(t-t_0-z/v),
\end{split}
\end{equation}
\begin{equation}\label{eq:14}
\begin{split}
E^{(II)}_z(r,z,t,r_0,t_0) = 2q_0k^2_{p(1)}\frac{I_0(k_{p(1)}r_0)}{I_0(k_{p(1)}a)}\Delta_{0}(k_{p(1)}r,k_{p(1)}a)\times\\
\cos\omega_{p(1)}(t-t_0-z/v)\theta(t-t_0-z/v) - \sum_{s}^{}\frac{4q_0}{a\omega_s}\frac{J_0(\varkappa_{p(1)s}r)J_0(\varkappa_{p(1)s}r_0)}{J^2_0(\varkappa_{p(1)s}a)}\frac{D_{2s}}{D'({\omega_s})}\times\\
\cos\omega_s(t-t_0-z/v)\theta(t-t_0-z/v),
\end{split}
\end{equation}
\begin{equation}\label{eq:15}
\begin{split}
E^{(III)}_z(r,z,t,r_0,t_0) = -\sum_{s}^{}\frac{4q_0}{a\omega_s D'({\omega_s})}\frac{J_0(\varkappa_{p(1)s}r_0)}{J_0(\varkappa_{p(1)s}a)}\left( \frac{F_0(\varkappa_{p(2)s}r,\varkappa_{p(2)s}b)}{F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)}D_{2s} + \right. \\ \left.\frac{F_0(\varkappa_{p(2)s}r,\varkappa_{p(2)s}a)}{F_0(\varkappa_{p(2)s}b,\varkappa_{p(2)s}a)}\frac{\varepsilon_{p(2)s}F_1(\varkappa_{p(2)s}b,\varkappa_{p(2)s}b)}{\varkappa_{p(2)s}F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)} \right)\cos\omega_s(t-t_0-z/v)\theta(t-t_0-z/v),
\end{split}
\end{equation}
\begin{equation}\label{eq:16}
\begin{split}
E^{(IV)}_z(r,z,t,r_0,t_0) = -\sum_{s}^{}\frac{4q_0}{a\omega_s D'({\omega_s})}\frac{J_0(\varkappa_{p(1)s}r_0)}{J_0(\varkappa_{p(1)s}a)}\frac{\varepsilon_{p(2)s}F_1(\varkappa_{p(2)s}b,\varkappa_{p(2)s}b)}{\varkappa_{p(2)s}F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)}\times\\
\frac{F_0(\varkappa_{p(3)s}r,\varkappa_{p(3)s}R)}{F_0(\varkappa_{p(3)s}b,\varkappa_{p(3)s}R)}\cos\omega_s(t-t_0-z/v)\theta(t-t_0-z/v),
\end{split}
\end{equation}
where $k_{p(1)}=\omega_{p(1)}/v$, $\varkappa_{p(1)s} = \varkappa_{p(1)}(\omega_s)$,\,$\varkappa_{p(2)s} = \varkappa_{p(2)}(\omega_s)$,\,$\varkappa_{p(3)s} = \varkappa_{p(3)}(\omega_s)$,\,$D_{2s}=D_{2}(\omega_s ,\omega_s/v)$, and $D'(\omega_s)=\left( \frac{d D(\omega ,\omega/v)}{d \omega} \right)_{\omega=\omega_s}$, $\Delta _0(x,y) = I_0(x)K_0(y) - K_0(x)I_0(y)$, $I_{0}$ and $K_{0}$ are the modified zeroth-order Bessel and McDonald  functions.
Expressions~(\ref{eq:13})--(\ref{eq:16}) demonstrate that the longitudinal component of the electric field in the plasma background region at $r\leq a$ is contributed by two summands, namely, the wakefield of the Langmuir wave at frequency $\omega_{p(1)}$, and the wakefield of the eigenwaves, resonant with the drive bunch at frequencies $\omega_{s}$. Apparently, the wakefield of the Langmuir wave is localized in the plasma background region at $r\leq a$,  whereas in the tubular plasma regions and in the plasma background region at $b \leq r\leq a$, it is absent.  Physically, this is due to the Langmuir wave field screening by the surface charge induced at the plasma background-tubular plasma interface~\cite{Balakirev1997}.

To determine wakefield excited by the bunch of finite size, there is a need to summate the wakefields generated by the whole set of infinitely thin and short  charged rings, in the form of which  the drive bunch has been initially represented. We assume that the drive bunch has the following charge density distribution within its boundaries: the rectangular profile in the radial direction and the cosine-like profile in the longitudinal direction. In going from the ring-shaped charged particle to the bunch of finite sizes in the  longitudinal and transverse directions, it is necessary that in expressions~(\ref{eq:13})--(\ref{eq:16}) the charge $q_0$  should be replaced by the expression $q_0 = (Q_b/\pi R^2_bT_b)(1-\cos2\pi t_0/T_b)2\pi dt_0dr_0r_0$, and be integrated over the radius $r_0$ in the range from  0 to $R_b$, and also, over the time of fly into the waveguide, $t_0$, within the range  0 to $T_b$, where $T_b = L_b/v$ is the time duration of the drive bunch.

The final expression for the axial wakefield excited by the finite-size drive bunch, in the plasma background region at $r\leq a$ have the following form:
\begin{equation}\label{eq:17}
\begin{split}
E_z(r,z,t) = -\frac{4Q_b}{R_bL_b}\left( [\theta(r)-\theta(r-R_b)]R_{z1}(r) + \right. \\ \left.
[\theta(r-R_b)-\theta(r-a)]R_{z2}(r) \right)\Psi_{\parallel}(t,z,\omega_{p(1)}) -\\
\sum_{s}^{}\frac{8Q_bv}{R_bL_ba\varkappa_{p(1)s}\omega^2_s}\frac{D_{2s}}{D'({\omega_s})}
\frac{J_1(\varkappa_{p(1)s}R_b)J_0(\varkappa_{p(1)s}r)}{J_0^2(\varkappa_{p(1)s}a)}\Psi_{\parallel}(t,z,\omega_s),
\end{split}
\end{equation}

\begin{equation}\label{eq:18}
\begin{split}
&R_{z1}(r) = \frac{1}{k_{p(1)}R_b} - \frac{I_0(k_{p(1)}r)}{I_0(k_{p(1)}a)}\Delta_{1}(k_{p(1)}R_b,k_{p(1)}a),\\
&R_{z2}(r) = -\frac{I_1(k_{p(1)}R_b)}{I_0(k_{p(1)}a)}\Delta_{0}(k_{p(1)}r,k_{p(1)}a),
\end{split}
\end{equation}

\begin{equation}\label{eq:19}
\begin{split}
E_z(r,z,t) = -\sum_{s}^{}\frac{8Q_bv}{R_bL_ba\varkappa_{p(1)s}\omega_s D'({\omega_s})}\frac{J_1(\varkappa_{p(1)s}R_b)}{J_0(\varkappa_{p(1)s}a)}\left( \frac{F_0(\varkappa_{p(2)s}r,\varkappa_{p(2)s}b)}{F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)}D_{2s} + \right. \\ \left.\frac{F_0(\varkappa_{p(2)s}r,\varkappa_{p(2)s}a)}{F_0(\varkappa_{p(2)s}b,\varkappa_{p(2)s}a)}\frac{\varepsilon_{p(2)s}F_1(\varkappa_{p(2)s}b,\varkappa_{p(2)s}b)}{\varkappa_{p(2)s}F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)} \right)\Psi_{\parallel}(t,z,\omega_s),
\end{split}
\end{equation}

\begin{equation}\label{eq:20}
\begin{split}
E_z(r,z,t) = -\sum_{s}^{}\frac{8Q_bv}{R_bL_ba\varkappa_{p(1)s}\omega_s D'({\omega_s})}\frac{J_1(\varkappa_{p(1)s}R_b)}{J_0(\varkappa_{p(1)s}a)}\frac{\varepsilon_{p(2)s}F_1(\varkappa_{p(2)s}b,\varkappa_{p(2)s}b)}{\varkappa_{p(2)s}F_0(\varkappa_{p(2)s}a,\varkappa_{p(2)s}b)}\times\\
\frac{F_0(\varkappa_{p(3)s}r,\varkappa_{p(3)s}R)}{F_0(\varkappa_{p(3)s}b,\varkappa_{p(3)s}R)}\Psi_{\parallel}(t,z,\omega_s).
\end{split}
\end{equation}
The corresponding expressions for the transverse wakefield components in the plasma background region at $r\leq a$ are written as:
\begin{equation}\label{eq:21}
\begin{split}
E_r(r,z,t) = -\frac{4Q_b}{R_bL_b}\left( [\theta(r)-\theta(r-R_b)]R_{r1}(r) + \right. \\ \left.
[\theta(r-R_b)-\theta(r-a)]R_{r2}(r) \right)\Psi_{\perp}(t,z,\omega_{p(1)}) +\\
\sum_{s}^{}\frac{8Q_bv}{R_bL_ba\varkappa^2_{p(1)s}\omega_s a}\frac{D_{2s}}{D'({\omega_s})}
\frac{J_1(\varkappa_{p(1)s}R_b)J_1(\varkappa_{p(1)s}r)}{J_0^2(\varkappa_{p(1)s}a)}\Psi_{\perp}(t,z,\omega_s),
\end{split}
\end{equation}
\begin{equation}\label{eq:22}
\begin{split}
&R_{r1}(r) = \frac{I_1(k_{p(1)}r)}{I_0(k_{p(1)}a)}\Delta_{1}(k_{p(1)}R_b,k_{p(1)}a),\\
&R_{r2}(r) = \frac{I_1(k_{p(1)}R_b)}{I_0(k_{p(1)}a)}\Delta_{1}(k_{p(1)}r,k_{p(1)}a),
\end{split}
\end{equation}
\begin{equation}\label{eq:23}
\begin{split}
H_\varphi(r,z,t) = \sum_{s}^{}\frac{8\beta \varepsilon_{p(1)s}Q_b}{R_bL_ba\varkappa^2_{p(1)s}\omega_s a}\frac{D_{2s}}{D'({\omega_s})}
\frac{J_1(\varkappa_{p(1)s}R_b)J_1(\varkappa_{p(1)s}r)}{J_0^2(\varkappa_{p(1)s}a)}\Psi_{\perp}(t,z,\omega_s),
\end{split}
\end{equation}
where $\Delta _1(x,y) = I_1(x)K_0(y) + K_1(x)I_0(y)$, $I_{1}$ and $K_{1}$ are the modified first-order Bessel and McDonald functions. The longitudinal-temporal structure of the excited wakefield is described by the functions $\Psi_{\parallel}(t,z,\omega)$ and $\Psi_{\perp}(t,z,\omega)$, which have the form:
\begin{equation}\label{eq:24}
\begin{split}
\Psi_{\parallel}(t,z,\omega) = &\frac{1}{\omega T_b}\bigg( \theta(t - z/v)\sin\omega(t - z/v) - \theta(t - z/v - T_b)\sin\omega(t - z/v - T_b) \bigg) -\\
&\frac{1}{4\pi^2 - \omega^2 T_b^2}\left( \theta(t - z/v)\left\{2\pi \sin\frac{2\pi}{T_b}(t - z/v) - \omega T_b\sin\omega(t - z/v)\right\} -\right. \\& \left. \theta(t - z/v - T_b)\left\{2\pi \sin\frac{2\pi}{T_b}(t - z/v-T_b) - \omega T_b\sin\omega(t - z/v-T_b)\right\} \right),
\end{split}
\end{equation}
\begin{equation}\label{eq:25}
\begin{split}
\Psi_{\perp}(t,z,\omega) = &\frac{1}{\omega T_b}\bigg( \theta(t - z/v)\Big(1-\cos\omega(t - z/v)\Big) - \theta(t - z/v - T_b)\Big(1-\cos\omega(t - z/v - T_b)\Big) \bigg) -\\
&\frac{\omega T_b}{\omega^2 T_b^2 - 4\pi^2}\left( \theta(t - z/v)\left\{\cos\frac{2\pi}{T_b}(t - z/v) - \cos\omega(t - z/v)\right\} -\right. \\& \left. \theta(t - z/v-T_b)\left\{\cos\frac{2\pi}{T_b}(t - z/v-T_b) - \cos\omega(t - z/v-T_b)\right\} \right).
\end{split}
\end{equation}
The first summands in the expressions for the axial and radial components of the excited electric field~(\ref{eq:17})--(\ref{eq:23}), which are responsible for the Langmuir wave contribution to the total wakefield, are dependent only on the parameters of the drive bunch and the plasma background in the area of the waveguide axis. The second summands in the expressions for the axial and radial components of the excited electric field, which are responsible for the contribution of surface eigenwaves (resonant with the drive bunch) to the total wakefield, are dependent on the parameters of both the drive bunch and the plasma waveguide. Between the solutions of the Maxwell equations for the drive bunch-generated electric and magnetic fields~(\ref{eq:17})--(\ref{eq:23}), there is an important qualitative difference. The azimuthal component of the generated magnetic field~(\ref{eq:23}) is determined only by the field of surface eigenwaves. The Langmuir wave cannot contribute to the generated magnetic field, as the field of this wave is electrostatic in its nature, in contrast to the field of the eigenwaves, being in resonance with the drive bunch, which is electromagnetic in character.
\section{Numerical analysis}
With analytical expressions~(\ref{eq:17})--(\ref{eq:25}) we numerically investigate the space-time structure of the components of the generated wakefield in the THz plasma waveguide under consideration. For the numerical analysis, the plasma waveguide parameters were chosen such that the plasma wavelength in the region of the plasma background should be equal to $\lambda_{p(1)}=\lambda_{p(3)}=3\,mm$ (accordingly, the plasma frequency be $f_{p(1)}=99.9\,GHz$), and the eigenfrequency of the waveguide, resonant with the bunch, should be three times higher than $f_{p(1)}$. The parameters involved in the numerical analysis are presented in~Tab.\ref{Tabl_1}.
