\section{UV Series Expansion of Quantum Entanglement Measures}
\label{app:uv_expansion}

Here we detail the UV series expansion for HEE, MI, and EWCS. For HEE, we consider a strip of width $w$ and length $L_y$ (taken to infinity). The HEE $S$ and width $w$ are determined by the turning point $z_s$ of the minimal surface in the bulk, as given by Eq.~\eqref{Calculation equation for S and w under arbitrary zs}.

In the UV limit, $w \to 0$, which corresponds to $z_s \to 0$. Expanding $w(z_s)$ and $S(z_s)$ from Eq.~\eqref{Calculation equation for S and w under arbitrary zs} in powers of $z_s$:
\begin{equation}
	\begin{aligned}
		w & = 2 \mu \left[ \Gamma z_s + f_1 z_s^2 + f_2 z_s^3 + f_3 z_s^4 + O(z_s^5) \right],                    \\
		S & = \frac{L_y}{ 2 \mu G_N } \left[ -\frac{\Gamma}{z_s} + g_1 + g_2 z_s + g_3 z_s^2 + O(z_s^3) \right],
	\end{aligned}
	\label{eq:app_l_and_S_in_zs_to_0}
\end{equation}
where $\Gamma = \frac{\sqrt{\pi} \Gamma(3/4) }{ \Gamma(1/4)}$ is a constant. The coefficients $f_i$ and $g_i$ are functions of the near-boundary values of the metric and scalar field components and their $z$-derivatives at $z=0$: $\hat U^{(n)} \equiv \partial_z^n U|_{z=0}$, $\hat V_1^{(n)} \equiv \partial_z^n V_1|_{z=0}$, etc. These are related by the equations of motion at the boundary, e.g.,
\begin{equation}
	\begin{aligned}
		 & \hat{U}^{(1)} = \hat{V}_1^{(1)} = \hat{V}_2^{(1)},  \quad \hat{U}^{(2)} = \hat{V}_1^{(2)} = \hat{V}_2^{(2)},                     \\
		 & \left( \hat{U}^{(1)} \right)^2 - 2 \hat{U}^{(2)} = 3 \left( \hat{\phi}^{(0)} \right)^2,                                          \\
		 & \hat{V}_2^{(3)} + \hat{V}_1^{(3)} = -6 \left( \hat{\phi}^{(0)} \right)^2 \hat{V}_1^{(1)} - 12 \hat{\phi}^{(0)} \hat{\phi}^{(1)},
	\end{aligned}
	\label{eq:app_boundary_field_conditions}
\end{equation}
where $\hat \phi^{(0)} = \mu \lambda$. The explicit forms of Eq.~\eqref{eq:app_l_and_S_in_zs_to_0} are:
\begin{equation}
	\begin{aligned}
		 & \lim_{z_s \to 0} w = 2 \mu \Bigg[ \Gamma z_s
		- \frac{1}{2} \hat{V}_1^{(1)} \Gamma z_s^2
		+ \left( \frac{\Gamma}{4} \left( \hat{V}_1^{(1)} \right)^2
		- \frac{\pi - 12 \Gamma^2}{32 \Gamma} \mu^2 \lambda^2 \right) z_s^3       \\
		 & + \left( \frac{(4 + \mu^2) \pi}{64}
		+ \frac{3 \pi - 8 \pi \Gamma - 20 \Gamma^2}{64 \Gamma} \mu^2 \lambda^2 \hat{V}_1^{(1)}
		- \frac{\Gamma}{8} \left( \hat{V}_1^{(1)} \right)^3
		- \frac{\pi - 2 \Gamma}{4} \mu \lambda \hat{\phi}^{(1)}
		- \frac{\pi}{96} (\hat{U}^{(3)} + \hat{V}_1^{(3)}) \right) z_s^4
		+ O(z_s^5) \Bigg],                                                        \\
		 & \lim_{z_s \to 0} S = \frac{L_y}{ 2 \mu G_N} \Bigg[ -\frac{\Gamma}{z_s}
		+ \frac{1 - \Gamma}{2} \hat{V}_1^{(1)}
		+ \frac{3 (4 \Gamma^2 - \pi)}{32 \Gamma} \mu^2 \lambda^2 z_s              \\
		 & + \Bigg( \frac{\pi (4 + \mu^2)}{32}
		+ \frac{3 \pi - 16 \pi \Gamma + 4 \Gamma^2}{64 \Gamma} \mu^2 \lambda^2 \hat{V}_1^{(1)}
		+ \frac{ \Gamma - \pi }{2} \mu \lambda \hat{\phi}^{(1)}
		- \frac{\pi}{48} \left( \hat{U}^{(3)} + \hat{V}_1^{(3)} \right) \Bigg) z_s^2
		+ O(z_s^3) \Bigg].
	\end{aligned}
	\label{eq:relationship_S_l_zs_small_width}
\end{equation}
Inverting $w(z_s)$ to find $z_s(w)$:
\begin{equation}
	\begin{aligned}
		 & z_s = \frac{w}{2 \Gamma \mu} + \frac{ \hat V_1^{(1)} w^2 }{8 \Gamma^2 \mu^2} + \left[ (\pi-12\Gamma^2)\mu^2 \lambda^2 +  8 \Gamma^2 \left( \hat V_1^{(1)} \right)^2 \right] \frac{w^3}{256 \Gamma^5 \mu^3} + \bigg[ - 3 \Gamma \pi (4+\mu^2)
		\\
		 & + 6 \left( \pi + 4 \pi \Gamma - 20 \Gamma^2 \right) \mu^2 \lambda^2 \hat V_1^{(1)} + 24 \Gamma^2 \left( \hat V_1^{(1)} \right)^3 + 48 \Gamma (\pi - 2\Gamma)\mu \lambda \hat \phi^{(1)} + 2 \pi \Gamma \left( \hat U^{(3)} + \hat V_1^{(3)}\right) \bigg] \frac{w^4}{3072 \Gamma^6 \mu^4} + O(w^5).
		\label{eq:zs_small_w}
	\end{aligned}
\end{equation}
Substituting $z_s(w)$ into $S(z_s)$ yields $S(w)$ for small $w$:
\begin{equation}
	\begin{aligned}
		S(w) =
		\frac{L_y}{4 \mu G_N} \bigg[ -\frac{4 \Gamma^2 \mu}{w} + \underbrace{\hat V_1^{(1)}}_{P_S} - \frac{\pi \lambda^2 \mu}{16 \Gamma^2} w
		+ \left( C_{21} + C_{22} \underbrace{(\hat U^{(3)} - \hat V_1^{(3)} - 2\hat V_2^{(3)})}_{P_{IE}} \right) w^2 + O(w^3) \bigg] ,
		\label{eq:app_S_of_w_in_small_w}
	\end{aligned}
\end{equation}
where $C_{21} = \frac{\pi(4+\mu^2)}{128 \Gamma^2 \mu^2}$ and $C_{22} = - \frac{\pi} {192 \Gamma^2 \mu^2}$ are constants independent of $k$. The $k$-dependence of $S(w)$ at leading order (constant term in $w$) comes from $P_S \equiv \hat V_1^{(1)}$. The next significant $k$-dependent term appears at $O(w^2)$ through $ P_{IE} \equiv \hat U^{(3)} - \hat V_1^{(3)} - 2\hat V_2^{(3)} $.

For MI and EWCS, we consider a symmetric configuration $a=c=n\,b$ (for some constant $n$) and take $b \to 0$. In the presence of entanglement, combining Eqs.~\eqref{eq:definition_of_I}, \eqref{eq:definition_of_S_AC} and the UV expansion of $S$ \eqref{eq:app_S_of_w_in_small_w} yields:
\begin{equation}
	\begin{aligned}
		I = S(nb) + S(nb) - S((2n+1)b) - S(b) = \frac{L_y}{ 4 \mu G_N } \bigg[ C_{I0} \frac{1}{b} + C_{I1} b
			+ \left(C_{I21} + C_{I22} P_{IE} \right) b^2 + O(b^3) \bigg] ,
		\label{eq:app_MI_expression}
	\end{aligned}
\end{equation}
where $C_{I0}, C_{I1}, C_{I21}$, and $C_{I22}$ are $k$-independent coefficients derived from the $w^{-1}, w^1$, and $w^2$ terms in Eq.~\eqref{eq:app_S_of_w_in_small_w}. Importantly, the $P_S$ term cancels out in MI, and the leading $k$-dependence of MI comes from $ P_{IE}$ at $O(b^2) $.

For EWCS, in the symmetric configuration $a=c$, the minimal cross-section $\Sigma_{AB}$ is a surface at constant $x$ that extends from $z=0$ to some $z_s = z_{max}$). In the UV limit ($b \to 0$), the dominant contribution comes from $z \approx 0$. A similar expansion for $E_W$ (Eq.~\eqref{eq:EWCS}) yields:
\begin{equation}
	\begin{aligned}
		E_W = \frac{L_y}{4 \mu G_N} \bigg[ C_{E0} \frac{1}{b} + C_{E1} b + \left( C_{E21} + C_{E22} P_{IE} \right) b^2 + O(b^3) \bigg] .
	\end{aligned}
	\label{eq:app_EWCS_expression}
\end{equation}
Again, $C_{E0}, C_{E1}, C_{E21}$, and $C_{E22}$ are $k$-independent, and the leading $k$-dependence arises from $ P_{IE}$ at $O(b^2)$. The precise coefficients $C_{I0}, C_{I1}, C_{I21}, C_{I22}$ and $C_{E0}, C_{E1}, C_{E21}, C_{E22}$ depend on $n$ and other constants but their $k$-independence is what matters.

Thus, in the UV limit, both MI and EWCS have their leading $k$-dependence governed by the same geometric deformation term $ P_{IE} \equiv \hat U^{(3)} - \hat V_1^{(3)} - 2\hat V_2^{(3)} $:
\begin{equation}
	\partial_k^n I \propto \partial_k^n E_W \propto \partial_k^n P_{IE}.
	\label{eq:app_MI_proportional_EWCS}
\end{equation}
This explains why their third derivatives with respect to $k$ exhibit similar extremal behavior near the QCP, as shown in Fig.~\ref{fig:figureofMIandEW}.

