\title{Topologically protected edge oscillations in nonlinear dynamical units}

\author{Sayantan Nag Chowdhury}
\email{snagchowdh@constructor.university}
\affiliation{School of Science, Constructor University, P.O.Box 750561, 28725 Bremen, Germany}
\author{Hildegard Meyer-Ortmanns}
\email{hmeyerortm@constructor.university}
\affiliation{School of Science, Constructor University, P.O.Box 750561, 28725 Bremen, Germany} 
\affiliation{Complexity Science Hub, Vienna, Metternichgasse 8, 1030 Wien, Austria}
