\section{Symmetries of the Hamiltonian and their implications on the spectrum}\label{app2}
\label{appendixB}

\begin{lemma}\label{Theo1}
	Suppose, $\mathcal{H}(k_x, k_y)$ satisfies the inversion symmetry given in Eq.\ \eqref{inversion}. Then, the matrices $\mathcal{H}(k_x, k_y)$ and $\mathcal{H}(-k_x, -k_y)$ have the same eigenvalues.
\end{lemma}
\begin{proof}
	Let, $\mathcal{H}(k_x, k_y)\mathbf{v} = \lambda \mathbf{v}$; where $\lambda$ is an eigenvalue and $\mathbf{v}$ is the corresponding eigenvector.\\\\
	Now,  $\mathcal{I}(\mathcal{H}(k_x, k_y)\mathbf{v}) = \mathcal{I} (\lambda \mathbf{v}) $; where \(\mathcal{I} = \mathbf{\sigma}_x \otimes I_4\). So we have, 
	\begin{equation}\label{app1}
		 (\mathcal{I}\mathcal{H}(k_x, k_y))\mathbf{v} = \lambda (\mathcal{I} \mathbf{v}). 
	\end{equation}
By Eq.\ \eqref{inversion}, we have 	
	\begin{equation}\label{app2}
		\mathcal{I} \mathcal{H}(k_x, k_y) = \mathcal{H}(-k_x, -k_y)\mathcal{I}. 
	\end{equation}
	By combining Eqs.\ \eqref{app1} and \eqref{app2}, we get
		\begin{equation}\label{app3}
				 \mathcal{H}(-k_x, -k_y)(\mathcal{I}\mathbf{v}) = \lambda (\mathcal{I} \mathbf{v}). 
	\end{equation}
	Thus, the matrices \(\mathcal{H}(k_x, k_y)\) and \(\mathcal{H}(-k_x, -k_y)\) have the same eigenvalues. While the transformation preserves the eigenvalues, it alters the corresponding eigenvectors through the action of \(\mathcal{I}\). 
\end{proof}	

\begin{lemma}\label{Theo2}
	If $\mathcal{H}(k_x, k_y)$ satisfies the time-reversal symmetry given in Eq.\ \eqref{time-reversal}, then the eigenvalues of $\mathcal{H}(k_x, k_y)$ and $\mathcal{H}(-k_x, -k_y)$ come in complex conjugate pairs. That is, if $\lambda$ is an eigenvalue of $\mathcal{H}(k_x, k_y)$, then $\lambda^{*}$, the complex conjugate of $\lambda$, will be an eigenvalue of $\mathcal{H}(-k_x, -k_y)$.
\end{lemma}
\begin{proof}
		Let, $\mathcal{H}(k_x, k_y)\mathbf{v} = \lambda \mathbf{v}$; where $\mathbf{v}$ is an eigenvector of the matrix $\mathcal{H}(k_x, k_y)$ with an associated eigenvalue  $\lambda$.  
		Now, by Eq.\ \eqref{time-reversal}, we have 
		\begin{equation} \label{B4}  
			\mathcal{H}^{*}(k_x, k_y) = \mathcal{H}(-k_x, -k_y).  
		\end{equation}
		Now,  $\mathcal{H}(k_x, k_y)\mathbf{v} = \lambda \mathbf{v}$ $\implies$  $\mathcal{H}^{*}(k_x, k_y)\mathbf{v}^{*} = \lambda^{*} \mathbf{v}^{*}$. Using Eq.\ \eqref{B4}, we have
		\begin{equation} \label{app5}  
			\mathcal{H}(-k_x, -k_y)\mathbf{v}^{*} = \lambda^{*} \mathbf{v}^{*}.  
		\end{equation}
	which completes the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}  \label{Theo4}
	If our effective Hamiltonian \(\mathcal{H}(k_x, k_y)\) satisfies both time-reversal symmetry, as defined in Eq.\ \eqref{time-reversal}, and inversion symmetry, as given in Eq.\ \eqref{inversion}, then it necessarily violates PT symmetry, which is expressed in Eq.\ \eqref{PT}.  
\end{lemma}  
\begin{proof}  
	Suppose, for the sake of contradiction, that the Hamiltonian \(\mathcal{H}(k_x, k_y)\) satisfies PT symmetry. Additionally, we assume that \(\mathcal{H}(k_x, k_y)\) also obeys time-reversal and inversion symmetry.
	From the PT-symmetry assumption, we have  
	\begin{equation}  
		(\mathcal{I}\mathcal{T}) \mathcal{H}(k_x, k_y) (\mathcal{I}\mathcal{T})^{-1} = \mathcal{H}(k_x, k_y).  
	\end{equation}  
	This implies
	\begin{equation}  
		(\mathcal{I}\mathcal{T}) \mathcal{H}(k_x, k_y) (\mathcal{T}^{-1}\mathcal{I}^{-1}) = \mathcal{H}(k_x, k_y).  
	\end{equation}  
	Applying the time-reversal symmetry condition, this simplifies to  
	\begin{equation}  
		\mathcal{I} \mathcal{H}^{*}(-k_x, -k_y) \mathcal{I}^{-1} = \mathcal{H}(k_x, k_y).  
	\end{equation}  
	Using inversion symmetry, we then obtain  
	\begin{equation}  
		\mathcal{H}^{*}(k_x, k_y) = \mathcal{H}(k_x, k_y).  
	\end{equation}  
	This implies that \(\mathcal{H}(k_x, k_y)\) contains no complex terms, which contradicts the fact that the Hamiltonian has complex components. Hence, our initial assumption that \(\mathcal{H}(k_x, k_y)\) satisfies PT symmetry must be false, and the result follows.  
\end{proof}  


