\section{Black-Scholes identities}
Let  $\Black(F,K,v,T)$ denotes the Black-76 formula applied to the forward $F$, strike $K$ and total variance $v$ to maturity $T$:
\begin{equation}\Black(F,K,v,T)=\eta B(0,T) \left[F\Phi(\eta d_1)-K\Phi(\eta d_2)\right]\label{eqn:black}
\end{equation} with $d_1 = \frac{1}{\sqrt{v}}\left(\ln\frac{F}{K} + \frac{1}{2}v\right)$, $d_2 = d_1 -  \sqrt{v}$.

We also define \begin{equation}
	h(x) = \max(\eta x, 0)
\end{equation}
which constitutes the basis of our Taylor expansions.

\begin{identity}\label{identity:EGn}
	Let $G_n^\star = \frac{\beta}{G(T,1,m_p-1)}$ and $G_p^\star = \alpha G(T,m_p,m)$, we have
	\begin{equation}\mathbb{E}\left[ B(0,T) {G_n}^\star(T) h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] = \Black\left(1, \kappa^\star, {\nu}^2, T\right)\,,\end{equation}
	where  $\nu = \tilde{\nu}$ for the geometric approximation, $\nu$ computed from $a_i$ for the Levy approximation. 
\end{identity}
\begin{proof}
We have  $\mathbb{E}\left[ G_n^\star(T)\right] = 1$ and $G_n^\star$ may be thus expressed as \begin{equation*} G_n^\star(T)=e^{-\frac{1}{2}\int_0^T\gamma_n(s)^2\diff s + \int_0^T \gamma_n(s)  dW_{G_n}(T)}\end{equation*} in probability, with $W_{G_n}$ being a Brownian motion and $\gamma_n^2(s)=\frac{\partial \nu_n^2(s)}{\partial s}$. We interpret $\frac{G_n^\star(T)}{G_n^\star(0)}$ as a change of measure on $\mathcal{F}_T$. Under the new induced measure $\mathbb{Q}^{G_n}$, $\tilde{W}_{G_n} (T)= W_{G_n}(T) - \int_0^T \gamma_n(s) \diff s $ is a Brownian motion. Then $G_n^\star(T)$ under $\mathbb{Q}^{G_n}$ has the same law as $G_n^\star(T) e^{\nu_n^2 (T)}$ under $\mathbb{Q}$. Thus,
\begin{align}	
	\mathbb{E}\left[  {G_n}^\star(T) h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] &= \mathbb{E}^{G_n}\left[ \left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{\nu_{np}^2(T) -\nu_n^2 (T)} - \kappa^\star\right)^+ \right]\,,\label{eqn:margrabe}
\end{align}
where 
\begin{equation}
	\nu_{np}^2(T) = -\sum_{i=1}^{m_p-1}\sum_{j=m_p}^m  a_i a_j \rho_{i,j}\int_0^T \sigma_i(s) \sigma_j(s) \diff s\,. \label{eqn:nunp}
\end{equation}
We have  \begin{equation}
	\nu^2=\nu_n^2 + \nu_p^2 - 2 \nu_{np}^2\,.\label{eqn:nu_decomp}
\end{equation}
We know that ${G_p}^\star / G_n^\star$ has variance $\nu^2$. Furthermore, $G_n^\star$ and $G_p^\star$ are martingales of unit expectation under $\mathbb{Q}$, thus \begin{equation}
\mathbb{E}\left[\frac{{G_p}^\star}{{G_n}^\star}(T)\right]=e^{-\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}}\,.\label{eqn:EGpoverGn}
\end{equation}

Then using Equations \ref{eqn:nu_decomp} and \ref{eqn:margrabe}, we obtain the result.
\end{proof} 

\begin{identity}\label{identity:EGp}
	\begin{equation}
		\mathbb{E}\left[B(0,T)  G_p^\star(T) h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = \Black\left(e^{\nu^2(T)}, \kappa^\star, \nu^2, T\right)\,.
	\end{equation}
\end{identity}
\begin{proof}
We perform a change of measure $\frac{G_p^\star(T)}{G_p^\star(0)}$. Under this new measure $\mathbb{Q}^{G_p}$, $\tilde{W}_{G_p} (T)= W_{G_p}(T) - \int_0^T \gamma_p(s) \diff s $, with $\gamma_p^2(s)=\frac{\partial \nu_p^2(s)}{\partial s}$ is a Brownian motion. Then $\frac{G_p}{G_n}^\star(T)$ under $\mathbb{Q}^{G_p}$ has the same law as $\frac{G_p}{G_n}^\star(T) e^{\nu_p^2-\nu_{pn} (T)}$ under $\mathbb{Q}$. Thus,
\begin{align}	\mathbb{E}\left[  G_p^\star(T) h\left( \frac{G_p^\star(T)}{ G_n^\star(T)}- \kappa^\star\right)\right] &= \mathbb{E}^{G_p}\left[h\left( \frac{{G_p}^\star}{G_n^\star}(T)e^{\nu_p^2(T)-\nu_{np}^2 (T)} - \kappa^\star\right) \right]\,.\label{eqn:EGpGp}
\end{align}
%-nu_p + nu_n +nu  /2 + nu_p - nu_np = nu_p/2+nu_n/2 -nu/2 -nu_np = 0
Using Equation \ref{eqn:nu_decomp}, we find that the right hand side corresponds to a vanilla option price under the Black model with  forward $e^{\nu^2(T)}$, strike $\kappa^\star$ and total variance $\nu^2(T)$.
\end{proof}
%let $G^\star = \frac{G_p^\star}{G_n^\star}e^{\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}}$. According to \ref{eqn:EGpoverGn}, it is a martingale under $\mathbb{Q}$, we perform a change of measure $\frac{G^\star(T)}{G^\star(0)}$. Under this new measure $\mathbb{Q}^{G}$, $\tilde{W}_G (T)= W_G(T) - \int_0^T \beta(s) \diff s $, with $\beta^2(s)=\frac{\partial \nu^2(s)}{\partial s}$ is a Brownian motion. Then $G^\star(T)$ under $\mathbb{Q}^G$ has the same law as $G^\star(T) e^{\nu^2 (T)}$ under $\mathbb{Q}$. Thus,
%\begin{align}	\mathbb{E}\left[  G_p^\star(T) h'\left( {G_p^\star}(T)- \kappa^\star{G_n^\star}\right)\right] &= -e^{-\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}}\frac{\partial}{\partial \kappa^\star} \mathbb{E}^G\left[h\left( \frac{{G_p}^\star}{G_n^\star}(T)e^{\nu^2 (T)} - \kappa^\star\right) \right]\,.\label{eqn:EGG}
