\begin{identity}\label{identity:ESi}
\begin{equation}
	\mathbb{E}\left[  S_{i}^{\star}(T) h\left( \frac{G_p^\star}{G_n^\star}- \kappa^\star\right)\right] = \Black\left(e^{-\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}+\bar{v}_i},\kappa^\star,\nu^2,T\right)\,.
\end{equation}
with \begin{align}\bar{v}_i = \sum_{l=1}^n a_l v_{i,l}\,,&\quad v_{i,l} = \rho_{i,l}\int_{0}^T \sigma_i(s) \sigma_l(s)\diff s\,.\label{eqn:vibar_vil}\end{align}
\end{identity}
In particular, for an Asian, we have  $v_{i,l} = \int_{0}^{t_i \wedge t_j} \sigma^2(s)\diff s$. For baskets, the volatilities are taken to be constant equal to each underlying implied volatility to maturity in practice and we have  $v_{i,l} = \rho_{i,l} \sqrt{v_i v_l}$.


\begin{proof}
We use a change of measure $\frac{S_{i}^{\star}(T)}{S_i^\star(0)}$ and define \begin{equation*}\tilde{W}_i(t) = W_i(t) - \int_0^t \sigma_i(s) \diff s \end{equation*}  to obtain
\begin{align}	\mathbb{E}\left[  S_{i}^{\star}(T) h\left( \frac{G_p^\star}{G_n^\star}- \kappa^\star\right)\right] &= \mathbb{E}^i\left[h\left( \frac{{G_p}^\star}{G_n^\star}e^{ \sum_{j=1}^n a_j\int_0^{T}\rho_{i,j}\sigma_i(s)\sigma_j(s)\diff s} - \kappa^\star\right) \right]\,.\label{eqn:ESG}
\end{align}
From Equation \ref{eqn:EGpoverGn}, we find that the right hand side corresponds to a vanilla option price under the Black model with  forward $e^{-\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}+\bar{v}_i}$, strike $\kappa^\star$ and total variance $\nu^2(T)$.
\end{proof} 

\begin{identity}\label{identity:EGpG}
	\begin{equation}
		\mathbb{E}\left[B(0,T)  G_p^\star(T)  \frac{G_p^\star(T)}{G_n^\star(T)}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = e^{\nu^2(T)}\Black\left(e^{2\nu^2(T)}, \kappa^\star, \nu^2, T\right)\,.
	\end{equation}
\end{identity}
\begin{proof}
	Let $G^\star(T) = \frac{1}{\mathbb{E}\left[\frac{G_p^\star(T)}{G_n^\star(T)}\right]} \frac{G_p^\star(T)}{G_n^\star(T)}$,
we perform a change of measure $\frac{G^\star(T)}{G^\star(0)}$. Under this new measure $\mathbb{Q}^{G}$, $\tilde{W}_{G} (T)= W_{G}(T) - \int_0^T \gamma(s) \diff s $, with $\gamma^2(s)=\frac{\partial \nu^2(s)}{\partial s}$ is a Brownian motion. Then $\frac{G_p}{G_n}^\star(T)$ under $\mathbb{Q}^{G_p}$ has the same law as $\frac{G_p}{G_n}^\star(T) e^{\nu^2(T)}$ under $\mathbb{Q}$. Thus,
\begin{multline*}	\mathbb{E}\left[  G_p^\star(T) \frac{G_p^\star(T)}{G_n^\star(T)} h\left( \frac{G_p^\star(T)}{ G_n^\star(T)}- \kappa^\star\right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}\mathbb{E}^{G}\left[ G_p^\star(T) e^{\nu_p^2-\nu_{pn}^2(T)} h\left( \frac{{G_p}^\star}{G_n^\star}(T)e^{\nu^2(T)} - \kappa^\star\right) \right]\,.
\end{multline*}

%nup/2+nun/2+nu/2-nupn
Using Equation \ref{eqn:nu_decomp} and Identity \ref{identity:EGp} we find that the right hand side corresponds to a vanilla option price under the Black model with  forward $e^{2\nu^2(T)}$, strike $\kappa^\star$ and total variance $\nu^2(T)$.
\end{proof}


\begin{identity}\label{identity:ESiG}
	\begin{equation}
		\mathbb{E}\left[B(0,T)  S_i^\star(T)  \frac{G_p^\star(T)}{G_n^\star(T)}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = e^{\nu_n^2-\nu_{pn}^2+\bar{v}_i}\Black\left(e^{\nu^2+\nu_n^2-\nu_{pn}^2+\bar{v}_i(T)}, \kappa^\star, \nu^2, T\right)\,.
	\end{equation}
\end{identity}
\begin{proof}
	We start with a change of measure $\frac{G^\star(T)}{G^\star(0)}$: 
	\begin{multline*}
		\mathbb{E}\left[B(0,T)  S_i^\star(T)  \frac{G_p^\star(T)}{G_n^\star(T)}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}
		\mathbb{E}^G\left[B(0,T)  S_i^\star(T)e^{\bar{v}_i}  h\left( \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu^2 T}- \kappa^\star \right)\right]
	\end{multline*}
	We then apply the change of measure $\frac{S_{i}^{\star}(T)}{S_i^\star(0)}$:
	\begin{multline*}
		\mathbb{E}\left[B(0,T)  S_i^\star(T)  \frac{G_p^\star(T)}{G_n^\star(T)}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}+\bar{v}_i(T)}
		\mathbb{E}^{iG}\left[B(0,T)  h\left( \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu^2 T+\bar{v}_i}- \kappa^\star \right)\right]\,.
	\end{multline*}
	%-nup/2+nun/2+nu/2 = nun-nunp

	Using Equations \ref{eqn:nu_decomp} and \ref{eqn:EGpoverGn}, we find that the right hand side corresponds to a vanilla option price under the Black model with  forward $e^{\frac{-\nu_p^2+\nu_n^2+3\nu^2(T)}{2}+\bar{v}_i(T)}$, strike $\kappa^\star$ and total variance $\nu^2(T)$.
\end{proof}


\begin{identity}\label{identity:ESi2overGn}
	\begin{multline}
		\mathbb{E}\left[B(0,T)  \frac{S_i^\star(T)S_j^\star(T)}{G_n^\star(T)}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = \\ e^{\nu_n^2+{v}_{i,j}+\bar{v}_{i}^- + \bar{v}_{j}^-(T)}\Black\left(e^{\bar{v}_{i}+\bar{v}_j(T) -2\nu_{np}^2 +2\nu_n^2(T)} , \kappa^\star, \nu^2, T\right)\,.
	\end{multline}
	%-\frac{\nu_p^2(T)-\nu_n^2(T)-\nu^2(T)}{2}-\nu_{np}^2(T) +\nu_n^2 = -\nu_{np}^2(T) +\nu_n^2 
	with
	\begin{equation}
		\bar{v}_{i}^-(T) = \sum_{l=1}^{m_p-1} a_l\rho_{li} \int_0^T \sigma_i(s)\sigma_l(s)\diff s\,,\label{eqn:vin}
	\end{equation}	
	and $v_{i,j}$ defined in Equation \ref{eqn:vibar_vil}.
\end{identity}
\begin{proof}
We have $\mathbb{E}\left[\frac{1}{G_n^\star(T)}\right] = e^{\nu_n^2(T)}$. 
Let $G_n^{-1\star\star} =\frac{e^{-\nu_n^2(T)}}{G_n^\star(T)}$, it is a martingale of  unit expectation  under $\mathbb{Q}$ and may be thus expressed as \begin{equation*} G_n^{-1\star\star}(T)=e^{-\frac{1}{2}\int_0^T\gamma_n(s)^2\diff s + \int_0^T \gamma_n(s)  dW_{G_n^{-1}}(T)}\end{equation*} in probability, with $W_{G_n^{-1}}$ being a Brownian motion and $\gamma_n^2(s)=\frac{\partial \nu_n^2(s)}{\partial s}$. We interpret $\frac{G_n^{-1\star\star}(T)}{G_n^{-1\star\star}(0)}$ as a change of measure on $\mathcal{F}_T$. Under the new induced measure $\mathbb{Q}^{G_n^{-1}}$, $\tilde{W}_{G_n^{-1}} (T)= W_{G_n^{-1}}(T) - \int_0^T \gamma_n(s) \diff s $ is a Brownian motion. Then 
\begin{multline*}	
	\mathbb{E}\left[  \frac{S_i^\star(T)S_j^\star(T)}{G_n^\star(T)} h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] =\\ e^{\nu_n^2(T)}\mathbb{E}^{G_n^{-1}}\left[S_i^\star(T)S_j^\star(T)e^{\bar{v}_{i}^- + \bar{v}_{j}^-(T)} h\left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{-\nu_{np}^2(T) +\nu_n^2 (T)} - \kappa^\star\right) \right]\,.
\end{multline*}
We then apply the change of measure $\frac{S_{i}^{\star}(T)}{S_i^\star(0)}$:
\begin{multline*}	
	\mathbb{E}\left[  \frac{S_i^\star(T)S_j^\star(T)}{G_n^\star(T)} h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] =\\ e^{\nu_n^2(T)}\mathbb{E}^{iG_n^{-1}}\left[S_j^\star(T)e^{{v}_{i,j}+\bar{v}_{i}^- + \bar{v}_{j}^-(T)} h\left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{\bar{v}_{i}-\nu_{np}^2(T) +\nu_n^2 (T)} - \kappa^\star\right)\right]\,.
\end{multline*}
And finally a change of measure  $\frac{S_{j}^{\star}(T)}{S_j^\star(0)}$:
\begin{multline*}	
	\mathbb{E}\left[  \frac{S_i^\star(T)S_j^\star(T)}{G_n^\star(T)} h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] =\\ e^{\nu_n^2+{v}_{i,j}+\bar{v}_{i}^- + \bar{v}_{j}^-(T)}\mathbb{E}^{jiG_n^{-1}}\left[ h\left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{\bar{v}_{i}+\bar{v}_j-\nu_{np}^2(T) +\nu_n^2 (T)} - \kappa^\star\right) \right]\,.
\end{multline*}
Using Equations \ref{eqn:nu_decomp} and \ref{eqn:EGpoverGn}, we find that the right hand side corresponds to a vanilla option price under the Black model with  forward $e^{\bar{v}_{i}+\bar{v}_j(T) -2\nu_{np}^2 +2\nu_n^2(T)}$. 
\end{proof}


\begin{identity}\label{identity:EGpG2}
	\begin{equation}
		\mathbb{E}\left[B(0,T)  G_p^\star(T)  \left(\frac{G_p^\star(T)}{G_n^\star(T)}\right)^2 h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = e^{3\nu^2(T)}\Black\left(e^{3\nu^2(T)}, \kappa^\star, \nu^2, T\right)\,.
	\end{equation}
\end{identity}
\begin{proof}
	We start with the change of measure $\frac{G^\star(T)}{G^\star(0)}$
	\begin{multline*}
		\mathbb{E}\left[B(0,T)  G_p^\star(T)  \left(\frac{G_p^\star(T)}{G_n^\star(T)}\right)^2 h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}\mathbb{E}\left[B(0,T)  G_p^\star(T)  \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu_p^2-\nu_{pn}^2+\nu^2(T)}  h\left( \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu^2(T)} - \kappa^\star \right)\right]\,.
	\end{multline*}
	We then apply Identity \ref{identity:EGpG} with the additional overall multiplicative factor \begin{equation*}e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}e^{\nu_p^2-\nu_{pn}^2+\nu^2(T)} =e^{2\nu^2(T)}\,,\end{equation*}%nup/2 +nun/2 +nu/2 -nupn + nu = 2nu
	and forward multiplier $e^{\nu^2(T)}$.
\end{proof}



\begin{identity}\label{identity:ESiG2}
	\begin{multline}
		\mathbb{E}\left[B(0,T)  S_i^\star(T)  \left(\frac{G_p^\star(T)}{G_n^\star(T)}\right)^2 h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{\nu^2+2\nu_n^2-2\nu_{pn}^2+2\bar{v}_i}\Black\left(e^{2\nu^2+\nu_n^2-\nu_{pn}^2+\bar{v}_i(T)}, \kappa^\star, \nu^2, T\right)\,.
	\end{multline}
\end{identity}
\begin{proof}
	We start with a change of measure $\frac{G^\star(T)}{G^\star(0)}$: 
	\begin{multline*}
		\mathbb{E}\left[B(0,T)  S_i^\star(T)  \left(\frac{G_p^\star(T)}{G_n^\star(T)}\right)^2 h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}
		\mathbb{E}^G\left[B(0,T)  S_i^\star(T)\frac{G_p^\star(T)}{G_n^\star(T)} e^{\bar{v}_i+\nu^2(T)}  h\left( \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu^2 T}- \kappa^\star \right)\right]
	\end{multline*}
	We then apply Identity \ref{identity:ESiG} with global multiplier 
	\begin{equation*}
		e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}} e^{\bar{v}_i+\nu^2(T)}
	\end{equation*}
	and forward multiplier $e^{\nu^2 T}$.
\end{proof}


\begin{identity}\label{identity:ESi2GoverGn}
	\begin{multline}
		\mathbb{E}\left[B(0,T) \frac{S_{i}^{\star}S_{j}^{\star}G_p^\star(T)}{{G_n^\star}^2}		h\left( \frac{G_p^\star(T)}{G_n^\star(T)}-\kappa^\star \right)\right] = \\ e^{3\nu_n^2-2\nu_{pn}^2+\bar{v}_i+\bar{v}_j+{v}_{i,j}+\bar{v}_{i}^- + \bar{v}_{j}^-(T)}\Black\left(e^{\bar{v}_{i}+\bar{v}_j(T) +\nu^2 -2\nu_{pn}^2 +2\nu_n^2(T)} , \kappa^\star, \nu^2, T\right)\,.
	\end{multline}
\end{identity}
\begin{proof}
	We start with a change of measure $\frac{G^\star(T)}{G^\star(0)}$: 
	\begin{multline*}
		\mathbb{E}\left[B(0,T)  \frac{S_{i}^{\star}S_{j}^{\star}G_p^\star(T)}{{G_n^\star}^2}	h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] =\\ e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}}
		\mathbb{E}^G\left[B(0,T) \frac{S_i^\star(T)S_{j}^{\star}}{G_n^\star(T)} e^{\bar{v}_i+\bar{v}_j+\nu_n^2(T)-\nu_{pn}^2}  h\left( \frac{G_p^\star(T)}{G_n^\star(T)}e^{\nu^2 T}- \kappa^\star \right)\right]
	\end{multline*}
	We then apply Identity \ref{identity:ESi2overGn} with global multiplier 
	\begin{equation*}
		e^{-\frac{\nu_p^2-\nu_n^2-\nu^2(T)}{2}} e^{\bar{v}_i+\bar{v}_j+\nu_n^2(T)-\nu_{pn}^2}
	\end{equation*}
	and forward multiplier $e^{\nu^2 T}$.
\end{proof}

\begin{identity}\label{identiy:SiSjSkoverGn2}
	\begin{multline}
		\mathbb{E}\left[B(0,T)  	\frac{S_{i}^{\star}S_{j}^{\star}S_{k}^{\star}(T)}{{G_n^\star}^2}h\left( \frac{G_p^\star(T)}{G_n^\star(T)}- \kappa^\star \right)\right] = \\ e^{{v}_{i,j}+{v}_{k,i}+{v}_{k,j}+2\bar{v}_{i}^- + 2\bar{v}_{j}^- +2\bar{v}_{k}^- + 3\nu_n^2(T)}\Black\left(e^{\bar{v}_{i}+\bar{v}_j+\bar{v}_{k} -3\nu_{np}^2 +3\nu_n^2(T)} , \kappa^\star, \nu^2, T\right)\,.
	\end{multline}
\end{identity}
\begin{proof}
We start with a change of measure $\frac{G_n^{-1\star\star}(T)}{G_n^{-1\star\star}(0)}$:
\begin{multline*}	
	\mathbb{E}\left[  \frac{S_i^\star(T)S_j^\star(T)S_{k}^{\star}(T)}{{G_n^\star(T)}^2} h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] =\\ e^{\nu_n^2(T)}\mathbb{E}^{G_n^{-1}}\left[ \frac{S_i^\star(T)S_j^\star(T)S_{k}^{\star}(T)}{{G_n^\star(T)}}e^{\bar{v}_{i}^- + \bar{v}_{j}^- + \bar{v}_{k}^-(T)+\nu_n^2 (T)} h\left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{-\nu_{np}^2(T) +\nu_n^2 (T)} - \kappa^\star\right) \right]\,.
\end{multline*}
We then perform a change of measure $\frac{S_k^\star(T)}{S_k^\star(0)}$:
\begin{multline*}	
	\mathbb{E}\left[   \frac{S_i^\star(T)S_j^\star(T)S_{k}^{\star}(T)}{{G_n^\star(T)}^2} h\left( \frac{{G_p}^\star(T)}{{G_n}^\star(T)}- \kappa^\star \right) \right] =\\ e^{\nu_n^2(T)}\mathbb{E}^{kG_n^{-1}}\left[ \frac{S_i^\star S_j^\star(T)}{{G_n^\star(T)}}e^{{v}_{k,i}+{v}_{k,j}+\bar{v}_{i}^- + \bar{v}_{j}^- +2\bar{v}_{k}^- +\nu_n^2 (T)} h\left( \frac{{G_p}^\star(T)}{G_n^\star(T)} e^{\bar{v}_{k}-\nu_{np}^2(T) +\nu_n^2 (T)} - \kappa^\star\right)\right]\,.
\end{multline*}
And we apply Identity \ref{identity:ESi2overGn}  with global multiplier 
\begin{equation*}
	e^{{v}_{k,i}+{v}_{k,j}+\bar{v}_{i}^- + \bar{v}_{j}^- +2\bar{v}_{k}^- + 2\nu_n^2(T)}
\end{equation*}
and forward multiplier $e^{\bar{v}_{k}-\nu_{np}^2(T) +\nu_n^2 (T)}$.

\end{proof}

\section{Derivatives of the Black-76 formula towards the strike}\label{sec:appendix_black_der}
The following formulae are used to compute the expansions in practice:
\begin{align}
	\frac{\partial}{\partial K} \Black(F, K, v, T) &= -\eta B(0,T)  \Phi(\eta d_2)\,,\\
	\frac{\partial^2}{\partial K^2} \Black(F, K, v, T) &= \frac{B(0,T)}{K\sqrt{v}}  \phi(d_2)\,,\\
	\frac{\partial^3}{\partial K^3} \Black(F, K, v, T) &= \frac{ B(0,T)}{K^2\sqrt{v}}  \left( \frac{\phi( d_2)}{\sqrt{v}}-1\right)\,,
\end{align}
where $\Phi$, $\phi$ are the cumulative normal distribution function and the normal probability density function. 

