\subsection{Construction of the group $\mathscr{A}$}
\label{SU Construction of the group A}   

Let us use the tools above to construct the group $\mathscr{A}$ to use it in the proofs in the coming sections. 
%%
In the free group $\langle b,c \rangle$ of rank $2$ we denoted  $b_i = b^{c^i}\!\!$,\; see Section~\ref{SU Defining subgroups by integer sequences}.
For a fixed integer
$m$ define two isomorphisms
$\xi_m$ and $\xi'_m$ by the rules:
$\xi_m(b)=b_{-m+1},\;
\xi'_m(b)=b_{-m}$,\;
$\xi_m(c)=\xi'_m(c)=c^2$
of $\langle b,c \rangle$, and using them set the HNN-extension: 
\begin{equation}
\label{EQ Ksi two defined}
\Xi_m = \langle b,c \rangle *_{\xi_m, \xi'_m} (t_m, t'_m).
\end{equation}
See Figure~7 of 
\cite{Auxiliary free constructions for explicit embeddings} illustrating the construction of the group $\Xi_m$.  
We have proved the following technical lemmas in \cite{Auxiliary free constructions for explicit embeddings}:
%%%%%%
\begin{Lemma}
\label{LE Ksi}
In the above notation the following equalities hold for any $m$ in $\Xi_m$:
\begin{equation}
\label{EQ Ksi two equality}
\begin{split}
\langle b,c \rangle \cap \langle b_m, t_m, t'_m\rangle &= \langle b_m, b_{m+1},\ldots\rangle,
\\
\langle b,c \rangle \cap \langle b_{m-1}, t_m, t'_m\rangle &= \langle b_{m-1}, b_{m-2},\ldots\rangle.
\end{split}
\end{equation}
\end{Lemma}

\begin{Lemma}
\label{LE Ksi for G}
In the above notation the following equalities hold for any $m$ in $\langle a \rangle * \,\Xi_m$:
\begin{equation}
\label{EQ a simple example of bening subgroup}
\begin{split}
F \cap \langle b_m, t_m, t'_m\rangle = \langle b_m, b_{m+1},\ldots\rangle
\;\;\; {\it and} \;\;\;  
F \cap \langle a, b_m, t_m, t'_m\rangle = \langle a, b_m, b_{m+1},\ldots\rangle,
\hskip3mm \\
%
F \! \cap \!\langle b_{m-1}, t_m, t'_m\rangle  \! =  \! \langle b_{m-1}, b_{m-2},\ldots\rangle
\;\; {\it and} \;\;\,  
F \! \cap \! \langle a, b_{m-1}, t_m, t'_m\rangle \!  =  \! \langle a, b_{m-1}, b_{m-2},\ldots\rangle.
\end{split}
\end{equation}
\end{Lemma}

These lemmas provide us with infinitely generated benign subgroups of four types inside the free groups $\langle b,c \rangle$ and $F=\langle a,b,c \rangle$. In particular, 
$\langle b_1, b_2,\ldots \rangle$ is benign in $F$ for the finitely presented overgroup $\langle a \rangle * \Xi_1$, and for its finitely generated subgroup $\langle b_1, t_1, t'_1\rangle$.
%
Also the subgroup $\langle a, b_{0}, b_{-1},\ldots\rangle$ is benign in $F$ for the same finitely presented $\langle a \rangle * \Xi_1$ and for its finitely ge\-nerated subgroup $\langle a, b_{0}, t_1, t'_1\rangle$.


\begin{figure}[h]
\includegraphics[width=390px]{Figure_09_C.pdf}
\caption{Construction of the group  $\mathscr{C}$.}
% 
\label{FI Figure_09_C}
\end{figure}


Use these groups to build the 
$\bigast$-construction:
\begin{equation}
\label{EQ Defining C}
\mathscr{C} 
= \Big( \big(\langle a \rangle\! * \Xi_1\big) *_{\langle b_1, t_1, t'_1 \rangle} u_1 \Big)
\,*_{\langle a \rangle *\, \Xi_1}
\Big(\big(\langle a \rangle\! * \Xi_1\big) *_{\langle a, b_{0}, t_1, t'_1 \rangle} u_2 \Big)
\end{equation}
which is finitely presented, and which can explicitly be given by generators and defining relations via:
\begin{equation}
\label{EQ C by generators and defining relations}
\begin{split}
\mathscr{C} & = \big\langle a, b, c, t_1, t'_1, u_1, u_2 \mathrel{\;|\;}  
b^{t_1}= b,\;
b^{t'_1}= b^{c^{-1}}\!\!\!\!,\;\;
c^{t_1}=c^{t'_1}=c^2; \\
& \hskip37mm 
\text{$u_1$ fixes $b^c, t_1, t'_1$};\;\;\;
\text{$u_2$ fixes $a, b, t_1, t'_1$}
\big\rangle
\end{split}
\end{equation}
where ``fixes'' means ``fixes under conjugation'', e.g., $t_1^{u_1}=t_1$.





By Corollary~\ref{CO intersection and join are benign multi-dimensional}\;\eqref{PO 2 CO intersection and join are benign multi-dimensional} the join $J$ of $\langle b_1, b_2,\ldots  \rangle$ and $\langle a, b_{0}, b_{-1},\ldots\rangle$ is benign in $F$ for the finitely presented overgroup $K_J=\mathscr{C}$ and for its finitely generated subgroup
$L_J=\langle F^{u_1}, F^{u_2} \rangle$.






Further, in $F$ the subgroups 
$\langle b_1, b_2,\ldots  \rangle$ and $\langle a, b_{0}, b_{-1},\ldots\rangle$
clearly generate their \textit{free} pro\-duct.
Hence, by Corollary~\ref{CO smaller free product to the larger free product} the groups  $F^{u_1}$ and $F^{u_2}$ also generate their free product $F^{u_1} *\, F^{u_2}$ in $\mathscr{C}$, as well as in its subgroup: 
$$
F*_{F \,\cap\, \langle b_1, t_1, t'_1 \rangle, 
\;\;\; 
F\,\cap\,\langle a, b_{0}, t_1, t'_1 \rangle} 
(u_1,u_2)
\;=\;
F*_{\langle b_1, b_2,\ldots  \rangle, \;\; \langle a, b_{0}, b_{-1},\ldots\rangle} (u_1,u_2),
$$ 
see Lemma~\ref{LE intersection in bigger group multi-dimensional} and Lemma~\ref{LE Ksi for G}. Then \textit{arbitrary} two isomorphisms defined on $F^{u_1}$ and on $F^{u_2}$ can be continued to an isomorphism on the whole subgroup  $F^{u_1}* F^{u_2}$ inside $\mathscr{C}$.
%
Choose the trivial automorphism in $F^{\,u_1}$ and the conjugation by $b^{u_2}$ in $F^{\,u_2}$\!,\; and denote their common continuation in $F^{u_1}* F^{u_2}$ via $\omega$.
Inside $F$ this $\omega$ leaves the elements $ b_1, b_2,\ldots $ intact, but it sends $a, b_{0}, b_{-1},\ldots$ to their conjugates $a^b\!,\, b_{0}^b,\, b_{-1}^b,\ldots$

\begin{figure}[h]
\includegraphics[width=390px]{Figure_10_A.pdf}
\caption{Construction of the group  $\mathscr{A}$.}
% 
\label{FI Figure_10_A}
\end{figure}

Next, denote by $\delta$ the isomorphism of $F$ sending $a, b, c$ to $a, b^c, c$. Now we can define one of the key technical groups of this article as the HNN-extension:
$$
\mathscr{A} = \mathscr{C} \! *_{\omega, \delta}\!(d,e)
$$
which is finitely presented because  $\mathscr{C}$ is finitely presented, while $\omega$ is determined by its values on just six conjugates $a^{u_1}, b^{u_1}, c^{u_1}, a^{u_2}, b^{u_2}, c^{u_2}$, and 
$\delta$ is determined by its values on just three generators $a, b, c$.\,
%
This group can explicitly be written as:
\begin{equation}
\label{EQ relations A}
\begin{split}
\mathscr{A} 
& \!=\! 
\big\langle a, b, c, t_1, t'_1, u_1, u_2, d,e \mathrel{\;|\;}  
b^{t_1}\!=\! b,\;
b^{t'_1}\!=\! b^{c^{-1}}\!\!\!\!,\;
c^{t_1}\!=\!c^{t'_1}\!=\!c^2; \\[-2pt]
& \hskip17mm 
\text{$u_1$ fixes $b^c\!, t_1, t'_1$};\;\;\;\;
\text{$u_2$ fixes $a, b, t_1, t'_1$}; \\[-2pt]
& \hskip17mm  
\text{$d$ fixes 
$a^{u_1}$\!,\, 
$b^{u_1}$\!,\, 
$c^{u_1}$};  \\[-2pt]
& \hskip17mm \text{$d$ sends $a^{u_2}\!\!,\; b^{u_2}\!\!,\; c^{u_2}$ to $a^{b u_2}\!,\; b^{u_2}\!,\; c^{b u_2}$};\\[-2pt]
& \hskip17mm 
\text{$e$\; sends $a,b,c$ \;to\; $a,b^c\!,\; c$}
\big\rangle,
\end{split}
\end{equation}
with ``$d$ sends $a^{u_2}$ to $a^{b u_2}$''
simply meaning 
$a^{u_2 d}=a^{b u_2}$.
%
For later purposes denote the set of generators of $\mathscr{A}$ by 
\begin{equation}
\label{EQ generators of XA}
X_{\! \mathscr{A}}=\big\{
a, b, c, t_1, t'_1, u_1, u_2, d,e
\big\}.
\end{equation}
Denoting the set of defining relations of $\mathscr{A}$ from \eqref{EQ relations A} by 
$R_{\! \mathscr{A}}$ we have
$\mathscr{A}=\langle
\,X_{\! \mathscr{A}}
\;|\;
R_{\! \mathscr{A}}
\rangle$, i.e., 
$\mathscr{A}$ is given by $9$ generators and $1+1+2+3+4+3+3+3=20$ relations.







