\subsubsection{Presenting $R$ as a join}
\label{SU Presenting as a join} 

Let us present $R$ as a join of $m+1$ subgroups in $\Gamma$, each benign in  $\mathscr{G}$.  
%
Denote $\Phi_m=\langle b_0,\ldots,b_{m-1}, g, h_0,\ldots,h_{m-1} \rangle$, and notice that:

\begin{Lemma}
\label{LE new free subgroup}
$\Phi_m$ is freely generated by  $2m\!+\!1$ elements $b_0,\ldots,b_{m-1}, g, h_0,\ldots,h_{m-1}$\! in $\Gamma$, and hence in $\mathscr{G}$.
\end{Lemma} 

\begin{proof}  

Firstly, $\tilde B_{m}=\langle b_0,\ldots, b_{m-1}\rangle$ has trivial intersection with $P_m$ because $\langle b,c\rangle
\cap\,
P_m\! =B_m$ implies  
$\tilde B_{m} \cap\,
P_m 
\le \big(\tilde B_{m} \cap\langle b,c\rangle\big) \cap
P_m 
=\tilde B_{m} \cap\, \big(\langle b,c\rangle \cap P_m\big)
=\tilde B_{m} \cap\,B_{m}
= \1$.
%
Therefore, in $\mathscr{G}$ we 
by Corollary~3.5\;(1) 
and by Remark~3.6 
in \cite{Auxiliary free constructions for explicit embeddings} have:
$$
\langle b_0,\ldots,b_{m-1},\; g,h,k\rangle
=\tilde B_{m} *_{\tilde B_{m}   \,\cap\;   P_m} (g,h,k) = \tilde B_{m} *_{{\1}} (g,h,k)
=\tilde B_{m} * \langle g,h,k \rangle
$$
%      
which simply is a free group of (rank $m+3$).
Since $h_0,\ldots,h_{m\,-1}$ generate a free subgroup (of rank $m$) inside $\langle g,h,k \rangle$, they together with $g$ and with $b_0,\ldots,b_{m\,-1}$ generate a free subgroup (of rank $m+1+m=2m+1$)
inside $\langle b_0,\ldots,b_{m\,-1},\; g,h,k\rangle
\le \Gamma
\le \mathscr{G}
$.
\end{proof}   

Next we need a series of auxiliary benign subgroups in $\mathscr{G}$. Namely, for an integer $s=1,\ldots,m$ and for a sequence $f=(j_0, \ldots, j_{s-2}, j_{s-1})\in \mathcal E_s$ following the notation in \ref{SU Integer functions f} write $f^+=(j_0, \ldots, j_{s-2},\, j_{s-1}\!+\!1)$.
%
In this notation for any $f$ the group $\mathscr{G}$ contains the elements 
$g_{f^+}^{\vphantom{1}} \!
\cdot 
b_{s-1}^{-1} 
\cdot 
g_f^{-1}$, such as, 
$g^{h_0^{2} h_1^{5} h_2^{3} h_3^{\boldsymbol{8}} }
\cdot
b_{3}^{-1} 
\cdot
g^{-\,h_0^{2} h_1^{5} h_2^{3} h_3^{7} }
$  
for the tuple $f\!=\!(2,5,3,7)$ of the length $s=4$.
%
Denote:
\begin{equation*}
\label{EQ Ksi 0 and m}
\begin{split}
V_{\mathcal E_s} &= \Big\langle 
g_{f^+}^{\vphantom{1}} \!
\cdot 
b_{s-1}^{-1} 
\cdot 
g_f^{-1} \mathrel{|} f\in \mathcal E_s
\Big\rangle
\\
&= \Big\langle 
g^{h_0^{i_0} \cdots\, h_{s-2}^{i_{s-2}}h_{s-1}^{(i_{s-1}\boldsymbol{+1})}} 
\!
\cdot 
b_{s-1}^{-1} 
\cdot 
g^{-h_0^{i_0} \cdots\, h_{s-2}^{i_{s-2}}h_{s-1}^{i_{s-1}}} \mathrel{|} i_{0}\ldots,i_{s-2},i_{s-1} \in \Z
\Big\rangle.
\end{split}
\end{equation*}


\begin{Lemma}
\label{LE VEm is bening}
In the above notation each
$V_{\mathcal E_s}$, $s=1,\ldots,m$, is a benign subgroup in $\mathscr{G}$ for some explicitly given finitely presented group and its finitely generated subgroup.
\end{Lemma}

\begin{proof}  
By Lemma~\ref{LE new free subgroup} 
the elements $b_{s-1}, g, h_0,\ldots, h_{s-1}$
are \textit{free} generators for the $(s+2)$-generator subgroup
$\langle b_{s-1}, g, h_0,\ldots, h_{s-1} \rangle$
of $\Phi_m$. Thus, any of the following maps $\lambda_{i,\,j}$ can be continued to an isomorphism on the free group $\langle b_{s-1}, g, h_0,\ldots, h_{s-1} \rangle$:
%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{EQ lambda definitions}
\begin{aligned}
& \lambda_{s-1,\,0} 
& \!\!\!\!{\rm sends} \hskip3mm
& b_{s-1}, g, h_0,\ldots, h_{s-2}, h_{s-1}
& {\rm to} \hskip3mm 
& b_{s-1}, g^{h_0}, h_0,\ldots, h_{s-2}, h_{s-1};\\
%%%
