\left(h_0^{h_{2}}\right)^{2}
\left(h_1^{h_{2}}\right)^{5}
h_2^{3}\, h_3^{7} } \\
%%%%%%
& =  g^{h_2 \cdot\, h_2^{-1}  h_0^2 h_2 
h_2^{-1} h_1^5 h_2
h_2^{3} h_3^{\boldsymbol{8}} }
\cdot
b_{3}^{-1} 
\cdot
g^{-\,h_2 \cdot\, h_2^{-1}  h_0^2 h_2 
h_2^{-1} h_1^5 h_2
h_2^{3} h_3^{7} }\\
%%%%%%
& = g^{h_0^{2} h_1^{5} h_2^{\boldsymbol{4}} h_3^{\boldsymbol{8}} }
\cdot
b_{3}^{-1} 
\cdot
g^{-\,h_0^{2} h_1^{5} h_2^{\boldsymbol{4}} h_3^{7} }
=g_{f'^{\;+}}^{\vphantom{1}} \!
\cdot 
b_{3}^{-1} 
