\section{Whitehead groups and conjugacy classes}
\label{s:Whitehead}

From now on, we focus attention on Whitehead groups of finite groups. 


When $K$ is a field of characteristic $0$ and $n>0$ is an integer, we let 
$\mu_n$ be the group of $n$-th roots of unity in an algebraic closure of 
$K$, and regard the Galois group $\Gal(K(\mu_n)/K)$ as a subgroup of 
$(\Z/n)^\times$. Thus each automorphism $\gamma\in\Gal(K(\mu_n)/K)$ is 
identified with the unique class $a{+}n\Z\in(\Z/n)^\times$ such 
that $\gamma(\zeta)=\zeta^a$ for $\zeta\in\mu_n$. For example, 
	\[ \Gal(\Q(\mu_n)/\Q) =(\Z/n)^\times, \quad 
	\Gal(\R(\mu_n)/\R) =\{\4{\pm1}\} ~\textup{if $n\ge3$,}
	\quad\textup{and}\quad \Gal(\C(\mu_n)/\C)=1. \]


\begin{Defi}\label{d:K-A-conj}
Let $K$ be a field of characteristic $0$. When $G$ is a finite group, two 
elements $g,h\in G$ of the same order $n$ are \emph{$K$-$G$-conjugate} if 
$g$ is $G$-conjugate to $h^a$ for some $a+n\Z\in\Gal(K(\mu_n)/K)$. More 
generally, when $A\le\Aut(G)$ is a subgroup containing $\Inn(G)$, the elements 
$g,h\in G$ of order $n$ are \emph{$K$-$A$-conjugate} if $g$ is in the 
$A$-orbit of $h^a$ for some $a+n\Z\in\Gal(K(\mu_n)/K)$.
\end{Defi}

Thus $g,h\in G$ are $\R$-$A$-conjugate if $g$ is in the $A$-orbit of $h$ or 
$h^{-1}$, while they are $\Q$-$A$-conjugate if the cyclic subgroups 
$\gen{g}$ and $\gen{h}$ are in the same $A$-orbit. In particular, the 
number of $\Q$-$G$-conjugacy classes is equal to the number of conjugacy 
classes of cyclic subgroups of $G$.

As usual, by the \emph{rank} of a finitely generated abelian group $B$, we 
mean the rank of its free part; i.e., the order of its largest 
$\Z$-linearly independent subset. Thus $\rk(B)=\dim(\Q\otimes_{\Z}B)$. 

For a field $K$ of characteristic $0$ and a finite group $G$, we let 
$\Irr_K(G)$ be the set of isomorphism classes of irreducible $KG$-modules, 
regarded as a finite $\Aut(G)$-set. Via character theory, one shows the 
following:

\begin{Prop}\label{p:K-A-conj}
Let $K$ be a field of characteristic $0$. For each finite group $G$, and 
each group of automorphisms $A\le\Aut(G)$ containing $\Inn(G)$, 
	\[ |\Irr_K(G)/A| = \# \bigl\{\textup{$K$-$A$-conjugacy classes of 
	elements of $G$}\bigr\}. \]
\end{Prop}

\begin{proof} Let $R_K(G)$ be the representation ring for 
$KG$-representations: thus a free abelian group with basis $\Irr_K(G)$. Let 
$\Cl_K(G)$ be the space of all maps $G\too K$ that are constant on 
$K$-$G$-conjugacy classes, regarded as a vector space over $K$.
By~\cite[\S12.4, Corollary 2]{Serre(1977)}, the characters of the elements in 
$\Irr_K(G)$ form a $K$-basis for $\Cl_K(G)$. Hence the sums of the characters in 
each $A$-orbit form a basis for $\Fix(A,\Cl_K(G))$, and so 
	\beq |\Irr_K(G)/A| = \dim_K(\Fix(A,\Cl_K(G))) 
	= \# \bigl\{\textup{$K$-$A$-conjugacy classes of elements of 
	$G$}\bigr\}. \qedhere \eeq
\end{proof}


We refer to \cite[Section I.2a]{Oliver(1988)} for the definition of 
reduced norms for finite dimensional semisimple $\Q$-algebras.

\begin{Prop}\label{p:R/A}
Let $G$ be a finite group. Set $K=Z(\Q G)$, a product of fields, and let 
$R\le K$ be its unique maximal order (the product of the rings of integers in 
the factors). The reduced norm induces a homomorphism
	\[ \nr\: K_1(\Z G) \Right4{} R^\times \]
that commutes with the actions of $\Out(G)$ on $K_1(\Z G)$ and on 
$R^\times$, and whose kernel and cokernel are both finite. In particular, 
for each $A\le\Aut(G)$ containing $\Inn(G)$, 
	\[ \rk(\Z\otimes_{\Z A}\Wh(G)) = \rk(\Fix(A,\Wh(G))) 
	= \rk(\Fix(A,K_1(\Z G))) = \rk(\Fix(A,R^\times)). \]
\end{Prop}

\begin{proof} The fact that the reduced norm induces a homomorphism whose 
kernel and cokernel are finite was shown by Swan (see, e.g., 
\cite[Chapter 8]{Swan(1970)} or \cite[Theorem I.2.5(ii)]{Oliver(1988)}). 

Clearly, $\nr$ commutes with the actions of $A$. So 
$\Fix(A,K_1(\Z G))$ and $\Fix(A,R^\times)$ have the same rank.
\end{proof}

We also need Dirichlet's units theorem in the following form.

\begin{Lem}\label{l:Dirichlet}
Let $K\supseteq\Q$ be a finite extension, and let $R\subseteq K$ be the 
ring of integers. Then 
	\[ \rk(R^\times) = \#\bigl\{\textup{field factors in 
	$\R\otimes_{\Q}K$}\bigr\} 
	- 1. \]
\end{Lem}

\begin{proof} The ring $\R\otimes_{\Q}K$ is isomorphic to a product of one 
copy of $\R$ for each embedding of $K$ into $\R$, and one copy of $\C$ for 
each pair of conjugate embeddings of $K$ into $\C$ with image not in $\R$. 
So the statement follows from Dirichlet's theorem in its usual formulation 
(see \cite[Theorem B.6]{Stewart}). 
\end{proof}

\begin{Prop}\label{p:Wh-Irr(G)}
Let $G$ be a finite group. Then for each $A\le\Aut(G)$ containing $\Inn(G)$, 
we have 
	\[ \rk(\Z\otimes_{\Z A}\Wh(G)) = \rk(\Fix(A,\Wh(G))) = 
	|\Irr_{\R}(G)/A| - |\Irr_{\Q}(G)/A|. \]
\end{Prop}

\begin{proof} Set $K=Z(\Q G)$, a product of fields, and let $R\le K$ be its 
unique maximal order (the product of the rings of integers in the factors). 
Then $\rk(\Fix(A,\Wh(G)))=\rk(\Fix(A,R^\times))$ by Proposition~\ref{p:R/A}, 
and it remains to describe the rank of $\Fix(A,R^\times)$ in terms of 
representations of $G$. 

Set $K_0=\Fix(A,K)$ and $R_0=\Fix(A,R)$: the subgroups of elements fixed by 
$A$. By Wedderburn's theorem, there is a natural bijection of $A$-sets from 
$\Irr_{\R}(G)$ to the set of simple factors in $\R G$, and hence to the set 
of field factors in $Z(\R G)\cong\R\otimes_{\Q}K$. Also, by Galois theory, 
if a subgroup $A_0\le A$ sends a field factor to itself, then the set of 
elements in that field fixed by $A_0$ is a subfield. Thus the number of 
field factors in $\R\otimes_{\Q}K_0=\Fix(A,\R\otimes_{\Q}K)$ is equal to 
$|\Irr_{\R}(G)/A|$. 

Clearly, $R_0$ contains the product of the rings of integers in the field 
factors of $K_0$, with equality since for each field factor $L$ of $K_0$, 
the image of $R_0$ under projection to $L$ is a finitely generated subring 
and hence contained in the ring of integers (see, e.g., \cite[Lemma 
2.8]{Stewart}). So 
by Lemma~\ref{l:Dirichlet}, 
	\begin{align*} 
	\rk(\Fix(A,R^\times)) = \rk((R_0)^\times) &= \#\bigl\{\textup{field 
	factors in $\R\otimes_{\Q}K_0$}\bigr\} - |\Irr_{\Q}(G)/A| \\
	&= |\Irr_{\R}(G)/A| - |\Irr_{\Q}(G)/A|. \qedhere
	\end{align*}
\end{proof}

\begin{Thm}\label{t:rk(Wh^A)}
For each finite group $G$, and each subgroup $A\le\Aut(G)$ containing 
$\Inn(G)$, 
	\begin{multline*} 
	\dim_{\Q}\bigl((\Q\otimes_{\Z A}\Wh(G))\bigr) = 
	\#\bigl\{ \textup{$\R$-$A$-conjugacy classes of elements in $G$} 
	\bigr\} \\
	- \# \bigl\{ \textup{$\Q$-$A$-conjugacy classes of elements in $G$} 
	\bigr\}. 
	\end{multline*}
\end{Thm}

\begin{proof} When $A=\Inn(G)$, this is a theorem of Bass \cite[Theorem 
5]{Bass(1966)}. For arbitrary $A\le\Aut(G)$ containing $\Inn(G)$, it 
follows from Propositions~\ref{p:Wh-Irr(G)} and~\ref{p:K-A-conj}. 
\end{proof}



