\section{Examples}
\label{s:examples}

%%\newcommand{\NN}{\textit{\textbf{N}}}
\newcommand{\NN}{{\scrn}}

Throughout this section, it will be convenient to define, for each finite 
group $G$,
	\[ \NN_G = 
	\#\bigl\{\textup{$\R$-$\Aut(G)$-conjugacy classes in $G$}\bigr\} - 
	\#\bigl\{\textup{$\Q$-$\Aut(G)$-conjugacy classes in $G$}\bigr\} . 
	\]
Thus by Theorem \ref{t:rk(Wh^A)}, 
	\[ \NN_G = \rk(\Z\otimes_{\Z\Aut(G)}\Wh(G)) = 
	\dim_{\Q}(\Q\otimes_{\Z\Aut(G)}\Wh(G)). \]
So by Corollary 
\ref{cor:consequence_of_the:Wh(H)_to_Wh(G)_H_normal_finite}%
\eqref{cor:consequence_of_the:Wh(H)_to_Wh(G)_H_normal_finite:aut}, if $\NN_G>0$, 
then $\Q\otimes_{\Z}\Wh(\Gamma)\ne0$ for every group $\Gamma$ that contains $G$ 
as a normal subgroup. 

We now construct a wide variety of examples of finite groups $G$ with 
$\NN_G>0$, including some small metacyclic groups, metacyclic $p$-groups, 
and simple groups. For example, we show that the smallest group with 
$\NN_G>0$ is the nonabelian group of order $55$, and that $\NN_G>0$ when 
$G$ is the nonabelian group of order $p^3$ and exponent $p^2$ and $p\ge5$ 
is prime. We also determine exactly which of the sporadic simple groups, 
and which of the linear groups $\PSL_n(q)$, satisfy $\NN_G>0$.

We first need some tools for constructing automorphisms.

\begin{Lem}\label{l:abel.n}
\begin{enuma} 

\item Let $H\nsg G$ be a pair of finite groups such that $H$ is abelian and 
$G/H$ is cyclic. Then for each $x\in G$ such that $G=H\gen{x}$, and each 
$a\in\Z$ prime to $|G|$ such that $a\equiv1$ (mod $|G/H|$), there is 
$\alpha\in\Aut(G)$ such that $\alpha(h)=h^a$ for each $h\in H\cup\{x\}$. 

\item Let $G$ be a group, let $Z\le Z(G)$ be a central subgroup, and let 
$\psi\in\Hom(G,Z)$ be a homomorphism such that $Z\le\Ker(\psi)$. Then there 
is $\alpha\in\Aut(G)$ such that $\alpha(g)=g\psi(g)$ for each $g\in G$.

\end{enuma}
\end{Lem}

\begin{proof} \textbf{(a) } Define $\alpha\:G\too G$ by setting, 
for each $h\in H$ and each $i\in\Z$, $\alpha(hx^i)=h^ax^{ai}$. By 
assumption, every element in $G$ can be written in this form. If 
$hx^i=kx^j$ for $h,k\in H$ and $i,j\in\Z$, then $k^{-1}h=x^{j-i}$, so 
$k^{-a}h^a=(k^{-1}h)^a=x^{aj-ai}$, and hence $h^ax^{ai}=k^ax^{aj}$. So 
$\alpha$ is well defined as a map of sets. Finally, if $h,k\in H$ and 
$i,j\in\Z$ are arbitrary, then 
	\begin{align*} 
	\alpha((hx^i)(kx^j)) &= \alpha(h(x^ikx^{-i})x^{i+j}) = 
	h^a(x^ik^ax^{-i})x^{ai+aj} = h^a(x^{ai}k^ax^{-ai})x^{ai+aj} \\ 
	&= (h^ax^{ai})(k^ax^{aj}) = \alpha(hx^i)\alpha(kx^j), 
	\end{align*}
where the third equality holds since $x^{(a-1)i}\in H$ and hence commutes 
with $k^a$. So $\alpha$ is an automorphism.

\noindent\textbf{(b) } One easily checks that $\alpha$ is a homomorphism 
with inverse $(g\mapsto g\psi(g)^{-1})$.
\end{proof}

As a first, very simple, application of Lemma \ref{l:abel.n}(a), we have:

\begin{Ex}\label{ex:abel.n}
If a finite group $G$ contains a normal abelian subgroup of index at most 
$3$, then $\NN_G=0$.
\end{Ex}

\begin{proof} Assume $H\nsg G$ is abelian of index at most $3$. Fix $g\in 
G$; then either $g\in H$ or $G=H\gen{g}$. By Lemma \ref{l:abel.n}(a), for each 
$a\in\Z$ such that $\gcd(a,|G|)=1$, and such that $a\equiv1$ (mod $3$) if 
$|G/H|=3$, there is $\alpha\in\Aut(G)$ such that $\alpha(g)=g^a$. Thus 
all generators of $\gen{g}$ are $\R$-$\Aut(G)$-conjugate to $g$. Since 
$g\in G$ was arbitrary, Theorem~\ref{t:rk(Wh^A)} now implies
	\beq \NN_G = \#\bigl\{\textup{$\R$-$\Aut(G)$-conjugacy classes} 
	\bigr\} - 
	\#\bigl\{\textup{$\Q$-$\Aut(G)$-conjugacy classes} \bigr\} = 0. 
	\qedhere \eeq
\end{proof}

With a little more work, one can show that if $G$ is a finite group with 
$\NN_G=0$, then $\NN_{G\times H}=0$ for each finite group $H$ that contains 
an abelian subgroup of index at most $2$. However, if we let $G\cong 
C_5\rtimes C_4$ (induced by an injection $C_4\too\Aut(C_5)$), and let $H$ 
be a nonabelian group of order $21$, then $\NN_G=\NN_H=0$, but 
$\NN_{G\times H}>0$.

We next look at some more small groups $G$ for which $\NN_G$ vanishes.

\iffalse
Example \ref{ex:abel.n} is the key to showing that the smallest group $G$ 
for which $\NN_G>0$ has order $55$. 
\fi

\begin{Ex} \label{ex:|G|<55}
If $G$ is a group of order at most $54$, then $\NN_G=0$.
\end{Ex}

\begin{proof} If each element of $G$ has order dividing $4$ or $6$, then 
all generators of each cyclic subgroup of $G$ are $\R$-$G$-conjugate, so 
$\NN_G=0$. If $G$ is abelian, or contains a 
normal abelian subgroup of index $2$ or $3$, then $\NN_G=0$ by Example 
\ref{ex:abel.n}. From now on, we use these without repeating the 
references each time. 

When $q=p^k$ for a prime $p$ and $k\ge1$, we let $E_q$ denote an elementary 
abelian $p$-group of order $q$ and rank $k$. When $P$ is a $p$-group for a 
prime $p$, we let $\Phi(P)$ denote its Frattini subgroup: the intersection 
of the maximal proper subgroups of $P$, and the smallest normal subgroup 
such that $P/\Phi(P)$ is elementary abelian.

\noindent\boldd{Case 1: $|G|=n$ where $n\le53$ is odd.} If $n$ is prime or the 
square of a prime, or $n=35$ or $45$, then $G$ is abelian, so $\NN_G=0$. 
Otherwise, $n=3m$ where $m>3$ is prime or $m=9$, so $G$ contains a normal 
abelian subgroup of index $3$, and $\NN_G=0$. 

\noindent\boldd{Case 2: $|G|=2n$ where $n\le27$ is odd.} In these cases, 
$G$ always contains a normal subgroup $H\nsg G$ of order $n$ and index $2$. 
If $H$ is abelian, then $\NN_G=0$. If $H$ is nonabelian, then $n=21$ or 
$27$.

If $n=21$ and $H$ is nonabelian, then $G$ is a semidirect product of the 
form $C_{14}\rtimes C_3$ or $C_7\rtimes C_6$. In the first case, $\NN_G=0$. 
In the second case, all elements of $G$ have order $7$ or a divisor of $6$, 
and the elements of order $7$ are permuted transitively by $\Aut(G)$ by 
Lemma \ref{l:abel.n}(a). So $\NN_G=0$ also in this case.

This leaves the case where $|H|=n=27$ and $H$ is nonabelian. If $H$ has exponent 
$3$, then the order of each element of $G$ divides $6$, and so $\NN_G=0$. 
So assume $H$ is nonabelian of exponent $9$. There are three subgroups of 
order $9$ in $H$, at least one of which must be invariant under the 
conjugation action of $G/H\cong C_2$. So there is a normal subgroup $K\nsg 
G$ with $K\cong C_9$. If $C_G(K)>K$, then $G$ has a normal abelian subgroup 
of index $3$, and so $\NN_G=0$. Otherwise, $G/K\cong C_6$ (since 
$\Aut(K)\cong C_6$), and $G$ is a semidirect product $K\rtimes C_6$ where 
$C_G(K)=K$. 

In this last case, $G$ has presentation 
$\gen{a,b\,|\,a^9=1=b^6,~bab^{-1}=a^2}$. So by Lemma \ref{l:abel.n}(a), 
there is $\alpha\in\Aut(G)$ such that $\alpha(a)=a^7$ and $\alpha(b)=b$. 
Then $\alpha$ induces the identity on $G/\gen{a^3}$, so for each cyclic 
subgroup $C\le G$ of order $9$, $\alpha(C)=C$ and hence all generators of 
$C$ are $\R$-$\Aut(G)$-conjugate. Since all other elements have order 
dividing $6$, this shows that $\NN_G=0$.

\noindent\boldd{Case 3: $|G|=4n$ where $n\le13$ is odd.} If $n=1$ or 
$n\equiv3$ (mod $4$), then $G$ contains an abelian subgroup of index $2$. 
If $n=5$ or $13$, then either $G$ has an abelian subgroup of index $2$, or 
$G\cong C_n\rtimes C_4$, and each element of $G$ has order $1$, $2$, $4$, 
or $n$. All elements in $G$ of order $n$ are $\R$-$\Aut(G)$-conjugate by 
Lemma \ref{l:abel.n}(a), so $\NN_G=0$. 

Assume $n=9$, so $|G|=36$. If there is $H\nsg G$ of order $9$, then 
either $G$ has an abelian subgroup of index $2$, or $H\cong E_9$, 
$C_G(H)=H$, and all elements of $G$ have order $1,2,3,4,6$. So $\NN_G=0$ in 
all such cases. Otherwise, $|\syl3G|=4$, the conjugation action on this set 
induces a homomorphism $\chi\:G\too\Sigma_4$ with image $A_4$, and so $G$ 
has a normal abelian subgroup of index $3$.

\iffalse
\noindent\boldd{Case 4: $|G|=8$ or $16$.} In all of these cases, $G$ 
contains an abelian subgroup of index $2$. So $\NN_G=0$. 
\fi

\noindent\boldd{Case 4: $|G|=8$, $16$, or $32$.} If $G/Z(G)$ has an element 
of order $8$, generated by the class of $g\in G$, then $Z(G)\gen{g}$ is 
abelian of index at most $2$ in $G$. Also, if $G$ has an element of order 
$16$, then it generates a cyclic subgroup of index at most $2$. So 
$\NN_G=0$ in all such cases. 

Assume from now on that $G/Z(G)$ has exponent at most $4$ and $G$ has 
exponent at most $8$. So if $g\in G$ has order $8$, then $g^4\in Z(G)$. If 
$g\notin\Phi(G)$, then by Lemma \ref{l:abel.n}(b), applied with 
$Z=\gen{g^4}$, there is $\alpha\in\Aut(G)$ such that $\alpha(g)=g^5$. So 
all generators of $\gen{g}$ are $\R$-$\Aut(G)$-conjugate in this case. 

If $g\in\Phi(G)$ has order $8$, then $\Phi(G)=\gen{g}$ and $G/\Phi(G)\cong 
C_2\times C_2$, which is impossible unless $G$ has a cyclic subgroup of 
index $2$.



\iffalse
If $G/Z(G)$ has a cyclic 
subgroup of index $2$, then $G$ has an abelian subgroup of index $2$. If 
$Z(G)$ and $G/Z(G)$ are both elementary abelian, then $G$ has exponent $4$. 
Thus $\NN_G=0$ in all such cases. 

In all remaining cases, $Z(G)$ is cyclic. If $\Phi(G)$ has exponent $8$, 
then $G$ would be an extension of $H\cong C_8$ by $C_2\times C_2$, in which 
case either $G$ has a cyclic subgroup of index $2$ or $H\nleq\Phi(G)$. Thus 
$\Phi(G)$ has exponent $4$. So if $g\in G$ has order $8$, then $g^4\in 
Z(G)$ and $g\notin\Phi(G)$. So by Lemma \ref{l:abel.n}(b), there is 
$\alpha\in\Aut(G)$ that is the identity modulo $\gen{g^4}$ and such that 
$\alpha(g)=g^5$, proving that all generators of $\gen{g}$ are 
$\R$-$\Aut(G)$-conjugate. Hence $\NN_G=0$.
\fi

\noindent\boldd{Case 5: $|G|=24$.} If $|\syl3G|=1$, then $G$ contains a 
normal abelian subgroup of index $2$, so $\NN_G=0$. Otherwise, 
$|\syl3G|=4$, and the conjugation action on this set defines a homomorphism 
$\chi\:G\too\Sigma_4$ whose image contains $A_4$. So either 
$G\cong\Sigma_4$, or $G/Z(G)\cong A_4$ and $|Z(G)|=2$, and in all such 
cases, all elements of $G$ have order dividing $4$ or $6$. So $\NN_G=0$.

\noindent\boldd{Case 6: $|G|=40$.} In all cases, $|\syl5G|=1$. Then either 
$G$ has an abelian subgroup of index $2$ (and $\NN_G=0$), or there is a 
normal subgroup $H\nsg G$ such that $H\cong C_{10}$, $G/H\cong C_4$, and 
$C_G(H)=H$. 

Assume we are in this last case. By Lemma \ref{l:abel.n}(a), the generators 
of $H$ are permuted transitively by $\Aut(G)$, and similarly 
for the elements of order $5$. All other elements have order dividing $8$. 
Let $x\in H$ be the element of order $2$, and let $\alpha\in\Aut(G)$ be the 
automorphism that is the identity on the subgroup of index $2$ that 
contains $H$, and sends $g$ to $gx$ otherwise. If $g\in G$ has order $8$, 
then $x=g^4$ and $\alpha(g)=gx=g^5$, so all generators of $\gen{g}$ are 
$\R$-$\Aut(G)$-conjugate. Thus $\NN_G=0$. 

\noindent\boldd{Case 7: $|G|=48$.} By the Sylow theorems, $|\syl3G|=1$, 
$4$, or $16$. 

\noindent\boldd{Case 7A: } If $|\syl3G|=16$, then the Sylow $2$-subgroup 
$S\le G$ is normal and contains all elements not of order $3$. So $S$ has 
an automorphism of order $3$ that fixes only the identity element, hence 
$[S,S]$ is trivial or noncyclic, which implies $S\cong E_{16}$ or 
$C_4\times C_4$. Thus all elements of $G$ have order at most $4$, 
and so $\NN_G=0$.

\noindent\boldd{Case 7B: } Assume $|\syl3G|=4$, and let 
$\chi\:G\too\Sigma_4$ be the homomorphism defined by the conjugation 
action. If $\chi$ is onto, then $\Ker(\chi)=Z(G)=\gen{x}$ where $|x|=2$, so 
by Lemma \ref{l:abel.n}(b), there is $\alpha\in\Aut(G)$ such that 
$\alpha|_{\chi^{-1}(A_4)}=\Id$ and $\alpha(g)=gx$ for $g\in G$ with 
$\chi(g)\notin A_4$. So if $g\in G$ has order $8$, then $g^4=x$ and 
$\alpha(g)=gx=g^5$. Thus all generators of each cyclic subgroup of order 
$8$ are $\R$-$\Aut(G)$-conjugate. Since all elements of $G$ have order 
dividing $6$ or $8$, this proves that $\NN_G=0$. 

If $\chi(G)=A_4$, then either $\Ker(\chi)\cong E_4$, or 
$\Ker(\chi)=Z(G)\cong C_4$ and $G\cong C_4\times A_4$ or $C_4\circ\SL_2(3)$ 
(central product). In all such cases, all elements of $G$ have order 
dividing $4$ or $6$, so $\NN_G=0$.

\noindent\boldd{Case 7C: } Now assume $|\syl3G|=1$, let $H\nsg G$ be the 
normal subgroup of order $3$, and choose $S\in\syl2G$. Then $C_G(H)=HT$ for 
some $T\le S$ of index at most $2$, and $\NN_G=0$ if $T$ is abelian. So 
assume $S\cong G/H$ is nonabelian of order $16$, with a nonabelian 
subgroup $T\le S$ of index at most $2$. 

If $T=S$, then $G\cong H\times S$. If $S/Z(S)$ has a cyclic subgroup of 
index $2$, then $S$ has an abelian subgroup of index $2$. Otherwise, 
$|Z(S)|=2$ and $S/Z(S)\cong E_8$, in which case some pair of commuting 
elements in $S/Z(S)$ lift to commuting elements in $S$. So in all cases, 
$S$, and hence $G$, have abelian subgroups of index $2$, and so $\NN_G=0$.


Assume for the rest of the proof that $T$ has index $2$ in $S$. Since $G$ 
is a semidirect product $G=H\rtimes S$, each $\alpha\in\Aut(S)$ with 
$\alpha(T)=T$ extends to $\5\alpha\in\Aut(G)$ such that 
$\5\alpha|_H=\Id_H$. Also, there is $\beta\in\Aut(G)$ such that 
$\beta|_S=\Id_S$ and $\beta(h)=h^{-1}$ for $h\in H$.

If $S$ has an element $g$ of order $8$, then since $T$ is nonabelian, we 
have $S=\gen{g,x}$ and $T=\gen{g^2,x}$ for some $x\in T\sminus\gen{g}$. By 
Lemma \ref{l:abel.n}(a), for each odd $a\in\Z$, there is 
$\alpha\in\Aut(S)$ that $\alpha(g)=g^a$ and $\alpha(x)=x^a$, so 
$\alpha(T)=T$, and hence $\alpha$ extends to $\5\alpha\in\Aut(G)$. Thus 
$N_{\Aut(G)}(\gen{g})$ permutes transitively the generators of $\gen{g}$. 

If $g\in G$ has order $12$, then $H=\gen{g^4}$ and $g^3\in T$. Thus 
$\beta(g^4)=g^{-4}$ and $\beta(g^3)=g^3$, so $\beta(g)=g^5$, proving that all 
generators of $\gen{g}$ are $\R$-$\Aut(G)$-conjugate. All elements of $G$ 
have order $12$, $8$, $6$, or at most $4$, so $\NN_G=0$ in all of these 
cases. 
\end{proof}

By Example \ref{ex:|G|<55}, the smallest example of a finite group $G$ such 
that $\NN_G>0$ has order at least $55$. We now prove that there is such a 
group. Let $\varphi$ denote the Euler function: 
$\varphi(n)=|(\Z/n)^\times|$.

\begin{Ex} \label{ex:pm}
Fix a prime $p$, and an integer $m\ge3$ such that $m|(p-1)$. Let $G$ be a 
semidirect product $G\cong C_p\rtimes C_m$, where $C_m$ acts faithfully on 
$C_p$. Then $\NN_G\ge(\varphi(m)/2)-1$, with equality if $m$ is prime. Thus 
$\NN_G>0$ if $m=5$ or $m\ge7$.
\end{Ex}

\begin{proof} Fix elements $a,b\in G$ with $|a|=p$ and $|b|=m$, and set 
$H=\gen{a}\nsg G$. Let $k\in\Z$ be such that $bab^{-1}=a^k$. For each 
$\alpha\in\Aut(G)$, $\alpha(a)=a^s$ for some $s$, and so 
$\alpha(b)\alpha(a)\alpha(b)^{-1}=\alpha(a)^s=b\alpha(a)b^{-1}$. Hence 
$\alpha(b)\in bH$. In other words, each automorphism of $G$ induces the 
identity on $G/H\cong C_m$. 

Thus the $\varphi(m)$ generators of $\gen{b}$ all lie in one 
$\Q$-$\Aut(G)$-conjugacy class, but in separate $\Aut(G)$-conjugacy 
classes. Since each $\R$-$\Aut(G)$-conjugacy class is the union of at most 
two $\Aut(G)$-conjugacy classes, there are at least $\varphi(m)/2$ 
$\R$-$\Aut(G)$-conjugacy classes in the $\Q$-$\Aut(G)$-conjugacy class of 
$b$. So $\NN_G\ge(\varphi(m)/2)-1$. 

If $m$ is prime, then every nonidentity 
element of $G$ has order $p$ or $m$ and hence is $\Q$-$G$-conjugate to $a$ 
or $b$. All generators of $\gen{a}$ are $\Aut(G)$-conjugate to $a$, and there 
are $\varphi(m)/2$ $\R$-$\Aut(G)$-conjugacy classes of generators 
of $\gen{b}$. So $\NN_G=(\varphi(m)/2)-1$ in this case.
\end{proof}

With a little more work, one can show that 
$\NN_G=\sum_{2<d|m}((\varphi(d)/2)-1)$ in the situation of Example 
\ref{ex:pm}. 

The next example also involves metacyclic groups, and shows that there are 
$p$-groups $G$ (for an arbitrary prime $p$) such that $\NN_G>0$. Note that 
the smallest examples constructed in this way have order $p^3$ when 
$p\ge5$, or order $3^6$ or $2^{10}$ when $p=3$ or $2$.


\begin{Ex} \label{ex:p-gp}
Fix integers $1<r|q$, and let $G$ be the group of order $qr^2$ with 
presentation
	\[ G = \gen{a,b \,|\, a^{qr}=1=b^r,~ bab^{-1}=a^{q+1} }. \]
Then $\NN_G>0$ if $\varphi(r)>4$, or if $\varphi(r)=4$ and $q$ is odd or 
$2r|q$. 
\end{Ex}

\begin{proof} Set $t=q+1$ for short. Note first that 
$t^s=(1+q)^s\equiv1+sq$ (mod $q^2$) for each $s\ge1$. In particular, 
$t^r\equiv1$ (mod $qr$), so the above presentation does define a group of 
order $qr^2$. 

Let $\alpha\in\Aut(G)$ be an automorphism that normalizes the cyclic 
subgroup $\gen{b}$. Thus 
	\[ \alpha(a)=a^ib^j \qquad\textup{and}\qquad \alpha(b)=b^k \]
for some $i,j,k\in\Z$. Then $\gcd(k,r)=1$ since $\alpha(b)$ has order $r$, 
and $\gcd(i,q)=1$ since $\gen{\alpha(a),\alpha(b)}=G$. Since 
$\alpha$ is a homomorphism, 
	\[ a^{it^k}b^j = b^k(a^ib^j)b^{-k} = 
	\alpha(b)\alpha(a)\alpha(b)^{-1} = \alpha(bab^{-1}) 
	= \alpha(a^t) = (a^ib^j)^t = a^{iN}b^{tj}, \]
where $N=1+t^j+t^{2j}+\cdots+t^{(t-1)j}$. Since $\gcd(i,q)=1$, 
this implies that $N\equiv t^k$ (mod $qr$). Hence 
	\[ t^k \equiv N \equiv 1 + (1+jq) + (1+2jq) + \dots + (1+(t-1)jq) 
	=t+jq^2t/2 \pmod{qr} \]
(recall $q=t-1$). 
So $t^k\equiv t$ (mod $qr$) if $q$ is odd or $2r|q$, and 
$t^k\equiv t$ (mod $qr/2$) otherwise. Since $t=1+q$ and $t^k\equiv1+kq$ 
(mod $qr$), we now get that $k\equiv1$ (mod $r$) if $q$ is odd or $2r|q$, 
and $k\equiv1$ (mod $r/2$) otherwise. 

Thus if $q$ is odd or $2r|q$, then the only generators of $\gen{b}$ that 
are $\R$-$\Aut(G)$-conjugate to $b$ are $b$ and $b^{-1}$, so $\NN_G>0$ if 
$\varphi(r)\ge4$. Otherwise, $r$ is even, the $\R$-$\Aut(G)$-conjugacy 
class of $b$ in $\gen{b}$ contains the four elements $b^{\pm1}$ and 
$b^{(r/2)\pm1}$, and $\NN_G>0$ if $\varphi(r)>4$.
\end{proof}

We finish by looking at a few examples of finite simple groups $G$ where 
$\NN_G>0$. These are larger groups in most cases, but working with them has 
the advantage that the automorphism groups of simple groups are well known, 
and their outer automorphism groups are in most cases quite small. Also, the 
properties of conjugacy classes of elements of $G$ needed to determine 
$\NN_G$ are in many cases listed in the Atlas \cite{Atlas(1985)}. 

We start with the easiest case. 

\begin{Ex}\label{ex:An}
If $G$ is an alternating or symmetric group, then $\NN_G=0$.
\end{Ex}

\begin{proof} If $G\cong A_n$ or $\Sigma_n$, then two generators of the 
same cyclic subgroup of $G$ are always conjugate in $\Sigma_n$, and hence 
in $\Aut(G)$. So $\Q$-$\Aut(G)$-conjugate elements are also 
$\Aut(G)$-conjugate, and hence $\NN_G=0$. 
\end{proof}

We next look at the 26 sporadic simple groups, where we observe that the 
largest groups are not necessarily the ones for which $\NN_G$ or 
$\rk(\Wh(G))$ are largest. For example, the Whitehead group of $F_1$ (the 
monster) is finite, while $\NN_G>0$ when $G\cong F_2$ (the baby monster) or 
the Janko group $J_1$ (one of the smallest sporadic groups).

\begin{Ex}\label{ex:spor}
Among the sporadic simple groups $G$, 
\begin{enuma} 

\item $\Wh(G)$ is finite, and hence $\NN_G=0$, when $G$ is one of the five 
Matthieu simple groups, one of Conway's simple groups $\Co_n$ for 
$n=1,2,3$, or one of the groups $\HS$, $\McL$, $F_3$, or $F_1$; 

\item $\rk(\Wh(G))>0$ but $\NN_G=0$ when $G\cong J_2$, $\Suz$, or $\Fi_{22}$; 
and 

\item $\NN_G>0$ when $G$ is one of the Janko groups $J_n$ for $n=1,3,4$, or 
$G\cong \He$, $\Ly$, $\Ru$, $\ON$, $\Fi_{23}$, $\Fi_{24}'$, $F_5$ or $F_2$. 

\end{enuma}
\end{Ex}

\begin{proof} From the character tables in~\cite{Atlas(1985)}, we see that 
every pair of $\Q$-$G$-conjugate elements is $\R$-$G$-conjugate, and hence 
$\Wh(G)$ is finite, whenever $G$ is one of the Matthieu groups, one of 
Conway's simple groups $\Co_n$ for $n=1,2,3$, or $\HS$, $\McL$, $F_3$ or 
$F_1$. Note that an entry ``\texttt{5A B*}'' at the top of the character table 
means that class \texttt{5B} is $\Q$-$G$-conjugate but not 
$\R$-$G$-conjugate to class $\texttt{5A}$, while ``\texttt{5A B**}'' means 
that the classes are $\R$-$G$-conjugate.

The computations of $\rk(\Wh(G))$ and $\NN_G$ in the other cases are 
described in Table~\ref{tbl:spor}. 
\end{proof}


