We finish by looking at the projective special linear groups.

\begin{Ex}\label{ex:Ln(q)}
Assume $G\cong\PSL_n(q)$, where $n\ge2$, $q$ is a prime power, and $G$ is 
simple. Then $\NN_G>0$, except when $G$ is one of the groups $\PSL_2(4)\cong 
\PSL_2(5)\cong A_5$, $\PSL_2(7)\cong \PSL_3(2)$, $\PSL_2(8)$, $\PSL_2(9)\cong A_6$, 
$\PSL_3(4)$, or $\PSL_4(2)\cong A_8$. 
\end{Ex}

\begin{proof} Choose an ordered $\F_q$-basis for $\F_{q^n}$, and let 
$\chi\:\F_{q^n}^\times\too\GL_n(q)$ be the injective homomorphism that 
sends an element $u\in\F_{q^n}^\times$ to the matrix for multiplication by 
$u$ on $\F_{q^n}$. Fix a generator $u_0\in\F_{q^n}^\times$, set 
$\til{x}=\chi(u_0^{q-1})\in\SL_n(q)$, and let $x\in G=\PSL_n(q)$ be its 
class modulo the center. Then $\til{x}$ has order $(q^n-1)/(q-1)$, and so 
$x$ has order 
	\[ M \defeq \frac{q^n-1}{(q-1)\cdot\gcd(q-1,n)}. \] 
Note that $\frac{q^n-1}{q-1}\equiv n$ (mod $q-1$), and hence 
$\gcd(q-1,n)=\gcd(q-1,\frac{q^n-1}{q-1})$. Also, $\Aut_G(\gen{x})\cong C_n$, 
generated by the Frobenius automorphism $(x\mapsto x^q)$. 

Assume $q=p^k$ where $p$ is prime and $k\ge1$. The 
automorphism group $\Aut(G)$ is generated by $\Inn(G)$, the field 
automorphism that sends $x$ to $x^p$, diagonal automorphisms induced by 
conjugation by $\chi(u_0)$ that send $x$ to itself, and if $n\ge3$, the 
graph automorphism ``transpose inverse'' that (up to inner automorphism) 
sends $x$ to $x^{-1}$ (see, e.g., \cite[\S\,3.3.4]{Wilson(2009)}). Thus 
$\Aut_{\Aut(G)}(\gen{x})$ is generated by the automorphisms $(x\mapsto 
x^p)$ of order $nk$ and (if $n\ge3$) $(x\mapsto x^{-1})$. It follows that
	\beqq 
	\left.\begin{array}{r} 
	\textup{$n=2$ and $\varphi(M)>2k$} \\[3pt]
	\textup{or $n\ge3$ and $\varphi(M)>2nk$}
	\end{array} \right\} 
	\implies \NN_G>0. \label{e:Lnq-1} \eeqq

\boldd{Assume $n=2$ and $p=2$.} Then $M=2^k+1$ is odd, and 
$\Aut_{\Aut(G)}(\gen{x})$ is cyclic of order $2k$, generated by the 
Frobenius automorphism $(x\mapsto x^2)$. If $M$ is divisible by two or more 
odd primes, then $\Aut(\gen{x})$ is not cyclic, and hence $\NN_G>0$. 
Otherwise, $\varphi(M)\ge\frac23\cdot M=\frac23(2^k+1)$, and so 
$\NN_G>0$ if $2^k+1>3k$. This holds whenever $k\ge4$, and so $\NN_G>0$ 
whenever $q=2^k\ge16$. 

\boldd{Assume $n=2$ and $p$ is odd.} Then $M=(q+1)/2$, and again, 
$\Aut_{\Aut(G)}(\gen{x})$ is cyclic of order $2k$. If $M$ is divisible by 
two or more odd primes, then $\NN_G>0$ since $\Aut(\gen{x})$ is not cyclic. 
Otherwise, $\varphi(M)\ge\frac12\cdot\frac23\cdot M=(q+1)/6$, and so by 
\eqref{e:Lnq-1}, $\NN_G>0$ if $q+1>12k$. This holds for $q\ge13$ when 
$k=1$, for $q=p^2\ge25$ when $k=2$, for $q=p^3\ge5^3$ when $k=3$, and for 
all odd primes $p$ when $k\ge4$. Thus by \eqref{e:Lnq-1}, $\NN_G>0$ 
whenever $q\ge13$ and $q\ne27$. 

\boldd{Assume $n\ge3$.} In these cases, $\Aut_{\Aut(G)}(\gen{x})$ is the 
product of cyclic groups of order $nk$ and $2$. If $M$ is 
divisible by three or more odd primes, then $\Aut(\gen{x})$ has $2$-rank at 
least $3$, hence is not equal to $\Aut_{\Aut(G)}(\gen{x})$, and so 
$\NN_G>0$. If $M$ is divisible by at most two odd primes, then 
$\varphi(M)\ge\frac12\cdot\frac23\cdot\frac45\cdot M=\frac4{15}M$. So by 
\eqref{e:Lnq-1}, $\NN_G>0$ if $2kn<\frac4{15}M$, and since 
$M\ge\frac1n\cdot\frac{q^n-1}{q-1}>\frac1nq^{n-1}$, we have 
	\beqq  q^{n-1} = p^{k(n-1)} 
	\ge \tfrac{15}2\cdot kn^2 
	\quad\implies\quad \NN_G>0.\label{e:Lnq-2} \eeqq

By straightforward computation, the inequality in \eqref{e:Lnq-2} holds 
whenever $(p,k,n)$ is equal to one of the triples 
\begin{small} \def\8{\hskip3mm}
	\[ (11,1,3) \8(5,2,3) \8(3,3,3) \8(2,5,3) \8(5,1,4) \8
	(3,2,4) \8(2,3,4) \8 (2,2,6) \8(3,1,7) \8(2,1,11) \]
\end{small}%
Also, if this inequality holds for a given triple $(p_0,k_0,n_0)$ (with 
$n_0\ge3$), then it holds for $(p,k,n)$ (and hence $\NN_G>0$) whenever 
$p\ge p_0$, $k\ge k_0$, and $n\ge n_0$. Among the pairs $(p^k,n)$ with 
$n\ge3$ for which \eqref{e:Lnq-2} does not hold, the inequality in 
\eqref{e:Lnq-1} holds (so $\NN_G>0$) in the following cases:
\[ \renewcommand{\arraystretch}{1.2}
\begin{array}{c|cccccccccccccccc}
q & 3 & 5 & 7 & 8 & 9 & 16 & 4 & 2 & 3 & 4 & 2 & 3 & 2 & 2 & 2 & 2 \\
n & 3 & 3 & 3 & 3 & 3 & 3 & 4 & 5 & 5 & 5 & 6 & 6 & 7 & 8 & 9 & 10 \\\hline
M & 13 & 31 & 19 & 73 & 91 & 91 & 85 & 31 & 121 & 341 & 63 & 182 & 127 & 255 & 511 
& 1023 \\
\varphi(M) & 12 & 30 & 18 & 72 & 72 & 72 & 64 & 30 & 110 & 300 & 36 & 72 & 126 & 
128 & 432 & 600 \\
2kn & 6 & 6 & 6 & 18 & 12 & 24 & 16 & 10 & 10 & 20 & 12 & 12 & 14 & 16 & 18 & 20
\end{array} \]

\boldd{Remaining cases (all $n$).} We are left with the groups $\PSL_2(q)$ for 
$q\le11$ or $q=27$, $\PSL_3(q)$ for $q=2,4$, and $\PSL_4(q)$ for $q=2,3$. 
The groups $\PSL_2(4)\cong \PSL_2(5)\cong A_5$, $\PSL_2(9)\cong A_6$, and 
$\PSL_4(2)\cong A_8$ were handled in Example~\ref{ex:An}. Also, 
$\PSL_3(2)\cong \PSL_2(7)$, so it remains to look at $\PSL_2(7)$, 
$\PSL_2(8)$, $\PSL_2(11)$, $\PSL_2(27)$, $\PSL_3(4)$, and $\PSL_4(3)$. In 
each of these cases, the result follows with the help of the character 
tables in~\cite{Atlas(1985)}.

For example, when $G=\PSL_2(11)$, the classes $5A$ and $5B$ are not 
$\R$-$\Aut(G)$-conjugate, so $\NN_G>0$. When $G=\PSL_2(27)$, there are six 
conjugacy classes of elements of order $13$ (all of them 
$\Q$-$G$-conjugate), permuted in two orbits by 
field automorphisms of order $3$, hence forming two 
$\R$-$\Aut(G)$-conjugacy classes. When $G=\PSL_4(3)$, the subgroups of 
order $13$ have automizers in $\Aut(G)$ of order $6$, so their generators 
form two $\R$-$\Aut(G)$-conjugacy classes. Thus $\NN_G>0$ in the last two 
cases. When $G=\PSL_2(7)$, $\PSL_2(8)$, or $\PSL_3(4)$, each 
$\Q$-$\Aut(G)$-conjugacy class is permuted transitively by $\Aut(G)$, and 
so $\NN_G=0$. 
\end{proof}


