 \begin{lem} \label{lem:derivsk} On $ \H$ we have the following   identities:
 \begin{align}
 (s^\pm_2)'&= \frac{2E_4^{-1/2}(E_4^{3/2}\pm E_6)}
   {\big(E_2\pm E_4^{1/2}\big)^2}, \label{eq:ders2}\\
 s_4'&=-\frac{5(E_4^3-E_6^2)}{(E_2E_4-E_6)^2}, 
 \label{eq:ders4}\\
 s_6'&=\frac{7 E_4(E_4^3-E_6^2)}{(E_2E_6-E_4^2)^2}.
 \label{eq:ders6}
\end{align}
  \end{lem}
The derivatives here are with respect to the variable $\tau\in \H$.   
  \begin{proof}
These formulas can be obtained  by straightforward computations based on  Pro\-po\-sition~\ref{Ederi}.  
Indeed, by \eqref{eq:Ds2dem} we have
\begin{align*}
  Ds^+_2&=\frac{i}{2\pi}\cdot \frac{-(E_2+E_4^{1/2})^2+E_2^2- E_4+2 E_2E_4^{1/2}- 2E_6E_4^{-1/2}}{\big(E_2+E_4^{1/2}\big)^2}\\
  &=-\frac{i}{\pi} \cdot \frac{E_4^{-1/2}(E_6+E_4^{3/2})}
   {\big(E_2+E_4^{1/2}\big)^2}.
  \end{align*}
This gives the identity for $(s_2^+)'$. We obtain the one  for $(s_2^-)'$ by changing the sign of the root $E_4^{1/2}$. 

By  \eqref{E4der} and  \eqref{eq:Ds4dem} we have
\begin{align*}
Ds_4&=\frac{i}{2\pi} \cdot \frac{-5(E_2E_4-E_6)^2+5 E_4
(E_2^2E_4+E_4^2-2E_2E_6)} {(E_2E_4-E_6)^2}\\
&=\frac{5i}{2\pi} \cdot \frac{E_4^3-E_6^2}{(E_2E_4-E_6)^2}. 
  \end{align*}
The identity for $s_4'$ follows.    

By \eqref{E6der} and    \eqref{eq:Ds6dem} we have
  \begin{align*}
  Ds_6
  &=\frac{i}{2\pi}\cdot \frac{-7(E_2E_6-E_4^2)^2+
   7(E_2^2E^2_6-2E_2E_4^2E_6+E_4E^2_6)}{(E_4^2-E_2E_6)^2}\\
  &=-\frac{7i}{2\pi}  \cdot \frac{E_4(E_4^3-E_6^2)}
   {(E_4^2-E_2E_6)^2}.  \end{align*}
 The identity for $s_6'$ follows.  
  \end{proof}

  If $f$ is a function that is meromorphic near a point $z_0\in \C$, then we call
  $z_0$ a {\em critical point of $f$} if $f(z_0)\in \C$ (and so $f$ is actually a holomorphic function near  $z_0$) and $f'(z_0)=0$. 

  \begin{prop} \label{prop:critpts}  \begin{enumerate}[label=\normalfont{(\roman*)}]

 \item\label{i:pols2}   The functions $s_2^\pm$  have  
   no critical points in $\H\setminus \Ga(\rho)$.

   \smallskip 
    \item\label{i:pols4} The function $s_4$ has no critical points in $\H$.     
     \smallskip 
    \item\label{i:pols6}
    The set of  critical  points of  $s_6$ in $\H$  is equal to $\Ga(\rho)$. Each of these critical points is simple.  
   \end{enumerate}
   \end{prop}

 \begin{proof} \ref{i:pols2}  Since 
 \[(E_4^{3/2}+E_6)(E_4^{3/2}-E_6)=E_4^3-E_6^2=1728\Delta,
 \] the numerator in the expression 
 \eqref{eq:ders2} never vanishes at any point $\tau\in \H\setminus\Ga(\rho)$. This implies that neither $s_2^+$ and $s_2^-$ can have a critical point in 
$ \H\setminus\Ga(\rho)$.

 \smallskip
  \ref{i:pols4} In expression \eqref{eq:ders4} the numerator never vanishes and so $s_4$ has no critical points. 

\smallskip
  \ref{i:pols6} In  \eqref{eq:ders6} the numerator vanishes precisely at the points in  the set
 $\Gamma(\rho)$. Note that at these points
$E_2E_6-E_4^2=E_2E_6\ne 0$ by Lemma~\ref{lem:czeros}~\ref{i:E46} and
 \ref{i:E2}, and so
the denominator  in  \eqref{eq:ders6} is non-zero. 
We also have $DE_4=\tfrac13 (E_2E_4-E_6)=-\tfrac13 E_6\ne 0$ at these points. This shows that  the set of critical points of  $s_6$ is given by 
$\Ga(\rho)$ and that each of these critical points is simple. 
 \end{proof}

 \begin{cor}\label{cor:locinj}
 \begin{enumerate}[label=\normalfont{(\roman*)}]

 \item\label{i:loc2}   The functions  $s_2^\pm$  are locally 
   injective near every point in  $\H\setminus \Ga(\rho)$.

   \smallskip 
    \item\label{i:loc4} The function $s_4$ is locally injective near every point in $\H$.     
     \smallskip 
    \item\label{i:loc6} The function $s_6$ is locally injective near every point in   $\H\setminus \Ga(\rho)$   
 \end{enumerate}
 \end{cor}

 \begin{proof} These statements immediately follow from Propositions~\ref{prop:simpol} and~\ref{prop:critpts}.
 \end{proof}

 \section{Auxiliary results about conformal maps}\label{sec:auxconf}
 In this section, we collect various results about conformal maps.  
 We will need the following version of the Argument Principle. 



\begin{prop}\label{prop:arg}
Suppose $U\sub \bC$ is a closed Jordan region and $f\:\inte(U)\ra \C$ is a holomorphic function  that has a continuous extension (as a map into $\bC$) to the boundary $\partial U\sub \bC$. Suppose this extension maps $\partial U$ homeomorphically to the boundary $\partial V\sub \bC$ of a closed Jordan region $V\sub \bC$ with $ \inte(V)\sub \C$. 

If $\infty\in \partial V$ we make the following additional assumptions:
\begin{itemize} 

 \item[\textnormal{(i)}] if $z_0\in \partial U$ is the unique point with $f(z_0)=\infty$, then $f$ is locally injective on $U$ near $z_0$.

 \smallskip 
\item[\textnormal{(ii)}]  if the Jordan curve $\partial U$ is oriented so that $U$ lies on the left of $\partial U$ and if $\partial V$ carries the orientation induced by $f$, then $V$ lies on the left of $\partial V$.


\end{itemize}
Under these hypotheses, $f$ is a homeomorphism of   $U$ onto $V$ that is a biholomorphism  between $\inte(U)$ and $\inte(V)$.
\end{prop}
In our application of this statement, $\infty$ will be on the boundary of $U$ and $V$. This proposition goes back to  \cite[Prop.\ 4.1]{BZeta}, but the statement there was  incorrect as condition (i) was missing in the formulation.

\begin{proof}  Suppose first that $\infty\not \in \partial V$ (and hence $\infty\not \in V$). Then  the Argument Principle implies that on $\inte(U)$ the function $f$ attains each value in $\inte(V)$ once and no other values (see \cite[pp.~310--311]{Bur}  and 
 \cite[Exercise 9.17 (i)] {Bur} for this type of argument). The statement easily follows in this  case.   

 If $\infty \in  \partial V$, then the additional assumptions allow us to reduce to the previous case. For this we consider  auxiliary 
 Jordan regions $U'\sub U$ whose boundaries $\partial U'$ are obtained by replacing a small arc $\alpha\sub \partial U$ that contains $z_0$ in its interior with a small arc $\alpha'$ that has  the same endpoints, but whose interior is contained in $\inte(U)$ and so avoids $z_0$.  With suitable choices, condition (i) implies that $f$ is a homeomorphism of $\partial U'$ onto its image and $\infty\not \in f(\partial U')$. By the first part of the proof, there exists a Jordan region $V'\sub \C$ with $\partial V'=f(\partial U')$ such that $f$ is a ho\-meomorphism from $U'$ onto $V'$.  By choosing the arcs $\alpha$ and $\alpha'$ smaller and smaller, we  conclude that $f$ is a homeomorphism of $U$ onto its image. Condition (ii) then implies 
 $f(U)=V$ and we see that the statement is also true when $\infty\in \partial V$.
 \end{proof} 


 \begin{lem} \label{lem:injinfty} Suppose a holomorphic function $f$ has a  representation as convergent series 
  \begin{equation}\label{eq:finj}
 f(\tau)=\tau+ \sum_{n=-1}^\infty a_n q^n
 \end{equation}
 for $\tau \in \H$ with  $\im(\tau)>c_0\ge 0$, where $a_n\in \C$ for $n\in \{-1\}\cup\N_0$. 

Then the following statements are true:

 \begin{enumerate}[label=\normalfont{(\roman*)}]

\smallskip
 \item\label{item:inj1} If  $a_{-1}=0$, then there exists 
 $c_1>c_0$ such that $f$ injective on 
 the half-plane  $H_1\coloneq \{ \tau\in \H: \im(\tau)\ge c_1\}$.


\smallskip 
    \item\label{item:inj2} Suppose   $a_{-1}\ne 0$. Let $\alpha, \beta\in \R$ with $\alpha<\beta$ and $\beta-\alpha<1$ be arbitrary.  Then there exists $c_2>c_0$ such that $f$ is injective on the closed 
   half-strip
  \[ H_2\coloneq \{ \tau\in \C: \im(\tau)\ge c_2, \ \alpha\le \re(\tau)\le \beta\}.
  \]
\end{enumerate}
 \end{lem}

 \begin{proof} \ref{item:inj1}  We have 
 \[
 f'(\tau)=1+O(q)
 \]
 for $\tau\in \H$ as $\im(\tau)\to+ \infty$. In particular, there exists
 $c_1>c_0$ such that $\re(f'(\tau))>0$ for $\im(\tau)\ge c_1$. Then if $\tau_1, \tau_2\in H_1$, where $H_1$ is  defined as in the statement, and $\tau_1\ne \tau_2$, we have
 \[
 \re \biggl(\frac{ f(\tau_2)-f( \tau_1)}{\tau_2-\tau_1}\biggr)
 =\int_0^1 \re(f'((1-t)\tau_1+t\tau_2))\, dt>0
 \]
 and so $f(\tau_2)\ne f( \tau_1)$. 


 \smallskip
\ref{item:inj2} The function 
\[
g(\tau)\coloneq \tau+ \sum_{n=0}^\infty a_n q^n
\]
defined for  $\tau \in \H$ with $\im(\tau)>c_0$  is holomorphic and 
\[ 
g'(\tau)=1+O(q)
\] 
as $\im(\tau)\to + \infty$. This implies that there exists $c_2'>c_0$ such that 
\[
|g(\tau_2)-g(\tau_1)|\le 2|\tau_2-\tau_1| 
\]
whenever $\tau_1, \tau_2\in \H$ with $\im(\tau_k)\ge c_2'$ for $k=1,2$. 

On the other hand, let $\ga\coloneq \beta-\alpha\in (0,1)$. Then the holomorphic function $z\mapsto k(z)\coloneq (1-\exp(2\pi i z))/z$  has a removable singularity at $z=0$ and has its only zeros in the set $\Z\setminus\{0\}$.
In particular, $k$ has no zeros in the set 
\[ U\coloneq  \{z\in \C: \im(z)\ge 0 \text{ and } -\ga\le \re(z)\le \ga\}.
\]
It easily follows that there exists a constant $\delta>0$ such that 
\begin{equation}\label{eq:expaux}
\frac {|1-\exp(2\pi i z)|}{|z|}\ge \frac {\delta}{1+\im(z)}
\end{equation}
for $z\in U$. 

Now let $\tau_1, \tau_2\in \H$ with $\alpha \le \re(\tau_1), \re(\tau_2)\le \beta$ and $\im(\tau_1),\,  \im(\tau_2)>c_0$ be arbitrary.  Without loss of generality, we may assume that 
$\im(\tau_2)\ge \im(\tau_1)$. Then $z_0\coloneq \tau_2-\tau_1\in U$ and so 
\begin{align*}
|\exp(-2\pi i\tau_2)- \exp(-2\pi i\tau_1)|&= \exp(2\pi \im(\tau_2))
|1- \exp(2\pi iz_0)|\\
\ge  \exp(2\pi \im(\tau_2))\frac {\delta |z_0|}{1+\im(z_0)}\\
\ge 
\delta \frac{\exp(2\pi \im(\tau_2))}{1+\im(\tau_2)}|\tau_2-\tau_1|.
\end{align*}
 This inequality shows that if  in addition $$\im(\tau_1),\,  \im(\tau_2)>c_2$$
 with $c_2\ge c_2'$ sufficiently large (independent of $\tau_1$ and $\tau_2$), then 
 for the function $\tau\mapsto h(\tau)\coloneq a_{-1}\exp(-2\pi i \tau)$ we have 
 \[
 |h(\tau_2)-h(\tau_1)|\ge 3|\tau_2-\tau_1|.
 \]
 Note that $f=g+h$. 
It follows that if  $\tau_1, \tau_2\in H_2$, where $H_2$ is  defined as in the statement, and $\tau_1\ne \tau_2$, then we have
\begin{align*}
|f(\tau_2)-f(\tau_1)|&\ge |h(\tau_2)-h(\tau_1)|-|g(\tau_2)-g(\tau_1)|\\
&\ge 3|\tau_2-\tau_1|-2 |\tau_2-\tau_1|=|\tau_2-\tau_1|>0,
\end{align*}
and so $f(\tau_2)\ne f(\tau_1)$. 
 \end{proof}

 \begin{lem} \label{lem:orient} Suppose $f$ is a holomorphic function near $0$
 with $f(0)=0$ and $f'(0)> 0$ and such that  $f(z)\in \R$ for $z\in \R$ near $0$. Then  $\im(f(z))>0$ for all $z\in \C$ near $0$ with $\im(z) >0$. 
 \end{lem}

 \begin{proof}  Note that for $n\in \N$ we have $|\sin n t|\le n|\sin t|$ for all 
 $t\in\R$.
 It follows that for  $z=re^{it}$ with $r\ge 0$ and $t\in \R$ we have 
  \[
 |\im (z^n)|=r^n |\sin(nt)|\le nr^n |\sin t| =n|z|^{n-1} |\im(z)|.
 \]

Now our assumptions imply that near $0$ the function $f$ has a power series representation of the form 
\[
f(z)=\sum_{n=1}^\infty a_nz^n
\]
with $a_1=f'(0)>0$ and $a_n\in \R$ for $n\in \N$, $n\ge 2$. 
It follows that for $z\in \C$ sufficiently close to $0$ with $\im(z)>0$ we have 
\begin{align*} \im(f(z))&=\sum_{n=1}^\infty a_n\im(z^n)\\
&\ge \im(z) \biggl( a_1-\sum_{n=2}^\infty n |a_n| |z|^{n-1}\biggr)\\
&\ge  \im(z) (a_1-c|z|), 
\end{align*}
 where $c>0$ is a suitable constant. 
 This shows that if $|z|$ is sufficiently small and $\im(z)>0$, then 
 \[
 \im(f(z))\ge \im(z) (a_1-c|z|)\ge  \im(z)(a_1/2)>0,
 \]
 as desired.
 \end{proof}
Another way to think about the statement in the previous lemma is as follows.  
Near $0$ the map $f$ is a conformal map. If we traverse a small 
 interval $I$ in $\R$ containing $0$ in its interior from left to right, then our assumptions imply that under the map $f$ the image point also traverses a small interval $J=f(I)$ in $\R$
 containing $0$ in its interior from left to  right. Now 
points
$z\in\C$ close to $0$ with $\im(z)>0$ lie on the left of the oriented interval $I$. Hence the image point must also lie on the left of the oriented interval $J$, that is, we must have $\im(f(z))>0$. 

This interpretation immediately leads to some generalizations of the previous
lemma that we will freely use in the following: for example, suppose 
$f$ is holomorphic near $i$ and $f'(i)>0$. Suppose $f$ 
sends the imaginary axis near $i$ into itself.   Then for points $\tau$ near $i$ with $\re(\tau)>0$ we have $\re(f(\tau))>0$.  Analytically, this and similar  
statements  can easily be reduced to Lemma~\ref{lem:orient} by using auxiliary maps in source and target space. 







  \begin{lem} \label{lem:minprincip} Suppose $V\sub \C$ is an open  region 
  and  $h\: V \ra \R$ is a non-constant harmonic function 
  such that 
  \begin{equation}
\liminf_{V \ni z \to z_0}h(z)\ge 0
\end{equation}
for all $z_0\in \partial V$. Then $h(z)>0$ for all $z\in V$.  
\end{lem}
Here the boundary  $\partial V$  includes $\infty\in \wC$ if $V$ is  unbounded (as in our applications of the lemma). 


\begin{proof} This is a standard fact, but we include a proof for the sake of completeness. 
Let $m_0\coloneq \inf_{z\in V} h(z)\in \{-\infty\}\cup\R$. Then we can 
find a sequence $\{z_n\}$ in $V$ such that $h(z_n)\to m_0$ as $n\to \infty$. Passing to a subsequence if necessary, we may assume that $z_n\to z_0$ as  $n\to \infty$,  where $z_0\in V\cup \partial V \sub \wC$.  

Here $z_0\in V$ is impossible, because then $h(z_0)=m_0$ by continuity of $h$. In particular, $h$ would attain its  minimum at   
$z_0$ which is not possible for a non-constant harmonic function. 
We are left with $z_0\in \partial V$. But then our assumptions imply that 
\[m_0=\lim_{n\to \infty} h(z_n)\ge \liminf_{V \ni z \to z_0}h(z)\ge 0.
\] This shows that $h(z)\ge m_0\ge 0$ for $z\in V$. Here we must actually have $h(z)>0$ for $z\in V$, because otherwise we could find a point $u_0\in V$ with $h(u_0)=0$. Then $h$ attains its minimum $0$ at $u_0$ and we obtain a contradiction as before. 
\end{proof}

Recall that an {\em arc}  $\alpha$ in $\wC$ is a set homeomorphic to the unit interval $[0,1]$. We denote by $\inte(\al)$ the {\em set of interior points  of 
$\alpha$}, that is, the points corresponding to points in  $(0,1)$ under a homeomorphism between $[0,1]$ and $\alpha$. 

 \begin{lem} \label{lem:circarc} Suppose 
  $\alpha$ is an arc on a circle $K\sub \wC$ with endpoints $a,b\in K$, and $f$ is a
   $\wC$-valued continuous map on $\alpha$  with the following 
  properties: 
 \begin{enumerate}[label=\normalfont{(\alph*)}]
\item\label{i:cir1} $f(\alpha)\sub K$, 

\smallskip
\item\label{i:cir2} $f$ has no fixed points in $\inte(\alpha)$, 

\smallskip
\item\label{i:cir3}  near each point 
$z_0\in \inte(\alpha)$ the function $f$ has a locally injective meromorphic extension. 
\end{enumerate}
Then the following statements are true:

\begin{enumerate}[label=\normalfont{(\roman*)}]
\item\label{i:ciri} 
If $f(a)\not\in \alpha$, then $f$ is a homeomorphism of $\alpha$ 
onto its image $f(\alpha)$. 

\smallskip
\item\label{i:cirii} Suppose $f(a)=a$, $f(b)=b$, and that for all 
  points 
$p\in \inte(\alpha)$ sufficiently close  to $a$ the point $f(p)$ lies in the interior of  the subarc of $\alpha$ with endpoints  $a$ and $p$. Then $f$ is a homeomorphism of $\alpha$ onto itself.  Moreover,  in this case 
$f(p)$ always lies in the interior of  the subarc of $\alpha$ with endpoints  $a$ and $p$
for $p\in \inte(\alpha)$. 
\end{enumerate}
\end{lem}

Here a circle in $\wC$ is either a Euclidean  circle in $\C$ or a line considered as a circle through the point $\infty$.

The local injectivity condition in \ref{i:cir3}  is equivalent to the 
requirement that for each point $z_0\in \inte(\alpha)$  we have $f'(z_0)\ne 0$ if $f(z_0)\in \C$ or that $z_0$ is only a simple pole if $f(z_0)=\infty$. Of course,  \ref{i:cir3} could be replaced with a weaker condition not referring to meromorphic  extensions, but the formulation in this form  will be convenient for us later on.  


\begin{proof} It is easiest to think of these statements in terms of moving points on $K$. The ensuing arguments can easily be made rigorous by reducing to  the circle $K=\R \cup\{\infty\}$ by  conjugating $f$ with a suitable M\"obius transformation  and then  invoking the Intermediate Value Theorem.  


We consider a point $p$ traveling from $a$ to $b$ along the arc  $\alpha$. Then our assumptions \ref{i:cir1} and  \ref{i:cir3} imply  the image point $f(p)$ starts from $f(a)$ and moves on $K$ in a monotonic way, either in the same or in the opposite direction as $p$. These moving points  can only  collide at the beginning or at the end of the movement, because $f$ has no fixed point  in   $\inte(\alpha)$. Now if $f(a)\not \in \alpha$, then  is clear that in both cases $f(p)$ can never cross over $b$ as this would lead to a forbidden collision.

 In particular,    $f(p)$ cannot wrap  around $K$ and will sweep out an arc on $K$ with endpoints $f(a)$ and $f(b)$. The first statement follows.

 For the second statement note that $f(p)$ has to move in the same direction  as  $p$ starting at $f(a)=a$, because otherwise   $f(p)$ would leave 
 the arc $\alpha$,  contradicting our assumptions on the image of points close to $a$. Moreover, 
   while $f(p)$ moves in the same direction as $p$ on $\alpha$, at least initially  $f(p)$  is trailing behind $p$. But $f(p)$ can never overtake $p$ as this would force a forbidden collision. 
 Since $f(b)=b$, it follows that $f(p)$ will sweep out the arc $\alpha$
 as $p$ travels from $a$ to $b$ along $\alpha$. Moreover,  
  $f(p)$ always lies in the interior of  the subarc of $\alpha$ with endpoints  $a$ and $p$
for all $p\in \inte(\alpha)$. 
\end{proof} 

  \section{Mapping behavior of  $s_4$}\label{sec:maps4}

 We now analyze the mapping behavior of the function of $s_4$ defined in \eqref{eq:s4def} in more detail. This  will lead to a proof of Theorem~\ref{thm:s4} and its corollaries.
 For the proof of Theorem~\ref{thm:s4} we want to apply 
Proposition~\ref{prop:arg} for $f=s_4$ and $U=T_0$ as defined in \eqref{T0}.
This will require some preparation. 

   Recall that $E_4(\rho)=0=E_6(i)$. Using \eqref{eq:E2spec} we see that 
\[ s_4(\rho)=\rho,\quad s_4(i)=-i.
\]

The $q$-expansions \eqref{E2}--\eqref{E6} imply that for large $\im(\tau)$ the function $s_4$ can be represented in the form  
\begin{align}\label{eq:s4qser}
s_4(\tau) &=\tau -\frac{i}{120\pi}q^{-1} +i\sum_{n=0}^\infty a_nq^n\\
&=\tau -\frac{i}{120\pi}e^{-2\pi i \tau} +O(1) \text{ as $\im(\tau)\to +\infty$.} \label{eq:s4q}
 \end{align}  
 Here $a_n\in \R$ for $n\in \N_0$ and the $q$-series in 
 \eqref{eq:s4qser} converges when $|q|$ is sufficiently small, or equivalently, if  $\im(\tau)$ is sufficiently large. 

From \eqref{eq:s4q} we see  that $s_4(\tau)\to \infty$ as $\tau\in \H$ and 
$\im(\tau)\to +\infty$. This shows that we can continuously extend $s_4$ as a continuous map from the triangle  $T_0$  to $\wC$ by setting 
$s_4(\infty)=\infty$. 


Moreover, for  $t>0$ large we have 
\begin{align}
s_4(it)&=it -\frac{i}{120\pi}e^{2\pi t} +O(1), \label{eq:s4imasym}  \\
s_4(\tfrac12+it)&=\tfrac12+it +\frac{i}{120\pi}e^{2\pi t} +O(1).  
\label{eq:s4linsym}
\end{align}

In the following, we  denote by 
\begin{align}\label{eq:sidesT0}
A&\coloneq \{it: t\ge 1\}\cup\{\infty\},\\
B&\coloneq \{e^{it}: \pi/3\le t\le  \pi/2 \},\notag\\
C&\coloneq \{\tfrac12+it: t\ge \sqrt3/2 \} \cup\{\infty\}\notag
\end{align}
the three sides of the circular arc triangle $T_0$ and by  
\begin{align} \label{eq:sidesX0}
A'&\coloneq \{it: t\le -1\}\cup\{\infty\}, \\
B'&\coloneq \{e^{it}: \pi/3\le t\le  3\pi/2 \},\notag \\
C'&\coloneq \{\tfrac12+it: t\ge \sqrt3/2 \} \cup\{\infty\} \notag
\end{align}
the three sides of $X_0$ as described in Theorem~\ref{thm:s4}. 


\begin{lem}\label{lem:s4injinfty}
The map $s_4$ is injective on $T_0$ near $\infty$. 
\end{lem}
\begin{proof} This follows from the expansion \eqref{eq:s4qser}
and  Lemma~\ref{lem:injinfty}~\ref{item:inj2} applied for $\alpha=0$ and $\beta=1/2$.  
\end{proof}

\begin{lem}\label{lem:s4fixed}
A point $\tau_0\in \H$ is a fixed point of $s_4$ if and only if $\tau_0\in \Ga(\rho)$. 
\end{lem}
\begin{proof} The definition of $s_4$ shows that $\tau_0\in \H$ can only be a fixed point of $s_4$ if $E_4(\tau_0)=0$. Then 
$\tau_0\in \Ga(\rho)$ by \eqref{E4zeros}. Conversely, if $\tau_0\in \Ga(\rho)$, then $E_4(\tau_0)=0$ and $(E_2E_4-E_6)(\tau_0)=-
E_6(\tau_0)\ne 0$, because $E_4$ and $E_6$ have no common zeros. It follows that then $\tau_0$ is a fixed point of $s_4$. 
\end{proof}

An immediate consequence of the previous lemma is the fact that 
the only fixed points of $s_4$ in $T_0$ are the points $\rho$ and 
$\infty$. In particular, no interior point of any of the sides $A$, $B$, $C$ of $T_0$ is a fixed point of $s_4$. 


\begin{lem}\label{lem:s4homeo} The map $s_4$ is a homeomorphism of $\partial T_0$ onto $\partial X_0$. Moreover, if we orient   $\partial T_0$ 
so that $T_0$ lies on the left, then  $X_0$ lies on the left of $\partial X_0$ if we equip $\partial X_0$ with the orientation induced  by the map $s_4$.  
\end{lem}
\begin{proof} We know that no interior point of any of the sides of $T_0$ is a fixed point of  the meromorphic function $s_4$  (Lemma~\ref{lem:s4fixed}) and that $s_4$  is locally injective near each point in $\H$ 
(Corollary~\ref{cor:locinj}~\ref{i:loc4}). So condition~\ref{i:cir2} and  condition~\ref{i:cir3} in Lemma~\ref{lem:circarc} are true for $s_4$ and each side of $T_0$. 


It  follows directly from the definitions that $E_2(\tau)$, $E_4(\tau)$,  $E_6(\tau)$ take real values when $\tau\in \H$ and 
$\re(\tau)=0$ or $\re(\tau)=1/2$, because then $q=e^{2\pi i\tau}\in \R$. 
This implies that  $s_4(\tau)\in L_{0}$ (see \eqref{eq:imax}) when   $\re(\tau)=0$ and 
 $s_4(\tau)\in L_{1/2}$ (see \eqref{eq:12line}) when $\re(\tau)=1/2 $. 
 As a consequence,  $s_4$ sends the arc $A\sub L_{0}$ into $ L_{0}$ and the arc $C \sub L_{1/2}$  into 
   $L_{1/2}$.



  Since $s_4(A)\sub L_{0}$ and $s_4(i)=-i\not\in A$, we can apply Lemma~\ref{lem:circarc}~\ref{i:ciri} (with $L_{0}$ taking the role of $K$) and conclude that $s_4$ sends $A$ homeomorphically 
onto its image $s_4(A)$. This image must be one of the two subarcs
of  $L_{0}$ joining $s_4(i)=-i$ and $s_4(\infty)=\infty$. 
Now \eqref{eq:s4imasym} shows that $\im(s_4(it))$ takes  large negative values if $t>0$ is large. Therefore, we must have $s_4(A)=A'$ and so 
$s_4$ is a homeomorphism of $A$ onto $A'$. In particular,  the point $s_4(\tau)$  moves monotonically
from $\infty$ to $-i$ along $A'$ if $\tau$ moves from $\infty$ 
to $i$ along $A$. So if we equip $A'$ with this orientation, then  
$X_0$ lies on the left of $A'$. 


We have $s_4(C)\sub L_{1/2}$,  $s_4(\infty)=\infty$, and 
 $s_4(\rho)=\rho$. Moreover, \eqref{eq:s4linsym} shows that for $t>0$  large enough we have $\im(s_4(\tfrac12+it))>t$. For such $t$
 the image $s_4(\tfrac12+it)$ of $p=\tfrac12+it$ lies in the interior 
 of the subarc of 
 $C$ with  endpoints $\infty$ and $p$. Lemma~\ref{lem:circarc}~\ref{i:cirii} (with $L_{1/2}$ taking the role of $K$) shows that 
 $s_4$ is a homeomorphism  of $C$ onto itself. Therefore,  the point $s_4(\tau)$  moves monotonically
from $\rho$ to $\infty$ along $C'=C$ if $\tau$ moves from $\rho$ 
to $\infty$ along $C$. So if we equip $C'$ with this orientation, then  
$X_0$ lies on the left of $C'$.  

 We know by Proposition~\ref{prop:poly46} that 
\[s_4(1/\overline {\tau})=1/\overline {s_4(\tau)}\] 
for  $\tau\in \H$.
If $\tau\in B$, then $\tau$ lies on the unit circle $\partial \D$ and so $\tau=1/\overline \tau$. 
This implies that
\[ {s_4(\tau)}= s_4(1/\overline \tau)=1/\overline {s_4(\tau)}\] 
  and so $|s_4(\tau)|=1$ for $\tau\in B$. We see that $s_4$ sends $B\sub \partial \D$ into $\partial \D$. Since $s_4(i)=-i\not\in B$, Lemma~\ref{lem:circarc}~\ref{i:ciri} implies that  $s_4$ is a  homeomorphism of $B$ onto its image $s_4(B)$. 

  This image is one of the subarc of $\partial \D$ with endpoints $s_4(i)=-i$ and $s_4(\rho)=\rho$.   Here we actually  must have $s_4(B)=B'$ as follows by considering orientations. Indeed, since $s_4$ is locally injective near $i$,
  this map  is  conformal and hence orientation-preserving   near $i$. We know that $s_4$ sends $A$ oriented  from $\infty$ to $i$ onto the arc $A'$ oriented from $\infty$ to $-i$. Since $B$ lies on  the left of the oriented arc $A$ locally near $i$, the image $s_4(B)$ must lie on the left of $A'$ 
near $s_4(i)=-i$. This only leaves the possibility that $s_4$ sends $B$ homeomorphically onto $B'$. Moreover, 
the point $s_4(\tau)$  moves monotonically
from $-i$ to $\rho$ along $B'$ if $\tau$ moves from $i$ 
to $\rho$ along $B$. So if we equip $B'$ with this orientation, then  
$X_0$ lies on the left of $B'$.  


We conclude that $s_4$ sends the three sides $A$, $B$, $C$ of $T_0$ homeomorphically onto the three sides $A'$, $B'$, $C'$ of $X_0$, respectively. 
It follows that $s_4$ is a homeomorphism of $\partial T_0$ onto $\partial X_0$. Moreover, our previous considerations show that if we orient $\partial T_0$ so that $T_0$ lies on the left of $\partial T_0$, then $X_0$ lies on the left of $\partial X_0$ equipped with 
induced orientation under $s_4$. 
\end{proof}

\begin{lem} \label{lem:incronB} There exists a strictly increasing continuous function 
\[\varphi\: 
[\pi/3, \pi/2]\ra [\pi/3, 3\pi/2]\] such that 
$s_4(e^{it})=e^{i\varphi(t)}$ for  $t\in [\pi/3, \pi/2]$ 
and $\varphi(t)>t$ for $t\in  (\pi/3, \pi/2]$.  
\end{lem}

\begin{proof} We have seen in the proof of Lemma~\ref{lem:s4homeo} that 
$s_4$ maps the arc $B\sub \partial \D$ homeomorphically onto the arc $B'\sub \partial \D$. It  follows that there exists a strictly increasing function 
\[\varphi\: 
[\pi/3, \pi/2]\ra [\pi/3, 3\pi/2]\] such that 
$s_4(e^{it})=e^{i\varphi(t)}$ for  $t\in [\pi/3, \pi/2]$. 
Since $s_4(\rho)=\rho$ and $s_4(i)=-i$, we have $\varphi(\pi/3)=\pi/3$ and $\varphi(\pi/2)=3\pi/2>\pi/2$. The last inequality implies that on 
$\varphi(t)>t$ for all $t\in (\pi/3, \pi/2]$, because otherwise 
there would be a point $t_0\in  (\pi/3, \pi/2]$ with $\varphi(t_0)=t_0$
by the intermediate value theorem. But then $\tau_0=e^{it_0}$ would be a fixed point of $s_4$ in $B\setminus\{\rho\}\sub \H\setminus \Ga(\rho)$, but we know that $s_4$ has no  fixed points in $\H \setminus \Ga(\rho)$ by Lemma~\ref{lem:s4fixed}.   
\end{proof}


In order to apply Proposition~\ref{prop:arg} for $f=s_4$ and $U=T_0$, we want to show that $s_4$ has no poles in $\inte(T_0)$ and is hence holomorphic there. One way to do this is to use numerical estimates that rule out that the function 
$E_2E_4-E_6$  giving rise to poles of $s_4$ (see  \eqref{eq:s4def}) has any zeros 
in $\inte(T_0)$. We prefer a different approach that avoids 
numerical estimates. 

For this we consider the auxiliary function
\begin{equation}\label{eq:gdef}
g(\tau)\coloneq \frac{1}{\tau-s_4(\tau)}=-\frac{i\pi}{6}\cdot\frac {E_2E_4-E_6}{E_4}.
\end{equation}
This is a meromorphic function on $\H$ with poles exactly 
at the points where $E_4$ vanishes, that is, the points in $\Ga(\rho)$. In particular, $g$ is holomorphic in $\inte(T_0)$. The idea is now to show that $\re(g(\tau))>0$ for $\tau \in \inte(T_0)$. 
Then necessarily $E_2(\tau)E_4(\tau)-E_6(\tau)\ne 0$ for  
$\tau \in \inte(T_0)$. This in turn implies that $s_4$ has no poles in 
$\inte(T_0)$. In order to show that $g$ has positive real part on $\inte(T_0)$,
we analyze the behavior of $g$ near points 
$\tau\in \partial T_0$. 

\begin{lem} \label{lemgs4sides} We have $\re(g(\tau))=0$ for $\tau \in \inte(A)\cup \inte 
(C)$ and $\re(g(\tau))>0$ for $\tau \in \inte(B)$. 
\end{lem}

\begin{proof}  The first statement follows immediately from 
the definition \eqref{eq:gdef} of $g$, because on the set  $\inte(A)\cup \inte 
(C)$ the functions $E_2$, $E_4$, $E_6$ only take real values. 

 If $w\in \C$ and $\re(w)>0$, then also $\re(1/w)>0$.
Therefore, it is enough to establish the inequality 
$\re(\tau-s_4(\tau))>0$ for 
$\tau\in \inte(B)$. To see this, let $\varphi$ be the function from Lemma~\ref{lem:incronB}. Then it suffices to show that $\re(e^{it}-e^{i\varphi(t)})>0$ for 
$t\in (\pi/3,\pi/2)$. Essentially, this follows from the fact 
that 
\[\pi/3< t<\varphi(t)\le 3\pi/2\]  for $t\in (\pi/3,\pi/2)$, and so 
the point $s_4(e^{it})=e^{i\varphi(t)}$ lies in the half-plane 
$$\{ z\in \C: \re(z)<\re(e^{it})=\cos t\}. $$ More formally,  note that for 
$t\in (\pi/3,\pi/2)$ we have 
 $t+\varphi(t)\in (0,2\pi)$ and 
\[ 0>t-\varphi(t) >\pi/3-3\pi/2=-7\pi/6>-2\pi.  
\]
Hence $(t+\varphi(t))/2\in (0,\pi)$ and $(t-\varphi(t))/2\in (-\pi,0)$, which implies that 
\[
\sin((t+\varphi(t))/2)>0 \text{ and } \sin((t-\varphi(t))/2)<0
\]
and so
\begin{align*}
\re(e^{it}-e^{i\varphi(t)})&=\cos t-\cos\varphi(t)\\
&=-2\sin((t+\varphi(t))/2)
\sin((t-\varphi(t))/2)>0. \qedhere
\end{align*}
\end{proof}


\begin{lem} \label{lem:gs4vertex} We have 
\[
\liminf_{\inte(T_0)\ni \tau \to \tau_0} \re(g(\tau))\ge 0
\]
for $\tau_0\in \{i, \rho, \infty\}$
\end{lem}

\begin{proof} Let 
\[ f(\tau)\coloneq \tau-s_4(\tau)=\frac{6iE_4}{\pi(E_2E_4-E_6)}
\] for $\tau\in \H$.  Note that $s_4'(i)=-5E_4(i)/E_2(i)^2$ by \eqref{eq:ders4}. Since $E_2(i)>0$ by 
\eqref{eq:E2spec} and $E_4(i)>0$ as easily follows from \eqref{E4}, we see that $f'(i)=1-s'_4(i)>0$. Moreover, $f$ sends the imaginary axis near $i$ into itself.     Then Lemma~\ref{lem:orient} implies that
$\re(f(\tau))>0$ and so $\re(g(\tau))=\re(1/f(\tau))>0$ 
 for $\tau \in \inte(T_0)$ near $i$. The statement for $\tau_0=i$ follows.    


 By \eqref{eq:ders4} we have $s_4'(\rho)=5$ and so  
$f'(\rho)=-4<0$. The map $f$ sends the line $L_{1/2}$ near $\rho$ into the imaginary axis. It  easily follows from Lemma~\ref{lem:orient} that 
$\re(f(\tau))>0$ and so $\re(g(\tau))=\re(1/f(\tau))>0$ for $\tau \in \inte(T_0)$ near $\rho$.  The statement for $\tau_0=\rho$ follows.    

Finally, \eqref{eq:s4q} and \eqref{eq:gdef} show  that for $\tau\in \H$ with $\im(\tau)$ large we have 
\[ 
g(\tau)=-120\pi iq (1+O(q)),
\]
and so 
\[
\liminf_{\inte(T_0)\ni \tau \to \infty} \re(g(\tau))=0.
\]
The proof is complete.
\end{proof}


\begin{lem}  \label{lem:gs4pos}
We have $\re(g(\tau))>0$ for $\tau\in \inte(T_0)$. 
\end{lem}

\begin{proof} By Lemma~\ref{lem:minprincip} it is enough to show that
\[
\liminf_{\inte(T_0)\ni \tau \to \tau_0} \re(g(\tau))\ge 0
\]
for all $\tau_0\in \partial T_0$. This follows from Lemmas \ref{lemgs4sides} and~\ref{lem:gs4vertex}. 
\end{proof}

\begin{lem} \label{lem:s4nopoles} The function $s_4$ has no poles in $\inte(T_0)$. 
\end{lem}
\begin{proof} By Lemma~\ref{lem:gs4pos} the function  $g$ defined in \eqref{eq:gdef} has no zeros in $\inte(T_0)$. This implies that $s_4$ cannot have poles in $\inte(T_0)$. \end{proof}

 \begin{proof}[Proof of Theorem~\ref{thm:s4}]
 We can apply Proposition~\ref{prop:arg} to $f=s_4$, $U=T_0$, and $V=X_0$ 
   by Lemmas~\ref{lem:s4homeo},  \ref{lem:s4injinfty} and \ref{lem:s4nopoles}. The statement follows.
  \end{proof}


