 \begin{proof}[Proof of Corollary~\ref{cor:s4}] We will just give the basic idea omitting some  details. 

 By Theorem~\ref{thm:s4} the map 
 $s_4$ is a conformal map of $T_0$ onto $X_0$. One can now apply successive Schwarz reflections. If we do this with the triangle $T_0$ 
 in Figure~\ref{fig:T} and reflect in appropriate sides, then one obtains the triangles $T_0, \dots, T_5$ as indicated in the figure. Note that reflection in any of the sides of these triangles and, more generally, in any side of a triangle in the tessellation tessellation $\mathcal{T}$, is given by elements in the extended modular group $\overline{\Ga}$. 



By Proposition~\ref{prop:poly46} the images under these reflections  undergo the same operation as the original triangle in the tessellation $\mathcal{T}$. For example, to obtain $T_1$, we reflect $T_0$ in the unit circle. This means that to obtain the image $X_1=s_4(T_1)$, we also have to reflect $X_0$ also in the unit circle. 
 In follows that the images $X_k\coloneq s_4(T_k)$, $k=0, \dots, 5$ can be represented as in Figure~\ref{fig:covs4}. Each of them is a circular arc triangle with angles  $\pi, \pi/2, \pi/3$. Note that 
 the union of these images is equal to $\wC\setminus \overline{\inte(V_0)}$, where $V_0$ is the circular arc triangle given in \eqref{eq:V0}. 

These considerations  imply $\overline{s_4}$ is an anti-conformal map that sends the circular arc triangle $V_0$ onto  the complementary circular arc triangle $\wC\setminus \inte(V_0)$. 
Here the vertices of $V_0$ are fixed and each side of $V_0$ is mapped homeomorphically onto itself. 

 If $V$ is an arbitrary circular arc triangle from the tessellation $\mathcal{V}$, then there exists a unique  $\varphi\in \overline {\Ga}(2)\sub \overline{\Ga}$
such that $V=\varphi(V_0)$. Since each element in $\overline{\Ga}$ preserves the real axis, we have $\varphi(\overline{\tau})=\overline{\varphi(\tau)}$ for $\tau\in \wC$.  Then it follows from  \eqref{eq:poly46} that
\[
\varphi \circ \overline{s_4}=\overline{\varphi \circ s_4}=\overline{s_4\circ \varphi}
=\overline{s_4}\circ \varphi. 
\] 
This identity implies  that $\overline s_4$ is an anti-conformal map of $V=\varphi(V_0)$ onto its complementary triangle $\varphi(\wC\setminus \inte(V_0))=\wC\setminus \inte(V)$ as described in the statement.  
 \end{proof}

  \begin{proof}[Proof of Corollary~\ref{cor:crit4}]
   We know that $\tau\in \H$ is a critical point of $E_4$ if and only of $s_4(\tau)=\infty$ (see Lemma~\ref{lem:critpol46}). Now the considerations 
  in the proof of Corollary~\ref{cor:s4} show that for $\tau\in V_0$ we have 
  $s_4(\tau)=\infty$ if and only if $\tau=\infty$ (essentially, this follows from Figure~\ref{fig:covs4} by inspection). We conclude that 
  $E_4$ has  no critical points in $V_0\cap \H$. 

  If $V\in \mathcal{V}$ and $\infty\in V$, then $V=V_0+n$ for some $n\in \Z$. 
  Since we have the identity $E_4(\tau+n)=E_4(\tau)$ for $\tau\in \H$, it follows that $E_6$ has no critical points in $V\cap \H$.

  Now let $V\in \mathcal{V}$ with $\infty\not \in V$ be arbitrary. Then it follows from 
   Corollary~\ref{cor:s4} that  the map $s_4$ attains the value $\infty$ exactly once in $V$ and this unique preimage of $\infty$ in $V$ must  lie in $\inte(V)$.   
  Since the critical points of $E_4$ are simple by 
   Proposition~\ref{prop:Esimcrit}, the statement follows. 
  \end{proof}












  \section{Mapping behavior of  $s_6$} \label{sec:maps6}


  Analyzing the mapping behavior of $s_6$ runs along very similar lines as for $s_4$ with small modifications. 

   Using $E_4(\rho)=0=E_6(i)$ and \eqref{eq:E2spec},  we see that 
$$ s_6(\rho)=\overline {\rho},\quad s_6(i)=i.$$
For large $\im(\tau)$ the function $s_6$ can be represented in the form  
\begin{align}\label{eq:s6qser}
s_6(\tau) &=\tau +\frac{i}{168\pi}q^{-1} +i \sum_{n=0}^\infty a_nq^n\\
&=\tau +\frac{i}{168\pi}e^{-2\pi i \tau} +O(1) \text{ as $\im(\tau)\to +\infty$.}  \label{eq:s6q}
 \end{align}  
 Here $a_n\in \R$ for $n\in \N_0$ and the $q$-series in 
 \eqref{eq:s6qser} converges when $|q|$ is sufficiently small, or equivalently, if  $\im(\tau)$ is sufficiently large. 

From \eqref{eq:s6q} we see  that $s_6(\tau)\to \infty$ as $\tau\in \H$ and 
$\im(\tau)\to +\infty$. This shows that we can continuously extend $s_6$ as a continuous map from $T_0$ to $\wC$ by setting 
$s_6(\infty)=\infty$. 

For  $t>0$ large we have 
\begin{align}
s_6(it)&=it +\frac{i}{168\pi}e^{2\pi t} +O(1), \label{eq:s6imasym}  \\
s_6(\tfrac12+it)&=\tfrac12+it -\frac{i}{168\pi}e^{2\pi t} +O(1).  
\label{eq:s6linsym}
\end{align}

In the following, we  again denote by $A$, $B$, $C$ the sides of $T_0$ as in \eqref{eq:sidesT0}. Let   
\begin{align*}
A'&\coloneq \{it: t\ge 1\}\cup\{\infty\},\\
B'&\coloneq \{e^{it}: -\pi/3\le t\le  \pi/2 \},\\
C'&\coloneq \{\tfrac12+it: t\le- \sqrt3/2 \} \cup\{\infty\}
\end{align*}
be the three sides of $Y_0$ as described in Theorem~\ref{thm:s6}. 


\begin{lem}\label{lem:s6injinfty}
The map $s_6$ is injective on $T_0$ near $\infty$. 
\end{lem}
\begin{proof} This follows from the expansion \eqref{eq:s6qser}
and Lemma~\ref{lem:injinfty}~\ref{item:inj2} applied for $\alpha=0$ and $\beta=1/2$.  
\end{proof}

\begin{lem}\label{lem:s6fixed}
A point $\tau_0\in \H$ is a fixed point of $s_6$ if and only if $\tau_0\in \Ga(i)$. 
\end{lem}
\begin{proof} The definition of $s_6$ shows that $\tau_0\in \H$ can only be a fixed point of $s_6$ if $E_6(\tau_0)=0$. Then 
$\tau_0\in \Ga(i)$ by \eqref{E6zeros}. Conversely, if $\tau_0\in \Ga(i)$, then $E_6(\tau_0)=0$ and $(E_2E_6-E_4^2)(\tau_0)=-
E_4^2(\tau_0)\ne 0$, because $E_4$ and $E_6$ have no common zeros. It follows that then $\tau_0$ is a fixed point of $s_6$. 
\end{proof}

An immediate consequence of the previous lemma is the fact that 
the only fixed points of $s_6$ in $T_0$ are the points $i$ and 
$\infty$. In particular, no interior point of any of the sides $A$, $B$, $C$ of $T_0$ is a fixed point of $s_6$. 


\begin{lem}\label{lem:s6homeo} The map $s_6$ is a homeomorphism of $\partial T_0$ onto $\partial Y_0$. Moreover, if we orient   $\partial T_0$ 
so that $T_0$ lies on the left, then  $Y_0$ lies on the left of $\partial Y_0$ if we equip under $\partial Y_0$ with the orientation induced  by $s_6$.  
\end{lem}
\begin{proof} We know that no interior point of any of the sides of $T_0$ is a fixed point of  the meromorphic function $s_6$  (Lemma~\ref{lem:s6fixed}). Moreover, by Corollary~\ref{cor:locinj}~\ref{i:loc6} the function $s_6$  is locally injective near each point in $\H\setminus \Ga(\rho)$ and hence near 
each  interior point of any of the sides of $T_0$. 
 So condition~\ref{i:cir2} and  condition~\ref{i:cir3} in Lemma~\ref{lem:circarc} are true for $s_6$ and each side of $T_0$. 



Since  $E_2(\tau), E_4(\tau), E_6(\tau)\in \R$  when $\tau\in \H$ and 
$\re(\tau)=0$ or $\re(\tau)=1/2$, the map $s_6$ sends the arc $A\sub L_{0}$ into $ L_{0}$ and the arc $C \sub L_{1/2}$  into 
  $ L_{1/2}$.

We have  $s_6(i)=i$ and $s_6(\infty)=\infty$. Moreover, \eqref{eq:s6imasym} shows that for $t>0$  large enough we have $\im(s_6(it))>t$. For such $t$
 the image $s_6(it)$ of $p=it$ lies in the interior 
 of the subarc of 
 $A$ with  endpoints $\infty$ and $p$.  Lemma~\ref{lem:circarc}~\ref{i:cirii} (with $L_{0}$ taking the role of $\partial K$) shows that 
 $s_6$ is a homeomorphism  of $A$ onto itself. As a consequence, the point $s_6(\tau)$  moves monotonically
from $\infty$ to $i$ along $A'=A$ if $\tau$ moves from $\infty$ 
to $i$ along $A$. So if we equip $A'$ with this orientation, then  
$Y_0$ lies on the left of $A'$. 




We have $s_6(C)\sub L_{1/2}$  and 
 $s_6(\rho)=\overline \rho \not \in C$. Lemma~\ref{lem:circarc}~\ref{i:ciri} (with $L_{1/2}$ taking the role of $K$)  shows that $s_6$ is a homeomorphism of $C$ onto its image $s_6(C)$. 
 This image is a one of the two subarcs of    $L_{1/2}$
with endpoints $s_6(\rho)=\overline \rho$ and $s_6(\infty)=\infty$.  
Now  \eqref{eq:s6linsym} shows that for $t>0$  large  $\im(s_6(\tfrac12+it))$ takes a large negative value. 
Hence $s_6(C)=C'$.  

It follows that  the  point $s_6(\tau)$  moves monotonically
from $\overline \rho$ to $\infty$ along $C'$ if $\tau$ moves from $\rho$ 
to $\infty$ along $C$. So if we equip $C'$ with this orientation, then  
$Y_0$ lies on the left of $C'$.   

 We know by Proposition~\ref{prop:poly46} that 
\[s_6(1/\overline {\tau})=1/\overline {s_6(\tau)}\] 
for  $\tau\in \H$.
If $\tau\in B$, then $\tau$ lies on the unit circle and so $\tau=1/\overline \tau$. 
This implies that
\[ {s_6(\tau)}= s_6(1/\overline \tau)=1/\overline {s_6(\tau)}\] 
  and so $|s_6(\tau)|=1$ for $\tau\in B$. 

We see that $s_6$ sends $B$ into the unit circle $\partial \D$. Since $s_6(\rho)=\overline \rho\not \in B$, Lemma~\ref{lem:circarc}~\ref{i:ciri} implies that $s_6$ sends $B$ homeomorphically onto its image $s_6(B)$. 

This image is one of the subarc of $\partial \D$ with endpoints $s_6(i)=i$ and $s_6(\rho)=\overline \rho$.   Here we actually  must have $s_6(B)=B'$ as follows by considering orientations. Indeed,
since $s_6$ is locally injective near $i$,
  this map  is  conformal and hence orientation-preserving 
map  near $i$.  We know that $s_6$ sends $A$ oriented from $\infty$ to $i$ into itself  oriented in the same way.  Since $B$ lies on  the left of the oriented arc $A$ locally near $i$, the image $s_6(B)$ must lie on the left of $A'=A$ 
near $s_6(i)=i$. This only leaves the possibility that $s_6$ sends $B$ homeomorphically onto $B'$. Moreover, 
the point $s_6(\tau)$  moves monotonically
from $i$ to $\overline \rho$ along $B'$ if $\tau$ moves from $i$ 
to $\rho$ along $B$. So if we equip $B'$ with this orientation, then  
$Y_0$ lies on the left of $B'$.  


We conclude that $s_6$ sends the three sides $A$, $B$, $C$ of $T_0$ homeomorphically onto the three sides $A'$, $B'$, $C'$ of $Y_0$, respectively. 
It follows that $s_6$ is a homeomorphism of $\partial T_0$ onto $\partial Y_0$. Moreover, our  considerations shows that if we orient $\partial T_0$ so that $T_0$ lies on the left of $\partial T_0$, then $Y_0$ lies on the left of $\partial Y_0$ equipped with 
induced orientation under $s_6$. 
\end{proof}

\begin{lem} \label{lem:incronB6} There exists a strictly increasing continuous function 
\[\varphi\: 
[\pi/3, \pi/2]\ra [-\pi/3, \pi/2]\] such that 
$s_6(e^{it})=e^{i\varphi(t)}$ for  $t\in [\pi/3, \pi/2]$ 
and $\varphi(t)<t$ for $t\in  [-\pi/3, \pi/2)$.  
\end{lem}

\begin{proof} We have seen in the proof of Lemma~\ref{lem:s4homeo} that 
$s_6$ maps the arc $B\sub \partial \D$ homeomorphically onto the arc $B'\sub \partial \D$. It  follows that there exists a strictly increasing function 
\[\varphi\: 
[\pi/3, \pi/2]\ra [-\pi/3, \pi/2]\] such that 
$s_6(e^{it})=e^{i\varphi(t)}$ for  $t\in [\pi/3, \pi/2]$. 
Since $s_6(i)=i$ and $s_6(\rho)=\overline \rho$, we have $\varphi(\pi/2)=\pi/2$ 
and $\varphi(\pi/3)=-\pi/3<\pi/3$. The last inequality implies that  
$\varphi(t)<t$ for all $t\in [\pi/3, \pi/2)$, because otherwise 
there would be a point $t_0\in  [\pi/3, \pi/2)$ with $\varphi(t_0)=t_0$
by the intermediate value theorem. But then $\tau_0=e^{it_0}$ would be a fixed point of $s_6$ in $B\setminus\{i\}\sub \H\setminus \Ga(i)$, but we know that $s_6$ has no  fixed points in $\H \setminus \Ga(i)$ by Lemma~\ref{lem:s6fixed}.  
\end{proof}


In order to apply Proposition~\ref{prop:arg}  for $f=s_6$ and $U=T_0$, we have to show that $s_6$ has no poles in $\inte(T_0)$ and is hence holomorphic there. 

For this we consider the auxiliary function
\begin{equation}\label{eq:gdef6}
g(\tau)= \frac{1}{s_6(\tau)-\tau}=\frac{i\pi}{6}\cdot \frac {E_2E_6-E_4^2}{E_6}.
\end{equation}
This is a meromorphic function on $\H$ with poles exactly 
at the points where $E_6$ vanishes, that is, the points in $\Ga(i)$. In particular, $g$ is holomorphic in $\inte(T_0)$. 

\begin{lem} \label{lemgs6sides} We have $\re(g(\tau))=0$ for $\tau \in \inte(A)\cup \inte 
(C)$ and $\re(g(\tau))>0$ for $\tau \in \inte(B)$. 
\end{lem}

\begin{proof}  The first statement follows immediately from 
the definition \eqref{eq:gdef6} of $g$, because on the set  $\inte(A)\cup \inte 
(C)$ the functions $E_2$, $E_4$, $E_6$ only take real values. 

 If $w\in \C$ and $\re(w)>0$, then also $\re(1/w)>0$.
Therefore, it is enough to establish the inequality 
$\re(s_6(\tau)-\tau)>0$ for 
$\tau\in \inte(B)$. To see this, let $\varphi$ be the function from Lemma~\ref{lem:incronB6}. Then it suffices to show that $\re(e^{i\varphi(t)}-e^{it})>0$ for 
$t\in (\pi/3,\pi/2)$. Note that for 
$t\in (\pi/3,\pi/2)$ we have 
 $\varphi(t)+t\in (0,\pi)$ and 
\[ 0>\varphi(t)-t >-\pi/3-\pi/2=-5\pi/6>-\pi.  
\]
Hence $(\varphi(t)+t)/2\in (0,\pi/2)$ and $(\varphi(t)-t)/2\in (0,-\pi/2)$, which implies that 
\[
\sin((\varphi(t)+t)/2)>0 \text{ and } \sin((\varphi(t)-t)/2)<0
\]
and so
\begin{align*}
\re(e^{i\varphi(t)}-e^{it})&=\cos\varphi(t)- \cos t\\
&=-2\sin((\varphi(t)+t)/2)
\sin((\varphi(t)-t)/2)>0.\qedhere
\end{align*}\end{proof}



\begin{lem} \label{lem:gs6vertex} We have 
\[
\liminf_{\inte(T_0)\ni \tau \to \tau_0} \re(g(\tau))\ge 0
\]
for $\tau_0\in \{i, \rho, \infty\}$
\end{lem}

\begin{proof} Let 
\[ f(\tau)\coloneq s_6(\tau)-\tau=-\frac{6iE_6}{\pi(E_2E_6-E_4^2)}
\] for $\tau\in \H$.  Note that $s_6'(i)=7$ by  \eqref{eq:ders6} and so $f'(i)=6>0$. Moreover, $f$ sends the imaginary axis near $i$ into itself.     Then Lemma~\ref{lem:orient} implies that
$\re(f(\tau))>0$ and so $\re(g(\tau))=\re(1/f(\tau))>0$ 
 for $\tau \in \inte(T_0)$ near $i$. The statement for $\tau_0=i$ follows.    


 By \eqref{eq:ders6} we have $s_6'(\rho)=0$ and so  
$f'(\rho)=-1<0$. The map $f$ sends the line $L_{1/2}$ near $\rho$ into the imaginary axis. It  easily follows from Lemma~\ref{lem:orient} that 
$\re(f(\tau))>0$ and so $\re(g(\tau))=\re(1/f(\tau))>0$ for $\tau \in \inte(T_0)$ near $\rho$.  The statement for $\tau_0=\rho$ follows.    

Finally, \eqref{eq:s6q} and \eqref{eq:gdef6} show  that for $\tau\in \H$ with $\im(\tau)$ large we have 
\[ 
g(\tau)=-168\pi iq (1+O(q)),
\]
and so 
\[
\liminf_{\inte(T_0)\ni \tau \to \infty} \re(g(\tau))=0.
\]
The proof is complete.
\end{proof}


\begin{lem}  \label{lem:s6gpos}
We have $\re(g(\tau))>0$ for $\tau\in \inte(T_0)$. 
\end{lem}

\begin{proof} By Lemma~\ref{lem:minprincip} it is enough to show that
\[
\liminf_{\inte(T_0)\ni \tau \to \tau_0} \re(g(\tau))\ge 0
\]
for all $\tau_0\in \partial T_0$. This follows from Lemmas \ref{lemgs6sides} and~\ref{lem:gs6vertex}. 
\end{proof}

