\begin{lem} \label{lem:s2onim} The maps $s_2^+$ and $s_2^-$ on $W$  can be continuously extended to  $0$ and $\infty$ by setting $s_2^+(0)=0=s_2^-(0)$ and $s_2^+(\infty)=\infty=s_2^-(\infty)$.
Moreover, for small $t>0$ we have 
$s_2^+(it)=ih(t)$, where $0<h(t)<t$.  
\end{lem}

\begin{proof} 
It follows from \eqref{eq:s2+ser} and   \eqref{eq:s2-ser} that $s_2^+(\tau)\to \infty$ and $s_2^-(\tau)\to \infty$ as $\tau \in W$ and $\tau\to \infty$, because then necessarily $\im(\tau)\to +\infty$ and $q\to 0$.

For a point $\tau\in W$ let $\tau'\coloneq -1/\tau\in W$. Then 
as $\tau\to 0$, we have $\tau'\to \infty$ and so $s_2^+(\tau')\to \infty$ and  $s_2^-(\tau')\to \infty$ by what we have just seen. Then  \eqref{eq:s2trans} implies that 
 $s_2^+(\tau)=-1/s_2^-(\tau')\to 0$ and  $s_2^-(\tau)=-1/s_2^+(\tau')\to 0$. We conclude that on $W$ the maps  $s^+_2$   and $s^+_2$  have indeed a continuous extension to $0$ and $\infty$ as stated. 




Now suppose that  $\tau=it$ with $t>0$. Then $\tau'=-1/\tau=it'$, where  
$t'\coloneq 1/t$,  and  \eqref{eq:s2-ser}  shows that if $t$ is sufficiently small, then 
$s_2^-(\tau')=i\widetilde h(t')$ with $\widetilde h(t')>t'$. It follows that 
if we set $h(t)\coloneq 1/\widetilde h(t')$ for small $t>0$, then 
$0<h(t)<1/t'=t$ and 
\[ s_2^+(it)=-1/s_2^-(it')=i/\widetilde h(t')=i h(t).
\]
The statement follows. 
\end{proof}

Recall the definition of $U_0$ given in \eqref{eq:U0}. Since $U_0\sub W\cup\{0,\infty\}$, 
by the previous lemma we can consider $s_2^+$ and $s_2^-$ as continuous maps on $U_0$.  

\begin{lem}\label{lem:s2injinfty}
The map $s_2^+$ is injective on $U_0$ near $\infty$. 
\end{lem}
\begin{proof} This follows from  \eqref{eq:s2+ser}
and  Lemma~\ref{lem:injinfty}~\ref{item:inj1}.  
\end{proof}


 \begin{lem}\label{lem:s2fixed} The maps   $s^+_2$ and $s^-_2$ have no 
 fixed point in $W$.
 \end{lem}  
 \begin{proof} Note that $s_2^\pm(\tau)-\tau=1/(E_2\pm E_4^{1/2})$ cannot vanish
 anywhere on $W$ and so the statement follows.
 \end{proof} 








 We denote by 
\begin{align*}
A&\coloneq \{it: t\ge 0\}\cup\{\infty\},\\
B&\coloneq \{1+ e^{it}: 2\pi/3\le t\le  \pi \},\\
C&\coloneq \{\tfrac12+it: t\ge \sqrt3/2 \} \cup\{\infty\}
\end{align*}
the three sides of $U_0$ and by  
\begin{align*}
A'&\coloneq \{it: t\ge 0\}\cup\{\infty\},\\
B'&\coloneq \{1+e^{it}: \pi \le t\le  4\pi/3 \},\\
C'&\coloneq \{\tfrac12+it: t\ge -\sqrt3/2 \} \cup\{\infty\}
\end{align*}
the three sides of $Z_0$ as described in Theorem~\ref{thm:s2}.  



 \begin{lem}\label{lem:s2homeo} The map $s_2^+$ is a homeomorphism of $\partial U_0$ onto $\partial Z_0$. Moreover, if we orient   $\partial U_0$ 
so that $U_0$ lies on the left, then  $Z_0$ lies on the left of $\partial Z_0$ if we equip  $\partial Z_0$ with the orientation induced  by the map $s^+_2$.  
\end{lem}

\begin{proof} No interior point of any of the sides of $U_0$ is a fixed point of $s_2^+$ or  $s_2^+$ (Lemma~\ref{lem:s2fixed}) and it follows 
from Corollary~\ref{cor:locinj}~\ref{i:loc2} that  both $s_2^+$ and $s_2^-$ are locally injective near each of these points. So condition~\ref{i:cir2} and  condition~\ref{i:cir3} in Lemma~\ref{lem:circarc} are true for $s_2^+$ and 
$s_2^-$ and each side of $U_0$. 





We know that  $E_2(\tau), E_4(\tau)\in \R$  when $\tau\in \inte(A)\cup \inte(C)$. Actually, the values of $E_4(\tau)$ are positive when 
$\tau\in \inte(A)$. They are also positive for  $\tau\in \inte(C)$, because they are real, positive for $\tau\in \inte(C)$ near $\infty$ as follows from \eqref{E4}, and 
there is no zero of $E_4$ in $\inte(C)$. Therefore, \eqref{eq:E4root} implies that 
 $E_4^{1/2}(\tau)>0$ and in particular $E_4^{1/2}(\tau) \in \R$ for $\tau\in \inte(A)\cup \inte(C)$. We conclude that 
 $s^+_2(A)\sub  L_{0}$,   
 $s_2^+(C)\sub L_{1/2}$, and  $s_2^-(C)\sub   L_{1/2}$. 

Now by  Lemma~\ref{lem:s2onim} we have  $s_2^+(0)=0$, $s_2^+(\infty)=\infty$, and for points 
$\tau$ on the positive imaginary axis close to $0$, the image 
$s_2^+(\tau)$ lies in the interior  of the subarc of $A$ with endpoints $0$ and $\tau$. So by Lemma~\ref{lem:circarc}~\ref{i:cirii} (with $L_{0}$ taking the role of $K$) 
$s_2^+$ maps $A$ homeomorphically onto $A'=A$. Moreover,
it follows that there exists an increasing function  $h\: [0,\infty)\ra [0,\infty)$
such that 
\begin{equation}\label{eq:s2+h}
 0<h(t)<t \text{ and }  s_2^+(it)=ih(t)
\end{equation}
   for all $t>0$. 
We also see that the point $s_2^+(\tau)$  moves monotonically
from $\infty$ to $0$ along $A'=A$ if $\tau$ moves from $\infty$ 
to $0$ along $A$. So if we equip $A'$ with this orientation, then  
$Z_0$ lies on the left of $A'$. 

By \eqref{eq:s2+} we have  $s_2^+(\rho)= s_2^-(\rho)=\overline \rho\not\in C$.  Now Lemma~\ref{lem:circarc}~\ref{i:ciri} (with $L_{1/2}$ taking the role of $K$) shows that both maps  $s_2^+$ and $s_2^-$ send $C$ homeomorphically onto their images in  $ L_{1/2}$. These are necessarily arcs in 
$ L_{1/2}$ with endpoints $\overline \rho$ and $\infty$.
Now the expansions \eqref{eq:s2+ser} and \eqref{eq:s2-ser}  show that $\im(s_2^+(\tfrac12+it))$ takes large positive values and $\im(s_2^-(\tfrac12+it))$ takes large negative values when $t>0$ is large. It follows that 
$s_2^+$ sends $C$ homeomorphically onto $C'$, while 
$s_2^-$ sends $C$ homeomorphically onto the other subarc 
\[C''\coloneq \{\tfrac12+it: t\le -\sqrt3/2 \} \cup\{\infty\}
\]
of $ L_{1/2}$ with endpoints $\overline \rho$ and $\infty$.

The former statement implies  that $s_2^+(\tau)$  moves monotonically
from $\overline \rho$ to $\infty$ along $C'$ as $\tau$ moves from $\rho$ 
to $\infty$ along $C$. So if we equip $C'$ with this orientation, then  
$Z_0$ lies on the left of $C'$. We can also conclude that $s_2^-(\tau)$  moves monotonically
from $\overline \rho$ to $\infty$ along $C''$ as $\tau$ moves from $\rho$ 
to $\infty$ along $C$.

 Now let $\beta$ denote the reflection in the unit circle as in \eqref{eq:abcdef}.
Then $\beta(B)=C$ and $\beta(C'')=B'$. Moreover, $s_2^+=\beta \circ s_2^-\circ \beta$ on $B$ as follows from Lemma~\ref{lem:transs2}. Since $s_2^-$ sends $C$ homeomorphically onto $C''$, 
the map 
$s_2^+=\beta\circ s_2^-\circ \beta $ sends $B$ homeomorphically onto $B'$. 
Keeping track of orientations, we see that  
$s_2^+(\tau)$ moves from $0$ to $\overline \rho$ along $B'$ as  
as $\tau$ moves from $0$ 
to $\rho$ along $B$. If we equip $B'$ with this orientation, then $Z_0$ lies on the left of $B'$.  

 We conclude that $s_2^+$ sends the three sides $A$, $B$, $C$ of $U_0$ homeomorphically onto the three sides $A'$, $B'$, $C'$ of $Z_0$, respectively. 
It follows that $s_2^+$ is a homeomorphism of $\partial T_0$ onto $\partial Z_0$. Moreover, our  considerations also show
 that  the statement about orientations is true as stated. 
 \end{proof}



In order to show that $s_2^+$ has no poles in $\inte(U_0)$, 
 we consider the auxiliary function
\begin{equation}\label{eq:gdef2}
g(\tau)\coloneq \frac{1}{s_2^+(\tau)-\tau}=\frac{i\pi}{6} (E_2+E_4^{1/2}).
\end{equation}
This is a holomorphic  function on $\inte(U_0)$ with a continuous extension to (at least) $U_0\setminus\{0,\infty\}$.  

\begin{lem} \label{lemgs2sides} We have $\im(g(\tau))>0$ for $\tau \in \partial U_0\setminus\{0,\infty\}$. 
\end{lem}

\begin{proof}  If $\tau\in \inte(A)$, then 
$\tau=it$ with $t>0$ and  by \eqref{eq:s2+h}
we have 
$s_2^+(it)=ih(t)$ with $0<h(t)<t$. It follows that 
\[
\im (g(\tau))= \im \biggl( \frac{1}{s_2^+(it)-it}\biggr) =\frac1{t-h(t)}>0.
\]

 If $\tau\in \inte(B)$, then $s_2^+(\tau)\in \inte(B')$. In particular, $\im(\tau)>0$ and $\im(s_2^+(\tau))<0$. So $\im (\tau-s_2^+(\tau))>0$ and 
 \[
\im (g(\tau))= \im \biggl(\frac{1}{s_2^+(\tau)-\tau}\biggr)>0,
\]
 because $\im(w)>0$ for $w\in \C$ implies that $\im(-1/w)>0$. 

 Finally, we have seen in the proof of Lemma~\ref{lem:s2homeo}   that $s_2^+(\tau)$  moves monotonically
from $\overline \rho$ to $\infty$ along $C'$ as $\tau$ moves from $\rho$ 
to $\infty$ along $C$. Since  $s_2^+$ has no fixed points in 
$C\setminus\{\infty\}$ 
(see Lemma~\ref{lem:s2fixed}), it follows that there exists a function $k\: [\sqrt3/2, \infty)\ra [-\sqrt3/2, \infty)$ with $k(t)<t$ and 
\[
s_2^+(\tfrac 12+it)=\tfrac 12 +ik(t)
\] for  $t\in  [\sqrt3/2, \infty)$. 
Now if $\tau\in C\setminus\{\infty\}$, then $\tau=\tfrac12+it$ with 
 $t\in  [\sqrt3/2, \infty)$ and so 
\[
\im (g(\tau))=\im \biggl( \frac{1}{s_2^+(\tau)-\tau}\biggr)=\frac{1}{t-k(t)}>0.
\]
The statement follows.
 \end{proof}


\begin{lem} \label{lem:gs2vertex} We have 
\[
\liminf_{\inte(U_0)\ni \tau \to \tau_0} \im(g(\tau))\ge 0
\]
for $\tau_0\in \{0,  \infty\}$
\end{lem}

\begin{proof} The expansion \eqref{eq:s2+ser} shows that 
\[ s_2^+(\tau)-\tau=-\tfrac{3i}{\pi}+o(1) \text{ and so } 
g(\tau)= \frac{1}{s_2^+(\tau)-\tau}=\tfrac{i\pi}{3}+o(1)
\]
as $U_0\ni \tau \to \infty$. 
Hence 
\[
\liminf_{\inte(U_0)\ni \tau \to \infty} \im(g(\tau))=\pi/3\ge 0. 
\]

Now suppose 
$\tau\in \inte(U_0)$ is close to $0$. Then 
$\tau'\coloneq 1/\overline \tau\in  \inte(U_0)$ is close to $\infty$. In particular, $\im(\tau')$ is large and $\re(\tau')$ is uniformly bounded. Moreover,   \eqref{eq:s2-ser} shows that 
\[
s_2^-(\tau')=\tau'+\frac{i}{24\pi}\widehat q^{-1}+O(1),
\]
where $\widehat q=\exp(2\pi i \tau')$. 
Since $|\widehat q^{-1}|=\exp(2\pi \im(\tau'))$ and $\im(\tau')\to +\infty$ as $ \inte(U_0)\ni \tau\to 0$, we have 
\[
\tau'/s_2^-(\tau')\to 0
\]
as $ \inte(U_0)\ni \tau\to 0$. 

Now by \eqref{eq:sbet} we have 
\[
s_2^+(\tau)=1/\overline{s_2^-(\tau')}
\]
and so 
\begin{align*}
\im(g(\tau))&=\im\biggr(\frac{1}{s_2^+(\tau)-\tau}\biggl)=
\im\biggr(\frac{1}{1/\tau'-1/s_2^-(\tau')}\biggl)\\
&=\im\biggr( \frac{\tau'}{1-\tau'/s_2^-(\tau')}\biggl)=\im(\tau'(1+o(1)))\to +\infty
\end{align*}
as $ \inte(U_0)\ni \tau\to 0$ (for the last conclusion it is important that $\re(\tau')$ is uniformly bounded). 
It follows that 
\[
\liminf_{\inte(T_0)\ni \tau \to 0} \im(g(\tau))=+\infty\ge 0.
\]
The proof is complete.
\end{proof}


\begin{lem}  \label{lem:gs2pos}
We have $\im(g(\tau))>0$ for $\tau\in \inte(U_0)$. 
\end{lem}

\begin{proof} By Lemma~\ref{lem:minprincip} it is enough to show that
\[
\liminf_{\inte(U_0)\ni \tau \to \tau_0} \im(g(\tau))\ge 0
\]
for all $\tau_0\in \partial U_0$. This follows from Lemmas \ref{lemgs2sides} and~\ref{lem:gs2vertex}. 
\end{proof}

\begin{lem} \label{lem:s2nopoles} The function $s_2^+$ has no poles in $\inte(U_0)$. 
\end{lem}
\begin{proof} By Lemma~\ref{lem:gs2pos} the function  $g$ has no zeros in $\inte(U_0)$. This implies that $s_2^+$ cannot have poles in $\inte(U_0)$. \end{proof}

 \begin{proof}[Proof of Theorem~\ref{thm:s2}]
 We can apply Proposition~\ref{prop:arg} to $f=s_2^+$, $U=U_0$, and $V=Z_0$  by Lemmas~\ref{lem:s2homeo},  \ref{lem:s2injinfty} and \ref{lem:s2nopoles}. The statement follows.
  \end{proof}




