    \includegraphics[width=0.2\linewidth]{magic-square-matroid.pdf}
    \caption{A rank 3 matroid}
    \label{fig:magic-square-matroid}
\end{figure}


\subsection{Matroid isomorphism structures}
\label{sec:matroid-iso-str}
Two matroids $M$ and $N$ are \textit{isomorphic} if there is a bijection $\varphi\colon \ssets{E}{M} \to E(N)$ such that $A\in \ssets{\pB}{M}$ if and only if $\varphi(A)\in \ssets{\pB}{N}$; such a $\varphi$ is an \textit{isomorphism} of $M$ and $N$. An isomorphism may be characterized in analogous ways for other axiomatic structures of matroids; we formalize this in the following way. 

Denote by $\MatIso$ the class of all matroids and $\Set$ the class of all sets. A \textit{matroid isomorphism structure} on $\MatIso$ is a function $\pS \colon \MatIso \to \Set$ satisfying
\begin{enumerate}
    \item for each matroid $M$ we have $\ssets \pS M \subseteq 2^{\ssets E M}$, and
    \item for each pair of matroids $M$ and $N$,  a function $\varphi \colon \ssets E M \to \ssets E N$ defines an isomorphism $M \to N$ if and only if:
    \begin{equation*}
        A\in \ssets \pS M \quad \text{if and only if} \quad \varphi(A) \in \ssets \pS N.
    \end{equation*}
\end{enumerate}
Examples of matroid isomorphism structures include bases $\ssets \pB M$, nonbases $\ssets \NB M$, independent sets $\ssets \pI M$, circuits $\ssets \pC M$, flats $\ssets \pF M$, and hyperplanes $\ssets \pH M$. 

An \textit{automorphism} of $M$ is an isomorphism of $M$ to itself and the set of all automorphisms of $M$ forms the \textit{automorphism group} of $\Aut(M)$. 

In the following section we define a matroid isomorphism game for each matroid isomorphism structure. In order for the existence of perfect deterministic winning strategies to characterize matroid isomorphism, we need the matroid isomorphism structure $\pS$ to satisfy the following property. 
We say that $\pS$ \textit{covers} the matroid $M$ if for each $p\in \ssets E M$ there is an element $A\in \pS(M)$ such that $p\in A$. As we see in \Cref{prop:matroid+cover}, our frequently used isomorphism structures cover most matroids of interest. 

In order to formulate this proposition, we must review some basic attributes of and operations on matroids. 
Let $M$ be a matroid. A \textit{loop} of  $M$ is an element of $\ssets{E}{M}$ not contained in any basis of $M$. A \textit{coloop} is an element of $\ssets{E}{M}$ contained in every basis of $M$, equivalently, an element not contained in any circuit of $M$. 

The dual of $M$ is the matroid $M^{\vee}$ that has the same ground set as $M$ and 
\begin{equation*}
    \pB(M^{\vee}) = \{A\subseteq \ssets E M \suchthat \ssets E M \setminus A \in \ssets \pB M\}.
\end{equation*}
Given $A\subset \ssets E M$, the \textit{restriction} $M|A$ is the matroid on $X$ whose independent sets are the independent sets of $M$ contained in $A$. The \textit{deletion} $M\setminus A$ is the restriction of $M$ to $\ssets E M \setminus A$. The contraction $M/A$ of $M$ by $A$ is the dual of  $(M^{\vee})|A$. 


Given $e\notin \ssets{E}{M}$, the \textit{free extension} of $M$ by $e$ is the matroid $M + e$ whose ground set is $\ssets{E}{M + e} = \ssets{E}{M} \sqcup \{e\}$, and 
\begin{equation}
\label{eq:bases-free-ext}
    \ssets{\pB}{M+e} = \ssets{\pB}{M} \cup \left\{A\cup \{e\} \suchthat A\in \ssets{\pI}{M},\ |A| = \rk(M)-1 \right\}. 
\end{equation}

The matroid $M$ is \textit{paving} if each circuit of $M$ has size at least $\rk(M)$. 

Given two matroids $M$ and $N$, their \textit{direct sum} is the matroid $M\oplus N$ with
\begin{equation*}
    \ssets{E}{M \oplus N} = \ssets E M \sqcup \ssets E N, \quad \ssets{\pB}{M \oplus N} = \{A\cup B \suchthat A\in \ssets \pB M, B\in \ssets \pB N\}.
\end{equation*}
A matroid is \textit{connected} if it is not the direct sum of two matroids. 

\begin{proposition}
\label{prop:matroid+cover}
    Let $M$ be a matroid of rank $r$ whose ground set has $n$ elements. 
    \begin{enumerate}
        \item The set of bases $\ssets \pB M$ covers $M$ if and only if  $M$ has no loops. 
        \item The set of circuits $\pC(M)$ covers $M$ if and only if $M$ has no coloops. 
        \item The set of nonbases $\NB(M)$ covers $M$ if and only if $M$ is not a free extension of a paving matroid or $M$ does not split as a direct sum of the form $U(1,1) \oplus U(r-1,n-1)$.  
        \item The set of flats $\pF(M)$ and the set of hyperplanes $\pH(M)$ each cover the matroid $M$ unconditionally. 
    \end{enumerate}
\end{proposition}

\begin{proof}
    Statements (1), (2) and (4) are clear. Consider (3).  Suppose $M = N + e$ where $N$ is a paving matroid of rank $r$. This means that every $(r-1)$--element subset of $\ssets E N$ is an independent set of $N$. So every $r$-element subset of $\ssets E M$ containing $e$ is a basis by the characterization of free extension provided in \Cref{eq:bases-free-ext}.
    If $M \cong U(1,\{e\}) \oplus U(r-1, n-1)$, then every $r$-element subset containing $e$ is a basis of $M$. In either case, $\ssets \NB M$ does not cover $M$.

    Conversely, suppose $e\in \ssets E M$ is not contained in a nonbasis of $M$. In particular, every $(r-1)$--element subset of $\ssets E M \setminus \{e\}$ is independent. Let $N = M \setminus e$.
    If $\rk(N) = r-1$, then $e$ is a coloop of $M$ and every $(r-1)$--subset of $\ssets E N$ is a basis. Therefore $M \cong U(1,\{e\}) \oplus U(r-1,n-1)$. Now suppose that $\rk(N) = r$. Since every $(r-1)$--element subset of $\ssets E N$ is independent, we see that $N$ is a paving matroid. The identification of $M$ with $N + e$ may be seen using the basis characterization of free extension in  Equation \eqref{eq:bases-free-ext}.
\end{proof}







\section{Matroid isomorphism games and their strategies}
We begin this section with a brief review of nonlocal games and their properties. We also describe deterministic and quantum commuting strategies. Then we define the $(M,N,\pS)$--matroid isomorphism game for each pair of matroids $(M,N)$ and isomorphism structure $\pS$ that covers $M$ and $N$. We then show that $M$ and $N$ are isomorphic if and only if this game has a perfect deterministic strategy, and we give a criterion for perfect quantum commuting strategies to exist. The latter is useful in \S\ref{sec:algebra} where we describe a purely algebraic criterion for the existence of perfect quantum commuting strategies. 
\subsection{Reminders on non-local games}
\label{sec:non-local-games}
A standard reference for nonlocal games is \cite{CleveHoyerTonerWatrous}.
Our non-local games are played between two cooperating players Alice and Bob together with a referee. Alice and Bob each have their own input sets $X_{A}$ and $X_{B}$, respectively, and their own output sets $Y_{A}$ and $Y_{B}$, respectively. We assume that all of these sets are finite. Let $V \colon X_{A}\times X_{B} \times Y_{A} \times Y_B \to \{0,1\}$ be a predicate.
We write the value of $V$ on the tuple $(a,b,x,y)\in  X_{A}\times X_{B} \times Y_{A} \times Y_B$ by $\pred{a}{b}{x}{y}$.  
The rules of the non-local game $\pG = \pG(X_{A}, X_{B}, Y_{A}, Y_{B}, V)$ are as follows. 
The referee chooses at random (for us, the distribution will always be uniform) a pair of questions $(a,b)$ in $X_{A}\times X_{B}$. Alice responds with an answer $x \in Y_{A}$ and Bob responds with an answer $y \in Y_{B}$.  Alice and Bob win if $\pred{a}{b}{x}{y} = 1$; otherwise they lose. While Alice and Bob are not allowed to communicate during the game, they may strategize beforehand. 

The non-local game $\pG$ is \textit{synchronous} if $X_{A} = X_{B} = X$, $Y_{A} = Y_{B} = Y$, and $\pred{a}{a}{x}{y} = 0$ whenever $x\neq y$.  As defined in \cite{PaulsenRahaman}, $\pG$ is  \textit{bisynchronous} if it is synchronous and in addition $\pred{a}{b}{x}{x} = 0$ whenever $a\neq b$. 

A \textit{deterministic strategy} for $\pG$ consists of a pair of functions $f \colon X_{A} \to Y_{A}$ and $g \colon X_{B} \to Y_{B}$ such that $x = f(a)$ and $y = g(b)$. That is, Alice and Bob's responses are functions of their inputs. Such a strategy is \textit{perfect} if it guarantees victory, i.e., $\pred{a}{b}{f(a)}{g(b)} = 1$ for all $a\in X_{A}$ and $b \in X_{B}$.  If the game $\pG$ is synchronous, then $f = g$ holds in a perfect deterministic strategy. 

More generally, a classical strategy allows for Alice and Bob to exploit shared randomness in order to increase their chances of winning. When the input sets are finite (which is always the case in this paper), the existence of a perfect classical strategy ensures the existence of a perfect deterministic strategy. 

There are several different formulations of quantum strategies, and our focus is on the quantum commuting variation, see \cite[\S~2]{AtseriasEtAl} or \cite{PaulsenSeveriniStahlkeTodorovWinter}. 
We formulate this in the language of positive operator-valued measurements. 
Let $H$ be a complex Hilbert space. A \textit{positive operator-valued measurement}, POVM for short, consists of a \textit{finite} family $\pF = (F_{x})_{x\in X}$ of Hermitian positive semidefinite linear operators $F_x$ on $H$ such that 
\begin{equation*}
    \sum_{x\in X} F_x = I_{H}
\end{equation*}
where $I_{H}$ denotes the identity on $H$. They are called \textit{projective measurements}, or PVM's, if all operators $F_x$ in the POVM are projective, i.e., $F_x=F_x^*=F_x^2$.

A \textit{quantum commuting strategy} for the non-local game $\pG$ may consists of the following:
\begin{itemize}
    \item a complex Hilbert space $H$;
    \item a unit vector $\psi\in H$;
    \item families of POVMs $(\pE_{x})_{x\in Y_{A}}$ and $(\pF_{y})_{y\in Y_{B}}$  on $H$ for Alice and Bob, respectively;
    \item write $\pE_{x} = (E_{ax})_{a\in X_{A}}$ and $\pF_{y} = (F_{by})_{b\in X_{B}}$.  We require that each pair of operators $E_{ax}$ and $F_{by}$ commute.
\end{itemize}  
The probability of Alice and Bob answering with $x$ and $y$ on the input $a$ and $b$ is
\begin{equation*}
    p(x, y | a, b) = 
    \psi^{*}(E_{ax} F_{by}) \psi.
\end{equation*}


\subsection{The game}
Fix matroids $M$ and $N$ and an isomorphism structure $\pS$ that covers $M$ and $N$.
Given a matroid isomorphism structure $\pS$, define
\begin{equation*}
    \pS_{\bullet}(M) = \{(S, p) \suchthat S \in \ssets \pS M, \ p\in A \}.
\end{equation*}
Throughout, pointed sets will be denoted by lowercase bold letters. 
Given a pointed set $\fa = (S, p)$, we write $S_{\fa}$ for $S$ and $p_{\fa}$ for $p$. 


To define an isomorphism game, we need a way to score the players' answers. To that end, define the map $\rel_{\pS(M)} : \pS_{\bullet}(M) \times \pS_{\bullet}(M)  \to \{0,1,2,3\}$ by
  \begin{equation*}
    \rel_{\ssets \pS M}(\fa , \fb) = \begin{cases}
      0 & \text{if } S_{\fa} = S_{\fb} \text{ and } p_{\fa} = p_{\fb} \\
      1 & \text{if } S_{\fa} \neq S_{\fb} \text{ and } p_{\fa} = p_{\fb} \\
      2 & \text{if } S_{\fa} = S_{\fb} \text{ and } p_{\fa} \neq p_{\fb} \\
      3 & \text{if }  S_{\fa} \neq S_{\fb} \text{ and } p_{\fa} \neq p_{\fb}
    \end{cases}
  \end{equation*}
To illustrate this relation, we associate to the pair $(M,\pS)$ an edge colored graph.

\begin{definition}
\label{def:relation+colored+graph}
The \textit{relation colored graph} of the pair $(M,\pS)$ is the graph $\Grel(M,\pS)$ whose vertex set is $\psSets M$, and edge set
\begin{equation*}
    E(\Grel(M,\pS)) = \left\{  \{\fa,\fb\} \suchthat \rel_{\pS(M)}(\fa,\fb) \in \{1, 2\} \right\}.
\end{equation*}
The color of the edge $\{\fa,\fb\}$ is $\rel_{\ssets \pS M}(\fa , \fb)$.
\end{definition}

\begin{remark}
There are other natural graphs associated to a matroid $M$ and matroid isomorphism structure $\pS$.  Consider the bipartite graph $\Gbip(M,\pS)$ with vertices $V = \ssets E M \cup \sSets M $ and edges 
    \[
      E = \{ \{a, A\} \suchthat A \in \sSets M, a \in A\}.
    \]
Then, the line graph $\Gline(M,\pS)$ of $\Gbip(M,\pS)$, i.e., the graph with vertices $E(\Gbip(M,\pS))$ and edges
    \[
      E = \{(\{A,a\},\{B,b\}) \suchthat A = B \text{ or } a=b,\ \text{ but not both}\}
    \]
is the uncolored version of the graph $\Grel(M,\pS)$ defined above.
\end{remark}

