The $(M,N,\pS)$--\textit{matroid isomorphism game} is a two-player cooperative nonlocal game defined in the following way. 
The input and output set for both Alice and Bob is $\pS_{\bullet}(M) \sqcup \pS_{\bullet}(N)$. The referee chooses uniformly at random elements $\fa$ and $\fb$ of $\pS_{\bullet}(M) \sqcup \pS_{\bullet}(N)$ to give to Alice and Bob, respectively. Alice returns $\fx$ and Bob returns $\fy$, both in $\pS_{\bullet}(M) \sqcup \pS_{\bullet}(N)$. Alice and Bob win, i.e., $V(\fx, \fy | \fa, \fb) = 1$, if the following two conditions are met. 
The first condition is that $\fa \in \pS_{\bullet}(M)$ if and only if $\fx \in \pS_{\bullet}(N)$ and $\fb \in \pS_{\bullet}(M)$ if and only if $\fy \in \pS_{\bullet}(N)$, i.e., the players have to answer with a pointed set of the matroid they did not receive an input from. Provided this condition  is met,  Suppose $\{\fc, \fv \} =  \{\fa, \fx\}$ where  $\fc \in \pS_{\bullet}(M)$ and $\fv \in \pS_{\bullet}(N)$ and let $\{ \fd, \fw \} = \{\fb, \fy\}$ be defined in a similar way. The second condition is 
\begin{equation*}
    \rel_{\ssets \pS M}(\fc, \fd) = \rel_{\ssets \pS N}(\fv , \fw).
\end{equation*}


\begin{remark}
\label{rmk:colored+graph+iso}
Note that the $(M,N,\pS)$-matroid isomorphism game is the same as the colored graph isomorphism game, as defined in \cite{robersonschmidt}, of the relation colored graphs $\Grel(M,\pS)$ and $\Grel(N,\pS)$. Therefore, one could use this connection to obtain our next results from known facts about graph isomorphism games \textit{and} how the colored graph isomorphisms are related to matroid isomorphisms. In this section, our approach is to directly work with matroid isomorphisms and their interplay with strategies for the matroid isomorphism game. We make use of the relation colored graphs in \Cref{sec:disj-aut}.   
\end{remark}


\begin{proposition}\label{prop:matroid+bisynchronous}
    The $(M, N, \pS)$--matroid isomorphism game is bisynchronous.
\end{proposition}
\begin{proof}
Suppose both Alice and Bob receive $\fa$, and assume  without loss of generality that $\fa\in \pssets \pS M$. If Alice and Bob return $\fx, \fy \in \pssets \pS N$ (respectively) with $\fx \neq \fy$, then $\rel_{\pS(M)}(\fa, \fa) = 0$ and $\rel_{\pS(N)}(\fx,\fy) \neq 0$. This shows that the game is synchronous and a similar argument shows that this game is bisynchronous. 
\end{proof}

Because this game is synchronous, a perfect classical deterministic strategy is defined by a single function used by both Alice and Bob. 
Suppose $\varphi\colon M \to N$ is an isomorphism with inverse $\psi\colon N \to M$. One particular perfect deterministic strategy is  given by the function 
\begin{equation*}
    \Phi\colon \pssets \pS M  \sqcup \pssets \pS N \to \pssets \pS M \sqcup \pssets \pS N
\end{equation*}
where $\Phi(\fa) = (\varphi(S_{\fa}), \varphi(p_{\fa}))$ if $\fa \in \psSets M$ or $\Phi(\fa) = (\psi(S_{\fa}), \psi(p_{\fa}))$ if $\fa \in \psSets N$. Such a perfect deterministic strategy is said to be \textit{induced} by a matroid isomorphism. 

\begin{theorem}
\label{thm:iso-iff-classical}
	Suppose $M$ and $N$ are matroids and $\pS$ is a matroid isomorphism structure that covers $M$ and $N$. Every perfect deterministic strategy of the $(M, N, \pS)$--matroid isomorphism game is induced by a matroid isomorphism. 
    In particular, $M$ and $N$ are isomorphic if and only if the $(M, N, \pS)$--matroid isomorphism game has a perfect deterministic strategy.
\end{theorem}

\noindent First, we collect some properties of a perfect deterministic strategy in the following lemma. 

\begin{lemma}
\label{lem:perfect-classical}
Suppose $\Phi\colon \pssets{\pS}{M} \sqcup \pssets{\pS}{N} \to  \pssets{\pS}{M} \sqcup \pssets{\pS}{N}$ defines a perfect deterministic strategy. We have the following. 
\begin{enumerate}
\item The restriction of $\Phi$ to $\pssets \pS M$ is a function $\Theta \colon \pssets{\pS}{M} \to \pssets{\pS}{N}$ and the restriction of $\Phi$ to $\pssets \pS N$ is a function $\Xi \colon \pssets{\pS}{N} \to \pssets{\pS}{M}$. Furthermore, $\Theta$ and $\Xi$ are inverses of each other. 
\item There are functions $\vartheta \colon \ssets E M \to E(N)$ and $\xi \colon E(N) \to \ssets E M$ that make the following diagrams commute:
\begin{equation*}
\begin{tikzcd}
 \psSets M \arrow{r}{\Theta} \arrow{d}{} & \psSets N \arrow{d}{} \\%
\ssets{E}{M} \arrow{r}{\vartheta}& \ssets{E}{N}
\end{tikzcd} 
\quad \text{and} \quad
\begin{tikzcd}
 \psSets N \arrow{r}{\Xi} \arrow{d}{} & \psSets M \arrow{d}{} \\%
\ssets{E}{N} \arrow{r}{\xi}& \ssets{E}{M}
\end{tikzcd} 
\end{equation*}
The vertical arrows in the above diagram are defined by sending $\fa$ to $p_{\fa}$. Furthermore, $\vartheta$ and $\xi$ are inverses of each other. 
\end{enumerate}
\end{lemma}

\begin{proof}
    Consider (1). In a perfect deterministic strategy, Alice must return an element of $\pssets \pS N$ if and only if she receives an element of $\pssets \pS M$, and similarly for Bob. This proves that the restricted functions $\Theta$ and $\Xi$ are well defined. Next, we have
    \begin{equation*}
        \rel_{\pS(M)}(\Xi(\Theta(\fa)), \fa) = \rel_{\pS(N)}(\Theta(\fa), \Theta(\fa)) = 0
    \end{equation*}
    and so $\Xi \circ \Theta$ is the identity. Similarly, we have that $\Theta \circ \Xi$ is also the identity, and hence $\Theta$ and $\Xi$ are inverses of each other. 

    Now consider (2). Suppose $\fa$ and $\fb$ are in $\pssets \pS M$ such that $p_{\fa} = p_{\fb}$, $\Theta(\fa) = \fx$, and $\Theta(\fb) = \fy$. Since 
\begin{equation}
\label{eq:abxy}
     \rel_{\ssets \pS M}(\fa, \fb) = \rel_{\ssets \pS N}(\fx, \fy)
\end{equation}
and $\rel(\fa, \fb) \in \{0,1\}$,  we must also have $\rel(\fx, \fy) \in \{0,1\}$. Therefore $p_{\fx} = p_{\fy}$. Together with the fact that $\pS$ covers $M$, we have a well defined function $\vartheta$ that makes the above diagram commute. We have in a similar way the function $\xi$. 

Next we claim that $\vartheta$ and $\xi$ are inverses of each other. Let $p\in \ssets E M$ and $q=\vartheta(p)$.  Given $\fa \in \pssets{\pS}{M}$ and $\fy \in \pssets{\pS}{N}$ with $p_{\fa} = p$ and $p_{\fy} = q$, we have $\Theta(\fa) = \fx$ and $\Xi(\fy) = \fb$ with $p_{\fx} = \vartheta(p)$ and $p_{\fb} = \xi(q)$. We have the same equality as in Equation \eqref{eq:abxy}
and it's value is $0$ or $1$ since $\vartheta(p) = q$. So $p = (\xi\circ \vartheta)(q)$, i.e., $\xi\circ \vartheta$ is the identity. A similar argument shows that $\vartheta \circ \xi$ is also the identity, so $\vartheta$ and $\xi$ are inverses of each other. 
\end{proof}

\begin{proof}[Proof of \Cref{thm:iso-iff-classical}]
Suppose a perfect deterministic strategy exists.  
By  \Cref{lem:perfect-classical}(1), this defines a pair of functions $\Theta \colon \pssets \pS M \to \pssets \pS N$ and $\Xi \colon \pssets \pS N \to \pssets \pS M$ that are inverses to each other. Let  $\vartheta$ and $\xi$ be the functions defined in part (2) of that lemma. These functions satisfy $\Theta(\fa) = \fx$ and $\Xi(\fy) = \fb$ where $p_{\fx} = \vartheta(p_{\fa})$ and $p_{\fb} = \xi(p_{\fy})$.  We must show that  $\vartheta$ is an isomorphism, i.e., that $A \in \pS(M)$ if and only if $ \vartheta(A) \in \pS(N)$. Suppose $A = \{s_1, \ldots, s_k\} \in \ssets{\pS}{M}$, and denote by $\fa_i = (A, s_i)$.  Set
\begin{equation*}
    \fx_i = \Theta(\fa_i), \quad \text{for} \quad 1\leq i \leq k.
\end{equation*}  
For $j\geq 2$, we have that $\rel(\fa_1, \fa_j) = 2$, and hence $\rel(\fx_{1}, \fx_{j}) = 2$. So the $S_{\fx_j}$'s are all equal to each other; call this set $X$. Because $t_{i}=\vartheta(s_i)$, we see that $X$ contains $\vartheta(A)$. 

Suppose $X$ properly contains $\vartheta(A)$, say  $X=\{t_1, \ldots, t_k, t_{k+1}, \ldots, t_{\ell}\}$ where  $\ell > k$. Set $\fy_{i} = (X,t_i)$ and $\fb_i =  \Xi(\fx_i)$ for $k+1 < i \leq \ell$. Because $\xi$ is injective, we have that $\xi(t_i) \notin A$, and so $A\neq S_{y_{k+1}}$. But $\rel_{\ssets \pS N}(\fx_{k}, \fy_{k+1}) = 2$ implies that $\rel_{\ssets \pS M}(\fa_k, \fb_{k+1}) = 2$, so $A = S_{\fy_{k+1}}$, which is a contradiction. This proves that $X=\vartheta(A)$.  A similar argument applied to $\xi$ shows that if $\vartheta(A) \in \ssets \pS N$ then $A\in \ssets \pS M$. 
\end{proof}

\begin{corollary}
\label{cor:induced+iso}
    If $\Theta \colon \psSets M \to \psSets N$ is a bijection satisfying 
    \begin{equation*}
        \rel_{\pS(M)}(\fa, \fb) = \rel_{\pS(N)}(\Theta(\fa), \Theta(\fb))
    \end{equation*}
    for all $\fa,\fb\in \psSets M$, then $\Theta$ is induced by a matroid isomorphism $M \to N$.
\end{corollary}

\begin{proof}
        The function $\Theta \sqcup \Theta^{-1} \colon \psSets M \sqcup \psSets N \to \psSets M \sqcup \psSets N$ defines a perfect deterministic strategy for the $(M,N,\pS)$--matroid isomorphism game. By \Cref{thm:iso-iff-classical}, this strategy must be induced by a matroid isomorphism $\varphi \colon M \to N$. 
\end{proof}

\subsection{Perfect quantum strategies for the matroid isomorphism game} 
As before, let $M$ and $N$ be two matroids and let $\pS$ be an isomorphism structure that covers $M$ and $N$.  With  \Cref{thm:iso-iff-classical} in mind, we say that $M$ and $N$ are $\pS$-\textit{quantum isomorphic} if the $(M,N,\pS)$--isomorphism game has a perfect quantum commuting strategy. In this subsection, we give a characterization of $\pS$-quantum isomorphic matroids that we use in \S\ref{sec:algebra}.
First, we review the following general fact about synchronous nonlocal games, see \cite[Cor.~5.6]{PaulsenSeveriniStahlkeTodorovWinter}.

\begin{lemma}\label{lem:synchronous}
Let $\pG$ be a synchronous nonlocal game with both input sets equal to $X$ and both output sets equal to $Y$. There exists a perfect quantum commuting strategy if and only if there is a $C^*$-algebra $A$, PVM's $(F_{ax})_{x\in Y} \subseteq A$ for all $a\in  X$, and a faithful tracial state $\tau \colon A\to \C$ such that
\begin{align}\label{eq:synch}
    \tau(F_{ax} F_{by}) = 0 \quad \text{if} \quad \pred{a}{b}{x}{y} = 0.
\end{align}
\end{lemma}

We have the following characterization of when the $(M,N,\pS)$--isomorphism game has a perfect quantum strategy. The statement and its proof are similar to \cite[Thm 5.4/5.13]{AtseriasEtAl}.

\begin{theorem}\label{thm:perfectstrat}
The $(M,N,\pS)$--isomorphism game has a perfect quantum commuting strategy if and only if there is a $C^*$-algebra $A$, projections $F_{\fa\fx} \in A$ for $\fa\in \psSets M$ and $\fx \in \psSets N$, and a faithful tracial state $\tau \colon A\to \C$ such that 
\begin{enumerate}
        \item $\sum_{\ft \in \psSets N} F_{\fa \ft} = 1$ for each $\fa \in \psSets M$, 
        \item $\sum_{\fs \in \psSets M} F_{\fs \fx} = 1$ for each $\fx \in \psSets N$, 
        \item $F_{\fa \fx} F_{\fb \fy} = 0$ if $\rel_{\pS(M)}(\fa, \fb) \neq \rel_{\pS(N)}(\fx, \fy)$,
    \end{enumerate}
    and $p(\fx, \fy | \fa, \fb) = \tau(F_{\fa\fx} F_{\fb\fy})$.
\end{theorem}

\begin{proof}
Recall that for the $(M,N,\pS)$--isomorphism game we have $X=Y=\pS_{\bullet}(M) \sqcup \pS_{\bullet}(N)$ and consider the PVM's $(F_{\fa\fx})_{\fx\in Y}$ obtained from \Cref{lem:synchronous}. We get that (3) is immediate, since $\tau$ is faithful. For (1), consider the case $\fa, \fx\in \psSets M$ and recall that the players always lose if one of them answers with a ground set element of the same matroid the player got a question from. Therefore
\begin{align*}
    \tau(F_{\fa\fx})=\tau(F_{\fa\fx}\sum_\fy F_{\fb\fy})=\sum_\fy \tau(F_{\fa\fx}F_{\fb\fy})=0
\end{align*}
by \Cref{eq:synch}, which yields $F_{\fa\fx}=0$ since $\tau$ is faithful. This shows (1), because 
\begin{equation*}
\sum_{\ft\in \psSets N} F_{\fa \ft}=\sum_{\ft\in Y} F_{\fa \ft}= 1
\end{equation*}
for each $\fa \in \psSets M$.

It remains to show (2) for the first direction. Note that $F_{\fa\fx}F_{\fx\fa'}=0$ for $\fa\neq \fa'$ since $V(\fx,\fa,\fa',\fx)=0$ in the matroid isomorphism game. Therefore
\begin{align*}
    F_{\fa\fx}=F_{\fa\fx}\sum_{\fa'}F_{\fx\fa'}=F_{\fa\fx}F_{\fx\fa}=\sum_{\tilde \fa}F_{\tilde{\fa}\fx}F_{\fx\fa}=F_{\fx\fa}.
\end{align*}
We deduce $\sum_{\fs\in \psSets M} F_{\fs \fx}=\sum_{\fs\in \psSets M} F_{\fx\fs}=\sum_{\fs\in Y} F_{\fx\fs}= 1$ for $\fx \in \psSets N$, where we also use $F_{\fx\fs}=0$ for $\fs\in \psSets N$. This shows (2).

For the other direction, suppose we have projections and a tracial state as in the theorem statement. Define $F_{\fa\fx}=F_{\fx\fa}$ and let $F_{\fa\fx}=0$ for $\fa, \fx\in \psSets M$ and $\fa, \fx\in \psSets N$. It is easy to see that $(F_{\fa\fx})_{\fx\in Y}$ are PVM's and (3) yields \Cref{eq:synch}. This completes the proof. 
\end{proof}

\begin{remark}
In a $C^*$-algebra $A$, projections $(P_x)_x\subseteq A$ such that $\sum_xP_x=1$ always fulfill the relation $P_xP_{y}=0$ for all $x \neq y$. Note that this is in general not true in a $\ast$-algebra, which is why we have the additional relations $P_xP_{y}=0$ for $x\neq y$. 
\end{remark}

\section{Nonisomorphic matroids that are quantum isomorphic}
\label{sec:quantum-iso-matroids}
We produce a pair of matroids that are quantum isomorphic but not isomorphic. This pair of matroids are defined on a ground set with 18 elements and have rank 3. More generally, we describe how to obtain a matroid from a special type of binary constraint system. 

\subsection{Matroids and binary constraint systems}
\label{sec:matroids+BCS}
A \textit{linear binary constraint system (LBCS)}, as defined in \cite{CleveLiuSlofstra, CleveMittal}, consists of a pair $(\pV, \pE)$  where $\pV$ is a set of $m$ binary-valued variables and $\pE$ is a set of $n$ linear equations in these variables with binary coefficients. The most famous examples come from the Mermin--Peres magic square \cite{Mermin}, which consists of the $m=9$ variables $x_1,\ldots, x_9$ and the $n=6$ equations
\begin{align}\label{magicsquare}
\begin{array}{ccc}
     x_1 x_2 x_3 = s_1,  &
     x_4 x_5 x_6 = s_2,  &
     x_7 x_8 x_9 = s_3, \\
     x_1 x_4 x_7 = s_4,  &
     x_2 x_5 x_8 = s_5,  &
     x_7 x_6 x_9 = s_6
\end{array} 
\end{align}
where each $s_i$ is $1$ or $-1$. (We write the linear equations multiplicatively so that we may use $\{-1,1\}$--valued variables instead of $\{0,1\}$--valued variables.)

First, given a matroid $M$, let us describe how to obtain a LBCS. Our prototype for this procedure is given by the way one obtains the magic square game from the matroid in \Cref{ex:magic-square-matroid}. The variables of the magic square game correspond to the ground set elements of this matroid and the equations correspond to the nonbases of this matroid. Actually, we find it more convenient to view the nonbases of this matroid as special kinds of hyperplanes of a matroid, i.e., cyclic hyperplanes, which we now describe. 

Recall from \S \ref{sec:matroids} that a hyperplane of $M$ is a flat of rank $\rk(M) - 1$ and the set of all hyperplanes is denoted by $\pH(M)$. A \textit{cyclic flat} is a flat that is a union of circuits, and a \textit{cyclic hyperplane} is a hyperplane that is also a cyclic flat. Denote by $\pZ(M)$ the set of cyclic flats of $M$ and $\pZ^{k}(M)$ the set of cyclic flats that have rank $\rk(M) - k$. In particular, $\pZ^{1}(M)$ consists of the set of cyclic hyperplanes of $M$. 

Similar to the collection of flats, the collection of cyclic flats forms a lattice. Given two cyclic flats $X$ and $Y$, their \textit{join} is $X\vee Y = \cl_{M}(X\cup Y)$ and their \textit{meet}, denoted by $X\wedge Y$, the union of all circuits contained in $X\cap Y$.
The lattice of cyclic flats, together with the restriction of the rank function to $\pZ(M)$, completely determine $M$. This leads to the following axiomatic characterization of matroids as formulated in \cite[Thm 3.2]{BonindeMier}.

\begin{theorem}
\label{thm:cyclic-flat-axioms}
    Let $E$ be a finite set,  $\pZ\subset 2^{E}$ a lattice (under inclusion), and $r\colon \pZ \to \N_{0}$ a function. There is a matroid $M$ whose cyclic flats are $\pZ$ and whose rank function restricted to $\pZ$ is $r$ if and only if
    \begin{enumerate}
        \item $r(0_{\pZ}) = 0$,
        \item $0 < r(Y) - r(X) < |Y\setminus X|$ for each pair $X,Y \in \pZ(M)$ with $X\subsetneq Y$, and
        \item $r(X) + r(Y) \geq r(X \vee Y) + r(X \wedge Y) + |(X\cap Y) \setminus (X\wedge Y)|$ for all $X,Y\in \pZ$. 
    \end{enumerate}
\end{theorem}

Fix a collection $S = \left( s_{H} \suchthat H\in \cZ(M) \right)$ in $\{\pm 1\}^{\cZ^{1}(M)}$.  
We associate to $(M,S)$ a LBCS $(\pV, \pE)$ by setting  
\begin{equation*}
	\pV =  \{x_a \suchthat a\in \ssets E M\}, \quad \text{and} \quad \pE = \left\{ \prod_{a\in H} x_a = s_{H} \suchthat H\in \cZ^{1}(M) \right\}.
\end{equation*}

Next, we describe how to obtain a new matroid from a LBCS obtained from this matroid $M$. Our construction requires that $M$ is a rank $3$ sparse paving matroid. A matroid is \textit{sparse paving} if both the matroid and its dual are paving matroids (recall that a matroid is paving if the size of each circuit is at least the rank of the matroid). The following proposition gives a clear description of rank 3 sparse paving matroids. For this, we need the definition of a \textit{simple} matroid, which is a matroid $M$ that has no loops and such that every subset $A$ that has rank 1 is a singleton set. 

\begin{proposition}
\label{prop:sparse-paving}
	If $M$ is a rank $3$ matroid, then $M$ is sparse paving if and only if 
	  $M$ is simple and each cyclic hyperplane of $M$ has exactly $3$ elements. 
\end{proposition}

\begin{proof}
We use the following fact from \cite[Prop.~2.1.6]{Oxley}: a subset $H\subseteq \ssets E M$ is a hyperplane of $M$ if and only if $\ssets E M \setminus H$ is a circuit of $M^{\vee}$. 

Suppose $M$ is sparse paving. 
Because $M$ is paving, every subset of size at most $2$ is independent; in particular $M$ is a simple matroid. 
Let $H\in \cZ^{1}(M)$. Since $H$ contains a circuit, it must have at least $3$ elements.  
By the fact stated above, $C = \ssets E M \setminus H$ is a circuit of $M^{\vee}$. Furthermore, $C$ has $|\ssets E M|-|H| \leq |\ssets E M|-3$ elements. 
As $M^{\vee}$ is also paving and has rank $|\ssets E M|-3$, we have $|C| \geq |\ssets E M| - 3$. 
So $C = |\ssets E M| - 3$, and hence $|H| = 3$. 

Conversely, suppose that $M$ is simple and each cyclic hyperplane of $M$ has exactly 3 elements. Because $M$ is simple and its rank is $3$, it is paving. If $C$ is a circuit of $M^{\vee}$, then $H = \ssets E M \setminus C$ is a hyperplane of $M$. By hypothesis, $H$ has either $2$ or $3$ elements. This implies that $|C| \geq |\ssets E M| - 3$. Because the rank of $M^{\vee}$ is $|\ssets E M| - 3$, we see that $M^{\vee}$ is paving. 
\end{proof}

We define a new matroid $M_{S}$ from this data by describing its cyclic flats. The ground set of $M_{S}$ is 
\begin{equation*}
	E(M_{S}) = \ssets E M \times \{\pm 1\}. 
\end{equation*} 



Let $\pi\colon E(M_{S}) \to \ssets E M$ be the projection to the variable $\pi(a,s) = a$. 
Set $\pZ(M_{S}) = \{ \emptyset, E(M_{S}) \} \cup \pZ^{1}(M_{S})$ where
\begin{equation*}
    \pZ^{1}(M_{S}) = \left\{ K \subset E(M_{S}) \suchthat |\pi(K)| = |K|,\, \pi(K) \in \pZ^{1}(M),\, \text{ and }  \prod_{(a,s)\in K} s = s_{\pi(K)} \right\}.
\end{equation*}
Define $r\colon \pZ(M_{S}) \to \N_{0}$ by 
\begin{equation*}
    r(X) = 
    \begin{cases}
    0 & \text{ if } X = \emptyset, \\
    2 & \text{ if } X\in \pZ^{1}(M_{S}),  \\
    3 & \text{ if } X = E(M_{S}).
    \end{cases}
\end{equation*}
We view $\pZ(M_{S})$ as a lattice whose join and meet operations are
    \begin{equation*}
        X \vee Y = 
        \begin{cases}
        X & \text{ if } Y\subset X, \\
        Y & \text{ if } X\subset Y, \\
        E(M_{S}) & \text{otherwise},
        \end{cases}
        \qquad \text{and} \qquad
        X\wedge Y = 
        \begin{cases}
        X & \text{ if } X\subset Y, \\
        Y & \text{ if } Y\subset X, \\
        \emptyset & \text{otherwise}.
        \end{cases}
    \end{equation*}
\begin{theorem}
\label{thm:matroid-from-BCS}
	The lattice $\pZ(M_{S})$ and the function $r \colon \pZ(M_{S}) \to \N_{0}$ define a matroid $M_{S}$ as in  \Cref{thm:cyclic-flat-axioms}. 
\end{theorem}

\begin{proof}
This is a straightforward verification using \Cref{thm:cyclic-flat-axioms}. The most interesting case is the verification of the inequality in (3) for $X, Y\in \pZ^{1}(M_{S})$ with $X\neq Y$. In this case, $r(X) = r(Y) = 2$,  $r(X \vee Y) = 3$ and $r(X \wedge Y)=0$. Furthermore, $|X\cap Y|\leq 1$ because if $X\cap Y$ have 2 elements in common, they must be equal (this uses in an essential way the fact that each cyclic hyperplane of $M$ has exactly 3 elements). These sets satisfy the inequality in  (3), as required. 
\end{proof}

\subsection{Linear binary constraint system games}
\label{sec:LBCS+game}
As defined in \cite{CleveMittal}, one can associate a nonlocal game to every binary constraint system $(\pV, \pE)$. The game is played as follows (note that our game is a synchronous version of the games in \cite{CleveMittal}). The referee sends Alice and Bob equations $H_A$ and $H_B$ from the set $\pE$, respectively. They answer with $\{-1,1\}$--assignments to all variables in $H_A$ and $H_B$. They win the game if
\begin{itemize}
    \item[(i)] Their assignments are solutions to their equations,
    \item[(ii)] Their assignments agree on all variables that appear in both equations.
\end{itemize}

\noindent It is well-known \cite{Mermin}, that the nonlocal game associated to the magic square has a perfect quantum strategy, but no perfect classical strategy if $s_i=-1$ for an odd number of $i$ in \Cref{magicsquare}.


\subsection{Examples of quantum isomorphic matroids}

Let $M$ be a rank 3 sparse-paving matroid, $S = \left( s_{H} \suchthat H\in \cZ(M) \right)$ in $\{\pm 1\}^{\cZ^{1}(M)}$, and let $M_{S}$ be the matroid defined in \S~\ref{sec:matroids+BCS}. As a consequence of \Cref{prop:sparse-paving}, we have $\cZ^{1}(M) = \NB(M)$. So the set of nonbases of $M_{S}$ is given by
\begin{align*}
    \NB(M_{S}) = \left\{ \{(x_a,t_a), (x_b, t_b), (x_c, t_c)\} \suchthat \{x_a,x_b,x_c\}\in \NB(M),\ t_i\in\{\pm1\} \text{ and } t_at_bt_c=s_H \right\}, 
\end{align*}
i.e., a nonbasis consist of an equation of the linear system with fulfilling assignments. Note that by choosing different values for $s_H\in \{\pm 1\}$, we obtain (possibly) different matroids from $M$. If $s_H=1$ for all $H$, the linear system is \emph{homogeneous} and we call the associated matroid $M_{hom}$.
In the following, we write $(H,t)$ for the nonbasis of $M_{S}$ corresponding to $H\in\cZ(M)$ and $t\in\{\pm 1\}^H$.

\begin{theorem}
\label{thm:qisomorphic-matroid}
Consider a rank $3$ sparse paving matroid $M$, a collection $S = \left( s_{H} \suchthat H\in \cZ(M) \right)$ in $\{\pm 1\}^{\cZ^{1}(M)}$ and the associated linear system $(\pV, \pE)$ (see previous subsections). Assume there exists a perfect quantum strategy for the linear system game associated to $(\pV, \pE)$. Then $M_{hom}$ and $M_{S}$ are quantum isomorphic, i.e., the ($M_{hom}, M_{S}$, $\NB$)-isomorphism game has a perfect quantum strategy. 
\end{theorem}

\begin{proof}
The players Alice and Bob use the following strategy in the nonbasis isomorphism game: Upon receiving pointed nonbases $((H_A, t_A), (x, a))$ and $((H_B, t_B), (y,b))$, respectively, they play the linear system game (see \S\ref{sec:LBCS+game}) with questions $H_A$ and $H_B$ using the perfect quantum strategy. Since it is a perfect quantum strategy, they receive fulfilling assignments $k_A$ and $k_B$ to $H_A$ and $H_B$  which agree on the common variables in $H_A$ and $H_B$. The players then answer $((H_A, t_A*k_A), (x, ak))$ and $((H_B, t_B*k_B),(y,bl))$ in the isomorphism game, where $*$ denotes the entry-wise product and $k$ and $l$ are the assignments to $x$ and $y$ in $k_A$ and $k_B$. Note that since $t_A$ and $t_B$ are fulfilling assignments in the homogeneous system, we get that $t_A*k_A$ and $t_B*k_B$ fulfilling assignments for the LBCS associated to $S$, i.e., $(H_A, t_A*k_A)$ and $(H_B, t_B*k_B)$ are nonbasis in $M_{S}$. 

It remains to check that the relations are preserved in this strategy:

\medskip 

\noindent \textbf{Case 1:} $\rel(((H_A, t_A), (x, a)),((H_B, t_B), (y,b)))=0$. It is clear that the same is true for their answers, since the assignments they get agree on the common variables, which are all variables since $H_A=H_B$.

\medskip 

\noindent \textbf{Case 2:} $\rel(((H_A, t_A), (x, a)),((H_B, t_B), (y,b)))=1$. We have $(x,a)=(y,b)$ and since the answers agree on common variables, it holds $k=l$ and therefore $(x,ka)=(y,lb)$. We furthermore have $(H_A, t_A*k_A)\neq (H_B, t_B*k_B)$: either it holds $H_A\neq H_B$ or if $H_A=H_B$, then we have $t_A \neq t_B$ by assumption, and since we have $k_A=k_B$ it holds $t_A*k_A\neq t_B*k_B$.

\medskip 

\noindent \textbf{Case 3:} $\rel(((H_A, t_A), (x, a)), ((H_B, t_B), (y,b)))=2$. Since common variables get multiplied by the same number, we get that $(x, ak)\in (H_B, t_B*k_B)$ and $(y,bl)\in(H_A, t_A)$.

\medskip 

\noindent \textbf{Case 4:} $\rel(((H_A, t_A), (x, a)),((H_B, t_B), (y,b)))=3$. It suffices to check that if $(x, a)\notin (H_B, t_B)$, then $(x, ka)\notin (H_B, t_B*k_B)$ (and similarly for $(y,b)$). This is clear if $x\notin H_B$. If $x\in H_B$, note that assignments of common variables of $H_A$ and $H_B$ get multiplied by the same number. So if the assignments were different before, they are different after multiplying both with $k$. 
\end{proof}

We apply this theorem to find two matroids that are not isomorphic but are $\NB_{\bullet}$--quantum isomorphic. For the rest of this section, let $M$ be the matroid from   \Cref{ex:magic-square-matroid}, recall 
  \begin{equation*}
  \NB(M) = \{123,147,258,369,456,789 \} = \cZ^{1}(M).
  \end{equation*}
(As in that example, we write, e.g., $123$ for $\{1,2,3\}$.)
Define $S = (s_{H} \suchthat H\in \cZ^{1}(M))$ by $s_{789}=-1$ and $s_{H}=1$ for $H\in \cZ^{1}(M) \setminus \{789\}$. 
Let $P = M_{hom}$ and $Q = M_{S}$. 
These matroids have the same ground set $E$ where
\begin{equation*}
    E = \{(a,+1) \suchthat a\in [9] \} \cup \{(a,-1) \suchthat a\in [9] \},
\end{equation*}
and they each have exactly $24$ nonbases. 
Explicitly, the nonbases of $P$ are of the form 
\begin{align*}
    &\{ (a,+1), (b,+1), (c,+1) \}, \
    \{ (a,+1), (b,-1), (c,-1) \}, \\ 
    &\{ (a,-1), (b,+1), (c,-1) \}, \ 
    \{ (a,-1), (b,-1), (c,+1) \},
\end{align*}
where $\{a,b,c\} \in \NB(M)$. The nonbases of $Q$ consist of those listed above for $\{a,b,c\} \in \NB(M)$ except for $\{7,8,9\}$. Instead, $Q$ has as nonbases
\begin{align*}
    \{ (7,+1), (8,+1), (9,-1) \}, \
    &\{ (7,+1), (8,-1), (9,+1) \}, \\ 
    \{ (7,-1), (8,+1), (9,+1) \}, \
    &\{ (7,-1), (8,-1), (9,-1) \}.
\end{align*}
The relation colored graphs of these matroids are illustrated in \Cref{fig:matroids-PQ}.

