\title{Low-Latency Software Polar Encoders and Decoders for Short Blocklengths}

\author{\IEEEauthorblockN{Mathieu Léonardon\IEEEauthorrefmark{1},
         Mohammed El Houcine Ayoubi\IEEEauthorrefmark{1},
         Adrien Cassagne\IEEEauthorrefmark{2},
