	\end{align}
	Moreover, assuming that  $||u_h ||_{0,\O}=1$ we have
	\begin{align}
		h^2||\lambda u-\lambda_h ||_{0,\O}^2&\leq 2\lambda^2||u-u_h ||_{0,\O}^2 +2|\lambda - \lambda_h|^2\leq C |u-u_h|_{2,K}^2+2|\lambda - \lambda_h|^2\nonumber
	\end{align}
