\begin{theorem}\label{thm:grp}
    The group $W(\mathcal{C}_1)$ is generated by $\im X, \im Z,$ and $Q$ (defined in \Cref{thm:mainresult}).
\end{theorem}
\begin{proof}
    By \Cref{thm:GHZ3}, if $\tilde{U}.\ket{\Psi_3}=\ket{\Psi_3}$, then $\tilde{U}=(U_1,U_2,\dots,U_6)$ where $T(U_1\otimes U_2)T^\dagger=PB$ for some permutation matrix $P\in \SO_4$ and diagonal $B\in\SO_4$. The set of all $PB$ of this form is a group generated by the 3 matrices in the left column of \Cref{table1}; though not relevant to the proof, this group consists of all elements $w\in W(D_4)$ in the Weyl group of type $D_4$ such that $\det(w)>0$. The right column of \Cref{table1} shows, for each generator $U$, how $T^\dagger U T$ decomposes as a Kronecker product of matrices in $\SU_2$. Applying \Cref{prop:stab}, we conclude that $W(\mathcal{C}_1)$ is generated by
    \[
    \im X=\begin{pmatrix}
        0 & \im \\
        \im & 0
    \end{pmatrix}, \quad \im Z=\begin{pmatrix}
        \im & 0 \\
        0 & -\im
    \end{pmatrix}, \quad \text{and}\quad
    Q=\frac{1}{2}\begin{pmatrix}
        1+\im & 1+\im \\
        -1+\im & 1-\im
    \end{pmatrix}.
    \]
    These come from taking the inverse transpose of the left factors of the matrices that appear in the right column of \Cref{table1}.
\end{proof}

\subsubsection{Group of order 24}\label{sec:24} The generators of $W(\mathcal{C}_1)$ are elements of $\SU_2$. Thus, we can use the standard double cover $\SU_2\to \SO_3(\RR)$ to help us to understand this group. The generators map to the following:
\[
\im X \mapsto \begin{pmatrix}
    1 & 0 & 0 \\
    0 & -1 & 0 \\
    0 & 0 & -1
\end{pmatrix},\quad 
\im Z \mapsto \begin{pmatrix}
    -1 & 0 & 0 \\
    0 & -1 & 0 \\
    0 & 0 & 1
\end{pmatrix},\quad 
Q \mapsto \begin{pmatrix}
    0 & 0 & 1 \\
    1 & 0 & 0\\
    0 & 1 & 0
\end{pmatrix}.
\]
These $3\times 3$ matrices generate the tetrahedral group, which represents the rotational symmetries of the tetrahedron with vertices $(1,1,1)$, $(1,-1,-1)$, $(-1,1,-1)$, and $(-1,-1,1)$. The tetrahedral group contains 12 elements; it acts as even permutations on the set of vertices and is isomorphic to the alternating group $\mathfrak{A}_4\subset\mathfrak{S}_4$. Since $W(\mathcal{C}_1)$ is the preimage of the tetrahedral group under the double cover, it contains 24 elements.

\section{Lie theory and Vinberg theory}\label{sec:vinberg}
In this section, we cover results from Lie theory and Vinberg's paper \cite{Vinberg_1976} about graded Lie algebras. We focus on a specific $\ZZ_2$-graded Lie algebra.

Let $\mathfrak{g}=\mathfrak{so}_{8}$ be the complex Lie algebra consisting of $8\times 8$ skew-symmetric matrices with the Lie bracket given by the commutator $[M,N]=MN-NM$ for $M,N\in\mathfrak{g}$. Let $G=\SO_{8}$ be the corresponding connected Lie group. The Lie algebra $\mathfrak{g}$ has an adjoint representation $\text{ad}:\mathfrak{g}\to\text{Aut}(\mathfrak{g})$ defined by the action $M.N=[M,N]$. The Lie group $G$ has an adjoint representation $\text{Ad}:G\to \GL(\mathfrak{g})$ defined by conjugation: $g.M=gMg^\top$, where $g\in G$. Up to a scalar multiple, the Killing form $\mathfrak{g}\times\mathfrak{g}\to\CC$ is given by $(M,N)\mapsto\text{tr}(MN)$. Note the invariance of the Killing form:
\begin{equation}\label{eq:killing}
\text{tr}([L,M],N)=\text{tr}(M,[N,L]),\quad\text{for all $L,M,N\in\mathfrak{g}$.}
\end{equation}

\subsection{A graded Lie algebra}\label{sec:graded}
Each element of $\mathfrak{g}$ can be viewed as a $2\times 2$ block matrix with $4\times 4$ blocks. From this, we see that the space decomposes as $\mathfrak{g}=\mathfrak{g}_0\oplus\mathfrak{g}_1$, where
\begin{align*}
\mathfrak{g}_0=\left\{\begin{pmatrix}
    E_1 & 0 \\
    0 & E_2
\end{pmatrix}: E_1,E_2\in\mathfrak{so}_4\right\}\quad\text{and}\quad
\mathfrak{g}_1 = \left\{\begin{pmatrix}
    0 & A \\
    -A^\top & 0
\end{pmatrix}: A\in\CC^{4\times 4} \right\}.
\end{align*}
This is in fact a $\mathbb{Z}_2$-grading of the Lie algebra:
$
[\mathfrak{g}_i,\mathfrak{g}_j]\subset\mathfrak{g}_{i+j \text{ (mod 2)}}.
$
In particular, we have $[\mathfrak{g}_0,\mathfrak{g}_1]\subset\mathfrak{g}_1$ so that the adjoint action induces a representation
\begin{equation*}\label{eq:ad}
\mathfrak{g}_0\to\text{End}(\mathfrak{g}_1),\quad E\mapsto \text{ad}(E)|_{\mathfrak{g}_1}.
\end{equation*}
Let $G_0:=\exp(\mathfrak{g}_0)\cong \SO_4^{\times 2}$ be the subgroup of $G$ corresponding to $\mathfrak{g}_0$. The Lie algebra representation above corresponds to the Lie group representation
\[
G_0\to \GL(\mathfrak{g}_1),\quad g\mapsto \text{Ad}(g)|_{\mathfrak{g}_1}.
\]
We are interested in the grade-1 piece $\mathfrak{g}_1$ as a $G_0$-module. Note that $\CC^{4\times 4}\cong \mathfrak{g}_1$ by the linear isomorphism
\[
\CC^{4\times 4}\to\mathfrak{g}_1,\quad
A\mapsto M_A :=\begin{pmatrix}
    0 & A \\
    -A^\top & 0
\end{pmatrix}.
\]
Given $A\in\CC^{4\times 4}$ and $U_1,U_2\in\SO_4$, we have
\[
\text{Ad}\begin{pmatrix}
    U_1 & 0 \\ 0 & U_2
\end{pmatrix}M_A=M_{U_1AU_2^\top}.
\]
Thus, the corresponding $\SO_4^{\times 2}$-action on $\CC^{4\times 4}$ is given by $(U_1,U_2).A=U_1 AU_2^\top$. We conclude that $\mathfrak{g}_1$ is equivalent to both $\CC^4\otimes\CC^4$ and $\CC^{4\times 4}$ as $\SO_4^{\times 2}$-modules.

\subsection{Cartan subspaces}\label{sec:cartansubspaces}
Recall that an element $M\in\mathfrak{g}$ is \textit{semisimple} if $\text{ad}(M)$ is diagonalizable. Let $\mathfrak{a}$ be a subspace of $\mathfrak{g}_1$ with the properties:
\begin{itemize}
    \item[1.] $\mathfrak{a}$ is \textit{abelian}, that is, $[\mathfrak{a},\mathfrak{a}]=0$, and
    \item[2.] every $M\in\mathfrak{a}$ is semisimple.
\end{itemize}
If $\mathfrak{a}$ is maximal among all subspaces of $\mathfrak{g}_1$ with these properties, then $\mathfrak{a}$ is a \textit{Cartan subspace} of $\mathfrak{g}_1$.
Any two Cartan subspaces are conjugate (\Cref{prop:conjugacy}), but our preferred one is
\[
\mathfrak{h}=\{M_A:\text{$A\in\CC^{4\times 4}$ is diagonal}\}.
\]
Note that $\mathfrak{h}$ is also a Cartan subalgebra of $\mathfrak{g}$ in the usual Lie-theoretical sense.

\begin{theorem}\label{prop:semiclosed}
    An element $M\in\mathfrak{g}_1$ is semisimple if and only if its $G_0$-orbit is closed.
\end{theorem}
\begin{proof}
    See \cite[Proposition 3]{Vinberg_1976}.
\end{proof}

\begin{theorem}\label{prop:conjugacy}
    If $\mathfrak{a}\subset\mathfrak{g}_1$ is a Cartan subspace, then there exists $g\in G_0$ such that $g.\mathfrak{a}=\mathfrak{h}$.
\end{theorem}
\begin{proof}
    See \cite[Theorem 1]{Vinberg_1976}.
\end{proof}

If $\mathfrak{a}\subset\mathfrak{g}_1$ is an abelian subspace consisting of semisimple elements, then there exists $g\in G_0$ such that $g.\mathfrak{a}\subset \mathfrak{h}$. Indeed, any such $\mathfrak{a}$ is contained in one that is maximal: a Cartan subspace. The claim then follows from \Cref{prop:conjugacy}.


\begin{lemma}\label{lem:stab}
    Let $\mathfrak{a}$ be an abelian subspace of $\mathfrak{g}_1$ consisting of semisimple elements. Almost every $M\in\mathfrak{a}$ has the following property: if $g\in G_0$ such that $g.M=M$, then $g.N=N$ for all $N\in\mathfrak{a}$.
\end{lemma}
\begin{proof}
We may apply a change of basis and assume that $\mathfrak{a}\subset\mathfrak{h}$, by \Cref{prop:conjugacy}. The subspace $\mathfrak{a}$ corresponds to a subspace $\mathfrak{t}'\subset\CC^{4\times 4}$ consisting of diagonal matrices via the isomorphism $\mathfrak{g}_1\cong\CC^{4\times 4}$. Let $\{A^i:1\leq i\leq K\}$, where $A^i=\text{diag}(\lambda^i_1,\lambda^i_2,\lambda^i_3,\lambda^i_4)$, be a basis of $\mathfrak{t}'$. A parameterization of $\mathfrak{t}'$ comes from the matrix with polynomial entries
\[
A=\sum_{i=1}^K z_iA^{i}=\text{diag}(\sum_{i=1}^Kz_i\lambda^{i}_1,\dots,\sum_{i=1}^Kz_i\lambda^{i}_4),
\]
where the $z_i$ are indeterminates. One obtains a point in $\mathfrak{t}'$ by evaluating $A$ at a point in $\CC^K$. Two diagonal entries $A_{jj}$ and $A_{kk}$ of $A$ are equal as polynomials if and only if $\lambda_j^i=\lambda^i_k$ for all $i$. By conjugating, we can permute entries and thus assume that $A$ has block diagonal form
\begin{equation}\label{eq:diagparam}
A = f_1(z) I_{m_1\times m_1}\oplus\dots\oplus f_s(z) I_{m_s\times m_s}
\end{equation}
for some distinct $f_i\in \CC[z_1,\dots,z_K]$ and positive integers $m_i$ such that $\sum_i m_i=4$. Let $B=A|_v$ for a generic choice of $v\in\CC^K$. Suppose $U_1,U_2\in \SO_4$ such that $U_1 B U_2^\top=B$. We complete the proof by showing that $U_1 B'U_2^\top=B'$ for all $B'\in\mathfrak{t}'$. We have $U_1 B^2 U_1^\top = B^2$ and
\[
B^2 = f^2_1(v) I_{m_1\times m_1}\oplus\dots\oplus f^2_s(v) I_{m_s\times m_s}.
\]
Since $U_1$ commutes with $B^2$, $U_1$ preserves the eigenspaces of $B$. If the values $f^2_1(v),\dots,f^2_s(v)$ are distinct, then $U_1\in \SO_{m_1}\oplus\dots\oplus\SO_{m_s}$. A similar argument applies for $U_2$. It follows that $U_1=U_2$. Then $(U_1,U_2)$ fixes \eqref{eq:diagparam} as a matrix of polynomials. That is, $(U_1,U_2)$ fixes every point of $\mathfrak{t}'$.
\end{proof}

\subsection{Weyl group}\label{sec:weyl} In Vinberg theory, the subgroup
$
N(\mathfrak{h})=\{g\in G_0: g.\mathfrak{h}=\mathfrak{h}\}
$
is known as the \textit{normalizer} of the Cartan subspace $\mathfrak{h}$. There exists a natural representation $\mu:N(\mathfrak{h})\to \GL(\mathfrak{h})$ defined by $\mu(g)A=g.A$ for all $g\in G_0$ and $A\in\mathfrak{h}$. The kernel of $\mu$ is called the \textit{centralizer} of $\mathfrak{h}$, written
$
C(\mathfrak{h})=\{g\in G_0: g.M=M\text{ for all }M\in\mathfrak{h}\}.
$
The \textit{Weyl group} of $\mathfrak{h}$ is defined as $W(\mathfrak{h}):=\mu(N(\mathfrak{h}))\cong N(\mathfrak{h})/C(\mathfrak{h})$. The action of $N(\mathfrak{h})$ on $\mathfrak{h}$ naturally induces an action of $W(\mathfrak{h})$ on $\mathfrak{h}$. The following is analogous to the Chevalley restriction theorem:
\begin{theorem}\label{thm:isomorphism}
    The restriction map $f\mapsto f|_{\mathfrak{h}}$ for $f\in \CC[\mathfrak{g}]$ induces an isomorphism of invariant algebras $\CC[\mathfrak{g}]^{G_0}\cong \CC[\mathfrak{h}]^{W(\mathfrak{h})}$.
\end{theorem}
\begin{proof}
    See \cite[Theorem 7]{Vinberg_1976}.
\end{proof}
A natural basis for $\mathfrak{h}$ is $\{M_{\ket{i}\bra{i}}:0\leq i\leq 3\}$. With this choice of coordinates, $W(\mathfrak{h})$ consists of matrices of the form $PB$, where $P\in \Or_4$ is a permutation matrix and $B\in \SO_4$ is a special orthogonal diagonal matrix (see \cite[Exercise~3, p.~179]{WallachGIT}). This group is also the Weyl group of the Lie algebra $\mathfrak{so}_8$ in the usual sense of Lie theory.

\subsection{Embedded 4-qubit state space}\label{sec:embed} Recall from \Cref{sec:unitarychange} that the unitary map $(\CC^2)^{\otimes 4}\to \CC^4\otimes\CC^4$, where $\ket{u}\mapsto T^{\otimes 2}\ket{u}$, is $\SL_2^{\times 4}$-equivariant; the representation
\[\begin{tikzcd}
	{\operatorname{SL}_2^{\times 4}} & {\operatorname{SO}_4\times\operatorname{SO}_4} & {\operatorname{GL}(\CC^4\otimes\CC^4)}
	\arrow["q", from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
\end{tikzcd}\]
factors through the homomorphism
\[
q(A_1,A_2,A_3,A_4)=(T(A_1\otimes A_2)T^\dagger,T(A_3\otimes A_4)T^\dagger).
\]
In this way, the $\SL_2^{\times 4}$-module $(\CC^2)^{\otimes 4}$ is equivalent to the $\SO_4^{\times 2}$-module $\CC^4\otimes \CC^4$. Both are equivalent to the $\SO_4$-module $\CC^{4\times 4}$ with the action $(U_1,U_2).A=U_1 AU_2^\top$ for $U_1,U_2\in\SO_4$ and $A\in\CC^{4\times 4}$. We also remind the reader that $T(\SU_2\otimes\SU_2)T^\dagger=\SO_4\cap \U_4$.

\subsubsection{Critical points} We say that $M\in\mathfrak{g}_1$ is \textit{critical} if the corresponding state in $(\CC^2)^{\otimes 4}$ is critical. A subspace $\mathfrak{a}\subset\mathfrak{g}_1$ is \textit{critical} if every $M\in\mathfrak{a}$ is critical. A critical subspace in $\mathfrak{g}_1$ corresponds to a pure code of distance 2 in $(\CC^2)^{\otimes 4}$. In particular, the Cartan subspace $\mathfrak{h}$ is critical and corresponds to the $((4,4,2))$ code $\mathcal{C}_2\subset(\CC^2)^{\otimes 4}$. Note that $M\in\mathfrak{g}_1$ is critical if and only if
\begin{equation}\label{eq:altcritical}
    \text{tr}([E,M]M^\dagger)=0,\quad \forall E\in \mathfrak{g}_0.
\end{equation}
This follows from translating the characterization of critical points given by \Cref{prop:equiv}, which says that $x\in (\CC^2)^{\otimes 4}$ is critical if and only if $\langle Ex,x\rangle=0$ for all $E\in \text{Lie}(\SL_2^{\otimes 4})$, where angle brackets indicate the Hermitian inner product.
Applying the change of coordinates $x'=(T\otimes T)x$, the condition becomes $\langle Ex',x'\rangle=0$ for all $E\in\text{Lie}(\SO_4^{\otimes 2})$. Every $E\in\text{Lie}(\SO_4^{\otimes 2})$ has the form $E=E_1\otimes I+I\otimes E_2$ for some $E_1,E_2\in \mathfrak{so}_4$. Let $A,B\in \CC^{4\times 4}$. Note that $\text{tr}(M_A M^\dagger_B)=2\text{tr}(AB^\dagger)$. Therefore, $M_A\in\mathfrak{g}_1$ is critical if and only if
\[
\text{tr}([\begin{pmatrix}
    E_1 & 0 \\ 0 & E_2
\end{pmatrix},M_A]M_{A}^\dagger)=2\text{tr}((E_1A+AE_2^\top)A^\dagger)=0
\]
for every $E_1,E_2\in \mathfrak{so}_4$, as desired.

\subsubsection{Note on the spin flip} Taking the negative conjugate transpose $M\mapsto -M^\dagger$ of a matrix $M\in\mathfrak{g}_1$ corresponds to an involutory $\RR$-linear map $(\CC^2)^{\otimes 4}\to (\CC^2)^{\otimes 4}$ known as the \textit{spin flip} \cite{PhysRevLett.80.2245}. For an arbitrary number $n$ of qubits, this map is defined by
\[
\ell:(\CC^2)^{\otimes n}\to (\CC^2)^{\otimes n},\quad\ell\ket{\varphi}=J^{\otimes n}\ket{\bar{\varphi}},
\]
where $J=-iY$ (recall that a bar over a vector indicates the complex conjugate). The spin flip is the standard time reversal operation for spin $\frac{1}{2}$ particles \cite{sakurai_modern_2021}. Note the Cayley-Klein parameterization of the special unitary group:
\begin{equation}\label{eq:cayley-klein}
\SU_2=\left\{\begin{pmatrix}
    a & b\\
    -\bar{b} & \bar{a}
\end{pmatrix}:a,b\in\CC\:\land\:|a|^2+|b|^2=1\right\}.
\end{equation}
 From this it is simple to check that $U_i J=J\bar{U}_i$ for any $U_i\in\SU_2$. If $U=U_1\otimes\dots\otimes U_n$ where each $U_i\in\SU_2$, then
 \[U(\ell \ket{\varphi})=UJ^{\otimes n}\ket{\bar{\varphi}}=J^{\otimes n}\bar{U}\ket{\bar{\varphi}}=\ell (U\ket{\varphi}),\quad\forall\ket{\varphi}\in(\CC^2)^{\otimes n}.\]
 That is, $\ell$ is equivariant: it commutes with any $U\in \SU_2^{\otimes n}$. For $n=4$ qubits, this corresponds to the fact that $gM^\dagger g^\dagger=(gM g^\dagger)^\dagger$ for $M\in\mathfrak{g}_1$ and $g\in G_0\cap\U_8$.

