\section{Classification results}\label{sec:classification}

\subsection{Four-qubit codes of distance two}\label{sec:1uniform} We now present a sequence of lemmas leading to \Cref{cor:1uniform}, which tells us that every 4-qubit pure code is equivalent to a subspace of $\mathcal{C}_2$. Two special cases are a result of Wallach, that every 4-qubit critical state is equivalent to a point in $\mathcal{C}_2$; and a result of Rains, that the $((4,4,2))_2$ code is unique. This shows the power of the Vinberg theoretical perspective we adopt.

\begin{lemma}[Wallach]\label{lem:wallach}
The point $M\in \mathfrak{g}_1$ is critical if and only if $[M,M^\dagger]=0$.
\end{lemma}
\begin{proof}
    We follow the proof of Lemma 3.73 in \cite{WallachGIT}. By \eqref{eq:killing}, we have
    $\text{tr} ([E,M]M^\dagger)=\text{tr}(E[M,M^\dagger])
    $
    for all $E\in \mathfrak{g}_0$.
    The restriction $\mathfrak{g}_0\times\mathfrak{g}_0\to\CC$ of the Killing form is nondegenerate. Therefore, $\text{tr} ([E,M]M^\dagger)=0$ for all $E\in\mathfrak{g}_0$ if and only if $[M,M^\dagger]=0.$ Using the condition \eqref{eq:altcritical} for being critical, we are done.
\end{proof}
\begin{lemma}\label{lem:critsubspace}
A subspace $\mathfrak{a}\subset \mathfrak{g}_1$ is critical if and only if $[\mathfrak{a},\mathfrak{a}^\dagger]=0$.
\end{lemma}
\begin{proof}
    It is clear from \Cref{lem:wallach} that if $[\mathfrak{a},\mathfrak{a}^\dagger]=0$, then $\mathfrak{a}$ is critical. Conversely, suppose $\mathfrak{a}$ is critical. Then for any $M,N\in\mathfrak{g}_1$ and $z\in \CC$ we have
    \[
    0=[M+z N,M^\dagger+\bar{z} N^\dagger]=\bar{z}[M,N^\dagger]+z[N,M^\dagger]=\bar{z}[M,N^\dagger]+(\bar{z}[M,N^\dagger])^\dagger.
    \]
    Setting $L_z=\bar{z}[M,N^\dagger]$, we have $L_z=-L_z^\dagger$. Since $L_z$ is skew-symmetric, $L_z=(L_z^{\dagger})^\top$ so $L_z$ is purely real. Since $z\in \CC$ is arbitrary, we must have $[M,N^\dagger]=0$.
\end{proof}
\begin{lemma}\label{lem:uniquecritcartan}
    Let $\mathfrak{a}\subset\mathfrak{g}_1$ be a critical abelian subspace. There exists $g\in G_0\cap \U_8$ such that $g.\mathfrak{a}\subset\mathfrak{h}$.
\end{lemma}
\begin{proof}
    Taken together, \Cref{prop:semiclosed} and the third item of \Cref{prop:K-N} imply that $\mathfrak{a}$ consists of semisimple elements. By \Cref{prop:conjugacy}, there exists $g\in G_0$ such that $g.\mathfrak{a}\subset\mathfrak{h}$. It is left to show that $g$ can be chosen to be unitary. We can choose, by \Cref{lem:stab}, an element $x\in g.\mathfrak{a}$ such that $h.(g.\mathfrak{a})=g.\mathfrak{a}$ whenever $h\in G_0$ such that $h.x=x$. Since $g^{-1}.x\in\mathfrak{a}$ and $x\in\mathfrak{h}$ are both critical, by \Cref{prop:K-N}, there exists $\tilde{g}\in G_0\cap \U_8$ such that $\tilde{g}.(g^{-1}.x)=x$. This element has the form $\tilde{g}=hg$, where $h\in G_0$ such that $h.x=x$. It follows that $\tilde{g}.\mathfrak{a}=g.\mathfrak{a}$.
\end{proof}
\begin{corollary}\label{cor:wal}
    If $M$ is critical, then there exists $g\in G_0\cap \U_8$ such that $g.M\in\mathfrak{h}$.
\end{corollary}
\begin{proof}
    If $M$ is critical, then $[M,M]=[M,M^\dagger]=0$, by \Cref{lem:wallach}. Then $M$ spans a critical abelian subspace. The result follows from \Cref{lem:uniquecritcartan}.
\end{proof}
For the proof of \Cref{lem:lll}, let us work out what it means for elements of $\mathfrak{g}_1$ to commute in terms of their $4\times 4$ submatrices. For $A,B\in\CC^{4\times 4}$, we have
\[
[M_A,M_B]=\begin{pmatrix}
    -AB^\top+BA^\top & 0 \\
    0 & -A^\top B + B^\top A
\end{pmatrix}.
\]
Therefore, $[M_A,M_B]=0$ if and only if $AB^\top=BA^\top=(AB^\top)^\top$ and $B^\top A=A^\top B=(B^\top A)^\top$ are symmetric.
\begin{lemma}\label{lem:lll}
    Suppose $M,N\in \mathfrak{g}_1$ such that $N$ is critical. We have $[M,N]=0$ if and only if $[M,N^\dagger]=0$.
\end{lemma}
\begin{proof}
    It suffices to prove one direction because $N^\dagger$ is critical if $N$ is critical and $(N^\dagger)^\dagger=N$. Furthermore, we may assume that $N\in\mathfrak{h}$ since there exists $g\in G_0\cap \U_8$ such that $g.N\in\mathfrak{h}$ (\Cref{cor:wal}) and $N\mapsto N^\dagger$ commutes with the action of $g$.

    Let $A,B\in \CC^{4\times 4}$ such that $B$ is diagonal. If $[M_A,M_B]=0$, then $AB$ and $BA$ are symmetric. That is, for any $1\leq i<j\leq 4$ we have
    \begin{align*}
    0&=(AB)_{ij}-(AB)_{ji}=A_{ij}B_{jj}-A_{ji}B_{ii},\\
    0&=(BA)_{ij}-(BA)_{ji}=A_{ij}B_{ii}-A_{ji}B_{jj}.
    \end{align*}
    Adding and subtracting the equations above, we obtain the equivalent system:
    \begin{align*}
    0&=(A_{ij}-A_{ji})B_{ii}+(A_{ij}-A_{ji})B_{jj}=(A_{ij}-A_{ji})(B_{ii}+B_{jj}), \\
    0&=(A_{ij}+A_{ji})B_{jj}-(A_{ij}+A_{ji})B_{ii}=(A_{ij}+A_{ji})(B_{jj}-B_{ii}).
    \end{align*}
    But this holds if and only if
    \[
    0=(A_{ij}-A_{ji})(\bar{B}_{ii}+\bar{B}_{jj})\quad\text{and}\quad
    0=(A_{ij}+A_{ji})(\bar{B}_{jj}-\bar{B}_{ii}).\]
    Reasoning backwards, we conclude that $A\bar{B}$ and $\bar{B}A$ are symmetric. Thus, $[M_A,M_B^\dagger]=[M_A,-M_{\bar{B}}]=0$.
\end{proof}

\begin{theorem}\label{thm:general}
    Let $\mathfrak{a}\subset\mathfrak{g}_1$ be a critical subspace. There exists $g\in G_0\cap \U_8$ such that $g.\mathfrak{a}\subset\mathfrak{h}$.
\end{theorem}
\begin{proof}
    We show that $\mathfrak{a}$ is abelian; the result follows from \Cref{lem:uniquecritcartan}. Let $M,N\in\mathfrak{a}$. By \Cref{lem:critsubspace}, we have $[M,N^\dagger]=0$. By \Cref{lem:lll}, we have $[M,N]=0$.
\end{proof}

\begin{corollary}\label{cor:1uniform}
    Every pure code $\mathcal{C}\subset(\CC^2)^{\otimes 4}$ is $\SU_2^{\times 4}$-equivalent to a subspace of $\mathcal{C}_2$.
\end{corollary}
\begin{proof}
    Since 4-qubit AME states do not exist \cite{HIGUCHI2000213}, it suffices to show that every 1-uniform subspace of $(\CC^2)^{\otimes 4}$ is equivalent to a subspace of $\mathcal{C}_2$. This follows from \Cref{thm:general}.
\end{proof}

\subsection{First main result}\label{sec:first} We are now ready to prove our first main result (\Cref{thm:first}). To prepare, let us recall some basic concepts from algebraic geometry.

Let $V$ be a finite-dimensional vector space over a field $\mathbb{K}$. Given an ideal $\mathcal{I}\subset\mathbb{K}[V]$, the variety of $\mathcal{I}$ is
$
\textbf{V}_\mathbb{K}(\mathcal{I})=\{x\in V:\text{$f(x)=0$ for all $f\in\mathcal{I}$}\}.
$
If $\mathcal{A}\subset V$ is a subset, the ideal of $\mathcal{A}$ is
$
\textbf{I}(\mathcal{A})=\{f\in \mathbb{K}[V]:\text{$f(x)=0$ for all $x\in \mathcal{A}$}\}.
$
If $\mathcal{I},\mathcal{J}$ are ideals in $\mathbb{K}[V]$, the ideal quotient of $\mathcal{I}$ by $\mathcal{J}$ is the ideal
$
\mathcal{I}:\mathcal{J}=\{f\in\mathbb{K}[V]: \text{$fg\in\mathcal{I}$ for all $g\in\mathcal{J}$}\}.
$
The intersection of ideals corresponds to the union of varieties: $\textbf{V}_\mathbb{K}(\mathcal{I}\cap\mathcal{J})=\textbf{V}_\mathbb{K}(\mathcal{I})\cup\textbf{V}_\mathbb{K}(\mathcal{J})$.

\begin{lemma}\label{thm:colon}
    If $\mathcal{I}$ and $\mathcal{J}$ are ideals in $\mathbb{K}[V]$, then $\textbf{V}_\mathbb{K}(\mathcal{I})\setminus\textbf{V}_\mathbb{K}(\mathcal{J})\subset \textbf{V}_\mathbb{K}(\mathcal{I}:\mathcal{J})$.
\end{lemma}
\begin{proof}
    See \cite[Proposition 7]{CoxLittleOShea2015}.
\end{proof}



\begin{theorem}\label{thm:first}
    Suppose $\ket{\psi}\in(\CC^2)^{\otimes 5}$ is AME. There exists $g\in\SU_2^{\times 5}$ such that $g.\ket{\psi}\in\mathcal{C}_1$.
\end{theorem}
\begin{proof}
    The $((5,2,3))_2$ code $\mathcal{C}_1$ is unique up to local unitary equivalence (\Cref{thm:rainsuniqueness}), so it suffices to show that every AME state is equivalent to a point in \textit{some} $((5,2,3))_2$ code. Since $\ket{\psi}$ is 2-uniform, the vectors $\bra{0}_1\ket{\psi}$ and $\bra{1}_1\ket{\psi}$ span a $((4,2,2))_2$ code (\Cref{prop:rains2}). By \Cref{cor:1uniform}, we can apply local unitary change of coordinates so that $\bra{0}_1\ket{\psi}$ and $\bra{1}_1\ket{\psi}$ are in $\mathcal{C}_2$. That is, we may assume that $\ket{\psi}\in \CC^2\otimes \mathcal{C}_2$. The proof proceeds as follows. Let $\mathcal{A}\subset \CC^2\otimes\mathcal{C}_2$ be the real variety of AME states in $\CC^2\otimes\mathcal{C}_2$. We show that this variety decomposes into irreducibles as $\mathcal{A}=\mathcal{A}_1\cup\mathcal{A}_2$, where $\mathcal{A}_1$ and $\mathcal{A}_2$ are orbits of $((5,2,3))_2$ codes under the action of a subgroup of $\SU_2^{\times 5}$. The computations in this proof were carried out with the help of the computer algebra system Macaulay2 \cite{M2}.


    For $i,j\in\{0,1\}$, let $\ket{\varphi_{ij}}=\bra{ij}_{12}\ket{\Psi}$ (these were written out explicitly in \Cref{sec:main}). The vectors $\ket{\varphi_{ij}}$ form a basis fo $\mathcal{C}_2$ and gives coordinates to the subspace $\CC^2\otimes\mathcal{C}_2$. Every $\ket{\psi}\in\CC^2\otimes\mathcal{C}_2$ is written as
    \begin{align*}
\ket{\psi}=&\sum_{i=0}^1\ket{i}\otimes(z_{i0}\ket{\varphi_{00}}+z_{i1}\ket{\varphi_{01}}+z_{i2}\ket{\varphi_{10}}+z_{i3}\ket{\varphi_{11}})
    \end{align*}
    for some constants $z_{ij}\in\CC$. Let $z_{ij}=x_{ij}+\im y_{ij}$ where $x_{ij},y_{ij}\in \RR$. The variety $\mathcal{A}$ is cut out by the 12 quadratics listed in \Cref{table2}, which generate an ideal $\mathcal{J}\subset\RR[x_{ij},y_{ij}]$. These polynomials come from the fact that $\ket{\psi}$ is AME if and only if $\rho_S=\text{Tr}_{S}(\ket{\psi}\bra{\psi})$ is proportional to the identity for every 3-element subset $S\subset\{1,\dots,5\}$. Thus, $\mathcal{A}$ is defined by the vanishing of the complex functions
    $
    (\rho_S)_{ij}
    $ for $1\leq i<j\leq 4$ and $(\rho_S)_{11}-(\rho_S)_{ii}$ for $2\leq i\leq 4$. By taking real and imaginary parts, this collection of functions corresponds to a collection of real polynomials. After simplification, we obtain \Cref{table2}.

    Let $\ket{\Phi_0}=\bra{0}_1\ket{\Psi}$ and $\ket{\Phi_1}=\bra{1}_1\ket{\Psi}$. Recalling the Cayley-Klein parametrization \eqref{eq:cayley-klein}, define the map
    \begin{align*}%\label{eq:singlesite}
    \gamma(a,b,c,d)&=
        \begin{pmatrix}
            a & b\\
            -\bar{b} & \bar{a}
        \end{pmatrix}\otimes I\otimes I\otimes I\otimes I
        (c\ket{\Phi_0}+d\ket{\Phi_1}),
    \end{align*}
    where $a,b,c,d\in\CC$. By definition, every point in the image of $\gamma$ is in the local unitary orbit of a point in the $((5,2,3))_2$ code $\mathcal{C}_1$ spanned by $\ket{\Phi_0}$ and $\ket{\Phi_1}$. A calculation shows that $\gamma(a,b,c,d)=\sum_{i=0}^1\ket{i}\otimes \gamma_i(a,b,c,d)$, where
    \begin{align*}
\gamma_0(a,b,c,d)&=ac\ket{\varphi_{00}}+bc\ket{\varphi_{01}}+ad\ket{\varphi_{10}}+bd\ket{\varphi_{11}},\text{ and} \\ \gamma_1(a,b,c,d)&=-\bar{b}c\ket{\varphi_{00}}+\bar{a}c\ket{\varphi_{01}}-\bar{b}d\ket{\varphi_{10}}+\bar{a}d\ket{\varphi_{11}}.
    \end{align*}
    From the above, it is not hard to see that $\gamma$ maps onto an irreducible subvariety $\mathcal{A}_1$ of $\mathcal{A}$. The subvariety $\mathcal{A}_1$ is equivalent to the set of matrices in $\CC^{2\times 4}$ with block form $(cU|dU)$, where $U\in\SU_2$ and $c,d\in\CC$. Irreducibility follows from the irreducibility of the domain. This contruction works just as well with the vectors $\ket{\varphi_{01}}$ and $\ket{\varphi_{10}}$ swapped. That is, the image of the map $\kappa(a,b,c,d)=\sum_{i=0}^1\ket{i}\otimes \kappa_i(a,b,c,d)$, where
    \begin{align*}
\kappa_0(a,b,c,d)&=ac\ket{\varphi_{00}}+ad\ket{\varphi_{01}}+bc\ket{\varphi_{10}}+bd\ket{\varphi_{11}},\text{ and} \\ \kappa_1(a,b,c,d)&=-\bar{b}c\ket{\varphi_{00}}-\bar{b}d\ket{\varphi_{01}}+\bar{a}c\ket{\varphi_{10}}+\bar{a}d\ket{\varphi_{11}}
    \end{align*}
    is an irreducible variety $\mathcal{A}_2$ consisting of AME states that are equivalent to a points in a $((5,2,3))_2$ code. Note that the domain of $\gamma$ and $\kappa$ can be considered to be $\RR^8$ by taking real and imaginary parts; we write, for example, $a=a_0+\im a_1$ for some $a_0,a_1\in\RR$.
    The maps $\gamma,\kappa:\RR^8\to \CC^2\otimes\mathcal{C}_2$ correspond to ring maps $ \gamma^*,\kappa^*:\RR[x_{ij},y_{ij}]\to \RR[a_0,a_1,\dots,d_0,d_1]$
    defined by $\gamma^*(f)=f\circ \gamma$ and $\kappa^*(f)=f\circ \kappa$.
    Then $\ker (\gamma^*)=\textbf{I}(\mathcal{A}_1)$ and $\ker (\kappa^*)=\textbf{I}(\mathcal{A}_2)$, giving us a way to compute the ideals of $\mathcal{A}_1$ and $\mathcal{A}_2$. By \Cref{thm:colon}, we have
    \[
    \mathcal{A}\setminus(\mathcal{A}_1\cup \mathcal{A}_2)\subset \textbf{V}_{\RR}(\mathcal{J}:(\textbf{I}(\mathcal{A}_1)\cap\textbf{I}(\mathcal{A}_2))).
    \]
    A direct check shows that the real polynomial $h=\sum_{ij}|z_{ij}|^2$ is a member of the ideal quotient of $\mathcal{J}$ by $\textbf{I}(\mathcal{A}_1)\cap\textbf{I}(\mathcal{A}_2)$. Since the only real zero of $h$ is 0, we conclude that $\mathcal{A}=\mathcal{A}_1\cup \mathcal{A}_2$.
\end{proof}

