\subsection{Invariant theory for finite groups}\label{sec:finite}
Let us recall some facts from the classical theory of invariants of finite groups. Let $\alpha:G\to\GL(V)$ be a finite-dimensional complex representation of a finite group $G$. The operator $\mathcal{R}=|G|^{-1}\sum_{g\in G} \alpha(g)$ is known as the \textit{Reynolds operator}. The Reynolds operator is a projection onto the invariant subspace $V^G$. That is, the image of $\mathcal{R}$ is $V^G$ and $\mathcal{R}\circ\mathcal{R}=\mathcal{R}$. The representation $\alpha$ induces a representation on the graded algebra $\CC[V]\cong\bigoplus_{d=0}^\infty\text{Sym}^d (V^*)$.

\begin{theorem}[Molien's formula]\label{thm:molien} The following equality of generating functions holds:
    \[
    \sum_{d=0}^\infty \dim(\textup{Sym}^d (V^*)^G)t^d=\frac{1}{|G|}\sum_{g\in G}\frac{1}{\det(I-t\alpha(g))}.
    \]
\end{theorem}
\begin{proof}
    See \cite[Theorem 2.2.1]{SturmfelsInvariant}.
\end{proof}

\begin{theorem}[Noether's degree bound]\label{thm:noether}
    The invariant algebra $\CC[V]^G$ is generated by the set of polynomials $f\in\CC[V]^G$ such that the degree of $f$ is at most $|G|$.
\end{theorem}
\begin{proof}
    See \cite[Theorem 2.1.4]{SturmfelsInvariant}.
\end{proof}

Since $G$ is finite, the invariant algebra $\CC[V]^G=\langle f_1,\dots,f_r\rangle$ is finitely generated by polynomials $f_i\in\CC[V]$. The inclusion map $\CC[V]^G\to \CC[V]$ corresponds to a morphism of varieties $\pi:V\to V\sslash G$ called the \textit{categorical quotient}. We can realize the map $\pi$ explicitly as follows. Given a choice of generators $f_i$ of the invariant algebra, let $\mathcal{J}$ be the kernel of the map
$\CC[x_1,\dots,x_r]\to\CC[V]^G,$ where $x_i\mapsto f_i.$
Then $\CC[V]^G\cong \CC[x_1,\dots,x_r]/\mathcal{J}$ or $\CC[V]^G$ is isomorphic to the coordinate ring of $\textbf{V}_\CC(\mathcal{J})\cong V\sslash G$. The \textit{categorical quotient} is the map
\begin{equation*}%\label{eq:catquotient}
\pi:V\to \textbf{V}_{\CC}(\mathcal{J}), \quad \pi(x)=(f_1(x),\dots,f_r(x))
\end{equation*}
for all $x\in V$.

\begin{theorem}\label{thm:catquotient}
    If $G\to\GL(V)$ is a representation of a finite group $G$, then the fibers of the categorical quotient are $G$-orbits. That is, for all $x\in V$ we have
    \[G.x=\pi^{-1}\circ\pi(x)=\{y\in V:\text{$f(y)=f(x)$ for all $f\in\CC[V]^G$}\}.\]
\end{theorem}
\begin{proof}
     See \cite[Chapter 2.3]{Derksen-Kemper}.
\end{proof}

\begin{theorem}\label{thm:wallachsecond}
    Two states $\ket{\varphi},\ket{\psi}\in\mathcal{C}_2$ are $\SL_2^{\times 4}$-equivalent if and only if they are $W(\mathcal{C}_2)$-equivalent.
\end{theorem}
\begin{proof}
    It follows immediately from the definition of $W(\mathcal{C}_2)$ that if $\ket{\varphi}$ and $\ket{\psi}$ are $W(\mathcal{C}_2)$-equivalent, then $\ket{\varphi}$ and $\ket{\psi}$ are $\SL_2^{\times 4}$-equivalent. Conversely, suppose that $\ket{\varphi}$ and $\ket{\psi}$ are $\SL_2^{\times 4}$-equivalent. Then $f(\ket{\varphi})=f(\ket{\psi})$ for all $\SL_2^{\times 4}$-invariant $f\in\CC[(\CC^2)^{\otimes 4}]$. By \Cref{thm:isomorphism}, we have $g(\ket{\varphi})=g(\ket{\psi})$ for all $W(\mathcal{C}_2)$-invariant $g\in \CC[\mathcal{C}_2]$. By \Cref{thm:catquotient}, $\ket{\varphi}$ and $\ket{\psi}$ are $W(\mathcal{C}_2)$-equivalent.
\end{proof}

Note that $W(\mathcal{C}_2)\cong W(\mathfrak{h})$ via the equivalence $(\CC^2)^{\otimes 4}\cong\mathfrak{g}_1$. An explicit description of $W(\mathcal{C}_2)$ was provided in \Cref{sec:weyl}. The basis $\{M_{\ket{i}\bra{i}}:0\leq i\leq 3\}$ of $\mathfrak{h}$ corresponds to the basis $\{\ket{u_1}+\ket{u_2},\ket{u_1}-\ket{u_2},\ket{u_3}+\ket{u_4},\ket{u_3}-\ket{u_4}\}$ of $\mathcal{C}_2$ (recall the definition of $\ket{u_i}$ from \Cref{sec:main}).

\subsection{Second main result}\label{sec:2pr} We now turn to our second main result. The proof relies on having a set of generators of the algebra of $W(\mathcal{C}_1)$-invariant polynomials. What follows are standard computations for finding a generating set, using the fact that $W(\mathcal{C}_1)$ is finite. Recall, from \Cref{sec:24}, that $|W(\mathcal{C}_1)|=24$. By Molien's formula, we have
\begin{equation*}
\sum_{d=0}^\infty \dim(\text{Sym}^d(\mathcal{C}_1^*)^{W(\mathcal{C}_1)})t^d =\frac{1}{24}\sum_{g\in W(\mathfrak{c})} \frac{1}{\det (I-tg)}
%=\frac{t^8-t^4+1}{t^{24}-t^{10}+1}.
=\frac{1-t^4+t^8}{(1-t^4)(1-t^6)} .
%= (t^8-t^4+1)(1+t^4+t^8+t^{12}+\cdots)(1+t^6 +t^{12} + t^{18} + \cdots)
\end{equation*}
Expanding the above, we obtain the following.
\begin{equation}\label{eq:genfunction}
1+t^6+t^8+2t^{12}+t^{14}+t^{16}+2t^{18}+2t^{20}+t^{22}+3t^{24}+\cdots
\end{equation}
Computing the images under the Reynolds operator $f\mapsto\frac{1}{24}\sum_{g\in W(\mathcal{C}_1)} g.f$ of all monomials $f\in\CC[\mathcal{C}_1]$ of degrees $d\leq 12$, we find three invariants of degrees 6, 8, and 12:
\begin{align*}
\mathscr{I}_6&=x^5 y - xy^5,\\
\mathscr{I}_8&=x^8 + 14x^4 y^4 + y^8, \text{ and}\\
\mathscr{I}_{12}&=x^{12} - 33x^8 y^4 - 33x^4y^8 + y^{12}.
\end{align*}
The polynomials $\mathscr{I}_6^2$ and $\mathscr{I}_{12}$ span the space of homogeneous degree 12 invariants. Looking at the coefficients of the generating function \eqref{eq:genfunction}, we see that these generate the invariant algebra up to degree 24. By Noether's degree bound, $\mathscr{I}_6, \mathscr{I}_8$, and $\mathscr{I}_{12}$ generate the invariant algebra.

\begin{theorem}\label{thm:surj}
    The map $\CC[(\CC^2)^{\otimes 5}]^{\SL_2^{\times 5}}\to\CC[\mathfrak{\mathcal{C}_1}]^{W(\mathcal{C}_1)}$ induced by restriction is surjective.
\end{theorem}
\begin{proof}
Let $R$ denote the ring of $\SL_2^{\times 5}$-invariant polynomials, and $R_d$ denote the homogeneous polynomials of degree $d$ in $R$. To prove the claim, for each $d\in\{6,8,12\}$ we show that there exists an invariant $f_d\in R_d$ such that $f_d|_{\mathcal{C}_1}=\mathscr{I}_d$.

There is a unique (up to scale) $f_6\in R_6$ with constructions that appear in the prior literature \cite{Luque_2006,Oeding02012016}. Oeding and Sam give a very explicit formula for this invariant in \cite{Oeding02012016}. We verify that $f_6$ does not vanish on $\mathcal{C}_1$. This suffices since $\text{Sym}^6(\mathcal{C}_1^*)^{W(\mathcal{C}_1)}$ is 1-dimensional.

For degrees 8 and 12, we use ``filters,'' or invariants that vanish on product states, constructed by Ðoković and Osterloh from ``combs'' \cite{10.1063/1.3075830}. For an odd number of qubits, this comb approach only works for degrees divisible by 4. In the following, let $(c_1,c_2,c_3)=(-1,1,1)$ and $(\sigma_1,\sigma_2,\sigma_3)=(I,X,Z)$. To avoid introducing any new notation, we write down the polynomials explicitly. The degree 8 invariant is defined by
\begin{equation*}\label{eq:deg8}
\mathscr{G}_6^{(5)}(x)=\sum_{i_1,i_2,\dots,i_6=1}^{3} c_{i_1}c_{i_2}\dots c_{i_6}\left(\prod_{j=1}^4 x^\top E^{(j)}_{i_1,i_2,\dots,i_6}x \right),\quad \forall x\in(\CC^2)^{\otimes 5}
\end{equation*}
where
\begin{align*}
    E^{(1)}_{i_1,i_2,\dots,i_6}=\sigma_{i_1}\otimes \sigma_{i_2}\otimes \sigma_{i_3}\otimes Y\otimes Y,\qquad 
    E^{(2)}_{i_1,i_2,\dots,i_6}=\sigma_{i_4}\otimes \sigma_{i_2}\otimes \sigma_{i_3}\otimes Y\otimes Y,\\
    E^{(3)}_{i_1,i_2,\dots,i_6}=\sigma_{i_4}\otimes Y\otimes Y\otimes \sigma_{i_5}\otimes\sigma_{i_6},\qquad 
    E^{(4)}_{i_1,i_2,\dots,i_6}=\sigma_{i_1}\otimes Y\otimes Y\otimes \sigma_{i_5}\otimes\sigma_{i_6}.
\end{align*}
Note that $\mathscr{G}_6^{(5)}$ is a summand of the polynomial $\mathscr{F}_6^{(5)}$ from \cite{10.1063/1.3075830}. The degree 12 invariant is defined by
\begin{equation*}\label{eq:deg12}
\mathscr{F}_{12;2}^{(5)}(x)=\sum_{i_1,i_2,\dots,i_9=1}^3 c_{i_1}c_{i_2}\dots c_{i_9} \left(\prod_{j=1}^6 x^\top E^{(j)}_{i_1\dots i_9}x\right),\quad\forall x\in(\CC^2)^{\otimes 5}
\end{equation*}
where
\begin{align*}
E^{(1)}_{i_1\dots i_9}&=\sigma_{i_1}\otimes\sigma_{i_2}\otimes\sigma_{i_3}\otimes Y\otimes Y,\qquad E^{(2)}_{i_1\dots i_9}=\sigma_{i_1}\otimes\sigma_{i_2}\otimes\sigma_{i_4}\otimes Y\otimes Y, \\
E^{(3)}_{i_1\dots i_9}&=\sigma_{i_5}\otimes Y\otimes\sigma_{i_3}\otimes Y\otimes \sigma_{i_6},\qquad E^{(4)}_{i_1\dots i_9}=\sigma_{i_5}\otimes\ Y\otimes \sigma_{i_4}\otimes Y\otimes \sigma_{i_7}, \\
E^{(5)}_{i_1\dots i_9}&=\sigma_{i_8}\otimes Y\otimes Y\otimes \sigma_{i_9}\otimes \sigma_{i_6},\qquad E^{(6)}_{i_1\dots i_9}=\sigma_{i_8}\otimes Y\otimes Y\otimes \sigma_{i_9}\otimes\sigma_{i_7}.
\end{align*}
We verify that $\mathscr{G}_6^{(5)}$ does not vanish on $\mathcal{C}_1$. The invariants $\mathscr{F}_{12;2}^{(5)}$ and $f_6^2$ restrict to independent elements of $\CC[\mathcal{C}_1]$.
\end{proof}
\begin{theorem}\label{thm:second}
    Two states $\ket{\varphi},\ket{\psi}\in\mathcal{C}_1$ are $\SL_2^{\times 5}$-equivalent if and only if they are $W(\mathcal{C}_1)$-equivalent.
\end{theorem}
\begin{proof}
    By the definition of $W(\mathfrak{\mathcal{C}_1})$, if $\ket{\varphi}$ and $\ket{\psi}$ are $W(\mathcal{C}_1)$-equivalent, then they are $\SL_2^{\times 5}$-equivalent. Conversely, suppose that $\ket{\varphi}$ and $\ket{\psi}$ are $\SL_2^{\times 5}$-equivalent. By \Cref{thm:surj}, $\mathscr{I}_i=f_i|_\mathfrak{\mathcal{C}_1}$ for some $\SL_2^{\times 5}$-invariants $f_i$, so we must have $\mathscr{I}_i(\ket{\varphi})=f_i(\ket{\varphi})=f_i(\ket{\psi})=\mathscr{I}_i(\ket{\psi})$ for all $i\in \{6,8,12\}$. Since the $\mathscr{I}_i$ generate the invariant algebra, $\ket{\varphi}$ and $\ket{\psi}$ are in the same $W(\mathcal{C}_1)$-orbit (\Cref{thm:catquotient}).
\end{proof}

\begin{theorem}\label{thm:separating}
    Suppose $\ket{\psi},\ket{\varphi}\in(\CC^2)^{\otimes 5}$ are AME and let $\mathcal{S}=\{f_6,\mathscr{G}^{(5)}_6,\mathscr{F}^{(5)}_{12;2}\}$ be the set of polynomials from the proof of \Cref{thm:surj}. Two states $\ket{\psi},\ket{\varphi}\in(\CC^2)^{\otimes 5}$ are $\SL_2^{\times 5}$-equivalent if and only if $f(\ket{\varphi})=f(\ket{\psi})$ for all $f\in \mathcal{S}$.
\end{theorem}
\begin{proof}
    One direction is clear: if $\ket{\varphi}$ and $\ket{\psi}$ are $\SL_2^{\times 5}$-equivalent, then $f(\ket{\varphi})=f(\ket{\psi})$ for all $f\in \mathcal{S}$. By \Cref{thm:first}, $\ket{\varphi}$ and $\ket{\psi}$ are $\SU_2^{\times 5}$-equivalent to points $\ket{\varphi'}$ and $\ket{\psi'}$ in $\mathcal{C}_1$. If $f(\ket{\varphi})=f(\ket{\psi})$ for all $f\in \mathcal{S}$, then by the proof of \Cref{thm:surj} we have $g(\ket{\varphi'})=g(\ket{\psi'})$ for every $W(\mathcal{C}_1)$-invariant $g\in\CC[\mathcal{C}_1]$. By \Cref{thm:catquotient}, $\ket{\varphi'}$ and $\ket{\psi'}$ are equivalent and so are $\ket{\varphi}$ and $\ket{\psi}$.
\end{proof}

