The loop-diagram contributions to the third-order $T$-matrices, $\mathcal{T}_{\phi B}^{(\text{N2LO})}$, are explicitly derived in ref.~\cite{Liu:2006xja}. After performing scale-independent renormalization, we have
\begin{align}
\label{tpisigman2lo}
    \mathcal{T}_{\pi^+\Sigma^+}^{(\text{N2LO})}=\frac{m_\pi^2}{8\pi^2 f_\pi^4}\Big\{-\frac{3}{2}m_\pi-\sqrt{m_K^2-m_\pi^2}\arccos\frac{m_\pi}{m_K}+\frac{\pi}{2}\Big[3F^2m_\pi-\frac{1}{3}D^2m_\eta\Big]\Big\},
\end{align}
\begin{align}
\label{tpixin2lo}
    \mathcal{T}_{\pi^+\Xi^0}^{(\text{N2LO})}=&\frac{m_\pi^2}{16\pi^2 f_\pi^4}\Big\{-\frac{3}{2}m_\pi-\sqrt{m_K^2-m_\pi^2}\Big(\pi+\arccos\frac{m_\pi}{m_K}\Big)\nonumber\\
    &+\frac{\pi}{4}\Big[3(D-F)^2m_\pi-\frac{1}{3}(D+3F)^2m_\eta\Big]\Big\},
\end{align}
\begin{align}
\label{tkpn2lo}
    \mathcal{T}_{K^+p}^{(\text{N2LO})}=&\frac{m_K^2}{16\pi^2 f_K^4}\Big\{-3 m_K+2\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}-3\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
    &-\frac{\pi}{6}(D-3F)\Big[2(D+F)\frac{m_\pi^2}{m_\eta+m_\pi}+(D+5F)m_\eta\Big]\Big\},
\end{align}
\begin{align}
\label{tknn2lo}
    \mathcal{T}_{K^+n}^{(\text{N2LO})}=&\frac{m_K^2}{16\pi^2 f_K^4}\Big\{-\frac{3}{2} m_K+\frac{5}{2}\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}-\frac{3}{2}\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
    &+\frac{\pi}{3}(D-3F)\Big[(D+F)\frac{m_\pi^2}{m_\eta+m_\pi}+\frac{1}{2}(3D-F)m_\eta\Big]\Big\},
\end{align}
\begin{align}
\label{tk0barxin2lo}
    \mathcal{T}_{\bar{K}^0\Xi^0}^{(\text{N2LO})}=&\frac{m_K^2}{16\pi^2 f_K^4}\Big\{-3 m_K+2\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}-3\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
    &-\frac{\pi}{6}(D+3F)\Big[2(D-F)\frac{m_\pi^2}{m_\eta+m_\pi}+(D-5F)m_\eta\Big]\Big\}.
\end{align}

At the fourth order $\mathcal{O}(p^4)$, one also has $T$-matrices from one-loop diagrams generated by the vertices of $\mathcal{L}_{\phi B}^{(2)}$, $\mathcal{L}_{\phi B}^{(1)}$ and $\mathcal{L}_{\phi \phi}^{(2)}$ are shown in Fig.~\ref{fig:oneloopfeynman}. After performing tedious calculations, the loop-diagram contributions to the fourth-order $T$-matrices, $\mathcal{T}_{\phi B}^{(\text{N3LO})}$, are given by
\begin{align}
\label{tpisigman3lo}
      \mathcal{T}_{\pi^+\Sigma^+}^{(\text{N3LO})}=\frac{1}{\pi^2 f_\pi^4}\Big\{\alpha_{1}m_\pi^4+\beta_{1}m_K^4+\gamma_{1}m_\pi^2m_K^2+\delta_{1}\sqrt{m_K^2-m_\pi^2}\arccos\frac{m_\pi}{m_K}\Big\},
\end{align}
\begin{align}
\label{tpixi0n3lo}
      \mathcal{T}_{\pi^+\Xi^0}^{(\text{N3LO})}=&\frac{1}{\pi^2 f_\pi^4}\Big\{\alpha_{2}m_\pi^4+\beta_{2}m_K^4+\gamma_{2}m_\pi^2m_K^2+\delta_{2}\sqrt{m_K^2-m_\pi^2}\arccos\frac{m_\pi}{m_K}\nonumber\\
      &+\epsilon_2\sqrt{m_K^2-m_\pi^2}\arccos\frac{-m_\pi}{m_K}\Big\},
\end{align}
\begin{align}
\label{tkpn3lo}
      \mathcal{T}_{K^+p}^{(\text{N3LO})}=&\frac{1}{\pi^2 f_K^4}\Big\{\alpha_{3}m_\pi^4+\beta_{3}m_K^4+\gamma_{3}m_\pi^2m_K^2+\delta_3\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
      &+\epsilon_3\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}\Big\},
\end{align}
\begin{align}
\label{tknn3lo}
      \mathcal{T}_{K^+n}^{(\text{N3LO})}=&\frac{1}{\pi^2 f_K^4}\Big\{\alpha_{4}m_\pi^4+\beta_{4}m_K^4+\gamma_{4}m_\pi^2m_K^2+\delta_4\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
      &+\epsilon_4\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}\Big\},
\end{align}
\begin{align}
\label{tkbar0xi0n3lo}
      \mathcal{T}_{\bar{K}^0 \Xi^0}^{(\text{N3LO})}=&\frac{1}{\pi^2 f_K^4}\Big\{\alpha_{5}m_\pi^4+\beta_{5}m_K^4+\gamma_{5}m_\pi^2m_K^2+\delta_5\sqrt{m_\eta^2-m_K^2}\arccos\frac{m_K}{m_\eta}\nonumber\\
      &+\epsilon_5\sqrt{m_K^2-m_\pi^2}\ln\frac{m_K+\sqrt{m_K^2-m_\pi^2}}{m_\pi}\Big\},
\end{align}
where the parameters $\alpha_i$, $\beta_i$, $\gamma_i$, $\delta_i$ and $\epsilon_i$ ($i=1, 2, 3, 4, 5$) can be found in Appendix~\ref{parameters}. The Gell-Mann-Okubo (GMO) relation $m_\eta=\sqrt{(4m_K^2-m_\pi^2)/3}$ has also been used to simplify the equations.

\section{Scattering lengths}
\label{scattering lengths}
The $S$-wave scattering length is defined by
\begin{align}
\label{eq:pscatteringlength}
    a=\frac{1}{4\pi}\frac{M_B}{m_\phi+M_B}T_{\phi B},
\end{align}
where $m_\phi$ is the meson mass and $M_B$ is the baryon mass. We take the sign convention where a repulsive interaction corresponds to a negative scattering length. The chiral expansion may not converge when truncated at finite order, introducing uncontrolled systematic errors. For reliable predictions, the $T$-matrix can be iterated to infinite order. As in ref.~\cite{Kaiser:1995eg}, we use a Lippmann-Schwinger equation with a momentum cutoff scale $\mu$ to obtain finite results. For a single-channel separable potential, the scattering length is given by
\begin{align}
\label{eq:iscatteringlength}
    a=a_{\text{Born}}\Big(1-\frac{1}{2}\mu\, a_{\text{Born}}\Big)^{-1}.
\end{align}
Here, $a_{\text{Born}}$ incorporates contributions from all diagrams with the exception of the iterated diagrams (e) and (f) in Fig.~\ref{fig:oneloopfeynman} of this work, as well as the fourth diagram in Fig.~1 of ref.~\cite{Liu:2006xja}. We only need to subtract the contributions from these three iterated diagrams where the internal and external mesons coincide, which can be obtained through the iteration of first- and second-order tree diagrams. In our convention, these contributions can be derived by multiplying $m_\phi/(8\pi^2)$ with the corresponding first- and second-order tree-level amplitudes. Thus, our calculation includes all contributions from tree, renormalization, and crossed diagrams up to the fourth order in the potential iteration. As a result, the scattering lengths do not explicitly include the imaginary parts.

\section{Results and discussion}
\label{results}
Before making predictions, we need to determine the LECs. We employ two distinct approaches to constrain these parameters: a conventional least-squares fitting method and a Bayesian statistical analysis framework.

\subsection{Least-squares fitting}

We determine the low-energy constants $b_{D,F,0,1,2,3,4}$, $\bar{h}_{1}$, $\bar{h}_{123}$, and $\bar{e}_{1,2}$ through a least-squares fit to lattice QCD data. The goodness-of-fit is quantified by the $\chi^2$ function \cite{Dobaczewski:2014jga,Carlsson:2015vda}:
\begin{align}
\label{chi2}
    \chi^2=\sum_{i=1}^{N_d}\frac{(a_{i}^{\text{ChPT}}-a_{i}^{\text{Lattice}})^2}{\Delta a_{i}^2},
\end{align}
where $a_i^{\text{ChPT}}$ denotes the scattering lengths calculated from our chiral expansions, $a_i^{\text{Lattice}}$ represents the corresponding lattice QCD results from ref.~\cite{Torok:2009dg}, and $\Delta a_i$ is the combined uncertainty calculated by adding in quadrature the statistical and systematic uncertainties from the lattice QCD results. We use lattice data for five scattering processes: $\pi^{+}\Sigma^{+}$, $\pi^{+}\Xi^{0}$, $K^{+}p$, $K^{+}n$, and $\bar{K}^{0}\Xi^{0}$, including their scattering lengths, hadron masses and decay constants. We also use the Gell-Mann-Okubo (GMO) mass relation and $f_\eta = 1.3 f_\pi$ in all calculations.

The lattice data are calculated using unphysical quark masses, which leads to a larger mass for the light meson ($\sim 700$ MeV). However, the chiral expansions are based on the ratio $m_\phi/\Lambda_\chi$, where $m_\phi$ is the light meson mass and $\Lambda_{\chi}=1/(4\pi f_\pi)$ is the chiral symmetry breaking scale. The large meson mass might cause convergence issues in these expansions. Additionally, the predicted scattering length should not depend on the model choices. To address this, we perform two analyses: Fit LSp implements a fully perturbative treatment using Eq.~(\ref{eq:pscatteringlength}), while Fit LSu employs a non-perturbative approach based on Eq.~(\ref{eq:iscatteringlength}). This allows us to check the consistency of our predictions.

