   \subsection{The signs}\label{Sign}

    For $\Sigma = \Sigma_{g,p}$ with $c_1, \cdots, c_p$ the preferred peripheral elements of $\fund.$  The \emph{sign} of a representation $\phi\in\HP(\Sigma)$ is a $p$-tuple $s(\phi)=(s_1,\dots,s_p)$ in $\{-1,0,+1\}^p$  with 
    \begin{equation*}
   s_i = \left\{
    \begin{array}{rl}
       +1,  &  \text{if } \phi(c_i) \text{ is positive parabolic}\\
        0, & \text{if } \phi(c_i) \text{ is hyperbolic}\\ 
        -1, &  \text{if } \phi(c_i) \text{ is negative parabolic},
    \end{array}\right.
    \end{equation*}
$i\in\{1,\dots,p\}.$
    Since the type of an element of $\psl$ is invariant under $\psl-$conjugation, the sign of $\phi$ is independent on the choice of the preferred peripheral elements $c_i$'s. In the rest of this paper, for an $s\in \{-1,0,+1\}^p$, we respectively let  $p_+(s),$ $p_0(s)$ and $p_-(s)$ be the number of $1$'s, $0$,s and $-1$'s in the components of  $s$.

   Similar to the relative Euler class, the sign also defines an integer valued continuous function on $\HP(\Sigma),$ hence is a constant on each connected subspace of $\HP(\Sigma).$   As a consequence, it provides a necessary condition for two representations to lie in the same connected component of a subspace of $\HP(\Sigma)$: If  $\phi$ and $\psi$ are connected by a path in $\HP(\Sigma)$, then  $s(\phi) = s(\psi)$.
   \bigskip



   The following lemma provides a convenient way to determine the sign of a parabolic element.  

    \begin{lemma}\label{lem_offdiag} 
        For $n\in \mathbb{Z}$ and a parabolic element $\widetilde{A}\in \mathrm{Par}_n$ of $\univcover,$ let  $s(\widetilde{A})\in\{\pm\}$ be its sign, i.e., $s(\widetilde{A})=+$ if $\widetilde{A}\in \mathrm{Par}^+_n,$ and $s(\widetilde{A})=-$ if $\widetilde{A}\in \mathrm{Par}^-_n.$ Let $A$ be the projection of $\widetilde{A}$ to $\SL$, and for $i,j\in\{1,2\}$ let $a_{ij}$ be the $(i,j)$-entry of $A.$ Then either $a_{12}\neq0$ or $a_{21}\neq 0.$  Furthermore,

        \begin{enumerate}[(1)]
       \item If $n$ is even, then $s(\widetilde{A})=sgn(a_{12})$ if $a_{12}\neq 0,$ and $s(\widetilde{A})=-sgn(a_{21})$ if $a_{21}\neq 0.$

    \item If $n$ is odd, then $s(\widetilde{A})=-sgn(a_{12})$ if $a_{12}\neq 0,$  and $s(\widetilde{A})=sgn(a_{21})$ if $a_{21}\neq 0.$
    \end{enumerate}
    \end{lemma}

    \begin{proof}  Recall that a parabolic element  of $\psl$ is \emph{positive} if it is conjugate to $\pm\parpp,$ and is \emph{negative} if it is conjugate to $\pm \parmp;$ and a parabolic element in the universal covering $\widetilde{\SL}$ of $\psl$ is \emph{positive} or \emph{negative} if its projection to $\psl$ is so. 
    Therefore, by the definition, if $\widetilde{A}$ is positive, then $A$ is conjugate to $\parpp$ when $n$ is even, and is conjugate to $-\parpp$ when $n$ is odd. This means $A = \pm \abcd\parpp\abcd^{-1}
        = \pm \begin{bmatrix}
                1-ac & a^2 \\
                -c^2 & 1+ac
          \end{bmatrix}$ for some matrix $\abcd$ in $\SL,$ again, $+$ when $n$ is even and $-$ when $n$ is odd.  Note that $ad - bc = 1$ implies that at least one of $a$ and $c$ is nonzero. As a consequence, in the case that $n$ is even, if $a\neq 0,$ then $a_{12}=a^2>0,$ and if $c\neq 0,$ then $a_{21}=-c^2<0;$ and in the case that $n$ is odd, if $a\neq 0,$ then $a_{12}=-a^2<0,$ and if $c\neq 0,$ then $a_{21}=c^2>0.$  Similarly, if $A$ is negative, then $A$ is conjugate to $\parmp$ when $n$ is even, and is conjugate to $-\parmp$ when $n$ is odd; and we have $A =\pm \abcd\parmp\abcd^{-1}
        = \pm \begin{bmatrix}
                1+ac & -a^2 \\
                c^2 & 1-ac
          \end{bmatrix}.$ As a consequence, in the case that $n$ is even, if $a\neq 0,$ then $a_{12}=-a^2<0,$ and if $c\neq 0,$ then $a_{21}=c^2>0;$ and in the case that $n$ is odd,  if $a\neq 0,$ then $a_{12}=a^2>0,$ and if $c\neq 0,$ then $a_{21}=-c^2<0.$
    \end{proof} 

The following proposition describes the behavior of the relative Euler class and the sign under the $\pgl\setminus\psl$-conjugations.

    \begin{proposition}\label{prop_pglpsl} 
    Let $h$ be an element of $\pgl\setminus \psl$; and for a representation $\phi\in\HP(\Sigma),$ let $h \phi h^{-1}:\pi_1(\Sigma)\to\psl$ be  defined by 
    $h \phi h^{-1}(c)=h \phi(c)h ^{-1}$
 for each $c\in\pi_1(\Sigma).$  Then $h \phi h^{-1}\in\HP(\Sigma)$ with the relative Euler class $e(h \phi h^{-1})=-e(\phi)$ and the sign $s(h \phi h^{-1})=-s(\phi).$    
    \end{proposition}

\begin{proof} Let $J=\pm \begin{bmatrix}
        0 & 1 \\
        1 & 0
    \end{bmatrix}\in\pgl\setminus\psl$. As every element of $\pgl\setminus \psl$ has the form $Jg$ for some  $g$ in $\psl,$ up to a $\psl$-conjugation of $\phi$, we can assume that $h=J.$ Then we observe that for $\pm A = \pm \abcd\in\psl,$ 
    $\pm JAJ^{-1}
    = \pm \begin{bmatrix}
        d & c \\
        b & a
    \end{bmatrix}
    $, and hence $|\tr(\pm A)|=|\pm JAJ^{-1}|=|a+d|$, and $\pm A$ and $\pm JAJ^{-1}$ share the same type. As a consequence, $h\phi h^{-1}\in \HP(\Sigma).$ Furthermore, if both $\pm A$ and $\pm JAJ^{-1}$ are parabolic, then by Lemma \ref{lem_offdiag} they have the opposite sign. This implies that the sign $s(h \phi h^{-1})=-s(\phi).$ The relationship of the relative Euler classes is included in \cite[Proof of Proposition 4.6]{goldman}. 
    \end{proof}



    \subsection{Some other results of Goldman}\label{Other}


In this subsection, we recall the known results that is needed for the proof in this paper. The two lemmas below will be needed for punctured surfaces of Euler characteristic $-2$, namely, the two-hole torus $\Sigma_{1,2}$ and the four-hole sphere $\Sigma_{0,4}.$


    \begin{lemma}\cite[Lemma 9.3]{goldman}\label{lem_inthyptorus}
    	Let $\Sigma = \Sigma_{1,2}$
        %be a surface of genus one with two boundary components 
        with $c_1, c_2$ the peripheral elements of $\fund$. Let $d=(c_1c_2)^{-1}$ be the element of $\pi_1(\Sigma)$ which is represented by a simple closed curve that separates $\Sigma$ into a one-hole torus $T$  and a three-hole sphere $P$.
        Let $\phi\in \hom$ such that $\phi\big(\pi_1(P)\big)$ and $\phi\big(\pi_1(T)\big)$ are non-abelian. Then,
        there exists a path $\{\phi_t\}_{t\in [0,1]}$ in $\hom$
         such that:
         \begin{enumerate}[(1)]
            \item $\phi_0 = \phi$,
            \item for all $t\in [0,1]$, $\phi_t|_{\pi_1(P)}$ and $\phi_t|_{\pi_1(T)}$ are non-abelian,
            \item for all $t\in [0,1]$ and $i\in\{1,2\},$ $\phi_t(c_i)$ is conjugate to $\phi(c_i)$, and
            \item $\phi_1(d)$ is hyperbolic.
            \end{enumerate}
    \end{lemma}


    \begin{lemma}\cite[Lemma 9.6]{goldman}\label{lem_inthyppants}
    Let $\Sigma = \Sigma_{0,4}$
        %be a surface of genus one with two boundary components, 
        with $c_1, c_2, c_3, c_4$ the  peripheral elements in $\fund$. Let $d=(c_1c_2)^{-1}$ be the element of $\pi_1(\Sigma)$ which is represented by a simple closed curve that separates $\Sigma$ into two  three-hole spheres $P_1$ and $P_2$.
        Let $\phi\in \hom$ such that $\phi\big(\pi_1(P_1)\big)$ and $\phi\big(\pi_1(P_2)\big)$ are non-abelian. 
        Suppose in addition  that there exists an $i\in \{1,2,3,4\}$ such that $\phi(c_i)$ is hyperbolic.
        Then there exists a path $\{\phi_t\}_{t\in [0,1]}$ in $\hom$ such that:
        \begin{enumerate}[(1)]
            \item $\phi_0 = \phi$,
            \item for all $t\in [0,1]$, $\phi_t|_{\pi_1(P_1)}$ and $\phi_t|_{\pi_1(P_2)}$ are non-abelian,
            \item for all $t\in [0,1]$ and $i\in\{1,2,3,4\}$,  $\phi_t(c_i)$ is conjugate to $\phi(c_i)$, and 
       \item $\phi_1(d)$ is hyperbolic.
       \end{enumerate}
    \end{lemma}
