    \begin{lemma}\label{lem_conjugacypath_const}
        Let $\pm A$ be an element of $\psl\setminus \{\pm \mathrm I\}$,
        %a parabolic element or a hyperbolic element of $\psl$, 
        and let $\{\pm A_t\}\interval$ 
        be a continuous path in $\psl$ with $\pm A_0 = \pm A$. 
