    \subsubsection{Type-preserving representations}\label{subsection_TP}



    Finally, we describe the connected components of the space $\mathcal R (\Sigma_{0,3})$ of type-preserving representations. 
    Let $e: \mathcal R(\Sigma_{0,3})\to \mathbb{Z}$ be the relative Euler class map and  $s: \mathcal R(\Sigma_{0,3})\to \{\pm 1\}^3$ be the sign map defined respectively by sending $\phi$ to the relative Euler class $e(\phi)$ and the sign $s(\phi)$ of $\phi.$
    For $n\in \mathbb{Z}$, let 
    $\mathcal R_n(\Sigma_{0,3}) = e^{-1}(n)$.
   Then by Proposition \ref{prop_evimage}, $\mathcal R_n(\Sigma_{0,3})$ is non-empty if and only if $n\in \{-1,0,1\}.$ 



    \begin{theorem}\label{thm_pants} For $n\in \mathbb{Z}$ and $s\in\{\pm 1\}^3,$  let $\mathcal R^s_n(\Sigma_{0,3}) = e^{-1}(n)\cap s^{-1}(s)$. 

    \begin{enumerate}[(1)]


\item $\mathcal R_{-1}^s(\Sigma_{0,3})$ is non-empty if and only if  $s=(-1,-1,-1).$ 

\item $\mathcal R_{0}^s(\Sigma_{0,3})$ is non-empty if and only if,  up to a permutation of the peripheral elements, $s=(+1,-1,-1)$ or $(+1,+1,-1).$

\item $\mathcal R_{1}^s(\Sigma_{0,3})$ is non-empty if and only if $s=(+1,+1,+1).$

 \end{enumerate}
Moreover, all the non-empty spaces above are connected. 
\end{theorem}


