        Then by Theorem \ref{thm_pants2}, we have
         $e(\phi|_{\pi_1(P)}) = e(\psi|_{\pi_1(P)}) = \frac{1}{2}(s_1+s_2)$, and by Lemma \ref{lem_sameEuler_torus}, there exists a path in $\HPns(\Sigma_{1,2})$ connecting $\phi$ and $\psi$.
    \end{proof}


\subsection{Four-hole sphere}\label{subsection_pantstwo}


        The fundamental group of the four-hole sphere $\Sigma_{0,4}$ has the following presentation
     $$\pi_1(\Sigma_{0,4}) = \langle 
