    \begin{enumerate}[(1)]
        \item  $n = 0,$ and either $p_-(s) = 1$ or $p_+(s)=1$, and
        \item  $n = 1$ and $p_-(s) = 0$,  or $n = -1$ and $ p_+(s) = 0$.
    \end{enumerate} 

    The following Theorem \ref{thm_pantstype4} proves Theorem \ref{thm_main2} for $\Sigma = \Sigma_{0,4}$ for the non-exceptional pairs, and the case for the exceptional pairs will be discussed in Section 7. 


    \begin{theorem}\label{thm_pantstype4}
        Let $n\in \mathbb{Z}$, $s\in\{\pm 1\}^4$ such that the pair $(n,s)$ is not exceptional.
        Then $\mathcal{R}^s_n(\pantstwo)$ is non-empty if and only if 
       $$\chi(\Sigma_{0,4}) + p_+(s)\leqslant n \leqslant -\chi(\Sigma_{0,4}) - p_-(s).$$ 
        Moreover, each non-empty $\mathcal{R}^s_n(\pantstwo)$ above is connected.
    \end{theorem}
    \begin{remark}
        Theorem \ref{thm_pantstype4} can also be found in \cite{yang}, where the connected components of the space of  $\psl$-characters  of irreducible type-preserving representations were characterized.
