    \subsection{Abelian representations}
    In this subsection, we will prove Theorem \ref{thm_main2} for Case (2). Moreover, we will show that the corresponding components $\mathcal{R}^s_n(\Sigma)$ consist entirely of abelian representations. This also explains why Theorem \ref{thm_nonabel}, and consequently, Theorem \ref{thm_general} fail in this case. 
    These results are stated as Theorem \ref{thm_Exc1} below.



    \begin{theorem}\label{thm_Exc1}
        Let $\Sigma = \Sigma_{0,p}$ with $p\geqslant 3$, and let $s\in \{\pm 1\}^p$ with $\ p_+(s) = 1 \mbox{ or }p_-(s) = 1.$ Then 
        $\mathcal{R}^s_0(\Sigma)$ is non-empty, connected, and consists of abelian representations. 
        %$\mathcal{R}^s_0(\Sigma)$ is a connected component of $\R$ that consists of abelian representations of sign $s$.
    \end{theorem}
    \begin{proof}
       As the case that $p = 3$ is proved by Theorem \ref{thm_pants} and Lemma \ref{lem_R0pants}, we only need to consider the case that $p\geqslant 4$. We will prove the result for the case that $p_+(s)=1$. Then the result for the remaining case that $p_-(s)=1$ follows from the previous case and Proposition \ref{prop_pglpsl}.
       \\


       Up to a permutation of the peripheral elements we can assume that $s_1 = +1$ and $s_2=\cdots=s_p= -1$. To show that $\mathcal{R}^s_0(\Sigma)$ is non-empty, we define a  representation $\phi$ by letting 
        $\phi(c_1) = \pm \begin{bmatrix}
                        1 & p-1\\
                        0 & 1
                    \end{bmatrix}$ and 
        $\phi(c_i) = \pm \parmp$ for each $i\in \{2,\cdots, p\}$, which is an abelian representation and is in $\mathcal{R}^s_0(\Sigma)$ by Proposition \ref{prop_reducible}.
        \medskip 

        Next, we prove that every representation $\phi$ in $\mathcal{R}^s_0(\Sigma)$ is abelian.
        Let $ \displaystyle\bigcup_{i=1}^{p-2} P_i$ be the chosen almost-path decomposition of $\Sigma$.
        We will first show that $\phi |_{\pi_1(P_i)}$ is abelian for all $i\in\{1,\dots,p-2\}$, then use this to show that $\phi$ is abelian on the entire $\pi_1(\Sigma)$.

        We use contradiction. Suppose otherwise that $\phi|_{\pi_1(P_i)}$ is non-abelian for some $i\in \{1,\cdots, p-2\}$. 
        Then by Proposition \ref{prop_NAsphere1}, we can assume that $\phi\in \mathrm{NA}^s_0(\Sigma)$; and since $s_1 = -s_2$, by Lemma \ref{lem_inthyp_sphere}, $\phi(d_1)$ is hyperbolic. 
        As the fundamental group $\pi_1(P_1)$ has the preferred peripheral elements $c_1, c_2$ and $d_1$ with $\phi(c_1)\in \Par^+, \phi(c_2)\in \Par^-$ and $\phi(d_1)\in \Hyp$, we have 
        $\phi|_{\pi_1(P_1)}\in \HP(P_1)$ with sign $s\big(\phi|_{\pi_1(P_1)}\big) = (+1, -1, 0)$; and by Theorem \ref{thm_pants2}, it follows that the relative Euler class $e\big(\phi|_{\pi_1(P_1)}\big) = 0$.
        Similarly, as the fundamental group $\pi_1(\Sigma\setminus P_1)$ has the preferred peripheral elements $c_3,\cdots, c_p$ and $d_1^{-1}$ with $\phi(c_i)\in \Par^-$ for 
    $i\in \{3,\cdots, p\}$ and $\phi(d_1^{-1})\in \Hyp$, we have 
    $\phi|_{\pi_1(\Sigma \setminus P_1)}\in \HP(\Sigma \setminus P_1)$ with sign $s\big(\phi|_{\pi_1(\Sigma\setminus P_1)}\big) = (-1,\cdots, -1, 0)$.
    As $p_0\big(s\big(\phi|_{\pi_1(\Sigma\setminus P_1)}\big)\big) = 1$, the triple $\big(\Sigma\setminus P_1, e(\phi|_{\pi_1(\Sigma \setminus P_1)}), s(\phi|_{\pi_1(\Sigma \setminus P_1)})\big)$ is not exceptional, hence by Theorem \ref{thm_general}  satisfies the generalized Milnor-Wood inequality
     $$\chi(\Sigma \setminus P_1) + p_+\big(s(\phi|_{\pi_1(\Sigma \setminus P_1)})\big)\leqslant e(\phi|_{\pi_1(\Sigma \setminus P_1)})\leqslant -\chi(\Sigma \setminus P_1) - p_-\big(s(\phi|_{\pi_1(\Sigma \setminus P_1)})\big).$$
     As $\chi(\Sigma\setminus P_1) = 3-p$ %$p_+\big(s(\phi|_{\pi_1(\Sigma \setminus P_1)})\big) = 0$ 
     and $p_-\big(s(\phi|_{\pi_1(\Sigma \setminus P_1)})\big) = p-2$, it follows that
     $e(\phi|_{\pi_1(\Sigma \setminus P_1)})\leqslant -1$. Then as
     $e\big(\phi|_{\pi_1(P_1)}\big) = 0$, by Proposition \ref{prop_additivity}, we have 
     $0 = e\big(\phi|_{\pi_1(P_1)}\big) + e\big(\phi|_{\pi_1(\Sigma \setminus P_1)}\big)\leqslant -1$, which is a contradiction. %In conclusion, for all $i\in \{1,\cdots, p-2\}$, $\phi |_{\pi_1(P_i)}$ is abelian. 

     We now prove that $\phi$ is abelian on $\pi_1(\Sigma)$. For each $i\in \{1,\cdots, p-2\}$, as $\phi|_{\pi_1(P_i)}$  is abelian, the image $\phi\big(\pi_1(P_i)\big)$ lies in a one-parameter subgroup $S_i$ of $\psl$; and for each $i\in \{1,\cdots, p-3\}$, either $S_i =S_{i+1}$ or $S_i\cap S_{i+1} = \{\pm \mathrm I\}$. We will show that 
         $S_i =S_{i+1}$ for all $i\in \{1,\cdots, p-3\}$, and conclude that the entire image $\phi\big(\pi_1(\Sigma)\big)$ lies in the one-parameter subgroup $S_1$, and hence $\phi$ abelian. 
         Suppose that $S_i \neq S_{i+1}$ for some $i\in \{1,\cdots, p-3\}$. Then $S_i\cap S_{i+1} = \{\pm \mathrm I\}$, and as an element in $\phi\big(\pi_1(P_i)\big)\cap  \phi\big(\pi_1(P_{i+1})\big)\subset S_i\cap S_{i+1}$, $\phi(d_i) = \pm \mathrm I$. 
         Since there exists an $i\in \{1,\cdots, p-3\}$ where $\phi(d_i) = \pm \mathrm I$, we can choose the largest $i_0\in\{1,\cdots, p-3\}$  such that $\phi(d_{i_0}) = \pm \mathrm I$. 
         If $i_0 = p-3$, then as $\phi(c_{p-1})\phi(c_p) = \phi(d_{p-3}) = \pm \mathrm I$, we have $\phi(c_{p-1}) = \phi(c_p)^{-1}$, contradicting that both $\phi(c_{p-1})$ and $\phi(c_p)$ are in $\Par^-$.
         If otherwise that $i_0 \leqslant p-4$, we let $\Sigma' \doteq \displaystyle\bigcup^{p-2}_{i = i_0+2} P_i$. 
         The fundamental group $\pi_1(\Sigma')$ has the preferred peripheral elements $c_{i_0+3},\cdots, c_p$ and $d_{i_0+1}^{-1}$, and for $k\in \{i_0+3,\cdots, p\}$, we have $\phi(c_k)\in \Par^-$. Moreover, since $\phi(d_{i_0}^{-1}) = \pm \mathrm I$ and $\phi(c_{i_0+2})\in \Par^-$, we have 
         $\phi(d_{i_0 + 1}^{-1}) = \phi(d_{i_0}^{-1})\phi(c_{i_0+2})\in \Par^-$. Therefore, $\phi|_{\pi_1(\Sigma')}$ is type-preserving, and $p_+\big(s\big(\phi|_{\pi_1(\Sigma')}\big)\big) = 0$. 
         However, as $\phi |_{\pi_1(P_i)}$ is abelian for all $i\in \{i_0+2,\cdots, p-2\}$, $p_+\big(s\big(\phi|_{\pi_1(\Sigma')}\big)\big)\geqslant 1$ by Lemma \ref{lem_abelsphere}, which is a contradiction. Therefore, $S_i =S_{i+1}$ for all $i\in \{1,\cdots, p-3\}$; and as a consequence, $\phi$ is abelian.
         \\

        Finally, we prove that $\mathcal{R}^s_0(\Sigma)$ is connected. 
        Let $\phi_1, \phi_2\in \mathcal{R}^s_0(\Sigma)$. For each $j\in \{1,2\}$, since $\phi_j(c_1)\in \Par^+$, there is a $g_j\in \psl$ such that $g_j\phi_j(c_1)g_j^{-1} = \pm \parpp$.
        Let $\{g_{j,t}\}\interval$ be a path in $\psl$ connecting $\pm\mathrm{I}$ to $g_j$. % in the one-parameter subgroup of $\psl$ generated by $g_1.$ 
         Then the path $\{\phi_{j,t}\}\interval$ defined by $\phi_{j,t}\doteq g_{j,t}\phi_j g_{j,t}^{-1}$ connects $\phi_j$ to $\phi_{j,1} = g_j\phi_jg_j^{-1}$.
        Since $\phi_j \in \mathcal{R}^s_0(\Sigma)$ is abelian, its $\psl$-conjugation $\phi_{j,1}$ is also abelian; and the image $\phi_{j,1}\big(\pi_1(\Sigma)\big)$
        lies in the one-parameter subgroup of $\psl$ that contains $g_j\phi_j(c_1)g_j^{-1}$, which is $\bigg\{\pm \part\bigg\}_{t\in \mathbb{R}}$. 
        Moreover, for each $j\in \{1,2\}$ and $t\in [0,1]$, since $\phi_{j,t}(c_i)$ and $\phi_j(c_i)$ are conjugate for all $i\in \{1,\cdots, p\}$, the signs $s(\phi_{j,t}) = s(\phi_j)$ and the relative Euler classes $e(\phi_{j,t}) = e(\phi_j)$. Therefore, the paths $\{\phi_{1,t}\}\interval$ and $\{\phi_{2,t}\}\interval$ are in $\mathcal{R}^s_0(\Sigma).$
        Now for each $i\in \{1,\cdots, p\}$ and each $j\in \{1,2\}$, 
        we let 
        $g_j\phi_j(c_i)g_j^{-1} = 
        \pm \begin{bmatrix}
        1 & \xi_{i,j} \\
        0 & 1
        \end{bmatrix}$ for some $\xi_{i,j}\in \mathbb{R}\setminus \{0\}$.
        To connect $g_1\phi_1g_1^{-1}$ and $g_2\phi_2g_2^{-1},$ we
        consider the path $\{\psi_t\}_{t\in [1,2]}$ given by $\psi_t(c_i) = \pm  \begin{bmatrix}
        1 & (2-t)\xi_{i,1}+(t-1)\xi_{i,2} \\
        0 & 1
        \end{bmatrix}$ for each $i\in \{1,\cdots, p\}$. 
        %Then $\psi_1 = g_1\phi_1g_1^{-1}$ and $\psi_2 = g_2\phi_2g_2^{-1}$, 
        Since $s(g_1\phi_1g_1^{-1})=s(g_2\phi_2g_2^{-1}),$ 
        for each $i\in \{1,\cdots, p\}$, 
        we have $sgn(\xi_{i,1})=sgn(\xi_{i,2})$, 
        and hence for all $t\in [1,2],$ we have $sgn\big((2-t)\xi_{i,1}+(t-1)\xi_{i,2}\big)=sgn(\xi_{i,1})$. 
        Therefore, for all $t\in [1,2]$, the signs $s(\psi_t)=s(g_1\phi_1g_1^{-1})$ 
         and the relative Euler classes $e(\psi_t)=e(g_1\phi_1g_1^{-1})$, and the path $\{\psi_t\}_{t\in [1,2]}$ is in $\mathcal R_0^s(\Sigma)$ connecting $g_1\phi_1g_1^{-1}$ and $g_2\phi_2g_2^{-1}.$ As a consequence, $\mathcal R_0^s(\Sigma)$ is connected. 
\end{proof}

\begin{remark}
        Theorem \ref{thm_Exc1} shows that $\mathcal{R}^s_0(\Sigma)$ with $p_+(s) = 1$ or $p_-(s) = 1$ consists of totally non-hyperbolic representations,
        as abelian type-preserving representations map all the simple closed curves (hence all the decomposition curves) to parabolic elements.
    \end{remark}


\subsection{Non-abelian representations}
    %Fix an almost-path decomposition $\Sigma = \displaystyle\bigcup_{i=1}^{p-2} P_i$ with decomposition curves $d_i = c_{i+2}\cdots c_p = \big(c_1\cdots c_{i+1}\big)^{-1}$, as constructed in Section 4.



    In this subsection, we will prove Theorem \ref{thm_main2} for Case (3). Moreover, we will show that the corresponding components $\mathcal{R}^s_n(\Sigma)$ consist entirely of totally non-hyperbolic representations. This also explains why Lemma \ref{lem_inthyp}, and consequently, Theorem \ref{thm_general} fail in this case. 
    These results are stated as Theorem \ref{thm_Exc2} below.

    \begin{theorem}\label{thm_Exc2}
        Let $\Sigma = \Sigma_{0,p}$ with $p\geqslant 3$, and let $s\in \{\pm 1\}^p$ with $\ p_-(s) = 0 \mbox{ or }p_+(s) = 0.$ Then 
        $\mathcal{R}^s_{s_1}(\Sigma)$ is non-empty, connected, and consists of totally non-hyperbolic representations. 
    \end{theorem}
