    We will first extend the lifted product map 
    $\ev: \overline{\Hyp}\times \overline{\Hyp}\to \widetilde{\SL}$
    defined in Subsection \ref{subsection_PLP} to $\psl\times \psl$ in Subsection \ref{subsection_PLP_Ell}, using which we will prove Theorem \ref{thm_Exc2} in Subsection \ref{subsection_exc2proof}.


\subsubsection{The evaluation map and the path-lifting properties}\label{subsection_PLP_Ell}

    In this subsection, we define the \emph{lifted product map}  
        $$\ev: \psl\times \psl\to \widetilde{\SL}$$
    by sending the pair $(g_1,g_2)$ to the product $\widetilde{g_1}
    \widetilde{g_2}$ of the unique lifts $\widetilde{g_1}$ and $
    \widetilde{g_2}$ of  $g_1$ and $g_2$  in $\overline{\Hyp_0}\cup \Ell_1$.
%Recall: the definition of product in universal covering 
    Recall that the product $\widetilde{g_1}\widetilde{g_2}$ in the universal cover $\widetilde{\SL}$ is defined as follows. For $i\in \{1,2\},$ let $\{\widetilde{g_{i,t}}\}\interval$ be a path connecting $\widetilde{g_{i,0}} = \mathrm{I}$ and $\widetilde{g_{i,1}} = \widetilde{g_i}$ in the one-parameter subgroup of $\univcover$ generated by $\widetilde{g_i},$ and let $\{g_{i,t}\}\interval$ be the projection of $\{\widetilde{g_{i,t}}\}\interval$ to $\psl$.
    Let $\{\widetilde{g_{1,t}g_{2,t}}\}\interval$ be the lift of the path $\{g_{1,t}g_{2,t}\}\interval$ in $\psl$ to  $\widetilde{\SL}$ starting from $\mathrm I.$ Then  $\widetilde{g_1}\widetilde{g_2}$ is the endpoint $\widetilde{g_{1,1}g_{2,1}}$ of the lifted path. Here we notice that   $\ev$ is not continuous on the whole $\psl\times\psl.$ See also \cite{deroin_tholozan} for a similar discussion.
    \\
     %In this subsection, we let $\Par_{\mathrm I}\doteq \tr^{-1}(2)\setminus  \{\mathrm I\}$ be a union of $\Par_{\mathrm I}^+$ and $\Par_{\mathrm I}^-$, which are respectively the projections of $\Par^+_0$ and $\Par^-_0$ in $\univcover$ onto $\SL$. Moreover, we let $\Ell^+$ and $\Ell^-$ respectively be the projections of $\Ell_1$ and $\Ell_{-1}$ in $\univcover$ onto $\SL$. 

     To define the evaluation maps and study their path-lifting properties, we need the following Lemma \ref{lem_offdiag_Ell} and Lemma \ref{lem_evimage_Ell}. %which provides a convenient way to determine whether an elliptic element in $\univcover$ is in $\Ell^+$ or $\Ell^-$.    

\begin{lemma}\label{lem_offdiag_Ell} 
        For $n\in \mathbb{Z}$ and an elliptic element $\widetilde{A}\in \mathrm{Ell}_n$ of $\univcover,$ let $A$ be its projection to $\SL$, and for $i,j\in\{1,2\}$ let $a_{ij}$ be the $(i,j)$-entry of $A.$ 
        Then $a_{12}\neq0$ and $a_{21}\neq 0.$  Moreover:
        \begin{enumerate}[(1)]
            \item 
            If $n$ is odd, then $sgn(n)=sgn(a_{12}) = -sgn(a_{21})$.

            \item 
            If $n$ is even, then $sgn(n)=-sgn(a_{12}) = sgn(a_{21})$.
        \end{enumerate}
    \end{lemma}
    \begin{proof} 
    Let $\widetilde{\exp}: \sl\to \univcover$ be the exponential map of $\univcover$.
        By the definition of $\Ell_n$, $\widetilde{A}\in \Ell_n$ is conjugate to $\widetilde{\exp}\begin{bmatrix}
        0 & \alpha \\
       -\alpha & 0 
    \end{bmatrix}$ for some $\alpha \in \big((n-1)\pi, n\pi\big)$ if $n>0$, and for
    some $\alpha \in \big(n\pi, (n+1)\pi\big)$ if $n<0$.
    Therefore, letting $\exp: \sl\to \SL$ be the exponential map of $\SL$,
    the projection $A$ of $\widetilde{A}$ is conjugate to 
    $\exp\begin{bmatrix}
        0 & \theta \\
       -\theta & 0 
    \end{bmatrix}
    = \begin{bmatrix}
        \cos\theta & \sin\theta \\
       -\sin\theta & \cos\theta
    \end{bmatrix}$ in $\SL$ for some $\theta\in (-\pi,0)\cup(0, \pi)$ 
    with $\theta \equiv \alpha \pmod{2\pi}$. 
    %for some $\theta\in (-\pi,0)\cup(0, \pi)$,
    It follows that
    $$A = \abcd
        \begin{bmatrix}
            \cos\theta & \sin\theta \\
            -\sin\theta & \cos\theta
        \end{bmatrix}
        \abcd^{-1}
        = \begin{bmatrix}
            \cos\theta - (ac+bd)\sin\theta & (a^2 + b^2)\sin\theta \\
            -(c^2 + d^2)\sin\theta & \cos\theta + (ac+bd)\sin\theta
        \end{bmatrix}$$ for some matrix $\abcd\in \SL$. 
        Since $ad - bc = 1$, at least one of $a$ and $b$ is nonzero, hence $a^2 + b^2 > 0$; and at least one of $c$ and $d$ is nonzero, hence $c^2 + d^2 > 0$. 
        In the case that $n$ is odd, if $n>0$ then $\theta\in (0,\pi)$, and hence 
        $a_{12} = (a^2+b^2)\sin\theta >0$ and $a_{21} = -(c^2+d^2)\sin\theta < 0$; and 
        if $n<0$ then $\theta\in (-\pi,0)$, and hence 
        $a_{12} = (a^2+b^2)\sin\theta <0$ and $a_{21} = -(c^2+d^2)\sin\theta > 0$. As a consequence, $a_{12}\neq 0$, $a_{21}\neq 0$, and $sgn(n) = sgn(a_{12}) = -sgn(a_{21})$. Similarly, in the case that $n$ is even, if $n>0$ then $\theta\in (-\pi,0)$, and hence 
        $a_{12} = (a^2+b^2)\sin\theta <0$ and $a_{21} = -(c^2+d^2)\sin\theta > 0$; and 
        if $n<0$ then $\theta\in (0,\pi)$, and hence 
        $a_{12} = (a^2+b^2)\sin\theta >0$ and $a_{21} = -(c^2+d^2)\sin\theta < 0$. As a consequence, $sgn(n)=-sgn(a_{12}) = sgn(a_{21})$.
    \end{proof} 
    \begin{lemma}\label{lem_evimage_Ell}Let $s\in \{\pm 1\}$, and let $\ev: \psl\times \psl\to \widetilde{\SL}$ be the lifted product map defined above.
    \begin{enumerate}[(1)] 

    \item $\ev\big(\Par^{sgn(s)} \times\Ell\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) = \Ell_1$.
    %\item For $(A,B)\in \Ell^{sgn(m)}\times \Par_{\mathrm I}^{sgn(s)}$, $\ev(A,B)\in \Ell_m$.
    \item $\ev\big(\Par^{sgn(s)} \times\Par^{sgn(s)} \big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) = \Ell_s$.
    \end{enumerate}
    \end{lemma}
    \begin{proof} 
    For (1), we first show 
    $\ev\big(\Par^{sgn(s)} \times\Ell\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big) \subset \Ell_1$ as follows. 
    Let $(g_1, g_2)\in \Par^{sgn(s)}\times \Ell$, and suppose that $\ev(g_1, g_2) \in \Ell_k$ for some $k\in \mathbb{Z}\setminus\{0\}$. 
    Let $\widetilde{g_1}$ be the lift of $g_1$ in $\Par^{sgn(s)}_0$, and let $\widetilde{g_2}$ be the lift of $g_2$ in $\Ell_1$.
    For $i\in \{1,2\},$ let $\{\widetilde{g_{i,t}}\}\interval$ be a path  connecting $\mathrm{I}$ and $\widetilde{g_i}$ in the one-parameter subgroup of $\univcover$ generated by $\widetilde{g_i},$ and let $\{g_{i,t}\}\interval$ be the projection of $\{\widetilde{g_{i,t}}\}\interval$ to $\psl$.
    Then the lift $\{\widetilde{g_{1,t}g_{2,t}}\}\interval$ of $\{g_{1,t}g_{2,t}\}_{t\in [0,1]}$ in $\widetilde{\SL}$ connects $\widetilde{g_{1,0}g_{2,0}} = \mathrm{I}$ to $\widetilde{g_{1,1}g_{2,1}} = \widetilde{g_1}\widetilde{g_2}$. Up to a $\psl-$conjugation, we can assume that $g_1 = \pm \begin{bmatrix}
        1 & s \\
        0 & 1
    \end{bmatrix}$; and by a re-parametrization if necessary, we can assume that 
        the projection $\{A_t\}\interval$ of the path $\{\widetilde{g_{1,t}}\}\interval$  in $\univcover$ to $\SL$ equals 
        $$A_t
        = \begin{bmatrix}
            1 & st \\
            0 & 1
        \end{bmatrix}$$
        for all $t\in [0,1].$ 
        Similarly, we can also assume that the projection $\{B_t\}\interval$ of the path $\{\widetilde{g_{2,t}}\}\interval$  in $\univcover$ to $\SL$ equals $$B_t=\abcd\begin{bmatrix}
            \cos(\theta t) & \sin(\theta t)\\
            -\sin(\theta t) & \cos(\theta t)
        \end{bmatrix}\abcd^{-1}$$
        for some $\theta\in (0,\pi)$ and $\abcd\in\SL$. % as $\widetilde{g_2}\in \Ell_1$\\
        Then the projection $\{A_tB_t\}\interval$ of the path $\{\widetilde{g_{1,t}g_{2,t}}\}\interval$  in $\univcover$ to $\SL$ equals 
          \begin{equation*}
          \begin{split}
          &A_tB_t=\\
           &\begin{bmatrix}
            \cos(\theta t) - (ac + bd)\sin(\theta t) - (c^2+d^2)st\sin(\theta t) 
               & (a^2+b^2)\sin(\theta t) + st \cos(\theta t) + (ac+bd)st\sin(\theta t) \\
               -(c^2 + d^2)\sin(\theta t) & \cos(\theta t) + (ac + bd)\sin(\theta t)
            \end{bmatrix}.
            \end{split}
            \end{equation*}
            %If $m =  +1$, 
            Since $ad - bc = 1$, at least one of $c$ and $d$ is nonzero, hence $c^2 + d^2 > 0$; and since $\theta\in (0, \pi)$, we have the $(2,1)$-entry $(A_tB_t)_{21} = -(c^2+d^2)\sin(\theta t) <0$ for all $t\in (0,1]$. 
            Then by Lemma \ref{lem_offdiag_Ell}, the path $\{\widetilde{g_{1,t}g_{2,t}}\}\interval$ intersects neither $\Ell_{-1}$ nor $\Ell_2$, hence lies in $\overline{\Hyp_0}\cup \overline{\Hyp_1}\cup \Ell_1$ as it is the connected component 
            of $\univcover\setminus \big(\Ell_{-1}\cup \Ell_2\big)$ that contains $\widetilde{g_{1,0}g_{2,0}} = \mathrm I$.
            As $\widetilde{g_{1,1}g_{2,1}} = \widetilde{g_1}\widetilde{g_2}$ is elliptic by the assumption, we have $\widetilde{g_{1,1}g_{2,1}}\in \Ell_1$. %Similarly, if $m = -1$, since $-\pi<\theta<0$ ensures  $(\widetilde{A_tB_t})_{21}>0$, Lemma \ref{lem_offdiag_Ell} implies that $\widetilde{(A_1B_1)}$ lies in $\Ell_{-1}$.
            \medskip

            Next, to show that 
    $\Ell_1\subset \ev\big(\Par^{sgn(s)} \times\Ell\big)\cap \big(\bigcup_{k\in \mathbb{Z}\setminus \{0\}}\Ell_k\big)$, 
    we consider $$g_1=\pm \begin{bmatrix}
        1 & s \\
        0 & 1
    \end{bmatrix}\quad\text{and}\quad g_2
        = \pm \begin{bmatrix}
        \cos\theta & \frac{1}{2}\sin\theta \\
        -2\sin\theta & \cos\theta
        \end{bmatrix}$$ for $\theta\in (0,\pi)$.  Then $\ev(g_1,g_2) = \widetilde{g_1}\widetilde{g_2}$ projects to the matrix 
         $$A_\theta = \begin{bmatrix}
        \cos\theta - 2s\sin\theta &  \frac{1}{2}\sin\theta + s\cos\theta  \\
        -2\sin\theta & \cos\theta
        \end{bmatrix}$$
           in $\SL$ with $\tr(A_\theta)=2(\cos\theta-s\sin\theta).$ 
             %defines a continuous one-parameter family $\bigg\{\begin{bmatrix}
            %    1 - \lambda - \lambda^2
            %    & 2 + \lambda  \\
            %    -\lambda^2 
            %    & 1 + \lambda
            %\end{bmatrix}\bigg\}_{\lambda\in [0,\infty)}$ in $\univcover$. 
            If $s = +1$, 
            then as $\theta$ varies from $0$ to $\frac{\pi}{2},$ the trace $\tr(A_\theta)=2(\cos\theta-\sin\theta)$ decreases from $2$ to $-2$; and 
            if $s = -1$, 
            then as $\theta$ varies from $\frac{\pi}{2}$ to $\pi,$ the trace $\tr(A_\theta)=2(\cos\theta+\sin\theta)$ decreases from $2$ to $-2$. Moreover, whenever $\tr(A_\theta)\in (-2,2)$, the corresponding $\widetilde{g_1}\widetilde{g_2}$ is elliptic as it projects to $A_\theta$ in $\SL$, hence lies in $\Ell_1$ as shown in the previous paragraph. 
