     Since $\widetilde{\phi_j(c_1)}$ and $\widetilde{\phi_j(c_2)}$ are in $\Par^{sgn(s)}_0$ for $j\in \{1,2\}$,
    we have the characters $\chi(\phi_1) = \chi(\phi_2) = (2,2,z)$ with $z = \tr \widetilde{C}$. Moreover, since $|z|<2$, 
    $\kappa(2, 2, z) = (z-2)^2 + 2 \neq 2$. 
    For $j\in \{1,2\}$,
    let $A_j$ and $B_j$ respectively be the projections of $\widetilde{\phi_j(c_1)}$ and $\widetilde{\phi_j(c_2)}$ in $\Par^{sgn(s)}_0$ to $\SL$.
    Since both $(A_1, B_1)$ and $(A_2, B_2)$ are in $\chi^{-1}(2,2,z)\subset \SL\times \SL$ with $\kappa(2, 2, z)\neq 2$, by Proposition \ref{prop_char}, $(A_1, B_1)$ and $(A_2, B_2)$ are $\GL$-conjugate; and they are $\SL$-conjugate as the parabolic elements $\phi_1(c_1)$ and $\phi_2(c_1)$ %, which are respectively the projections of $A_1$ and $A_2$, 
    have the same sign. (See the proof of Proposition \ref{prop_pglpsl}.) Let $P\in\SL$ be such that 
        $(A, B)
        = 
        \big(PA_2P^{-1}, PB_2P^{-1}\big),$ and let $g=\pm P$ be the projection of $P$ to $\psl.$ Then we have $\phi_2=g \phi_1 g^{-1}.$ 
        Let $\{g_t\}_{t\in [1,2]}$ be a path in $\psl$ connecting $g_1 =\pm \mathrm I$ and $g_2 = g$. Then
        the path $\{\phi'_t\}_{t\in [1,2]}$ defined by $\phi'_t \doteq g_t\phi_1 g_t^{-1}$ connects $\phi_1$ to $\phi_2$ in $\PP^s(\pants)$.
    \end{proof}




\subsubsection{Proof of Theorem \ref{thm_Exc2}}\label{subsection_exc2proof}
The proof of Theorem \ref{thm_Exc2} relies on the following Lemma \ref{lem_Exc2} and Proposition \ref{Prop_Exc2}.
\begin{lemma}\label{lem_Exc2}
    Let $\Sigma = \Sigma_{0,p}$ with $p\geqslant 3$, and let $s\in \{\pm 1\}^p$ with $p_-(s) = 0$ or $p_+(s) = 0$.
    Let $\phi$ and $\psi$ be totally non-hyperbolic representations with sign $s$ such that $\phi|_{\pi_1(P_i)}$ and $\psi|_{\pi_1(P_i)}$ are non-abelian for all $i \in \{1,\cdots,p-2\}$. Then $e(\phi) = e(\psi) = n$ for some $n\in \mathbb{Z}$, and there is a path in $\nonabel$ connecting $\phi$ and $\psi$.
\end{lemma}
\begin{proof}
        %To complete the proof, we first show this statement. 
        %\textcolor{purple}{We will prove the result for the case that $p_-(s)=0.$ Then the result for the remaining case that $p_+(s)=0$ follows from the previous case and Proposition \ref{prop_pglpsl}.}\textcolor{red}{Let's try not to do this} \medskip
        %As the case that $p = 3$ is proved by Theorem \ref{thm_pants}, we only need to consider the case that $p\geqslant 4$.
        If $p = 3$, then by Theorem \ref{thm_pants}, $\phi$ and $\psi$ are in $\mathcal{R}^s_{s_1}(\Sigma)$ which is connected; and by Proposition \ref{prop_reducible}, 
        $\mathcal{R}^s_{s_1}(\Sigma)$ consists of non-abelian representations, hence the lemma follows. 
        If otherwise that $p\geqslant 4$, then by Lemma \ref{lem_inthyp_sphere} and the assumption that $\phi$ and $\psi$ are totally non-hyperbolic, 
        for all $i\in \{1,\cdots, p-3\}$, $\phi(d_i)$ and $\psi(d_i)$ are elliptic. 
        For each $i\in \{1, \cdots, p-3\}$, let $\Sigma_i\doteq \displaystyle\bigcup_{k = 1}^{i} P_k$.
        We will first show by induction that for all $i\in \{1,\cdots, p-3\}$, there is a path $\{\phi_t: \pi_1(\Sigma_i)\to \psl\}_{t\in [0,i]}$ of representations of $\pi_1(\Sigma_i)$ connecting $\phi|_{\pi_1(\Sigma_i)}$ to $\psi|_{\pi_1(\Sigma_i)}$, such that for all $t\in [0,i]$, $\phi_t(c_k)\in \Par^{sgn(s_k)}$ for all $k\in \{1,\cdots, i+1\}$, and $\phi_t(d_l)\in \Ell$ for all $l\in \{1,\cdots, i\}$. 
        Then as $\Sigma_{p-3} = \Sigma\setminus P_{p-2}$,
        there is a path $\{\phi_t: \pi_1(\Sigma\setminus P_{p-2})\to \psl\}_{t\in [0,p-3]}$ connecting $\phi|_{\pi_1(\Sigma\setminus P_{p-2})}$ to $\psi|_{\pi_1(\Sigma\setminus P_{p-2})}$, such that for all $t\in [0,p-3]$, 
        $\phi_t(c_k)\in \Par^{sgn(s_k)}$ for all $k\in \{1,\cdots, p-2\}$, and $\phi_t(d_l)\in \Ell$ for all $l\in \{1,\cdots, p-3\}$. Finally, using $\{\phi_t\}_{t\in [0,p-3]}$ on $\pi_1(\Sigma\setminus P_{p-2})$, we will construct a path $\{\phi_t\}_{t\in [0,p-2]}$ on $\pi_1(\Sigma)$ connecting $\phi$ to $\psi$.
        \medskip

        As the base case of the induction, the path $\{\phi_t: \pi_1(P_1)\to \psl\}\interval$ is defined as follows. 
        The fundamental group $\pi_1(P_1)$ has the preferred peripheral elements $c_1,c_2$ and $d_1$. 
        For each $k\in \{1,2\}$, we have $\phi(c_k), \psi(c_k)\in \Par^{sgn(s_k)}$, where $s_1 = s_2$ as otherwise $p_+(s) \neq 0$ and $p_-(s) \neq 0$.
        Moreover, we have $\phi(d_1), \psi(d_1)\in \Ell$, hence both $\phi|_{\pi_1(P_1)}$ and $\psi|_{\pi_1(P_1)}$ are in $\PP^{s_1}(P_1)$. 
        By Lemma \ref{lem_evimage_Ell}, 
        the image of the evaluation map $\ev: \PP^{s_1}(P_1)\to \Ell_{s_1}$ is $\Ell_{s_1}$, which is connected; and by Theorem \ref{prop_PLP_Ell}, its domain $\PP^{s_1}(P_1)$ is connected. 
         Therefore, there exists a path $\{\phi_t\}\interval$ in $\PP^{s_1}(P_1)$ connecting $\phi_0= \phi|_{\pi_1(P_1)}$ to $\phi_1= \psi|_{\pi_1(P_1)}$, with 
        $\phi_t(c_1)\in \Par^{sgn(s_1)}, \phi_t(c_2)\in \Par^{sgn(s_2)}$, and $\phi_t(d_1)\in \Ell$ for all $t\in [0,1]$.
         \medskip

         Now assume that, for some
     $i\in \{1, \cdots, p-4\}$, there is a path $\{\phi_t: \pi_1(\Sigma_i)\to \psl\}_{t\in [0,i]}$ connecting $\phi|_{\pi_1(\Sigma_i)}$ to $\psi|_{\pi_1(\Sigma_i)}$ that satisfies the condition above. We will first construct a path $\{\phi_t: \pi_1(\Sigma_{i+1})\to \psl\}_{t\in [0,i]}$ 
    connecting $\phi|_{\pi_1(\Sigma_{i+1})}$ to a $\phi_i$ such that $\phi_i|_{\pi_1(\Sigma_i)} = \psi|_{\pi_1(\Sigma_i)}$, then construct a path $\{\phi_t: \pi_1(\Sigma_{i+1})\to \psl\}_{t\in [i,i+1]}$ connecting $\phi_i$ to $\psi|_{\pi_1(\Sigma_{i+1})}$. Then the path $\{\phi_t\}_{t\in [0,i+1]}$ connects $\phi|_{\pi_1(\Sigma_{i+1})}$ to $\psi|_{\pi_1(\Sigma_{i+1})}$.

        The  path $\{\phi_t: \pi_1(\Sigma_{i+1})\to \psl\}_{t\in [0,i]}$  is constructed as follows. 
       By the assumption, there exists a path $\{\phi_t: \pi_1(\Sigma_i)\to \psl\}_{t\in [0,i]}$ connecting $\phi_0= \phi|_{\pi_1(\Sigma_i)}$ to $\phi_i= \psi|_{\pi_1(\Sigma_i)}$, which is to be extended to $\pi_1(\Sigma_{i+1})$. 
       Recall that the fundamental group $\pi_1(P_{i+1})$ has the preferred peripheral elements $c_{i+2}, d_{i+1}$, and $d_i^{-1}$. 
       For each $t\in [0,i]$, we let $\widetilde{\phi_t(d_i)}$ be the lift of $\phi_t(d_i)\in \Ell$ in $\Ell_1$, then the path $\{\widetilde{\phi_t(d_i)}\}_{t\in [0,i]}$ lies in $\Ell_1$. Let 
        $\ev: \PE^{s_{i+2}}(P_{i+1})\to\Ell_1$ be the evaluation map defined in Subsection \ref{subsection_PLP_Ell}.
       By Lemma \ref{lem_evimage_Ell}, $\ev$ is surjective onto $\Ell_1$; and by Proposition \ref{prop_PLP_Ell}, 
       the path $\{\widetilde{\phi_t(d_i)}\}_{t\in[0,i]}$ lifts to the path $\{\psi_t%: \pi_1(P_{i+1})\to \psl
       \}_{t\in[0,i]}$  in $\PE^{s_{i+2}}(P_{i+1})$ with $\psi_0 = \phi|_{\pi_1(P_{i+1})}$. 
       For each $t\in [0,i]$, since $\psi_t$ and $\phi_t$ agree at the common boundary $d_i$ of $\Sigma_i$ and $P_{i+1}$, by letting $\phi_t|_{\pi_1(P_{i+1})}\doteq \psi_t$, we extend the path $\{\phi_t\}_{t\in [0,i]}$ from $\pi_1(\Sigma_i)$ to $\pi_1(\Sigma_{i+1})$ with $\phi_0 = \phi|_{\pi_1(\Sigma_{i+1})}$. For each $t\in [0,i]$, by the assumption, 
       $\phi_t(c_k)\in \Par^{sgn(s_k)}$ for all $k\in \{1,\cdots, i+1\}$, and $\phi_t(d_l)\in \Ell$ for all $l\in \{1,\cdots, i\}$. Moreover, as the path $\{\phi_t|_{\pi_1(P_{i+1})}\}_{t\in [0,i]}$ lies in $\PE^{s_{i+2}}(P_{i+1})$,
       we have $\phi_t(c_{i+2})\in \Par^{sgn(s_{i+2})}$ and $\phi_t(d_{i+1})\in \Ell$ for each $t\in [0,i]$. 

       The  path $\{\phi_t: \pi_1(\Sigma_{i+1})\to \psl\}_{t\in [i,i+1]}$  is constructed as follows.
       The evaluation map $\PE^{s_{i+2}}(P_{i+1})\to \Ell_1$
       sends both $\phi_i|_{\pi_1(P_{i+1})}$ and $\psi|_{\pi_1(P_{i+1})}$ to $\widetilde{\phi_i(d_i)}\in \Ell_1$. By Proposition \ref{prop_PLP_Ell}, the fiber $\ev^{-1}(\widetilde{\phi_i(d_i)})$ is connected, hence there exists a path $\{\phi_t: \pi_1(P_{i+1})\to \psl\}_{t\in [i,i+1]}$ in $\ev^{-1}(\widetilde{\phi_i(d_i)})$ connecting $\phi_i|_{\pi_1(P_{i+1})}$ to $\phi_{i+1} = \psi|_{\pi_1(P_{i+1})}$. As the path lies in $\ev^{-1}(\widetilde{\phi_i(d_i)})$, for all $t\in [i,i+1]$, $\phi_t(d_i) = \phi_i(d_i)$. Therefore, by letting $\phi_t|_{\pi_1(\Sigma_i)} \doteq \phi_i|_{\pi_1(\Sigma_i)} = \psi|_{\pi_1(\Sigma_i)}$ for all $t\in [i,i+1]$, we extend the path $\{\phi_t\}_{t\in [i,i+1]}$ from $\pi_1(P_{i+1})$ to $\pi_1(\Sigma_{i+1})$ with $\phi_{i+1} = \psi|_{\pi_1(\Sigma_{i+1})}$. For each $t\in [i,i+1]$, $\phi_t(c_k) = \phi_i(c_k)\in \Par^{sgn(s_k)}$ for all $k\in \{1,\cdots, i+1\}$, and $\phi_t(d_l) = \phi_i(d_l)\in \Ell$ for all $l\in \{1,\cdots, i\}$. Moreover, as the path $\{\phi_t|_{\pi_1(P_{i+1})}\}_{t\in [i,i+1]}$ lies in $\PE^{s_{i+2}}(P_{i+1})$,
       we have $\phi_t(c_{i+2})\in \Par^{sgn(s_{i+2})}$ and $\phi_t(d_{i+1})\in \Ell$ for each $t\in [i,i+1]$.
       \medskip

       Next, we construct the path $\{\phi_t\}_{t\in [0,p-2]}$ connecting $\phi$ to $\psi$. 
       By the induction above, there exists a path $\{\phi_t: \pi_1(\Sigma\setminus P_{p-2})\to \psl\}_{t\in[0,p-3]}$ connecting $\phi_0= \phi|_{\pi_1(\Sigma\setminus P_{p-2})}$ to $\phi_{p-3}= \psi|_{\pi_1(\Sigma\setminus P_{p-2})}$, which is to be extended to $\pi_1(\Sigma)$. Recall that the fundamental group $\pi_1(P_{p-2})$ has the preferred peripheral elements $c_{p-1}, c_p$, and $d_{p-3}^{-1}$.
       Let $\{\widetilde{\phi_t(d_{p-3})}\}_{t\in [0,p-3]}$ be the lift of the path $\{\phi_t(d_{p-3})\}_{t\in [0,p-3]}\subset \Ell$ in $\Ell_{s_p}$, and let
        $\ev: \PP^{s_p}(P_{p-2})\to\Ell_{s_p}$ be the evaluation map defined in Subsection \ref{subsection_PLP_Ell}.
       For each $k\in \{p-1,p\}$, we have $\phi(c_k), \psi(c_k)\in \Par^{sgn(s_k)}$, where $s_{p-1} = s_p$ as otherwise $p_+(s) \neq 0$ and $p_-(s) \neq 0$. 
       Moreover, we have $\phi(d_{p-3}^{-1}), \psi(d_{p-3}^{-1})\in \Ell$, hence both $\phi|_{\pi_1(P_{p-2})}$ and $\psi|_{\pi_1(P_{p-2})}$ are in $\PP^{s_p}(P_{p-2})$. By Lemma \ref{lem_evimage_Ell}, $\ev$ is surjective onto $\Ell_{s_p}$; and by Proposition \ref{prop_PLP_Ell}, 
       the path $\{\widetilde{\phi_t(d_{p-3})}\}_{t\in[0,p-3]}$ lifts to the path $\{\psi_t%: \pi_1(P_{p-2})\to \psl
       \}_{t\in[0,p-3]}$  in $\PP^{s_p}(P_{p-2})$ with $\psi_0 = \phi|_{\pi_1(P_{p-2})}$. 
       For each $t\in [0,p-3]$, since $\psi_t$ and $\phi_t$ agree at the common boundary $d_{p-3}$ of $\Sigma\setminus P_{p-2}$ and $P_{p-2}$, by letting $\phi_t|_{\pi_1(P_{p-2})}\doteq \psi_t$, we extend the path $\{\phi_t\}_{t\in [0,p-3]}$ from $\pi_1(\Sigma\setminus P_{p-2})$ to $\pi_1(\Sigma)$ with $\phi_0 = \phi$. 
       It remains to find a path $\{\phi_t\}_{t\in [p-3,p-2]}$ connecting $\phi_{p-3}$ to $\psi$. Notice that $\ev(\phi_{p-3}|_{\pi_1(P_{p-2})}) = \ev(\psi|_{\pi_1(P_{p-2})}) = \widetilde{\phi_{p-3}(d_{p-3})}\in \Ell_{s_p}$. By Proposition \ref{prop_PLP_Ell}, the fiber $\ev^{-1}\big(\widetilde{\phi_{p-3}(d_{p-3})}\big)$ is connected, hence there is a path $\{\phi_t: \pi_1(P_{p-2})\to \psl\}_{t\in [p-3,p-2]}$ in $\ev^{-1}(\widetilde{\phi_{p-3}(d_{p-3})})$ connecting $\phi_{p-3}|_{\pi_1(P_{p-2})}$ to $\phi_{p-2} = \psi|_{\pi_1(P_{p-2})}$. As the path lies in $\ev^{-1}(\widetilde{\phi_{p-3}(d_{p-3})})$, for all $t\in [p-3,p-2]$, $\phi_t(d_{p-3}) = \phi_{p-3}(d_{p-3})$. Therefore, by letting $\phi_t|_{\pi_1(\Sigma\setminus P_{p-2})} \doteq \phi_{p-3}|_{\pi_1(\Sigma\setminus P_{p-2})} = \psi|_{\pi_1(\Sigma\setminus P_{p-2})}$ for all $t\in [p-3,p-2]$, we extend the path $\{\phi_t\}_{t\in [p-3,p-2]}$ from $\pi_1(P_{p-2})$ to $\pi_1(\Sigma)$  with $\phi_{p-2} = \psi$. This defines the path $\{\phi_t\}_{t\in [0,p-2]}$ connecting $\phi$ to $\psi$.


       Finally, we show that $e(\phi) = e(\psi) = n$ for some $n\in \mathbb{Z}$, and that $\{\phi_t\}_{t\in [0,p-2]}\subset \nonabel$.
       For each $k\in \{1,\cdots, p-2\}$, 
       we have $\phi_t(c_k)\in \Par^{sgn(s_k)}$ for $t\in [0,p-3]$, also 
       $\phi_t(c_k) = \phi_{p-3}(c_k)\in \Par^{sgn(s_k)}$ for $t\in [p-3,p-2]$.
       Moreover, 
       since $s_{p-1} = s_p$ and
       $\{\phi_t|_{\pi_1(P_{p-2})}\}_{t\in [0,p-2]}\subset \PP^{s_p}(P_{p-2})$,
       $\phi_t(c_{p-1})\in \Par^{sgn(s_{p-1})}$ and $\phi_t(c_p)\in \Par^{sgn(s_p)}$.
       %for each $k\in \{p-1,p\}$, $\phi_t(c_k)\in \Par^{sgn(s_{k})}$. 
       Consequently, 
       for each $t\in [0,p-2]$, 
       the signs $s(\phi_t) = s(\phi)$ and the relative Euler classes $e(\phi_t) = e(\phi)$, and hence $e(\psi) = e(\phi) =n$ for some $n\in \mathbb{Z}$. Moreover, 
          $\phi_t(c_1)\in \Par$ and $\phi_t(d_1)\in \Ell$ do not commute, hence $\phi_t|_{\pi_1(P_1)}$ is non-abelian; and 
          for each $i\in \{2,\cdots, p-2\}$, 
          $\phi_t(c_{i+1})\in \Par$ and $\phi_t(d_{i-1})\in \Ell$ do not commute, hence $\phi_t|_{\pi_1(P_i)}$ is non-abelian. As a consequence, the path $\{\phi_t\}_{t\in [0,p-2]}$ lies in $\nonabel$.    
\end{proof}
\begin{proposition}\label{Prop_Exc2}
    Let $\Sigma = \Sigma_{0,p}$ with $p\geqslant 3$, and let $s\in \{\pm 1\}^p$ with $p_-(s) = 0$ or $p_+(s) = 0$. Then the space $\mathcal{R}^s_{s_1}(\Sigma)$ is non-empty. Moreover, for a totally non-hyperbolic representation $\phi$ with sign $s$, if $\phi|_{\pi_1(P_i)}$ is non-abelian for all $i \in \{1,\cdots,p-2\}$, then $\phi$ is in $\mathcal{R}^s_{s_1}(\Sigma)$.
\end{proposition}
\begin{proof}
    %We will prove the result for the case that $p_-(s)=0.$ Then the result for the remaining case that $p_+(s)=0$ follows from the previous case and Proposition \ref{prop_pglpsl}.
    As the case that $p = 3$ is proved by Theorem \ref{thm_pants}, it suffices to consider the case that $p\geqslant 4$. We will prove the result for the case that $p_-(s)=0$. Then the result for the remaining case that $p_+(s)=0$ follows from the previous case and Proposition \ref{prop_pglpsl}.
    \\

    As $s_i = +1$ for all $i\in \{1,\cdots, p\}$, we first show that $\mathcal{R}^s_1(\Sigma)$ is non-empty. We define a  representation $\psi$ by letting 
        $\psi(c_1) = \pm \begin{bmatrix}
                        3 & p-2\\
                        \frac{4}{2-p} & -1
                    \end{bmatrix}$, 
        $\psi(c_2) = \pm \begin{bmatrix}
                        1 & 0\\
                        \frac{4}{2-p} & 1
                    \end{bmatrix}$, 
        and 
        $\psi(c_i) = \pm \parpp$ for each $i\in \{3,\cdots, p\}$. 
        By Lemma \ref{lem_offdiag}, $\psi(c_i)\in \Par^+$ for all $i\in \{1,\cdots, p\}$, and hence $s(\psi) = s$. 
        To show that $e(\psi) = 1$, we consider the restrictions 
        $\psi|_{\pi_1(P_1)}$ and $\psi|_{\pi_1(\Sigma\setminus P_1)}$. The fundamental group $\pi_1(P_1)$ has the preferred peripheral elements $c_1,c_2,$ and $d_1$, and
        the fundamental group $\pi_1(\Sigma\setminus P_1)$ has the preferred peripheral elements $c_3,\cdots, c_p$ and $d_1^{-1}$. As $\psi(d_1) = \big(\psi(c_1)\psi(c_2)\big)^{-1} = \pm \begin{bmatrix}
                        1 & p-2\\
                        0 & 1
                    \end{bmatrix}\in \Par^+$, 
        $\psi|_{\pi_1(P_1)}$ and $\psi|_{\pi_1(\Sigma\setminus P_1)}$ are type-preserving. 
        As $s(\psi|_{\pi_1(P_1)}) = (+1,+1,+1)$, Theorem \ref{thm_pants} implies $e(\psi|_{\pi_1(P_1)}) = 1$; and as $\psi|_{\pi_1(\Sigma\setminus P_1)}$ is abelian, Proposition \ref{prop_reducible} implies that $e(\psi|_{\pi_1(\Sigma\setminus P_1)}) = 0$. Hence by Proposition \ref{prop_additivity}, $e(\psi) = e(\psi|_{\pi_1(P_1)})
        + (\psi|_{\pi_1(\Sigma \setminus P_1)}) = 1.$
        \\

        Next, let $\phi$ be a totally non-hyperbolic representation with sign $s$, and suppose that $\phi|_{\pi_1(P_i)}$ is non-abelian for all $i \in \{1,\cdots,p-2\}$. To show that $\phi\in \mathcal{R}^s_1(\Sigma)$,
        we will first
        find a totally non-hyperbolic representation 
        $\rho$
        in $\mathrm{NA}^s_1(\Sigma)$. Then by applying Lemma \ref{lem_Exc2} to $\phi$ and $\rho$, we conclude that $\phi\in \mathrm{NA}^s_1(\Sigma)\subset\mathcal{R}^s_1(\Sigma)$.
        To this end, we will 
        construct a path $\{\psi_t\}_{t\in[0,2]}$ in $\mathcal{R}^s_1(\Sigma)$ connecting $\psi_0 =\psi$ to a $\psi_2 \in \mathrm{NA}^s_1(\Sigma)$ as follows. 
        First, we will define paths $\{\psi_t: \pi_1(\Sigma\setminus P_1)\to \psl\}_{t\in[1,2]}$ and $\{\psi'_t: \pi_1( P_1)\to \psl\}_{t\in[1,2]}$ of representations of $\pi_1(\Sigma\setminus P_1)$ and $\pi_1(P_1)$, respectively. Next, we will find a path $\{g_t\}_{t\in [1,2]}\subset \psl$ using Lemma \ref{lem_conjugacypath}, and
        glue $\{\psi_t: \pi_1(\Sigma\setminus P_1)\to \psl\}_{t\in[1,2]}$ and $\{g_t\psi'_tg_t^{-1}: \pi_1(P_1)\to \psl\}_{t\in[1,2]}$ along the decomposition curve $d_1$ to extend the path $\{\psi_t\}_{t\in[1,2]}$ to $\pi_1(\Sigma)$. 
        Finally, we will construct a path $\{\psi_t\}_{t\in[0,1]}$ connecting $\psi$ to $\psi_1$, and compose it with $\{\psi_t\}_{t\in[1,2]}$.
        \smallskip

        We first define a path 
        $\{\psi_t: \pi_1(\Sigma\setminus P_1)\to \psl\}_{t\in [1,2]}$ as follows: 
        For each $t\in [1,2]$,
        let 
        $\psi_t(c_k) \doteq \pm \parpp$ for each $k\in \{3,\cdots, p-1\}$, and let 
        $\psi_t(c_p) \doteq \pm
        \begin{bmatrix}
            1 - \frac{t-1}{\sqrt{p-3}} & 1 \\
            - \frac{(t-1)^2}{p-3} & 1+ \frac{t-1}{\sqrt{p-3}}
        \end{bmatrix}$.
        Then the values $\{\psi_t(c_k)\}_{k\in\{3,\dots,p\}}$ determine the representation $\psi_t$ of $\pi_1(\Sigma\setminus P_1)$ with $\psi_1 = \psi|_{\pi_1(\Sigma\setminus P_1)}$. 
        For each $t\in (1,2]$ and each $i\in \{1,\cdots, p-3\}$, $\psi_t(d_i)$ is elliptic, as
        $$\psi_t(d_i) = \psi_t(c_{i+2})\cdots \psi_t(c_p) 
            = \pm 
        \begin{bmatrix}
            1-\frac{t-1}{\sqrt{p-3}} - \frac{(p-2-i)(t-1)^2}{p-3} & p-1-i+\frac{(p-2-i)(t-1)}{\sqrt{p-3}}  \\
            -\frac{(t-1)^2}{p-3} & 1+ \frac{t-1}{\sqrt{p-3}}
        \end{bmatrix}
        $$
            %$$\psi_1(d_i) = \psi_1(c_{i+2})\cdots \psi_1(c_p)= \pm \begin{bmatrix}\frac{\sqrt{p-4}}{p-3} - \frac{1-i}{p-3} &  (p-1-i)\big(1-\frac{\sqrt{p-4}}{p-3}\big) -1 \\ -\frac{1}{p-3} & 1 - \frac{\sqrt{p-4}}{p-3}\end{bmatrix},$$ 
         has the trace $2 - \frac{(p-2-i)}{p-3}(t-1)^2 < 2$ in absolute value.

        Next, we construct a path 
        $\{\psi'_t: \pi_1( P_1)\to \psl\}_{t\in [1,2]}$ using
    Lemma \ref{lem_plpchar} as follows. 
        Since $e\big(\psi|_{\pi_1(P_1)}\big) = 1$, it follows that
        the character $\chi(\psi|_{\pi_1(P_1)}) = (2,2,-2)$. Define the straight line segment $\{(2,2,z_t)\}_{t\in [1,2]}$ in $\mathbb{R}^3$, where $z_t 
        = (t-1)^2 - 2 
        %= t^2 - 2t - 1
        $
        connecting $-2$ to $-1$.
    Let $A_1$ and $B_1$ respectively
    be the lifts of $\psi(c_1)$ and $\psi(c_2)$ in $\SL$ with trace $2$, noting that the image of $(A_1, B_1)$ under the character map $\chi$ equals $\chi(\psi|_{\pi_1(P_1)}) = (2,2,-2)$.
    As $e(\psi|_{\pi_1(P_1)}) = 1$, by Proposition \ref{prop_reducible}, $\psi|_{\pi_1(P_1)}$ is non-abelian.
    In particular, $\psi(c_1)$ and $\psi(c_2)$ do not commute in $\psl$, and their lifts $A_1$ and $B_1$ do not commute in $\SL$. Moreover, as $\kappa(2, 2, z_t) = (z_t - 2)^2 + 2 > 2$ for all $t\in [1,2]$, where $\kappa$ is as defined in Proposition \ref{prop_char},  the path $\big\{(2,2,z_t)\big\}_{t\in [1,2]}$ lies in
    $\mathbb{R}^3
    \setminus \big([-2,2]^3\cap \kappa^{-1}([-2,2])\big)$. 
    Then by Lemma \ref{lem_plpchar}, 
        there exists a path $\{(A_t, B_t)\}_{t\in [1,2]}$ of non-commuting pairs of elements of $\SL$ starting from  $(A_1, B_1)$, having 
