\subsection{Proof of Lemma \ref{lem_evPsubm}}
\begin{proof}%[Proof of Lemma \ref{lem_evPsubm}]
    Let $\xi, \eta \in \sl$. 
    The differential of $m$ at a point $(A,B)\in \SL\times \SL$ equals
    $$d{m}_{(A,B)}(\xi A, \eta B)
    = \xi AB  + A\eta B,$$ 
    and by composing this with the linear isomorphism 
    $\xi\mapsto \xi(AB)^{-1}$, we obtain the map $m_*: \sl\times\sl\to \sl$ defined by
    $$%M_*(d{R}_{(A,B)}
    m_*(\xi, \eta)
    = \xi  + A\eta A^{-1}.$$
    %The differential of $m$ at a point $(A,B)\in \SL\times \SL$ equals
    %$$dm_{(A,B)}(\xi, \eta)
    %= \xi AB + A\eta B.$$
    %By composing the differential $dm_{(A,B)}: T_{(A,B)}(\SL\times \SL)\to T_{AB}\SL$ at a point $(A,B)\in \SL\times \SL$ with the linear isomorphisms $\xi\mapsto \xi A$, $\xi\mapsto \xi B$, and $\xi\mapsto \xi(AB)^{-1}$ on $\sl$, we obtain the map
    %m_*: \sl\times \sl \to \sl$ defined by $m_*(\xi, \eta) = \xi  + A\eta A^{-1}$. 
    %$$M_*dm_{(A,B)}(\xi, \eta)= (\xi AB + A\eta B)B^{-1}A^{-1} = \xi  + A\eta A^{-1}.$$
    To show that each restriction of $dm_{(A,B)}$ is surjective, for each generator $
    \sldiag,
    \slupper$, and $\sllower$ of $\sl$,
    we will find a preimage $(\xi, \eta)\in \sl\times \sl$ under $m_*$ such that $(\xi A, \eta B)$ lies in the tangent space of the restricted domain of $m$.
    \\

    For (1), for each $\xi \in \sl$, we have $m_*(\xi, 0) = m_*(0,A^{-1}\xi A) = \xi$.
    %we observe that $m_*$ maps the elements $(\xi, 0), (0, A^{-1}\xi A)\in \sl\times \sl$ to $\xi.$
    Moreover, for the restriction of $m$ to each of $U\times U, \Par\times U, U\times \Par$,
    $(\xi A, 0)$ or 
    $(0, A^{-1}\xi A B)$ lies in the tangent space of the domain, as $\xi A\in T_AU\cong T_A\SL$ and $(A^{-1}\xi A) B\in T_BU\cong T_B\SL$. Therefore, $m$ is submersive on these domains.
    \medskip

    For (2), as the tangent space of the domain is 
    $T_A\Par\times T_B\Par$, we first compute the elements of $T_X\Par$ for each $X = \abcd\in \Par$ in $\SL$. 
    Each element of $T_X\SL$ can be written as $$\xi X = \bigg(x\slupper + y\sllower + z\sldiag\bigg) \abcd
    = \begin{bmatrix}
            cx+az & dx+bz \\
            ay-cz & by-dz
        \end{bmatrix}$$\\
    for some $x,y,z\in \mathbb{R}.$
    Since $\Par$ is the level set $\tr^{-1}(2)\cup \tr^{-1}(-2)$  of the trace map, the differential of the trace map $d(\tr)_X:T_X\SL\to \mathbb{R}$ at $X$, which maps $\xi X\in \sl$ to the trace $\tr(\xi X)$, is zero on $T_X\Par$.
    This implies that $\xi X\in T_X\Par$ if and only if
    $d(\tr)_X(\xi X) = cx + by + (a-d)z = 0.$
      %For $-A$, we replace $a,b,c,d$ to $-a,-b,-c,-d$, and we obtain the same equation for $d(\tr)_{-A}\big(\xi (-A)\big) = 0$. 

    We now compute the image of $dm_{(A,B)}$.
    Up to conjugation and multiplication by $-\mathrm I$, we can assume that 
    $A = \begin{bmatrix}
        1 & s \\
        0 & 1
    \end{bmatrix}$ for some $s\in \{\pm 1\}$.
    %as if $dm_{(A,B)}$ is surjective, then $dm_{(-A,-B)}$ and $dm_{(PAP^{-1},PBP^{-1})}$ are surjective.
    We have $\xi A = x\slupper + y\sllower + z\sldiag\in T_A\Par$ if and only if $y = 0$, i.e.,
    $T_A\Par$ is generated by
        $\slupper A$ and $\sldiag A$.
    Hence for $\xi = \slupper$ or $\xi = \sldiag$, 
    $m_*(\xi, 0) = \xi$ and $(\xi A, 0)\in T_A\Par\times T_B\Par$.
    %xFor $X,Y\in \sl$, denote by $\langle X,Y\rangle$ the 2-dimensional subspace of $\sl$ generated by $X,Y$.\\ Since the space $\bigg\langle \slupper, \sldiag\bigg\rangle$ is contained in the image of $m_*$, it remains to find a pre-image of $\sllower$. 
    As $\slupper$ and $\sldiag$
    are in the image of $m_*$, it remains to find a preimage $(\xi,\eta)\in \sl\times \sl$ of $\sllower$ such that $(\xi A, \eta B)\in T_A\Par\times T_B\Par$; and it suffices to find a $(\xi,\eta)$ with $(\xi A, \eta B)\in T_A\Par\times T_B\Par$ whose image $m_*(\xi,\eta)$ has non-zero $(2,1)$-entry. By computing $R_*(0,\eta) =  A\eta A^{-1}$ for $
    \eta = \begin{bmatrix}
        z  & x \\
        y  & -z
      \end{bmatrix}\in \sl$,
    %Thus, $dm_{(A,B)}$ is surjective if and only if there is a preimage $(\xi, \eta)$ of $\sllower$ under $m_*$ such that $(\xi A, \eta B)\in T_A\Par\times T_B\Par$.
    we obtain 
$m_*(0,\eta)
      = A\eta A^{-1}
    %= \parpp
    %  \begin{bmatrix}
    %    z  & x \\
    %    y  & -z
    %  \end{bmatrix}
    %  \parmp\\
    %= \begin{bmatrix}
    %    z + sy  & x - y - 2sz \\
    %      y    &  -z-sy
    %  \end{bmatrix}
      = \begin{bmatrix}
        z-y  & x - y + 2z \\
          y    &  y-z
      \end{bmatrix}$.
      Therefore, there is such $(\xi, \eta)$ if and only if 
      there is an $\eta B = \begin{bmatrix}
        z  & x \\
        y  & -z
      \end{bmatrix} B\in T_B\Par$ with $y \neq 0$.
      Letting $B = \abcd\in \SL$, having $T_B\Par = \bigg\{ \begin{bmatrix}
        z  & x \\
        0  & -z
      \end{bmatrix} B: x,z\in \mathbb{R}^2\bigg\}$ is equivalent to having $cx + by + (a-d)z = 0$ for all $(x,0,z)\in \mathbb{R}^3$, i.e., $c = a-d = 0$ and $B = \pm\begin{bmatrix}
        1 & b \\
        0 & 1
    \end{bmatrix}$ for some $b\in \mathbb{R}$ which commutes with $A$.
    As a consequence, $dm_{(A,B)}$ is surjective if and only if $A$ and $B$ do not commute.
\end{proof}


