        \end{bmatrix}
        \Bigg) \in \mathcal{R}_0^{(-1,+1,0)}
            (\Sigma_{0,3})$  
            and 
         $\Bigg(
        \pm \begin{bmatrix}
        1 & 1 \\
        0 & 1
        \end{bmatrix},
        \pm 
        \begin{bmatrix}
