\section{Rota-Baxter dendriform D-bialgebras}\label{bialgs}

\begin{defi}
A {\bf Rota-Baxter operator of weight $\lambda$ on a dendriform D-bialgebra $(A,A^{\ast})$} is a linear map $P: A \longrightarrow A$ such that
\begin{itemize}
\item[{\rm(i)}] $P$ is a Rota-Baxter operator of weight $\lambda$ on $A$;
\item[{\rm(ii)}] $\widetilde{P^{\ast}}:= -\lambda\Id -P^{\ast}$ is a Rota-Baxter operator of weight $\lambda$ on $A^{\ast}$.
\end{itemize}
A dendriform D-bialgebra with a Rota-Baxter operator of weight $\lambda$ is called a {\bf Rota-Baxter dendriform D-bialgebra of weight $\lambda$}.

We denote a Rota-Baxter dendriform D-bialgebra of weight $\lambda$ by $(A,A^{\ast},P)$.
\end{defi}

\begin{pro}
If $P$ is a Rota-Baxter operator of weight $\lambda$ on the dendriform D-bialgebra $(A,A^{\ast})$. Then
$\widetilde{P^{\ast}}$ is a Rota-Baxter operator of weight $\lambda$ on its dual dendriform D-bialgebra $(A^{\ast},A)$.
\end{pro}
\begin{proof}
	It follows by a direct calculation.
	\end{proof}

\begin{pro}\label{double}
Let $(A,A^{\ast},P)$ be a Rota-Baxter dendriform D-bialgebra of weight $\lambda$. Then $(\frkd,\frkd_r^{\ast},\huaP)$ is a Rota-Baxter dendriform D-bialgebra of weight $\lambda$, where $(\frkd,\frkd_r^{\ast})$ is the dendriform D-bialgebra given by Theorem \ref{dendriform double}, and $\huaP:A \oplus A^{\ast} \longrightarrow A\oplus A^{\ast} $ is the linear map defined by
\begin{eqnarray}\label{huaP}
\huaP(x+\xi)=Px-\lambda\xi-P^{\ast}\xi,\quad \forall x\in A,~~~\xi\in A^{\ast}.
\end{eqnarray}
\end{pro}

\begin{proof}
It is straightforward to check that the linear map $\huaP$ is a Rota-Baxter operator of weight $\lambda$ on the dendriform double algebra $\frkd =A\bowtie A^{\ast}$.

Since $\widetilde{P^{\ast}}=-\lambda\Id-P^{\ast} $ is a Rota-Baxter operator of weight $\lambda$ on the dendriform algebra $A^{\ast}$, it is straightforward to check that
$-\lambda\Id-\widetilde{\huaP^{\ast}}:\frkd_r^{\ast} \longrightarrow \frkd_r^{\ast}$, via $ \xi+x \mapsto -\lambda\xi-P^{\ast}\xi+Px $, is a Rota-Baxter operator of weight $\lambda$ on the dual dendriform algebra $\frkd_r^{\ast}$ by \eqref{frkdast1} and \eqref{frkdast2}. Consequently, $(\frkd,\frkd_r^{\ast},\huaP)$ is a Rota-Baxter
dendriform D-bialgebra of weight $\lambda$.
\end{proof}

\begin{ex}{\rm
Let $(A,A^{\ast})$ be a dendriform D-bialgebra. Then $(A,A^{\ast},P)$ is a Rota-Baxter dendriform D-bialgebra of  weight $\lambda$, where the linear map $P:A \longrightarrow A$ is defined by $P(x)=-\lambda x$.
}
\end{ex}

\begin{ex}{\rm
Consider the dendriform D-bialgebra $(\frkd,\frkd_r^{\ast})$ given in Theorem \ref{dendriform double}, where
$\frkd =A\bowtie A^{\ast}$. Then the linear map
$$ P:A \bowtie A^{\ast} \longmapsto A \bowtie A^{\ast}, \quad x+\xi \mapsto -\lambda x,$$
is a Rota-Baxter operator of weight $\lambda$ on the dendriform algebra $\frkd$. Furthermore, we have
 $$ (-\lambda\Id-P^{\ast})(\xi+x)=-\lambda x,$$
which implies that $-\lambda\Id-P^{\ast}$ is also a  Rota-Baxter operator of weight $\lambda$ on the dual dendriform algebra $\frkd_r^{\ast}$. Therefore, $(\frkd,\frkd_r^{\ast},P)$ is a Rota-Baxter dendriform D-bialgebra of  weight $\lambda$.
}
\end{ex}

Factorizable dendriform D-bialgebras can give rise to Rota-Baxter dendriform D-bialgebras.
\begin{thm}\label{thm:facden-RBD}
Let $(A,A_{r}^{\ast})$ be a factorizable dendriform D-bialgebra with $I=r_{+}-r_{-}$. Then $(A,A_{r}^{\ast},P)$ is a Rota-Baxter dendriform D-bialgebra of weight $\lambda$, where $P$ is given by \eqref{P2}.
\end{thm}

\begin{proof}
It is obvious that $\widetilde{P^{\ast}}=-\lambda\Id-P^{\ast}=\lambda I^{-1}\circ r_{-}.$ Moreover, by the facts that $r_{-}:A_{r}^{\ast}\longrightarrow A$ is a dendriform algebra homomorphism and
$\lambda I^{-1}:(A,\prec_P,\succ_P)\longrightarrow(A_{r}^{\ast},\prec_r,\succ_r)$ is a dendriform algebra isomorphism, we have
\begin{eqnarray*}
&&\widetilde{P^{\ast}}\Big(\widetilde{P^{\ast}}\xi \prec_{r} \eta+\xi \prec_{r} \widetilde{P^{\ast}}\eta +\lambda \xi \prec_{r} \eta \Big)\\
&=& \lambda I^{-1} r_{-}\Big((\lambda I^{-1} r_{-}\xi)\prec_{r} \eta+\xi \prec_{r}(\lambda I^{-1} r_{-}\eta)+\lambda \xi \prec_{r} \eta\Big)\\
&=& \lambda I^{-1} \Big( (\lambda r_{-} I^{-1} r_{-}\xi)\prec_A r_{-}\eta + r_{-}\xi  \prec_A                      (\lambda r_{-} I^{-1} r_{-}\eta) +  \lambda r_{-}\xi  \prec_A r_{-}\eta   \Big)\\
&=& \lambda I^{-1} ( r_{-}\xi  \prec_{P} r_{-}\eta)\\
&=& (\lambda I^{-1}r_{-}\xi) \prec_{r} (\lambda I^{-1}r_{-}\eta)\\
&=&  (\widetilde{P^{\ast}}\xi) \prec_{r} (\widetilde{P^{\ast}}\eta).
\end{eqnarray*}
Similarly, we can also have
$$\widetilde{P^{\ast}}\Big(\widetilde{P^{\ast}}\xi \succ_{r} \eta+\xi \succ_{r} \widetilde{P^{\ast}}\eta +\lambda \xi \succ_{r} \eta \Big)=(\widetilde{P^{\ast}}\xi) \succ_{r} (\widetilde{P^{\ast}}\eta),$$
which implies that $\widetilde{P^{\ast}}$ is a Rota-Baxter operator of weight $\lambda$ on $A_{r}^{\ast}$. Therefore, $(A,A_{r}^{\ast},P)$ is a Rota-Baxter dendriform D-bialgebra of weight $\lambda$.
\end{proof}

On the other hand, there is the following construction of factorizable dendriform D-bialgebras from Rota-Baxter dendriform D-bialgebras, supplying Theorem \ref{thm:facden-RBD} from the converse side in certain sense.
\begin{cor}\label{cor:RBD-facden}
Let $(A,A^*,P)$ be a Rota-Baxter dendriform D-bialgebra of weight $\lambda~(\lambda\neq 0)$. Then there is a factorizable dendriform D-bialgebra $(\frkd,\frkd_\frkr^*)$, where $\frkd=A \bowtie A^*$ and $\frkr\in \otimes^2 \frkd$ is determined by
\begin{eqnarray}\label{frkr}
\frkr_{+} (\xi,x)=\frac{1}{\lambda}(\huaP+\lambda\Id)(-x,\xi), \quad \forall x\in A, \xi\in A^*,
\end{eqnarray}
where $\huaP$ is given by \eqref{huaP}.
\end{cor}

\begin{proof}
It is straightforward to check that $(\frkd=A \bowtie A^*,\huaP,\omega)$ is a quadratic Rota-Baxter dendriform algebra of weight $\lambda$, where $\huaP$ is given by \eqref{huaP} and $\omega$ is given by
\begin{eqnarray}\label{omega}
\omega(x+\xi,y+\eta)=\xi(y)-\eta(x), \quad \forall x\in A, \xi\in A^*.
\end{eqnarray}
Then by Theorem \ref{Factorizable dendriform algebra}, we obtain a factorizable dendriform D-bialgebra $(\frkd,\frkd_\frkr^*)$, where $\frkr\in \otimes^2 \frkd$ is determined by
\begin{eqnarray*}
\frkr_{+}=\frac{1}{\lambda} (\huaP+\lambda\Id)\circ \huaJ_{\omega}:\frkd_r^* \longrightarrow \frkd.
\end{eqnarray*}
It is obvious that $\huaJ_{\omega}(\xi,x)=(-x,\xi)$.
\end{proof}

Let $(A,A_r^*)$ be a factorizable dendriform D-bialgebra. By Theorem \ref{thm:facden-RBD}, $(A,A_r^*,P)$ is a Rota-Baxter dendriform D-bialgebra, where $P=\lambda r_-\circ I^{-1}$. By Corollary \ref{cor:RBD-facden}, we obtain a factorizable dendriform D-bialgebra $(\frkd,\frkd_{\frkr}^*)$, where $\frkd=A \bowtie A_r^*$ and $\frkr \in \otimes^2 \frkd$ is determined by \eqref{frkr}. Straightforward computations show that
$$ \frkr_{+} (\xi,x)=(r_+\circ I^{-1} (x),I^{-1} \circ r_+(\xi)), \quad \forall x\in A,\xi \in A^*. $$
On the other hand, any dendriform D-bialgebra gives rise to a factorizable dendriform D-bialgebra according to Theorem \ref{dendriform double}. In particular, the factorizable dendriform D-bialgebra $(A,A_r^*)$ gives the factorizable dendriform D-bialgebra $(\frkd,\frkd_{{\bar{r}}}^*)$, where $\bar{r}=\sum_{i} e_i \otimes e_i^*.$ Obviously, $\frkr$ and $\bar{r}$ are different, the former is determined by the original $r$, while the latter is not related to $r$.

Therefore, a factorizable dendriform D-bialgebra $(A,A_r^*)$ gives rise to two different factorizable dendriform D-bialgebras via the above two different approaches.
}

