\title{Universal energy cascade and relaxation in three-dimensional inertial electron magnetohydrodynamic turbulence}
\author{Supratik Banerjee}%
\email{sbanerjee@iitk.ac.in}
\affiliation{Department of Physics, Indian Institute of Technology Kanpur, Kanpur, Uttar Pradesh, 208016, India}
