\section{Numerical investigation}
\label{sec3}
\subsection{Non-dimensionalisation of governing equations}
\label{sec3A}
For numerical analysis, we take $\rho_e = 1$ and rewrite the magnetic field in the Alfv\'{e}n units such that $\bb= \bB/\sqrt{\mu_0}$, $\bj = \bnabla\times\bb$, $\bu_e = -d_e\bj$, $\bw_e = d_e\nabla^2 \bb$ and $\bm{q}=\bb - d_e\bw_e$. In terms of the newly introduced variables, along with a proper non-dimensonalisation, Eq.~\eqref{frozen_in_Eq} can be re-written as 
\begin{equation}
\frac{\partial \bm{q}^*}{\partial t^*}
=\bnabla^*\times\left(\bu_e^*\times\bm{q}^*\right) +\bm{f}^*_{\bm{q}^*} + \eta^* \nabla^{*2}\bb^* - \nu_e^* d_e^{*2} \nabla^{*4}\bb^*,\label{Geq_nondim}
\end{equation}
where $\bm{q}^* = \bb^*-d_e^{*2}\nabla^{*2}\bb^*$, $\bb^* = \bb/U_{rms}$, $\bu_e^* = \bu_e/U_{rms}$, $\bm{f}^*_{\bm{q}^*}= (L/U^2_{rms}) \bm{f}_{\bm{q}}$, $ t^*= (U_{rms}/L)t$, $\bnabla^* = L\bnabla$, $d_e^* =  d_e/L$, $\eta^*=\eta/(U_{rms} L) $ and $\nu_e^*=\nu_e/(U_{rms} L) $ with $L$ being the box size. For the sake of notational simplicity, we drop the * sign hereinafter. In our numerical simulations, for convenience, we choose $\nu_e = \eta$ such that Eq.~\eqref{Geq_nondim} reduces to 
\begin{equation}
    \frac{\partial \bm{q}}{\partial t} = \bnabla\times(\bu_e\times\bm{q}) +\bm{f}_{\bm{q}} + \eta \nabla^2 \bm{q}.\label{gov_eq_nondim_final}
\end{equation}
In a similar manner as above, the derived exact relation in Eq.~\eqref{exact_law_energy_final} can be written in the non-dimensional units as 
\begin{equation}
A(\bm{\ell}) = d_e^{-1}\left\langle \delta\left(\bm{q}\times\bu_e \right) \cdot \delta \bu_e \right\rangle = 2 \varepsilon \label{exact_energy_nondim}\\
\end{equation}
whereas the flux rate in Eq.~\eqref{Flux_rate_energy_Fourier} and is given by 
\begin{equation}
 \Pi (k) = - d_e^{-1}\sum_{|\bk'|\leq k}\Re\left[\bu_e^* (\bk')\cdot\widehat{\left(\bm{q}\times\bu_e\right)}_{\bk'}\right] =\varepsilon,\label{flux_Fourier_energy_nondim}
\end{equation}
Finally, the relaxed state in Eq.~\eqref{relaxed_solution} is written in the non-dimensional units as
\begin{equation}
    \bu_e\times\bm{q}=\bnabla\Phi\implies \bnabla\times(\bu_e\times\bm{q}) = \bm{0}.\label{relaxed_state_nondim}
\end{equation}

