% Redefining the Gap problem
%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Redefining the \texorpdfstring{\gap}{Gap} problem} \label{sec:lifting_opt}

In this section, we exploit the idea proposed in \cite{art:BenBoy:IGSmallTSP} of dividing the study of $\alpha_n$ into subproblems $\gap(\bm{x})$ associated to the vertices $\bm{x}$ of the polytope $\psep{n}$.
In~\cite{art:BenBoy:IGSmallTSP}, Benoit and Boyd explain how to craft a linear problem $\opt(\bm{x})$ for each vertex $\bm{x} \in \psep{n}$, in order to compute $\gap(\bm{x}) = 1 / \opt(\bm{x})$.
The integrality gap $\alpha_n$ is finally recovered as
$\alpha_n = \max \{ \gap(\bm{x}) \mid \bm{x} \text{ vertex of } \psep{n} \}$.

In this work, we build upon the same idea, slightly changing the definition of \gap\ (see \Cref{def:vgap}), without losing the main aim of this approach.

\begin{definition}[\gapp\ of a vertex]
    Let $\bm{x} \in \psep{n}$ be a vertex. The \emph{\gapp\ of $\bm{x}$} is
    $$
    \gapp(\bm{x}) := \sup \left\{ \frac{\tsp(\bm{c})}{\bm{c} \bm{x}} \ \mid \ \bm{c} \text{ metric } \right\} \ .
    $$
\end{definition}

This definition is a relaxed version of the previous one, from which we dropped the request that $\bm{c}$ satisfies $\bm{c} \bm{x} = \sep(\bm{c})$; thus $\gapp(\bm{x}) \geq \gap(\bm{x})$.
Even though \gapp\ appears to be rougher than \gap\ on the individual vertices, it pursues the same overall goal %
\footnote{This fact was already mentioned in \cite{art:BenBoy:IGSmallTSP}, last note of Section~2.}, that is
$$
\alpha_n = \max_{\bm{x} \text{ vertex of } \psep{n}} \gapp(\bm{x}) \ .
$$

Following the same strategy used for \gap\ (see \cite{art:BenBoy:IGSmallTSP}), to compute \gapp\ we consider the linear problem \optp.
\begin{align}
    \optp(\bm{x}) := \
    \text{minimize \ \ }
        & \sum_{ij \in E_n} x_{ij} c_{ij}
            \label{eq:optp_obj} \\
    \text{subject to: \ }
        & c_{ik} + c_{jk} - c_{ij} \ \geq 0
            & & \forall ij \in E_n, \ k \in V_n \setminus \{ i, j \},
            \label{eq:optp_tr_ineq} \\
        & \sum_{ij\in E_n} t_{ij} c_{ij} \ \geq 1
            & & \forall \bm{t} \text{ tour},
            \label{eq:optp_tour_cost_1} \\
        & c_{ij} \geq 0
            & & \forall ij \in E_n.
            \label{eq:optp_var}
\end{align}
Constraints~\eqref{eq:optp_tr_ineq} force $\bm{c}$ to be a metric cost;
constraints~\eqref{eq:optp_tour_cost_1} normalize $\tsp(\bm{c}) = 1$;
minimizing $\bm{c} \bm{x}$ is then equivalent to maximizing $1 / \bm{c} \bm{x} = \tsp(\bm{c}) / \bm{c} \bm{x}$, \ thus $\optp(\bm{x}) = 1 / \gapp(\bm{x})$.

We now state the first immediate result about \gapp, which is the symmetric version of Proposition~4.6.1 of~\cite{thesis:Ell:IGATSP}.
This lemma guarantees that, for the study of $\gapp(\bm{x})$, it is enough to consider only (the metric completion of) metric costs on the support graph $G_{\bm{x}}$.

\begin{lemma}
    Let $\bm{x}$ be a vertex of $\psep{n}$ and let $c \in \arg\max \gapp(\bm{x})$
    (i.e. $\bm{c}$ is a metric cost that realizes the \gapp\ on $\bm{x}$).
    Let $\bm{c}_{|G_{\bm{x}}}$ be the restriction of $\bm{c}$ on the edges of $G_{\bm{x}}$, and consider its metric completion $\tilde{\bm{c}} := (\bm{c}_{|G_{\bm{x}}})^*$. \
    Then $\tilde{\bm{c}} \in \arg\max \gapp(\bm{x})$
    (i.e. $\tilde{\bm{c}}$ also is a metric cost that realizes the \gapp\ on $\bm{x}$).
\end{lemma}

\begin{proof}
    By definition, $\tilde{\bm{c}}$ is metric and $\tilde{\bm{c}}_{|G_{\bm{x}}} = \bm{c}_{|G_{\bm{x}}}$, thus $\tilde{\bm{c}} \bm{x} = \bm{c} \bm{x}$.
    Moreover $\tilde{\bm{c}} \geq \bm{c}$ componentwise, hence $\tsp(\tilde{\bm{c}}) \geq \tsp(\bm{c})$.
    This gives
    $\frac{\tsp(\tilde{\bm{c}})}{\tilde{\bm{c}} \bm{x}} \geq \frac{\tsp(\bm{c})}{\bm{c} \bm{x}} = \gapp(\bm{x})$.
    The other verse of the inequality,
    $\frac{\tsp(\tilde{\bm{c}})}{\tilde{\bm{c}} \bm{x}} \leq \gapp(\bm{x})$,
    holds simply because $\gapp(\bm{x})$ is the maximum of such fractions.
    This proves $\frac{\tsp(\tilde{\bm{c}})}{\tilde{\bm{c}} \bm{x}} = \gapp(\bm{x})$.
\end{proof}

The following lemma is the first result that studies the behavior of \gapp\ under the application of the \bb-move.

\begin{lemma} \label{lem:bb_move_gap}
    The \bb-move is \gapp-increasing, that is, \
    $\gapp(\, \bb(\bm{x}) \, ) \geq \gapp(\bm{x})$ \ for all the vertices $\bm{x} \in \psep{n}$ \ for every $n\geq 3$.
\end{lemma}

\begin{proof}
    Let $\bm{x}_0 \in \psep{n}$ be a vertex with a $1$-edge $ab$.
    Let $\bm{x}_1 \in \psep{n+1}$ be the result of the \bb-move applied on $ab$: we denote $w$ the node added ($V_{n+1} := V_n \cup \{ w \}$) and $aw, wb$ the two $1$-edges originated by this move.
    Consider a metric cost $\bm{c}^0$ which realizes the \gapp\ on $\bm{x}_0$, namely
    $\gapp(\bm{x}_0) = \frac{\tsp(\bm{c}^0)}{\bm{c}^0 \bm{x}_0}$.
    We construct the metric $\bm{c}^1$ on $V_{n+1}$ adding the node $w$ at distance $0$ form $b$: \
    $c^1_{wb} = 0$, \
    $c^1_{vw} = c^0_{vb}$ \ for all nodes $v \in V_n \setminus b$ \ and \
    $c^1_{v_1 v_2} = c^0_{v_1 v_2}$ \ for all couples of nodes $v_1, v_2 \in V_n$.
    Clearly $\bm{c}^1$ is metric and $\bm{c}^1 \bm{x}_1 = \bm{c}^0 \bm{x}_0$.

    We first show that $\tsp(\bm{c}^0) \geq \tsp(\bm{c}^1)$.
    Let $\bm{t}_0$ be a tour on $K_n$ that is optimal for $\tsp(\bm{c}^0)$: $\tsp(\bm{c}^0) = \bm{c}^0 \bm{t}_0$.
    Let $\bm{t}^+_0$ be the tour on $K_{n+1}$ which retraces the steps of $\bm{t}_0$ but visits $w$ immediately after $b$, that is, if the sequence of nodes visited by $\bm{t}_0$ is \ $b, v_2, \dots, v_n$, \ then the sequence of nodes visited by $\bm{t}^+_0$ is \ $b, w, v_2, \dots, v_n$. \
    It is immediate to verify that $\bm{c}^1 \bm{t}^+_0 = \bm{c}^0 \bm{t}_0$: \
    $\bm{t}^+_0$ uses the same edges of $\bm{t}_0$, except for $aw$ and $wb$ in place of $ab$, which still involve the same cost $c^1_{aw} + c^1_{wb} = c^0_{ab} + 0$. 
    Therefore $\tsp(\bm{c}^1) \leq \bm{c}^1 \bm{t}^+_0 = \bm{c}^0 \bm{t}_0 = \tsp(\bm{c}^0)$.

    On the other hand, $\tsp(\bm{c}^1)$ is always larger than $\tsp(\bm{c}^0)$: given an optimal tour $\bm{t}_1$ for $\tsp(\bm{c}^1)$, we can always cut out $w$ to get a tour $\bm{t}^-_1$ with $\bm{c}^0 \bm{t}^-_1 \leq \bm{c}^1 \bm{t}_1$ by triangle inequality, thus \ $\tsp(\bm{c}^0) \leq \bm{c}^0 \bm{t}^-_1 \leq \bm{c}^1 \bm{t}_1 = \tsp(\bm{c}^1)$.

    Putting both the inequalities together, we have $\tsp(\bm{c}^1) = \tsp(\bm{c}^0)$, which finally proves
    $\gapp(\bm{x}_1) \geq \frac{\tsp(\bm{c}^1)}{\bm{c}^1 \bm{x}_1} = \frac{\tsp(\bm{c}^0)}{\bm{c}^0 \bm{x}_0} = \gapp(\bm{x}_0)$.
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%
% The Gap-Bounding algorithm
%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The \texorpdfstring{\gap}{Gap}-Bounding algorithm} \label{sec:gap_bounding}

This section is entirely devoted to finding a way to bound the \gapp\ for all the vertices of a given family $\cF_k$.
To achieve this goal, two main facts are exploited.
\begin{itemize}
    \item Any vertex of $\cF_k$ can be obtained starting from one ancestor in $\cA_k$ and sequentially applying the \bb-move finitely-many times.
    Moreover, the set of ancestors $\cA_k$ is finite.
    \item Knowing a vertex $\bm{x}_0$, it is possible to give a bound on $\gapp(\bb(\bm{x}_0))$: we can contain the increase in \gapp\ originated by an iterative application of a \bb-move, thus bounding $\gapp(\bm{x}')$ for any successor $\bm{x}'$ of $\bm{x}_0$.
\end{itemize}
The former has already been examined in \Cref{sec:families}; the latter is the core of this section.

To give a lower bound on \optp\ (which is equivalent to giving an upper bound on \gapp), we follow this simple idea.
Assume that we are given a vertex $\bm{x}_0$ alongside with an optimal solution of $\optp(\bm{x}_0)$ and an optimal solution of the dual problem $\dual\optp(\bm{x}_0)$.
When considering a successor $\bm{x}'$ of $\bm{x}$, we may try to produce a feasible dual solution of $\dual\optp(\bm{x}')$ starting from the optimal dual solution of $\dual\optp(\bm{x}_0)$: succeeding in this task will directly result in a lower bound for $\optp(\bm{x}')$, as guaranteed by the well known weak duality theorem.
Clearly, in this procedure, the key point is not just a matter of finding \emph{any} feasible dual solution, but rather of finding a \emph{good-enough} feasible dual solution, so that the bound obtained is meaningful (e.g., the trivial dual solution of all zeros ultimately gives no bound on \gapp).


%%%%%%%%%% Dual formulations of the OPT+ problem
\subsection{Dual formulations of the \texorpdfstring{\optp}{OPT+} problem} \label{sec:doptp_ii}

The dual problem of \optp\ \eqref{eq:optp_obj} -- \eqref{eq:optp_var} is the following.
\begin{align}
    \dual\optp(\bm{x}) := \
    \text{maximize \ \ }
        & \sum_{\bm{t} \text{ tour }} \mu_{\bm{t}}
            \label{eq:doptp_obj} \\
    \text{subject to: \ }
        & \sum_{k \neq i, j}(-\lambda_{ijk} +\lambda_{ikj} +\lambda_{jki})
            + \sum_{\bm{t} \text{ tour }} t_{ij} \mu_{\bm{t}} \ \leq x_{ij}
            & & \forall ij \in E_n,
            \label{eq:doptp_constr} \\
        & \lambda_{ijk} \ \geq 0
            & & \forall ij \in E_n, \ k \in V_n \setminus \{ i, j \},
            \label{eq:doptp_var_lambda} \\
        & \mu_{\bm{t}} \ \geq 0
            & & \forall \bm{t} \text{ tour on $K_n$}.
            \label{eq:doptp_var_mu}
\end{align}
Notice that the abuse of notation $ij \equiv ji \in E$ induces also $\lambda_{ijk} \equiv \lambda_{jik}$; this fact does not involve the third index: $\lambda_{ijk} \not\equiv \lambda_{kji}$
\footnote{With the symbol $\equiv$, we do not mean that two distinct variables have the same value; rather, we mean that the two notations coincide: they denote the same variable.}.

When considering a vertex $\bm{x}$ and one of its successors $\bm{x}'$, the task of producing a feasible solution of $\dual\optp(\bm{x}')$ starting from an optimal solution of $\dual\optp(\bm{x})$ is anything but trivial.
%
In what follows, we design an equivalent formulation and make use of it instead: \ $\dual\optii$.
Its main purpose is to get rid of $\bm{\lambda}$ variables: this is achieved at the price of considering walks on $G_{\bm{x}}$ (see \Cref{def:walk} and \Cref{rem:walk_mult}) in place of tours.

\begin{align}
    \dual\optii(\bm{x}) := \
    \text{maximize \ \ }
        & \sum_{\bm{w} \text{ walk on $G_{\bm{x}}$}} \mu_{\bm{w}}
            \label{eq:doptii_obj} \\
    \text{subject to: \ }
        & \sum_{\bm{w} \text{ walk on $G_{\bm{x}}$}} w_{ij} \mu_{\bm{w}} \ \leq x_{ij}
            & & \forall ij \in E_{\bm{x}},
            \label{eq:doptii_constr} \\
        & \mu_{\bm{w}} \ \geq 0
            & & \forall \bm{w} \text{ walk on $G_{\bm{x}}$}.
            \label{eq:doptii_var_mu}
\end{align}

The equivalence of the two formulations $\dual\optp(\bm{x})$ and $\dual\optii(\bm{x})$ (that is, they have the same optimal value) is stated in the following lemma; the proof is rather technical and it is deferred in Section \ref{sec:proof_opti_2}.

\begin{lemma} \label{lem:doptp_ii}
    $\dual\optp(\bm{x}) = \dual\optii(\bm{x})$ \ for every vertex $\bm{x}$ of $\psep{n}$.
\end{lemma}


%%%%%%%%%% Bounding the gap on successors
\subsection{Bounding the \texorpdfstring{\gap}{Gap} on successors} \label{subsec:bounding_gap}

Given the equivalence of the formulations $\dual\optp$ and $\dual\optii$, the goal of this section is to derive a feasible solution of $\dual\optii(\bm{x}')$ starting from an optimal solution of $\dual\optii(\bm{x}_0)$, where $\bm{x}'$ is a generic successor of $\bm{x}_0$.
This will ultimately give a bound on $\gapp(\bm{x}')$.

Let $\bm{x}_0$ be a vertex of $\psep{n}$ and let $\bm{\mu}^0 \in \arg\max \dual\optii(\bm{x}_0)$.
%
We consider a $1$-edge $ab$ of $\bm{x}_0$ and apply $d$ consecutive \bb-moves (see \Cref{def:BBmove}), inserting nodes \ $a_1, \dots, a_d$ \ and obtaining, by \Cref{thm:bb_move}, the vertices \ $\bm{x}_k := \bb(\bm{x}_{k-1}, \ a_{k-1} b)$ \ for all $k = 1, \dots, d$ \ (where $a_0 := a$).
We aim to design a feasible solution for 
$\dual\optii(\bm{x}_d)$.

To obtain an assignment $\bm{\mu}^d$ for $\dual\optii(\bm{x}_d)$ we have to construct walks $\bm{w}^d$ on $G_{\bm{x}_d}$ starting from the walks $\bm{w}^0$ on $G_{\bm{x}_0}$.
In this perspective, we divide the latter into three families, according to how many times the edge $ab$ is traversed: \
we define \ $\cW^{ab}_m := \{ \bm{w} \text{ walk} \ \mid \ w_{ab} = m \}$ \ for $m = 0, 1, 2$.
%
\begin{itemize}
    \item If $\bm{w}^0 \in \cW^{ab}_0$, we construct the following $d \!+\! 1$ walks on $G_{\bm{x}_d}$. \
    For each $k = 0, \dots, d$, \ the walk $\bm{w}^d_k$ retraces $\bm{w}^0$ but, when it arrives at $a$, it deviates to pass through $a_1, a_2, \dots, a_k$ (the nodes inserted via the \bb-moves) and back, and when it arrives at $b$, it deviates to $a_d, a_{d-1}, \dots, a_{k+1}$ and back.

    We set $\mu^d_{\bm{w}^d_k} := \frac{1}{d+1} \mu^0_{\bm{w}^0}$ \ for all $k = 0, \dots, d$.

    \item If $\bm{w}^0 \in \cW^{ab}_1$, we construct the walk $\bm{w}^d$ on $G_{\bm{x}_d}$ as the walk that retraces $\bm{w}^0$ but replaces the passage on $ab$ by passing through $a a_1, a_1 a_2, \dots, a_{d-1} a_d, a_d b$.

    We set $\mu^d_{\bm{w}^d} := \mu^0_{\bm{w}^0}$.

    \item If $\bm{w}^0 \in \cW^{ab}_2$, we construct the walk $\bm{w}^d$ on $G_{\bm{x}_d}$ as the walk that retraces $\bm{w}^0$ but replaces the double passage on $ab$ by passing twice through $a a_1, a_1 a_2, \dots, a_{d-1} a_d, a_d b$.

    We set $\mu^d_{\bm{w}^d} := \mu^0_{\bm{w}^0}$.
\end{itemize}
For all the walks $\bm{w}^d$ on $G_{\bm{x}_d}$ not obtained this way, we set $\mu^d_{\bm{w}^d} := 0$.
\Cref{fig:BB_walks_constructions} illustrates the new assignment $\bm{\mu}^d$ for $d = 2$.

\begin{figure}[htbp]
    \centering
    \input{BB_walks_constructions}
    \caption{Construction of $\bm{\mu}^2$ variables for $\dual\optii(\bm{x}_2)$ \ starting from $\bm{\mu}^0$ variables for $\dual\optii(\bm{x}_0)$.}
    \label{fig:BB_walks_constructions}
\end{figure}

Direct explicit computations (reported in \Cref{subsec:tech_GB}) show that: \
(i) $\bm{\mu}^d$ attains the same objective value as $\bm{\mu}^0$; \
(ii) $\bm{\mu}^d$ satisfies all the constraints~\eqref{eq:doptii_constr}, except for the ones associated to the edges of the $1$-path $a a_1 \dots a_d b$, where, anyway, the value of the constraint does not exceed a fixed constant $C(\bm{x}_0, ab)$.
The factor $C(\bm{x}_0, ab)$ depends only on the starting vertex $\bm{x}_0$ and the edge $ab$ chosen for the application of the \bb-moves; it is obtained as
$$
C(\bm{x}_0, ab) :=
2 \!\!\! \sum_{\bm{w}^0 \in \cW^{ab}_0} \mu^0_{\bm{w}^0} \ + \
         \sum_{\bm{w}^0 \in \cW^{ab}_1} \mu^0_{\bm{w}^0} \ + \
2 \!\!\! \sum_{\bm{w}^0 \in \cW^{ab}_2} \mu^0_{\bm{w}^0} \ .
$$
%
We can thus rescale $\bm{\mu}^d$ by the factor $C(\bm{x}_0, ab)$ to get the feasible solution \
$\bm{\mu}^* := \frac{1}{C(\bm{x}_0, ab)} \bm{\mu}^d$; \
the objective value of $\bm{\mu}^*$ gets rescaled accordingly and becomes $\frac{1}{C(\bm{x}_0, ab)} \dual\optii(\bm{x}_0)$.
%
Therefore \ $\dual\optii(\bm{x}_d) \geq \frac{1}{C(\bm{x}_0, ab)} \dual\optii(\bm{x}_0)$, \
$\dual\optp(\bm{x}_d) \geq \frac{1}{C(\bm{x}_0, ab)} \dual\optp(\bm{x}_0)$ \ by \Cref{lem:doptp_ii}, \
$\optp(\bm{x}_d) \geq \frac{1}{C(\bm{x}_0, ab)} \optp(\bm{x}_0)$ \ by the strong duality theorem, \
and finally, by definition of $\optp$, \ $\gapp(\bm{x}_d) \ \leq \ C(\bm{x}_0, ab) \cdot \gapp(\bm{x}_0)$.

Notice that we expect $C(\bm{x}_0, ab)$ to be greater than or equal to $1$, otherwise we would obtain $\gapp(\bm{x}_d) < \gapp(\bm{x}_0)$, contradicting \Cref{lem:bb_move_gap}.

It is crucial to highlight that $C(\bm{x}_0, ab)$ does not depend on $d$, hence the bound found is valid for any vertex which is obtained expanding the $1$-edge $ab$ of $\bm{x}_0$ to a $1$-path of arbitrary length.

Our purpose now is to generalize the procedure to get a bound for all the successors of $\bm{x}_0$, obtained by expanding not just one but all its $1$-edges.
Let $e_1, \dots, e_p$ be the $1$-edges of $\bm{x}_0$ and consider the successor obtained expanding them to $1$-paths with $d_1, \dots, d_p$ internal nodes.
We expand the $1$-paths one by one, creating the vertices $\bm{x}^1, \dots, \bm{x}^p$.
%
Notice that here we are using superscript indices to distinguish these iterations from those of the previous argument:
Previously, we added nodes one by one to expand a $1$-edge to a $1$-path;
now we are expanding $1$-paths one by one to transform $\bm{x}_0$ into its successor $\bm{x}'$.
Each iteration of this latter argument encapsulates a full expansion of a $1$-edge to a $1$-path.
To be consistent with this notation, we may also use the superscript for the starting vertex \ $\bm{x}^0:= \bm{x}_0$.

The assignments of dual variables $\bm{\mu}^1, \dots, \bm{\mu}^p$  are thus created sequentially starting from $\bm{\mu}^0$, repeating the same constructions previously described.
The normalization of the assignment $\bm{\mu}^h$ is not performed at each iteration $h$; rather, the dual variables $\bm{\mu}^p$ are adjusted only at the very end of the procedure, to give a final $\bm{\mu}^*$ guaranteed to be feasible.

The constants \
$C(\bm{x}^{h-1}, e_h) :=
2 \sum_{\bm{w}^{h-1} \in \cW^{e_h}_0} \mu^{h-1}_{\bm{w}^{h-1}} +
  \sum_{\bm{w}^{h-1} \in \cW^{e_h}_1} \mu^{h-1}_{\bm{w}^{h-1}} +
2 \sum_{\bm{w}^{h-1} \in \cW^{e_h}_2} \mu^{h-1}_{\bm{w}^{h-1}}$ \
are computed at each iteration $h$, and serve as upper bounds on the value that the constraint~\eqref{eq:doptii_constr} attains, for the variables $\bm{\mu}^h$, on the $1$-path that expands $e_h$.
%
To normalize the last assignment $\bm{\mu}^p$ of the procedure, we retrieve the maximum factor
\ $C^*(\bm{x}^0) := \max_{h = 1, \dots, p} \{ C(\bm{x}^{h-1}, e_h) \}$ \
and define \ $\bm{\mu}^* := \frac{1}{C^*(\bm{x}^0)} \bm{\mu}^p$, \ which is feasible.
%
Again, since the objective value of the assignments has remained unvaried until the normalization, \
$\dual\optii(\bm{x}^p) \geq \frac{1}{C^*(\bm{x}^0)} \dual\optii(\bm{x}^0)$, \ \
$\dual\optp(\bm{x}^p) \geq \frac{1}{C^*(\bm{x}^0)} \dual\optp(\bm{x}_0)$, \ \
$\optp(\bm{x}^p) \geq \frac{1}{C^*(\bm{x}^0)} \optp(\bm{x}_0)$, \ \ and \ \
$\gapp(\bm{x}^p) \ \leq \ C^*(\bm{x}^0) \cdot \gapp(\bm{x}_0)$.

There is one last detail of this procedure that needs to be discussed: the dependence of $C(\bm{x}^{h-1}, e_h)$ on $\bm{x}^{h-1}$.
If our final bound relies on specific steps of the constructions, we fail the goal of finding a bound that holds for \emph{all} the successors of $\bm{x}^0$.
%
In fact, the dependence of $C^*(\bm{x}^0)$ from the choice of $d_1, \dots, d_p$ is only apparent: although the constructions performed at each iteration do depend on the lengths of the $1$-paths, the factors $C(\bm{x}^{h-1}, e_h)$ do not.
We would get the same constants even when applying no \bb-move at all, namely $d_1 = \dots = d_p = 0$: this means that, regardless of the order of application of \bb-moves during the construction, we may compute $C(\bm{x}^{h-1}, e_h)$ as if it was calculated at the very first iteration:
$$
C(\bm{x}^{h-1}, e_h) \ = \ C(\bm{x}^0, e_h) \ = \
2 \!\!\! \sum_{\bm{w}^0 \in \cW^{e_h}_0} \mu^0_{\bm{w}^0} \ + \
         \sum_{\bm{w}^0 \in \cW^{e_h}_1} \mu^0_{\bm{w}^0} \ + \
2 \!\!\! \sum_{\bm{w}^0 \in \cW^{e_h}_2} \mu^0_{\bm{w}^0} \ .
$$
%
The explicit computation that proves this fact is presented in \Cref{subsec:tech_GB}.

We are finally able to design the \gap-Bounding (\gb) algorithm as \Cref{alg:GB_algo}; its main purpose is clarified in the next theorem.

\begin{algorithm}
    \caption{\gap-Bounding algorithm} \label{alg:GB_algo}
    \begin{algorithmic}[1]
        \STATE \textsc{input}: $\bm{x} \in \psep{n}$ vertex \\[5pt]
        \STATE Solve $\dual\optii(\bm{x})$ and retrieve an optimal assignment of variables $\{ \mu_{\bm{w}} \}_{\bm{w} \text{ walk on } x}$.
        \FOR{each $e$ $1$-edge of $\bm{x}$}
            \STATE $\displaystyle
                C(\bm{x}, e) \ \gets \
                2 \sum_{\bm{w} \in \cW^e_0} \mu_{\bm{w}} +
                \sum_{\bm{w} \in \cW^e_1} \mu_{\bm{w}} +
                2 \sum_{\bm{w} \in \cW^e_2} \mu_{\bm{w}}$
        \ENDFOR
        \STATE $C^*(\bm{x}) \ \gets \ \max_e \{ C(\bm{x}, e) \}$
        \STATE $\gapp(\bm{x}) \ \gets \ \nicefrac{1}{\dual\optii(\bm{x})}$
        \STATE Return: $C^*(\bm{x}) \cdot \gapp(\bm{x})$
    \end{algorithmic}
\end{algorithm}

\begin{theorem} \label{thm:GB_algo}
    The \gap-Bounding algorithm, on input a vertex $\bm{x} \in \psep{n}$, returns a value $\gb(\bm{x})$ which is an upper bound for the gap of all the successors $\bm{x}'$ of $\bm{x}$: \
    $\gap(\bm{x}') \leq \gb(\bm{x})$.
\end{theorem}

\begin{proof}
    This whole section is the proof that \ $\gapp(\bm{x}') \leq C^*(\bm{x}) \cdot \gapp(\bm{x}) = \gb(\bm{x})$ \ for any successor $\bm{x}'$ of $\bm{x}$, and we already saw, by definition of $\gapp$, that \ $\gapp(\bm{x}') \geq \gap(\bm{x}')$.
\end{proof}

Notice that both the \gb\ algorithm and \Cref{thm:GB_algo} apply to all generic $\bm{x}$ vertices, without requiring that they be ancestors.

We conclude this section with the following lemma, which will be of great help in improving computational results.

\begin{lemma}\label{lemma:bound_ancestors}
    Let $\bm{x} \in \psep{n}$ be a vertex and let $\bm{x}_0$ be its ancestor.
    Then $\gb(\bm{x})$ gives a bound for the gap of all the successors $\bm{x}'$ of $\bm{x}_0$ (even when $\bm{x}'$ is not a successor of $\bm{x}$): \
    $\gap(\bm{x}') \leq \gb(\bm{x})$.
\end{lemma}

\begin{proof}
    Let $\bm{x}'$ be a successor of $\bm{x}_0$.
    Let $e_1, \dots, e_p$ be the $1$-edges of $\bm{x}_0$ \ and let $d_1, \dots, d_p$ and $d'_1, \dots, d'_p$ be the lengths of the corresponding $1$-paths of $\bm{x}$ and $\bm{x}'$, respectively.
    Consider the successor $\tilde{\bm{x}}$ of $\bm{x}_0$ whose $1$-paths have $\max(d_1, d'_1), \dots, \max(d_p, d'_p)$ internal nodes.
    Then $\tilde{\bm{x}}$ is a successor of $\bm{x}'$, hence \ $\gapp(\bm{x}') \leq \gapp(\tilde{\bm{x}})$ \ for \Cref{lem:bb_move_gap}, \
    and $\tilde{\bm{x}}$ is a successor of $\bm{x}$ as well, hence \ $\gapp(\tilde{\bm{x}}) \leq \gb(\bm{x})$ \ for the previous theorem.
    This proves the lemma.
\end{proof}


