\subsection{Convergence Analysis} 
For Design \ref{design1}, CoGC with a recovery guarantee, the convergence is guaranteed \cite{raviv2020gradient}. This section extends our previously non-convex convergence analysis in \cite{weng2024supplementaryfilecooperativegradient} for Design \ref{design2} by relaxing the condition on $T$ from infinite to large yet finite. The non-convex convergence analysis can generally provide insights into modern deep neural networks (DNNs).

To begin with, we state several assumptions on the local objective function to ensure a feasible analysis.
\begin{assumption}[{$L$-Smoothness}]
    Each local objective function is bounded by $F_m(x)\geq F^\star$ and is differentiable, its gradient $\nabla F_m(x)$ is L-smooth, i.e., $\lVert \nabla F_m(x)-\nabla F_m(y) \rVert\leq L\lVert x-y \rVert$, $\forall i \in [M]$.
\end{assumption}
\begin{assumption}[Unbiasedness and Bounded Variance]
   The local stochastic gradient is an unbiased estimation, i.e., $\mathbb{E}_\xi[\nabla F_m(x,\xi)]=\nabla F_m(x)$, and has bounded data variance $\mathbb{E}_\xi[\lVert \nabla F_m(x,\xi)-\nabla F_m(x)\rVert^2]\leq \sigma^2 $, $\forall i \in [M]$. 
\end{assumption}
\begin{assumption}[Bounded Heterogeneity]
    The dissimilarity between $\nabla F_m(x)$ and $\nabla F(x)$ is bounded, i.e., $\lVert \nabla F_m(x)-\nabla F(x)\rVert^2\leq D_m^2$, $\forall i \in [M]$. 
\end{assumption}
Based on assumptions 1--3, and Lemmas 2--4 in \cite{weng2024supplementaryfilecooperativegradient}, we derive a convergence bound with a probability guarantee of $99.86\%$, formally stated below.
\begin{theorem}\label{theo:convergence CoGC}
Given $I$ local training iterations, for any algorithm that results in binary recovery of the global model with failure probability of $P_O$ per round and updates the global model as in (\ref{eq:local_initial}), if the learning rate is set as $\eta=\frac{1}{L}\sqrt{\frac{M}{T}}$ and the number of training rounds $T$ is  is sufficiently large but finite, the following convergence bound holds with probability more than $99.86\%$, 
\begin{align*}
    &\min_{r\in [T]} \mathbb{E}\left[\left\lVert\nabla F(\boldsymbol{g}_{r}^{0}) \right\rVert^2\right] 
    \\
    &\leq\frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}}+3\left( \frac{\sigma_{\mathcal{J}_2}^2}{\mu_{\mathcal{J}_1}^2T}+\frac{\mu_{\mathcal{J}_2}^2\sigma_{\mathcal{J}_1}^2}{\mu_{\mathcal{J}_1}^4T}+2\frac{\mu_{\mathcal{J}_2}\sigma_{\mathcal{J}_1} \sigma_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}^3 T} \right)\overset{\triangle}{=}\epsilon(P_O),
    \numberthis
    \label{eq_theorem1}
\end{align*}
where $\mu_{\mathcal{J}_1}$, $\mu_{\mathcal{J}_2}$, $\sigma_{\mathcal{J}_1}$ and $\sigma_{\mathcal{J}_2}$ are given in (\ref{eq:E_J1}), (\ref{eq:E_J2}), (\ref{eq:sigma1^2}), and (\ref{eq:sigma2^2}) respectively. 
\end{theorem}
\begin{proof}
    Proof of Theorem 1 is provided in Appendix \ref{appx: Proof of Theorem 1}. 
\end{proof}
\begin{remark}
    Given the choice of $\eta=\frac{1}{L}\sqrt{\frac{M}{T}}$, the optimility gap converges to $0$ with rate $\mathcal{O}\left(\frac{1}{\sqrt{T}}\right)$.
\end{remark}
\begin{remark}\label{remark: convergence wrt data hetero}
    From \cite[Theorem 1]{weng2024cooperative}, the convergence bound is magnified by $\frac{1}{1-P_O}\sum_{k=1}^K\omega_m D_m^2$ if $P_O\rightarrow 1$.
\end{remark}
