\section{GC$^+$: Enhanced Reliability by\\ Recycling the Wastes} \label{sec: GC$^+$}  If more than $s$ incomplete partial sums are present at the PS, it is impossible to compute the exact sum by the standard GC decoding mechanism. However, instead of discarding these incomplete partial sums, leveraging their remaining information can be valuable for reconstructing the global model. This section introduces such a decoding mechanism, named GC$^+$, which enhances the original GC decoding approach by integrating a complementary decoding strategy.
{The GC$^+$ improves straggler tolerance by leveraging the inherent structure of perturbed coefficient matrices caused by communication disruptions. This improvement can even enable retrievals of all local models and recover the exact global model, possibly within one complete transmission round in CoGC.
}



%%%%%%%---------------------------------------
\vspace{-0.5em}
\subsection{The GC$^+$ Decoding}
Below, we present the GC$^+$ decoding mechanism under the CoGC framework, highlighting its differences from the standard GC decoding mechanism. The complete training procedure is outlined in Algorithm \ref{alg:GC$^+$}, while the GC$^+$ is detailed in Algorithm \ref{algo:GC$^+$_decoding}\footnote{Algorithm \ref{algo:GC$^+$_decoding} is an approximate detection of the full-rank blocks with significantly reduced complexity. Due to dominance by full recovery, the approximation is sufficiently good. } (in MATLAB syntax).
\begin{itemize}[leftmargin=*, topsep=1pt, itemsep=1mm, parsep=0pt, label=$\blacktriangleright$] 
    \item \textbf{Broadcasting}: At the beginning of the $r$-th round training, PS broadcasts the latest global model $\boldsymbol{g}_{r-1}$ to all clients.     
    \item The \textbf{Local Training} follows standard procedures in (\ref{eq:Local_update}).
    \item \textbf{Communication:} For ease of reliability analysis, a fixed number of repeated communications, $t_r$, is assumed. However, it is worth noting that the communication can also be repeated until PS can decode a subset of individuals without a preset threshold. The gradient-sharing phase is identical to Section \ref{sec: CoGC}. 
%Unlike CoGC, communication in the $r$-th training round occurs over $t_r$ rounds. However, the \textit{D2D Communication} process remains identical to that in CoGC during each communication round. 
However, to enable the GC$^+$ mechanism, both the complete and incomplete partial sums need to be transmitted to the PS. 
%\subsubsection*{Client-to-PS Communication} Unlike CoGC, all clients send their computed partial sums in (\ref{eq:partial sum}) to PS, complete or incomplete. 
In each communication round, say $i_r$-th, $i_r\in [t_r]$, the GC matrices pair, $\boldsymbol{A}_{i_r}$ and $\boldsymbol{B}_{i_r}$, is generated independently. Through the intermittent networks, the coefficients of the partial sums, $\hat{\boldsymbol{B}}_{i_r}$, received at PS, is given by 
\begin{align*}
\hat{\boldsymbol{B}}_{i_r}=\left(\boldsymbol{B}_{i_r} \circ \boldsymbol{\mathcal{T}}_{i_r}(r)\right)\bullet\boldsymbol{\tau}_{i_r}(r),
\numberthis
\label{eq: perturb_B}
\end{align*}
where $\bullet$ denotes the row-wise face-splitting product, and $\boldsymbol{\tau}_{i_r}(r)$ and $\boldsymbol{\mathcal{T}}_{i_r}(r)$ follows a similar definition as $\boldsymbol{B}_{i_r}$. 
%All transmissions are assumed to be orthogonal and independent. 
\item \textbf{The GC$^+$ Decoding:}  
If PS manages to collect at least $n-s$ complete partial sums in \textbf{any} communication round, it computes the global model using the standard GC decoding mechanism in (\ref{eq: global_update_at_PS}).
Otherwise, the PS applies the following complementary decoding mechanism. First, PS identifies the largest determined or overdetermined submatrix, $\hat{\boldsymbol{B}}_{\mathrm{sub}}$, within the vertically stacked received coefficient matrices in the $r$-th training round, $\hat{\boldsymbol{B}}(r)=[\hat{\boldsymbol{B}}_{1}; \cdots; \hat{\boldsymbol{B}}_{t_r}]$. 
%Here,  $\hat{\boldsymbol{B}}_{i_r}$ denotes the received coefficient matrix at PS during the $i_r$-th communication round. 
The $\hat{\boldsymbol{B}}_{\mathrm{sub}}$ can be formed by excluding certain rows in $\hat{\boldsymbol{B}}(r)$. The detection of $\hat{\boldsymbol{B}}_{\mathrm{sub}}$ is outlined in Algorithm \ref{algo:detect_hatB}. If such $\hat{\boldsymbol{B}}_{\mathrm{sub}}$ exists, the corresponding local models, denoted by the set $\mathcal{K}_4(r)$, can be recovered by solving the matrix equation associated with the received partial sums. The global model is then updated as 
\begin{align*}
   \boldsymbol{g}_r=\frac{1}{\lvert \mathcal{K}_4(r)\rvert} \sum_{m\in \mathcal{K}_4(r)} \boldsymbol{g}_{m,r}.
   \numberthis
   \label{eq: GullGC_PSagg}
\end{align*}
As will be seen in Fig. \ref{fig: count for full recovery}, the probability of the PS decoding nothing is low. Thus, it is reasonable to condition the global model update on the non-empty set of decoded local models when GC$^+$ applies. The communication process repeats until the PS can decode at least one local model. 
\end{itemize}




\begin{algorithm}[t]
\caption{Training Process Using GC$^+$ in CoGC}\label{alg:GC$^+$}
\KwIn{$T$}
\KwOut{$\boldsymbol{g}_r$}
\textbf{Initialize:} $\boldsymbol{ g}_0 \gets 0$; $r \gets 1$; $\mathcal{K}_4(r), \hat{\boldsymbol{B}}(r)\gets\emptyset$; $t_r\gets 0$;\\
\While{$r\leq T$}{
    PS broadcasts $\boldsymbol{g}_{r-1}$ to all clients\;
    \For{$m=1,\cdots,M$}{
    Client $m$ sets $\boldsymbol{g}_{m,r}^{0}=\boldsymbol{g}_{r-1}$\;
    Client $m$ performs $I$-step SGD as (\ref{eq:Local_update})\;
    }
    \While{$\mathcal{K}_4(r)=\emptyset$}{
    \For{$i_r=1, \cdots, t_r$}{
    \For{$m=1,\cdots,M$}{
    Client $m$ sends  $b_{km}^{i_r} \boldsymbol{g}_{m,r}$ to client $k\in\mathcal{K}_1(m)$\;
    Client $m$ hears from clients in $\mathcal{K}_2(m)$\;
    Client $m$ computes and transmits (\ref{eq:partial sum}) to PS\;
    $\hat{\boldsymbol{B}}(r)=[\hat{\boldsymbol{B}}(r); \hat{\boldsymbol{B}}_{i_r}]$
    }}
    PS performs GC$^+$ decoding as in Algorithm \ref{algo:GC$^+$_decoding}\;
    }
    $r=r+1$;
    }  
\end{algorithm}
\begin{remark}
    While GC$^+$ provides flexibility and enhanced resilience against stragglers, it compromises privacy at the PS, as the PS can decode individual local models. However, it remains secure against potential eavesdroppers during client-to-PS communication. 
    {To further address privacy concerns, GC$^+$ can be seamlessly combined with e.g., the Gaussian mechanism, enhancing privacy preservation. }
\end{remark}

\begin{algorithm}[t]
\caption{Detection of $\hat{\boldsymbol{B}}_{\mathrm{sub}}$}\label{algo:GC$^+$_decoding}\label{algo:detect_hatB}
\KwIn{$\hat{\boldsymbol{B}}(r)$ of size $Mt_r \times M$}
\KwOut{$\hat{\boldsymbol{B}}_{\mathrm{sub}}(r)$, $\mathcal{K}_4(r)$, $\boldsymbol{g}_r$}
\eIf{$\forall i_r\in [t_r]: \hat{\boldsymbol{B}}_{i_r}$ contains $s$ complete rows}{
PS computes the global model as in (\ref{eq: global_update_at_PS}) \;
$\mathcal{K}_4(r)=[M]$\;
}{
$\boldsymbol{E}(r)=\mathrm{rref}(\hat{\boldsymbol{B}}(r))$\;
\Comment{Compute the reduced row Echelon form of $\hat{\boldsymbol{B}}(r)$}
$\mathcal{K}_4(r)\defeq\{i\in [M]: \boldsymbol{e}(:,i)\in\boldsymbol{E}(r), \boldsymbol{e}(:,i)\neq \boldsymbol{0}_{Mt_r\times 1}\}$\;
$\mathcal{K}_5(r)\defeq\{i\in [Mt_r]:\boldsymbol{e}(i,:)\in\boldsymbol{E}(r), \boldsymbol{e}(i,:)\neq \boldsymbol{0}_{1\times M}\}$\;
\Comment{Detect the nonzero columns and rows in $\boldsymbol{E}(r)$}
\eIf{$\lvert \mathcal{K}_4(r) \rvert<\lvert \mathcal{K}_5(r) \rvert $}{
$\{\boldsymbol{g}_{k,r}: k\in \mathcal{K}_4(r)\} $ can be solved using the associated received partial sums\;
PS computes the global model as in (\ref{eq: GullGC_PSagg});\\
}{
$\mathcal{K}_4(r)=\emptyset$\;
}
}
\end{algorithm}
