\subsection{Convergence Analysis}
Building on the analysis of the success bound, we establish the following properties of GC$^+$. These results address the intertwined decoding of individual models arising from the decoding mechanism. Details can be found in Appendix B.
\begin{lemma}[Bounded Averaging in Coded Networks]\label{lemma: GC$^+$}
For any algorithm, if the PS can observe all possible sets of the given cardinality with equal probability, 
%of decoded local models is equally likely given that the PS observes $K_r$ local models, $\forall K_r \in \{1,\cdots, M\}$, 
the update rule of the global model in (\ref{eq: GullGC_PSagg}) is unbiased, i.e., 
\begin{align*}   
\mathbb{E}_{\mathcal{K}_4(r)}\left[\sum_{m\in \mathcal{K}_4(r)} \frac{1}{\lvert \mathcal{K}_4(r)\rvert}  \boldsymbol{g}_{m,r}\Bigg \vert \mathcal{K}_4(r)\neq \emptyset\right]=\sum_{m=1}^M \frac{1}{M}\boldsymbol{g}_{m,r}.
\numberthis
\label{eq:lemma3-1}
\end{align*} 
Additionally, it also holds that 
\begin{align*}   
\mathbb{E}_{\mathcal{K}_4(r)}\left[\sum_{m\in \mathcal{K}_4(r)} \frac{1}{\lvert \mathcal{K}_4(r)\rvert^2} \boldsymbol{g}_{m,r}\Bigg \vert \mathcal{K}_4(r)\neq \emptyset\right]\triangleq\sum_{m=1}^M \Bar{\alpha}_m \boldsymbol{g}_{m,r},
\numberthis
\label{eq:lemma3-2}
\end{align*}
where $\Bar{\alpha}_m=\frac{1}{M\Bar{K}}$. Furthermore, by adopting GC$^+$, $\frac{1}{\Bar{K}}$ is upper bounded by $\frac{1}{\Bar{K}_r}\leq  \frac{\check{P}_M \sum_{m=1}^{M-1}\frac{1}{m}}{1-\min\{ P_O^{t_r}, 1- \check{P}_M \}} +\frac{1}{M} \triangleq \frac{1}{K^\star}$ with $\check{P}_M $ given in (\ref{eq:check_PM}).
\end{lemma}
%%%%%%%%%-----------------------------------------------------------------------------------
%%%%%%-------------------------------------------------------------
With the help of Lemma \ref{lemma: GC$^+$} and under Assumptions 1–3, we derive the non-convex convergence rate of GC$^+$.
\begin{theorem}\label{theo:GC$^+$}
Let assumption 1$\sim$3 hold, and choose $\eta=K^\star/(8LTI)^{\frac{1}{2}}$ with $I\leq (TI)^{\frac{1}{4}}/K^{\star\frac{3}{4}}$. By adopting GC$^+$ in CoGC, the optimality gap satisfies
\begin{align*}   
&\frac{1}{T}\sum_{r=1}^T\mathbb{E}\left[\lVert\nabla F(\boldsymbol{g}_r) \rVert^2  \big\vert \mathcal{K}_4(r)\neq \emptyset \right] \leq \\
&\frac{496 L}{11(TIK^{\star})^{\frac{1}{2}}}\left( \mathbb{E}\left[F(\boldsymbol{g}_0)\right]-F^\star \right)\\
&+\frac{31}{88(TI)^\frac{3}{2}K^{\star\frac{1}{2}}}\sum_{r=1}^{T}\sum_{m=1}^{M} \frac{1}{M} J_{m,r}^2\\
&+\left(\frac{39}{88(TIK^{\star})^{\frac{1}{2}}}+\frac{1}{88(TIK^{\star})^{\frac{3}{4}}}\right)\frac{\sigma^2}{b}+\\
&\left( \frac{4}{11(TIK^{\star})^{\frac{1}{2}}}+\frac{1}{22(TIK^{\star})^{\frac{3}{4}}} +\frac{31}{22(TI)^\frac{1}{4}K^{\star\frac{5}{4}}} \right)\hspace{-1mm}\sum_{m=1}^{M}\frac{1}{M} D_m^2.
\numberthis \label{eq:theorem 1}
\end{align*}
\end{theorem}
\begin{proof}[Proof Sketch]
    It can be verified that Lemmas 2–4 from the supplementary material of \cite{10802992} remain valid. Therefore, Theorem~\ref{theo:GC$^+$} can be proved by following similar steps to those of \cite[Theorem 1]{10802992}. 
\end{proof}
