\section{Proof of Theorem \ref{theo:convergence CoGC}}\label{appx: Proof of Theorem 1}
With the help of Lemma 2$\sim$4 in \cite{weng2024supplementaryfilecooperativegradient}, the first half proof of Theorem 1 is the same as in \cite{weng2024supplementaryfilecooperativegradient}, here, we begin with the preliminary bound acquired in (28) in \cite{weng2024supplementaryfilecooperativegradient}, i.e.,  
\begin{align*}
    &\frac{1}{T}\sum_{r\in [T]} H_1\mathbb{E}\left[\left\lVert\nabla F(\boldsymbol{g}_{r}^{0}) \right\rVert^2\right]\leq \frac{1}{T}H_2\left(F^\star-F(\boldsymbol{g}_{r}^0)\right)\\
    &\hspace{1.5cm}+\frac{1}{T}\sum_{r\in [T]}H_3\sum_{m=1}^M p_m D_m^2
    +\frac{1}{T}\sum_{r\in [T]}H_4 \sigma^2,
\numberthis
\label{eq:theorem1_tau_pre}
\end{align*}
where
\begin{subequations}
\begin{align}
    &H_1=\frac{1}{2}R_r-H_3,\\
    &H_2=\frac{1}{\eta I },\\
    &H_3=2\eta R_r^2 I L+\eta^2\frac{\frac{2}{3}L^2R_r(R_r I\hspace{-1mm}+\hspace{-1mm}1)(2R_r I\hspace{-1mm}+\hspace{-1mm}1)(\frac{1}{2}\hspace{-1mm}+\hspace{-1mm}\eta R_r I L)}{1-R_r I(R_r I+1)\eta^2L^2},\\
    &H_4=\frac{1}{2}\eta R_r L \sum_{m=1}^M p_m^2+\eta^2\frac{\frac{1}{2}L^2R_r(R_r I+1)(\frac{1}{2}+\eta R_r I L)}{1-R_r I(R_r I+1)\eta^2L^2}.
\end{align}
\end{subequations}
By choosing $\eta=\frac{1}{L}\sqrt{\frac{M}{T}}$ and $T$ large, $H_1 \sim H_4$ is dominated by $\mathcal{O}(1/\sqrt{T})$, (\ref{eq:theorem1_tau_pre}) can be approximated as follows, 
\begin{align*}
    \Bar{\mathcal{J}}_1(R_r)\cdot  \min_{r\in [T]} \mathbb{E}\left[\left\lVert\nabla F(\boldsymbol{g}_{r}^{0}) \right\rVert^2\right] \leq \Bar{\mathcal{J}}_2(R_r),
    \label{eq:approx}
    \numberthis
\end{align*}
where
\begin{subequations}
\begin{align*}
    &\Bar{\mathcal{J}}_1(R_r)=\frac{1}{T}\sum_{r\in [T]}\mathcal{J}_1(R_r)=\frac{1}{T}\sum_{r\in [T]} \left( \frac{1}{2}R_r-2I\sqrt{\frac{M}{T}} R_r^2 \right),\numberthis\\
    &\Bar{\mathcal{J}}_2(R_r)= \frac{L}{TI}\sqrt{\frac{T}{M}}\left(F^\star-F(\boldsymbol{g}_{r}^0)\right)+\\
    &
    \hspace{3mm}\frac{1}{T}\sum_{r\in [T]} \underbrace{\left(2I\sqrt{\frac{M}{T}}\sum_{m=1}^M p_m D_m^2 R_r^2 + \frac{\sigma^2}{2} \sqrt{\frac{M}{T}}\sum_{m=1}^{M} p_m^2 R_r\right)}_{\mathcal{J}_3(R_r)}.\numberthis
\end{align*}
\end{subequations}
%\begin{align*}
%    & \min_{r\in [T]} \mathbb{E}\left[\left\lVert\nabla %F(\boldsymbol{g}_{r}^{0}) \right\rVert^2\right]\\
%    \leq &\frac{L}{TI}\sqrt{\frac{T}{M}}\left(F^\star-%F(\boldsymbol{g}_{r}^0)\right)+\frac{1}{T}\sum_{r\in %[T]} 2I\sqrt{\frac{M}{T}}\sum_{m=1}^M p_m D_m^2 R_r^2\\
%    &+ \frac{1}{T}\sum_{r\in [T]} \frac{\sigma^2}{2} %\sqrt{\frac{M}{T}}\sum_{m=1}^{M} p_m^2 R_r
%    \numberthis
%\end{align*}

According to central limit theorem (CLT), when $T$ is chosen large but finite, $\mathcal{J}_1(R_r)$ and $\mathcal{J}_2(R_r)$ are asymptotically Gaussian r.v.s, below we compute the parameters characterizing the Gaussian distributions of $\mathcal{J}_1(R_r)$ and $\mathcal{J}_2(R_r)$, respectively. 
\begin{subequations}
\begin{align*}
    &\mu_{\mathcal{J}_1}=\mathbb{E}\left[ \mathcal{J}_1(R_r) \right]\\
    &\hspace{6mm}=\frac{1-P_O}{P_O}\left(\frac{1}{2}\mathrm{Li}_{-1}(P_O)-2I\sqrt{\frac{M}{T}}\mathrm{Li}_{-2}(P_O) \right),\numberthis \label{eq:E_J1}\\
    &\mathbb{E}\left[ \left(\mathcal{J}_1(R_r)\right)^2 \right]\hspace{-1mm}=\hspace{-1mm}\frac{1-P_O}{P_O}\Bigg(\frac{1}{4}\mathrm{Li}_{-2}(P_O)-2I\sqrt{\frac{M}{T}}\mathrm{Li}_{-3}(P_O)\\
    &\hspace{40mm}+4I^2\frac{M}{T}\mathrm{Li}_{-4}(P_O) \Bigg), \numberthis
    \label{eq:E_J1^2}
\end{align*}
\end{subequations}
where $\mathrm{Li}_{-v}(z)=\sum_{k=1}^\infty k^v z^k$ is the polylogarithm function and specific values can be computed by $\mathrm{Li}_{-v}(z)= \left(z\frac{\partial }{\partial z}\right)^v \frac{z}{1-z} $. In (\ref{eq:E_J1}) and (\ref{eq:E_J1^2}), we use the fact that $\sum_{k=1}^\infty k^v z^{k-1} (1-z)=\frac{1-z}{z} \mathrm{Li}_{-v}(z)$.

Subsequently, the variance $\sigma_{\mathcal{J}_1}^2$ of $\mathcal{J}_1(R_r)$ is given by
\begin{align*}
\sigma_{\mathcal{J}_1}^2=\mathbb{E}\left[\left(\mathcal{J}_1(R_r)\right)^2 \right]-\left(\mathbb{E}\left[ \mathcal{J}_1(R_r) \right]\right)^2.
    \numberthis
    \label{eq:sigma1^2}
\end{align*}
Similarly, we have
\begin{subequations}
\begin{align*}
    &\mu_{\mathcal{J}_3}=\mathbb{E}\left[\mathcal{J}_3(R_r)\right]\\
    &\hspace{6mm}=\frac{1-P_O}{P_O}\Bigg(\frac{\sigma^2}{2}\sqrt{\frac{M}{T}}\sum_{m=1}^Mp_m^2\mathrm{Li}_{-1}(P_O) \\
    &\hspace{2.5cm}+2I\sqrt{\frac{M}{T}}\sum_{m=1}^{M}p_mD_m^2\mathrm{Li}_{-2}(P_O) \Bigg), \label{eq:E_J3}
    \numberthis\\
    &\mathbb{E}\left[ \left(\mathcal{J}_3(R_r)\right)^2 \right]=\frac{1-P_O}{P_O}\Bigg( \frac{M\sigma^4}{4T}\left( \sum_{m=1}^Mp_m^2 \right)^2 \mathrm{Li}_{-2}(P_O)\\
    &\hspace{26mm}+\frac{4MI}{T}\left( \sum_{m=1}^Mp_m D_m^2\right)^2\mathrm{Li}_{-4}(P_O)\\
    &\hspace{5mm}+\frac{2MI}{T}\left( \sum_{m=1}^Mp_m^2 \right)\left( \sum_{m=1}^Mp_m D_m^2\right)\mathrm{Li}_{-3}(P_O)   \Bigg). \label{eq:E_J3^2} \numberthis
\end{align*}
\end{subequations}
Consequently, we have
\begin{subequations}
    \begin{align}
        &\mu_{\mathcal{J}_2}=\mathbb{E}\left[\mathcal{J}_2(R_r)\right]=\frac{L}{TI}\sqrt{\frac{T}{M}}\left(F^\star-F(\boldsymbol{g}_{r}^0)\right)+\mathbb{E}\left[\mathcal{J}_3(R_r)\right], \label{eq:E_J2}\\
        &\sigma_{\mathcal{J}_2}^2=\sigma_{\mathcal{J}_3}^2=\mathbb{E}\left[\left(\mathcal{J}_3(R_r)\right)^2 \right]-\left(\mathbb{E}\left[ \mathcal{J}_3(R_r) \right]\right)^2 \label{eq:sigma2^2}.
    \end{align}
\end{subequations}
According to CLT, we have
\begin{subequations}
\begin{align}
    &\Bar{\mathcal{J}}_1(R_r)\sim \mathcal{N}\left(\mu_{\mathcal{J}_1}, \frac{\sigma_{\mathcal{J}_1}^2}{T} \right),\\
    &\Bar{\mathcal{J}}_2(R_r)\sim \mathcal{N}\left(\mu_{\mathcal{J}_2}, \frac{\sigma_{\mathcal{J}_2}^2}{T}\right)
\end{align}    
\end{subequations}
where $\mu_{\mathcal{J}_1}$. $\sigma_{\mathcal{J}_1}^2$, $\mu_{\mathcal{J}_2}$, $\sigma_{\mathcal{J}_2}^2$ are given in (\ref{eq:E_J1})$\sim$(\ref{eq:sigma2^2}). 

A simple variation of (\ref{eq:approx}) gives
\begin{align*}
    \min_{r\in [T]} \mathbb{E}\left[\left\lVert\nabla F(\boldsymbol{g}_{r}^{0}) \right\rVert^2\right] \leq \frac{\Bar{\mathcal{J}}_1(R_r)}{\Bar{\mathcal{J}}_2(R_r)}.
    \numberthis
\end{align*}
Having determined the distribution of $\Bar{\mathcal{J}}_1(R_r)$ and $\Bar{\mathcal{J}}_2(R_r)$, with the help of Delta method, one can further approximate the distribution of $\frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_2(R_r)}$. First, approximate the non-linear ratio $\frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_1(R_r)}$ by linear functions around $\Bar{\mathcal{J}}_1(R_r)=\mu_{\mathcal{J}_1}, \Bar{\mathcal{J}}_2(R_r)=\mu_{\mathcal{J}_2}$ using first-order Taylor expansion as
\begin{align*}
    &\frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_1(R_r)} \approx \frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}}+\frac{1}{\mu_{\mathcal{J}_1}}\left(\Bar{\mathcal{J}}_2(R_r)- \mu_{\mathcal{J}_2} \right)\\
    &\hspace{2.3cm}-\frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1^2}}\left(\Bar{\mathcal{J}}_1(R_r)- \mu_{\mathcal{J}_1} \right),
    \numberthis
\end{align*}
So $\frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_2(R_r)}$ can be approximated as a Gaussian r.v. characterized by 
\begin{subequations}
    \begin{align*}
        &\mathbb{E}\left[ \frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_1(R_r)} \right]=\frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}},\numberthis\\
        &\sigma_{\Bar{\mathcal{J}}_2/\Bar{\mathcal{J}}_1}^2 \approx \frac{\sigma_{\mathcal{J}_2}^2/T}{\mu_{\mathcal{J}_1}^2}+\frac{\mu_{\mathcal{J}_2}^2\sigma_{\mathcal{J}_1}^2/T}{\mu_{\mathcal{J}_1}^4}\\
        &\hspace{26mm}-2\frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}^3}\mathrm{cov}\left( \Bar{\mathcal{J}}_2(R_r), \Bar{\mathcal{J}}_1(R_r)\right),
        \numberthis
    \end{align*}
\end{subequations}
when $T$ is large. 
It is difficult to give a closed-form expression of $\mathrm{cov}\left( \Bar{\mathcal{J}}_2(R_r), \Bar{\mathcal{J}}_1(R_r)\right)$, but it is possible to upper bound the $\sigma_{\Bar{\mathcal{J}}_2/\Bar{\mathcal{J}}_1}^2$. By Cauchy-Schwarz Inequality, it holds that 
\begin{align}
    \left\lvert\mathrm{cov}\left( \Bar{\mathcal{J}}_2(R_r), \Bar{\mathcal{J}}_1(R_r)\right)\right\rvert \leq \frac{\sigma_{\mathcal{J}_1} \sigma_{\mathcal{J}_2}}{T},
\end{align}
thus,
\begin{align}
    &\sigma_{\Bar{\mathcal{J}}_2/\Bar{\mathcal{J}}_1}^2\leq \frac{\sigma_{\mathcal{J}_2}^2}{\mu_{\mathcal{J}_1}^2T}+\frac{\mu_{\mathcal{J}_2}^2\sigma_{\mathcal{J}_1}^2}{\mu_{\mathcal{J}_1}^4T}+2\frac{\mu_{\mathcal{J}_2}\sigma_{\mathcal{J}_1} \sigma_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}^3 T}\overset{\triangle}{=} \sigma_{\mathrm{max}}^2.
    \label{eq:upperbound_variance_ratio}
\end{align}
To summarize, 
\begin{align*}
    \frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_1(R_r)}\sim \mathcal{N}\left(\frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}} , \sigma_{\Bar{\mathcal{J}}_2/\Bar{\mathcal{J}}_1}^2\right).
    \numberthis
\end{align*}
According to Three-Sigma Rule (3SR) and (\ref{eq:upperbound_variance_ratio}), $\frac{\Bar{\mathcal{J}}_2(R_r)}{\Bar{\mathcal{J}}_1(R_r)}\leq \frac{\mu_{\mathcal{J}_2}}{\mu_{\mathcal{J}_1}}+3\sigma_{\mathrm{max}}^2 $ w.p. larger than $99.86\%$. 




