\section{Proof of Lemma \ref{lemma: GC$^+$}}
\begin{proof}[Proof of (\ref{eq:lemma3-1})]
{First, we prove the unbiasedness of the global model recovery. In GC$^+$, when the standard GC decoding mechanism can work, (\ref{eq: global_update_at_PS}) is always met, and it can be categorized into the case when $\mathcal{K}_4(r)=[M]$. If the GC fails, the complementary decoding mechanism applies, $\mathcal{K}_4(r)$ can be any non-empty subset of $[M]$. Let $\mathcal{K}_4(r)$ contain all the decodable local models in $r$-th round and $\mathcal{K}_4^c(r)=[M]\setminus \mathcal{K}_4(r)$ contains all local models that can not be decoded by the PS. The unbiasedness of the updated rule in GC$^+$ is proved as follows,} 
\begin{subequations}
\begin{align}   
&\mathbb{E}_{\mathcal{K}_4(r)}\left[\sum_{m\in \mathcal{K}_4(r)} \frac{1}{\lvert \mathcal{K}_4(r)\rvert}  \boldsymbol{g}_{m,r}\Bigg \vert \mathcal{K}_4(r)\neq \emptyset\right]\\
&=\mathbb{E}_{K_r}\left[ \mathbb{E}_{\substack{ \mathcal{K}_4(r): \\ \lvert\mathcal{K}_4(r)\rvert=K_r }}\left[ \frac{1}{K_r}\sum_{m\in \mathcal{K}_4(r)}  \boldsymbol{g}_{m,r}\right] \right] \label{eq:client sampling}\\
&=\mathbb{E}_{K_r}\left[ \frac{1}{M}\sum_{m=1}^M \boldsymbol{g}_{m,r}\right]=\frac{1}{M}\sum_{m=1}^M \boldsymbol{g}_{m,r}.\label{eq:client sampling unbiased}
\numberthis
\end{align}
\end{subequations}
{For any possible sets $\mathcal{K}_4(r): \lvert\mathcal{K}_4(r)\rvert=K_r\neq 0$, $\mathcal{K}_4(r)$ can be viewed as a specific realization of uniformly sampling $K_r$ clients from $[M]$ without replacement, but induced by unreliable communications in the homogeneous network. Therefore, the inside layer of expectation in (\ref{eq:client sampling}) is unbiased and gives (\ref{eq:client sampling unbiased}), following the conclusion of Scheme II in \cite{li2019convergence}. }  
\end{proof}




\begin{proof}[Proof of (\ref{eq:lemma3-2})]
{Next, we prove the second conclusion in Lemma \ref{lemma: GC$^+$}. This proof partly refers to \cite[Appendix A]{wang2021quantized}, but ours tackles the challenge of the coded networks, where the decoding of individuals is intertwined due to coding blocks.} 
By expanding (\ref{eq:lemma3-2}), it holds that 
\begin{subequations}
\begin{align}
&\mathbb{E}_{\mathcal{K}_4(r)}\left[\sum_{m\in \mathcal{K}_4(r)} \frac{1}{\lvert \mathcal{K}_4(r)\rvert^2} \boldsymbol{g}_{m,r}\Bigg \vert \mathcal{K}_4(r)\neq \emptyset\right] \triangleq\sum_{m=1}^M \Bar{\alpha}_m \boldsymbol{g}_{m,r} \label{eq: 46a}\\
&=\sum_{K_r=1}^{M} \sum_{\substack{ \mathcal{K}_4(r): \\ \lvert\mathcal{K}_4(r)\rvert=K_r }} P(\mathcal{K}_4(r)) \cdot \frac{1}{K_r^2} \cdot\sum_{m\in \mathcal{K}_4(r)} \hspace{-3mm}\boldsymbol{g}_{m,r} \label{eq: 46b}\\
&=\sum_{K_r=1}^{M} P(K_r) \cdot \frac{1}{K_r^2} \cdot \sum_{\substack{ \mathcal{K}_4(r): \\ \lvert\mathcal{K}_4(r)\rvert=K_r }} \sum_{m\in \mathcal{K}_4(r)}\hspace{-3mm}\boldsymbol{g}_{m,r} \label{eq: simple variation}\\
&=\sum_{K_r=1}^{M} P(K_r) \cdot \frac{1}{K_r^2} \cdot \sum_{m=1}^M {M-1 \choose K_r-1}\cdot\boldsymbol{g}_{m,r} \label{eq: change count}\\
&=\sum_{K_r=1}^{M} {M \choose K_r} P(K_r) \cdot \frac{1}{K_r} \cdot \frac{1}{M}\sum_{m=1}^M \boldsymbol{g}_{m,r} \label{eq: com_rule}
\end{align}
\label{eq: alpha}
\end{subequations}
For homogeneous networks, $P(\mathcal{K}_4(r))$ is identical for every possible $\mathcal{K}_4(r): \lvert\mathcal{K}_4(r)\rvert=K_r\neq 0$, and depends only on the cardinality $K_r$. Let $ P(\mathcal{K}_4(r))=P(K_r)$, then we have (\ref{eq: simple variation}). The last two sums $\sum_{\substack{ \mathcal{K}_4(r):  \lvert\mathcal{K}_4(r)\rvert=K_r }} \sum_{m\in \mathcal{K}_4(r)} \boldsymbol{g}_{m,r}$ searches over all possible $\mathcal{K}_4(r)$ and sum up the local models $\boldsymbol{g}_{m,r}$ in all possible $\mathcal{K}_4(r)$. By maintaining the same search space, we can instead count the occurrence frequency of each $\boldsymbol{g}_{m,r}$ in all possible $\mathcal{K}_4(r)$ and sum them up. Hence, we obtain (\ref{eq: change count}). The (\ref{eq: com_rule}) holds due to $\frac{1}{M}{M\choose K_r}=\frac{1}{K_r}{M-1 \choose K_r-1}$.  

The (\ref{eq: alpha}) holds for any choice of $\boldsymbol{g}_{m,r}$. To compute $\Bar{\alpha}_m$, we can set $\boldsymbol{g}_{m,r}=1$. Then (\ref{eq: 46a}) gives
\begin{subequations}
\begin{align}
    &\mathbb{E}_{\mathcal{K}_4(r)}\left[\sum_{m\in \mathcal{K}_4(r)} \frac{1}{\lvert \mathcal{K}_4(r)\rvert^2} \cdot 1 \Bigg \vert \mathcal{K}_4(r)\neq \emptyset\right]\\
    &=\mathbb{E}_{\mathcal{K}_4(r)}\left[ \frac{1}{\lvert \mathcal{K}_4(r)\rvert}  \right]\triangleq \frac{1}{\Bar{K}_r}\label{eq: bar_k_ext}\\
    &=\sum_{K_r=1}^{M} {M \choose K_r} P(K_r) \cdot \frac{1}{K_r} \label{eq: bar_k_exp}
\end{align}
\end{subequations}
By comparing (\ref{eq: 46a}), (\ref{eq: com_rule}), and (\ref{eq: bar_k_ext}), we get
\begin{align}
     \Bar{\alpha}_m=\frac{1}{M\Bar{K}_r}. 
     \label{eq: bar_am}
\end{align}
Define $P_m={M \choose m} P(m)$ as the total probability of decoding $m$ local models. Both the GC decoding and the complementary contribute to $P_M=P(M)$, as the cases where $\tilde{\boldsymbol{B}}_{i_r}$ contains $M-s$ unperturbed rows and where $\tilde{\boldsymbol{B}}$ is of rank $M$ overlap partially. Instead, $P_m$ solely depends on GC$^+$. For $m\in[M]: P_m=\frac{\hat{P}_m}{1-P_{\emptyset}}$,  where $P_{\emptyset}$ denotes the probability of decoding nothing in GC$^+$. The scaling $\frac{1}{1-P_{\emptyset}}$ is due to the conditioning. Moreover, it holds that $P_{\emptyset}\leq \min\{ P_O^{t_r}, 1- \check{P}_M \}$.  
%The probability of successfully computing the global model by GC decoding mechanism is $1-P_O^{t_r}$, as this occurs if any $\tilde{\boldsymbol{B}}_{i_r}$ can independently handle stragglers.
When $(M-s)t_r\gg M$, $\check{P}_M$ dominates $\hat{P}$, as analyzed in Section \ref{sec: Success Bound}. Since that $\hat{P}=\sum_{m=1}^{M} \hat{P}_m$, we have $\forall m\neq M: \hat{P}_m \leq \check{P}_M$. Consequently, $P_m\leq \frac{\check{P}_M}{1-P_{\emptyset}}$. Moreover, $P_M<1$. 
%it holds that $P_M\leq\frac{1}{1-P_{\emptyset}}\left(\check{P}_M+P_O^{t_r}\right)$. Thus, we have $\forall m\neq M: P_m\leq P_M\leq \frac{1}{1-P_{\emptyset}}\left(\check{P}_M+P_O^{t_r}\right)$.
By substituting these relations into (\ref{eq: bar_k_exp}), we have 
\begin{align}
    \frac{1}{\Bar{K}_r}\leq \frac{\check{P}_M \sum_{m=1}^{M-1}\frac{1}{m}}{1-\min\{ P_O^{t_r}, 1- \check{P}_M \}} +\frac{1}{M},
    \label{eq: upper bound Kbar}
\end{align}
where $\check{P}_M$ is given in (\ref{eq:check_PM}). By (\ref{eq: bar_k_ext}), (\ref{eq: bar_am}) and (\ref{eq: upper bound Kbar}), we complete the proof of Lemma \ref{lemma: GC$^+$}. 
\end{proof}


